# Суффикс этапа «V» / «V» как римская цифра и «-5» как арабская — один проект
_ROMAN_PROJECT_TAIL = {
    "I": 1,
    "II": 2,
    "III": 3,
    "IV": 4,
    "V": 5,
    "VI": 6,
    "VII": 7,
    "VIII": 8,
    "IX": 9,
    "X": 10,
}


def _project_name_fusion_base(s: str) -> str:
    """
    Приводит хвост названия к виду «… 5»: «Есипово V» и «Есипово-5» → «Есипово 5».
    """
    if not s:
        return ""
    t = (
        str(s)
        .replace("\xa0", " ")
        .replace("\u200b", "")
        .replace("\ufeff", "")
        .replace("-", " ")
    )
    t = re.sub(r"\s+", " ", t).strip()
    if not t:
        return ""
    m_num = re.fullmatch(r"(.+?)\s+(\d{1,4})\s*", t, flags=re.I)
    if m_num:
        head = m_num.group(1).strip()
        n = int(m_num.group(2))
        return f"{head} {n}"
    m_rom = re.fullmatch(r"(.+?)\s+([IVX]{1,4})\s*", t, flags=re.I)
    if m_rom:
        head = m_rom.group(1).strip()
        rom = m_rom.group(2).upper()
        n = _ROMAN_PROJECT_TAIL.get(rom)
        if n is not None:
            return f"{head} {n}"
    return t


def _project_filter_norm_key(val) -> str:
    """Ключ для сравнения названий проекта (скрытые дубли в фильтре, совпадение с выбором)."""
    return _pl_norm_key(val)


_PROJECT_CHILD_SUFFIX_RE = re.compile(r"^(\d{1,4}|[IVX]{1,4})$", re.I)


def _project_norm_key_matches_msp_keys(row_key: str, msp_keys: set[str]) -> bool:
    """
    Строка 1С/синтетики с ключом «дмитровский 1» входит в выбор MSP «Дмитровский»
    (ключ «дмитровский»): совпадение или один сегмент-номер/римская цифра после базы.
    """
    if not msp_keys:
        return True
    if not row_key:
        return False
    rk = str(row_key).strip()
    try:
        rk2 = re.sub(r"([а-яёa-z])(\d{1,4})$", r"\1 \2", rk)
        if rk2 != rk:
            rk = re.sub(r"\s+", " ", rk2).strip()
    except re.error:
        pass
    if rk in msp_keys:
        return True
    for k in msp_keys:
        if not k:
            continue
        pref = k + " "
        if not rk.startswith(pref):
            continue
        rest = rk[len(pref) :]
        if rest and _PROJECT_CHILD_SUFFIX_RE.fullmatch(rest):
            return True
    # Обратно: в фильтре ключ «дмитровский 1», в строке — только «дмитровский» (1С без номера).
    for k in msp_keys:
        if not k:
            continue
        pref = rk + " "
        if rk and k.startswith(pref):
            rest = k[len(pref) :]
            if rest and _PROJECT_CHILD_SUFFIX_RE.fullmatch(rest):
                return True
    return False


def _project_canonical_display_map(series: pd.Series) -> dict[str, str]:
    """
    Для каждого «сырого» варианта названия проекта — одна подпись для таблиц/группировок
    (MSP_PROJECT_NAME_MAP / правила девелоперских проектов).
    """
    if series is None or getattr(series, "empty", True):
        return {}
    out: dict[str, str] = {}
    for raw in series.dropna().unique():
        s = str(raw).strip()
        if not s or s.lower() in ("nan", "none"):
            continue
        out[s] = unified_project_display_label(s)
    return out


def _project_column_apply_canonical(df: pd.DataFrame, col: str | None) -> pd.DataFrame:
    """Подменяет значения колонки проекта на канонические подписи в копии датафрейма."""
    if not col or col not in df.columns:
        return df
    return apply_unified_project_column(df, col)


def _unique_project_labels_for_select(
    series: pd.Series, *, apply_exclude_names: bool = True
) -> list[str]:
    """Уникальные подписи проекта: один пункт на логический проект (как в девелоперских)."""
    return project_labels_for_filter(series, apply_exclude_names=apply_exclude_names)


def _session_reset_project_if_excluded(
    state_key: str, *, allowed_labels: list[str] | None = None
) -> None:
    """Сброс устаревших имён проекта, если их нет в текущем списке фильтра."""
    try:
        if state_key not in st.session_state:
            return
        raw = st.session_state[state_key]
        allowed = {str(x).strip() for x in (allowed_labels or []) if str(x).strip()}

        def _is_blocked(name: str) -> bool:
            s = str(name).strip()
            if s not in MSP_PROJECT_FILTER_EXCLUDE_NAMES:
                return False
            if allowed and s in allowed:
                return False
            return True

        if state_key in ("budget_project", "dev_proj_multi"):
            if isinstance(raw, str) and _is_blocked(raw):
                st.session_state[state_key] = []
            elif isinstance(raw, list):
                blocked = [x for x in raw if _is_blocked(x)]
                if blocked:
                    if allowed:
                        kept = [x for x in raw if not _is_blocked(x)]
                        st.session_state[state_key] = kept
                    else:
                        st.session_state[state_key] = []
        elif isinstance(raw, str) and _is_blocked(raw):
            st.session_state[state_key] = "Все"
    except Exception:
        pass


def _filter_df_by_project_labels(
    df: pd.DataFrame,
    selected_labels: list[str],
    *,
    col: str = "project name",
) -> pd.DataFrame:
    """Оставить строки выбранных проектов (сопоставление по norm-key)."""
    return filter_dataframe_by_project_labels(df, selected_labels, col=col)


