def _pd_dynamics_table_box_height(n_rows: int) -> int:
    """Высота iframe/скролл-бокса ПД: по числу строк, кап 640 (без пустоты у коротких таблиц)."""
    return int(min(640, max(120, 48 + max(0, int(n_rows)) * 32 + 16)))


