def _render_html_table(
    df,
    max_rows=500,
    column_tooltips=None,
    *,
    cell_titles: bool = False,
    column_role: dict = None,
    iframe_light: bool = False,
    colored_dev_columns=None,
    scroll: bool = False,
):
    """Render a DataFrame as a styled HTML table (bypasses broken st.dataframe canvas).

    column_tooltips: optional dict column_name -> tooltip for <th title="..."> (full header text on hover).
    cell_titles: если True — у ячеек td задаётся title «Колонка: значение» для подсказки.
    column_role: опционально имя колонки -> 'baseline' | 'fact' | 'dev' | None (класс col-* для раскраски).
    """
    show = df.head(max_rows).copy()
    for col in show.columns:
        show[col] = [str(v) if pd.notna(v) else "" for v in show[col]]
    _role = column_role or {}
    _colored_dev = set(colored_dev_columns or [])
    try:
        from dashboards.light_theme import is_light_preview_active

        _light_preview = is_light_preview_active()
    except Exception:
        _light_preview = False
    _light = iframe_light or _light_preview
    _light_open = '<div class="bi-light-table">' if _light else ""
    _light_close = "</div>" if _light else ""
    _table_css = _gantt_table_css_for_theme() if _light else _TABLE_CSS

    def _th_class(c):
        r = _role.get(c) or _role.get(str(c))
        if r == "baseline":
            return " col-baseline"
        if r == "fact":
            return " col-fact"
        if r == "dev":
            return " col-dev"
        return ""

    if True:
        # scroll=True: вертикальная прокрутка с липкой шапкой (класс pred-detail-wrap
        # подхватывает единый scroll-box в render_report_html_table/utils).
        _wrap_cls = (
            "rendered-table-wrap pred-detail-wrap" if scroll else "rendered-table-wrap"
        )
        _wrap_attr = f' data-bi-rows="{len(show)}"' if scroll else ""
        parts = [
            f'<div class="{_wrap_cls}"{_wrap_attr}>',
            '<table class="rendered-table bi-sortable-table bi-sort-click-only" style="border-collapse:collapse;width:100%">',
            "<thead><tr>",
        ]
        for c in show.columns:
            esc_c = html_module.escape(str(c))
            tip = (column_tooltips or {}).get(c) or (column_tooltips or {}).get(str(c))
            cls = _th_class(c)
            _cc = table_column_css_class(c)
            _cls_full = f"{_cc} {cls.strip()}".strip()
            if tip:
                esc_tip = html_module.escape(str(tip), quote=True)
                parts.append(
                    f'<th class="{_cls_full}" title="{esc_tip}" data-sort-label="{esc_c}">'
                    f'<span class="bi-sort-label">{esc_c} \u21c5</span></th>'
                )
            else:
                parts.append(
                    f'<th class="{_cls_full}" data-sort-label="{esc_c}">'
                    f'<span class="bi-sort-label">{esc_c} \u21c5</span></th>'
                )
        parts.append("</tr></thead><tbody>")
        for i in range(len(show)):
            row = show.iloc[i]
            _row_vals = [str(row[c]).strip() for c in show.columns]
            _is_total = any(v.casefold() == "итого" for v in _row_vals)
            parts.append('<tr class="bd-total-row">' if _is_total else "<tr>")
            for c in show.columns:
                cell = row[c]
                esc = html_module.escape(str(cell)) if str(cell).strip() != "" else ""
                cls = _th_class(c)
                _cc = table_column_css_class(c)
                _cls_full = f"{_cc} {cls.strip()}".strip()
                # Знаковая прокраска колонок отклонений: «+N» (просрочка) — красный,
                # «-N» (с опережением) — зелёный; 0 и «—» — нейтрально.
                if _colored_dev and c in _colored_dev and esc:
                    _txt = str(cell).strip()
                    _color = None
                    if _txt.startswith("+"):
                        _color = "#e74c3c"
                    elif _txt.startswith("-") or _txt.startswith("\u2212"):
                        _color = "#27ae60"
                    if _color:
                        esc = f'<span style="color:{_color};font-weight:600">{esc}</span>'
                if cell_titles and str(cell).strip():
                    ct = html_module.escape(f"{c}: {cell}", quote=True)
                    parts.append(f'<td class="{_cls_full}" title="{ct}">{esc}</td>')
                else:
                    parts.append(f'<td class="{_cls_full}">{esc}</td>')
            parts.append("</tr>")
        parts.append("</tbody></table></div></div>")
        render_report_html_table(
            _light_open + _table_css + "".join(parts) + _light_close,
            export_df=df,
            file_stem="table_export",
            key_prefix=f"html_tbl_{abs(id(df))}",
        )
    if len(df) > max_rows:
        with st.expander("Ограничение отображения таблицы", expanded=False):
            suppress_caption(
                f"Показано {max_rows} из {len(df)} записей. Скачайте CSV или Excel для полных данных."
            )


def _render_budget_table_html(
    df: pd.DataFrame,
    *,
    file_stem: str | None = None,
    key_prefix: str | None = None,
    **kwargs,
) -> None:
    from utils import _export_file_stem

    stem = file_stem or (
        _export_file_stem(kwargs.get("table_caption"))
        if kwargs.get("table_caption")
        else "budget_table"
    )
    kp = key_prefix or f"budget_{stem}_{abs(id(df))}"
    render_report_html_table(
        budget_table_to_html(df, **kwargs),
        export_df=df,
        file_stem=stem,
        key_prefix=kp,
    )


