def _render_styled_table_report(
    styler,
    export_df: pd.DataFrame,
    *,
    file_stem: str = "table_export",
    key_prefix: str | None = None,
    hide_index: bool = True,
    full_width: bool = False,
) -> None:
    html = render_styled_table_to_html(styler, hide_index=hide_index)
    if full_width and export_df is not None and not export_df.empty:
        html = wrap_styled_table_full_width(html, len(export_df))
    render_report_html_table(
        html,
        export_df=export_df,
        file_stem=file_stem,
        key_prefix=key_prefix or f"sty_tbl_{file_stem}_{abs(id(export_df))}",
    )


def _plan_fact_dates_col_css_class(col: str) -> str:
    c = str(col).strip()
    if c in ("Баз. начало", "Базовое начало", "Начало", "Отклонение начала", "Откл. начала"):
        return "col-pf-start"
    if c in ("Баз. окончание", "Базовое окончание", "Окончание", "Отклонение окончания", "Откл. окончания", "Отклонение окончания (дней)"):
        return "col-pf-end"
    if c in ("Баз. длит.", "Длительность", "Отклонение длительности", "Откл. длит."):
        return "col-pf-dur"
    if c in ("ИД",):
        return "col-gantt-id"
    if c in ("Ур",):
        return "col-gantt-lvl"
    if c in ("Название задачи", "Лот"):
        return "col-gantt-task"
    if c == "% завершения":
        return "col-gantt-pct"
    if c in ("Причины отклонений", "Причина отклонения"):
        return "col-gantt-reason"
    if c == "Заметки":
        return "col-gantt-notes"
    cl = c.casefold()
    if ("проект" in cl or "project" in cl) and "задач" not in cl and "task" not in cl:
        return "col-pf-project"
    if any(k in cl for k in ("задач", "назван")):
        return "col-text"
    return ""


_PF_DEV_START_KEYS = ("Откл. начала", "Отклонение начала")
_PF_DEV_END_KEYS = (
    "Откл. окончания",
    "Отклонение окончания",
    "Отклонение окончания (дней)",
)
_PF_DEV_DUR_KEYS = ("Откл. длит.", "Отклонение длительности")
_PF_START_TINT_COLS = frozenset(
    {
        "Базовое начало",
        "Баз. начало",
        "Начало",
        "Откл. начала",
        "Отклонение начала",
    }
)
_PF_END_TINT_COLS = frozenset(
    {
        "Базовое окончание",
        "Баз. окончание",
        "Окончание",
        "Откл. окончания",
        "Отклонение окончания",
        "Отклонение окончания (дней)",
    }
)
_PF_DUR_TINT_COLS = frozenset(
    {
        "Баз. длит.",
        "Базовая длительность",
        "Длительность",
        "Откл. длит.",
        "Отклонение длительности",
    }
)
_PF_CIPHER_TINT_COLS = frozenset({"Раздел", "Шифр"})


def _plan_fact_pick_dev_value(row: pd.Series, keys: tuple[str, ...]):
    for k in keys:
        if k not in row.index:
            continue
        v = row[k]
        if v is None or (isinstance(v, float) and pd.isna(v)):
            continue
        return v
    return None


def _plan_fact_deviation_bg_style(nval) -> str:
    """Фон ячейки (даты/длительность/отклонение): <0 красный, 0 нейтральный, >0 зелёный."""
    if nval is None or (isinstance(nval, float) and pd.isna(nval)):
        return ""
    try:
        n = float(nval)
    except (TypeError, ValueError):
        return ""
    try:
        from dashboards.light_theme import is_light_preview_active

        _light = is_light_preview_active()
    except Exception:
        _light = False
    if n < 0:
        t = min(max(-n, 0.0), 365.0) / 365.0
        if _light:
            alpha = 0.16 + 0.24 * t
            return f"background-color:rgba(248,113,113,{alpha:.3f}) !important;"
        alpha = 0.24 + 0.36 * t
        return f"background-color:rgba(255,84,84,{alpha:.3f}) !important;"
    if n == 0:
        if _light:
            return "background-color:rgba(34,197,94,0.14) !important;"
        return "background-color:rgba(70,214,138,0.22) !important;"
    t = min(max(n, 0.0), 365.0) / 365.0
    if _light:
        alpha = 0.12 + 0.2 * t
        return f"background-color:rgba(34,197,94,{alpha:.3f}) !important;"
    alpha = 0.18 + 0.28 * t
    return f"background-color:rgba(70,214,138,{alpha:.3f}) !important;"


def _plan_fact_deviation_td_style(nval) -> str:
    """Совместимость: только фон (цвет шрифта — pf-dev-*)."""
    return _plan_fact_deviation_bg_style(nval)


def _plan_fact_dev_nval_for_col(col: str, dev_start, dev_end, dev_dur):
    c = str(col).strip()
    if c in _PF_CIPHER_TINT_COLS:
        return dev_end
    if c in _PF_START_TINT_COLS:
        return dev_start
    if c in _PF_END_TINT_COLS:
        return dev_end
    if c in _PF_DUR_TINT_COLS:
        return dev_dur
    return None


def _plan_fact_td_align_style(col: str, *, in_dev: bool, in_num: bool, in_date: bool) -> str:
    if in_dev or in_num or in_date:
        return "text-align:center;"
    return "text-align:center;"


def _plan_fact_sort_attr(nval) -> str:
    if nval is None or (isinstance(nval, float) and pd.isna(nval)):
        return ""
    if isinstance(nval, pd.Timestamp):
        if pd.isna(nval):
            return ""
        return f' data-sort-val="{float(nval.timestamp())}"'
    if isinstance(nval, (int, float, np.integer, np.floating)):
        fv = float(nval)
        if pd.isna(fv):
            return ""
        return f' data-sort-val="{fv}"'
    try:
        fv = float(nval)
        if pd.isna(fv):
            return ""
        return f' data-sort-val="{fv}"'
    except (TypeError, ValueError):
        pass
    try:
        ts = pd.to_datetime(nval, errors="coerce", dayfirst=True)
        if ts is not None and pd.notna(ts):
            return f' data-sort-val="{float(ts.timestamp())}"'
    except Exception:
        pass
    s = str(nval).strip()
    if s and s.lower() not in ("nan", "none", "nat"):
        return f' data-sort-val="{html_module.escape(s, quote=True)}"'
    return ""


def _plan_fact_deviation_span(nval, text: str) -> str:
    if nval is None or (isinstance(nval, float) and pd.isna(nval)):
        return ""
    try:
        n = int(round(float(nval)))
    except (TypeError, ValueError):
        return html_module.escape(str(text))
    cls = "pf-dev-red" if n < 0 else "pf-dev-green"
    if n > 0:
        disp = f"+{n}"
    elif n < 0:
        disp = str(n)
    else:
        disp = "0"
    return f'<span class="{cls}">{html_module.escape(disp)}</span>'


def _render_plan_fact_dates_main_table(
    display_df: pd.DataFrame,
    numeric_df: pd.DataFrame,
    *,
    wrap_class: str = "",
    file_stem: str = "plan_fact_dates",
    key_prefix: str | None = None,
    export_df: pd.DataFrame | None = None,
) -> None:
    if display_df is None or getattr(display_df, "empty", True):
        st.info("Нет данных для таблицы.")
        return
    _dev_cols = {
        "Откл. начала",
        "Откл. окончания",
        "Откл. длит.",
        "Отклонение начала",
        "Отклонение окончания",
        "Отклонение длительности",
        "Отклонение окончания (дней)",
    }
    _num_cols = {"Баз. длит.", "Длительность", "Базовая длительность"}
    _date_cols = {"Базовое начало", "Базовое окончание", "Начало", "Окончание"}
    _reason_cols = {"Причины отклонений", "Заметки"}
    _wrap_extra = (wrap_class or "").strip()
    _is_pd_dyn = file_stem == "pd_dynamics_table" or "pd-dynamics-scroll-wrap" in _wrap_extra
    _wrap_cls = "rendered-table-wrap pf-dates-table-wrap"
    _scroll_attr = ""
    _pd_wrap_id = ""
    _pd_box_h = 0
    if _is_pd_dyn:
        _pd_box_h = _pd_dynamics_table_box_height(len(display_df))
        _pd_wrap_id = f"pd_dyn_{abs(id(display_df))}"
        _wrap_cls = (
            "budget-deviation-table-wrap pd-dynamics-table-wrap "
            "rendered-table-wrap pf-dates-table-wrap"
        )
        _scroll_attr = f' data-scroll-box-h="{_pd_box_h}"'
    elif _wrap_extra:
        _wrap_cls = f"{_wrap_cls} {_wrap_extra}"
    elif file_stem == "plan_fact_dates":
        _wrap_cls = f"{_wrap_cls} pf-dates-scroll-wrap"
    if not _is_pd_dyn and "pf-dates-scroll-wrap" in _wrap_cls:
        _pf_box_h = int(min(640, max(180, 44 + len(display_df) * 28 + 12)))
        _scroll_attr = f' data-scroll-box-h="{_pf_box_h}"'
    parts: list[str] = []
    if _is_pd_dyn:
        parts.extend(
            [
                "<style>",
                f"#{_pd_wrap_id} .budget-table-scroll {{ height: {_pd_box_h}px !important; "
                f"max-height: {_pd_box_h}px !important; min-height: 0; "
                "overflow: auto; -webkit-overflow-scrolling: touch; scrollbar-gutter: stable; "
                "box-sizing: border-box; }",
                f"#{_pd_wrap_id}.budget-deviation-table-wrap {{ display: block; overflow: hidden; "
                "width: 100%; margin: 0.35em 0 0 0; }}",
                f"#{_pd_wrap_id} thead th {{ position: sticky; top: 0; z-index: 5; }}",
                f"#{_pd_wrap_id} .budget-table-scroll table {{ width: 100%; min-width: 100%; "
                "table-layout: fixed; }}",
                "</style>",
                f'<div id="{_pd_wrap_id}" class="{_wrap_cls}" data-bi-rows="{len(display_df)}">',
                f'<div class="budget-table-scroll pd-dynamics-scroll-wrap"{_scroll_attr}>',
            ]
        )
    else:
        parts.append(
            f'<div class="{_wrap_cls}" data-bi-rows="{len(display_df)}"{_scroll_attr}>'
        )
    parts.extend(
        [
        '<table class="rendered-table bi-sortable-table pf-dates-table bi-sort-click-only">',
        "<thead><tr>",
        ]
    )
    for c in display_df.columns:
        cls = _plan_fact_dates_col_css_class(c)
        c_esc = html_module.escape(str(c))
        parts.append(
            f'<th class="{cls}" data-sort-label="{c_esc}">'
            f'<span class="bi-sort-label">{c_esc} \u21c5</span></th>'
        )
    parts.append("</tr></thead><tbody>")
    for i in range(len(display_df)):
        num_row = numeric_df.iloc[i]
        dev_start = _plan_fact_pick_dev_value(num_row, _PF_DEV_START_KEYS)
        dev_end = _plan_fact_pick_dev_value(num_row, _PF_DEV_END_KEYS)
        dev_dur = _plan_fact_pick_dev_value(num_row, _PF_DEV_DUR_KEYS)
        parts.append("<tr>")
        for c in display_df.columns:
            cls = _plan_fact_dates_col_css_class(c)
            txt = display_df.iloc[i][c]
            sort_attr = ""
            style_parts: list[str] = []
            if c in _dev_cols and c in numeric_df.columns:
                nv = numeric_df.iloc[i][c]
                sort_attr = _plan_fact_sort_attr(nv)
                cell = (
                    _plan_fact_deviation_span(nv, "")
                    if pd.notna(nv) and str(nv).strip().lower() not in ("", "nan", "none")
                    else ""
                )
            elif c in _reason_cols:
                s = str(txt).strip() if pd.notna(txt) else ""
                cell = (
                    html_module.escape(s)
                    if s and s.lower() not in ("", "nan", "none")
                    else ""
                )
            elif c in _num_cols and c in numeric_df.columns:
                sort_attr = _plan_fact_sort_attr(numeric_df.iloc[i][c])
                cell = (
                    html_module.escape(str(txt))
                    if pd.notna(txt) and str(txt).strip() not in ("", "nan", "None")
                    else ""
                )
            elif c in _date_cols and c in numeric_df.columns:
                sort_attr = _plan_fact_sort_attr(numeric_df.iloc[i][c])
                cell = (
                    html_module.escape(str(txt))
                    if pd.notna(txt) and str(txt).strip() not in ("", "nan", "None")
                    else ""
                )
            else:
                cell = (
                    html_module.escape(str(txt))
                    if pd.notna(txt) and str(txt).strip() not in ("", "nan", "None")
                    else ""
                )
            if cell and c not in _reason_cols:
                tint_n = _plan_fact_dev_nval_for_col(c, dev_start, dev_end, dev_dur)
                if tint_n is not None:
                    bg = _plan_fact_deviation_bg_style(tint_n)
                    if bg:
                        style_parts.append(bg)
            style_parts.append(
                _plan_fact_td_align_style(
                    c,
                    in_dev=c in _dev_cols,
                    in_num=c in _num_cols,
                    in_date=c in _date_cols,
                )
            )
            align = f' style="{"".join(style_parts)}"' if style_parts else ""
            parts.append(f'<td class="{cls}"{sort_attr}{align}>{cell}</td>')
        parts.append("</tr>")
    parts.append("</tbody></table>")
    if _is_pd_dyn:
        parts.append("</div></div>")
    else:
        parts.append("</div>")
    _kp = key_prefix or f"pf_dates_{abs(id(display_df))}"
    render_report_html_table(
        _gantt_table_css_for_theme() + mark_html_table_sortable("".join(parts)),
        export_df=export_df if export_df is not None else display_df,
        file_stem=file_stem,
        key_prefix=_kp,
    )


def _parse_gantt_dev_days_display(v):
    """Число дней из строки вида «+5 дн.» / «0 дн.» для подсветки таблицы графика проекта."""
    if v is None:
        return None
    try:
        if isinstance(v, float) and pd.isna(v):
            return None
    except Exception:
        pass
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none"):
        return None
    s = re.sub(r"дн\.?", "", s, flags=re.I).strip()
    m = re.search(r"([+-]?)\s*(\d+)", s)
    if not m:
        return None
    val = int(m.group(2))
    sg = m.group(1) or ""
    if sg == "-":
        return -val
    if sg == "+":
        return val
    return val


def _gantt_deviation_cell_style(v) -> str:
    n = _parse_gantt_dev_days_display(v)
    base = f"background-color: {TABLE_BG_COLOR}; color: {TABLE_TEXT_COLOR}"
    if n is None:
        return base
    if n == 0:
        return "background-color: #14532d; color: #ecfdf5"
    if n > 0:
        return "background-color: #c0392b; color: #ffffff"
    return "background-color: #27ae60; color: #ffffff"


def _gantt_resolve_level_display_target(ln: pd.Series, level_sel: str) -> int | None:
    """Целевой уровень MSP для «Верхний/Детальный» с fallback по фактическим уровням в срезе."""
    lvl_map = {"Верхний уровень": 4, "Детальный уровень": 5}
    target = lvl_map.get(level_sel)
    if target is None:
        return None
    nums = pd.to_numeric(ln, errors="coerce").dropna()
    if nums.empty:
        return target
    levels = sorted({int(round(float(x))) for x in nums})
    if target in levels:
        return target
    if level_sel == "Верхний уровень":
        mid = [lv for lv in levels if 3 <= lv <= 4]
        if mid:
            return max(mid)
        deeper = [lv for lv in levels if lv > 2]
        return max(deeper) if deeper else target
    if level_sel == "Детальный уровень":
        for lv in (5, 4, 3):
            if lv in levels:
                return lv
    return target


def _gantt_apply_level_display_filter(
    df: pd.DataFrame,
    *,
    level_col: str | None,
    level_sel: str,
    wbs_col: str | None,
    sel_block: str,
) -> pd.DataFrame:
    """Фильтр «Уровень отображения задач» (без режима «Показать причины отклонений»)."""
    if df is None or getattr(df, "empty", True):
        return df
    if sel_block != "Все" and any(
        tok in str(sel_block).lower()
        for tok in ("ковенант", "ковен", "covenant", "coven")
    ):
        return df
    if not level_col or level_col not in df.columns or level_sel == "Все уровни":
        return df
    ln = pd.to_numeric(df[level_col], errors="coerce")
    target = _gantt_resolve_level_display_target(ln, level_sel)
    if target is None:
        return df
    if ln.notna().any():
        return df.loc[ln == float(target)].copy()
    wbs_dep = df[level_col].map(_msp_wbs_tuple).map(lambda t: int(len(t)) if t else np.nan)
    if wbs_dep.notna().any():
        return df.loc[wbs_dep == target].copy()
    return df


def _gantt_task_name_col_width_ch(display_df: pd.DataFrame, col_name: str = "Название задачи") -> int | None:
    """Ширина колонки «Название задачи» = max(заголовок, самое длинное имя) в ch."""
    if display_df is None or col_name not in display_df.columns:
        return None

    def _txt(v) -> str:
        if pd.isna(v):
            return ""
        s = str(v).strip()
        return "" if s in ("", "nan", "None") else s

    lens = [len(col_name) + 2]
    for s in display_df[col_name].map(_txt):
        if s:
            lens.append(len(s))
    if not lens:
        return None
    return max(max(lens) + 1, 9)


def _gantt_task_col_width_css(ch: int) -> str:
    """Фиксированная ширина «Название задачи» (ch) — одинакова с/без «Причины отклонений»."""
    tbl = (
        f'.bi-sortable-html-root .gantt-schedule-table-wrap '
        f'table[data-gantt-task-ch="{ch}"]'
    )
    cell = f"{tbl} th.col-gantt-task,{tbl} td.col-gantt-task"
    col = f"{tbl} col.col-gantt-task"
    return (
        f"{tbl}{{width:max-content!important;min-width:100%!important;"
        f"table-layout:auto!important;}}"
        f"{col}{{width:{ch}ch!important;min-width:{ch}ch!important;max-width:{ch}ch!important;}}"
        f"{cell}{{width:{ch}ch!important;min-width:{ch}ch!important;max-width:{ch}ch!important;"
        f"white-space:nowrap!important;box-sizing:border-box!important;overflow:visible!important;"
        f"text-overflow:clip!important;}}"
        f"{tbl} th.col-gantt-task > div,{tbl} th.col-gantt-task .bi-sort-label{{"
        f"width:auto!important;flex:0 0 auto!important;white-space:nowrap!important;}}"
    )


def _render_gantt_schedule_html_table(
    display_df: pd.DataFrame,
    numeric_df: pd.DataFrame | None = None,
    *,
    max_rows: int = 80,
    group_by_project: bool = False,
    project_col_name: str = "Проект",
    task_col_width_ch: int | None = None,
) -> None:
    """Таблица под «График проекта»: сортировка, прокраска отклонений, без обрезки текста."""
    if display_df is None or getattr(display_df, "empty", True):
        st.info("Нет данных для таблицы.")
        return
    num = numeric_df if numeric_df is not None else display_df
    show_disp = display_df.head(max_rows)
    show_num = num.reindex(show_disp.index)

    _dev_cols = {
        "Отклонение начала",
        "Отклонение окончания",
        "Отклонение Начала",
        "Отклонение Окончания",
    }
    _gantt_dev_end_keys = ("Отклонение окончания", "Отклонение Окончания")
    _gantt_dev_start_keys = ("Отклонение начала", "Отклонение Начала")
    _gantt_dev_dur_keys = ("Отклонение длительности",)
    _date_cols = {
        "Начало",
        "Базовое начало",
        "Окончание",
        "Базовое окончание",
    }
    _num_cols = {"ИД", "Ур", "% завершения", "Базовая длительность", "Длительность"}
    _dev_cols_all = _dev_cols | {"Отклонение длительности"}
    _reason_cols = {"Причины отклонений", "Причина отклонения", "Заметки"}
    _task_col_name = "Лот" if "Лот" in show_disp.columns else "Название задачи"
    _task_col_w_ch = (
        int(task_col_width_ch)
        if task_col_width_ch
        else (_gantt_task_name_col_width_ch(show_disp, _task_col_name) or 1)
    )
    _ncols = len(show_disp.columns)
    _use_groups = bool(
        group_by_project
        and project_col_name
        and project_col_name in show_disp.columns
    )

    _gantt_box_h = int(min(624, max(180, 44 + len(show_disp) * 28 + 16)))

    parts = [
        f'<div class="gantt-schedule-scroll-wrap" data-bi-rows="{len(show_disp)}" '
        f'data-scroll-box-h="{_gantt_box_h}">',
        '<div class="rendered-table-wrap gantt-schedule-table-wrap">',
    ]
    parts.append(f"<style>{_gantt_task_col_width_css(_task_col_w_ch)}</style>")
    _task_tbl_attr = f' data-gantt-task-ch="{_task_col_w_ch}"'
    parts.append(
        f'<table class="rendered-table bi-sortable-table gantt-schedule-table bi-sort-click-only"'
        f"{_task_tbl_attr}>"
    )
    parts.append("<colgroup>")
    for c in show_disp.columns:
        if c == _task_col_name:
            parts.append(
                f'<col class="col-gantt-task" style="width:{_task_col_w_ch}ch;'
                f'min-width:{_task_col_w_ch}ch;max-width:{_task_col_w_ch}ch">'
            )
        else:
            parts.append("<col>")
    parts.append("</colgroup>")
    parts.extend([
        "<thead><tr>",
    ])
    for c in show_disp.columns:
        cls = _plan_fact_dates_col_css_class(c)
        c_esc = html_module.escape(str(c))
        parts.append(
            f'<th class="{cls}" data-sort-label="{c_esc}">'
            f'<span class="bi-sort-label">{c_esc} \u21c5</span></th>'
        )
    parts.append("</tr></thead><tbody>")

    disp_cols = list(show_disp.columns)
    _disp_arrays = {c: show_disp[c].to_numpy() for c in disp_cols}
    _num_arrays = {
        c: show_num[c].to_numpy() if c in show_num.columns else None for c in disp_cols
    }

    def _dev_at(idx: int, keys: tuple[str, ...]):
        for k in keys:
            arr = _num_arrays.get(k)
            if arr is None:
                continue
            v = arr[idx]
            if v is None or (isinstance(v, float) and pd.isna(v)):
                continue
            return v
        return None

    def _cell_text(val) -> str:
        if pd.isna(val):
            return ""
        s = str(val).strip()
        return "" if s in ("", "nan", "None") else s

    def _append_group_row(project_label: str) -> None:
        p_esc = html_module.escape(str(project_label).strip())
        parts.append(
            f'<tr class="bd-group-row">'
            f'<td colspan="{_ncols}" class="col-pf-project">{p_esc}</td>'
            f"</tr>"
        )

    def _append_data_row(i: int) -> None:
        dev_start = _dev_at(i, _gantt_dev_start_keys)
        dev_end = _dev_at(i, _gantt_dev_end_keys)
        dev_dur = _dev_at(i, _gantt_dev_dur_keys)
        parts.append("<tr>")
        for c in disp_cols:
            cls = _plan_fact_dates_col_css_class(c)
            txt = _disp_arrays[c][i]
            sort_attr = ""
            style_parts: list[str] = []
            if c in _dev_cols_all:
                nv = _num_arrays[c][i] if _num_arrays.get(c) is not None else None
                sort_attr = _plan_fact_sort_attr(nv)
                disp = _cell_text(txt)
                if not disp and pd.notna(nv):
                    try:
                        disp = str(int(round(float(nv))))
                    except (TypeError, ValueError):
                        pass
                cell = _plan_fact_deviation_span(nv, disp) if (disp or pd.notna(nv)) else ""
            elif c in _reason_cols:
                s = _cell_text(txt)
                cell = html_module.escape(s) if s else ""
            elif c in _date_cols:
                nv = _num_arrays[c][i] if _num_arrays.get(c) is not None else None
                sort_attr = _plan_fact_sort_attr(nv)
                cell = html_module.escape(_cell_text(txt)) if _cell_text(txt) else ""
            elif c in _num_cols:
                nv = _num_arrays[c][i] if _num_arrays.get(c) is not None else None
                sort_attr = _plan_fact_sort_attr(nv)
                cell = html_module.escape(_cell_text(txt)) if _cell_text(txt) else ""
            else:
                cell = html_module.escape(_cell_text(txt)) if _cell_text(txt) else ""
            if cell and c not in _reason_cols:
                tint_n = _plan_fact_dev_nval_for_col(c, dev_start, dev_end, dev_dur)
                if tint_n is not None:
                    bg = _plan_fact_deviation_bg_style(tint_n)
                    if bg:
                        style_parts.append(bg)
            style_parts.append(
                _plan_fact_td_align_style(
                    c,
                    in_dev=c in _dev_cols_all,
                    in_num=c in _num_cols,
                    in_date=c in _date_cols,
                )
            )
            align = f' style="{"".join(style_parts)}"' if style_parts else ""
            parts.append(f'<td class="{cls}"{sort_attr}{align}>{cell}</td>')
        parts.append("</tr>")

    if _use_groups:
        _proj_arr = _disp_arrays.get(project_col_name)
        _cur_proj = None
        for i in range(len(show_disp)):
            if _proj_arr is not None:
                _p = str(_proj_arr[i]).strip()
                if _p and _p.lower() not in ("", "nan", "none") and _p != _cur_proj:
                    _cur_proj = _p
                    _append_group_row(_p)
            _append_data_row(i)
    else:
        for i in range(len(show_disp)):
            _append_data_row(i)

    parts.append("</tbody></table></div></div>")
    render_report_html_table(
        _gantt_table_css_for_theme() + mark_html_table_sortable("".join(parts)),
        export_df=display_df,
        file_stem="gantt_schedule",
        key_prefix=f"gantt_tbl_{abs(id(display_df))}",
    )
    if len(display_df) > max_rows:
        suppress_caption(
            f"Показано {max_rows} из {len(display_df)} записей. "
            "Скачайте CSV для полных данных."
        )



