# Максимальное число строк, передаваемых в Plotly для scatter/line-графиков.
# Для агрегированных (bar, pie) ограничение не нужно — там строк обычно немного.
_MAX_CHART_ROWS = 5_000

_dev_outline_level_numeric = outline_level_numeric


def _dev_tasks_find_column(df, possible_names):
    """Поиск колонки по списку имён (без учёта регистра, с частичным совпадением)."""
    if df is None or not hasattr(df, "columns"):
        return None
    for col in df.columns:
        col_normalized = str(col).replace("\n", " ").replace("\r", " ").strip()
        col_lower = col_normalized.lower()
        for name in possible_names:
            name_lower = name.lower().strip()
            if name_lower == col_lower:
                return col
            if name_lower in col_lower or col_lower in name_lower:
                return col
            name_words = [w for w in name_lower.split() if len(w) > 2]
            if name_words and all(word in col_lower for word in name_words):
                return col
    return None


def _dev_tasks_resolve_level_column(d: pd.DataFrame):
    """Колонка числового уровня иерархии MSP (Outline / level structure / Уровень)."""
    if d is None or getattr(d, "empty", True):
        return None
    candidates: list = []
    seen = set()

    def _add(col) -> None:
        if col is None or col not in d.columns:
            return
        key = str(col).strip().lower()
        if key in seen:
            return
        seen.add(key)
        candidates.append(col)

    for c in d.columns:
        if str(c).strip().lower() == "level structure":
            _add(c)
    for name in (
        "level",
        "outline level",
        "outline_level",
        "wbs level",
        "wbs_level",
        "исходный уровень",
        "исходный_уровень",
    ):
        cols_lower = {str(x).strip().lower(): x for x in d.columns}
        if name in cols_lower:
            _add(cols_lower[name])
    for c in d.columns:
        sl = str(c).strip().lower()
        if "outline" in sl and "level" in sl.replace(" ", "") and "number" not in sl:
            _add(c)
        if "wbs" in sl and "level" in sl.replace(" ", "") and "number" not in sl:
            _add(c)
        if "уровень" in sl and "приоритет" not in sl and "риск" not in sl:
            _add(c)

    for c in candidates:
        coerced = _dev_outline_level_numeric(d[c])
        if coerced.notna().any():
            return c
    return None


def _deviations_msp_tier_levels(ln: pd.Series) -> tuple[int, int]:
    """
    Уровни MSP для фильтров «функциональный блок» и «строение».
    Если в данных есть классические 2 и 3 — используем их; иначе — вторая и третья
    уникальные величины уровня (экспорты, где нумерация начинается не с 2).
    """
    s = _dev_outline_level_numeric(ln).dropna()
    us: list[int] = []
    for x in s:
        try:
            v = int(round(float(x)))
        except (TypeError, ValueError):
            continue
        if v not in us:
            us.append(v)
    us.sort()
    if not us:
        return 2, 3
    if 2 in us and 3 in us:
        return 2, 3
    if len(us) >= 3:
        return us[1], us[2]
    if len(us) == 2:
        return us[0], us[1]
    return us[0], us[0]


def _dev_tasks_build_ancestor_keys(
    df: pd.DataFrame,
    level_col,
    task_col,
    *,
    block_outline_level=None,
    building_outline_level=None,
) -> pd.DataFrame:
    """
    По порядку строк MSP и колонке уровня строит ключи для фильтров:
    задача ур. block_outline_level (функциональный блок) и ур. building_outline_level (строение)
    как предки текущей строки.
    """
    work = df.copy().reset_index(drop=True)
    if (
        not level_col
        or level_col not in work.columns
        or not task_col
        or task_col not in work.columns
    ):
        work["_dt_lvl2_key"] = ""
        work["_dt_lvl3_key"] = ""
        work["_dt_lvl_num"] = np.nan
        return work
    lvl = _dev_outline_level_numeric(work[level_col])
    _tier_blk, _tier_bld = _deviations_msp_tier_levels(lvl)
    if block_outline_level is None:
        block_outline_level = _tier_blk
    if building_outline_level is None:
        building_outline_level = _tier_bld
    names = work[task_col].map(lambda x: str(x).strip() if pd.notna(x) else "")
    # Читаем значения из numpy-массивов, а не через .iloc в цикле: на десятках/сотнях
    # тысяч строк per-row .iloc даёт основную задержку дашборда «Причины отклонений».
    _lvl_vals = lvl.to_numpy()
    _name_vals = names.to_numpy()
    _n_lvl = len(_lvl_vals)
    _n_nm = len(_name_vals)
    stack = []
    r2, r3, lvn = [], [], []
    for i in range(len(work)):
        L_raw = _lvl_vals[i] if i < _n_lvl else np.nan
        if pd.isna(L_raw):
            L = None
        else:
            try:
                L = int(round(float(L_raw)))
            except (TypeError, ValueError):
                L = None
        nm = _name_vals[i] if i < _n_nm else ""
        lvn.append(float(L) if L is not None else np.nan)
        if L is None:
            r2.append("")
            r3.append("")
            continue
        while stack and stack[-1][0] >= L:
            stack.pop()
        a2 = ""
        a3 = ""
        for le, nn in stack:
            if le == block_outline_level:
                a2 = nn
            if le == building_outline_level:
                a3 = nn
        k2 = nm if L == block_outline_level else a2
        k3 = nm if L == building_outline_level else a3
        r2.append(k2)
        r3.append(k3)
        stack.append((L, nm))
    work["_dt_lvl2_key"] = r2
    work["_dt_lvl3_key"] = r3
    work["_dt_lvl_num"] = lvn
    return work


def _msp_wbs_tuple(val):
    try:
        if val is None or pd.isna(val):
            return ()
    except Exception:
        if val is None:
            return ()
    s = str(val).strip()
    if not s or s.lower() in ("nan", "none"):
        return ()
    parts = [p for p in re.split(r"[.\s/|>\\-]+", s) if p != ""]
    out = []
    for p in parts:
        try:
            out.append(int(float(p)))
        except (TypeError, ValueError):
            continue
    return tuple(out) if out else ()


def _msp_resolve_wbs_column(d: pd.DataFrame):
    """Колонка WBS / Outline Number для иерархии MSP."""
    if d is None or getattr(d, "empty", True):
        return None
    cols_lower = {str(c).strip().lower(): c for c in d.columns}
    for w in (
        "outline number",
        "outline_number",
        "wbs",
        "wbs code",
        "код wbs",
        "иерархический номер",
        "номер структуры",
    ):
        if w in cols_lower:
            return cols_lower[w]
    for c in d.columns:
        sl = str(c).strip().lower()
        if "outline" in sl and "number" in sl:
            return c
        if "wbs" in sl:
            return c
    return None


def _msp_filter_level5_with_ancestors(
    df: pd.DataFrame,
    level_col,
    wbs_col=None,
) -> pd.DataFrame:
    """Задачи уровня 5 и все их родители (по WBS или по уровню ≤ 5)."""
    if df is None or getattr(df, "empty", True):
        return df
    if not level_col or level_col not in df.columns:
        return df
    ln_all = pd.to_numeric(df[level_col], errors="coerce")
    leaf_mask = ln_all == 5.0
    if not leaf_mask.any():
        return df
    if wbs_col and wbs_col in df.columns:
        wbs_all = df[wbs_col].map(_msp_wbs_tuple)
        ancestor_set: set = set()
        for t in wbs_all[leaf_mask].tolist():
            if not t:
                continue
            for k in range(1, len(t) + 1):
                ancestor_set.add(t[:k])
        if ancestor_set:
            return df[wbs_all.isin(ancestor_set)].copy()
    return df[leaf_mask | (ln_all.notna() & (ln_all <= 5))].copy()


def _gdrs_header_is_dd_mm_yyyy(name) -> bool:
    """
    Колонка — календарный день: строка ДД.ММ.ГГГГ либо datetime/Timestamp в имени колонки после read_excel.
    """
    if name is None:
        return False
    try:
        if pd.isna(name):
            return False
    except Exception:
        pass
    if isinstance(name, (pd.Timestamp, datetime, date)):
        return True
    t = str(name).strip()
    # 01.02.2026 / 1.2.26
    if re.match(r"^\d{1,2}\.\d{1,2}\.\d{2,4}$", t):
        return True
    # "грязные" заголовки вида 02..01.2026 / 02...01.26
    if re.match(r"^\d{1,2}\.{2,3}\d{1,2}\.\d{2,4}$", t):
        return True
    return False


def _format_gdrs_period_range_dd_mm_yyyy(d_from, d_to, sep: str = " - ") -> str:
    """Диапазон в виде ДД.ММ.ГГГГ - ДД.ММ.ГГГГ (как у виджета «Период» с format=DD.MM.YYYY)."""
    try:
        ts_a = pd.Timestamp(d_from)
        ts_b = pd.Timestamp(d_to)
        if pd.isna(ts_a) or pd.isna(ts_b):
            return ""
        da = ts_a.normalize().date()
        db = ts_b.normalize().date()
        return (
            f"{da.day:02d}.{da.month:02d}.{da.year:04d}"
            f"{sep}"
            f"{db.day:02d}.{db.month:02d}.{db.year:04d}"
        )
    except Exception:
        return ""


def _format_gdrs_month_year_title_ru(d_from, d_to, pdf: pd.DataFrame | None, period_col: str | None) -> str:
    """Человекочитаемый период для шапки ГДРС: «Март 2026» или «Январь — Март 2026»."""
    _months = (
        "",
        "Январь",
        "Февраль",
        "Март",
        "Апрель",
        "Май",
        "Июнь",
        "Июль",
        "Август",
        "Сентябрь",
        "Октябрь",
        "Ноябрь",
        "Декабрь",
    )

    def _one_month(y: int, m: int) -> str:
        if 1 <= int(m) <= 12:
            return f"{_months[int(m)]} {int(y)}"
        return ""

    try:
        if d_from is not None and d_to is not None:
            ta = pd.Timestamp(d_from).normalize()
            tb = pd.Timestamp(d_to).normalize()
            if pd.notna(ta) and pd.notna(tb):
                if ta.year == tb.year and ta.month == tb.month:
                    return _one_month(ta.year, ta.month)
                if ta.year == tb.year:
                    return f"{_months[int(ta.month)]} — {_months[int(tb.month)]} {int(ta.year)}"
                return (
                    f"{_months[int(ta.month)]} {int(ta.year)} — {_months[int(tb.month)]} {int(tb.year)}"
                )
    except Exception:
        pass
    try:
        if pdf is not None and period_col and period_col in pdf.columns:
            _pvals = pd.to_datetime(pdf[period_col], errors="coerce", dayfirst=True).dropna()
            if not _pvals.empty:
                ta = pd.Timestamp(_pvals.min()).normalize()
                tb = pd.Timestamp(_pvals.max()).normalize()
                if ta.year == tb.year and ta.month == tb.month:
                    return _one_month(ta.year, ta.month)
                if ta.year == tb.year:
                    return f"{_months[int(ta.month)]} — {_months[int(tb.month)]} {int(ta.year)}"
                return (
                    f"{_months[int(ta.month)]} {int(ta.year)} — {_months[int(tb.month)]} {int(tb.year)}"
                )
    except Exception:
        pass
    return ""


def _gdrs_delta_pct_cell_bg_style(raw, *, theme: str = "dark") -> str:
    """Фон «Отклонение %» (факт − план в %): >0 зелёный, <0 красный."""
    from dashboards.gdrs_resursi import gdrs_delta_pct_cell_bg_style

    return gdrs_delta_pct_cell_bg_style(raw, theme=theme)


def _gdrs_period_series_to_year(series: pd.Series) -> pd.Series:
    """Календарный год для значений колонки периода (Period / Timestamp / строка)."""

    def _one(v):
        if v is None or (isinstance(v, float) and pd.isna(v)):
            return np.nan
        try:
            if isinstance(v, pd.Period):
                return int(v.year)
            return int(pd.Timestamp(v).year)
        except Exception:
            return np.nan

    return series.map(_one)


def _gdrs_detect_csv_resource_kind_column(pdf: pd.DataFrame) -> Optional[str]:
    """Колонка признака «Рабочие / Техника» в CSV (PDF: столбец H)."""
    if pdf is None or getattr(pdf, "empty", True):
        return None
    exclude_lc = {
        "проект",
        "контрагент",
        "период",
        "план",
        "факт",
        "скуд",
        "data_source",
        "тип ресурсов",
        "вид работы",
        "вид работ",
        "__source_file",
        "snapshot_date",
    }
    best_c = None
    best_score = 0.0
    for c in pdf.columns:
        cl = str(c).strip().lower()
        if cl in exclude_lc or _gdrs_header_is_dd_mm_yyyy(c):
            continue
        raw = pdf[c].astype(str).str.strip()
        ser = raw.str.casefold().replace({"nan": "", "none": ""})
        ser = ser[ser.ne("")]
        if ser.empty:
            continue
        uniq = ser.unique().tolist()
        if len(uniq) > 14:
            continue
        u = set(uniq)
        score = 0.0
        if any("рабоч" in v for v in u):
            score += 3.0
        if any("тех" in v for v in u):
            score += 3.0
        if any(v in {"ресурсы", "ресурс", "люди"} for v in u):
            score += 1.0
        if 2 <= len(u) <= 10:
            score += 1.0
        if score > best_score:
            best_score = score
            best_c = str(c)
    return best_c if best_score >= 4.0 else None


def _gdrs_fact_bar_color(plan_v: float, fact_v: float) -> str:
    """R23-05 стр.12: градиентная окраска факта относительно плана.

    - План выполнен (fact >= plan) → салатовый #2ECC71.
    - Факт меньше плана → красный градиент: чем больше просадка, тем темнее/краснее.
    - Факт ≤ 0 → ярко-красный.
    - План не задан (plan <= 0) → оранжевый (нечего сравнивать).
    """
    _light_green = "#2ECC71"
    _orange = "#F39C12"
    try:
        plan_v = float(plan_v)
        fact_v = float(fact_v)
    except Exception:  # noqa: BLE001
        return _orange
    if plan_v <= 0:
        return _orange
    if fact_v <= 0:
        return "#c0392b"
    if fact_v >= plan_v:
        return _light_green
    miss_ratio = max(0.0, min(1.0, (plan_v - fact_v) / plan_v))
    lo = (255, 179, 179)
    hi = (192, 57, 43)
    rr = int(round(lo[0] + (hi[0] - lo[0]) * miss_ratio))
    gg = int(round(lo[1] + (hi[1] - lo[1]) * miss_ratio))
    bb = int(round(lo[2] + (hi[2] - lo[2]) * miss_ratio))
    return f"#{rr:02x}{gg:02x}{bb:02x}"


def _gdrs_match_data_source(series: pd.Series, wanted) -> pd.Series:
    """Фильтр по data_source без учёта регистра."""
    s = series.astype(str).str.strip().str.lower()
    w = str(wanted).strip().lower()
    if w in ("техника", "tech", "technique"):
        return s.isin({"техника", "tech", "technique"})
    if w in ("ресурсы", "ресурс"):
        return s.isin({"ресурсы", "ресурс"})
    return s == w


def _gdrs_is_metric_like_period_false_positive(col) -> bool:
    """Колонка не может быть «периодом»: метрики, дельта, суточные даты, служебные."""
    s = str(col).strip().lower()
    if not s:
        return True
    if s.startswith("unnamed"):
        return True
    if _gdrs_header_is_dd_mm_yyyy(col):
        return True
    bad = (
            "среднее" in s
            or "количество ресурс" in s
            or "за день" in s
            or "неделя" in s
            or "недел" in s
            or "дельт" in s
            or "отклон" in s
            or "план" == s
            or "факт" == s
            or "data_source" in s
            or "тип ресурсов" in s
    )
    if bad:
        return True
    # «…за месяц» в длинном названии метрики, не колонка «Месяц»
    if "за месяц" in s and s not in ("месяц", "за месяц") and "период" not in s:
        if not (s.startswith("месяц") or s.startswith("период")):
            return True
    return False


def _gdrs_resolve_period_column(df: pd.DataFrame):
    """
    Колонка календарного периода (Период / Месяц). Не используем find_column_by_partial
    с подстрокой «месяц» — иначе матчится «среднее … за месяц» и ломается ось X.
    """
    if df is None or getattr(df, "empty", True):
        return None
    for c in df.columns:
        if _gdrs_is_metric_like_period_false_positive(c):
            continue
        t = str(c).strip()
        tl = t.lower()
        if tl in ("период", "месяц", "period", "month"):
            return c
    for c in df.columns:
        if _gdrs_is_metric_like_period_false_positive(c):
            continue
        tl = str(c).strip().lower()
        if tl.startswith("период") or tl.startswith("месяц"):
            return c
    return None


def _gdrs_is_plan_column_false_positive(col) -> bool:
    s = str(col).strip().lower()
    if not s:
        return True
    if s.startswith("unnamed"):
        return True
    if _gdrs_header_is_dd_mm_yyyy(col):
        return True
    if "дельт" in s or "отклон" in s:
        return True
    if "бюджет" in s:
        return True
    # Метрики факта/средних и недельные поля не должны попадать в «План»
    if "среднее" in s or "average" in s:
        return True
    if "недел" in s or "week" in s:
        return True
    if "старт" in s or "конец" in s or "start" in s or "finish" in s:
        return True
    if s.startswith("планов") or s.startswith("планир"):
        return True
    return False


def _gdrs_resolve_plan_column(df: pd.DataFrame):
    """
    Колонка числового плана (чел.-дни и т.п.). Без жёсткого «подстрока план везде» —
    иначе цепляются «Планета», «плановый», «Старт План» из других отчётов.
    """
    if df is None or getattr(df, "empty", True):
        return None
    for c in df.columns:
        if _gdrs_is_plan_column_false_positive(c):
            continue
        tl = str(c).strip().lower()
        if tl in ("план", "plan"):
            return c
    for c in df.columns:
        if _gdrs_is_plan_column_false_positive(c):
            continue
        tl = str(c).strip().lower()
        if tl.startswith("план") and (len(tl) == 4 or tl[4] in " ,.(["):
            return c
        if tl.startswith("plan") and (len(tl) == 4 or tl[4] in " ,.(["):
            return c
    for c in df.columns:
        if _gdrs_is_plan_column_false_positive(c):
            continue
        tl = str(c).strip().lower()
        if re.search(r"(?<!\w)план(?!\w)", tl, flags=re.UNICODE):
            return c
        if re.search(r"(?<!\w)plan(?!\w)", tl, flags=re.UNICODE):
            return c
    return None


def _gdrs_point_pct_of_period_plan(
    by_frame: pd.DataFrame,
    df_src: pd.DataFrame,
    period_col: str,
    fact_col: str = "Факт",
) -> pd.DataFrame:
    """
    Доля для подписей точек «факт по неделям» / «факт по периоду»:
    **факт / сумма(План_numeric) по тому же периоду** × 100.
    Если колонки плана нет или сумма плана по периоду = 0 — fallback: доля факта в сумме факта по всем точкам (как раньше).
    Добавляет/перезаписывает колонки: «%», «План_период» (сумма плана по периоду или NaN).
    """
    out = by_frame.copy()
    if period_col not in out.columns or fact_col not in out.columns or out.empty:
        out["%"] = 0.0
        if "План_период" not in out.columns:
            out["План_период"] = np.nan
        return out
    fac = pd.to_numeric(out[fact_col], errors="coerce").fillna(0.0)
    total_fact = float(fac.sum())
    out["План_период"] = np.nan
    if df_src is not None and "План_numeric" in getattr(df_src, "columns", []):
        plan_sum = (
            df_src.groupby(period_col, dropna=False)["План_numeric"]
            .apply(lambda s: float(pd.to_numeric(s, errors="coerce").fillna(0.0).sum()))
            .reset_index(name="_psum")
        )
        out = out.merge(plan_sum, on=period_col, how="left")
        psum = pd.to_numeric(out["_psum"], errors="coerce").fillna(0.0)
        out["План_период"] = psum
        out.drop(columns=["_psum"], inplace=True, errors="ignore")
        out["%"] = 0.0
        mask = psum > 0
        out.loc[mask, "%"] = (fac.loc[mask] / psum.loc[mask] * 100.0).clip(lower=0.0)
        rem = ~mask
        if rem.any() and total_fact > 0:
            out.loc[rem, "%"] = (fac.loc[rem] / total_fact * 100.0).round(1)
    else:
        out["%"] = ((fac / total_fact * 100.0).round(1) if total_fact else 0.0)
    return out


def _gdrs_hist_collapse_week_grain(
    by_period_week: pd.DataFrame,
    period_col_hist: str,
    df_hist: pd.DataFrame,
) -> pd.DataFrame:
    """
    Если в колонке «Период» суточные даты — схлопнуть в месяц × номер недели,
    чтобы ось «Период — неделя» не превращалась в ряд дней.
    """
    if (
        by_period_week is None
        or by_period_week.empty
        or period_col_hist not in by_period_week.columns
        or "Неделя" not in by_period_week.columns
    ):
        return by_period_week
    out = by_period_week.copy()
    pdt = pd.to_datetime(out[period_col_hist], errors="coerce", dayfirst=True)
    if int(pdt.notna().sum()) < max(2, len(out) // 4):
        return out
    uniq_days = int(pdt.dt.normalize().nunique())
    uniq_months = int(pdt.dt.to_period("M").nunique())
    if uniq_days <= max(uniq_months * 2, 8):
        return out
    out["_mon"] = pdt.dt.to_period("M")
    collapsed = (
        out.groupby(["_mon", "Неделя"], as_index=False, dropna=False)["Факт"]
        .sum()
    )
    collapsed[period_col_hist] = collapsed["_mon"]
    collapsed["Период_стр"] = collapsed["_mon"].astype(str).str.strip()
    if df_hist is not None and "План_numeric" in getattr(df_hist, "columns", []):
        _src = df_hist.copy()
        _src["_mon"] = pd.to_datetime(
            _src[period_col_hist], errors="coerce", dayfirst=True
        ).dt.to_period("M")
        _plan_m = (
            _src.groupby("_mon", dropna=False)["План_numeric"]
            .apply(lambda s: float(pd.to_numeric(s, errors="coerce").fillna(0.0).sum()))
            .reset_index(name="План_период")
        )
        collapsed = collapsed.merge(_plan_m, on="_mon", how="left")
        fac = pd.to_numeric(collapsed["Факт"], errors="coerce").fillna(0.0)
        psum = pd.to_numeric(collapsed["План_период"], errors="coerce").fillna(0.0)
        collapsed["%"] = np.where(
            psum > 0, (fac / psum * 100.0).clip(lower=0.0), 0.0
        )
    else:
        collapsed = _gdrs_point_pct_of_period_plan(
            collapsed, df_hist, period_col_hist, "Факт"
        )
    return collapsed.drop(columns=["_mon"], errors="ignore")


def _sample_for_chart(df: pd.DataFrame, max_rows: int = _MAX_CHART_ROWS) -> pd.DataFrame:
    """
    Если датафрейм превышает max_rows, равномерно сэмплирует его и показывает уведомление.
    Используется перед передачей больших таблиц в Plotly.
    """
    if df is None or df.empty or len(df) <= max_rows:
        return df
    sampled = df.sample(n=max_rows, random_state=42).sort_index()
    st.info(
        f"Показаны {max_rows:,} из {len(df):,} строк (равномерная выборка для ускорения графика)."
    )
    return sampled


def _limit_bar_categories(
    df: pd.DataFrame,
    value_col: str,
    max_bars: int = 40,
    label: str = "позиций",
) -> pd.DataFrame:
    """
    Оставляет топ-max_bars строк по убыванию value_col.
    Если отрезаны строки — показывает предупреждение.
    Используется для горизонтальных bar-графиков с большим числом категорий.
    """
    if df is None or df.empty or len(df) <= max_bars:
        return df
    top_df = df.nlargest(max_bars, value_col)
    st.info(
        f"График показывает топ-{max_bars} из {len(df)} {label} по убыванию значения."
    )
    return top_df


def wrap_label(text, width=15):
    return "<br>".join(textwrap.wrap(text, width=width))


def _xaxis_range_positive(values, pad: float = 1.15, min_span: float = 1.0):
    """
    Диапазон оси X для неотрицательных величин (гориз. bar): без лишнего «пустого» поля справа.
    Учитывает только конечные неотрицательные числа; иначе — компактный дефолт.
    """
    s = pd.to_numeric(pd.Series(values), errors="coerce")
    s = s.replace([np.inf, -np.inf], np.nan).dropna()
    s = s[s >= 0]
    if s.empty:
        return [0.0, float(min_span)]
    xmax = float(s.max())
    if not np.isfinite(xmax) or xmax <= 0:
        xmax = float(min_span)
    upper = max(xmax * pad, float(min_span))
    return [0.0, upper]


def _clean_display_str(val, empty: str = "") -> str:
    """Строка для ячеек: без nan/None; без «Н/Д» в табличных данных."""
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return empty
    s = str(val).strip()
    if not s or s.lower() in ("nan", "nat", "none"):
        return empty
    return s


