def _finance_bdr_expense_deviation_chart_parts(
    plan_rub: pd.Series,
    fact_rub: pd.Series,
    *,
    threshold_mln: float = 0.01,
    min_abs_mln: float = 0.01,
    decimals: int = 1,
    unit_suffix: str = " млн рублей",
) -> tuple[pd.Series, pd.Series, list[str], list[str], list[str], list[str]]:
    """БДР/БДДС расходы: факт−план; >0 выше нуля (зелёный), <0 ниже (красный).

    Подписи: факт<план → «−…» красным, факт>план → «+…» зелёным (как таблица БДДС).
    """
    dev_mln = (fact_rub.astype(float) - plan_rub.astype(float)) / 1e6
    thr = float(threshold_mln)
    y_pos = dev_mln.where(dev_mln > thr)
    y_neg = dev_mln.where(dev_mln < -thr)
    floor_rub = float(min_abs_mln or 0.0) * 1e6
    d = max(0, int(decimals))
    suf = str(unit_suffix or "")
    txt_pos: list[str] = []
    clr_pos: list[str] = []
    txt_neg: list[str] = []
    clr_neg: list[str] = []
    for p, f, yp, yn in zip(plan_rub, fact_rub, y_pos, y_neg):
        try:
            pv = float(p)
            fv = float(f)
        except (TypeError, ValueError):
            pv = fv = 0.0
        diff_rub = fv - pv
        if pd.notna(yp):
            if abs(diff_rub) < floor_rub:
                txt_pos.append("")
                clr_pos.append(_fin_chart_neutral_color())
            elif fv > pv:
                txt_pos.append(f"+{abs(diff_rub) / 1e6:.{d}f}{suf}")
                clr_pos.append(_FINANCE_DEV_LABEL_GREEN)
            else:
                txt_pos.append("")
                clr_pos.append(_fin_chart_neutral_color())
        else:
            txt_pos.append("")
            clr_pos.append(_fin_chart_neutral_color())
        if pd.notna(yn):
            if abs(diff_rub) < floor_rub:
                txt_neg.append("")
                clr_neg.append(_fin_chart_neutral_color())
            elif fv < pv:
                txt_neg.append(f"-{abs(diff_rub) / 1e6:.{d}f}{suf}")
                clr_neg.append(_FINANCE_DEV_LABEL_RED)
            else:
                txt_neg.append("")
                clr_neg.append(_fin_chart_neutral_color())
        else:
            txt_neg.append("")
            clr_neg.append(_fin_chart_neutral_color())
    return y_pos, y_neg, txt_pos, clr_pos, txt_neg, clr_neg



def _finance_signed_deviation_bar_text(
    y_mln: pd.Series,
    *,
    min_abs_mln: float = 0.005,
    decimals: int = 1,
    unit_suffix: str = " млн. руб.",
) -> list[str]:
    """Подписи отклонений: +/− по знаку столбца (reserve = plan − fact)."""
    out: list[str] = []
    d = max(0, int(decimals))
    suf = str(unit_suffix or "")
    floor_mln = float(min_abs_mln or 0)
    for v in y_mln:
        if v is None or (isinstance(v, float) and pd.isna(v)):
            out.append("")
            continue
        try:
            fv = float(v)
        except (TypeError, ValueError):
            out.append("")
            continue
        if abs(fv) < floor_mln:
            out.append("")
            continue
        sign = "+" if fv > 0 else ("-" if fv < 0 else "")
        out.append(f"{sign}{abs(fv):.{d}f}{suf}" if sign else f"{abs(fv):.{d}f}{suf}")
    return out


def _bdds_recalc_reserve(df: pd.DataFrame) -> pd.DataFrame:
    """Единая формула отклонения БДДС: факт − план (как в таблицах и 1С overlay)."""
    if df is None or getattr(df, "empty", True):
        return df
    out = df.copy()
    if "budget plan" not in out.columns or "budget fact" not in out.columns:
        return out
    pl = pd.to_numeric(out["budget plan"], errors="coerce").fillna(0.0)
    fc = pd.to_numeric(out["budget fact"], errors="coerce").fillna(0.0)
    out["reserve budget"] = fc - pl
    return out


def _bdds_normalize_period_original(df: pd.DataFrame) -> pd.DataFrame:
    """Нормализует period_original к Period[M] для корректной агрегации графика."""
    if df is None or getattr(df, "empty", True) or "period_original" not in df.columns:
        return df
    out = df.copy()

    def _to_m(x):
        if isinstance(x, pd.Period):
            return x.asfreq("M") if x.freq != "M" else x
        if x is None or (isinstance(x, float) and pd.isna(x)):
            return pd.NaT
        try:
            return pd.Period(str(x), freq="M")
        except Exception:
            pass
        try:
            ts = pd.Timestamp(x)
            if pd.notna(ts):
                return ts.to_period("M")
        except Exception:
            pass
        return pd.NaT

    out["period_original"] = out["period_original"].map(_to_m)
    return out


def _finance_deviation_bar_text_signed_mln(
    y_mln: pd.Series,
    *,
    min_abs_mln: float = 0.005,
    decimals: int = 1,
    unit_suffix: str = " млн. руб.",
) -> list[str]:
    """Подписи отклонения: знак как в ячейке (факт − план)."""
    out: list[str] = []
    d = max(0, int(decimals))
    suf = str(unit_suffix or "")
    floor_mln = float(min_abs_mln or 0)
    for v in y_mln:
        if v is None or (isinstance(v, float) and pd.isna(v)):
            out.append("")
            continue
        try:
            fv = float(v)
        except (TypeError, ValueError):
            out.append("")
            continue
        if abs(fv) < floor_mln:
            out.append("")
            continue
        sign = "+" if fv > 0 else ("-" if fv < 0 else "")
        out.append(f"{sign}{abs(fv):.{d}f}{suf}" if sign else f"{abs(fv):.{d}f}{suf}")
    return out


def _finance_fmt_signed_million_deviation(v) -> str:
    """Ячейка отклонения: факт − план, со знаком +/− (как подписи на графике БДДС)."""
    if v is None or v == "" or (isinstance(v, float) and pd.isna(v)):
        return ""
    try:
        fv = float(v)
    except (TypeError, ValueError):
        return format_million_rub(v, decimals=1)
    s = format_million_rub(abs(fv), decimals=1)
    if fv > 0:
        return "+" + s
    if fv < 0:
        return "-" + s
    return s


def _forecast_bdd_bar_value_labels(
    values_rub: pd.Series,
    *,
    min_abs_rub: float = 0.0,
) -> list[str]:
    """Подписи к столбцам прогнозного БДДС (млн ₽, одна строка). Пусто только у нулей/NaN."""
    out: list[str] = []
    floor = float(min_abs_rub) if min_abs_rub else 0.0
    for v in values_rub:
        if v is None or (isinstance(v, float) and pd.isna(v)):
            out.append("")
            continue
        try:
            rv = float(v)
        except (TypeError, ValueError):
            out.append("")
            continue
        if floor > 0.0 and abs(rv) < floor:
            out.append("")
            continue
        if abs(rv) < 1e-9:
            out.append("")
            continue
        x = rv / 1e6
        ax = abs(x)
        if ax >= 100.0:
            txt = f"{x:.1f}"
        elif ax >= 1.0:
            txt = f"{x:.2f}"
        elif ax >= 0.01:
            txt = f"{x:.3f}"
        else:
            txt = f"{x:.4f}"
        out.append(txt)
    return out


def _forecast_bdd_bar_inside_labels(
    values_rub: pd.Series,
    ymax_mln: float,
    *,
    with_unit_suffix: bool = False,
) -> list[str]:
    out: list[str] = []
    ymax_mln = float(ymax_mln or 0.0)
    thr = max(ymax_mln * 0.05, 1.0)
    for v in values_rub:
        if v is None or (isinstance(v, float) and pd.isna(v)):
            out.append("")
            continue
        try:
            x = float(v) / 1e6
        except (TypeError, ValueError):
            out.append("")
            continue
        if abs(x) < 1e-9 or x < thr:
            out.append("")
            continue
        txt = f"{x:.1f}" if x >= 1.0 else f"{x:.2f}"
        out.append(f"{txt} млн" if with_unit_suffix else txt)
    return out


def _finance_bar_yaxis_tight(
    ymax_mln: float,
    *,
    outside_labels: bool = False,
    tick_stride: int = 1,
) -> tuple[float, float]:
    ymax_mln = float(ymax_mln or 0.0)
    if ymax_mln <= 0:
        return 5.0, 10.0
    head = max(8.0, ymax_mln * 0.24) if outside_labels else max(3.0, ymax_mln * 0.08)
    y_top = ymax_mln + head
    if y_top <= 40:
        dtick = 5.0
    elif y_top <= 100:
        dtick = 10.0
    elif y_top <= 200:
        dtick = 20.0
    elif y_top <= 500:
        dtick = 50.0
    elif y_top <= 1200:
        dtick = 100.0
    else:
        dtick = 200.0
    stride = max(1, int(tick_stride))
    dtick = float(dtick * stride)
    y_max = float(np.ceil(y_top / dtick) * dtick)
    return dtick, y_max


def _apply_bar_uniformtext(fig: go.Figure) -> go.Figure:
    """
    Подписи bar: uniformtext + automargin по осям без перезаписи margin
    (для графиков с кастомными l/r/t/b).
    """
    try:
        fig.update_layout(uniformtext=dict(minsize=8, mode="show"))
        fig.update_xaxes(automargin=True)
        fig.update_yaxes(automargin=True)
    except Exception:
        pass
    return fig


def _plotly_bar_hide_legacy_textfont(fig: go.Figure) -> go.Figure:
    """
    У некоторых тем/режимов Plotly базовый textfont рисуется вместе с insidetextfont/
    outsidetextfont для Bar — получаются «удвоенные» цифры. Прозрачный базовый
    слой оставляет видимым только явно заданные inside/outside шрифты.
    """
    try:
        for tr in getattr(fig, "data", ()) or []:
            if getattr(tr, "type", None) != "bar":
                continue
            try:
                tr.update(textfont=dict(color="rgba(0,0,0,0)", size=1))
            except Exception:
                continue
    except Exception:
        pass
    return fig


def _plotly_text_all_empty(text) -> bool:
    if text is None:
        return True
    if isinstance(text, (list, tuple)):
        for t in text:
            if t is None:
                continue
            if str(t).strip():
                return False
        return True
    if isinstance(text, np.ndarray):
        for t in text:
            if t is None or (isinstance(t, float) and np.isnan(t)):
                continue
            if str(t).strip():
                return False
        return True
    if isinstance(text, (str, bytes)) and str(text).strip():
        return False
    return True


def _bar_values_axis_datelike_gantt(tr) -> bool:
    if type(tr).__name__ != "Bar":
        return False
    orient = getattr(tr, "orientation", None) or "v"
    base = getattr(tr, "base", None)
    if base is not None:
        s = pd.to_datetime(pd.Series(list(base)), errors="coerce", utc=False)
        if s.notna().any():
            return True
    if orient == "h":
        x = getattr(tr, "x", None)
        if x is not None:
            s = pd.to_datetime(pd.Series(list(x)), errors="coerce", utc=False)
            n = len(s)
            if n and int(s.notna().sum()) >= max(1, n // 2 + n % 2):
                return True
    return False


def _bar_scalar_is_negative(v) -> bool:
    if v is None:
        return False
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if isinstance(v, float) and (np.isnan(v) or np.isinf(v)):
            return False
        return v < 0
    if hasattr(v, "toordinal") or hasattr(v, "to_pydatetime"):
        return False
    try:
        return float(v) < 0
    except (TypeError, ValueError):
        return False


def _bar_scalar_is_zero(v) -> bool:
    if v is None:
        return True
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if isinstance(v, float) and (np.isnan(v) or np.isinf(v)):
            return True
        return float(v) == 0.0
    if hasattr(v, "toordinal") or hasattr(v, "to_pydatetime"):
        return False
    try:
        return float(v) == 0.0
    except (TypeError, ValueError):
        return False


def _format_plotly_bar_scalar(v) -> str:
    if v is None:
        return ""
    if isinstance(v, (float, int)) and not isinstance(v, bool):
        if isinstance(v, float) and (np.isnan(v) or np.isinf(v)):
            return ""
        if isinstance(v, float) and float(v) == int(v) and abs(v) < 1e12:
            return str(int(v))
        if isinstance(v, float):
            a = abs(v)
            if a >= 1000:
                return f"{v:,.0f}".replace(",", " ")
            if a >= 1:
                return f"{v:.2f}"
            if a >= 0.01:
                return f"{v:.2f}"
            return f"{v:.2g}"
        return str(int(v)) if v == int(v) else str(v)
    if hasattr(v, "strftime"):
        try:
            return v.strftime("%d.%m.%Y")
        except Exception:
            return str(v)
    try:
        t = pd.Timestamp(v)
        if pd.notna(t):
            return t.strftime("%d.%m.%Y")
    except Exception:
        pass
    s = str(v).strip()
    if s.lower() in ("nan", "none", "nat", ""):
        return ""
    return s


def apply_standard_pie_layout(
    fig: go.Figure,
    *,
    height=None,
    pct_fontsize=22,
    showlegend=True,
    clear_annotations=False,
    extra_layout=None,
    text_show_value_and_percent: bool = False,
) -> go.Figure:
    """В секторе — проценты или значение+процент; легенда — под диаграммой по центру."""
    if fig is None:
        return fig
    _n_slices = 0
    try:
        for tr in fig.data:
            if getattr(tr, "type", None) == "pie":
                _labs = getattr(tr, "labels", None)
                if _labs is not None:
                    _n_slices = max(_n_slices, len(_labs))
    except Exception:
        pass
    _auto = pie_layout_for_bottom_legend(
        max(_n_slices, 1),
        font_size=CHART_LEGEND_FONT_SIZE,
        items_per_row=4 if text_show_value_and_percent else 3,
        outside_labels=text_show_value_and_percent,
    )
    dx = _auto["domain_x"]
    dy = _auto["domain_y"]
    _b_margin = int(_auto["margin_bottom"])
    _leg_y = _auto["legend_y"]
    _leg_clr = _fin_chart_legend_text_color()
    _out_txt_clr = _fin_chart_label_color()
    try:
        if text_show_value_and_percent:
            _pie_line = "rgba(148,163,184,0.75)"
            try:
                from dashboards.light_theme import is_light_preview_active

                if not is_light_preview_active():
                    _pie_line = "rgba(15,23,42,0.85)"
            except Exception:
                pass
            fig.update_traces(
                selector=dict(type="pie"),
                textinfo="text",
                texttemplate="<b>%{value}</b><br>%{percent:.2%}",
                textposition="outside",
                textfont=dict(
                    size=max(11, int(pct_fontsize) - 4),
                    color=_out_txt_clr,
                    family="Inter, system-ui, Arial, sans-serif",
                ),
                marker_line_width=1,
                marker_line_color=_pie_line,
                domain=dict(x=[float(dx[0]), float(dx[1])], y=[float(dy[0]), float(dy[1])]),
            )
        else:
            fig.update_traces(
                selector=dict(type="pie"),
                textinfo="percent",
                texttemplate="%{percent:.0%}",
                textposition="inside",
                insidetextorientation="horizontal",
                textfont=dict(
                    size=int(pct_fontsize),
                    color="#ffffff",
                    family="Inter, system-ui, Arial, sans-serif",
                ),
                marker_line_width=0,
                domain=dict(x=[float(dx[0]), float(dx[1])], y=[float(dy[0]), float(dy[1])]),
            )
    except Exception:
        pass
    layout = dict(
        showlegend=bool(showlegend),
        legend=standard_pie_chart_legend(
            font=dict(size=CHART_LEGEND_FONT_SIZE, color=_leg_clr),
            y=_leg_y,
        ),
        uniformtext=dict(minsize=max(10, int(pct_fontsize) - 5), mode="show"),
        margin=dict(
            l=44,
            r=int(180 if text_show_value_and_percent else 44),
            t=44,
            b=_b_margin,
        ),
    )
    if height is not None:
        layout["height"] = int(height)
    if extra_layout:
        layout.update(extra_layout)
    fig.update_layout(**layout)
    if clear_annotations:
        try:
            fig.update_layout(annotations=[])
        except Exception:
            pass
    return fig


def _pie_apply_percent_inside_legend_left(
    fig: go.Figure,
    *,
    height=None,
    pct_fontsize=22,
    legend_fontsize=12,
    left_margin=None,
    domain_x=None,
    domain_y=None,
    clear_annotations=False,
    showlegend=True,
    extra_layout=None,
    text_show_value_and_percent: bool = False,
) -> go.Figure:
    """Обратная совместимость: делегирует в apply_standard_pie_layout."""
    del legend_fontsize, left_margin, domain_x, domain_y
    return apply_standard_pie_layout(
        fig,
        height=height,
        pct_fontsize=pct_fontsize,
        showlegend=showlegend,
        clear_annotations=clear_annotations,
        extra_layout=extra_layout,
        text_show_value_and_percent=text_show_value_and_percent,
    )


def _apply_plotly_spec_411_labels(fig: go.Figure) -> go.Figure:
    if fig is None:
        return fig
    try:
        traces = list(fig.data or [])
    except Exception:
        return fig
    for tr in traces:
        try:
            tname = type(tr).__name__
            if tname == "Bar":
                if getattr(tr, "texttemplate", None):
                    continue
                if not _plotly_text_all_empty(getattr(tr, "text", None)):
                    continue
                if _bar_values_axis_datelike_gantt(tr):
                    continue
                orient = getattr(tr, "orientation", None) or "v"
                if orient == "h":
                    values = list(getattr(tr, "x", None) or [])
                else:
                    values = list(getattr(tr, "y", None) or [])
                if not values:
                    continue
                out = []
                tpos = []
                for v in values:
                    if _bar_scalar_is_zero(v):
                        out.append("")
                        tpos.append("none")
                        continue
                    out.append(_format_plotly_bar_scalar(v))
                    if _bar_scalar_is_negative(v):
                        tpos.append("auto")
                    else:
                        tpos.append("outside")
                tr.update(
                    text=out,
                    textposition=(tpos[0] if len(tpos) == 1 else tpos),
                    cliponaxis=False,
                )
            elif tname == "Pie":
                if getattr(tr, "texttemplate", None):
                    continue
                if not _plotly_text_all_empty(getattr(tr, "text", None)):
                    continue
                ti_raw = getattr(tr, "textinfo", None)
                if ti_raw is None:
                    tr.update(textinfo="label+percent")
                    continue
                tn = (
                    str(ti_raw)
                    .strip()
                    .lower()
                    .replace(" ", "")
                    .replace("+", "")
                )
                if tn in ("percent", "none"):
                    continue
                if str(ti_raw).strip().lower() == "none":
                    continue
                if "label" in str(ti_raw).lower():
                    continue
                tr.update(textinfo="label+percent")
        except Exception:
            continue
    return fig


# Ширина холста Plotly по умолчанию: одинаковая «рамка» графика между проектами/блоками при stretch в Streamlit.
_RENDER_CHART_DEFAULT_WIDTH_PX = 1150


def render_chart(
    fig,
    key: str = None,
    height: int = None,
    max_height: int = 900,
    caption_below: str = None,
    plotly_config_extra=None,
    *,
    skip_clamp_zoom: bool = False,
    omit_default_width: bool = False,
    scroll_viewport_height: int = None,
    compact: bool = False,
) -> None:
    """
    Единая точка вывода Plotly-графика с адаптивной конфигурацией.
    Заменяет прямые вызовы st.plotly_chart() по всему файлу.
    Если задан только height — ограничиваем сверху max_height для читаемости на больших bar-графиках.
    caption_below — подпись под графиком (заголовок снизу); при этом у fig убирается верхний title.
    plotly_config_extra — дополнительные ключи config (мержатся поверх _PLOTLY_CONFIG).
    skip_clamp_zoom: не вызывать _clamp_plotly_scroll_zoom_padding (Gantt по датам: minallowed/maxallowed
    на оси X в Streamlit иногда даёт пустую область графика).
    omit_default_width: не подставлять layout.width=1150 — чтобы график реально растягивался на ширину контейнера.
    scroll_viewport_height: для длинных Gantt — figure на полную высоту, прокрутка внутри блока (px).
    compact: фиксированная высота fig без autosize (короткие bar-графики ПД без внутреннего скролла).
    """
    # Круговая: Plotly по умолчанию оставляет только камеру — полный modebar как у bar.
    _is_pie = _figure_has_pie_trace(fig)
    if _is_pie:
        try:
            fig = _ensure_pie_full_modebar(fig)
        except Exception:
            pass
        try:
            _inject_pie_modebar_zoom_sync()
        except Exception:
            pass
    cfg = dict(_PLOTLY_CONFIG)
    if _is_pie:
        cfg.update(_PLOTLY_CONFIG_FULL_MODEBAR)
    if plotly_config_extra:
        cfg.update(plotly_config_extra)
    if _is_pie and "modeBarButtons" not in cfg:
        cfg["modeBarButtons"] = _PLOTLY_MODEBAR_BUTTONS_FULL
    kwargs = {
        "width": "stretch",
        "config": cfg,
    }
    if key:
        kwargs["key"] = key
    if height is not None:
        h = min(int(height), int(max_height)) if max_height else int(height)
        fig.update_layout(height=h)
    _layout_h: Optional[int] = None
    if height is not None:
        _layout_h = int(h)
    if _layout_h is None:
        try:
            _lh = fig.layout.height
            if _lh is not None:
                _layout_h = int(_lh)
        except Exception:
            _layout_h = None
    if caption_below:
        try:
            fig.update_layout(title_text="")
        except Exception:
            pass
    try:
        _lw = fig.layout.width
        if _lw is None and not omit_default_width:
            fig.update_layout(width=_RENDER_CHART_DEFAULT_WIDTH_PX)
    except Exception:
        pass
    if not skip_clamp_zoom:
        _clamp_plotly_scroll_zoom_padding(fig)
    _apply_plotly_spec_411_labels(fig)
    _resync_plotly_chart_theme(fig)
    _apply_finance_light_preview_chart_colors(fig)
    if compact and _layout_h is not None:
        try:
            fig.update_layout(autosize=False, height=_layout_h)
        except Exception:
            pass
    elif not compact:
        try:
            fig.update_layout(autosize=True)
        except Exception:
            pass
    try:
        _yax = fig.layout.yaxis
        if _yax is not None and getattr(_yax, "autorange", None) is False:
            _yr = getattr(_yax, "range", None)
            if _yr is not None and len(_yr) == 2:
                fig.update_yaxes(
                    range=[float(_yr[0]), float(_yr[1])],
                    autorange=False,
                )
    except Exception:
        pass
    try:
        _xax = fig.layout.xaxis
        if _xax is not None and getattr(_xax, "autorange", None) is False:
            _xr = getattr(_xax, "range", None)
            if _xr is not None and len(_xr) == 2:
                fig.update_xaxes(range=[_xr[0], _xr[1]], autorange=False)
    except Exception:
        pass
    _use_scroll = (
        scroll_viewport_height is not None
        and _layout_h is not None
        and _layout_h > int(scroll_viewport_height)
    )
    if _use_scroll:
        _vh = int(scroll_viewport_height)
        try:
            from dashboards.light_theme import is_light_preview_active

            if is_light_preview_active() and key:
                _gk = str(key).replace("-", "_")
                st.markdown(
                    f"<style>"
                    f"html body.gdrs-light-preview div[class*='st-key-{_gk}'] "
                    f"div[data-testid='stVerticalBlockBorderWrapper']{{"
                    f"overflow-y:auto!important;overflow-x:hidden!important;"
                    f"-webkit-overflow-scrolling:touch!important;}}"
                    f"html body.gdrs-light-preview div[class*='st-key-{_gk}'] "
                    f"[data-testid='stPlotlyChart']{{overflow:visible!important;"
                    f"background:#ffffff!important;border:1px solid #cbd5e1!important;}}"
                    f"</style>",
                    unsafe_allow_html=True,
                )
        except Exception:
            pass
        # Длинный Gantt: рендерим график на ПОЛНУЮ высоту (_layout_h) в нативном
        # прокручиваемом контейнере Streamlit (st.container(height=...)). Это
        # надёжнее iframe + to_html(CDN): Plotly рендерится штатно на всю ширину,
        # без проблем с асинхронной загрузкой и нулевой шириной (из-за чего полосы
        # не отрисовывались). Колёсико прокручивает список; масштаб — панель Plotly.
        try:
            fig.update_layout(autosize=True, height=_layout_h, width=None)
        except Exception:
            pass
        _scroll_kwargs = dict(kwargs)
        _cfg_scroll = dict(cfg)
        _cfg_scroll["scrollZoom"] = False
        _scroll_kwargs["config"] = _cfg_scroll
        try:
            _scroll_box = st.container(height=_vh, border=False)
            with _scroll_box:
                st.plotly_chart(fig, **_scroll_kwargs)
            if caption_below:
                _chart_caption_below(caption_below, tight=True)
            return
        except Exception:
            # Фолбэк: график во всю высоту, прокрутка страницей.
            pass
    st.plotly_chart(fig, **kwargs)
    if caption_below:
        _chart_caption_below(caption_below)


def render_export_buttons(
    df: pd.DataFrame = None,
    fig=None,
    csv_filename: str = "export.csv",
    png_filename: str = "chart.png",
    key_prefix: str = "export",
) -> None:
    """
    Автоэкспорт после отчёта: только PNG графика (поповер «Скачать таблицу» отключён).

    Args:
        df:           не даёт отдельной кнопки таблицы в этом блоке
        fig:          Plotly-фигура для PNG (опционально)
        csv_filename: резерв
        png_filename: Имя PNG-файла
        key_prefix:   префикс ключей виджетов
    """
    has_df = df is not None and not df.empty
    png_bytes = None
    if fig is not None:
        try:
            png_bytes = fig.to_image(format="png", width=1400, height=700, scale=2)
        except Exception:
            png_bytes = None

    if not has_df and png_bytes is None:
        return

    def _log_export(fmt_name: str, file_name: str):
        try:
            from auth import get_current_user
            from logger import log_action

            u = get_current_user()
            if u:
                log_action(
                    u["username"],
                    "data_exported",
                    f"{fmt_name}:{file_name} ({key_prefix})",
                )
        except Exception:
            pass

    if has_df and png_bytes is not None:
        # Таблицу из автоматического экспорта не дублируем (поповер «Скачать таблицу» убран по макету) —
        # остаётся только PNG графика.
        try:
            st.download_button(
                label="Скачать PNG",
                data=png_bytes,
                file_name=png_filename,
                mime="image/png",
                key=f"{key_prefix}_png",
                on_click=lambda: _log_export("png", png_filename),
            )
        except TypeError:
            st.download_button(
                label="Скачать PNG",
                data=png_bytes,
                file_name=png_filename,
                mime="image/png",
                key=f"{key_prefix}_png",
            )
        return

    if png_bytes is not None:
        try:
            st.download_button(
                label="Скачать PNG",
                data=png_bytes,
                file_name=png_filename,
                mime="image/png",
                key=f"{key_prefix}_png",
                on_click=lambda: _log_export("png", png_filename),
            )
        except TypeError:
            st.download_button(
                label="Скачать PNG",
                data=png_bytes,
                file_name=png_filename,
                mime="image/png",
                key=f"{key_prefix}_png",
            )


def _deviations_filter_month_string_to_period(month_str):
    try:
        parts = str(month_str).split()
        if len(parts) == 2:
            month_name, year = parts
            month_num = None
            for num, russian_name in RUSSIAN_MONTHS.items():
                if russian_name == month_name:
                    month_num = num
                    break
            if month_num:
                return pd.Period(f"{year}-{month_num:02d}", freq="M")
    except Exception:
        pass
    return None


def _drop_deviation_hierarchy_artifacts(d: pd.DataFrame) -> pd.DataFrame:
    """Удаляет служебные колонки _dt_* после фильтрации по иерархии MSP."""
    if d is None or getattr(d, "empty", True):
        return d
    drop = [c for c in d.columns if str(c).startswith("_dt_")]
    if not drop:
        return d
    return d.drop(columns=drop, errors="ignore")


# Разделитель для плоской модели «Блок · Раздел» (нет колонок уровня MSP в CSV/Excel)
_DEVIATIONS_FLAT_FB_SEP = " · "


def _deviations_resolve_task_col(df: pd.DataFrame):
    if df is None or not hasattr(df, "columns"):
        return None
    if "task name" in df.columns:
        return "task name"
    return _dev_tasks_find_column(df, ["Задача", "task", "Task Name", "Название"])


def _deviations_effective_level_col(df: pd.DataFrame):
    """
    Колонка уровня иерархии MSP для фильтров отклонений.

    ``_dev_tasks_resolve_level_column`` иногда не видит уровень, хотя после
    ``ensure_msp_hierarchy_columns`` уже есть непустой ``level structure``/``level``
    — тогда не падаем в сырой ``block`` («Блок U1…») в селекте «Функциональный блок».
    """
    if df is None or getattr(df, "empty", True):
        return None
    c = _dev_tasks_resolve_level_column(df)
    if c and c in df.columns:
        s = _dev_outline_level_numeric(df[c])
        if s.notna().any():
            return c
    if "level structure" in df.columns:
        s = _dev_outline_level_numeric(df["level structure"])
        if s.notna().any():
            return "level structure"
    if "level" in df.columns:
        s = _dev_outline_level_numeric(df["level"])
        if s.notna().any():
            return "level"
    return None


def _deviations_flat_fb_label(block_val, section_val) -> str:
    b = (
        str(block_val).strip()
        if block_val is not None and not (isinstance(block_val, float) and pd.isna(block_val))
        else ""
    )
    s = (
        str(section_val).strip()
        if section_val is not None and not (isinstance(section_val, float) and pd.isna(section_val))
        else ""
    )
    if b and s:
        return f"{b}{_DEVIATIONS_FLAT_FB_SEP}{s}"
    return b or s or ""


def _deviations_use_flat_block_section_task(df: pd.DataFrame) -> bool:
    """Excel/фиксированный макет: Блок + Раздел + Задача без колонок outline MSP."""
    if df is None or getattr(df, "empty", True):
        return False
    if _deviations_effective_level_col(df) is not None:
        return False
    tc = _deviations_resolve_task_col(df)
    if not tc or tc not in df.columns:
        return False
    if "block" not in df.columns or "section" not in df.columns:
        return False
    return True


def _deviations_flat_functional_block_options(df_slice: pd.DataFrame) -> list:
    if df_slice is None or getattr(df_slice, "empty", True):
        return ["Все"]
    if "block" not in df_slice.columns or "section" not in df_slice.columns:
        return ["Все"]
    w = df_slice[["block", "section"]].copy()
    w["_lbl"] = w.apply(lambda r: _deviations_flat_fb_label(r["block"], r["section"]), axis=1)
    u = sorted({x for x in w["_lbl"].dropna().astype(str).str.strip().tolist() if x})
    return ["Все"] + u


def _deviations_flat_building_options(
    df_slice: pd.DataFrame, selected_fb: str, task_col: str
) -> list:
    if df_slice is None or getattr(df_slice, "empty", True):
        return ["Все"]
    if not task_col or task_col not in df_slice.columns:
        return ["Все"]
    sub = df_slice
    if selected_fb != "Все" and _DEVIATIONS_FLAT_FB_SEP in str(selected_fb):
        parts = str(selected_fb).split(_DEVIATIONS_FLAT_FB_SEP, 1)
        if len(parts) == 2:
            blk, sec = parts[0].strip(), parts[1].strip()
            sub = sub[sub["block"].astype(str).str.strip() == blk]
            sub = sub[sub["section"].astype(str).str.strip() == sec]
    u = sorted(sub[task_col].dropna().astype(str).str.strip().unique().tolist())
    return ["Все"] + u


def _deviations_msp_norm_colname(s: str) -> str:
    t = (
        str(s)
        .replace("\ufeff", "")
        .replace("\u00a0", " ")
        .replace("\u202f", " ")
        .replace("\u2007", " ")
    )
    t = re.sub(r"[\s\t\n\r]+", " ", t).strip().lower()
    return t


def _deviations_msp_sched_col(d: pd.DataFrame, candidates) -> Optional[str]:
    if d is None or getattr(d, "empty", True):
        return None
    cols_norm = {_deviations_msp_norm_colname(c): c for c in d.columns}
    for name in candidates:
        n = _deviations_msp_norm_colname(name)
        if n in cols_norm:
            return cols_norm[n]
    return None


def _deviations_msp_col_contains(d: pd.DataFrame, needles, exclude=()) -> Optional[str]:
    if d is None or getattr(d, "empty", True):
        return None
    ex = tuple(str(x).lower() for x in exclude)
    for c in d.columns:
        sl = _deviations_msp_norm_colname(c)
        if any(e in sl for e in ex):
            continue
        for n in needles:
            if n.lower() in sl:
                return c
    return None


def _deviations_msp_gantt_style_block_meta(
    d: pd.DataFrame,
) -> tuple[Optional[str], list[str]]:
    """Как «График проекта»: (колонка блока, значения). Пустой список — нет MSP-поля для селекта."""
    if d is None or getattr(d, "empty", True):
        return None, []
    block_msp = _deviations_msp_sched_col(d, ["block", "БЛОК", "Блок"])
    block_res = (
        block_msp
        or _deviations_msp_sched_col(d, ["Функциональный блок", "Functional block"])
        or _deviations_msp_sched_col(d, ["section", "Раздел"])
    )
    section_res = _deviations_msp_sched_col(d, ["section", "Раздел", "БЛОК", "блок"])
    if not block_res or block_res not in d.columns:
        return None, []

    def _is_gen_blk(v) -> bool:
        return _is_generic_block_name(v)

    _raw_b = sorted(
        d[block_res].dropna().astype(str).map(str.strip).unique().tolist()
    )
    _raw_b = [b for b in _raw_b if b and b.lower() != "nan"]
    _non_gen = [b for b in _raw_b if not _is_gen_blk(b)]
    _block_vals = _non_gen if _non_gen else []
    if not block_msp:
        if (
            (not _non_gen)
            and section_res
            and section_res in d.columns
            and section_res != block_res
        ):
            _sec_v = d[section_res].dropna().astype(str).map(str.strip)
            _sec_u = sorted({s for s in _sec_v.tolist() if s and s.lower() != "nan"})
            _sec_ng = [s for s in _sec_u if not _is_gen_blk(s)]
            if _sec_ng:
                _block_vals = sorted(_sec_ng)
                block_res = section_res
    if not _block_vals:
        return None, []
    return block_res, _gantt_dedupe_block_filter_values(_block_vals)


def _deviations_msp_gantt_style_building_col(d: pd.DataFrame) -> Optional[str]:
    if d is None or getattr(d, "empty", True):
        return None
    c = _deviations_msp_sched_col(
        d,
        [
            "building",
            "Building",
            "строение",
            "Строение",
            "корпус",
            "Корпус",
            "объект",
            "Объект",
        ],
    ) or _deviations_msp_col_contains(
        d,
        ("строени", "building", "корпус", "объект"),
        exclude=("приоритет", "риск", "severity"),
    )
    if c and c in d.columns:
        return c
    return None


def _deviations_gantt_like_task_label(val) -> str:
    """Как «График проекта» / _gantt_clean_task_label — для списка строений ур. 3."""
    t = str(val).strip()
    if not t or t.lower() in ("nan", "none"):
        return ""
    t = re.sub(r"(?i)^\s*задача\s+\d+\s+", "", t)
    t = re.sub(r"(?i)^\s*задача\s+", "", t)
    return sanitize_display_label(t.strip())


def _deviations_slice_msp_csv_if_tagged(df: pd.DataFrame) -> pd.DataFrame:
    """Как «График проекта»: при наличии msp_*.csv в __source_file — только эти строки."""
    if df is None or getattr(df, "empty", True):
        return df
    if "__source_file" not in df.columns:
        return df.copy()
    _src_low = df["__source_file"].astype(str).str.lower()
    _is_msp = (
        _src_low.str.startswith("msp_")
        | _src_low.str.contains("/msp_", na=False)
        | _src_low.str.contains(r"\\msp_", na=False, regex=True)
    )
    if bool(_is_msp.any()):
        return df[_is_msp].copy()
    return df.copy()


def _deviations_plot_df_plan_rows_like_gantt(df: pd.DataFrame) -> pd.DataFrame:
    """Строки с заполненными плановыми датами — как `plot_df` в «График проекта»."""
    w = _deviations_slice_msp_csv_if_tagged(df)
    if w is None or getattr(w, "empty", True):
        return pd.DataFrame()
    if "plan start" not in w.columns or "plan end" not in w.columns:
        return pd.DataFrame()
    out = w.copy()
    out["plan start"] = pd.to_datetime(out["plan start"], errors="coerce")
    out["plan end"] = pd.to_datetime(out["plan end"], errors="coerce")
    return out[out["plan start"].notna() & out["plan end"].notna()].copy()


def _deviations_gantt_best_level_column(d: pd.DataFrame) -> Optional[str]:
    """Эвристика колонки уровня — как `_gantt_best_level_column` в «График проекта»."""
    if d is None or getattr(d, "empty", True):
        return None
    best_c, best_sc = None, 0
    for c in d.columns:
        raw = str(c).strip()
        s = raw.lower().replace("_", " ")
        s = re.sub(r"\s+", " ", s).strip()
        if "приоритет" in s or "риск" in s or "severity" in s:
            continue
        score = 0
        if s in ("level", "outline level", "outline_number", "wbs level"):
            score += 8
        if "outline" in s and "level" in s.replace(" ", ""):
            score += 7
        if "level structure" in s or "уровень структуры" in s:
            score += 6
        if s == "уровень" or s.endswith(" уровень"):
            score += 5
        if "wbs" in s and "level" in s.replace(" ", ""):
            score += 5
        if "исходный" in s and "уровень" in s:
            score += 5
        if "уровень" in s and "приоритет" not in s and "риск" not in s:
            score += 3
        if score > best_sc:
            best_sc, best_c = score, c
    return best_c if best_sc >= 3 else None


def _deviations_resolve_level_col_like_gantt(d: pd.DataFrame) -> Optional[str]:
    """Колонка уровня MSP — тот же порядок, что в «График проекта» для `plot_df`."""
    if d is None or getattr(d, "empty", True):
        return None
    level_col = _deviations_msp_sched_col(
        d,
        [
            "level",
            "level structure",
            "Outline Level",
            "outline level",
            "outline number",
            "WBS Level",
            "wbs level",
            "Уровень",
            "уровень структуры",
            "Уровень_структуры",
            "уровень иерархии",
            "Исходный уровень",
        ],
    )
    if not level_col:
        cols_lower = {str(c).strip().lower(): c for c in d.columns}
        for w in (
            "level",
            "outline level",
            "outline_level",
            "outline number",
            "исходный уровень",
            "исходный_уровень",
            "уровень",
        ):
            if w in cols_lower:
                level_col = cols_lower[w]
                break
        if not level_col:
            for c in d.columns:
                sl = str(c).strip().lower()
                if "outline" in sl and "level" in sl.replace(" ", ""):
                    level_col = c
                    break
        if not level_col:
            for c in d.columns:
                sl = str(c).strip().lower()
                if "wbs" in sl and "level" in sl.replace(" ", ""):
                    level_col = c
                    break
        if not level_col:
            for c in d.columns:
                sl = str(c).strip().lower()
                if "уровень" in sl and "приоритет" not in sl and "риск" not in sl:
                    level_col = c
                    break
    if not level_col:
        level_col = _deviations_msp_col_contains(
            d,
            (
                "уровень структуры",
                "уровень_структуры",
                "outline level",
                "wbs level",
                "уровень",
                "level",
            ),
            exclude=("приоритет", "риск", "severity"),
        )
    if not level_col and "level structure" in d.columns:
        level_col = "level structure"
    if not level_col:
        level_col = _deviations_gantt_best_level_column(d)
    if level_col and level_col in d.columns:
        return level_col
    return None


def _deviations_l3_building_labels_like_gantt(df: pd.DataFrame) -> list[str]:
    """Подписи «Строение» как fallback ганта: `plot_df` + level==3 + task name."""
    p = _deviations_plot_df_plan_rows_like_gantt(df)
    if p is None or getattr(p, "empty", True):
        return []
    lc = _deviations_resolve_level_col_like_gantt(p)
    tc = _deviations_resolve_task_col(p)
    if not lc or not tc or lc not in p.columns or tc not in p.columns:
        return []
    _lv = pd.to_numeric(p[lc], errors="coerce")
    if not (_lv == 3).any():
        return []
    ser = p.loc[_lv == 3, tc].dropna()
    return sorted(
        {
            _deviations_gantt_like_task_label(x)
            for x in ser.tolist()
            if _deviations_gantt_like_task_label(x)
        }
    )


def _deviations_l3_building_option_labels(
    d: pd.DataFrame, level_col: str, task_col: str
) -> list[str]:
    """Совместимость: сначала как гант (`plot_df`), иначе переданные колонки уровня/задачи."""
    g = _deviations_l3_building_labels_like_gantt(d)
    if g:
        return _gantt_dedupe_block_filter_values(g)
    if d is None or getattr(d, "empty", True):
        return []
    if not level_col or not task_col or level_col not in d.columns or task_col not in d.columns:
        return []
    _lv = pd.to_numeric(d[level_col], errors="coerce")
    if not (_lv == 3).any():
        return []
    ser = d.loc[_lv == 3, task_col].dropna()
    raw = sorted(
        {
            _deviations_gantt_like_task_label(x)
            for x in ser.tolist()
            if _deviations_gantt_like_task_label(x)
        }
    )
    return _gantt_dedupe_block_filter_values(raw)


def _deviations_mask_by_building_key(
    df: pd.DataFrame, sel_building: str
) -> pd.Series | None:
    """Маска строк с «Строение» = выбранному значению (как в детальной таблице)."""
    if df is None or getattr(df, "empty", True) or "_dt_lvl3_key" not in df.columns:
        return None
    s_raw = _clean_display_str(sel_building)
    if not s_raw or s_raw.lower() in ("все",):
        return None
    s_g = _deviations_gantt_like_task_label(s_raw) or s_raw
    col = df["_dt_lvl3_key"].map(_clean_display_str)
    col_g = col.map(_deviations_gantt_like_task_label)
    return (col == s_raw) | (col == s_g) | (col_g == s_g)


def _deviations_filter_df_under_l3_building(
    df: pd.DataFrame,
    sel_building: str,
) -> pd.DataFrame:
    """Срез по строению: сначала ``_dt_lvl3_key`` (как в таблице), иначе поддерево L3."""
    if df is None or getattr(df, "empty", True):
        return df
    s_raw = str(sel_building).strip()
    if not s_raw or s_raw.lower() in ("", "все", "nan", "none"):
        return df
    work = df
    if "_dt_lvl3_key" not in work.columns:
        work = _deviations_maket_attach_ancestor_keys(work.copy())
    _key_mask = _deviations_mask_by_building_key(work, s_raw)
    if _key_mask is not None and bool(_key_mask.any()):
        return work.loc[_key_mask].copy()
    p = _deviations_plot_df_plan_rows_like_gantt(work)
    lc = _deviations_resolve_level_col_like_gantt(p) if not p.empty else None
    tc = _deviations_resolve_task_col(p) if not p.empty else None
    if not lc or not tc or lc not in work.columns or tc not in work.columns:
        return work.iloc[0:0].copy()
    s_key = _deviations_gantt_like_task_label(s_raw) or s_raw
    work = work.reset_index(drop=True)
    _ln = pd.to_numeric(work[lc], errors="coerce")
    _nm = work[tc].map(_deviations_gantt_like_task_label)
    _mask = (_ln == 3) & (_nm.astype(str).str.strip() == str(s_key).strip())
    if not bool(_mask.any()):
        return work.iloc[0:0].copy()
    _pos = np.flatnonzero(_mask.to_numpy())
    _start = int(_pos.min())
    _end = len(work)
    for _pp in range(_start + 1, len(work)):
        _lv = _ln.iloc[_pp]
        if pd.notna(_lv) and int(_lv) <= 3:
            _end = _pp
            break
    return work.iloc[_start:_end].copy()

def _deviations_apply_block_building_filters(
    filtered_df: pd.DataFrame,
    selected_block: str,
    selected_building: str,
    building_col,
):
    """
    Функциональный блок и строение: приоритетно поля MSP (как «График проекта»),
    иначе уровни outline (2/3), затем плоский block/section и колонка строения.
    """
    if filtered_df is None or getattr(filtered_df, "empty", True):
        return filtered_df

    msp_blk_col, msp_blk_vals = _deviations_msp_gantt_style_block_meta(filtered_df)
    msp_bld_col = _deviations_msp_gantt_style_building_col(filtered_df)

    level_col = _deviations_effective_level_col(filtered_df)
    task_col = (
        "task name"
        if "task name" in filtered_df.columns
        else _dev_tasks_find_column(
            filtered_df, ["Задача", "task", "Task Name", "Название"]
        )
    )
    use_hierarchy = bool(level_col and task_col and task_col in filtered_df.columns)

    use_msp_block = bool(
        msp_blk_col and msp_blk_vals and msp_blk_col in filtered_df.columns
    )

    if use_msp_block or (msp_bld_col and msp_bld_col in filtered_df.columns):
        out = filtered_df.copy()
        if use_msp_block and selected_block != "Все":
            out = out[_gantt_block_series_eq_selected(out[msp_blk_col], selected_block)].copy()
        if selected_building != "Все":
            if use_hierarchy and _deviations_l3_building_option_labels(
                out, level_col, task_col
            ):
                return _deviations_filter_df_under_l3_building(
                    out, selected_building
                )
            if msp_bld_col and msp_bld_col in out.columns:
                out = out[
                    out[msp_bld_col].astype(str).str.strip()
                    == str(selected_building).strip()
                ].copy()
            elif use_hierarchy:
                _ln_fb = _dev_outline_level_numeric(out[level_col])
                _blv, _bdv = _deviations_msp_tier_levels(_ln_fb)
                wh = _dev_tasks_build_ancestor_keys(
                    out,
                    level_col,
                    task_col,
                    block_outline_level=_blv,
                    building_outline_level=_bdv,
                )
                wh = wh[
                    wh["_dt_lvl3_key"].astype(str).str.strip()
                    == str(selected_building).strip()
                ]
                return _drop_deviation_hierarchy_artifacts(wh)
            elif building_col and building_col in out.columns:
                out = out[
                    out[building_col].astype(str).str.strip()
                    == str(selected_building).strip()
                ].copy()
        return out

    if use_hierarchy:
        _ln_fb = _dev_outline_level_numeric(filtered_df[level_col])
        _blv, _bdv = _deviations_msp_tier_levels(_ln_fb)
        wh = _dev_tasks_build_ancestor_keys(
            filtered_df,
            level_col,
            task_col,
            block_outline_level=_blv,
            building_outline_level=_bdv,
        )
        if selected_block != "Все":
            wh = wh[_gantt_block_series_eq_selected(wh["_dt_lvl2_key"], selected_block)]
        if selected_building != "Все":
            if _deviations_l3_building_option_labels(wh, level_col, task_col):
                sub = _deviations_filter_df_under_l3_building(
                    wh, selected_building
                )
                return _drop_deviation_hierarchy_artifacts(sub)
            wh = wh[
                wh["_dt_lvl3_key"].astype(str).str.strip()
                == str(selected_building).strip()
            ]
        return _drop_deviation_hierarchy_artifacts(wh)
    out = filtered_df
    use_flat = (
        task_col
        and task_col in out.columns
        and "block" in out.columns
        and "section" in out.columns
        and not use_hierarchy
    )
    if use_flat:
        if selected_block != "Все":
            sb = str(selected_block).strip()
            if _DEVIATIONS_FLAT_FB_SEP in sb:
                parts = sb.split(_DEVIATIONS_FLAT_FB_SEP, 1)
                if len(parts) == 2:
                    blk, sec = parts[0].strip(), parts[1].strip()
                    out = out[_gantt_block_series_eq_selected(out["block"], blk)]
                    out = out[out["section"].astype(str).str.strip() == sec]
            elif "block" in out.columns:
                out = out[_gantt_block_series_eq_selected(out["block"], sb)]
        if selected_building != "Все":
            out = out[out[task_col].astype(str).str.strip() == str(selected_building).strip()]
        return out
    if selected_block != "Все" and "block" in out.columns:
        out = out[_gantt_block_series_eq_selected(out["block"], selected_block)]
    if (
        selected_building != "Все"
        and building_col
        and building_col in out.columns
    ):
        out = out[
            out[building_col].astype(str).str.strip()
            == str(selected_building).strip()
        ]
    return out


def _deviations_project_slice_by_key(df: pd.DataFrame, state_key: str) -> pd.DataFrame:
    """Срез по выбранному проекту (ключ session_state) — для списков блока/строения."""
    pr = st.session_state.get(state_key, "Все")
    if pr != "Все" and df is not None and "project name" in df.columns:
        mask = _project_norm_key_filter_mask(df["project name"], pr)
        return df[mask].copy()
    return df.copy() if df is not None else df


def _project_norm_key_filter_mask(series: pd.Series, selected_label) -> pd.Series:
    """True для строк, чей project name совпадает с выбранной подписью (в т.ч. «Дмитровский» / «Дмитровский-1»)."""
    sel_k = _project_filter_norm_key(selected_label)
    if not sel_k:
        return pd.Series(True, index=series.index)
    msp_keys = {sel_k}
    rk = series.map(_project_filter_norm_key)
    return rk.map(lambda k: _project_norm_key_matches_msp_keys(k, msp_keys))


def _deviations_filter_df_by_project_name(
    df: pd.DataFrame, selected_label
) -> pd.DataFrame:
    """Фильтр по колонке `project name` с тем же нормализованным ключом, что и в селектах."""
    if df is None or getattr(df, "empty", True) or "project name" not in df.columns:
        return df
    if selected_label is None or str(selected_label).strip() in ("", "Все"):
        return df
    mask = _project_norm_key_filter_mask(df["project name"], selected_label)
    return df[mask].copy()


def _filter_df_by_norm_key_col(df: pd.DataFrame, col: str, selected_label) -> pd.DataFrame:
    """Сравнение по `_project_filter_norm_key` для произвольной строковой колонки (проект/и т.п.)."""
    if not col or col not in getattr(df, "columns", []):
        return df
    if selected_label is None or str(selected_label).strip() in ("", "Все"):
        return df
    sel_k = _project_filter_norm_key(selected_label)
    if not sel_k:
        return df
    return df[df[col].map(_project_filter_norm_key) == sel_k].copy()


def _is_generic_block_name(v) -> bool:
    """Шаблонные имена вроде «Блок 1», «Block 3», «Суммарная задача» — не ур.2 MSP."""
    s = str(v).strip().lower()
    if not s:
        return True
    if "суммар" in s and "задач" in s:
        return True
    if s in ("summary task", "summary"):
        return True
    return bool(re.match(r"^(блок|block)\s*[-_a-zа-я]*\d+$", s))


def _gantt_collect_physical_block_filter_values(
    d: pd.DataFrame,
    level_col: str | None,
    task_col: str | None,
) -> list[str]:
    """Физические блоки MSP (ур. 3): только «Блок B (… m2)», без «Блок B» и без «ЗЕМЛЯ»."""
    if d is None or getattr(d, "empty", True):
        return []
    if not level_col or not task_col or level_col not in d.columns or task_col not in d.columns:
        return []

    filter_tier = _gantt_resolve_block_filter_tier(d, level_col, task_col)
    ln = pd.to_numeric(d[level_col], errors="coerce")
    names: list[str] = [
        _deviations_gantt_like_task_label(x)
        for x in d.loc[ln == float(filter_tier), task_col].dropna().astype(str).tolist()
    ]
    names = [x for x in names if x and not _is_generic_block_name(x)]
    if not names:
        _wk = _dev_tasks_build_ancestor_keys(d.copy(), level_col, task_col)
        _key_col = _gantt_block_ancestor_key_col(d, level_col, task_col)
        for x in _wk[_key_col].dropna().astype(str).tolist():
            n = _deviations_gantt_like_task_label(x)
            if n and not _is_generic_block_name(n) and _gantt_is_physical_block_label(n):
                names.append(n)
    else:
        names = [x for x in names if _gantt_is_physical_block_label(x)]
    return _gantt_dedupe_block_filter_values(names)


def _gantt_norm_block_label(v) -> str:
    t = str(v).replace("\ufeff", "").replace("\u00a0", " ").replace("\u202f", " ").replace("\u2007", " ")
    t = re.sub(r"\s+", " ", t).strip()
    t = re.sub(r"m²|m2|м2", "m2", t, flags=re.I)
    return t


def _gantt_block_cmp_key(v) -> str:
    """Ключ сравнения: пробелы, регистр, латиница/кириллица (B/В, A/А …)."""
    t = _gantt_norm_block_label(v).casefold()
    for cyr, lat in (
        ("а", "a"), ("б", "b"), ("в", "b"), ("г", "g"), ("д", "d"), ("е", "e"),
        ("ё", "e"), ("ж", "zh"), ("з", "z"), ("и", "i"), ("й", "y"), ("к", "k"),
        ("л", "l"), ("м", "m"), ("н", "n"), ("о", "o"), ("п", "p"), ("р", "r"),
        ("с", "c"), ("т", "t"), ("у", "u"), ("ф", "f"), ("х", "x"), ("ц", "c"),
        ("ч", "ch"), ("ш", "sh"), ("щ", "sch"), ("ъ", ""), ("ы", "y"), ("ь", ""),
        ("э", "e"), ("ю", "yu"), ("я", "ya"),
    ):
        t = t.replace(cyr, lat)
    return t


def _gantt_block_stem_key(v) -> str:
    """Как `_gantt_block_cmp_key`, но с лёгким стеммингом мн./ед. числа (тендеры → тендер)."""
    k = _gantt_block_cmp_key(v)
    if len(k) > 4 and not k.endswith(")") and k[-1] in ("y", "i"):
        return k[:-1]
    return k


def _gantt_block_series_eq_selected(series: pd.Series, selected) -> pd.Series:
    """Маска строк, чьё значение блока совпадает с `selected` без учёта регистра/числа
    (совместимо с дедупом опций «Функциональный блок»: Тендер ↔ ТЕНДЕРЫ)."""
    sel_key = _gantt_block_stem_key(selected)
    if not sel_key:
        return pd.Series(True, index=series.index)
    return series.astype(str).str.strip().map(_gantt_block_stem_key) == sel_key


def _gantt_prefer_block_label(candidate: str, current: str) -> bool:
    """True, если `candidate` лучше подходит для отображения, чем уже выбранный `current`."""
    c_upper = candidate.isupper()
    cur_upper = current.isupper()
    if c_upper != cur_upper:
        return not c_upper
    return len(candidate) < len(current)


def _gantt_dedupe_block_filter_values(values: list[str]) -> list[str]:
    """Уникальные подписи блока без дублей «Блок B» + «Блок B (… м2)» и без
    дублей по регистру/числу («ТЕНДЕРЫ» / «Тендер», «ФИНАНСЫ» / «Финансы»)."""
    order: list[str] = []
    canon: dict[str, str] = {}
    for v in values or []:
        n = _gantt_norm_block_label(v)
        if not n or n.lower() in ("nan", "none"):
            continue
        key = _gantt_block_stem_key(n)
        if key not in canon:
            canon[key] = n
            order.append(key)
        elif _gantt_prefer_block_label(n, canon[key]):
            canon[key] = n
    normed = [canon[k] for k in order]
    drop: set[str] = set()
    for a in normed:
        a_ck = _gantt_block_cmp_key(a)
        for b in normed:
            if a == b:
                continue
            b_ck = _gantt_block_cmp_key(b)
            if len(b_ck) <= len(a_ck):
                continue
            if (
                b_ck.startswith(a_ck + " (")
                or b_ck.startswith(a_ck + "(")
                or b_ck.startswith(a_ck + " ")
            ):
                drop.add(a)
                break
        if a in drop:
            continue
        if "(" not in a and ")" not in a and re.match(r"^(блок|block)\s+\S+$", a, re.I):
            for b in normed:
                if a == b or b in drop:
                    continue
                if "(" in b and _gantt_block_cmp_key(b).startswith(a_ck):
                    drop.add(a)
                    break
    return sorted(v for v in normed if v not in drop)


def _gantt_is_physical_block_label(v) -> bool:
    """Подпись похожа на физический блок (Блок B (… м2), АСЦ …), а не фазу СМР/ИРД."""
    s = _gantt_norm_block_label(v)
    if not s:
        return False
    ck = _gantt_block_cmp_key(s)
    if re.search(r"\([\d\s.,]+(?:m2|sq)", ck):
        return True
    if ck.startswith("asc") or ck.startswith("ac "):
        return True
    if ck.startswith("kpp"):
        return True
    if "moyka" in ck:
        return True
    if ck.startswith("zavod") or "(2000 m2)" in ck:
        return True
    return False


def _gantt_resolve_block_filter_tier(
    d: pd.DataFrame,
    level_col: str | None,
    task_col: str | None,
) -> int:
    """Уровень MSP для селекта «Функциональный блок»: фаза (2) или физ. блок (3)."""
    if d is None or getattr(d, "empty", True) or not level_col or level_col not in d.columns:
        return 2
    ln = pd.to_numeric(d[level_col], errors="coerce")
    blk_tier, bld_tier = _deviations_msp_tier_levels(ln)
    if not task_col or task_col not in d.columns:
        return blk_tier

    def _tier_names(tier: int) -> list[str]:
        t = d[ln == float(tier)]
        if t.empty:
            return []
        return [
            _deviations_gantt_like_task_label(x)
            for x in t[task_col].dropna().astype(str).tolist()
        ]

    l2n = _tier_names(blk_tier)
    l3n = _tier_names(bld_tier)
    phys2 = sum(1 for x in l2n if _gantt_is_physical_block_label(x))
    phys3 = sum(1 for x in l3n if _gantt_is_physical_block_label(x))
    if phys3 >= 2 and phys3 > phys2:
        return bld_tier
    if phys2 >= 1:
        return blk_tier
    if l3n and not l2n:
        return bld_tier
    return blk_tier


def _gantt_block_tier_frame(
    d: pd.DataFrame,
    level_col: str | None,
    *,
    tier_level: int | None = None,
) -> pd.DataFrame:
    """Строки уровня «функциональный блок» MSP — источник списка фильтра."""
    if d is None or getattr(d, "empty", True) or not level_col or level_col not in d.columns:
        return d
    ln = pd.to_numeric(d[level_col], errors="coerce")
    if not ln.notna().any():
        return d
    use_tier = tier_level
    if use_tier is None:
        blk_tier, _ = _deviations_msp_tier_levels(ln)
        use_tier = blk_tier
    tier = d[ln == float(use_tier)]
    return tier if not tier.empty else d


def _gantt_block_ancestor_key_col(
    d: pd.DataFrame,
    level_col: str | None,
    task_col: str | None,
) -> str:
    """Колонка ancestor-keys для фильтра по функциональному блоку (уровень фазы, не строения)."""
    return "_dt_lvl2_key"


def _gantt_supplement_block_filter_l2_branches(
    d: pd.DataFrame,
    block_vals: list[str],
    *,
    level_col: str | None = None,
    task_col: str | None = None,
) -> list[str]:
    """Дополняет «БЛОК» задачами ур.2 с другим именем (напр. «Вехи СМР» при block=«СМР»)."""
    out = list(block_vals or [])
    if (
        d is None
        or getattr(d, "empty", True)
        or not level_col
        or level_col not in d.columns
        or not task_col
        or task_col not in d.columns
    ):
        return _gantt_dedupe_block_filter_values(out)
    seen = {_gantt_block_cmp_key(v) for v in out}
    ln = pd.to_numeric(d[level_col], errors="coerce")
    blk_tier, _ = _deviations_msp_tier_levels(ln)
    block_col = _deviations_msp_sched_col(d, ["block", "БЛОК", "Блок"])
    tier = d.loc[ln == float(blk_tier)]
    extra: list[str] = []
    for _, row in tier.iterrows():
        name = _deviations_gantt_like_task_label(row[task_col])
        if not name or _is_generic_block_name(name):
            continue
        name_key = _gantt_block_cmp_key(name)
        if name_key in seen:
            continue
        blk_raw = row[block_col] if block_col and block_col in row.index else None
        blk = (
            _deviations_gantt_like_task_label(blk_raw)
            if blk_raw is not None and str(blk_raw).strip()
            else ""
        )
        if blk and _gantt_block_cmp_key(blk) == name_key:
            continue
        extra.append(name)
        seen.add(name_key)
    return _gantt_dedupe_block_filter_values(out + extra)


def _gantt_block_filter_values_for_df(
    d: pd.DataFrame,
    *,
    level_col: str | None = None,
    task_col: str | None = None,
) -> list[str]:
    """Значения селекта «Функциональный блок» — MSP Block / section, не L3 «Строение»."""
    _col, vals = _deviations_msp_gantt_style_block_meta(d)
    if vals and _col and _col in d.columns and level_col and level_col in d.columns:
        ln = pd.to_numeric(d[level_col], errors="coerce")
        if ln.notna().any():
            blk_tier, _ = _deviations_msp_tier_levels(ln)
            _tier_blk = (
                d.loc[ln == float(blk_tier), _col]
                .dropna()
                .astype(str)
                .map(lambda x: _gantt_norm_block_label(str(x).strip()))
            )
            _tier_vals = sorted(
                {
                    x
                    for x in _tier_blk.tolist()
                    if x and x.lower() not in ("nan", "none") and not _is_generic_block_name(x)
                }
            )
            if _tier_vals:
                vals = _tier_vals
            _phase = [v for v in vals if not _gantt_is_physical_block_label(v)]
            _phys = [v for v in vals if _gantt_is_physical_block_label(v)]
            if _phase and _phys:
                vals = _phase
    if vals:
        return _gantt_supplement_block_filter_l2_branches(
            d, vals, level_col=level_col, task_col=task_col
        )
    if (
        d is None
        or getattr(d, "empty", True)
        or not level_col
        or level_col not in d.columns
        or not task_col
        or task_col not in d.columns
    ):
        return []
    ln = pd.to_numeric(d[level_col], errors="coerce")
    blk_tier, _ = _deviations_msp_tier_levels(ln)
    names = [
        _deviations_gantt_like_task_label(x)
        for x in d.loc[ln == float(blk_tier), task_col].dropna().astype(str).tolist()
    ]
    names = [x for x in names if x and not _is_generic_block_name(x)]
    if names:
        return _gantt_dedupe_block_filter_values(sorted(names))
    _wk = _dev_tasks_build_ancestor_keys(d.copy(), level_col, task_col)
    if "_dt_lvl2_key" in _wk.columns:
        _k2 = _wk["_dt_lvl2_key"].astype(str).str.strip()
        _k2 = _k2[_k2.ne("") & _k2.str.lower().ne("nan")]
        _k2_list = sorted({x for x in _k2.tolist() if not _is_generic_block_name(x)})
        if _k2_list:
            return _gantt_dedupe_block_filter_values(_k2_list)
    return []


def _gantt_building_filter_values_for_df(
    d: pd.DataFrame,
    *,
    level_col: str | None = None,
    task_col: str | None = None,
    building_col: str | None = None,
) -> list[str]:
    """Значения селекта «Строение» по текущему срезу (проект + блок), без дублей."""
    if d is None or getattr(d, "empty", True):
        return []
    raw: list[str] = []
    bld_tier = 3
    tier_mask: pd.Series | None = None
    if level_col and level_col in d.columns:
        ln = pd.to_numeric(d[level_col], errors="coerce")
        if ln.notna().any():
            _, bld_tier = _deviations_msp_tier_levels(ln)
            tier_mask = ln == float(bld_tier)

    if task_col and task_col in d.columns and tier_mask is not None and bool(tier_mask.any()):
        for x in d.loc[tier_mask, task_col].dropna().astype(str).tolist():
            name = _deviations_gantt_like_task_label(x)
            if name and name.lower() not in ("nan", "none"):
                raw.append(name)

    if building_col and building_col in d.columns:
        src = d.loc[tier_mask] if tier_mask is not None and bool(tier_mask.any()) else d
        for x in src[building_col].dropna().astype(str).tolist():
            s = _gantt_norm_block_label(str(x).strip())
            if s and s.lower() not in ("nan", "none"):
                raw.append(s)

    if not raw:
        return []
    return _gantt_dedupe_block_filter_values(raw)


def _deviations_building_keys_with_deviations(work: pd.DataFrame):
    """Множество подписей «Строение» из детальной таблицы макета (как в UI).

    Возвращает:
    - set(label) — строения, которые реально видны в макете отклонений;
    - set() — отклонений нет;
    - None — макет есть, но колонка строения не построена (fallback на структуру).
    """
    if work is None or getattr(work, "empty", True):
        return set()
    try:
        maket = _deviations_maket_scope_df(work)
    except Exception:
        return None
    if maket is None or getattr(maket, "empty", True):
        return set()
    if "_dt_lvl3_key" not in maket.columns:
        return None
    # Как в таблице: _clean_display_str, без gantt-нормализации, иначе
    # «Завершение СМР» / «Блок U1.U2.» выпадают при пересечении со структурой L3.
    keys = {
        _clean_display_str(x)
        for x in maket["_dt_lvl3_key"].dropna().astype(str).tolist()
    }
    return {k for k in keys if k}


def _deviations_scope_building_opts_to_deviations(opts: list[str], dev_keys) -> list[str]:
    """Опции «Строение»: приоритет — подписи из макета (детальная таблица)."""
    if dev_keys is None:
        return opts
    if not dev_keys:
        return []
    # Источник истины — строения из детальной таблицы. Пересечение со списком
    # узлов level==3 структуры отбрасывало «Завершение СМР» (level=5,
    # level structure=3 под Ковенантами) и оставляло только «Общие работы».
    return _gantt_dedupe_block_filter_values(sorted(dev_keys))


def _deviations_scope_col_building_opts_to_deviations(
    src: pd.DataFrame, opts: list[str], col: str | None
) -> list[str]:
    """Сузить опции «Строение» (значения MSP-колонки) до тех, что есть в макете отклонений.

    Пустой макет → [] (строения фильтровать не по чему). Колонка не найдена в макете →
    исходный список. Иначе — только значения, встречающиеся в строках макета.
    """
    if not opts:
        return opts
    try:
        maket = _deviations_maket_scope_df(src)
    except Exception:
        return opts
    if maket is None or getattr(maket, "empty", True):
        return []
    if not col or col not in maket.columns:
        return opts
    vals = {
        str(v).strip()
        for v in maket[col].dropna().astype(str).str.strip().tolist()
        if str(v).strip() and str(v).strip().lower() not in ("nan", "none", "nat")
    }
    return [o for o in opts if str(o).strip() in vals]


def _deviations_building_select_options(
    df_full: pd.DataFrame,
    *,
    project_state_key: str = "devcombo_project",
    block_state_key: str = "devcombo_block",
    period_session_key: str = "devcombo_period_range",
    reason_session_key: str = "devcombo_reason",
    building_col: str | None = None,
) -> list[str]:
    """Список строений (L3) по срезу проект+блок — только те, под которыми есть отклонения (макет: ур.5, причина, отклонение < 0)."""
    # period/reason оставлены в сигнатуре для совместимости вызовов — на опции не влияют.
    _ = period_session_key, reason_session_key
    if df_full is None or getattr(df_full, "empty", True):
        return []
    if building_col is None:
        building_col = _find_deviations_building_column(df_full)
    work = df_full.copy()
    if "project name" in work.columns:
        work = _project_column_apply_canonical(work, "project name")
    work = _deviations_maket_attach_ancestor_keys(work)
    sel_proj = st.session_state.get(project_state_key, "Все")
    if sel_proj != "Все" and "project name" in work.columns:
        work = _deviations_filter_df_by_project_name(work, sel_proj)
    sel_block = st.session_state.get(block_state_key, "Все")
    # У «Ковенантов» в срезе блока часто нет L3 — список строений по проекту целиком.
    _is_cov_block = (
        str(sel_block).strip() != "Все"
        and any(
            tok in str(sel_block).lower()
            for tok in ("ковенант", "ковен", "covenant", "coven")
        )
    )
    if not _is_cov_block:
        work = _deviations_apply_block_building_filters(
            work, sel_block, "Все", building_col
        )
    if work.empty:
        return []

    # Сначала строения из детальной таблицы макета (в т.ч. «Завершение СМР»).
    dev_keys = _deviations_building_keys_with_deviations(work)
    if dev_keys:
        return _gantt_dedupe_block_filter_values(sorted(dev_keys))
    if dev_keys is not None:
        # Макет пуст по строениям — не подставляем всю структуру проекта.
        return []

    level_col = _deviations_resolve_level_col_like_gantt(work)
    task_col = _deviations_resolve_task_col(work)
    if level_col and task_col:
        opts = _deviations_l3_building_option_labels(work, level_col, task_col)
        if opts:
            return opts

    return _gantt_building_filter_values_for_df(
        work,
        level_col=level_col,
        task_col=task_col,
        building_col=(
            building_col if building_col and building_col in work.columns else None
        ),
    )


def _deviations_render_building_selectbox(
    options: list[str],
    *,
    state_key: str,
    label: str = "Строение",
) -> None:
    """Селект «Строение»; при пустом списке — всё равно «Все» (колонка не пропадает)."""
    opts = [x for x in (options or []) if str(x).strip()]
    full = ["Все"] + opts
    cur = st.session_state.get(state_key, "Все")
    if cur not in full:
        st.session_state[state_key] = "Все"
    st.selectbox(label, full, key=state_key)


def _deviations_filter_df_by_period_range(
    filtered_df: pd.DataFrame, range_key: str
) -> pd.DataFrame:
    """Срез по календарному диапазону из session_state (plan end / plan_month / snapshot_date)."""
    _dr = st.session_state.get(range_key)
    if isinstance(_dr, tuple) and len(_dr) == 2:
        _p_start, _p_end = _dr[0], _dr[1]
    elif hasattr(_dr, "year"):
        _p_start = _p_end = _dr
    else:
        return filtered_df
    _start_dt = pd.to_datetime(_p_start, errors="coerce")
    _end_dt = pd.to_datetime(_p_end, errors="coerce")
    if pd.isna(_start_dt) or pd.isna(_end_dt):
        return filtered_df
    if _start_dt > _end_dt:
        _start_dt, _end_dt = _end_dt, _start_dt
    _start_day = _start_dt.normalize()
    _end_day = _end_dt.normalize() + pd.Timedelta(days=1) - pd.Timedelta(nanoseconds=1)
    if "plan end" in filtered_df.columns:
        _pe = _deviations_coerce_datetime(filtered_df["plan end"])
        _mask = _pe.notna()
        if _mask.any():
            # Срез по фактической дате (день), а не по месяцу: иначе выбор 05.05/19.05
            # внутри мая давал бы тот же результат, что и весь месяц — число отклонений
            # не пересчитывалось бы.
            _pe_day = _pe.loc[_mask]
            _keep = (_pe_day >= _start_day) & (_pe_day <= _end_day)
            out_mask = pd.Series(False, index=filtered_df.index)
            out_mask.loc[_mask] = _keep
            return filtered_df[out_mask].copy()
    if "plan_month" in filtered_df.columns:
        _pm = filtered_df["plan_month"]
        _pf = _start_dt.to_period("M")
        _pt = _end_dt.to_period("M")
        return filtered_df[
            _pm.notna() & (_pm >= _pf) & (_pm <= _pt)
        ].copy()
    if "snapshot_date" in filtered_df.columns:
        _sd = pd.to_datetime(filtered_df["snapshot_date"], errors="coerce")
        _mask = _sd.notna()
        if not _mask.any():
            return filtered_df
        _sd_day = _sd.loc[_mask]
        _keep = (_sd_day >= _start_day) & (_sd_day <= _end_day)
        out_mask = pd.Series(False, index=filtered_df.index)
        out_mask.loc[_mask] = _keep
        return filtered_df[out_mask].copy()
    return filtered_df


def _deviations_period_range_key(session_key: str) -> Optional[str]:
    """Ключ календарного диапазона «Период» для «Причины отклонений»; иначе None."""
    sk = str(session_key or "").strip()
    if sk in ("devcombo_period_range", "devcombo_period_month"):
        return "devcombo_period_range"
    if sk in ("reason_period_range", "reason_period_month"):
        return "reason_period_range"
    return None


def _deviations_period_calendar_bounds(
    df: pd.DataFrame,
) -> tuple[Optional[date], Optional[date]]:
    """Мин/макс дат для календаря «Период» (plan end, иначе snapshot_date)."""
    if df is None or getattr(df, "empty", True):
        return None, None
    if "plan end" in df.columns:
        pe = _deviations_coerce_datetime(df["plan end"]).dropna()
        if not pe.empty:
            return pe.min().date(), pe.max().date()
    if "snapshot_date" in df.columns:
        sd = pd.to_datetime(df["snapshot_date"], errors="coerce").dropna()
        if not sd.empty:
            return sd.min().date(), sd.max().date()
    if "plan_month" in df.columns:
        pm = df["plan_month"].dropna()
        if not pm.empty:
            try:
                periods = pd.PeriodIndex(pm)
                return periods.min().start_time.date(), periods.max().end_time.date()
            except Exception:
                pass
    return None, None


def _deviations_migrate_month_list_to_date_range(
    st: Any,
    *,
    month_key: str,
    range_key: str,
    min_value: Optional[date],
    max_value: Optional[date],
) -> None:
    """Старый multiselect месяцев → календарный диапазон (один раз)."""
    if not hasattr(st, "session_state"):
        return
    if range_key in st.session_state:
        st.session_state.pop(month_key, None)
        return
    raw = st.session_state.get(month_key)
    periods: list = []
    if isinstance(raw, str):
        s = raw.strip()
        if s and s not in ("", "Все месяцы"):
            p = _deviations_filter_month_string_to_period(s)
            if p is not None:
                periods.append(p)
    elif isinstance(raw, list):
        for lbl in raw:
            p = _deviations_filter_month_string_to_period(lbl)
            if p is not None:
                periods.append(p)
    st.session_state.pop(month_key, None)
    if not periods:
        return
    periods = sorted(periods, key=lambda p: int(p.ordinal))
    try:
        start = periods[0].start_time.date()
        end = periods[-1].end_time.date()
    except Exception:
        return
    if min_value is not None and start < min_value:
        start = min_value
    if max_value is not None and end > max_value:
        end = max_value
    if start > end:
        start, end = end, start
    st.session_state[range_key] = (start, end)


def _deviations_render_period_calendar(
    st: Any,
    df: pd.DataFrame,
    *,
    range_key: str = "devcombo_period_range",
    month_key: Optional[str] = None,
) -> tuple[Optional[date], Optional[date]]:
    """Календарь диапазона дат для фильтра «Период» (как на БДДС)."""
    min_d, max_d = _deviations_period_calendar_bounds(df)
    if min_d is None or max_d is None:
        # Колонка «Период» не должна пропадать из сетки фильтров.
        st.selectbox("Период", ["Все"], key=f"{range_key}__empty_placeholder")
        return None, None
    if month_key:
        _deviations_migrate_month_list_to_date_range(
            st,
            month_key=month_key,
            range_key=range_key,
            min_value=min_d,
            max_value=max_d,
        )
    return period_date_range_input(
        st,
        range_key,
        min_value=min_d,
        max_value=max_d,
        default=(min_d, max_d),
        help=(
            "Календарный диапазон по дате окончания плана (можно захватить несколько месяцев). "
            "Выберите начало и конец периода в календаре."
        ),
    )


def _deviations_snapshot_month_sort_key(label: str) -> tuple:
    if str(label or "").strip() in ("", "Все месяцы"):
        return (0, 0)
    p = _deviations_filter_month_string_to_period(label)
    if p is not None:
        return (1, int(p.ordinal))
    return (2, str(label))


def _msp_snapshot_month_labels(
    df: pd.DataFrame, *, descending: bool = False
) -> list[str]:
    """Месяцы выгрузки MSP (snapshot_date).

    При descending=True: от текущего месяца к более ранним
    (июль → июнь → май…), затем будущие месяцы (если есть в данных).
    """
    if df is None or getattr(df, "empty", True) or "snapshot_date" not in df.columns:
        return []
    sd = pd.to_datetime(df["snapshot_date"], errors="coerce")
    periods = sd.dropna().dt.to_period("M").unique()
    labels = sorted(
        {format_period_ru(p) for p in periods if pd.notna(p)},
        key=_deviations_snapshot_month_sort_key,
        reverse=bool(descending),
    )
    if not descending or not labels:
        return labels
    try:
        cur = pd.Period(pd.Timestamp.today().normalize(), freq="M")
    except Exception:
        return labels
    past_or_now: list[str] = []
    future: list[str] = []
    for lbl in labels:
        p = _deviations_filter_month_string_to_period(lbl)
        if p is not None and int(p.ordinal) > int(cur.ordinal):
            future.append(lbl)
        else:
            past_or_now.append(lbl)
    # past_or_now уже по убыванию; future — по возрастанию (ближайшее будущее первым)
    future_asc = sorted(future, key=_deviations_snapshot_month_sort_key)
    return past_or_now + future_asc


def _deviations_snapshot_month_labels(df: pd.DataFrame) -> list[str]:
    return _msp_snapshot_month_labels(df, descending=False)


def _deviations_snapshot_month_options(df: pd.DataFrame) -> list[str]:
    """Совместимость: список месяцев + «Все месяцы» (legacy selectbox)."""
    labels = _deviations_snapshot_month_labels(df)
    return (["Все месяцы"] + labels) if labels else []


def _deviations_migrate_period_month_multiselect_state(
    st: Any, key: str, month_labels: list[str]
) -> None:
    """Пустой список = все месяцы; миграция со старого selectbox / календаря."""
    try:
        raw = st.session_state.get(key)
        # После календаря «Причины отклонений» в ключе мог остаться tuple дат —
        # multiselect падает, график ПД/РД «пропадает».
        if raw is not None and not isinstance(raw, (list, str)):
            st.session_state[key] = []
            raw = []
        if isinstance(raw, str):
            s = raw.strip()
            opts = {str(x).strip() for x in month_labels if str(x).strip()}
            if s in ("", "Все месяцы"):
                st.session_state[key] = []
            elif s in opts:
                st.session_state[key] = [s]
            else:
                st.session_state[key] = []
    except Exception:
        pass
    migrate_gdrs_month_multiselect_state(st, key, month_labels)


def _deviations_selected_upload_month_periods(session_key: str) -> list:
    """Выбранные месяцы выгрузки MSP из session_state; [] — все месяцы."""
    raw = st.session_state.get(session_key, [])
    if isinstance(raw, str):
        s = raw.strip()
        if s in ("", "Все месяцы"):
            return []
        p = _deviations_filter_month_string_to_period(s)
        return [p] if p is not None else []
    if not isinstance(raw, list):
        return []
    out: list = []
    seen: set = set()
    for lbl in raw:
        p = _deviations_filter_month_string_to_period(lbl)
        if p is not None and int(p.ordinal) not in seen:
            seen.add(int(p.ordinal))
            out.append(p)
    return out


def _deviations_filter_snapshots_by_upload_months(
    snap_part: pd.DataFrame,
    selected_periods: list,
) -> pd.DataFrame:
    """Последний снимок на (проект × месяц выгрузки) для выбранных месяцев."""
    if snap_part is None or getattr(snap_part, "empty", True) or not selected_periods:
        return snap_part.iloc[0:0].copy() if snap_part is not None else pd.DataFrame()
    out = snap_part.copy()
    out["_dev_upload_month"] = out["snapshot_date"].dt.to_period("M")
    out = out[out["_dev_upload_month"].isin(selected_periods)].copy()
    if out.empty:
        return out
    if "project name" in out.columns:
        latest = out.groupby(
            ["project name", "_dev_upload_month"], dropna=False
        )["snapshot_date"].transform("max")
    else:
        latest = out.groupby("_dev_upload_month")["snapshot_date"].transform("max")
    out = out[out["snapshot_date"] == latest]
    return out.drop(columns=["_dev_upload_month"], errors="ignore")


def _deviations_apply_snapshot_month_filter(
    df: pd.DataFrame,
    *,
    session_key: str = "devcombo_period_range",
    dynamics: bool = False,
) -> pd.DataFrame:
    """
    Срез «Период»:
    - «Причины отклонений»: дедуп снимков + календарный диапазон дат;
    - ПД/РД и прочие: multiselect месяцев выгрузки MSP (snapshot_date).
    """
    if df is None or getattr(df, "empty", True):
        return df

    range_key = _deviations_period_range_key(session_key)
    if range_key is not None:
        out = df
        if "snapshot_date" in df.columns:
            from web_loader import (
                _deduplicate_project_snapshots,
                _deduplicate_project_snapshots_last_per_month,
            )

            if dynamics:
                out = _deduplicate_project_snapshots_last_per_month(df)
            else:
                out = _deduplicate_project_snapshots(df)
        return _deviations_filter_df_by_period_range(out, range_key)

    selected_periods = _deviations_selected_upload_month_periods(session_key)
    if "snapshot_date" not in df.columns:
        return df

    from web_loader import (
        _deduplicate_project_snapshots,
        _deduplicate_project_snapshots_last_per_month,
    )

    if not selected_periods:
        if dynamics:
            return _deduplicate_project_snapshots_last_per_month(df)
        return _deduplicate_project_snapshots(df)

    out = df.copy()
    out["snapshot_date"] = pd.to_datetime(out["snapshot_date"], errors="coerce")
    has_snap = out["snapshot_date"].notna()
    if "project name" in out.columns:
        has_snap = has_snap & out["project name"].notna()
    if not has_snap.any():
        return out

    snap_part = out[has_snap].copy()
    no_snap_part = out[~has_snap].copy()
    snap_part = _deviations_filter_snapshots_by_upload_months(
        snap_part, selected_periods
    )
    if snap_part.empty:
        return out.iloc[0:0].copy()
    return pd.concat([no_snap_part, snap_part], ignore_index=True)


_DEV_TIME_AXIS_PLAN = "По дате окончания плана"
_DEV_TIME_AXIS_SNAPSHOT = "По дате снимка выгрузки"

_DEVCOMBO_FILTER_RESET_DEFAULTS = {
    "devcombo_project": "Все",
    "devcombo_block": "Все",
    "devcombo_building": "Все",
    "devcombo_reason": "Все",
    "devcombo_report_period": "Весь период",
    "reason_top5": False,
}


def _deviations_period_type_en_from_ru(label: str) -> str:
    return {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year", "День": "Day"}.get(
        str(label or "Месяц").strip(), "Month"
    )


def _deviations_report_period_options(df: pd.DataFrame, period_type_en: str) -> list[str]:
    if df is None or getattr(df, "empty", True) or "plan end" not in df.columns:
        return []
    pe = _deviations_coerce_datetime(df["plan end"])
    pe = pe[pe.notna()]
    if pe.empty:
        return []
    if period_type_en == "Day":
        vals = pe.dt.date
    elif period_type_en == "Quarter":
        vals = pe.dt.to_period("Q")
    elif period_type_en == "Year":
        vals = pe.dt.to_period("Y")
    else:
        vals = pe.dt.to_period("M")
    today = pd.Timestamp(date.today())
    if period_type_en == "Day":
        cutoff = today.normalize()
        vals = vals[vals <= cutoff]
    elif period_type_en == "Quarter":
        cutoff = today.to_period("Q")
        vals = vals[vals <= cutoff]
    elif period_type_en == "Year":
        cutoff = today.to_period("Y")
        vals = vals[vals <= cutoff]
    else:
        cutoff = today.to_period("M")
        vals = vals[vals <= cutoff]
    labels = [format_period_ru(v) for v in pd.unique(vals)]
    labels = [x for x in labels if str(x).strip()]
    return sorted(set(labels), key=lambda s: str(s))


def _deviations_apply_reason_filter(
    df: pd.DataFrame, *, session_key: str = "devcombo_reason"
) -> pd.DataFrame:
    if df is None or getattr(df, "empty", True):
        return df
    sel = str(st.session_state.get(session_key, "Все") or "Все").strip()
    if sel == "Все" or "reason of deviation" not in df.columns:
        return df
    return df[
        df["reason of deviation"].astype(str).str.strip() == sel
    ].copy()


def _deviations_apply_report_period_filter(
    df: pd.DataFrame, *, period_type_en: str
) -> pd.DataFrame:
    if df is None or getattr(df, "empty", True):
        return df
    sel = str(st.session_state.get("devcombo_report_period", "Весь период") or "Весь период").strip()
    if sel in ("", "Весь период") or "plan end" not in df.columns:
        return df
    out = df.copy()
    pe = _deviations_coerce_datetime(out["plan end"])
    mask = pe.notna()
    if period_type_en == "Day":
        temp = pe.dt.date
    elif period_type_en == "Quarter":
        temp = pe.dt.to_period("Q")
    elif period_type_en == "Year":
        temp = pe.dt.to_period("Y")
    else:
        temp = pe.dt.to_period("M")
    out.loc[mask, "_dev_report_period_lbl"] = temp.loc[mask].map(format_period_ru)
    out = out[out["_dev_report_period_lbl"].astype(str).str.strip() == sel].copy()
    return out.drop(columns=["_dev_report_period_lbl"], errors="ignore")

def _apply_deviations_combined_filters(
    df: pd.DataFrame, *, building_col=None
) -> pd.DataFrame:
    """Фильтры «Причины отклонений» из session_state (devcombo_*) без отрисовки виджетов."""
    if df is None or getattr(df, "empty", True):
        return df
    if building_col is None:
        building_col = _find_deviations_building_column(df)
    filtered_df = df.copy()
    if "project name" in filtered_df.columns:
        filtered_df = _project_column_apply_canonical(filtered_df, "project name")
    filtered_df = _deviations_maket_attach_ancestor_keys(filtered_df)
    selected_project = (
        st.session_state.get("devcombo_project", "Все")
        if "project name" in filtered_df.columns
        else "Все"
    )
    selected_block = st.session_state.get("devcombo_block", "Все")
    selected_building = st.session_state.get("devcombo_building", "Все")

    if selected_project != "Все" and "project name" in filtered_df.columns:
        filtered_df = _deviations_filter_df_by_project_name(
            filtered_df, selected_project
        )
    filtered_df = _deviations_apply_block_building_filters(
        filtered_df, selected_block, selected_building, building_col
    )

    filtered_df = _deviations_apply_snapshot_month_filter(filtered_df, dynamics=False)
    # «Причина» не режем здесь: вкладка «Доли причин» должна показывать распределение
    # по всем причинам проекта. Фильтр причины — в динамике и в детальной таблице.
    _pt_en = _deviations_period_type_en_from_ru(
        st.session_state.get("dynamics_period", "Месяц")
    )
    filtered_df = _deviations_apply_report_period_filter(
        filtered_df, period_type_en=_pt_en
    )

    return filtered_df


def _apply_deviations_dynamics_filters(
    df: pd.DataFrame, *, building_col=None
) -> pd.DataFrame:
    """Фильтры динамики: проект/блок/строение/причина + дедуп снимков под ось времени."""
    if df is None or getattr(df, "empty", True):
        return df
    if building_col is None:
        building_col = _find_deviations_building_column(df)
    filtered_df = df.copy()
    if "project name" in filtered_df.columns:
        filtered_df = _project_column_apply_canonical(filtered_df, "project name")
    selected_project = (
        st.session_state.get("devcombo_project", "Все")
        if "project name" in filtered_df.columns
        else "Все"
    )
    selected_block = st.session_state.get("devcombo_block", "Все")
    selected_building = st.session_state.get("devcombo_building", "Все")

    if selected_project != "Все" and "project name" in filtered_df.columns:
        filtered_df = _deviations_filter_df_by_project_name(
            filtered_df, selected_project
        )
    filtered_df = _deviations_apply_block_building_filters(
        filtered_df, selected_block, selected_building, building_col
    )
    filtered_df = _deviations_apply_reason_filter(filtered_df)
    # Ось «по plan end» (по умолчанию) — только актуальный снимок, как «Доли причин».
    # «По дате снимка» — последний файл каждого месяца выгрузки (история).
    _time_axis = str(
        st.session_state.get("dynamics_time_axis_combo")
        or st.session_state.get("dynamics_time_axis_pravki")
        or _DEV_TIME_AXIS_PLAN
    )
    _hist_snapshots = str(_time_axis).startswith("По дате снимка")
    filtered_df = _deviations_apply_snapshot_month_filter(
        filtered_df, dynamics=_hist_snapshots
    )
    return filtered_df


def _deviations_dynamics_source_df() -> pd.DataFrame:
    """Все MSP-снимки (до среза по месяцу выгрузки в фильтре «Период»)."""
    snap = st.session_state.get("project_data_all_snapshots")
    if snap is None or getattr(snap, "empty", True):
        return pd.DataFrame()
    out = snap.copy()
    ensure_msp_hierarchy_columns(out)
    if "project name" in out.columns:
        out = _project_column_apply_canonical(out, "project name")
    return out


def _render_deviations_combined_shared_filters(df):
    ensure_msp_hierarchy_columns(df)
    inject_unified_filters_css(st)
    building_col = _find_deviations_building_column(df)
    level_col = _deviations_effective_level_col(df)
    task_col = (
        "task name"
        if "task name" in df.columns
        else _dev_tasks_find_column(df, ["Задача", "task", "Task Name", "Название"])
    )
    use_hierarchy = bool(level_col and task_col and task_col in df.columns)
    use_flat_bs = _deviations_use_flat_block_section_task(df)

    with filters_panel(
        st,
        panel_key="deviations_combined",
        expanded=False,
        reset_keys=["devcombo_"],
        reset_defaults=_DEVCOMBO_FILTER_RESET_DEFAULTS,
    ):
        with filters_selectors(st):
            col1, col2, col3, col4, col5 = st.columns(5, gap="small")
            with col1:
                if "project name" in df.columns:
                    projects = ["Все"] + _project_name_select_options(df["project name"])
                    _session_reset_project_if_excluded(
                        "devcombo_project", allowed_labels=projects
                    )
                    st.selectbox("Проект", projects, key="devcombo_project")
            with col2:
                df_opts = _deviations_project_slice_by_key(df, "devcombo_project")
                msp_blk_col_dc, msp_blk_vals_dc = _deviations_msp_gantt_style_block_meta(
                    df_opts
                )
                block_opts = ["Все"]
                if msp_blk_vals_dc and msp_blk_col_dc:
                    block_opts = ["Все"] + list(msp_blk_vals_dc)
                elif use_hierarchy:
                    _ln_opts = _dev_outline_level_numeric(df_opts[level_col])
                    _blv, _bdv = _deviations_msp_tier_levels(_ln_opts)
                    wh = _dev_tasks_build_ancestor_keys(
                        df_opts.copy(),
                        level_col,
                        task_col,
                        block_outline_level=_blv,
                        building_outline_level=_bdv,
                    )
                    ln = _dev_outline_level_numeric(wh[level_col])
                    _raw_l2 = (
                        wh.loc[ln == _blv, task_col]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .unique()
                        .tolist()
                    )
                    _raw_l2 = [x for x in _raw_l2 if x and not _is_generic_block_name(x)]
                    block_opts = ["Все"] + _gantt_dedupe_block_filter_values(_raw_l2)
                    if len(block_opts) <= 1 and "_dt_lvl2_key" in wh.columns:
                        _k2c = wh["_dt_lvl2_key"].astype(str).str.strip()
                        _k2c = _k2c[_k2c.ne("") & _k2c.str.lower().ne("nan")]
                        if len(_k2c):
                            _k2c_list = [
                                x
                                for x in pd.unique(_k2c).tolist()
                                if not _is_generic_block_name(x)
                            ]
                            block_opts = ["Все"] + _gantt_dedupe_block_filter_values(
                                _k2c_list
                            )
                elif use_flat_bs:
                    fb_opts = _deviations_flat_functional_block_options(df_opts)
                    fb_opts = [
                        x for x in fb_opts if x == "Все" or not _is_generic_block_name(x)
                    ]
                    block_opts = ["Все"] + _gantt_dedupe_block_filter_values(
                        [x for x in fb_opts if x != "Все"]
                    )
                elif "block" in df.columns:
                    blocks_raw = sorted(
                        df["block"].dropna().astype(str).str.strip().unique().tolist()
                    )
                    blocks_raw = [x for x in blocks_raw if not _is_generic_block_name(x)]
                    block_opts = ["Все"] + _gantt_dedupe_block_filter_values(blocks_raw)
                _cur_block = str(
                    st.session_state.get("devcombo_block", "Все") or "Все"
                ).strip()
                if _cur_block not in block_opts:
                    st.session_state["devcombo_block"] = "Все"
                with st.container(key="devcombo_block_wrap"):
                    st.selectbox(
                        LABEL_BLOCK,
                        block_opts,
                        key="devcombo_block",
                    )
            with col3:
                _snap_bld = st.session_state.get("project_data_all_snapshots")
                _df_bld = (
                    _snap_bld.copy()
                    if _snap_bld is not None and not getattr(_snap_bld, "empty", True)
                    else df.copy()
                )
                if _df_bld is not df:
                    ensure_msp_hierarchy_columns(_df_bld)
                _bld_opts = _deviations_building_select_options(
                    _df_bld,
                    building_col=building_col,
                )
                _deviations_render_building_selectbox(
                    _bld_opts, state_key="devcombo_building"
                )
    
            _snap_period = st.session_state.get("project_data_all_snapshots")
            _df_period_src = _snap_period if (
                _snap_period is not None and not getattr(_snap_period, "empty", True)
            ) else df

            with col4:
                _deviations_render_period_calendar(
                    st,
                    _df_period_src,
                    range_key="devcombo_period_range",
                    month_key="devcombo_period_month",
                )

            with col5:
                if "reason of deviation" in df.columns:
                    _df_reason_opts = _deviations_project_slice_by_key(
                        df, "devcombo_project"
                    )
                    _reason_vals = (
                        _df_reason_opts["reason of deviation"]
                        .dropna()
                        .astype(str)
                        .str.strip()
                    )
                    _reason_vals = _reason_vals[
                        _reason_vals.ne("")
                        & ~_reason_vals.str.lower().isin(["nan", "none", "null"])
                    ]
                    _reason_opts = ["Все"] + sorted(_reason_vals.unique().tolist())
                    _cur_reason = str(
                        st.session_state.get("devcombo_reason", "Все") or "Все"
                    ).strip()
                    if _cur_reason not in _reason_opts:
                        st.session_state["devcombo_reason"] = "Все"
                    st.selectbox("Причина", _reason_opts, key="devcombo_reason")
                else:
                    suppress_caption("Нет колонки причин отклонений")

            # Правки по ТЗ (скриншот): убраны селекторы «Группировать по» (сегментация
            # по кварталу/году), дублирующий «Период», «Ось времени» и «Вид отображения».
            # Фиксируем значения по умолчанию для нижестоящей логики вкладок: помесячная
            # группировка, отчёт за весь период, ось по дате окончания плана, доли по причинам.
            st.session_state["dynamics_period"] = "Месяц"
            st.session_state["devcombo_report_period"] = "Весь период"
            st.session_state["dynamics_time_axis_combo"] = _DEV_TIME_AXIS_PLAN
            st.session_state["reasons_view_type"] = "По причинам"
        with filters_toggles(st):
            st.checkbox(
                "ТОП 5 причин отклонений",
                value=False,
                key="reason_top5",
            )
        # Линия тренда убрана по ТЗ (скриншот) — фиксируем выключенной.
        st.session_state["reasons_dynamics_show_trend_line"] = False
    _snap_for_filter = st.session_state.get("project_data_all_snapshots")
    if _snap_for_filter is not None and not getattr(_snap_for_filter, "empty", True):
        _sf = _snap_for_filter.copy()
        ensure_msp_hierarchy_columns(_sf)
        if "project name" in _sf.columns:
            _sf = _project_column_apply_canonical(_sf, "project name")
        if building_col is None:
            building_col = _find_deviations_building_column(_sf)
        _sf = _deviations_maket_attach_ancestor_keys(_sf)
        filtered_df = _apply_deviations_combined_filters(_sf, building_col=building_col)
    else:
        filtered_df = _apply_deviations_combined_filters(df, building_col=building_col)

    return filtered_df, building_col


def dashboard_deviations_combined(df):

    """Единый отчёт по отклонениям с табами (макет правок: общий заголовок «Причины отклонений»)."""
    if df is None or not hasattr(df, "columns") or df.empty:
        st.warning(
            "Нет данных для отображения. Пожалуйста, загрузите данные проекта."
        )
        return

    filtered_shared, building_col = _render_deviations_combined_shared_filters(df)
    suppress_caption(
        "Категории в диаграммах и таблицах приведены к перечню из последних правок по отчёту "
        "(стек долей, легенда и детальная таблица)."
    )
    tab_by_month, tab_reasons = st.tabs(
        [
            "Доли причин отклонений по проекту",
            "Динамика причин отклонений по месяцам",
        ]
    )

    # R23-04 add-on (стр.11): при выборе узкого диапазона «Период»
    # (например, январь–сентябрь) в подвкладках иногда падал traceback — если данных
    # за период нет совсем или они частичные. По ТЗ: «нет совсем — написать об этом;
    # есть частично — показать то, что есть». Оборачиваем каждую подвкладку в общий
    # обработчик: пустой срез → дружелюбное info, иначе — штатная логика, а любые
    # непредвиденные исключения ловим и печатаем аккуратно, без сырого traceback.
    def _render_tab_safe(render_func, frame, *, tab_label: str, **kwargs):
        _hide = bool(kwargs.get("hide_shared_filters"))
        if frame is None or getattr(frame, "empty", True):
            if _hide and render_func is dashboard_dynamics_of_deviations:
                try:
                    render_func(frame, **kwargs)
                    return
                except Exception as _e:  # noqa: BLE001
                    st.warning(
                        f"Не удалось построить подвкладку «{tab_label}» для выбранного периода: {_e}. "
                        "Если данных за часть диапазона нет — расширьте «Период», "
                        "или снимите сужающие фильтры."
                    )
                    return
            st.info(
                "За выбранный период нет данных по отклонениям. "
                "Поменяйте «Период» или фильтры «Проект / Функциональный блок / Строение»."
            )
            return
        try:
            render_func(frame, **kwargs)
        except Exception as _e:  # noqa: BLE001
            st.warning(
                f"Не удалось построить подвкладку «{tab_label}» для выбранного периода: {_e}. "
                "Если данных за часть диапазона нет — расширьте «Период», "
                "или снимите сужающие фильтры."
            )

    with tab_by_month:
        _render_tab_safe(
            dashboard_reasons_of_deviation,
            filtered_shared,
            tab_label="Доли причин отклонений по проекту",
            hide_shared_filters=True,
            building_col=building_col,
        )
    with tab_reasons:
        _render_tab_safe(
            dashboard_dynamics_of_deviations,
            df,
            tab_label="Динамика причин отклонений по месяцам",
            hide_shared_filters=True,
        )


def dashboard_reasons_of_deviation(df, hide_shared_filters=False, building_col=None):
    # Проверка на None или пустой DataFrame
    if df is None:
        st.warning(
            "Нет данных для отображения. Пожалуйста, загрузите данные проекта."
        )
        return

    # Проверка, что df является DataFrame и имеет атрибут columns
    if not hasattr(df, "columns") or df.empty:
        st.warning(
            "Нет данных для отображения. Пожалуйста, загрузите данные проекта."
        )
        return

    ensure_msp_hierarchy_columns(df)
    if "project name" in df.columns:
        df = _project_column_apply_canonical(df.copy(), "project name")
    if not hide_shared_filters:
        df = _deviations_maket_attach_ancestor_keys(df)

    # При hide_shared_filters фильтры задаются в общем блоке; локальные selectbox не рисуются — задаём значения по умолчанию.
    selected_project = "Все"

    if building_col is None:
        building_col = _find_deviations_building_column(df)
    if hide_shared_filters:
        snap = st.session_state.get("project_data_all_snapshots")
        if snap is not None and not getattr(snap, "empty", True):
            _snap_df = snap.copy()
            ensure_msp_hierarchy_columns(_snap_df)
            if "project name" in _snap_df.columns:
                _snap_df = _project_column_apply_canonical(_snap_df, "project name")
            if building_col is None or (
                building_col not in getattr(_snap_df, "columns", [])
            ):
                building_col = _find_deviations_building_column(_snap_df)
            _snap_df = _deviations_maket_attach_ancestor_keys(_snap_df)
            df = _apply_deviations_combined_filters(_snap_df, building_col=building_col)

    if not hide_shared_filters:
        st.header("Доли причин отклонений по проекту")

        _lvl_rs = _deviations_effective_level_col(df)
        _task_rs = (
            "task name"
            if "task name" in df.columns
            else _dev_tasks_find_column(
                df, ["Задача", "task", "Task Name", "Название"]
            )
        )
        _use_hi_rs = bool(_lvl_rs and _task_rs and _task_rs in df.columns)
        _use_flat_rs = _deviations_use_flat_block_section_task(df)

        with filters_panel(st, reset_keys=[
            "reason_project", "reason_block", "reason_building",
            "reason_period_range", "reason_period_month",
        ]):
            col1, col2, col3, col4 = st.columns(4, gap="small")

            with col1:
                try:
                    has_project_column = "project name" in df.columns
                except (AttributeError, TypeError):
                    has_project_column = False

                if has_project_column:
                    projects = ["Все"] + _project_name_select_options(df["project name"])
                    _session_reset_project_if_excluded(
                        "reason_project", allowed_labels=projects
                    )
                    selected_project = st.selectbox("Проект", projects, key="reason_project")
                else:
                    selected_project = "Все"

            with col2:
                df_opts = _deviations_project_slice_by_key(df, "reason_project")
                msp_blk_col_r, msp_blk_vals_r = _deviations_msp_gantt_style_block_meta(df_opts)
                if msp_blk_vals_r and msp_blk_col_r:
                    st.selectbox(
                        "Функциональный блок",
                        ["Все"] + msp_blk_vals_r,
                        key="reason_block",
                    )
                elif _use_hi_rs:
                    _ln_rs = _dev_outline_level_numeric(df_opts[_lvl_rs])
                    _blv_rs, _bdv_rs = _deviations_msp_tier_levels(_ln_rs)
                    wh = _dev_tasks_build_ancestor_keys(
                        df_opts.copy(),
                        _lvl_rs,
                        _task_rs,
                        block_outline_level=_blv_rs,
                        building_outline_level=_bdv_rs,
                    )
                    ln = _dev_outline_level_numeric(wh[_lvl_rs])
                    block_opts = ["Все"] + sorted(
                        wh.loc[ln == _blv_rs, _task_rs]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .unique()
                        .tolist()
                    )
                    if len(block_opts) <= 1 and "_dt_lvl2_key" in wh.columns:
                        _k2r = wh["_dt_lvl2_key"].astype(str).str.strip()
                        _k2r = _k2r[_k2r.ne("") & _k2r.str.lower().ne("nan")]
                        if len(_k2r):
                            block_opts = ["Все"] + sorted(pd.unique(_k2r).tolist())
                    st.selectbox(
                        "Функциональный блок",
                        block_opts,
                        key="reason_block",
                    )
                elif _use_flat_rs:
                    fb_opts_rs = _deviations_flat_functional_block_options(df_opts)
                    st.selectbox(
                        "Функциональный блок",
                        fb_opts_rs,
                        key="reason_block",
                    )
                elif "block" in df.columns:
                    blocks = ["Все"] + sorted(
                        df["block"].dropna().astype(str).str.strip().unique().tolist()
                    )
                    st.selectbox("Функциональный блок", blocks, key="reason_block")
                else:
                    suppress_caption("Нет колонки блока")

            with col3:
                _snap_bld_r = st.session_state.get("project_data_all_snapshots")
                _df_bld_r = (
                    _snap_bld_r.copy()
                    if _snap_bld_r is not None and not getattr(_snap_bld_r, "empty", True)
                    else df.copy()
                )
                if _df_bld_r is not df:
                    ensure_msp_hierarchy_columns(_df_bld_r)
                _bld_opts_r = _deviations_building_select_options(
                    _df_bld_r,
                    project_state_key="reason_project",
                    block_state_key="reason_block",
                    period_session_key="reason_period_range",
                    reason_session_key="reason_reason",
                    building_col=building_col,
                )
                _deviations_render_building_selectbox(
                    _bld_opts_r, state_key="reason_building"
                )

            with col4:
                _snap_reason = st.session_state.get("project_data_all_snapshots")
                _df_reason_period = _snap_reason if (
                    _snap_reason is not None and not getattr(_snap_reason, "empty", True)
                ) else df
                _deviations_render_period_calendar(
                    st,
                    _df_reason_period,
                    range_key="reason_period_range",
                    month_key="reason_period_month",
                )
    else:
        pass

    filtered_df = df.copy()

    try:
        has_project_col = "project name" in filtered_df.columns
    except (AttributeError, TypeError):
        has_project_col = False

    if not hide_shared_filters:
        _snap_standalone = st.session_state.get("project_data_all_snapshots")
        if _snap_standalone is not None and not getattr(_snap_standalone, "empty", True):
            filtered_df = _snap_standalone.copy()
            ensure_msp_hierarchy_columns(filtered_df)
            if "project name" in filtered_df.columns:
                filtered_df = _project_column_apply_canonical(filtered_df, "project name")
            filtered_df = _deviations_maket_attach_ancestor_keys(filtered_df)
        if selected_project != "Все" and has_project_col:
            filtered_df = _deviations_filter_df_by_project_name(
                filtered_df, selected_project
            )
        filtered_df = _deviations_apply_block_building_filters(
            filtered_df,
            st.session_state.get("reason_block", "Все"),
            st.session_state.get("reason_building", "Все"),
            building_col,
        )
        filtered_df = _deviations_apply_snapshot_month_filter(
            filtered_df, session_key="reason_period_range", dynamics=False
        )

    # ТЗ (макет): диаграммы и таблица — один набор строк (ур. 5, причина, отклонение < 0).
    _table_source_df = filtered_df.copy()
    maket_df = _deviations_maket_scope_df(filtered_df)
    if maket_df.empty:
        st.info(
            "По макету нет строк: уровень 5, непустая причина, отклонение окончания < 0."
        )
        return
    filtered_df = maket_df
    _maket_n = len(maket_df)
    suppress_caption(
        f"Диаграммы и детальная таблица: {_maket_n} задач "
        "(ур. 5, причина, отклонение окончания < 0)."
    )

    if hide_shared_filters:
        top5_only = bool(st.session_state.get("reason_top5", False))
    else:
        top5_only = st.checkbox(
            "ТОП 5 причин отклонений",
            value=False,
            key="reason_top5",
        )

    # Summary metrics: основная причина и доля (метрика «Всего задач» убрана по правкам макета)
    has_reason_col_metric = "reason of deviation" in filtered_df.columns
    main_reason_name = "—"
    main_reason_pct = 0.0
    main_reason_count = 0
    if has_reason_col_metric and not filtered_df.empty:
        reason_counts = filtered_df["reason of deviation"].value_counts()
        if not reason_counts.empty:
            main_reason_name = str(reason_counts.index[0]).strip() or "—"
            main_reason_count = int(reason_counts.iloc[0])
            _nr = (
                filtered_df["reason of deviation"].notna()
                & (
                    filtered_df["reason of deviation"].astype(str).str.strip() != ""
                )
            )
            total_reason_rows = int(_nr.sum())
            main_reason_pct = (
                (main_reason_count / total_reason_rows * 100)
                if total_reason_rows
                else 0.0
            )

    m1, m2 = st.columns(2, gap="small")
    with m1:
        st.metric("Основная причина отклонения", main_reason_name[:50] + ("…" if len(main_reason_name) > 50 else ""))
    with m2:
        col3_value = f"{main_reason_pct:.1f}% ({main_reason_count})" if (has_reason_col_metric and main_reason_count > 0) else "—"
        st.metric("Доля основной причины", col3_value)

    # Reasons breakdown
    try:
        has_reason_col_breakdown = "reason of deviation" in filtered_df.columns
    except (AttributeError, TypeError):
        has_reason_col_breakdown = False

    if has_reason_col_breakdown:
        reason_counts = filtered_df["reason of deviation"].value_counts().reset_index()
        reason_counts.columns = ["Причина", "Количество"]
        total_rc = float(reason_counts["Количество"].sum()) or 1.0
        reason_counts["pct"] = (reason_counts["Количество"] / total_rc * 100).round(1)
        if top5_only:
            reason_counts = reason_counts.nlargest(5, "Количество").reset_index(drop=True)
        # ТЗ: над столбцом одна строка «число (доля %)», как на круговой диаграмме.
        reason_counts["label_bar"] = reason_counts.apply(
            lambda r: f"{int(r['Количество'])} ({r['pct']}%)", axis=1
        )

        _ax_clr = _fin_chart_axis_color()
        _lbl_clr = _fin_chart_label_color()

        fig = px.bar(
            reason_counts,
            x="Причина",
            y="Количество",
            title=None,
            labels={
                "Причина": "Причина отклонения",
                "Количество": "Количество",
            },
            text="label_bar",
        )
        fig.update_traces(
            textposition="outside", textfont=dict(size=28, color=_lbl_clr)
        )
        fig = _apply_finance_bar_label_layout(fig)
        fig = _apply_vertical_category_bar_width(fig)
        fig = apply_chart_background(fig)
        _ymax = float(reason_counts["Количество"].max() or 0)
        n = len(reason_counts)
        _bar_h = max(960, int(560 + n * 112))
        # Запас под outside-подписи без «плюс 20» — иначе при малых counts (1–3)
        # столбцы сжимаются к нулю и график выглядит пустым.
        _y_top = max(_ymax * 1.55, _ymax + 1.25, 1.0)
        _gdrs_rc = _plotly_bargaps_sparse_x_like_gdrs(n)
        _ly_rc = dict(
            height=_bar_h,
            margin=dict(l=48, r=28, t=120, b=240 if n > 6 else 168),
            title=dict(
                text="Причины отклонений (за отчетный период)",
                x=0.5,
                xanchor="center",
                font=dict(size=18, color=_ax_clr),
            ),
            yaxis=dict(
                range=[0, _y_top],
                title=dict(text="Количество", standoff=10, font=dict(size=14, color=_ax_clr)),
                automargin=True,
                tickfont=dict(size=13, color=_ax_clr),
                dtick=1 if _ymax <= 8 else None,
            ),
            xaxis=dict(
                title=dict(text="Причина отклонений", standoff=44, font=dict(size=14, color=_ax_clr)),
                automargin=True,
            ),
        )
        if _gdrs_rc:
            _ly_rc.update(_gdrs_rc)
        fig.update_layout(**_ly_rc)
        if n == 1:
            fig.update_traces(width=0.36, selector=dict(type="bar"))
            fig.update_layout(bargap=0.72, bargroupgap=0.22)
        if n > 6:
            fig.update_xaxes(tickangle=-45, ticklabelstandoff=14)
        else:
            fig.update_xaxes(
                tickangle=0,
                tickmode="array",
                tickvals=reason_counts["Причина"].tolist(),
                ticktext=[wrap_label(r, width=15) for r in reason_counts["Причина"].tolist()],
                tickfont=dict(size=14),
                ticklabelstandoff=12,
                overwrite=True,
            )
        render_chart(fig, caption_below="")

        total = reason_counts["Количество"].sum()
        if "pct" not in reason_counts.columns:
            reason_counts["pct"] = (reason_counts["Количество"] / (float(total) or 1.0) * 100).round(1)

        # Круг «Доли причин»: значение+% в секторе; легенда под диаграммой по центру.
        n_reasons = len(reason_counts)
        _pie_h = int(max(640, 540 + min(n_reasons, 28) * 22))
        fig = px.pie(
            reason_counts,
            values="Количество",
            names="Причина",
            title=None,
        )
        fig.update_traces(sort=False, direction="clockwise")
        _pie_font = 22 if n_reasons <= 8 else 20 if n_reasons <= 12 else 18
        fig = apply_standard_pie_layout(
            fig,
            height=_pie_h,
            pct_fontsize=_pie_font,
            text_show_value_and_percent=True,
            extra_layout=dict(font=dict(family="Inter, system-ui, sans-serif")),
        )
        fig.update_traces(
            hovertemplate="<b>%{label}</b><br>Количество: %{value}<br>Доля: %{percent:.1%}<extra></extra>",
        )
        fig.update_traces(
            selector=dict(type="pie"),
            hole=0,
            texttemplate="<b>%{value:.0f}</b> (%{percent:.1%})",
            textinfo="text",
            insidetextorientation="horizontal",
            textposition="auto",
            pull=[0.03] * n_reasons,
            textfont=dict(
                size=max(11, min(_pie_font, 17)),
                color="#ffffff",
                family="Inter, system-ui, Arial, sans-serif",
            ),
            outsidetextfont=dict(
                size=13,
                color=_lbl_clr,
                family="Inter, system-ui, Arial, sans-serif",
            ),
        )
        fig = apply_chart_background(fig)
        fig = _ensure_pie_full_modebar(fig)
        _inject_pie_modebar_zoom_sync()
        render_chart(
            fig,
            caption_below="",
            plotly_config_extra=_PLOTLY_CONFIG_FULL_MODEBAR,
        )

    # Подпись текущего проекта (макет правок); при «Все» не показываем — дублирует фильтр
    if hide_shared_filters:
        _pl = st.session_state.get("devcombo_project", "Все")
        proj_lbl = str(_pl).strip() if _pl != "Все" else ""
    else:
        proj_lbl = (
            str(selected_project).strip()
            if selected_project != "Все"
            else ""
        )
    if proj_lbl:
        _proj_clr = _fin_chart_label_color(dark="#d8dee9", light="#111827")
        st.markdown(
            f"<div style='text-align:right;font-size:2.35rem;font-weight:700;color:{_proj_clr};margin:1rem 0 0 0'>{html_module.escape(proj_lbl)}</div>",
            unsafe_allow_html=True,
        )

    from dashboards.gdrs_theme import gdrs_render_subheader
    from dashboards.light_theme import is_light_preview_active

    gdrs_render_subheader(
        st,
        "Детальные данные",
        theme="light" if is_light_preview_active() else "dark",
    )
    _notes_col_rs = _gantt_resolve_notes_column(_table_source_df)
    _table_maket_df = _deviations_apply_reason_filter(filtered_df)
    _render_deviations_maket_table(
        _table_maket_df,
        building_col,
        notes_col=_notes_col_rs,
        notes_source_df=_table_source_df,
    )



def _deviations_contrast_text_on_fill(fill_hex: str | None) -> str:
    """Цвет подписи внутри сегмента столбца: тёмный на светлой заливке, белый на тёмной."""
    if not fill_hex or not isinstance(fill_hex, str):
        return "#f5f5f5"
    h = fill_hex.strip()
    if not h.startswith("#"):
        return "#f5f5f5"
    h = h[1:]
    try:
        if len(h) == 3:
            r = int(h[0] + h[0], 16)
            g = int(h[1] + h[1], 16)
            b = int(h[2] + h[2], 16)
        elif len(h) == 6:
            r, g, b = int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)
        else:
            return "#f5f5f5"
    except ValueError:
        return "#f5f5f5"
    lum = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255.0
    return "#141414" if lum > 0.62 else "#f5f5f5"


# Порядок снизу вверх в стеке (первая категория — нижний сегмент), как в референсе отчёта.
