def _plan_fact_pick_metric_task_row(
    frame: pd.DataFrame,
    *,
    selected_project: str,
    metric_task: str,
    dates_notes_col,
    dates_milestone_col,
) -> Optional[pd.Series]:
    if frame is None or getattr(frame, "empty", True) or "task name" not in frame.columns:
        return None
    w = frame.copy()
    if selected_project != "Все" and "project name" in w.columns:
        _k = _project_filter_norm_key(selected_project)
        if _k:
            w = w[w["project name"].map(_project_filter_norm_key) == _k]
    if w.empty:
        return None
    mt = (metric_task or "").strip()
    if mt:
        key = mt.casefold()
        tn = w["task name"].astype(str).str.strip()
        cand = w.loc[tn.str.casefold() == key]
        if cand.empty:
            try:
                rx = re.compile(re.escape(mt), flags=re.IGNORECASE)
                cand = w.loc[tn.map(lambda x: bool(rx.search(str(x))))]
            except re.error:
                cand = w.iloc[0:0]
        if not cand.empty:
            return cand.iloc[0]
    if mt and not _plan_fact_zos_task_name_match(mt):
        return None
    cm = _plan_fact_covenant_row_mask(w, dates_notes_col, dates_milestone_col)
    zm = w["task name"].astype(str).map(_plan_fact_zos_task_name_match)
    z = w.loc[cm & zm]
    if not z.empty:
        z = z.copy()
        z["_zos_rank"] = z["task name"].map(_plan_fact_zos_task_rank)
        return z.sort_values("_zos_rank", ascending=True).iloc[0]
    z = w.loc[zm]
    if not z.empty:
        z = z.copy()
        z["_zos_rank"] = z["task name"].map(_plan_fact_zos_task_rank)
        return z.sort_values("_zos_rank", ascending=True).iloc[0]
    return None


def render_plan_fact_dates_metric_plates(
    scope_df: pd.DataFrame,
    *,
    selected_project: str,
    dates_notes_col,
    dates_milestone_col,
) -> None:
    """
    Верхние плашки: максимальное |отклонение окончания| (дней), план/факт окончания проекта
    по задаче из админки `baseline_plan_task_for_metrics` (по умолчанию «ЗОС»).
    """
    nd = "Н/Д"
    metric_task = _plan_fact_resolved_metric_task_name()

    def _one_row_html(
        max_lbl: str,
        plan_lbl: str,
        fact_lbl: str,
        dev_lbl: str,
        project_name: str = "",
        *,
        show_proj_col: bool = False,
        dev_class: str = "",
        max_dev_class: str = "",
    ) -> str:
        max_cls = f" {max_dev_class}" if max_dev_class else ""
        dev_cls = f" {dev_class}" if dev_class else ""
        cells: list[str] = []
        if show_proj_col:
            cells.append(
                f'<div class="pf-kpi-cell"><div class="pf-kpi-lbl">Проект</div>'
                f'<div class="pf-kpi-val pf-kpi-val-proj">'
                f'{html_module.escape(project_name or "—")}</div></div>'
            )
        cells.extend(
            [
                f'<div class="pf-kpi-cell"><div class="pf-kpi-lbl">План окончания проекта</div>'
                f'<div class="pf-kpi-val">{html_module.escape(plan_lbl)}</div></div>',
                f'<div class="pf-kpi-cell"><div class="pf-kpi-lbl">Факт окончания проекта</div>'
                f'<div class="pf-kpi-val">{html_module.escape(fact_lbl)}</div></div>',
                f'<div class="pf-kpi-cell"><div class="pf-kpi-lbl">Отклонение</div>'
                f'<div class="pf-kpi-val{dev_cls}">{html_module.escape(dev_lbl)}</div></div>',
                f'<div class="pf-kpi-cell"><div class="pf-kpi-lbl">Максимальное отклонение (дней)</div>'
                f'<div class="pf-kpi-val{max_cls}">{html_module.escape(max_lbl)}</div></div>',
            ]
        )
        return f'<div class="pf-kpi-row">{"".join(cells)}</div>'

    parts: list[str] = [_plan_fact_kpi_plates_css_for_theme(), '<div class="pf-kpi-wrap">']

    def _row_for_scope(scope: pd.DataFrame) -> tuple[str, str, str, str, str, str]:
        if scope is None or getattr(scope, "empty", True):
            return nd, nd, nd, nd, "", ""
        ensure_date_columns(scope)
        if "plan end" not in scope.columns or "base end" not in scope.columns:
            return nd, nd, nd, nd, "", ""
        pe = pd.to_datetime(scope["plan end"], errors="coerce", dayfirst=True)
        be = pd.to_datetime(scope["base end"], errors="coerce", dayfirst=True)
        both = pe.notna() & be.notna()
        max_lbl = nd
        if bool(both.any()):
            diff_days = ((be - pe).dt.total_seconds() / 86400.0).loc[both]
            try:
                max_lbl = str(int(round(float(diff_days.abs().max()))))
            except (TypeError, ValueError):
                max_lbl = nd
        row = _plan_fact_pick_metric_task_row(
            scope,
            selected_project=selected_project,
            metric_task=metric_task,
            dates_notes_col=dates_notes_col,
            dates_milestone_col=dates_milestone_col,
        )
        plan_lbl = fact_lbl = dev_lbl = nd
        dev_class = max_dev_class = ""
        if row is not None:
            # План = базовое окончание (base end), факт = окончание (plan end).
            plan_lbl = _plan_fact_zos_format_date_cell(row.get("base end"))
            fact_lbl = _plan_fact_zos_format_date_cell(row.get("plan end"))
            plan_lbl = plan_lbl if str(plan_lbl).strip() else nd
            fact_lbl = fact_lbl if str(fact_lbl).strip() else nd
            _pe = pd.to_datetime(row.get("plan end"), errors="coerce", dayfirst=True)
            _be = pd.to_datetime(row.get("base end"), errors="coerce", dayfirst=True)
            if pd.notna(_pe) and pd.notna(_be):
                _dev = (_be - _pe).total_seconds() / 86400.0
                try:
                    dev_lbl = str(int(round(float(_dev))))
                except (TypeError, ValueError):
                    dev_lbl = nd
                dev_class = "pf-kpi-val-late" if _dev < 0 else ("pf-kpi-val-early" if _dev == 0 else "")
                max_dev_class = "pf-kpi-val-late" if _pe > _be else "pf-kpi-val-early"
        return max_lbl, plan_lbl, fact_lbl, dev_lbl, dev_class, max_dev_class

    if scope_df is None or getattr(scope_df, "empty", True):
        parts.append(_one_row_html(nd, nd, nd, nd, max_dev_class=""))
        parts.append("</div>")
        st.markdown("".join(parts), unsafe_allow_html=True)
        return

    w = scope_df.copy()
    if (
        selected_project == "Все"
        and "project name" in w.columns
        and w["project name"].notna().any()
    ):
        _proj_names = sorted(
            {
                str(p).strip()
                for p in w["project name"].dropna().astype(str).tolist()
                if str(p).strip() and str(p).strip().lower() != "nan"
            }
        )
        for _pn in _proj_names:
            _pk = _project_filter_norm_key(_pn)
            _sub = w[w["project name"].map(_project_filter_norm_key) == _pk]
            if _sub.empty:
                continue
            _max, _plan, _fact, _dev, _dev_cls, _max_dev_cls = _row_for_scope(_sub)
            parts.append(
                _one_row_html(
                    _max, _plan, _fact, _dev,
                    project_name=_pn, show_proj_col=True,
                    dev_class=_dev_cls, max_dev_class=_max_dev_cls,
                )
            )
    else:
        _max, _plan, _fact, _dev, _dev_cls, _max_dev_cls = _row_for_scope(w)
        parts.append(
            _one_row_html(_max, _plan, _fact, _dev, dev_class=_dev_cls, max_dev_class=_max_dev_cls)
        )

    parts.append("</div>")
    st.markdown("".join(parts), unsafe_allow_html=True)


def _plan_fact_parent_is_rd_stage(parent_name: str) -> bool:
    """Родитель ур.4 — этап «Рабочая документация» (и специализированные РД-этапы)."""
    s = str(parent_name or "").casefold().replace("ё", "е")
    if "рабоч" not in s or "документ" not in s:
        return False
    if "корректиров" in s:
        return False
    # Чистая ПД без РД — не берём; «проектная и рабочая…» оставляем (есть «рабоч»).
    if "проектная документация" in s and "рабоч" not in s:
        return False
    return True


def _plan_fact_rd_l5_sections_mask(df: pd.DataFrame) -> pd.Series:
    """Ур.5 с шифром ПД/РД под непосредственным родителем «Рабочая документация»."""
    empty = pd.Series(False, index=df.index if df is not None else None)
    if df is None or getattr(df, "empty", True):
        return empty
    hier_col, _outline_col, level_col, name_col, _block_col = _pd_msp_hierarchy_cols(df)
    stack_col = hier_col or level_col
    if not stack_col or stack_col not in df.columns or not name_col or name_col not in df.columns:
        return empty
    _cipher_col, cipher_ok = _pd_cipher_filled_mask(df)
    lv_col = level_col if level_col and level_col in df.columns else stack_col
    lv = pd.to_numeric(df[lv_col], errors="coerce")
    parent_names = _pd_msp_immediate_parent_names(df, stack_col, name_col)
    parent_rd = parent_names.map(_plan_fact_parent_is_rd_stage).fillna(False)
    return lv.eq(5) & cipher_ok.fillna(False) & parent_rd


def _plan_fact_build_rd_deadline_chart_df(scope_df: pd.DataFrame) -> pd.DataFrame:
    """
    Диаграмма «Отклонение от базового плана»: по одной строке на родителя ур.4
    «Рабочая документация» — max «Базовое окончание» и max «Окончание» среди
    дочерних разделов ур.5 с заполненным «Шифр ПД РД».
    """
    cols = [
        "task name",
        "project name",
        "plan end",
        "base end",
        "plan_end_diff",
        "_rd_parent",
    ]
    if scope_df is None or getattr(scope_df, "empty", True):
        return pd.DataFrame(columns=cols)

    work = scope_df.copy()
    ensure_msp_hierarchy_columns(work)
    ensure_date_columns(work)
    if "plan end" not in work.columns or "base end" not in work.columns:
        return pd.DataFrame(columns=cols)
    if "task name" not in work.columns:
        return pd.DataFrame(columns=cols)

    mask = _plan_fact_rd_l5_sections_mask(work)
    if not bool(mask.any()):
        return pd.DataFrame(columns=cols)

    hier_col, _oc, level_col, name_col, _bc = _pd_msp_hierarchy_cols(work)
    stack_col = hier_col or level_col
    parents = _pd_msp_immediate_parent_names(work, stack_col, name_col)
    sub = work.loc[mask].copy()
    sub["_rd_parent"] = parents.loc[mask].astype(str).str.strip()
    sub["plan end"] = pd.to_datetime(sub["plan end"], errors="coerce", dayfirst=True)
    sub["base end"] = pd.to_datetime(sub["base end"], errors="coerce", dayfirst=True)
    # «НД» и прочий мусор уже → NaT; строки без обеих дат не участвуют.
    sub = sub[sub["plan end"].notna() | sub["base end"].notna()].copy()
    if sub.empty:
        return pd.DataFrame(columns=cols)

    if "project name" not in sub.columns:
        sub["project name"] = ""

    rows: list[dict] = []
    group_keys = ["project name", "_rd_parent"]
    for (proj, parent), g in sub.groupby(group_keys, sort=False, dropna=False):
        # Даты — max по колонкам (как «по лоту»); подпись — L5 с самым поздним сроком.
        pe_max = g["plan end"].max()
        be_max = g["base end"].max()
        if pd.isna(pe_max) and pd.isna(be_max):
            continue
        _deadline = pd.concat([g["plan end"], g["base end"]], axis=1).max(
            axis=1, skipna=True
        )
        if _deadline.notna().any():
            pick = g.loc[_deadline.idxmax()]
            label = str(pick.get("task name") or "").strip()
        else:
            label = ""
        if not label:
            label = str(parent or "").strip() or "Рабочая документация"
        dev = np.nan
        if pd.notna(be_max) and pd.notna(pe_max):
            dev = (pd.Timestamp(be_max) - pd.Timestamp(pe_max)).total_seconds() / 86400.0
        rows.append(
            {
                "task name": label,
                "project name": str(proj).strip() if pd.notna(proj) else "",
                "plan end": pe_max,
                "base end": be_max,
                "plan_end_diff": dev,
                "_rd_parent": str(parent or "").strip(),
            }
        )

    if not rows:
        return pd.DataFrame(columns=cols)
    out = pd.DataFrame(rows)
    return out.sort_values("plan_end_diff", ascending=True, na_position="last").reset_index(
        drop=True
    )


# ==================== DASHBOARD 3: Plan/Fact Dates for Tasks ====================
def dashboard_plan_fact_dates(df):
    if df is None or not hasattr(df, "columns") or df.empty:
        st.warning("Нет данных для отображения. Загрузите файл с задачами MSP.")
        return

    # Ручная загрузка (data_loader) раньше не создавала level structure — без этого L2/L3 не работают.
    ensure_msp_hierarchy_columns(df)

    # R23-03: если в выгрузке есть MSP-файлы (`msp_*.csv`) — оставляем только их.
    # Без этого в фильтр «Функциональный блок» и в таблицу утекают строки из
    # синтетических примеров (`sample_project_data_fixed.csv`) c задачами
    # «Блок 1/2/3/4», которые клиент отдельно отмечает как «не должны быть».
    if "__source_file" in df.columns:
        _src_low = df["__source_file"].astype(str).str.lower()
        _is_msp = (
            _src_low.str.startswith("msp_")
            | _src_low.str.contains("/msp_", na=False)
            | _src_low.str.contains(r"\\msp_", na=False, regex=True)
        )
        if bool(_is_msp.any()):
            _before_rows = len(df)
            df = df[_is_msp].copy()
            _dropped = _before_rows - len(df)
            if _dropped > 0:
                suppress_caption(
                    f"В отчёт «Отклонение от базового плана» оставлены только MSP-выгрузки "
                    f"(`msp_*.csv`). Исключено строк из других источников: {_dropped}."
                )
            if df.empty:
                st.warning(
                    "После фильтра MSP-источников не осталось строк. "
                    "Проверьте наличие файлов `msp_*.csv` в активной загрузке."
                )
                return

    if "project name" in df.columns:
        df = _project_column_apply_canonical(df.copy(), "project name")

    # Helper function to find columns by partial match
    def find_column(df, possible_names):
        """Find column by possible names"""
        for col in df.columns:
            # Normalize column name: remove newlines, extra spaces, normalize case
            col_normalized = str(col).replace("\n", " ").replace("\r", " ").strip()
            col_lower = col_normalized.lower()

            for name in possible_names:
                name_lower = name.lower().strip()
                # Exact match (case insensitive)
                if name_lower == col_lower:
                    return col
                # Substring match
                if name_lower in col_lower or col_lower in name_lower:
                    return col
                # Check if all key words from name are in column
                name_words = [w for w in name_lower.split() if len(w) > 2]
                if name_words and all(word in col_lower for word in name_words):
                    return col
        return None

    dates_building_col = _find_deviations_building_column(df)
    dates_pct_col = _find_first_column_matching_keywords(
        df,
        (
            "percent complete",
            "pct complete",
            "% complete",
            "процент выполн",
            "процент_заверш",
            "% выполн",
            "% заверш",
            "физический %",
            "выполн",
            "complete",
            "percent",
        ),
    )
    if dates_pct_col is None:
        dates_pct_col = find_column(
            df,
            [
                "pct complete",
                "% complete",
                "percent complete",
                "% выполнения",
                "Процент выполнения",
                "Процент_завершения",
                "процент заверш",
            ],
        )
    dates_pct_col_resolved = dates_pct_col or find_column(
        df,
        [
            "pct complete",
            "percent complete",
            "Процент_завершения",
            "Процент завершения",
            "% выполнения",
        ],
    )
    dates_notes_col = _find_column_by_keywords(
        df, ("note", "заметк", "comment", "remark", "notes")
    )
    dates_milestone_col = _find_column_by_keywords(
        df, ("milestone", "веха", "контрольная точка", "кп")
    )
    # ТЗ заказчика (скрин 9): «По лоту» — выводить НАЗВАНИЕ лота, а не id.
    # В MSP две колонки: «ЛОТ_ID» (uuid) и «ЛОТ»→«lot» (название). Берём название,
    # id используем только как запасной вариант, если названия нет.
    dates_lot_col = None
    for _lot_name_cand in ("lot", "ЛОТ", "Лот", "lot name", "название лота"):
        if _lot_name_cand in df.columns:
            dates_lot_col = _lot_name_cand
            break
    if dates_lot_col is None:
        for _c in df.columns:
            _cl = str(_c).lower()
            if ("lot" in _cl or "лот" in _cl) and "id" not in _cl.replace("лот", "").replace("lot", ""):
                dates_lot_col = _c
                break
    if dates_lot_col is None:
        dates_lot_col = _find_column_by_keywords(df, ("lot", "лот", "LOT"))
    # Иерархия MSP: предпочтительно outline (level structure), см. web_loader._fill_section_from_task_tree
    plan_fact_dates_outline_col = _dev_tasks_resolve_level_column(df)
    if plan_fact_dates_outline_col is None and "level structure" in df.columns:
        plan_fact_dates_outline_col = "level structure"
    if plan_fact_dates_outline_col is None and "level" in df.columns:
        plan_fact_dates_outline_col = "level"

    with filters_panel(st, reset_keys=[
        "dates_project", "dates_block_l2", "dates_block_section", "dates_block",
        "dates_building_l3", "dates_building", "dates_level",
        "dates_show_reason_notes", "dates_hide_done", "dates_only_covenants",
        "dates_only_neg_end", "dates_tbl_dur", "dates_task_label_mode",
        "dates_reason_bucket_filter",
    ]):
        with filters_selectors(st):
            fl_main1, fl_main2, fl_main3, fl_main4, fl_main5 = st.columns(5, gap="small")
            with fl_main1:
                if "project name" in df.columns:
                    projects = ["Все"] + _project_name_select_options(df["project name"])
                    _session_reset_project_if_excluded(
                        "dates_project", allowed_labels=projects
                    )
                    selected_project = st.selectbox(
                        "Проект",
                        projects,
                        key="dates_project",
                    )
                else:
                    selected_project = "Все"

            pf_dates_proj_df = df.copy()
            if selected_project != "Все" and "project name" in pf_dates_proj_df.columns:
                pf_dates_proj_df = pf_dates_proj_df[
                    pf_dates_proj_df["project name"].map(_project_filter_norm_key)
                    == _project_filter_norm_key(selected_project)
                ]
            pf_dates_proj_df = pf_dates_proj_df.reset_index(drop=True)

            # Как в «График проекта»: списки «Функциональный блок» / «Строение» из полей MSP
            # (block / section / building), а не из имён задач по outline — иначе в фильтр
            # попадают листовые работы («Акт …») при нетипичной нумерации уровней.
            def _pf_dates_norm_colname(s: str) -> str:
                t = (
                    str(s)
                    .replace("\ufeff", "")
                    .replace("\u00a0", " ")
                    .replace("\u202f", " ")
                    .replace("\u2007", " ")
                )
                t = re.sub(r"[\s\t\n\r]+", " ", t).strip().lower()
                return t

            def _pf_dates_sched_col(d: pd.DataFrame, candidates):
                if d is None or getattr(d, "empty", True):
                    return None
                cols_norm = {_pf_dates_norm_colname(c): c for c in d.columns}
                for name in candidates:
                    n = _pf_dates_norm_colname(name)
                    if n in cols_norm:
                        return cols_norm[n]
                return None

            def _pf_dates_col_contains(d, needles, exclude=()):
                if d is None or getattr(d, "empty", True):
                    return None
                ex = tuple(str(x).lower() for x in exclude)
                for c in d.columns:
                    sl = _pf_dates_norm_colname(c)
                    if any(e in sl for e in ex):
                        continue
                    for n in needles:
                        if n.lower() in sl:
                            return c
                return None

            def _pf_dates_is_generic_block_value(v) -> bool:
                return _is_generic_block_name(v)

            _pfd_fb = pf_dates_proj_df
            pf_dates_block_col_msp = _pf_dates_sched_col(_pfd_fb, ["block", "БЛОК", "Блок"])
            pf_dates_block_col_res = (
                pf_dates_block_col_msp
                or _pf_dates_sched_col(_pfd_fb, ["Функциональный блок", "Functional block"])
                or _pf_dates_sched_col(_pfd_fb, ["section", "Раздел"])
            )
            pf_dates_section_col_res = _pf_dates_sched_col(_pfd_fb, ["section", "Раздел", "БЛОК", "блок"])
            pf_dates_building_col_res = (
                _pf_dates_sched_col(
                    _pfd_fb,
                    [
                        "building",
                        "Building",
                        "строение",
                        "Строение",
                        "корпус",
                        "Корпус",
                        "объект",
                        "Объект",
                    ],
                )
                or _pf_dates_col_contains(
                    _pfd_fb,
                    ("строени", "building", "корпус", "объект"),
                    exclude=("приоритет", "риск", "severity"),
                )
            )

            pf_dates_msp_block_filter_col: str | None = None
            pf_dates_msp_block_values: list[str] = []
            if pf_dates_block_col_res and pf_dates_block_col_res in _pfd_fb.columns:
                _raw_b = sorted(
                    _pfd_fb[pf_dates_block_col_res]
                    .dropna()
                    .astype(str)
                    .map(str.strip)
                    .unique()
                    .tolist()
                )
                _raw_b = [b for b in _raw_b if b and b.lower() != "nan"]
                _non_gen = [b for b in _raw_b if not _pf_dates_is_generic_block_value(b)]
                _block_vals = _non_gen if _non_gen else []
                if not pf_dates_block_col_msp:
                    if (
                        (not _non_gen)
                        and pf_dates_section_col_res
                        and pf_dates_section_col_res in _pfd_fb.columns
                        and pf_dates_section_col_res != pf_dates_block_col_res
                    ):
                        _sec_v = (
                            _pfd_fb[pf_dates_section_col_res]
                            .dropna()
                            .astype(str)
                            .map(str.strip)
                        )
                        _sec_u = sorted({s for s in _sec_v.tolist() if s and s.lower() != "nan"})
                        _sec_ng = [s for s in _sec_u if not _pf_dates_is_generic_block_value(s)]
                        if _sec_ng:
                            _block_vals = sorted(_sec_ng)
                            pf_dates_block_col_res = pf_dates_section_col_res
                if _block_vals:
                    pf_dates_msp_block_filter_col = pf_dates_block_col_res
                    pf_dates_msp_block_values = _block_vals

            pf_dates_level_col = _dev_tasks_resolve_level_column(pf_dates_proj_df)
            pf_dates_task_col = (
                "task name"
                if "task name" in pf_dates_proj_df.columns
                else find_column(
                    pf_dates_proj_df,
                    ["Задача", "task", "Task Name", "Название"],
                )
            )
            pf_dates_work_proj = _dev_tasks_build_ancestor_keys(
                pf_dates_proj_df, pf_dates_level_col, pf_dates_task_col
            )
            # Второй и третий ярусы в выгрузке (часто 2 и 3; иначе — по фактическим уровням в файле).
            pf_dates_blk_tier, pf_dates_bld_tier = 2, 3
            if pf_dates_level_col and pf_dates_level_col in pf_dates_work_proj.columns:
                _pf_lv_s = _dev_outline_level_numeric(
                    pf_dates_work_proj[pf_dates_level_col]
                )
                pf_dates_blk_tier, pf_dates_bld_tier = _deviations_msp_tier_levels(_pf_lv_s)

            selected_block_dates = "Все"
            selected_building_dates = "Все"
            pf_dates_block_filter_mode = "none"  # column | l2 | section | block
            pf_dates_block_filter_col: str | None = None
            pf_dates_building_filter_mode = "none"  # column | l3_key
            pf_dates_building_filter_col: str | None = None
            def _pf_is_generic_block_name(v) -> bool:
                return _is_generic_block_name(v)

            with fl_main2:
                if pf_dates_msp_block_values and pf_dates_msp_block_filter_col:
                    pf_dates_block_filter_mode = "column"
                    pf_dates_block_filter_col = pf_dates_msp_block_filter_col
                    blks = ["Все"] + list(pf_dates_msp_block_values)
                    selected_block_dates = st.selectbox(
                        "Функциональный блок",
                        blks,
                        key="dates_block_msp_col",
                    )
                else:
                    hierarchy_ok = (
                        bool(pf_dates_level_col)
                        and bool(pf_dates_task_col)
                        and pf_dates_level_col in pf_dates_work_proj.columns
                    )
                    l2_names: list = []
                    if hierarchy_ok:
                        _ln_b = _dev_outline_level_numeric(
                            pf_dates_work_proj[pf_dates_level_col]
                        )
                        l2_names = sorted(
                            pf_dates_work_proj.loc[
                                _ln_b == float(pf_dates_blk_tier), pf_dates_task_col
                            ]
                            .dropna()
                            .astype(str)
                            .str.strip()
                            .unique()
                            .tolist()
                        )
                        l2_names = [x for x in l2_names if x]
                        l2_names = [x for x in l2_names if not _pf_is_generic_block_name(x)]
                        if not l2_names and "_dt_lvl2_key" in pf_dates_work_proj.columns:
                            _k2 = (
                                pf_dates_work_proj["_dt_lvl2_key"]
                                .astype(str)
                                .str.strip()
                            )
                            _k2 = _k2[_k2.ne("") & _k2.str.lower().ne("nan")]
                            if len(_k2):
                                l2_names = sorted(pd.unique(_k2).tolist())

                    if l2_names:
                        pf_dates_block_filter_mode = "l2"
                        blks = ["Все"] + l2_names
                        selected_block_dates = st.selectbox(
                            "Функциональный блок",
                            blks,
                            key="dates_block_l2",
                        )
                    elif "section" in pf_dates_proj_df.columns:
                        _sec = pf_dates_proj_df["section"].dropna().astype(str).map(str.strip)
                        _sec = _sec[_sec.ne("") & _sec.str.lower().ne("nan")]
                        _uniq = sorted(pd.unique(_sec)) if len(_sec) else []
                        _uniq = [x for x in _uniq if not _pf_is_generic_block_name(x)]
                        if _uniq:
                            pf_dates_block_filter_mode = "section"
                            blks = ["Все"] + list(_uniq)
                            selected_block_dates = st.selectbox(
                                "Функциональный блок",
                                blks,
                                key="dates_block_section",
                            )
                        elif "block" in pf_dates_proj_df.columns:
                            pf_dates_block_filter_mode = "block"
                            blks = ["Все"] + sorted(
                                pf_dates_proj_df["block"]
                                .dropna()
                                .astype(str)
                                .str.strip()
                                .unique()
                                .tolist()
                            )
                            selected_block_dates = st.selectbox(
                                "Функциональный блок",
                                blks,
                                key="dates_block",
                            )
                        else:
                            selected_block_dates = "Все"
                    elif "block" in pf_dates_proj_df.columns:
                        pf_dates_block_filter_mode = "block"
                        blks = ["Все"] + sorted(
                            pf_dates_proj_df["block"]
                            .dropna()
                            .astype(str)
                            .str.strip()
                            .unique()
                            .tolist()
                        )
                        selected_block_dates = st.selectbox(
                            "Функциональный блок",
                            blks,
                            key="dates_block",
                        )
                    else:
                        selected_block_dates = "Все"
            with fl_main3:
                _pfd3 = pf_dates_proj_df
                if (
                    pf_dates_block_filter_mode == "column"
                    and pf_dates_block_filter_col
                    and pf_dates_block_filter_col in _pfd3.columns
                    and str(selected_block_dates).strip() != "Все"
                ):
                    _pfd3 = _pfd3[
                        _pfd3[pf_dates_block_filter_col].astype(str).str.strip()
                        == str(selected_block_dates).strip()
                    ].copy()
                _is_covenant_block_sel = (
                    str(selected_block_dates).strip() != "Все"
                    and any(
                        tok in str(selected_block_dates).lower()
                        for tok in ("ковенант", "ковен", "covenant", "coven")
                    )
                )
                # У «Ковенантов» в срезе нет L3 — список строений строим по проекту целиком.
                _pfd_bld_src = pf_dates_proj_df if _is_covenant_block_sel else _pfd3
                # «Строение»: как в «Причины отклонений» — сначала L3 по plan-строкам ганта,
                # затем MSP-колонка building/Строение; иначе запасные варианты (уровни/outline).
                _l3_b_opts_pf: list[str] = []
                if (
                    pf_dates_level_col
                    and pf_dates_task_col
                    and pf_dates_level_col in _pfd_bld_src.columns
                    and pf_dates_task_col in _pfd_bld_src.columns
                ):
                    _l3_b_opts_pf = _deviations_l3_building_option_labels(
                        _pfd_bld_src, pf_dates_level_col, pf_dates_task_col
                    )
                _msp_bld_pf = _deviations_msp_gantt_style_building_col(_pfd_bld_src)

                # В режиме «Показать причины отклонений» (макет: ур.5, причина,
                # отклонение окончания < 0) список строений ограничиваем теми, под
                # которыми реально есть отклонения. Иначе (обычная детализация) —
                # полная структура проекта.
                _maket_mode_pf = bool(
                    st.session_state.get("dates_show_reason_notes", True)
                )

                if _l3_b_opts_pf:
                    pf_dates_building_filter_mode = "l3_plan_slice"
                    pf_dates_building_filter_col = None
                    _l3_b_opts_show = _l3_b_opts_pf
                    if _maket_mode_pf:
                        _l3_b_opts_show = _deviations_scope_building_opts_to_deviations(
                            _l3_b_opts_pf,
                            _deviations_building_keys_with_deviations(_pfd_bld_src),
                        )
                    bopts = ["Все"] + _l3_b_opts_show
                    selected_building_dates = st.selectbox(
                        "Строение",
                        bopts,
                        key="dates_building_l3_gantt",
                    )
                elif _msp_bld_pf and _msp_bld_pf in _pfd_bld_src.columns:
                    pf_dates_building_filter_mode = "column"
                    pf_dates_building_filter_col = _msp_bld_pf
                    _msp_opts = sorted(
                        _pfd_bld_src[_msp_bld_pf]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .unique()
                        .tolist()
                    )
                    if _maket_mode_pf:
                        _msp_opts = _deviations_scope_col_building_opts_to_deviations(
                            _pfd_bld_src, _msp_opts, _msp_bld_pf
                        )
                    bopts = ["Все"] + _msp_opts
                    selected_building_dates = st.selectbox(
                        "Строение",
                        bopts,
                        key="dates_building_msp_col",
                    )
                elif (
                    pf_dates_building_col_res
                    and pf_dates_building_col_res in _pfd_bld_src.columns
                ):
                    pf_dates_building_filter_mode = "column"
                    pf_dates_building_filter_col = pf_dates_building_col_res
                    _res_opts = sorted(
                        _pfd_bld_src[pf_dates_building_col_res]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .unique()
                        .tolist()
                    )
                    if _maket_mode_pf:
                        _res_opts = _deviations_scope_col_building_opts_to_deviations(
                            _pfd_bld_src, _res_opts, pf_dates_building_col_res
                        )
                    bopts = ["Все"] + _res_opts
                    selected_building_dates = st.selectbox(
                        "Строение",
                        bopts,
                        key="dates_building_msp_res",
                    )
                elif (
                    pf_dates_level_col
                    and pf_dates_task_col
                    and pf_dates_level_col in pf_dates_work_proj.columns
                ):
                    pf_dates_building_filter_mode = "l3_key"
                    pf_dates_building_filter_col = None
                    _ln_g = _dev_outline_level_numeric(
                        pf_dates_work_proj[pf_dates_level_col]
                    )
                    w3_pf = pf_dates_work_proj[
                        _ln_g == float(pf_dates_bld_tier)
                    ].copy()
                    if (
                        str(selected_block_dates).strip() != "Все"
                        and not _is_covenant_block_sel
                    ):
                        if (
                            pf_dates_block_filter_mode == "column"
                            and pf_dates_block_filter_col
                            and pf_dates_block_filter_col in pf_dates_proj_df.columns
                        ):
                            _mask_blk = (
                                pf_dates_proj_df.reindex(w3_pf.index)[pf_dates_block_filter_col]
                                .astype(str)
                                .str.strip()
                                == str(selected_block_dates).strip()
                            )
                            w3_pf = w3_pf[_mask_blk.fillna(False).to_numpy()].copy()
                        else:
                            w3_pf = w3_pf[
                                w3_pf["_dt_lvl2_key"].astype(str).str.strip()
                                == str(selected_block_dates).strip()
                            ]
                    _go = sorted(
                        w3_pf[pf_dates_task_col]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .unique()
                        .tolist()
                    )
                    _go = [x for x in _go if x]
                    if (
                        not _go
                        and str(selected_block_dates).strip() != "Все"
                        and not _is_covenant_block_sel
                        and "_dt_lvl3_key" in w3_pf.columns
                    ):
                        _k3pf = w3_pf["_dt_lvl3_key"].astype(str).str.strip()
                        _k3pf = _k3pf[_k3pf.ne("") & _k3pf.str.lower().ne("nan")]
                        if len(_k3pf):
                            _go = sorted(pd.unique(_k3pf).tolist())
                    if _maket_mode_pf:
                        _go = _deviations_scope_building_opts_to_deviations(
                            _go,
                            _deviations_building_keys_with_deviations(_pfd_bld_src),
                        )
                    bopts = ["Все"] + _go
                    selected_building_dates = st.selectbox(
                        "Строение",
                        bopts,
                        key="dates_building_l3",
                    )
                elif dates_building_col and dates_building_col in pf_dates_proj_df.columns:
                    pf_dates_building_filter_mode = "column"
                    pf_dates_building_filter_col = dates_building_col
                    _dbc_opts = sorted(
                        _pfd_bld_src[dates_building_col]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .unique()
                        .tolist()
                    )
                    if _maket_mode_pf:
                        _dbc_opts = _deviations_scope_col_building_opts_to_deviations(
                            _pfd_bld_src, _dbc_opts, dates_building_col
                        )
                    bopts = ["Все"] + _dbc_opts
                    selected_building_dates = st.selectbox(
                        "Строение",
                        bopts,
                        key="dates_building",
                    )
                else:
                    pf_dates_building_filter_mode = "none"
                    pf_dates_building_filter_col = None
                    selected_building_dates = "Все"
            with fl_main4:
                _lvl_opts_tz = [
                    "Уровень 4 (укрупнённо)",
                    "Уровень 5 (детально)",
                ]
                if plan_fact_dates_outline_col and plan_fact_dates_outline_col in df.columns:
                    _legacy_lvl = st.session_state.get("dates_level")
                    if _legacy_lvl in (
                        "Сводные (1–3 ур.)",
                        "Все уровни",
                        "Укрупнённо (уровень 4)",
                    ):
                        st.session_state["dates_level"] = _lvl_opts_tz[0]
                    elif _legacy_lvl in ("Детально (уровень 5)", "Уровень 5 (детально)"):
                        st.session_state["dates_level"] = _lvl_opts_tz[1]
                    elif _legacy_lvl not in _lvl_opts_tz:
                        st.session_state["dates_level"] = _lvl_opts_tz[0]
                    selected_level = st.selectbox(
                        "Детализация",
                        _lvl_opts_tz,
                        index=0,
                        key="dates_level",
                    )
                else:
                    selected_level = _lvl_opts_tz[0]

            with fl_main5:
                selected_reason_bucket_dates = "Все"
                _rbuckets: list[str] = []
                if (not st.session_state.get("dates_only_covenants", False)) and "reason of deviation" in df.columns:
                    _rvals = (
                        df["reason of deviation"]
                        .dropna()
                        .astype(str)
                        .str.strip()
                    )
                    _rvals = _rvals[_rvals.ne("") & _rvals.str.lower().ne("nan")]
                    _rbuckets = sorted(
                        {
                            _deviations_reason_bucket_label(v)
                            for v in _rvals.tolist()
                            if _deviations_reason_bucket_label(v)
                        }
                    )
                if _rbuckets:
                    selected_reason_bucket_dates = st.selectbox(
                        "Причина отклонения (категория)",
                        ["Все"] + _rbuckets,
                        key="dates_reason_bucket_filter",
                    )
                else:
                    st.selectbox(
                        "Причина отклонения (категория)",
                        ["Все"],
                        key="dates_reason_bucket_filter_idle",
                        disabled=True,
                    )

        st.markdown(_plan_fact_display_opts_css_for_theme(), unsafe_allow_html=True)
        with filters_toggles(st):

            _cb1, _cb2, _cb3, _cb4, _cb5 = st.columns(5, gap="small")
            with _cb1:
                dates_show_reason_notes = st.checkbox(
                    "Показать причины отклонений",
                    value=True,
                    key="dates_show_reason_notes",
                    help=(
                        "При включении: таблица по макету «Причины отклонений» — только задачи MSP уровня 5 "
                        "с заполненной причиной и отклонением окончания < 0. Селектор «Детализация» игнорируется."
                    ),
                )
            with _cb2:
                hide_completed_dates = st.checkbox(
                    "Скрыть завершённые (100%)",
                    value=False,
                    key="dates_hide_done",
                )
            with _cb3:
                force_covenant_ui = st.checkbox(
                    "Только ковенанты",
                    value=False,
                    key="dates_only_covenants",
                )
            with _cb4:
                only_negative_dev_dates = st.checkbox(
                    "Отображать только диаграммы, где отклонение окончания < 0",
                    value=False,
                    key="dates_only_neg_end",
                )
            with _cb5:
                tbl_show_dur = st.checkbox(
                    "Показать «Отклонение длительности» в таблице",
                    value=True,
                    key="dates_tbl_dur",
                )

            if dates_lot_col:
                task_label_mode = st.radio(
                    "Подписи на графике и в таблице",
                    ("По наименованию MSP", "По лоту"),
                    horizontal=True,
                    key="dates_task_label_mode",
                )
            else:
                task_label_mode = "По наименованию MSP"

            dates_value_type = "Даты (план/факт)"
            tbl_show_start = True
            tbl_show_end = True


    # По ТЗ в таблице показываем только строки, где есть отклонение (|дней| > 0) по началу или окончанию.

    # Apply filters
    filtered_df = df.copy()
    if selected_project != "Все" and "project name" in filtered_df.columns:
        _sel_k = _project_filter_norm_key(selected_project)
        if _sel_k:
            filtered_df = filtered_df[
                filtered_df["project name"].map(_project_filter_norm_key) == _sel_k
            ]
    filtered_df = filtered_df.reset_index(drop=True)
    _pf_lvl_col = _dev_tasks_resolve_level_column(filtered_df)
    _pf_task_col = (
        "task name"
        if "task name" in filtered_df.columns
        else find_column(
            filtered_df,
            ["Задача", "task", "Task Name", "Название"],
        )
    )
    _pf_work = _deviations_maket_enrich_ancestor_keys(filtered_df.copy())
    for _c in ("_dt_lvl2_key", "_dt_lvl3_key", "_dt_lvl_num"):
        if _c in _pf_work.columns:
            filtered_df[_c] = _pf_work[_c].to_numpy()

    _covenant_block_ctx = bool(
        force_covenant_ui
        or (
            str(selected_block_dates).strip() != "Все"
            and any(
                tok in str(selected_block_dates).lower()
                for tok in ("ковенант", "ковен", "covenant", "coven")
            )
        )
    )

    def _pf_dates_apply_block_filter(_df: pd.DataFrame) -> pd.DataFrame:
        out = _df
        if selected_block_dates == "Все":
            return out
        if (
            pf_dates_block_filter_mode == "column"
            and pf_dates_block_filter_col
            and pf_dates_block_filter_col in out.columns
        ):
            return out[
                out[pf_dates_block_filter_col].astype(str).str.strip()
                == str(selected_block_dates).strip()
            ]
        if (
            pf_dates_block_filter_mode == "l2"
            and _pf_lvl_col
            and _pf_task_col
            and "_dt_lvl2_key" in out.columns
        ):
            return out[
                out["_dt_lvl2_key"].astype(str).str.strip()
                == str(selected_block_dates).strip()
            ]
        if pf_dates_block_filter_mode == "section" and "section" in out.columns:
            return out[
                out["section"].astype(str).str.strip()
                == str(selected_block_dates).strip()
            ]
        if pf_dates_block_filter_mode == "block" and "block" in out.columns:
            return out[
                out["block"].astype(str).str.strip()
                == str(selected_block_dates).strip()
            ]
        return out

    def _pf_dates_apply_building_filter(_df: pd.DataFrame) -> pd.DataFrame:
        out = _df
        if selected_building_dates == "Все":
            return out
        if (
            pf_dates_building_filter_mode == "column"
            and pf_dates_building_filter_col
            and pf_dates_building_filter_col in out.columns
        ):
            return out[
                out[pf_dates_building_filter_col].astype(str).str.strip()
                == str(selected_building_dates).strip()
            ]
        if pf_dates_building_filter_mode == "l3_plan_slice":
            return _deviations_filter_df_under_l3_building(
                out, selected_building_dates
            )
        if (
            pf_dates_building_filter_mode == "l3_key"
            and _pf_lvl_col
            and _pf_task_col
            and "_dt_lvl3_key" in out.columns
        ):
            return out[
                out["_dt_lvl3_key"].astype(str).str.strip()
                == str(selected_building_dates).strip()
            ]
        if dates_building_col and dates_building_col in out.columns:
            return out[
                out[dates_building_col].astype(str).str.strip()
                == str(selected_building_dates).strip()
            ]
        return out

    if _covenant_block_ctx and selected_building_dates != "Все":
        filtered_df = _pf_dates_apply_building_filter(filtered_df)
        filtered_df = _pf_dates_apply_block_filter(filtered_df)
    else:
        filtered_df = _pf_dates_apply_block_filter(filtered_df)
        filtered_df = _pf_dates_apply_building_filter(filtered_df)
    # ТЗ заказчика 2026-05-06 (Блок 2): верхняя единая таблица «ЗОС» должна
    # отображаться ВСЕГДА (независимо от выбранной «Детализации»), потому что
    # ЗОС-задачи находятся на уровне 5 (детальный) и иначе пропадают при
    # «Уровень 4». Сохраняем срез ДО фильтра уровня в `_zos_source_df`.
    _zos_source_df = filtered_df.copy()
    st.markdown(_PLAN_FACT_SECTION_COMPACT_CSS, unsafe_allow_html=True)
    st.subheader(_plan_fact_resolved_metric_task_name())
    render_plan_fact_dates_metric_plates(
        _zos_source_df,
        selected_project=selected_project,
        dates_notes_col=dates_notes_col,
        dates_milestone_col=dates_milestone_col,
    )
    # Таблица ЗОС ниже дублировала верхние KPI-плашки — скрыта (данные вынесены наверх).

    # Фильтр по уровню иерархии (макет: сводные 1–3, верхний 4, детальный 5)
    _mask_lvl_col = plan_fact_dates_outline_col
    if _mask_lvl_col is None or _mask_lvl_col not in filtered_df.columns:
        if "level structure" in filtered_df.columns:
            _mask_lvl_col = "level structure"
        elif "level" in filtered_df.columns:
            _mask_lvl_col = "level"
    _pf_wbs_col = _msp_resolve_wbs_column(filtered_df)
    # ТЗ заказчика: задачи блока «Ковенанты» лежат на уровне 5 (+заголовок ур.2),
    # поэтому фильтр «Детализация=Уровень 4» вырезал их целиком и весь блок (таблица
    # и график ковенантов) пропадал с «Нет данных». При выборе блока «Ковенанты»
    # (или галочки «Только ковенанты») фильтр уровня пропускаем — показываем все задачи.
    _covenant_block_selected = bool(
        force_covenant_ui
        or (
            str(selected_block_dates).strip() != "Все"
            and any(
                tok in str(selected_block_dates).lower()
                for tok in ("ковенант", "ковен", "covenant", "coven")
            )
        )
    )
    if _covenant_block_selected:
        pass
    elif dates_show_reason_notes:
        # Макет (ТЗ): «уровень 5» — колонка «Уровень» (level), НЕ outline / level structure.
        # В MSP-выгрузках (напр. Есипово) level=5 при level structure=3 — фильтр по
        # outline-колонке вырезал все строки («По макету нет строк»), хотя отклонения
        # ур.5 есть. Совмещаем с _deviations_maket_prepare_df: приоритет колонки «level».
        _lvl_col_maket = None
        if "level" in filtered_df.columns and pd.to_numeric(
            filtered_df["level"], errors="coerce"
        ).notna().any():
            _lvl_col_maket = "level"
        elif _mask_lvl_col and _mask_lvl_col in filtered_df.columns:
            _lvl_col_maket = _mask_lvl_col
        if _lvl_col_maket:
            level_num = pd.to_numeric(filtered_df[_lvl_col_maket], errors="coerce")
            filtered_df = filtered_df[level_num == 5]
    elif _mask_lvl_col and _mask_lvl_col in filtered_df.columns:
        level_num = pd.to_numeric(filtered_df[_mask_lvl_col], errors="coerce")
        if selected_level == "Сводные (1–3 ур.)":
            mask_level = level_num.notna() & (level_num <= 3)
            if mask_level.any():
                filtered_df = filtered_df[mask_level]
        elif selected_level in (
            "Уровень 4 (верхний)",
            "Укрупнённо (уровень 4)",
            "Уровень 4 (укрупнённо)",
        ):
            filtered_df = filtered_df[level_num == 4]
        elif selected_level in (
            "Уровень 5 (детальный)",
            "Детально (уровень 5)",
            "Уровень 5 (детально)",
        ):
            filtered_df = filtered_df[level_num == 5]

    if filtered_df.empty:
        st.info("Нет данных для выбранных фильтров.")
        return

    ensure_date_columns(filtered_df)
    # Prepare data for visualization - compare plan and fact dates
    # First, ensure all dates are datetime objects
    date_cols = ["plan start", "plan end", "base start", "base end"]
    for col in date_cols:
        if col in filtered_df.columns:
            filtered_df[col] = pd.to_datetime(
                filtered_df[col], errors="coerce", dayfirst=True
            )

    missing_date_cols = [col for col in date_cols if col not in filtered_df.columns]
    if missing_date_cols:
        st.warning(f"Отсутствуют необходимые колонки с датами: {', '.join(missing_date_cols)}")
        return

    # Filter to rows that have at least plan OR fact dates (not necessarily both)
    has_plan_dates = filtered_df["plan start"].notna() & filtered_df["plan end"].notna()
    has_fact_dates = filtered_df["base start"].notna() & filtered_df["base end"].notna()
    has_any_dates = has_plan_dates | has_fact_dates
    # .copy() обязателен для pandas 2.x (CoW): избегаем присвоений в slice/view
    filtered_df = filtered_df[has_any_dates].copy()

    if filtered_df.empty:
        st.info("Нет задач с плановыми или фактическими датами для выбранных фильтров.")
        return

    # Перевычисляем маски: начало и конец считаются отдельно, если есть обе даты пары
    both_starts = (
        filtered_df["plan start"].notna() & filtered_df["base start"].notna()
    )
    both_ends = filtered_df["plan end"].notna() & filtered_df["base end"].notna()

    filtered_df["plan_start_diff"] = np.nan
    filtered_df["plan_end_diff"] = np.nan
    filtered_df["total_diff_days"] = 0.0

    if both_starts.any():
        filtered_df.loc[both_starts, "plan_start_diff"] = (
            filtered_df.loc[both_starts, "base start"]
            - filtered_df.loc[both_starts, "plan start"]
        ).dt.total_seconds() / 86400
    if both_ends.any():
        filtered_df.loc[both_ends, "plan_end_diff"] = (
            filtered_df.loc[both_ends, "base end"]
            - filtered_df.loc[both_ends, "plan end"]
        ).dt.total_seconds() / 86400

    has_end = filtered_df["plan_end_diff"].notna()
    filtered_df.loc[has_end, "total_diff_days"] = filtered_df.loc[
        has_end, "plan_end_diff"
    ].abs()
    only_start = (~has_end) & filtered_df["plan_start_diff"].notna()
    filtered_df.loc[only_start, "total_diff_days"] = filtered_df.loc[
        only_start, "plan_start_diff"
    ].abs()

    pct_col_live = dates_pct_col_resolved
    if pct_col_live is None or pct_col_live not in filtered_df.columns:
        pct_col_live = find_column(
            filtered_df,
            [
                "pct complete",
                "percent complete",
                "Процент_завершения",
                "Процент завершения",
                "% выполнения",
                "% complete",
                "percent",
            ],
        )
    if pct_col_live is None or pct_col_live not in filtered_df.columns:
        pct_col_live = _find_first_column_matching_keywords(
            filtered_df,
            (
                "percent complete",
                "pct complete",
                "% complete",
                "процент выполн",
                "процент_заверш",
                "% выполн",
                "% заверш",
                "физический %",
                "выполн",
                "complete",
                "percent",
            ),
        )
    if hide_completed_dates and pct_col_live and pct_col_live in filtered_df.columns:
        _pct_raw = _safe_df_column_series(filtered_df, pct_col_live)
        if _pct_raw is not None:
            _pct = _parse_msp_percent_complete_series(_pct_raw).reindex(
                filtered_df.index
            )
            # Явные 100% (и «1» как доля) скрываем; пустые/нечисловые оставляем.
            filtered_df = filtered_df.loc[
                _pct.isna() | (_pct < 99.9995)
            ].copy()

    _covenant_tokens = (
        "ковенант",
        "ковенанты",
        "ковен",
        "финковенант",
        "covenant",
        "covenants",
        "coven",
    )

    def _text_indicates_covenant(val):
        if val is None or (isinstance(val, float) and pd.isna(val)):
            return False
        t = str(val).lower()
        return any(tok in t for tok in _covenant_tokens)

    def _covenant_row_mask(frame):
        m = pd.Series(False, index=frame.index)
        _cov_cols = ["section", "block", "task name", "reason of deviation"]
        if dates_notes_col:
            _cov_cols.append(dates_notes_col)
        if dates_milestone_col:
            _cov_cols.append(dates_milestone_col)
        # Дополнительно: любые колонки, по названию похожие на reason/notes/comments/milestone.
        _kw = ("reason", "причин", "note", "notes", "comment", "remark", "milestone", "вех")
        for _c in frame.columns:
            _lc = str(_c).strip().lower()
            if any(k in _lc for k in _kw):
                _cov_cols.append(_c)
        _cov_cols = list(dict.fromkeys(_cov_cols))
        for col in _cov_cols:
            if col in frame.columns:
                m = m | frame[col].astype(str).map(_text_indicates_covenant)
        return m

    df_after_hide = filtered_df.copy()
    if df_after_hide.empty:
        st.info("Нет данных после фильтра «Скрыть завершённые».")
        return

    if (
        selected_reason_bucket_dates != "Все"
        and "reason of deviation" in df_after_hide.columns
    ):
        _rnorm_all = (
            df_after_hide["reason of deviation"]
            .map(lambda x: _deviations_reason_bucket_label(_clean_display_str(x)))
            .astype(str)
            .str.strip()
        )
        df_after_hide = df_after_hide[
            _rnorm_all == str(selected_reason_bucket_dates).strip()
        ].copy()
        if df_after_hide.empty:
            st.info("Нет данных после фильтра «Причина отклонения (категория)».")
            return
    if force_covenant_ui:
        _manual_base_df = df_after_hide.copy()
        _cov_mask_all = _covenant_row_mask(df_after_hide)
        df_after_hide = df_after_hide.loc[_cov_mask_all].copy()
        if df_after_hide.empty:
            _manual_task_col = (
                _pf_task_col
                if _pf_task_col and _pf_task_col in _manual_base_df.columns
                else ("task name" if "task name" in _manual_base_df.columns else None)
            )
            if _manual_task_col:
                suppress_caption(
                    "Автопоиск ковенантов не нашёл совпадений по маркерам. "
                    "Выберите нужные задачи вручную."
                )
                _manual_work = _manual_base_df.copy()
                _task_s = _manual_work[_manual_task_col].astype(str).str.strip()
                _manual_work = _manual_work[_task_s.ne("") & _task_s.str.lower().ne("nan")]
                if (
                    selected_project == "Все"
                    and "project name" in _manual_work.columns
                ):
                    _proj_s = (
                        _manual_work["project name"].astype(str).str.strip().replace("", "—")
                    )
                    _manual_work["_cov_pick"] = (
                        _task_s.loc[_manual_work.index] + " (" + _proj_s + ")"
                    )
                else:
                    _manual_work["_cov_pick"] = _task_s.loc[_manual_work.index]
                _manual_opts = sorted(
                    _manual_work["_cov_pick"].dropna().astype(str).str.strip().unique().tolist()
                )
                _manual_sel = st.multiselect(
                    "Ковенанты: выбрать задачи вручную",
                    options=_manual_opts,
                    key="dates_manual_covenant_tasks",
                )
                if _manual_sel:
                    _sel_set = {str(x).strip() for x in _manual_sel if str(x).strip()}
                    df_after_hide = _manual_work[
                        _manual_work["_cov_pick"].astype(str).str.strip().isin(_sel_set)
                    ].drop(columns=["_cov_pick"], errors="ignore").copy()
            if df_after_hide.empty:
                st.info("Нет ковенантных строк для отображения.")
                return

    if task_label_mode == "По лоту" and dates_lot_col and dates_lot_col in df_after_hide.columns:
        _lc = df_after_hide[dates_lot_col].astype(str).str.strip()
        _lot_mask = df_after_hide[dates_lot_col].notna() & _lc.ne("") & _lc.str.lower().ne("nan")
        df_after_hide = df_after_hide[_lot_mask].copy()
        if df_after_hide.empty:
            st.info("Нет строк с заполненным лотом для выбранных фильтров.")
            return

    # ТЗ заказчика (скрин 7): при выборе блока «Ковенанты» (или галочки
    # «Только ковенанты») таблицу и график ковенантов нужно показывать целиком,
    # без фильтра «отклонение окончания < 0». Раньше ковенанты с неотрицательным
    # отклонением отсекались, выборка становилась пустой и весь блок пропадал
    # («Нет строк после фильтров»).
    _covenant_mode = bool(
        force_covenant_ui
        or (selected_block_dates != "Все" and _text_indicates_covenant(selected_block_dates))
    )

    chart_df_all = df_after_hide.copy()
    chart_df = chart_df_all.copy()
    if dates_show_reason_notes:
        _pf_maket_chart = _deviations_maket_scope_df(df_after_hide)
        if _pf_maket_chart.empty:
            st.info(
                "По макету нет строк: уровень 5, непустая причина, отклонение окончания < 0."
            )
            return
        chart_df_all = _pf_maket_chart.copy()
        chart_df = chart_df_all.copy()
        if "plan_end_diff" not in chart_df.columns and "_end_diff" in chart_df.columns:
            chart_df["plan_end_diff"] = chart_df["_end_diff"]
            chart_df_all["plan_end_diff"] = chart_df_all["_end_diff"]
    elif only_negative_dev_dates and not _covenant_mode:
        chart_df = chart_df[
            chart_df["plan_end_diff"].notna()
            & (chart_df["plan_end_diff"] < 0)
        ]

    table_df = df_after_hide.copy()
    if not dates_show_reason_notes and not _covenant_mode:
        _end_dev = pd.to_numeric(table_df.get("plan_end_diff"), errors="coerce")
        table_df = table_df[_end_dev.notna() & (_end_dev < -1e-9)].copy()

    if chart_df.empty and table_df.empty and not _covenant_mode:
        st.info(
            "Нет задач с отклонением окончания < 0 для выбранных фильтров."
        )
        return
    if chart_df.empty and table_df.empty and _covenant_mode:
        st.info("Нет ковенантных строк для выбранных фильтров.")
        return

    # filtered_df — выборка для графиков (учитывает «< 0»); основная таблица — из table_df.
    filtered_df = chart_df.sort_values("task name", ascending=True)

    def _sanitize_eng_networks(s):
        if s is None or (isinstance(s, float) and pd.isna(s)):
            return ""
        t = str(s).strip()
        return re.sub(
            r"(?i)(инженерн[а-яё]*\s+сет[а-яё]*)\s*№\s*[12]\b",
            r"\1",
            t,
        ).strip()

    def _fmt_lot_label(lv) -> str:
        """Подпись лота: его НАЗВАНИЕ; префикс «Лот » не дублируем, если он уже есть."""
        s = str(lv).strip()
        if s.lower().startswith("лот") or s.lower().startswith("lot"):
            return s
        return f"Лот {s}"

    def _bar_task_label_from_row(row, task_name):
        if task_label_mode == "По лоту" and dates_lot_col and dates_lot_col in row.index:
            lv = row.get(dates_lot_col)
            if pd.notna(lv) and str(lv).strip() not in ("", "nan", "None"):
                return _sanitize_eng_networks(_fmt_lot_label(lv))
        return _sanitize_eng_networks(str(task_name).strip() if task_name is not None else "")

    plan_start_col = "plan start" if "plan start" in filtered_df.columns else find_column(filtered_df, ["Старт План", "План Старт"])
    plan_end_col = "plan end" if "plan end" in filtered_df.columns else find_column(filtered_df, ["Конец План", "План Конец"])
    base_start_col = "base start" if "base start" in filtered_df.columns else find_column(filtered_df, ["Старт Факт", "Факт Старт"])
    base_end_col = "base end" if "base end" in filtered_df.columns else find_column(filtered_df, ["Конец Факт", "Факт Конец"])
    if not all([plan_start_col, plan_end_col, base_start_col, base_end_col]):
        st.warning("Не найдены колонки с датами (план/факт).")
        return

    # Prepare data for Gantt chart - compare plan vs fact
    viz_data = []
    for idx, row in filtered_df.iterrows():
        task_name = row.get("task name", "Неизвестно")
        project_name = row.get("project name", "Неизвестно")
        _disp = _bar_task_label_from_row(row, task_name)

        plan_start = row.get(plan_start_col)
        plan_end = row.get(plan_end_col)
        base_start = row.get(base_start_col)
        base_end = row.get(base_end_col)
        diff_days = row.get("total_diff_days", 0)

        # Add plan dates
        if pd.notna(plan_start) and pd.notna(plan_end):
            viz_data.append(
                {
                    "Task": f"{_disp} ({project_name})",
                    "Task_Original": task_name,
                    "Project": project_name,
                    "Start": plan_start,
                    "End": plan_end,
                    "Type": "План",
                    "Duration": (plan_end - plan_start).total_seconds() / 86400,
                    "Diff_Days": diff_days,
                }
            )

        # Add fact dates
        if pd.notna(base_start) and pd.notna(base_end):
            viz_data.append(
                {
                    "Task": f"{_disp} ({project_name})",
                    "Task_Original": task_name,
                    "Project": project_name,
                    "Start": base_start,
                    "End": base_end,
                    "Type": "Факт",
                    "Duration": (base_end - base_start).total_seconds() / 86400,
                    "Diff_Days": diff_days,
                }
            )

    if not viz_data:
        st.info("Нет валидных данных по датам.")
        return

    viz_df = pd.DataFrame(viz_data)

    # Sort tasks by difference (largest first) - maintain order from filtered_df
    task_order = filtered_df.sort_values("total_diff_days", ascending=False)[
        "task name"
    ].tolist()
    # Create a mapping for sorting
    task_order_map = {task: idx for idx, task in enumerate(task_order)}
    viz_df["sort_order"] = viz_df["Task_Original"].map(task_order_map).fillna(999)
    viz_df = viz_df.sort_values("sort_order")

    # Gantt chart - use proper timeline visualization with plotly express
    # Prepare data for bar chart - plan and fact side by side for each task
    # Порядок строк: по убыванию |отклонение окончания| (ТЗ: крупные отклонения сверху на графике)
    def _resolve_dev_group_name(row) -> str:
        if pf_dates_block_filter_mode == "l2" and "_dt_lvl2_key" in row.index:
            g = _clean_display_str(row.get("_dt_lvl2_key"))
            if g:
                return g
        section_name = _clean_display_str(row.get("section"))
        return section_name if section_name else "-"

    bar_data = []
    _ord = filtered_df.copy()
    _ord["_abs_end_dev"] = pd.to_numeric(_ord["plan_end_diff"], errors="coerce").abs()
    unique_tasks = (
        _ord.sort_values(["_abs_end_dev", "total_diff_days"], ascending=[False, False], na_position="last")
        .drop_duplicates(subset=["task name"], keep="first")["task name"]
        .tolist()
    )
    for task_name in unique_tasks:
        task_rows = filtered_df[filtered_df["task name"] == task_name]
        if task_rows.empty:
            continue

        # If "Все" projects, show each task for each project separately
        if selected_project == "Все":
            for _, row in task_rows.iterrows():
                project_name = row.get("project name", "Неизвестно")
                _tl = _bar_task_label_from_row(row, task_name)
                display_name = f"{_tl} ({project_name})"
                diff_days = row.get("total_diff_days", 0)

                plan_start = row.get("plan start")
                plan_end = row.get("plan end")
                base_start = row.get("base start")
                base_end = row.get("base end")

                group_name = _resolve_dev_group_name(row)

                # Add plan entry
                if pd.notna(plan_start) and pd.notna(plan_end):
                    bar_data.append(
                        {
                            "Задача": display_name,
                            "Группа": group_name,
                            "Тип": "План",
                            "Дата начала": plan_start,
                            "Дата окончания": plan_end,
                            "Длительность": (plan_end - plan_start).total_seconds() / 86400,
                            "Отклонение": diff_days,
                        }
                    )

                # Add fact entry
                if pd.notna(base_start) and pd.notna(base_end):
                    bar_data.append(
                        {
                            "Задача": display_name,
                            "Группа": group_name,
                            "Тип": "Факт",
                            "Дата начала": base_start,
                            "Дата окончания": base_end,
                            "Длительность": (base_end - base_start).total_seconds() / 86400,
                            "Отклонение": diff_days,
                        }
                    )
        else:
            # If specific project selected, show only that project's tasks
            row = task_rows.iloc[0]
            project_name = row.get("project name", "Неизвестно")
            _tl = _bar_task_label_from_row(row, task_name)
            display_name = f"{_tl} ({project_name})"
            diff_days = row.get("total_diff_days", 0)
            group_name = _resolve_dev_group_name(row)

            plan_start = row.get("plan start")
            plan_end = row.get("plan end")
            base_start = row.get("base start")
            base_end = row.get("base end")

            # Add plan entry
            if pd.notna(plan_start) and pd.notna(plan_end):
                bar_data.append(
                    {
                        "Задача": display_name,
                        "Группа": group_name,
                        "Тип": "План",
                        "Дата начала": plan_start,
                        "Дата окончания": plan_end,
                        "Длительность": (plan_end - plan_start).total_seconds() / 86400,
                        "Отклонение": diff_days,
                    }
                )

            # Add fact entry
            if pd.notna(base_start) and pd.notna(base_end):
                bar_data.append(
                    {
                        "Задача": display_name,
                        "Группа": group_name,
                        "Тип": "Факт",
                        "Дата начала": base_start,
                        "Дата окончания": base_end,
                        "Длительность": (base_end - base_start).total_seconds() / 86400,
                        "Отклонение": diff_days,
                    }
                )

    bar_df = pd.DataFrame(bar_data)

    covenant_filter_selected = (
        selected_block_dates != "Все"
        and _text_indicates_covenant(selected_block_dates)
    )
    covenant_auto_from_data = False
    for col in ("section", "block", "task name"):
        if col in df_after_hide.columns and df_after_hide[col].astype(str).map(
            _text_indicates_covenant
        ).any():
            covenant_auto_from_data = True
            break
    show_covenant_ui = force_covenant_ui or covenant_filter_selected or covenant_auto_from_data
    # «Причины отклонений»: основная таблица с колонками причин/заметок — без блока «Ковенанты (таблица)»
    # от автодетекта в данных (иначе дублируется и уходит в expander ковенантов).
    if dates_show_reason_notes and not force_covenant_ui:
        show_covenant_ui = False
    # Таблица «Ковенанты»: при выборе блока с маркером ковенанта срез уже ограничен блоком —
    # показываем все строки блока (как на экране СМР), без доп. текстовой маски «ковенант» в задаче.
    # Иначе — строки с признаком ковенанта в полях задачи/блока/примечаний и т.д.
    covenant_rows_all_cov = (
        chart_df_all.copy()
        if covenant_filter_selected
        else chart_df_all.loc[_covenant_row_mask(chart_df_all)].copy()
    )
    covenant_rows_df = table_df
    covenant_chart_df = chart_df.copy()

    if force_covenant_ui:
        covenant_chart_df = chart_df_all.copy()
        covenant_rows_df = covenant_rows_all_cov
        if covenant_chart_df.empty:
            show_covenant_ui = False
            st.info("Нет ковенантных строк для отображения.")
        elif covenant_rows_df.empty:
            pass
    elif covenant_auto_from_data and not covenant_filter_selected:
        covenant_rows_df = covenant_rows_all_cov
        covenant_chart_df = covenant_rows_df.copy()
        if covenant_rows_df.empty:
            show_covenant_ui = False
    elif covenant_filter_selected:
        covenant_rows_df = covenant_rows_all_cov
        covenant_chart_df = covenant_rows_df.copy()
    else:
        covenant_chart_df = covenant_rows_df.copy()

    covenant_points_chart = bool(force_covenant_ui or covenant_filter_selected)

    # График: блок «Ковенанты» — точки начала/окончания; иначе — столбцы до дат окончания.
    def _render_unified_gantt(source_df: pd.DataFrame, is_covenant: bool):
        pe_col, fe_col = "plan end", "base end"
        if source_df is None or source_df.empty:
            st.info("Нет данных для графика при текущих фильтрах.")
            return
        if pe_col not in source_df.columns or fe_col not in source_df.columns:
            st.warning("Нет колонок с датами для построения графика.")
            return
        local = source_df.copy()
        for _dc in ("plan start", "base start", pe_col, fe_col):
            if _dc in local.columns:
                local[_dc] = pd.to_datetime(local[_dc], errors="coerce", dayfirst=True)
        if "plan_end_diff" not in local.columns or local["plan_end_diff"].isna().all():
            both_ends = local[pe_col].notna() & local[fe_col].notna()
            local.loc[both_ends, "plan_end_diff"] = (
                local.loc[both_ends, fe_col] - local.loc[both_ends, pe_col]
            ).dt.total_seconds() / 86400.0
        local["plan_end_diff"] = pd.to_numeric(local.get("plan_end_diff", np.nan), errors="coerce")

        if is_covenant:
            _cov_m = _plan_fact_covenant_block_mask(local)
            if _cov_m.any():
                local = local.loc[_cov_m].copy()
            else:
                local = local.loc[_covenant_row_mask(local)].copy()
            local = local[local[pe_col].notna() | local[fe_col].notna()]
        else:
            local = local[local[pe_col].notna() | local[fe_col].notna()].copy()
            if only_negative_dev_dates:
                local = local.loc[
                    local["plan_end_diff"].notna() & (local["plan_end_diff"] < -1e-9)
                ].copy()

        if local.empty:
            st.info("Нет задач для графика при текущих фильтрах.")
            return

        TOP_CAP = 400
        local = (
            local.sort_values("plan_end_diff", ascending=True, na_position="last")
            .head(TOP_CAP)
            .copy()
        )

        def _pf_fmt_day_short(d):
            if d is None or (isinstance(d, float) and pd.isna(d)):
                return "—"
            try:
                ts = pd.Timestamp(d)
                if pd.isna(ts):
                    return "—"
                return ts.strftime("%d.%m.%y")
            except Exception:
                return "—"

        def _pf_task_name(row: pd.Series) -> str:
            disp = _bar_task_label_from_row(row, row.get("task name", ""))
            if selected_project == "Все" and "project name" in row.index:
                pn = str(row.get("project name", "")).strip()
                if pn:
                    disp = _gantt_label_with_project(disp, pn)
            return str(disp).strip()

        _PF_GANTT_TASK_FONT = 11
        # Длинные РД-подписи: 4 строки достаточно; больше — только раздувает высоту.
        _PF_GANTT_WRAP_MAX_LINES = 4

        def _pf_y_label_wrapped(name: str) -> str:
            _w = _gantt_label_wrap_width_chars(task_font=_PF_GANTT_TASK_FONT)
            return _gantt_wrap_task_label(
                name,
                width=_w,
                max_lines=_PF_GANTT_WRAP_MAX_LINES,
            )

        def _pf_simple_task_label(row: pd.Series) -> str:
            return _pf_y_label_wrapped(_pf_task_name(row))

        def _pf_gantt_chart_height(y_order: list[str]) -> tuple[int, int]:
            """Высота с учётом реального tick-шрифта (×1.5) и max строк <br>."""
            n_rows_local = max(1, len(y_order))
            max_lines = 1
            if y_order:
                max_lines = max(
                    1, max(len(str(y).split("<br>")) for y in y_order)
                )
            # Tick font на графике = task_font × 1.5 — иначе многострочные
            # подписи наезжают друг на друга при «узкой» строке.
            _eff_font = float(_gantt_task_label_font(_PF_GANTT_TASK_FONT))
            lh = float(max(18.0, _eff_font * 1.38))
            bars_block = 28.0  # две полосы + зазор plan/fact
            pad_between = 12.0
            row_h = int(max(56, max_lines * lh + bars_block + pad_between))
            chart_h = max(220, int(_GANTT_MARGINS_V + n_rows_local * row_h))
            return chart_h, max_lines

        def _pf_apply_gantt_y_labels(
            fig_obj, y_order_local: list[str], *, numeric_row_y: bool = False
        ) -> int:
            """Колонка названий — нативные tick-подписи оси Y + automargin.

            Для столбчатой диаграммы РД — numeric_row_y=True (равномерный шаг).
            Не выставляем autorange=\"reversed\": Plotly тогда игнорирует range.
            """
            left_m, _x0, _ann = _project_schedule_gantt_apply_y_labels(
                fig_obj,
                y_order_local,
                dense=False,
                task_font=_PF_GANTT_TASK_FONT,
                numeric_row_y=numeric_row_y,
            )
            fig_obj.update_xaxes(domain=[float(_x0), 1.0])
            _m = fig_obj.layout.margin
            fig_obj.update_layout(
                margin=dict(
                    l=max(int(left_m), 48),
                    r=int(getattr(_m, "r", None) or 56),
                    t=int(getattr(_m, "t", None) or 8),
                    b=int(getattr(_m, "b", None) or 48),
                ),
            )
            return int(left_m)

        _PF_GANTT_VIEWPORT = 1720  # видимая высота блока графика (×2 от 860)
        _PF_GANTT_BAR_WIDTH = 0.12  # ~в 4 раза уже стандартной полосы Plotly
        _PF_GANTT_LEGEND = dict(
            orientation="h",
            yanchor="top",
            y=-0.06,
            xanchor="left",
            x=0,
        )

        if is_covenant:
            local["_y_full"] = local.apply(_pf_simple_task_label, axis=1)
            _seen_fc: dict[str, int] = {}
            _uniq_fc: list[str] = []
            for lbl in local["_y_full"].tolist():
                if lbl in _seen_fc:
                    _seen_fc[lbl] += 1
                    _uniq_fc.append(f"{lbl}<br>#{_seen_fc[lbl]}")
                else:
                    _seen_fc[lbl] = 1
                    _uniq_fc.append(lbl)
            local["_y"] = _uniq_fc
        elif task_label_mode == "По лоту":
            # ТЗ (замечание): в режиме «по лоту» на один лот приходится несколько
            # задач уровня 5 → раньше рисовалось по полосе на задачу с одинаковой
            # подписью (подписи слева накладывались). Схлопываем дубликаты лота в
            # одну строку и берём «последний срок» — максимум «Базовое окончание»
            # и «Окончание» по задачам лота.
            local["_y_simple"] = local.apply(_pf_simple_task_label, axis=1)
            _lot_rows: list[dict] = []
            for _lbl, _g in local.groupby("_y_simple", sort=False):
                _be_max = pd.to_datetime(_g[fe_col], errors="coerce").max()
                _pe_max = pd.to_datetime(_g[pe_col], errors="coerce").max()
                _dev = np.nan
                if pd.notna(_be_max) and pd.notna(_pe_max):
                    _dev = (_be_max - _pe_max).total_seconds() / 86400.0
                _lot_rows.append(
                    {
                        "_y": _lbl,
                        "_y_simple": _lbl,
                        fe_col: _be_max,
                        pe_col: _pe_max,
                        "plan_end_diff": _dev,
                    }
                )
            local = (
                pd.DataFrame(_lot_rows)
                .sort_values("plan_end_diff", ascending=True, na_position="last")
                .reset_index(drop=True)
            )
        else:
            local["_y_simple"] = local.apply(_pf_simple_task_label, axis=1)
            _seen_br: dict[str, int] = {}
            _uniq_br: list[str] = []
            for lbl in local["_y_simple"].tolist():
                if lbl in _seen_br:
                    _seen_br[lbl] += 1
                    _uniq_br.append(f"{lbl} #{_seen_br[lbl]}")
                else:
                    _seen_br[lbl] = 1
                    _uniq_br.append(lbl)
            local["_y"] = _uniq_br

        y_order = local["_y"].tolist()
        n_rows = len(y_order)
        _chart_h, _max_lines = _pf_gantt_chart_height(y_order)
        if is_covenant:
            _chart_h = int(_chart_h * 3)

        fig = go.Figure()
        _pf_bar_chart_h: Optional[int] = None
        _pf_bar_chart_viewport: Optional[int] = None

        if is_covenant:
            _y = local["_y"]
            _full = local.get("_y_full", _y)

            def _cov_scatter(col, legend_name, color, symbol, text_color=None):
                if col not in local.columns:
                    return
                xv = local[col]
                if not xv.notna().any():
                    return
                _txt = [
                    _pf_fmt_day_short(v) if pd.notna(v) else ""
                    for v in xv.tolist()
                ]
                fig.add_trace(
                    go.Scatter(
                        x=xv,
                        y=_y,
                        mode="markers+text",
                        text=_txt,
                        textposition="top center",
                        textfont=dict(size=9, color=(text_color or color)),
                        cliponaxis=False,
                        name=legend_name,
                        marker=dict(size=11, color=color, symbol=symbol, line=dict(width=1, color="#fff")),
                        customdata=_full,
                        hovertemplate="%{customdata}<br>"
                        + legend_name
                        + ": %{x|%d.%m.%Y}<extra></extra>",
                    )
                )

            _cov_scatter("base start", "Базовое начало", "#3B82F6", "circle-open", text_color="#93c5fd")
            _cov_scatter(fe_col, "Базовое окончание", "#14b8a6", "diamond", text_color="#5eead4")
            _cov_scatter("plan start", "Начало", "#fb923c", "circle", text_color="#fdba74")
            _cov_scatter(pe_col, "Окончание", "#EF4444", "diamond-open", text_color="#fca5a5")
            fig.update_layout(
                autosize=True,
                width=None,
                xaxis_title="Дата",
                yaxis_title=None,
                height=_chart_h,
                xaxis=dict(type="date", tickformat="%d.%m.%Y", automargin=True),
                margin=dict(l=4, r=96, t=8, b=48),
                legend=_PF_GANTT_LEGEND,
            )
            _pf_apply_gantt_y_labels(fig, y_order)
            _pf_bar_chart_h = _chart_h
            _pf_bar_chart_viewport = int(_PF_GANTT_VIEWPORT * 3)
        else:
            def _epoch_ms(ts) -> Optional[float]:
                if ts is None or (isinstance(ts, float) and pd.isna(ts)):
                    return None
                t = pd.Timestamp(ts)
                if pd.isna(t):
                    return None
                return float(t.timestamp() * 1000.0)

            _bar_rows: list[dict] = []
            for _, row in local.iterrows():
                y_lbl = str(row["_y"])
                be = row.get(fe_col)
                pe = row.get(pe_col)
                be_ms = _epoch_ms(be) if pd.notna(be) else None
                pe_ms = _epoch_ms(pe) if pd.notna(pe) else None
                if be_ms is None and pe_ms is None:
                    continue
                _bar_rows.append(
                    {
                        "y": y_lbl,
                        "be": be,
                        "pe": pe,
                        "be_ms": be_ms,
                        "pe_ms": pe_ms,
                    }
                )

            if not _bar_rows:
                st.info(
                    "Нет задач с датами «Базовое окончание» или «Окончание» для диаграммы."
                )
                return

            _plot_ms = [
                float(ms)
                for r in _bar_rows
                for ms in (r.get("be_ms"), r.get("pe_ms"))
                if ms is not None
            ]
            _origin_ms = min(_plot_ms)
            _origin_ts = pd.to_datetime(_origin_ms, unit="ms", utc=True).tz_convert(None).normalize()

            _min_bar_ms = 0.5 * 86400000.0  # подпись даты только если полоса видима
            y_labels: list[str] = []
            y_idx: list[int] = []
            base_len_ms: list = []
            base_base_ms: list = []
            base_txt: list[str] = []
            cur_len_ms: list = []
            cur_base_ms: list = []
            cur_txt: list[str] = []
            cust_b: list[tuple[str, str, str]] = []
            cust_p: list[tuple[str, str, str]] = []

            for r in _bar_rows:
                y_lbl = r["y"]
                be = r["be"]
                pe = r["pe"]
                be_ms = r["be_ms"]
                pe_ms = r["pe_ms"]
                b_len = max(0.0, float(be_ms - _origin_ms)) if be_ms is not None else 0.0
                c_len = max(0.0, float(pe_ms - _origin_ms)) if pe_ms is not None else 0.0
                if b_len <= 0.0 and c_len <= 0.0:
                    continue
                _i = len(y_labels)
                y_labels.append(y_lbl)
                y_idx.append(_i)
                # NaN — нет полосы (нет даты / нулевая длина).
                if b_len > 0.0:
                    base_base_ms.append(float(_origin_ms))
                    base_len_ms.append(b_len)
                    base_txt.append(
                        pd.Timestamp(be).strftime("%d.%m.%Y")
                        if pd.notna(be) and b_len >= _min_bar_ms
                        else ""
                    )
                else:
                    base_base_ms.append(np.nan)
                    base_len_ms.append(np.nan)
                    base_txt.append("")
                if c_len > 0.0:
                    cur_base_ms.append(float(_origin_ms))
                    cur_len_ms.append(c_len)
                    cur_txt.append(
                        pd.Timestamp(pe).strftime("%d.%m.%Y")
                        if pd.notna(pe) and c_len >= _min_bar_ms
                        else ""
                    )
                else:
                    cur_base_ms.append(np.nan)
                    cur_len_ms.append(np.nan)
                    cur_txt.append("")
                _plain = y_lbl.replace("<br>", " ")
                cust_b.append(
                    (
                        _plain,
                        _pf_fmt_day_short(_origin_ts),
                        pd.Timestamp(be).strftime("%d.%m.%Y") if pd.notna(be) else "—",
                    )
                )
                cust_p.append(
                    (
                        _plain,
                        _pf_fmt_day_short(_origin_ts),
                        pd.Timestamp(pe).strftime("%d.%m.%Y") if pd.notna(pe) else "—",
                    )
                )

            if not y_labels:
                st.info("Нет задач с датами для диаграммы при текущих фильтрах.")
                return

            # Выравниваем число строк <br> — иначе короткие подписи «прыгают»
            # визуально относительно многострочных при равном шаге оси.
            _pad_n = max(1, max(len(str(y).split("<br>")) for y in y_labels))
            y_order = []
            for _lab in y_labels:
                _parts = str(_lab).split("<br>")
                while len(_parts) < _pad_n:
                    _parts.append("\u00a0")
                y_order.append("<br>".join(_parts))
            n_rows = len(y_order)
            _chart_h, _max_lines = _pf_gantt_chart_height(y_order)
            _chart_viewport = _PF_GANTT_VIEWPORT
            _x_max_ms = float(_origin_ms)
            for _b0, _bl in zip(base_base_ms, base_len_ms):
                if pd.notna(_b0) and pd.notna(_bl):
                    _x_max_ms = max(_x_max_ms, float(_b0) + float(_bl))
            for _b0, _bl in zip(cur_base_ms, cur_len_ms):
                if pd.notna(_b0) and pd.notna(_bl):
                    _x_max_ms = max(_x_max_ms, float(_b0) + float(_bl))
            _x_pad_ms = 28.0 * 86400000.0  # запас справа под подписи дат на концах полос

            # Numeric Y + lane offset: равномерный шаг строк (как «График проекта»).
            _has_fact = any(pd.notna(x) for x in cur_len_ms)
            _plan_y = [
                float(i)
                + _gantt_grouped_bar_lane_offset("plan", has_fact_trace=_has_fact)
                for i in y_idx
            ]
            _fact_y = [
                float(i)
                + _gantt_grouped_bar_lane_offset("fact", has_fact_trace=_has_fact)
                for i in y_idx
            ]
            _plan_base_dates = [
                pd.Timestamp(float(b), unit="ms") if pd.notna(b) else None
                for b in base_base_ms
            ]
            _fact_base_dates = [
                pd.Timestamp(float(b), unit="ms") if pd.notna(b) else None
                for b in cur_base_ms
            ]

            _base_lbl_clr = _fin_chart_label_color(dark="#5eead4", light="#0f766e")
            _cur_lbl_clr = _fin_chart_label_color(dark="#fdba74", light="#c2410c")
            fig.add_trace(
                go.Bar(
                    name="Базовое окончание",
                    orientation="h",
                    x=base_len_ms,
                    y=_plan_y,
                    base=_plan_base_dates,
                    width=_PF_GANTT_BAR_WIDTH,
                    marker=dict(color="#14b8a6"),
                    text=base_txt,
                    textposition="outside",
                    textfont=dict(size=10, color=_base_lbl_clr),
                    constraintext="none",
                    cliponaxis=False,
                    hovertemplate="%{customdata[0]}<br>Базовое окончание: %{customdata[2]}<extra></extra>",
                    customdata=cust_b,
                )
            )
            fig.add_trace(
                go.Bar(
                    name="Окончание",
                    orientation="h",
                    x=cur_len_ms,
                    y=_fact_y,
                    base=_fact_base_dates,
                    width=_PF_GANTT_BAR_WIDTH,
                    marker=dict(color="#fb923c"),
                    text=cur_txt,
                    textposition="outside",
                    textfont=dict(size=10, color=_cur_lbl_clr),
                    constraintext="none",
                    cliponaxis=False,
                    hovertemplate="%{customdata[0]}<br>Окончание: %{customdata[2]}<extra></extra>",
                    customdata=cust_p,
                )
            )
            fig.update_layout(
                barmode="overlay",
                autosize=True,
                width=None,
                yaxis_title=None,
                height=_chart_h,
                xaxis=dict(
                    type="date",
                    tickformat="%d.%m.%Y",
                    automargin=True,
                    range=[
                        pd.Timestamp(float(_origin_ms), unit="ms"),
                        pd.Timestamp(float(_x_max_ms + _x_pad_ms), unit="ms"),
                    ],
                    title=dict(
                        text="Дата (от начала шкалы до окончания)",
                        standoff=22,
                        font=dict(size=13, color=_fin_chart_axis_color()),
                    ),
                ),
                margin=dict(l=4, r=96, t=8, b=48),
                legend=_PF_GANTT_LEGEND,
                bargap=0.35,
                bargroupgap=0.45,
            )
            _pf_apply_gantt_y_labels(fig, y_order, numeric_row_y=True)
            _pf_bar_chart_h = _chart_h
            _pf_bar_chart_viewport = _chart_viewport

        _sep_shapes: list[dict] = []
        for _si in range(len(y_order) - 1):
            _sep_shapes.append(
                dict(
                    type="line",
                    xref="paper",
                    yref="y",
                    x0=0,
                    x1=1,
                    y0=_si + 0.5,
                    y1=_si + 0.5,
                    line=dict(color="rgba(148,163,184,0.22)", width=1, dash="dot"),
                )
            )
        if _sep_shapes:
            fig.update_layout(shapes=_sep_shapes)

        fig = apply_chart_background(fig, skip_uniformtext=True)
        _render_kw = dict(
            skip_clamp_zoom=True,
            omit_default_width=True,
            caption_below=(
                "Блок «Ковенанты»: начало и окончание — точками на шкале дат."
                if is_covenant
                else (
                    "Столбцы от начала шкалы до «Базового окончания» и «Окончания» "
                    "по последнему сроку разделов РД (ур.5 с шифром под «Рабочая документация»); "
                    "сверху — наибольшее отклонение."
                )
            ),
        )
        if _pf_bar_chart_h is not None:
            _render_kw["height"] = _pf_bar_chart_h
            _render_kw["max_height"] = None
            if (
                _pf_bar_chart_viewport is not None
                and _pf_bar_chart_h > _pf_bar_chart_viewport
            ):
                _render_kw["scroll_viewport_height"] = _pf_bar_chart_viewport
        render_chart(fig, **_render_kw)

    def _plan_fact_gantt_source_df() -> pd.DataFrame:
        if covenant_points_chart:
            out = covenant_chart_df.copy()
            if only_negative_dev_dates:
                ped = pd.to_numeric(out.get("plan_end_diff"), errors="coerce")
                out = out.loc[ped.notna() & (ped < 0)].copy()
            return out
        # Диаграмма всегда по РД (ур.5 + шифр под «Рабочая документация»),
        # независимо от «Показать причины отклонений» / детализации.
        rd_src = _plan_fact_build_rd_deadline_chart_df(_zos_source_df)
        if rd_src is not None and not rd_src.empty:
            out = rd_src
            if only_negative_dev_dates:
                ped = pd.to_numeric(out.get("plan_end_diff"), errors="coerce")
                out = out.loc[ped.notna() & (ped < -1e-9)].copy()
            return out
        return filtered_df.copy()

    _render_unified_gantt(_plan_fact_gantt_source_df(), is_covenant=covenant_points_chart)
    def format_date_display(date_val):
        if pd.isna(date_val):
            return ""
        if isinstance(date_val, pd.Timestamp):
            return date_val.strftime("%d.%m.%Y")
        try:
            dt = pd.to_datetime(date_val, errors="coerce", dayfirst=True)
            if pd.notna(dt):
                return dt.strftime("%d.%m.%Y")
        except Exception:
            pass
        s = str(date_val).strip() if date_val else ""
        return s if s and s.lower() not in ("nan", "nat", "none") else ""

    def _format_int_days(x):
        if pd.isna(x) or str(x).strip() == "":
            return ""
        try:
            return str(int(round(float(x), 0)))
        except (TypeError, ValueError):
            return ""

    def _resolve_msp_id_columns(frame: pd.DataFrame) -> dict:
        """
        Возвращает маппинг {display_name: source_column} для ID задач MSP.
        Встречаются разные выгрузки: Unique ID / UID / Task ID и т.п.
        """
        if frame is None or getattr(frame, "empty", True):
            return {}
        cols = list(frame.columns)
        lower_map = {}
        for c in cols:
            try:
                lower_map[str(c).strip().lower()] = c
            except Exception:
                continue

        out = {}
        # Единый заголовок «ID задачи» — первый доступный источник по приоритету.
        for key in (
            "unique id",
            "unique_id",
            "task id",
            "task id seq",
            "outline number",
            "outline_number",
            "external task id",
            "external_task_id",
            "identifier",
            "active task id",
            "active_task_id",
            "guid",
            "uid",
            "id",
        ):
            if key in lower_map:
                out["ID задачи"] = lower_map[key]
                break
        return out

    summary_source_df = table_df
    _msp_id_cols = _resolve_msp_id_columns(summary_source_df)

    if show_covenant_ui:
        pe_col, fe_col = "plan end", "base end"
        cov_rows: list[dict] = []
        _cov_tbl_df = covenant_rows_df if not covenant_rows_df.empty else covenant_chart_df
        _cov_id_map = _resolve_msp_id_columns(_cov_tbl_df)
        _cov_id_src = None
        if _cov_id_map:
            try:
                _cov_id_src = next(iter(_cov_id_map.values()))
            except StopIteration:
                _cov_id_src = None
        for _, crow in _cov_tbl_df.iterrows():
            ped = crow.get("plan_end_diff")
            ped_num = pd.to_numeric(ped, errors="coerce")
            pev = crow.get(pe_col)
            fev = crow.get(fe_col)
            _pe = pd.to_datetime(pev, errors="coerce", dayfirst=True)
            _fe = pd.to_datetime(fev, errors="coerce", dayfirst=True)
            if pd.isna(ped_num) and pd.notna(_pe) and pd.notna(_fe):
                ped_num = (_fe - _pe).total_seconds() / 86400.0
            _id_cell = ""
            if _cov_id_src and _cov_id_src in _cov_tbl_df.columns:
                _raw_id = crow.get(_cov_id_src)
                if pd.notna(_raw_id) and str(_raw_id).strip() not in ("", "nan", "none"):
                    _id_cell = str(_raw_id).strip()
            cov_rows.append(
                {
                    "Проект": _clean_display_str(crow.get("project name"))
                    if selected_project == "Все" and "project name" in _cov_tbl_df.columns
                    else "",
                    "Задача": _clean_display_str(crow.get("task name")),
                    "ID задачи": _id_cell,
                    "Базовое окончание": _fe,
                    "Окончание": _pe,
                    "Отклонение окончания (дней)": ped_num,
                }
            )
        cov_df = pd.DataFrame(cov_rows)
        if selected_project != "Все" or "project name" not in _cov_tbl_df.columns:
            cov_df = cov_df.drop(columns=["Проект"], errors="ignore")
        if not cov_df.empty:
            _has_cov_dates = cov_df["Базовое окончание"].notna() | cov_df["Окончание"].notna()
            cov_df = cov_df.loc[_has_cov_dates].copy()
        if cov_df.empty:
            st.info("Нет строк для таблицы ковенантов.")
        else:
            render_table_subheader(st, "Ковенанты (таблица)")
            cov_display = cov_df.copy()
            for _dc in ("Базовое окончание", "Окончание"):
                if _dc in cov_display.columns:
                    cov_display[_dc] = cov_display[_dc].apply(format_date_display)
            if "Отклонение окончания (дней)" in cov_display.columns:
                cov_display["Отклонение окончания (дней)"] = cov_display[
                    "Отклонение окончания (дней)"
                ].apply(_format_int_days)
            _cov_num = cov_df.copy()
            if "Отклонение окончания (дней)" in _cov_num.columns:
                _cov_num["Отклонение окончания (дней)"] = pd.to_numeric(
                    _cov_num["Отклонение окончания (дней)"], errors="coerce"
                )
            _render_plan_fact_dates_main_table(
                cov_display,
                _cov_num,
                wrap_class="pf-covenant-table-wrap",
                file_stem="plan_fact_covenant",
                key_prefix="pf_covenant_table",
            )
    elif bar_df.empty:
        st.info("Нет данных для отображения графика.")
    else:
        # Блок «План/факт по этапам» скрыт по ТЗ (макет: верхние метрики/поля убрать).
        pass

    # Верхние плашки KPI — `render_plan_fact_dates_metric_plates`; задача для дат окончания проекта — в админке (`baseline_plan_task_for_metrics`).

    # Summary table — макет: даты / отклонения, видимые столбцы
    summary_data = []

    for idx, row in summary_source_df.iterrows():
        plan_start = row.get("plan start", pd.NaT)
        plan_end = row.get("plan end", pd.NaT)
        base_start = row.get("base start", pd.NaT)
        base_end = row.get("base end", pd.NaT)
        start_diff = row.get("plan_start_diff", np.nan)
        end_diff = row.get("plan_end_diff", np.nan)
        dur_diff = np.nan
        pdur = np.nan
        fdur = np.nan
        # R23-03 add-on (стр.10-11): длительности нужны как отдельные столбцы таблицы,
        # а не только для расчёта Δ длительности. Считаем по каждой паре дат независимо.
        if pd.notna(plan_start) and pd.notna(plan_end):
            try:
                pdur = (plan_end - plan_start).total_seconds() / 86400.0
            except Exception:
                pdur = np.nan
        if pd.notna(base_start) and pd.notna(base_end):
            try:
                fdur = (base_end - base_start).total_seconds() / 86400.0
            except Exception:
                fdur = np.nan
        if not pd.isna(pdur) and not pd.isna(fdur):
            try:
                dur_diff = pdur - fdur
            except Exception:
                dur_diff = np.nan

        if task_label_mode == "По лоту" and dates_lot_col and dates_lot_col in row.index:
            lv = row.get(dates_lot_col)
            if pd.notna(lv) and str(lv).strip() not in ("", "nan", "None"):
                task_show = _sanitize_eng_networks(_fmt_lot_label(lv))
            else:
                task_show = _sanitize_eng_networks(_clean_display_str(row.get("task name")))
        else:
            task_show = _sanitize_eng_networks(_clean_display_str(row.get("task name")))

        _fb_val = ""
        if pf_dates_block_filter_col and pf_dates_block_filter_col in summary_source_df.columns:
            _fb_val = _clean_display_str(row.get(pf_dates_block_filter_col))
        elif pf_dates_block_col_res and pf_dates_block_col_res in summary_source_df.columns:
            _fb_val = _clean_display_str(row.get(pf_dates_block_col_res))
        if not _fb_val and "_dt_lvl2_key" in summary_source_df.columns:
            _fb_val = _clean_display_str(row.get("_dt_lvl2_key"))
        _bld_val = ""
        if "_dt_lvl3_key" in summary_source_df.columns:
            _bld_val = _clean_display_str(row.get("_dt_lvl3_key"))

        rec = {
            "Проект": _clean_display_str(row.get("project name")),
            "Функциональный блок": _fb_val,
            "Строение": _bld_val,
            "Задача": task_show,
            "Базовое начало": pd.to_datetime(base_start, errors="coerce", dayfirst=True),
            "Базовое окончание": pd.to_datetime(base_end, errors="coerce", dayfirst=True),
            "Начало": pd.to_datetime(plan_start, errors="coerce", dayfirst=True),
            "Окончание": pd.to_datetime(plan_end, errors="coerce", dayfirst=True),
            "Отклонение начала": start_diff,
            "Отклонение окончания": end_diff,
            "Базовая длительность": fdur,
            "Длительность": pdur,
            "Отклонение длительности": dur_diff,
        }
        for disp, src in _msp_id_cols.items():
            _tid = row.get(src)
            rec[disp] = (
                str(_tid).strip()
                if pd.notna(_tid) and str(_tid).strip() not in ("", "nan", "none")
                else ""
            )
        if dates_show_reason_notes:
            if _mask_lvl_col and _mask_lvl_col in summary_source_df.columns:
                _lv = pd.to_numeric(row.get(_mask_lvl_col), errors="coerce")
                rec["Ур"] = int(_lv) if pd.notna(_lv) else ""
            if "reason of deviation" in summary_source_df.columns:
                rec["Причины отклонений"] = _clean_display_str(
                    row.get("reason of deviation")
                )
            if dates_notes_col and dates_notes_col in summary_source_df.columns:
                rec["Заметки"] = _clean_display_str(row.get(dates_notes_col))
        summary_data.append(rec)

    summary_df = pd.DataFrame(summary_data)
    _dedup_cols = [c for c in [
        "Проект", "Задача", "Базовое начало", "Базовое окончание",
        "Начало", "Окончание",
    ] if c in summary_df.columns]
    if _dedup_cols:
        summary_df = summary_df.drop_duplicates(subset=_dedup_cols, keep="first").reset_index(drop=True)
    for col in (
        "Отклонение начала",
        "Отклонение окончания",
        "Отклонение длительности",
        "Базовая длительность",
        "Длительность",
    ):
        if col in summary_df.columns:
            summary_df[col] = pd.to_numeric(summary_df[col], errors="coerce")

    # ТЗ заказчика 2026-05-06 (Блок 2): порядок столбцов
    # «Базовое начало | Начало | Отклонение начала | Базовое окончание | Окончание |
    #  Отклонение окончания | Базовая длительность | Длительность | Отклонение длительности».
    # Идентификатор задачи MSP — первый найденный столбец из набора Unique ID / Task ID / Outline Number и т.п.
    out_cols = ["Задача"] if selected_project != "Все" else ["Проект", "Задача"]
    if dates_show_reason_notes and "Ур" in summary_df.columns:
        out_cols.insert(1 if selected_project != "Все" else 2, "Ур")
    if "ID задачи" in summary_df.columns:
        out_cols.append("ID задачи")
    if "Функциональный блок" in summary_df.columns:
        out_cols.append("Функциональный блок")
    if "Строение" in summary_df.columns:
        out_cols.append("Строение")
    out_cols.append("Базовое начало")
    out_cols.append("Начало")
    if tbl_show_start:
        out_cols.append("Отклонение начала")
    out_cols.append("Базовое окончание")
    out_cols.append("Окончание")
    if tbl_show_end:
        out_cols.append("Отклонение окончания")
    out_cols.append("Длительность")
    out_cols.append("Базовая длительность")
    if tbl_show_dur:
        out_cols.append("Отклонение длительности")
    if dates_show_reason_notes:
        if "Причины отклонений" in summary_df.columns:
            out_cols.append("Причины отклонений")
        if "Заметки" in summary_df.columns:
            out_cols.append("Заметки")
    out_cols = [c for c in out_cols if c in summary_df.columns]
    summary_df = summary_df[out_cols]

    if dates_show_reason_notes and "Ур" in summary_df.columns:
        summary_df["_sort_ур"] = pd.to_numeric(summary_df["Ур"], errors="coerce")
        summary_df = summary_df.sort_values(
            ["_sort_ур", "Задача"],
            ascending=[True, True],
            na_position="last",
        ).drop(columns=["_sort_ур"], errors="ignore").reset_index(drop=True)

    _col_short = {
        "Функциональный блок": "Функц. блок",
        "Отклонение начала": "Откл. начала",
        "Отклонение окончания": "Откл. окончания",
        "Базовая длительность": "Баз. длит.",
        "Отклонение длительности": "Откл. длит.",
        "Причина отклонения": "Причина откл.",
    }
    _rename_map = {k: v for k, v in _col_short.items() if k in summary_df.columns}
    summary_df = summary_df.rename(columns=_rename_map)

    summary_numeric = summary_df.copy()
    summary_display = summary_df.copy()
    _dt_download_cols = [
        c
        for c in ("Базовое начало", "Базовое окончание", "Начало", "Окончание")
        if c in summary_display.columns
    ]
    for _dc in _dt_download_cols:
        summary_display[_dc] = summary_display[_dc].apply(format_date_display)
    _int_day_cols = (
        "Откл. начала",
        "Откл. окончания",
        "Откл. длит.",
        "Баз. длит.",
        "Длительность",
    )
    for col in _int_day_cols:
        if col in summary_display.columns:
            summary_display[col] = summary_display[col].apply(_format_int_days)
    for col in _int_day_cols:
        if col in summary_numeric.columns:
            # В styled st.dataframe nullable Int64 может визуально «прятать» значения.
            # Держим стандартный numeric dtype с NaN для стабильного рендера.
            summary_numeric[col] = (
                pd.to_numeric(summary_numeric[col], errors="coerce")
                .round(0)
            )

    def _render_dates_main_table():
        _render_plan_fact_dates_main_table(summary_display, summary_numeric)

    _pf_n_after_filters = len(df_after_hide)
    if dates_show_reason_notes:
        _pf_maket_src = df_after_hide.copy()
        _pf_reason_col = _gantt_resolve_reason_column(_pf_maket_src)
        if _pf_reason_col and _pf_reason_col != "reason of deviation":
            _pf_maket_src = _pf_maket_src.rename(
                columns={_pf_reason_col: "reason of deviation"}
            )
        _pf_n_table = len(_deviations_maket_prepare_df(_pf_maket_src))
    else:
        _pf_maket_src = None
        _pf_n_table = len(summary_source_df)
    _pf_n_chart = len(chart_df)
    _pf_chart_cap = 400

    def _pf_dates_scope_caption() -> str:
        parts = [
            f"Таблица: {_pf_n_table} задач из {_pf_n_after_filters} после фильтров."
        ]
        if _pf_n_chart > _pf_chart_cap:
            parts.append(
                f"График: до {min(_pf_n_chart, _pf_chart_cap)} из {_pf_n_chart} "
                f"(лимит {_pf_chart_cap} строк)."
            )
        elif _pf_n_chart != _pf_n_table and not dates_show_reason_notes:
            parts.append(f"График: {_pf_n_chart} задач.")
        if not dates_show_reason_notes:
            parts.append("В таблице — только строки с отклонением окончания < 0.")
        if only_negative_dev_dates:
            parts.append("На графике — только отклонение окончания < 0.")
        if dates_show_reason_notes:
            parts.append(
                f"График и таблица: {_pf_n_table} задач (один набор по макету)."
            )
            parts.append(
                "Режим «Причины отклонений»: только уровень 5, заполненная причина, отклонение < 0; "
                "сортировка по отклонению (максимальное сверху). «Детализация» не действует."
            )
        elif _mask_lvl_col:
            parts.append(f"Детализация: {selected_level}.")
        parts.append("Сортировка: клик по заголовку колонки.")
        return " ".join(parts)

    if not show_covenant_ui:
        if dates_show_reason_notes:
            st.subheader("Причины отклонений (таблица)")
            suppress_caption(_pf_dates_scope_caption())
            _render_deviations_maket_table(
                _pf_maket_src,
                dates_building_col,
                dates_notes_col,
                file_stem="plan_fact_reasons_maket",
                key_prefix="pf_reasons_maket",
            )
        else:
            st.subheader("Отклонение от базового плана (таблица)")
            suppress_caption(_pf_dates_scope_caption())
            _render_dates_main_table()
    else:
        with st.expander("Полная таблица отклонений по всем задачам фильтра", expanded=True):
            _render_dates_main_table()


# ==================== DASHBOARD 4: Deviation Amount by Tasks ====================
def dashboard_deviation_by_tasks_current_month(df):
    # Проверка на None или пустой DataFrame
    if df is None:
        st.warning(
            "Нет данных для отображения. Пожалуйста, загрузите данные проекта."
        )
        return

    # Проверка, что df является DataFrame и имеет атрибут columns
    if not hasattr(df, "columns") or df.empty:
        st.warning(
            "Нет данных для отображения. Пожалуйста, загрузите данные проекта."
        )
        return

    ensure_msp_hierarchy_columns(df)


    find_column = _dev_tasks_find_column

    project_col = (
        "project name"
        if "project name" in df.columns
        else find_column(df, ["Проект", "project"])
    )
    if not project_col:
        st.warning("Поле 'project name' / 'Проект' не найдено в данных.")
        return

    all_projects = _unique_project_labels_for_select(df[project_col])
    if not all_projects:
        st.warning("Проекты не найдены в данных.")
        return

    with filters_panel(st, reset_keys=[
        "deviation_tasks_project", "deviation_tasks_block_l2", "deviation_tasks_building_l3",
        "deviation_tasks_detail_lvl", "deviation_tasks_block_col", "deviation_tasks_building_col",
    ]):
        f_proj, f_block, f_build, f_det = st.columns(4, gap="small")
        with f_proj:
            projects = ["Все"] + all_projects
            selected_project = st.selectbox(
                "Проект", projects, key="deviation_tasks_project"
            )

        base = df.copy()
        if selected_project != "Все" and project_col in base.columns:
            base = base[
                base[project_col].map(_project_filter_norm_key)
                == _project_filter_norm_key(selected_project)
            ]

        level_col = _dev_tasks_resolve_level_column(base)
        task_col = (
            "task name"
            if "task name" in base.columns
            else find_column(base, ["Задача", "task", "Task Name", "Название"])
        )
        if not task_col:
            st.warning("Поле 'task name' / «Задача» не найдено в данных.")
            return

        work_h = _dev_tasks_build_ancestor_keys(base, level_col, task_col)

        selected_block = "Все"
        selected_building = "Все"
        target_lvl = None

        if level_col and level_col in work_h.columns:
            ln = pd.to_numeric(work_h[level_col], errors="coerce")
            _blk_tier_d, _bld_tier_d = _deviations_msp_tier_levels(ln)
            block_opts = ["Все"] + sorted(
                work_h.loc[ln == float(_blk_tier_d), task_col]
                .dropna()
                .astype(str)
                .str.strip()
                .unique()
                .tolist()
            )
            if len(block_opts) <= 1 and "_dt_lvl2_key" in work_h.columns:
                _k2d = work_h["_dt_lvl2_key"].astype(str).str.strip()
                _k2d = _k2d[_k2d.ne("") & _k2d.str.lower().ne("nan")]
                if len(_k2d):
                    block_opts = ["Все"] + sorted(pd.unique(_k2d).tolist())
            with f_block:
                selected_block = st.selectbox(
                    "Функциональный блок",
                    block_opts,
                    key="deviation_tasks_block_l2",
                )
            w3 = work_h[ln == float(_bld_tier_d)]
            if selected_block != "Все":
                w3 = w3[
                    w3["_dt_lvl2_key"].astype(str).str.strip()
                    == str(selected_block).strip()
                ]
            build_opts = ["Все"] + sorted(
                w3[task_col].dropna().astype(str).str.strip().unique().tolist()
            )
            if len(build_opts) <= 1 and selected_block != "Все" and "_dt_lvl3_key" in w3.columns:
                _k3d = w3["_dt_lvl3_key"].astype(str).str.strip()
                _k3d = _k3d[_k3d.ne("") & _k3d.str.lower().ne("nan")]
                if len(_k3d):
                    build_opts = ["Все"] + sorted(pd.unique(_k3d).tolist())
            with f_build:
                selected_building = st.selectbox(
                    "Строение",
                    build_opts,
                    key="deviation_tasks_building_l3",
                )
            detail_opts = ("Укрупнённо (уровень 4)", "Детально (уровень 5)")
            with f_det:
                detail_label = st.selectbox(
                    "Детализация",
                    detail_opts,
                    index=0,
                    key="deviation_tasks_detail_lvl",
                )
            target_lvl = 5 if "5" in str(detail_label) else 4
        else:
            with f_block:
                suppress_caption("Нет колонки уровня MSP")
            block_col_fb = find_column(
                base,
                ["block", "Блок", "Функциональный блок", "Functional block"],
            )
            with f_block:
                if block_col_fb and block_col_fb in base.columns:
                    bopts = ["Все"] + sorted(
                        base[block_col_fb].dropna().astype(str).str.strip().unique().tolist()
                    )
                    selected_block = st.selectbox(
                        "Функциональный блок",
                        bopts,
                        key="deviation_tasks_block_col",
                    )
                else:
                    selected_block = "Все"
            building_col_fb = find_column(
                base,
                ["building", "Строение", "строение", "Сооружение"],
            )
            with f_build:
                if building_col_fb and building_col_fb in base.columns:
                    gopts = ["Все"] + sorted(
                        base[building_col_fb].dropna().astype(str).str.strip().unique().tolist()
                    )
                    selected_building = st.selectbox(
                        "Строение",
                        gopts,
                        key="deviation_tasks_building_col",
                    )
                else:
                    selected_building = "Все"
            with f_det:
                suppress_caption("—")
            suppress_caption(
                "Колонка уровня MSP не найдена — блок/строение из отдельных колонок (если есть); "
                "режим «уровень 4 / 5» недоступен."
            )

    filtered_df = work_h.copy()
    if level_col and level_col in filtered_df.columns and target_lvl is not None:
        if selected_block != "Все":
            filtered_df = filtered_df[
                filtered_df["_dt_lvl2_key"].astype(str).str.strip()
                == str(selected_block).strip()
            ]
        if selected_building != "Все":
            filtered_df = filtered_df[
                filtered_df["_dt_lvl3_key"].astype(str).str.strip()
                == str(selected_building).strip()
            ]
        ln_f = pd.to_numeric(filtered_df["_dt_lvl_num"], errors="coerce")
        filtered_df = filtered_df[ln_f == float(target_lvl)]
    else:
        block_col_fb = find_column(
            filtered_df,
            ["block", "Блок", "Функциональный блок", "Functional block"],
        )
        building_col_fb = find_column(
            filtered_df,
            ["building", "Строение", "строение", "Сооружение"],
        )
        if selected_block != "Все" and block_col_fb and block_col_fb in filtered_df.columns:
            filtered_df = filtered_df[
                filtered_df[block_col_fb].astype(str).str.strip()
                == str(selected_block).strip()
            ]
        if selected_building != "Все" and building_col_fb and building_col_fb in filtered_df.columns:
            filtered_df = filtered_df[
                filtered_df[building_col_fb].astype(str).str.strip()
                == str(selected_building).strip()
            ]

    # Filter tasks: deviation=1/True OR reason of deviation filled
    try:
        has_deviation_col = "deviation" in filtered_df.columns
        has_reason_col = "reason of deviation" in filtered_df.columns
    except (AttributeError, TypeError):
        has_deviation_col = False
        has_reason_col = False

    if has_deviation_col or has_reason_col:
        if has_deviation_col:
            deviation_flag = (
                (filtered_df["deviation"] == True)
                | (filtered_df["deviation"] == 1)
                | (filtered_df["deviation"].astype(str).str.lower() == "true")
                | (filtered_df["deviation"].astype(str).str.strip() == "1")
            )
        else:
            deviation_flag = pd.Series(False, index=filtered_df.index)
        if has_reason_col:
            reason_filled = (
                filtered_df["reason of deviation"].notna()
                & (filtered_df["reason of deviation"].astype(str).str.strip() != "")
            )
        else:
            reason_filled = pd.Series(False, index=filtered_df.index)
        filtered_df = filtered_df[deviation_flag | reason_filled]
    else:
        st.warning("Поле 'deviation' или 'reason of deviation' не найдено в данных.")
        return

    if filtered_df.empty:
        st.info("Отклонения не найдены для выбранных фильтров.")
        return

    # Колонка задачи уже определена выше (по выборке проекта)
    has_task_col = task_col is not None and task_col in filtered_df.columns

    if project_col and has_task_col:
        # Convert deviation in days to numeric
        try:
            has_deviation_days_col = "deviation in days" in filtered_df.columns
        except (AttributeError, TypeError):
            has_deviation_days_col = False

        if has_deviation_days_col:
            filtered_df["deviation in days"] = pd.to_numeric(
                filtered_df["deviation in days"], errors="coerce"
            )

        # Подставляем колонки дат из русских названий, если их ещё нет
        ensure_date_columns(filtered_df)
        # Calculate completion percentage if dates are available
        try:
            has_plan_start = "plan start" in filtered_df.columns
            has_plan_end = "plan end" in filtered_df.columns
            has_base_start = "base start" in filtered_df.columns
            has_base_end = "base end" in filtered_df.columns
        except (AttributeError, TypeError):
            has_plan_start = False
            has_plan_end = False
            has_base_start = False
            has_base_end = False

        if has_plan_start and has_plan_end and has_base_start and has_base_end:
            # Convert dates to datetime
            for col in ["plan start", "plan end", "base start", "base end"]:
                filtered_df[col] = pd.to_datetime(
                    filtered_df[col], errors="coerce", dayfirst=True
                )

            # Calculate completion percentage:
            # (Планируемая дата окончания - планируемая дата начала) / (Фактическая дата окончания - фактическая дата начала) * 100
            filtered_df["plan_duration"] = (
                filtered_df["plan end"] - filtered_df["plan start"]
            ).dt.days
            filtered_df["fact_duration"] = (
                filtered_df["base end"] - filtered_df["base start"]
            ).dt.days

            # Calculate percentage: plan_duration / fact_duration * 100
            # Avoid division by zero
            filtered_df["completion_percent"] = (
                filtered_df["plan_duration"]
                / filtered_df["fact_duration"].replace(0, np.nan)
                * 100
            ).fillna(0)
            # Cap at reasonable values (0-200%)
            filtered_df["completion_percent"] = filtered_df["completion_percent"].clip(
                0, 200
            )
        else:
            filtered_df["completion_percent"] = None

        # Группировка по проекту (фильтр по этапу/section убран по ТЗ)
        group_by_cols = [project_col]
        y_column = "Проект"

        # Group data based on determined grouping level
        deviations = (
            filtered_df.groupby(group_by_cols)
            .agg(
                {
                    "deviation in days": (
                        "sum" if "deviation in days" in filtered_df.columns else "count"
                    ),
                    "completion_percent": (
                        "mean"
                        if "completion_percent" in filtered_df.columns
                        and filtered_df["completion_percent"].notna().any()
                        else lambda x: None
                    ),
                }
            )
            .reset_index()
        )

        # Set column names based on grouping level (только проект)
        if len(group_by_cols) == 2:
            deviations.columns = [
                "Проект",
                "Задача",
                "Суммарно дней отклонений",
                "Процент выполнения",
            ]
            deviations["Отображение"] = (
                deviations["Задача"] + " (" + deviations["Проект"] + ")"
            )
        else:
            deviations.columns = [
                "Проект",
                "Суммарно дней отклонений",
                "Процент выполнения",
            ]
            deviations["Отображение"] = deviations["Проект"]

        def _wrap_label_dev(text, max_len=30, max_total=60):
            s = str(text)
            if len(s) > max_total:
                s = s[:max_total - 1] + "…"
            words = s.split(" ")
            lines, current = [], ""
            for word in words:
                if len(current) + len(word) + 1 > max_len:
                    lines.append(current)
                    current = word
                else:
                    current = (current + " " + word).strip()
            if current:
                lines.append(current)
            return "<br>".join(lines[:3])

        deviations["Отображение"] = deviations["Отображение"].apply(_wrap_label_dev)

        # If completion percent calculation failed, set to None
        if "Процент выполнения" in deviations.columns:
            deviations["Процент выполнения"] = pd.to_numeric(
                deviations["Процент выполнения"], errors="coerce"
            )

        # Числовая ось: убирает ошибочный масштаб и «пустое» поле справа на гориз. bar
        deviations["Суммарно дней отклонений"] = pd.to_numeric(
            deviations["Суммарно дней отклонений"], errors="coerce"
        ).fillna(0)

        # Sort by deviation amount (descending - largest first)
        deviations = deviations.sort_values("Суммарно дней отклонений", ascending=False)

        if deviations.empty:
            st.info("Нет данных для отображения.")
            return

        # Checkboxes row 2: Top 5 and Completion percentage
        col5, col6 = st.columns(2, gap="small")

        with col5:
            # Checkbox for Top 5 filter
            show_top5 = st.checkbox(
                "Топ 5 отклонений", value=False, key="show_top5_deviations"
            )

        with col6:
            # Checkbox to show/hide completion percentage
            show_completion = st.checkbox(
                "Показывать процент выполнения",
                value=False,
                key="show_completion_percent",
            )

        # Apply Top 5 filter if enabled
        if show_top5:
            deviations = deviations.head(5)

        # Visualization - horizontal bar chart
        deviations = _limit_bar_categories(
            deviations, "Суммарно дней отклонений", max_bars=50, label="проектов"
        )
        # Format text for display on bars
        text_values = []
        for _, row in deviations.iterrows():
            if show_completion and pd.notna(row.get("Процент выполнения")):
                text_values.append(
                    f"{int(round(row['Суммарно дней отклонений'], 0))} ({row['Процент выполнения']:.1f}%)"
                )
            else:
                text_values.append(f"{int(round(row['Суммарно дней отклонений'], 0))}")

        fig = px.bar(
            deviations,
            x="Суммарно дней отклонений",
            y="Отображение",
            orientation="h",
            title=None,
            labels={
                "Суммарно дней отклонений": "Суммарно дней отклонений",
                "Отображение": y_column,
            },
            text=text_values,
            color_discrete_sequence=["#1f77b4"],  # Blue color for all bars
        )

        # Set category order to show largest values at top (descending order)
        # For horizontal bars, reverse the list so largest is at top
        category_list = deviations["Отображение"].tolist()
        fig.update_layout(
            showlegend=False,
            yaxis=dict(
                categoryorder="array",
                categoryarray=list(
                    reversed(category_list)
                ),  # Reverse to show largest at top
            ),
        )
        fig.update_traces(
            textposition="outside", textfont=dict(size=14, color="white"),
            cliponaxis=False,
        )

        fig = apply_chart_background(fig)
        max_line_len = max(
            max(len(line) for line in s.split("<br>"))
            for s in deviations["Отображение"].tolist()
        ) if not deviations.empty else 20
        left_margin = min(max_line_len * 8, 400)
        fig.update_layout(
            height=max(350, len(deviations) * 80),
            margin=dict(l=left_margin, r=10, t=40, b=80),
            xaxis=dict(range=_xaxis_range_positive(deviations["Суммарно дней отклонений"])),
        )
        fig = _apply_bar_uniformtext(fig)
        render_chart(fig, caption_below=report_chart_caption_body("Отклонение от базового плана"))

        render_table_subheader(st, "Отклонение от базового плана по задачам")

        detail_df = filtered_df.copy()

        if detail_df.empty:
            st.info("Нет данных для отображения детализации.")
        else:
            # Convert deviation in days to numeric
            if "deviation in days" in detail_df.columns:
                detail_df["deviation in days"] = pd.to_numeric(
                    detail_df["deviation in days"], errors="coerce"
                )

            if "task name" in detail_df.columns:
                detail_deviations = (
                    detail_df.groupby(["task name"])
                    .agg(
                        {
                            "deviation in days": (
                                "sum"
                                if "deviation in days" in detail_df.columns
                                else "count"
                            )
                        }
                    )
                    .reset_index()
                )

                detail_deviations.columns = [
                    "Задача",
                    "Суммарно дней отклонений",
                ]
                detail_deviations["Отображение"] = detail_deviations["Задача"]

                def _wrap_label(text, max_len=30, max_total=60):
                    s = str(text)
                    if len(s) > max_total:
                        s = s[:max_total - 1] + "…"
                    words = s.split(" ")
                    lines, current = [], ""
                    for word in words:
                        if len(current) + len(word) + 1 > max_len:
                            lines.append(current)
                            current = word
                        else:
                            current = (current + " " + word).strip()
                    if current:
                        lines.append(current)
                    return "<br>".join(lines[:3])

                detail_deviations["Отображение"] = detail_deviations["Отображение"].apply(_wrap_label)

                # Не выводить отрицательные значения на графике
                detail_deviations = detail_deviations[
                    detail_deviations["Суммарно дней отклонений"] >= 0
                ]

                # Sort by deviation amount (descending)
                detail_deviations = detail_deviations.sort_values(
                    "Суммарно дней отклонений", ascending=False
                )

                # Create horizontal bar chart (только неотрицательные)
                if detail_deviations.empty:
                    st.info("Нет неотрицательных отклонений для детализации.")
                else:
                    detail_deviations["Суммарно дней отклонений"] = pd.to_numeric(
                        detail_deviations["Суммарно дней отклонений"], errors="coerce"
                    ).fillna(0)
                    table_display = detail_deviations[["Задача", "Суммарно дней отклонений"]].copy()
                    table_display["Суммарно дней отклонений"] = table_display["Суммарно дней отклонений"].apply(
                        lambda x: int(round(x, 0)) if pd.notna(x) else 0
                    )
                    table_display = table_display.sort_values("Суммарно дней отклонений", ascending=False)
                    suppress_caption(f"Записей: {len(table_display)}")
                    _render_html_table(
                        table_display,
                        column_tooltips={
                            str(c): str(c) for c in table_display.columns
                        },
                    )
                    fig_detail = px.bar(
                        detail_deviations,
                        x="Суммарно дней отклонений",
                        y="Отображение",
                        orientation="h",
                        title=None,
                        labels={
                            "Суммарно дней отклонений": "Суммарно дней отклонений",
                            "Отображение": "Задача",
                        },
                        text=detail_deviations["Суммарно дней отклонений"].apply(
                            lambda x: f"{int(round(x, 0))}" if pd.notna(x) else ""
                        ),
                        color_discrete_sequence=["#1f77b4"],
                    )

                    category_list_detail = detail_deviations["Отображение"].tolist()
                    fig_detail.update_layout(
                        showlegend=False,
                        yaxis=dict(
                            categoryorder="array",
                            categoryarray=list(reversed(category_list_detail)),
                        ),
                        height=max(400, len(detail_deviations) * 80),
                    )
                    fig_detail.update_traces(
                        textposition="outside", textfont=dict(size=12, color="white"),
                        cliponaxis=False,
                    )

                    fig_detail = _apply_bar_uniformtext(fig_detail)
                    fig_detail = apply_chart_background(fig_detail)
                    max_line_len = max(
                        max(len(line) for line in s.split("<br>"))
                        for s in detail_deviations["Отображение"].tolist()
                    ) if not detail_deviations.empty else 20
                    left_margin = min(max_line_len * 8, 400)
                    fig_detail.update_layout(
                        margin=dict(l=left_margin, r=10, t=40, b=80),
                        xaxis=dict(
                            range=_xaxis_range_positive(
                                detail_deviations["Суммарно дней отклонений"]
                            )
                        ),
                    )
                    render_chart(
                        fig_detail,
                        caption_below=report_chart_caption_body(
                            "Отклонение от базового плана", granularity="по задачам"
                        ),
                    )
            else:
                st.warning("Поле 'task name' не найдено для детализации.")
    else:
        st.warning(
            "Необходимые поля 'project name' или 'task name' не найдены в данных."
        )


# ==================== DASHBOARD 5: Dynamics of Reasons by Month ====================
def dashboard_dynamics_of_reasons(df, hide_shared_filters=False):
    # Проверка на None или пустой DataFrame
    if df is None:
        st.warning(
            "Нет данных для отображения. Пожалуйста, загрузите данные проекта."
        )
        return

    # Проверка, что df является DataFrame и имеет атрибут columns
    if not hasattr(df, "columns") or df.empty:
        st.warning(
            "Нет данных для отображения. Пожалуйста, загрузите данные проекта."
        )
        return

    if "project name" in df.columns:
        df = _project_column_apply_canonical(df.copy(), "project name")

    # При hide_shared_filters проект/этап/причина задаются общими фильтрами выше; без значений по умолчанию — NameError в ветках «По месяцам».
    selected_project = "Все"
    selected_reason = "Все"
    selected_section = "Все"
    selected_building_r = "Все"
    _bld_col = None

    if not hide_shared_filters:
        st.header("Динамика причин отклонений по месяцам")

    if hide_shared_filters:
        period_type = str(st.session_state.get("dynamics_period", "Месяц") or "Месяц")
        period_type_en = _deviations_period_type_en_from_ru(period_type)
        view_type = str(
            st.session_state.get("reasons_view_type", "По причинам") or "По причинам"
        )
        show_trend_line = bool(
            st.session_state.get("reasons_dynamics_show_trend_line", False)
        )
    else:
        with filters_panel(st, reset_keys=[
            "reasons_period", "reasons_reason", "reasons_project", "reasons_building",
            "reasons_view_type", "reasons_dynamics_show_trend_line",
        ]):
            col1, col2, col3, col4 = st.columns(4, gap="small")

            with col1:
                period_type = st.selectbox(
                    "Группировать по", ["Месяц", "Квартал", "Год"], key="reasons_period"
                )
                period_map = {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year"}
                period_type_en = period_map.get(period_type, "Month")

            with col2:
                try:
                    has_reason_column = "reason of deviation" in df.columns
                except (AttributeError, TypeError):
                    has_reason_column = False

                if has_reason_column:
                    reasons = ["Все"] + sorted(
                        df["reason of deviation"].dropna().unique().tolist()
                    )
                    selected_reason = st.selectbox(
                        "Причина", reasons, key="reasons_reason"
                    )
                else:
                    selected_reason = "Все"

            with col3:
                try:
                    has_project_column = "project name" in df.columns
                except (AttributeError, TypeError):
                    has_project_column = False

                if has_project_column:
                    projects = ["Все"] + _project_name_select_options(df["project name"])
                    _session_reset_project_if_excluded(
                        "reasons_project", allowed_labels=projects
                    )
                    selected_project = st.selectbox(
                        "Проект", projects, key="reasons_project"
                    )
                else:
                    selected_project = "Все"

            with col4:
                _bld_col = _find_column_by_keywords(
                    df, ("building", "строение", "лот", "lot", "bldg")
                )
                if _bld_col and _bld_col in df.columns:
                    _bld_opts = ["Все"] + sorted(
                        df[_bld_col]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .unique()
                        .tolist()
                    )
                    selected_building_r = st.selectbox(
                        "Строение", _bld_opts, key="reasons_building"
                    )
                else:
                    _bld_col = None
                    selected_building_r = "Все"
            selected_section = "Все"

            view_type = st.selectbox(
                "Вид отображения", ["По причинам", "По месяцам"], key="reasons_view_type"
            )
            if view_type == "По месяцам":
                show_trend_line = st.checkbox(
                    "Показывать линию тренда",
                    value=False,
                    key="reasons_dynamics_show_trend_line",
                )
            else:
                show_trend_line = False

    filtered_df = df.copy()

    if not hide_shared_filters:
        try:
            has_reason_col = "reason of deviation" in df.columns
        except (AttributeError, TypeError):
            has_reason_col = False

        if selected_reason != "Все" and has_reason_col:
            filtered_df = filtered_df[
                filtered_df["reason of deviation"].astype(str).str.strip()
                == str(selected_reason).strip()
            ]

        try:
            has_project_col = "project name" in filtered_df.columns
        except (AttributeError, TypeError):
            has_project_col = False

        if selected_project != "Все" and has_project_col:
            filtered_df = _deviations_filter_df_by_project_name(
                filtered_df, selected_project
            )

        # «Строение» вместо «Этап» (R23-04 page_9 item 2).
        if (
            selected_building_r != "Все"
            and _bld_col
            and _bld_col in filtered_df.columns
        ):
            filtered_df = filtered_df[
                filtered_df[_bld_col].astype(str).str.strip()
                == str(selected_building_r).strip()
            ]

    # Filter tasks: deviation=1/True OR reason of deviation filled
    try:
        has_deviation_col = "deviation" in filtered_df.columns
        has_reason_col = "reason of deviation" in filtered_df.columns
    except (AttributeError, TypeError):
        has_deviation_col = False
        has_reason_col = False

    if has_deviation_col or has_reason_col:
        if has_deviation_col:
            deviation_flag = (
                (filtered_df["deviation"] == True)
                | (filtered_df["deviation"] == 1)
                | (filtered_df["deviation"].astype(str).str.lower() == "true")
                | (filtered_df["deviation"].astype(str).str.strip() == "1")
            )
        else:
            deviation_flag = pd.Series(False, index=filtered_df.index)
        if has_reason_col:
            reason_filled = (
                filtered_df["reason of deviation"].notna()
                & (filtered_df["reason of deviation"].astype(str).str.strip() != "")
            )
        else:
            reason_filled = pd.Series(False, index=filtered_df.index)
        filtered_df = filtered_df[deviation_flag | reason_filled]

    if filtered_df.empty:
        st.info("Нет данных для выбранных фильтров.")
        return

    # Determine period column - use plan_month for month grouping
    try:
        has_plan_end_col = "plan end" in filtered_df.columns
    except (AttributeError, TypeError):
        has_plan_end_col = False

    if period_type_en == "Month":
        period_col = "plan_month"
        period_label = "Месяц"
        # If plan_month doesn't exist, try to create it from plan end
        try:
            has_period_col = period_col in filtered_df.columns
        except (AttributeError, TypeError):
            has_period_col = False

        if not has_period_col and has_plan_end_col:
            mask = filtered_df["plan end"].notna()
            filtered_df.loc[mask, period_col] = filtered_df.loc[
                mask, "plan end"
            ].dt.to_period("M")
    elif period_type_en == "Quarter":
        period_col = "plan_quarter"
        period_label = "Квартал"
        try:
            has_period_col = period_col in filtered_df.columns
        except (AttributeError, TypeError):
            has_period_col = False

        if not has_period_col and has_plan_end_col:
            mask = filtered_df["plan end"].notna()
            filtered_df.loc[mask, period_col] = filtered_df.loc[
                mask, "plan end"
            ].dt.to_period("Q")
    else:
        period_col = "plan_year"
        period_label = "Год"
        try:
            has_period_col = period_col in filtered_df.columns
        except (AttributeError, TypeError):
            has_period_col = False

        if not has_period_col and has_plan_end_col:
            mask = filtered_df["plan end"].notna()
            filtered_df.loc[mask, period_col] = filtered_df.loc[
                mask, "plan end"
            ].dt.to_period("Y")

    if period_col not in filtered_df.columns:
        st.warning(f"Столбец периода '{period_col}' не найден.")
        return

    filtered_df = _deviations_exclude_future_plan_rows(
        filtered_df, period_type_en=period_type_en
    )
    if filtered_df.empty:
        st.info("Нет данных для выбранных фильтров.")
        return

    # Group by period and категория причины (как «Доли причин» / «Динамика отклонений» — _deviations_reason_bucket_label)
    if "reason of deviation" in filtered_df.columns:
        _rd_slice = filtered_df[filtered_df[period_col].notna()].copy()
        _rd_slice["_reason_bucket"] = _rd_slice["reason of deviation"].map(
            _deviations_reason_bucket_label
        )
        reason_dynamics = (
            _rd_slice.groupby([period_col, "_reason_bucket"])
            .size()
            .reset_index(name="Количество")
        )

        reason_dynamics[period_col] = reason_dynamics[period_col].apply(format_period_ru)

        reason_dynamics = (
            reason_dynamics.groupby([period_col, "_reason_bucket"])["Количество"]
            .sum()
            .reset_index()
        )

        # В комбинированном отчёте selected_project не заполняется — для веток графика «По месяцам» берём devcombo_project
        chart_project_scope = (
            st.session_state.get("devcombo_project", "Все")
            if hide_shared_filters
            else selected_project
        )

        _reason_clr = _deviations_reason_bucket_colors()
        _reason_ord = list(DEVIATIONS_REASON_BUCKET_ORDER)

        # Build visualization based on view type
        if view_type == "По причинам":
            # View 1: By reasons - reason on X-axis, count on Y-axis
            # Group by reason and sum across all periods
            reason_summary = (
                reason_dynamics.groupby("_reason_bucket")["Количество"]
                .sum()
                .reset_index()
            )
            reason_summary = reason_summary.sort_values("Количество", ascending=False)
            reason_summary = reason_summary.drop_duplicates(
                subset=["_reason_bucket"], keep="first"
            )

            # Visualization - vertical bar chart with reasons on X-axis
            fig = px.bar(
                reason_summary,
                x="_reason_bucket",
                y="Количество",
                title=None,
                labels={
                    "_reason_bucket": "Причина отклонения",
                    "Количество": "Количество отклонений",
                },
                text="Количество",
                color="_reason_bucket",
                color_discrete_map=_reason_clr or None,
            )
            # fig.update_xaxes(tickangle=-45)
            # fig.update_traces(
            #     textposition="outside", textfont=dict(size=12, color="white")
            # )
            fig.update_xaxes(
                tickangle=-40,
                title_text="",
                automargin=True,
                tickfont=dict(size=12),
            )
            fig.update_traces(
                texttemplate="%{text}",
                textposition="outside",
                outsidetextfont=dict(size=12, color="white"),
            )
            fig = _apply_finance_bar_label_layout(fig)
            n_rs = int(len(reason_summary))
            _ymax_rs = float(
                pd.to_numeric(reason_summary["Количество"], errors="coerce").max() or 0.0
            )
            _y_top_rs = max(1.0, _ymax_rs * 1.45 + 12.0)
            # R23-04 follow-up (user screenshot): легенда в «По причинам» избыточна —
            # каждая категория уже есть на оси X; горизонтальная легенда снизу накладывается
            # с подписями оси. Скрываем легенду полностью в этом режиме.
            _gdrs_gap_rs = _plotly_bargaps_sparse_x_like_gdrs(n_rs)
            _ly_rs = dict(
                height=max(520, int(180 + n_rs * 52)),
                margin=dict(l=28, r=220, t=110, b=246),
                yaxis=dict(
                    range=[0, _y_top_rs],
                    title="Количество отклонений",
                    automargin=True,
                ),
                xaxis=dict(automargin=True, title_standoff=16),
                showlegend=True,
                legend=standard_chart_legend(title=dict(text="Причины отклонений"), font=dict(size=11, color="#e8eef5")),
            )
            if _gdrs_gap_rs:
                _ly_rs.update(_gdrs_gap_rs)
            else:
                _ly_rs["bargap"] = min(
                    0.62, float(max(0.35, 0.82 - n_rs * 0.065))
                )
                _ly_rs["bargroupgap"] = 0.06
            fig.update_layout(**_ly_rs)
        else:
            # View 2: By months - month on X-axis, count on Y-axis, reasons as colors (stacked)
            # If "Все" projects selected, show aggregated view (one column per period)
            if chart_project_scope == "Все":
                # For chart: group only by period (sum all reasons)
                chart_data = (
                    reason_dynamics.groupby(period_col)["Количество"]
                    .sum()
                    .reset_index()
                )
                chart_data["reason of deviation"] = (
                    "Все проекты"  # Dummy column for consistency
                )

                # Visualization - vertical bar chart with single column per period
                fig = px.bar(
                    chart_data,
                    x=period_col,
                    y="Количество",
                    title=None,
                    labels={
                        period_col: period_label,
                        "Количество": "Количество отклонений",
                    },
                    text="Количество",
                    color_discrete_sequence=["#1f77b4"],  # Single color for all bars
                )
                # R23-04 follow-up (user screenshot): при одной синей серии имя трейса
                # (period_col, напр. «Месяц») висит в горизонтальной легенде снизу и
                # накладывается на «Линия тренда». Убираем его из легенды —
                # остаётся только подпись линии тренда, когда она включена.
                try:
                    fig.update_traces(
                        selector=dict(type="bar"), showlegend=False
                    )
                except Exception:
                    pass
            else:
                # Visualization - vertical bar chart with stacked reasons
                # Use period_col for x-axis and reason for color (legend)
                # Use stacked mode to show all reasons in one column per period
                fig = px.bar(
                    reason_dynamics,
                    x=period_col,
                    y="Количество",
                    color="_reason_bucket",
                    title=None,
                    labels={
                        period_col: period_label,
                        "_reason_bucket": "Причина отклонения",
                        "Количество": "Количество отклонений",
                    },
                    text="Количество",
                    color_discrete_map=_reason_clr or None,
                    category_orders={"_reason_bucket": _reason_ord},
                    barmode="stack",  # Stacked bars: all reasons in one column per period
                )
        # Update layout based on view type
        if view_type == "По причинам":
            # For "По причинам" view, no additional annotations needed
            pass
        else:
            # For "По месяцам" view, add annotations and trend line
            fig.update_xaxes(tickangle=-45)
            # R23-04 follow-up (user screenshot): подпись оси X («Месяц»/«Квартал»/«Год»)
            # ложилась вплотную к горизонтальной легенде снизу и визуально сливалась с
            # «— Линия тренда». Сами значения оси X и так самоописывающие («Август 2026»…),
            # поэтому отдельная подпись оси X здесь не нужна — убираем.
            try:
                fig.update_xaxes(title_text="")
                # Отодвигаем легенду ещё ниже оси X и увеличиваем нижнее поле,
                # чтобы «Линия тренда» и подписи месяцев гарантированно не пересекались.
                fig.update_layout(
                    showlegend=True,
                    margin=dict(l=56, r=36, t=72, b=208),
                    legend=standard_chart_legend(
                        title=dict(text="Причины отклонений"),
                        font=dict(size=11, color="#e8eef5"),
                    ),
                )
            except Exception:
                pass
            # Подписи сегментов: только столбец text=… (без дубля из %{y}).
            fig.update_traces(
                texttemplate="%{text}",
                textposition="inside",
                textangle=0,
                cliponaxis=False,
                selector=dict(type="bar"),
            )

            try:
                for tr in fig.data:
                    if getattr(tr, "type", None) != "bar":
                        continue
                    mc = getattr(tr.marker, "color", None)
                    if isinstance(mc, str):
                        tc = _deviations_contrast_text_on_fill(mc)
                        tr.update(
                            textfont=dict(color=tc, size=12),
                            insidetextfont=dict(color=tc, size=12),
                        )
            except Exception:
                pass

            try:
                _nx_rr = _plotly_n_x_categories_from_bar_figure(fig)
                _g_mr = (
                    _plotly_bargaps_sparse_x_like_gdrs(_nx_rr)
                    if _nx_rr is not None and _nx_rr > 0
                    else {}
                )
                if _g_mr:
                    fig.update_layout(**_g_mr)
                else:
                    fig.update_layout(bargap=0.38, bargroupgap=0.05)
            except Exception:
                pass
            if chart_project_scope == "Все":
                # For "Все проекты": use chart_data for annotations and trend
                total_by_period = (
                    chart_data.groupby(period_col)["Количество"].sum().reset_index()
                )
                periods = sorted(chart_data[period_col].unique())
                max_y_value = chart_data["Количество"].max()
            else:
                # Calculate total deviations per period for annotations
                total_by_period = (
                    reason_dynamics.groupby(period_col)["Количество"]
                    .sum()
                    .reset_index()
                )
                total_by_period_dict = dict(
                    zip(total_by_period[period_col], total_by_period["Количество"])
                )
                periods = sorted(reason_dynamics[period_col].unique())
                max_y_value = reason_dynamics["Количество"].max()

                # Add annotations for individual project view
                for period in periods:
                    total = total_by_period_dict.get(period, 0)
                    if total > 0:
                        # Get all bars for this period to find max height
                        period_bars = reason_dynamics[
                            reason_dynamics[period_col] == period
                        ]
                        if not period_bars.empty:
                            # Find the maximum height among all bars in this period group
                            max_bar_height = period_bars["Количество"].max()

                            # Calculate offset
                            if max_y_value > 0:
                                y_offset = max_y_value * 0.10
                            else:
                                y_offset = max_bar_height * 0.10

                            # Position annotation
                            x_position = period
                            y_position = max_bar_height + y_offset

                            fig.add_annotation(
                                x=x_position,
                                y=y_position,
                                text=f"<b>{int(round(total, 0))}</b>",
                                showarrow=False,
                                font=dict(size=14, color="white"),
                                xanchor="center",
                                yanchor="bottom",
                                bgcolor="rgba(0,0,0,0.5)",
                                xshift=10,
                            )

            # Add trend line if checkbox is checked (use chart's x order so line aligns with bars)
            if show_trend_line and len(fig.data) > 0:
                x_order = list(fig.data[0].x)
                if len(x_order) > 1:
                    total_by_period_idx = total_by_period.set_index(period_col)
                    y_values = total_by_period_idx.reindex(x_order)["Количество"].values
                    y_values = np.nan_to_num(y_values, nan=0.0)

                    x_numeric = np.arange(len(y_values))
                    z = np.polyfit(x_numeric, y_values, 1)
                    p = np.poly1d(z)
                    trend_y = p(x_numeric)

                    fig.add_trace(
                        go.Scatter(
                            x=x_order,
                            y=trend_y,
                            mode="lines",
                            name="Линия тренда",
                            line=dict(dash="dash", width=3, color="white"),
                            showlegend=True,
                            hoverinfo="skip",
                        )
                    )

        fig = _apply_bar_uniformtext(fig)
        fig = apply_chart_background(fig)
        if view_type == "По причинам":
            fig.update_layout(
                showlegend=True,
                margin=dict(l=28, r=220, t=110, b=246),
                legend=standard_chart_legend(title=dict(text="Причины отклонений"), font=dict(size=11, color="#e8eef5")),
            )
            if chart_project_scope != "Все":
                # Подпись графика — чистое название проекта (без префикса «Проект=…»).
                _deviations_plotly_project_chart_title(fig, chart_project_scope)
        elif view_type == "По месяцам" and chart_project_scope != "Все":
            fig.update_layout(showlegend=True)
            # Подпись графика — чистое название проекта (без префикса «Проект=…»),
            # чтобы было видно, к какому проекту относится диаграмма.
            _deviations_plotly_project_chart_title(fig, chart_project_scope)
        render_chart(fig, caption_below=None)

        # Summary table - always show by reason (summarized values)
        # Group by reason and sum across all periods
        summary_by_reason = (
            reason_dynamics.groupby("_reason_bucket")["Количество"]
            .sum()
            .reset_index()
        )
        summary_by_reason.columns = ["Причина отклонения", "Суммарное количество"]
        summary_by_reason = summary_by_reason.sort_values(
            "Суммарное количество", ascending=False
        )

        render_table_subheader(
            st,
            report_title_name("Динамика отклонений", format_report_granularity_label(period_label)),
        )
        st.markdown(f"**Записей:** {len(summary_by_reason)}")
        _render_html_table(
            summary_by_reason,
            column_tooltips={str(c): str(c) for c in summary_by_reason.columns},
        )
    else:
        st.warning("Столбец 'reason of deviation' не найден в данных.")


