def _finance_table_html_kwargs(base: dict | None = None, **overrides) -> dict:
    kw = dict(base or _BDDS_TABLE_HTML_KW)
    kw.update(overrides)
    try:
        from dashboards.light_theme import is_light_preview_active

        if is_light_preview_active():
            kw.pop("total_row_bg_color", None)
            kw.pop("total_row_font_css", None)
    except Exception:
        pass
    return kw


# Минимум оборотов (руб.) для месяца на графике БДДС/БДР — иначе ось забивается «пустыми» месяцами.
_FINANCE_CHART_MIN_MONTH_RUB = 500_000.0
_BDDS_CHART_MIN_MONTH_RUB = _FINANCE_CHART_MIN_MONTH_RUB


def _finance_plotly_bar_layout(n_periods: int) -> tuple[float, float, float]:
    """bargap, bargroupgap, trace width для grouped bar chart (БДДС / БДР)."""
    n = max(1, int(n_periods))
    if n <= 8:
        return 0.20, 0.06, 0.72
    if n <= 14:
        return 0.16, 0.05, 0.58
    if n <= 24:
        return 0.12, 0.04, 0.48
    if n <= 36:
        return 0.10, 0.035, 0.40
    return 0.08, 0.03, max(0.32, min(0.55, 20.0 / n))


_bdds_plotly_bar_layout = _finance_plotly_bar_layout


_FINANCE_BAR_PX_PER_MONTH = 140


_FINANCE_BAR_SCROLL_VP_PX = 1420
_FINANCE_BAR_CANVAS_PAD_PX = 96


def _finance_plotly_xaxis_category_pad(fig, n_periods: int, *, pad_end: float = 1.12) -> None:
    """Правый/левый запас по категориям — grouped bar + outside labels не обрезаются."""
    n = max(1, int(n_periods))
    try:
        fig.update_xaxes(range=[-0.58, (n - 1) + float(pad_end)], autorange=False)
        _m = fig.layout.margin
        fig.update_layout(
            margin=dict(
                l=int(getattr(_m, "l", None) or 56),
                r=max(int(getattr(_m, "r", None) or 36), 88),
                t=int(getattr(_m, "t", None) or 68),
                b=int(getattr(_m, "b", None) or 120),
            )
        )
    except Exception:
        pass


def _finance_plotly_canvas_width(
    n_periods: int,
    *,
    px_per_month: int | None = None,
    force_hscroll: bool = False,
    max_width: int = 12000,
) -> tuple[bool, int]:
    """
    (need_hscroll, width_px).
    Пока ряд помещается во viewport — st.plotly_chart на всю ширину;
    иначе фиксированная ширина + гориз. скролл (components.html).
    """
    n = max(1, int(n_periods))
    vp = int(_FINANCE_BAR_SCROLL_VP_PX)
    pad = int(_FINANCE_BAR_CANVAS_PAD_PX)
    px = int(px_per_month if px_per_month is not None else _FINANCE_BAR_PX_PER_MONTH)
    _cap = int(max(max_width, vp))
    content_w = n * px + pad
    if force_hscroll:
        if content_w <= vp:
            px = max(px, int((vp + pad + 40) / n) + 1)
            content_w = n * px + pad
        return True, int(min(_cap, content_w))
    if content_w <= vp:
        return False, vp
    return True, int(min(_cap, content_w))


def _finance_plotly_bar_trace_width(n_bar_slots: int, *, bargroupgap: float = 0.16) -> float:
    """Ширина одного столбца в grouped bar (единая для БДДС/БДР)."""
    nb = max(1, int(n_bar_slots))
    if nb <= 1:
        return 0.72
    total = 0.8
    bgap = max(0.0, min(0.5, float(bargroupgap)))
    return total * (1.0 - bgap) / nb


def _finance_plotly_apply_bar_width(
    fig,
    n_periods: int,
    categories: list,
    *,
    fixed_canvas_width: int | None = None,
    n_bar_slots: int | None = None,
    stack: bool = False,
    bar_width_scale: float = 1.0,
) -> None:
    """Grouped bar: bargap + горизонтальные подписи; fixed_canvas_width — для гориз. скролла."""
    n = max(1, int(n_periods))
    bg, bgg, bar_w = _finance_plotly_bar_layout(n)
    stack = bool(stack)
    try:
        barmode = "stack" if stack else str(fig.layout.barmode or "group").lower()
    except Exception:
        barmode = "stack" if stack else "group"
    n_bar = sum(
        1
        for tr in (fig.data or [])
        if getattr(tr, "type", None) == "bar" or type(tr).__name__ == "Bar"
    )
    slots = max(1, int(n_bar_slots if n_bar_slots is not None else n_bar))
    if fixed_canvas_width is not None:
        bg = max(0.05, min(0.12, 2.2 / n))
        if float(bar_width_scale or 1.0) >= 2.0:
            bgg = 0.06 if barmode == "group" and slots > 1 else 0.04
        else:
            bgg = 0.16 if barmode == "group" and slots > 1 else 0.04
    else:
        bgg = max(bgg, 0.14) if barmode == "group" and slots > 1 else bgg
    fig.update_layout(bargap=bg, bargroupgap=bgg)
    if stack:
        fig.update_traces(width=0.82, selector=dict(type="bar"))
    elif barmode == "group" and slots > 1:
        _tw = _finance_plotly_bar_trace_width(slots, bargroupgap=bgg) * max(
            1.0, float(bar_width_scale or 1.0)
        )
        fig.update_traces(width=_tw, selector=dict(type="bar"))
    elif barmode != "group" or n_bar <= 1:
        fig.update_traces(width=bar_w, selector=dict(type="bar"))
    _cats = [str(c) for c in categories] if categories else None
    if _cats:
        fig.update_xaxes(
            type="category",
            categoryorder="array",
            categoryarray=_cats,
            tickmode="array",
            tickvals=_cats,
            ticktext=_cats,
            tickangle=0,
            ticklabelstandoff=14,
            tickfont=dict(size=CHART_AXIS_TICK_FONT_SIZE),
            automargin=True,
        )
    else:
        fig.update_xaxes(tickangle=0, ticklabelstandoff=12, automargin=True)
    if fixed_canvas_width is not None:
        fig.update_layout(width=int(fixed_canvas_width))


def _render_finance_bar_chart(
    fig,
    *,
    n_periods: int,
    categories: list,
    height: int,
    caption_below: str = "",
    px_per_month: int | None = None,
    force_hscroll: bool = False,
    n_bar_slots: int | None = None,
    bar_width_scale: float = 1.0,
    max_canvas_width: int = 12000,
) -> None:
    """Grouped bar: короткий ряд — на всю ширину; длинный — components.html + гориз. скролл."""
    import uuid

    # Извлекаем легенду из фигуры → рендерим статично под полосой скролла
    _leg_items: list[tuple[str, str]] = []
    try:
        for _tr in (fig.data or []):
            _nm = getattr(_tr, "name", None) or ""
            if not _nm or getattr(_tr, "showlegend", True) is False:
                continue
            _mc = None
            try:
                _mc = _tr.marker.color
            except Exception:
                pass
            if isinstance(_mc, (list, tuple)):
                _mc = _mc[0] if _mc else None
            _leg_items.append((_nm, str(_mc or "#888")))
    except Exception:
        pass
    try:
        fig.update_layout(showlegend=False)
    except Exception:
        pass

    n = max(1, int(n_periods))
    cats = [str(c) for c in (categories or [])]
    fig_h = int(height)
    need_hscroll, canvas_w = _finance_plotly_canvas_width(
        n, px_per_month=px_per_month, force_hscroll=force_hscroll, max_width=max_canvas_width
    )
    fixed_w = int(canvas_w) if need_hscroll else None

    try:
        _finance_plotly_apply_bar_width(
            fig,
            n,
            cats,
            fixed_canvas_width=fixed_w,
            n_bar_slots=n_bar_slots,
            bar_width_scale=bar_width_scale,
        )
    except Exception:
        pass
    try:
        fig.update_layout(height=fig_h, autosize=not need_hscroll)
        if need_hscroll and fixed_w:
            fig.update_layout(width=fixed_w)
        else:
            fig.update_layout(width=None)
    except Exception:
        pass
    try:
        if cats:
            fig.update_xaxes(
                tickangle=0,
                tickmode="array",
                tickvals=cats,
                ticktext=cats,
                automargin=True,
            )
        else:
            fig.update_xaxes(tickangle=0, automargin=True)
    except Exception:
        pass
    if caption_below:
        try:
            fig.update_layout(title_text="")
        except Exception:
            pass
    _apply_finance_light_preview_chart_colors(fig)
    try:
        from dashboards.light_theme import is_light_preview_active

        if is_light_preview_active():
            from dashboards.gdrs_theme import get_gdrs_theme, gdrs_sanitize_bar_text_labels

            fig = gdrs_sanitize_bar_text_labels(fig, get_gdrs_theme("light"))
    except Exception:
        pass
    # Гарантия: у bar есть outside-подписи (sanitize раньше мог затирать text=None).
    try:
        for _tr in fig.data or []:
            if getattr(_tr, "type", None) != "bar":
                continue
            _ys = list(getattr(_tr, "y", None) or [])
            _raw_txt = getattr(_tr, "text", None)
            try:
                _txts = list(_raw_txt) if _raw_txt is not None else []
            except Exception:
                _txts = []
            if _plotly_text_all_empty(_txts) and _ys:
                _txts = []
                for _y in _ys:
                    try:
                        _yf = float(_y)
                    except (TypeError, ValueError):
                        _txts.append("")
                        continue
                    _txts.append(f"{_yf:.1f}" if abs(_yf) >= 0.05 else "")
            _tf = getattr(_tr, "outsidetextfont", None) or getattr(_tr, "textfont", None)
            _tf_kw = dict(size=10, color=_fin_chart_label_color())
            try:
                if _tf is not None:
                    if getattr(_tf, "size", None) is not None:
                        _tf_kw["size"] = _tf.size
                    if getattr(_tf, "color", None) is not None:
                        _tf_kw["color"] = _tf.color
            except Exception:
                pass
            _tr.update(
                text=_txts,
                texttemplate="%{text}",
                textposition="outside",
                cliponaxis=False,
                constraintext="none",
                textfont=_tf_kw,
                outsidetextfont=_tf_kw,
            )
    except Exception:
        pass
    _apply_plotly_spec_411_labels(fig)
    _finance_plotly_xaxis_category_pad(fig, n)
    try:
        _yax = fig.layout.yaxis
        _yr = getattr(_yax, "range", None) if _yax is not None else None
        if _yr is not None and len(_yr) == 2:
            fig.update_yaxes(
                range=[float(_yr[0]), float(_yr[1])],
                autorange=False,
            )
    except Exception:
        pass
    # Annotations поверх столбцов — гарантированно видны в iframe/светлом превью.
    # bar.text отключаем, чтобы не было двойных подписей.
    try:
        fig = _finance_force_grouped_bar_annotations(fig, min_abs=0.05)
        fig.update_traces(
            selector=dict(type="bar"),
            text=None,
            texttemplate=None,
            textposition=None,
        )
    except Exception:
        pass

    if not need_hscroll:
        render_chart(
            fig,
            caption_below=caption_below,
            height=fig_h,
            max_height=None,
            omit_default_width=True,
        )
        return

    uid = uuid.uuid4().hex[:8]
    w = int(fixed_w or canvas_w)
    h = int(fig_h)
    cfg = dict(_PLOTLY_CONFIG)
    cfg["responsive"] = False
    try:
        _m = fig.layout.margin
        _b = int(_m.b) if _m is not None and _m.b is not None else 120
        fig.update_layout(
            margin=dict(
                l=int(_m.l or 56) if _m is not None else 56,
                r=max(int(_m.r or 24) if _m is not None else 24, 88),
                # Не срезать верх: outside-подписи над столбцами.
                t=max(int(_m.t or 68) if _m is not None else 68, 120),
                b=min(_b, 108),
            )
        )
    except Exception:
        pass
    # Каждый iframe components.html изолирован — plotly.js нужен в каждом графике.
    try:
        plot_div = fig.to_html(
            full_html=False,
            include_plotlyjs="cdn",
            config=cfg,
            default_width=f"{w}px",
            default_height=f"{h}px",
        )
        _scroll_px = 22
        _light_plotly_css = _fin_iframe_plotly_light_css(uid)
        _scroll_track = (
            "background:rgba(226,232,240,0.85);"
            if _light_plotly_css
            else "background:rgba(15,23,42,0.35);"
        )
        _bar_border = (
            "1px solid #cbd5e1"
            if _light_plotly_css
            else "1px solid rgba(148,163,184,0.22)"
        )
        _fbar_wrap_cls = f"pf-fbar-{uid}-wrap"
        _fbar_inner_cls = f"pf-fbar-{uid}-inner"
        _modebar_pin_css = _finance_plotly_hscroll_modebar_pin_css(wrap_class=_fbar_wrap_cls)
        _modebar_pin_js = _finance_plotly_hscroll_modebar_pin_script(
            wrap_class=_fbar_wrap_cls,
            inner_class=_fbar_inner_cls,
        )
        shell = (
            "<!DOCTYPE html><html><head><meta charset='utf-8'>"
            f"<style>"
            f"html,body{{margin:0;padding:0;background:transparent;overflow:visible;min-height:{h + _scroll_px}px;}}"
            f".{_fbar_wrap_cls}{{width:100%;max-width:100%;overflow-x:auto;overflow-y:visible;"
            f"-webkit-overflow-scrolling:touch;box-sizing:border-box;line-height:normal;"
            f"padding:0 0 {_scroll_px}px 0;scrollbar-gutter:stable both-edges;"
            f"border:{_bar_border};border-radius:8px;"
            f"min-height:{h + _scroll_px}px;}}"
            f".{_fbar_inner_cls}{{width:{w}px;min-width:{w}px;max-width:{w}px;display:block;"
            f"line-height:normal;}}"
            f".{_fbar_inner_cls} .plotly-graph-div,.{_fbar_inner_cls} .js-plotly-plot{{"
            f"width:{w}px!important;min-width:{w}px!important;max-width:{w}px!important;"
            f"height:{h}px!important;}}"
            f".{_fbar_wrap_cls}::-webkit-scrollbar{{height:12px;}}"
            f".{_fbar_wrap_cls}::-webkit-scrollbar-thumb{{background:rgba(148,163,184,0.55);border-radius:6px;}}"
            f".{_fbar_wrap_cls}::-webkit-scrollbar-track{{{_scroll_track}border-radius:6px;}}"
            f"{_modebar_pin_css}"
            f"{_light_plotly_css}"
            f"</style></head><body>"
            f'<div class="{_fbar_wrap_cls}"><div class="{_fbar_inner_cls}">{plot_div}</div></div>'
            f"{_modebar_pin_js}"
            "</body></html>"
        )
        components.html(shell, height=h + _scroll_px + 12, scrolling=False)
        if caption_below:
            _chart_caption_below(caption_below)
        # Статичная легенда под полосой скролла
        if _leg_items:
            _leg_html = (
                '<div style="display:flex;flex-wrap:wrap;gap:8px 20px;'
                'padding:10px 4px 4px 4px;font-size:12px;line-height:1.4;">'
            )
            for _ln, _lc in _leg_items:
                _leg_html += (
                    f'<span style="display:flex;align-items:center;gap:5px;">'
                    f'<span style="display:inline-block;width:14px;height:14px;'
                    f'border-radius:2px;background:{_lc};flex-shrink:0;"></span>'
                    f'<span style="color:{_fin_chart_legend_text_color()};">{_ln}</span></span>'
                )
            _leg_html += "</div>"
            components.html(_leg_html, height=44, scrolling=False)
    except Exception:
        render_chart(
            fig,
            caption_below=caption_below,
            height=fig_h,
            max_height=None,
            omit_default_width=True,
            plotly_config_extra={"responsive": False},
        )
        if _leg_items:
            _leg_html = (
                '<div style="display:flex;flex-wrap:wrap;gap:8px 20px;'
                'padding:10px 4px 4px 4px;font-size:12px;line-height:1.4;">'
            )
            for _ln, _lc in _leg_items:
                _leg_html += (
                    f'<span style="display:flex;align-items:center;gap:5px;">'
                    f'<span style="display:inline-block;width:14px;height:14px;'
                    f'border-radius:2px;background:{_lc};flex-shrink:0;"></span>'
                    f'<span style="color:{_fin_chart_legend_text_color()};">{_ln}</span></span>'
                )
            _leg_html += "</div>"
            components.html(_leg_html, height=44, scrolling=False)


_DK_BAR_PX_SLOT = 220  # «С группировкой» (стек)
_DK_BAR_PX_SLOT_GROUP = 440  # «Без группировки»: 2× ширина слота категории
_DK_BAR_SCROLL_VP_PX = 1420




def _dk_chart_axis_peak_mln(
    chart_df: pd.DataFrame,
    *,
    has_deviation: bool,
    side_by_side: bool,
) -> float:
    """Верх шкалы Y (млн): только серии, которые реально рисуются на графике."""
    if side_by_side:
        peaks: list[float] = []
        for col in ("Аванс", "КС-2"):
            if col in chart_df.columns:
                peaks.append(float(pd.to_numeric(chart_df[col], errors="coerce").fillna(0.0).max()))
        if has_deviation and "Отклонение" in chart_df.columns:
            _dev = pd.to_numeric(chart_df["Отклонение"], errors="coerce").fillna(0.0)
            peaks.append(float(_dev.clip(lower=0.0).max()))
            _neg = float(_dev.min())
            if _neg < 0:
                peaks.append(abs(_neg))
        return max(peaks) if peaks else 0.0
    _stack = pd.Series(0.0, index=chart_df.index, dtype=float)
    if has_deviation and "Отклонение" in chart_df.columns:
        _dev = pd.to_numeric(chart_df["Отклонение"], errors="coerce").fillna(0.0)
        _stack = _stack + _dev.clip(lower=0.0)
    for col in ("КС-2", "Аванс"):
        if col in chart_df.columns:
            _stack = _stack + pd.to_numeric(chart_df[col], errors="coerce").fillna(0.0)
    return float(_stack.max()) if len(_stack) else 0.0


def _dk_chart_yaxis_layout(
    chart_df: pd.DataFrame,
    *,
    has_deviation: bool,
    side_by_side: bool,
) -> dict:
    """Одинаковые range/dtick для обоих режимов (эталон — «С группировкой»)."""
    _dev_all = (
        pd.to_numeric(chart_df["Отклонение"], errors="coerce").fillna(0.0)
        if has_deviation and "Отклонение" in chart_df.columns
        else pd.Series(0.0, index=chart_df.index)
    )
    _neg_min = float(_dev_all.min()) if side_by_side else 0.0
    _peak = _dk_chart_axis_peak_mln(
        chart_df, has_deviation=has_deviation, side_by_side=side_by_side
    )
    _dtick_fc, _y_top_fc = _finance_bar_yaxis_tight(
        max(_peak, 0.01), outside_labels=True, tick_stride=1
    )
    if side_by_side and _neg_min < 0:
        _neg_abs = abs(_neg_min)
        _, _y_bot_fc = _finance_bar_yaxis_tight(
            max(_neg_abs, 0.01), outside_labels=True, tick_stride=1
        )
        _pad_bot = max(_neg_abs * 0.12, 0.8)
        _y_rng = [-(_y_bot_fc + _pad_bot), _y_top_fc]
    else:
        _y_rng = [0, _y_top_fc]
    return dict(
        title=dict(text="млн руб.", font=dict(size=CHART_AXIS_TITLE_FONT_SIZE + 6, color=_fin_chart_axis_color())),
        tickfont=dict(size=CHART_AXIS_TICK_FONT_SIZE + 4, color=_fin_chart_axis_color()),
        range=_y_rng,
        dtick=_dtick_fc,
        tick0=0,
    )


def _dk_plotly_canvas_width(n_cats: int, *, grouped: bool = True) -> tuple[bool, int]:
    """Ширина canvas: «Без группировки» — слот категории в 2× шире стека."""
    n = max(1, int(n_cats))
    vp = int(_DK_BAR_SCROLL_VP_PX)
    px = int(_DK_BAR_PX_SLOT_GROUP if grouped else _DK_BAR_PX_SLOT)
    content_w = n * px + 80
    if n >= 5:
        return True, int(min(18000, content_w))
    if content_w <= vp:
        return False, vp
    return True, int(min(18000, content_w))




def _dk_plotly_finalize_stack_bars(fig, *, n_cats: int | None = None) -> None:
    """«С группировкой»: barmode=stack — один столбец на категорию (без split overlay+base)."""
    try:
        n = max(1, int(n_cats)) if n_cats is not None else None
        bar_width = 0.82
        layout_kw: dict = dict(barmode="stack", bargroupgap=0.04)
        if n is not None and n <= 2:
            _gaps = _plotly_bargaps_sparse_x_like_gdrs(n)
            if _gaps:
                layout_kw.update(_gaps)
        if n == 1:
            bar_width = 0.14
            layout_kw.update(bargap=0.92, bargroupgap=0.28)
        fig.update_layout(**layout_kw)
        fig.update_traces(width=bar_width, selector=dict(type="bar"))
        for tr in fig.data or []:
            if getattr(tr, "type", None) != "bar" and type(tr).__name__ != "Bar":
                continue
            tr.update(offsetgroup=None, alignmentgroup=None, base=None)
    except Exception:
        pass


def _dk_plotly_finalize_group_bars(
    fig,
    *,
    n_cats: int | None = None,
    bargap: float | None = None,
) -> None:
    """«Без группировки»: серии рядом; ширина столбца — как БДДС, без offsetgroup."""
    try:
        n = max(1, int(n_cats)) if n_cats is not None else None
        _bg = (
            float(bargap)
            if bargap is not None
            else (max(0.05, min(0.12, 1.6 / n)) if n else 0.10)
        )
        _n_tr = sum(
            1
            for tr in (fig.data or [])
            if getattr(tr, "type", None) == "bar" or type(tr).__name__ == "Bar"
        )
        _n_tr = max(1, _n_tr)
        _bgg = 0.16 if _n_tr > 1 else 0.04
        layout_kw: dict = dict(barmode="group", bargap=_bg, bargroupgap=_bgg)
        if n is not None and n <= 2:
            _gaps = _plotly_bargaps_sparse_x_like_gdrs(n)
            if _gaps:
                layout_kw.update(_gaps)
        if n == 1:
            layout_kw.update(bargap=0.92, bargroupgap=0.28)
        fig.update_layout(**layout_kw)
        if _n_tr > 1:
            _trace_w = _finance_plotly_bar_trace_width(_n_tr, bargroupgap=_bgg)
            _trace_w = min(_trace_w, max(0.08, (0.82 * (1.0 - _bgg)) / _n_tr))
        elif n == 1:
            _trace_w = 0.14
        else:
            _trace_w = 0.82
        fig.update_traces(width=_trace_w, selector=dict(type="bar"))
        for tr in fig.data or []:
            if getattr(tr, "type", None) != "bar" and type(tr).__name__ != "Bar":
                continue
            tr.update(offsetgroup=None, alignmentgroup=None, base=None)
    except Exception:
        pass


def _dk_make_side_by_side_bar_figure(
    chart_df: pd.DataFrame,
    chart_label: str,
    *,
    has_deviation: bool,
    value_cols: list[str],
    colors: dict[str, str],
    text_fn,
    bar_label_style: dict,
) -> tuple[go.Figure, list[str], str | None]:
    """
    «Без группировки»: серии рядом (barmode=group).

    Одна категория (один подрядчик/договор) — метрики на оси X, как ГДРС при одной
    сущности; иначе Plotly рисует столбцы друг на друге.
    """
    _dev_pos_style = dict(
        textposition="outside",
        textangle=0,
        cliponaxis=False,
        textfont=dict(size=16, color=_fin_chart_label_color()),
    )

    if len(chart_df) == 1:
        row = chart_df.iloc[0]
        partner = str(row[chart_label]).strip()
        specs: list[tuple[str, float, str, str, dict]] = []
        for col in ("Аванс", "КС-2"):
            if col not in value_cols or col not in chart_df.columns:
                continue
            y = float(pd.to_numeric(row[col], errors="coerce") or 0.0)
            specs.append((col, y, colors.get(col, "#888888"), col, bar_label_style))
        if has_deviation and "Отклонение" in chart_df.columns:
            dev = float(pd.to_numeric(row["Отклонение"], errors="coerce") or 0.0)
            if dev >= 0:
                specs.append(
                    (
                        "Откл. ≥0",
                        dev,
                        "#95A5A6",
                        "Отклонение, если больше или = 0",
                        _dev_pos_style,
                    )
                )
            else:
                specs.append(
                    (
                        "Откл. <0",
                        dev,
                        "#F1948A",
                        "Отклонение, если меньше 0",
                        _dev_pos_style,
                    )
                )
        fig = go.Figure()
        x_cats: list[str] = []
        for x_name, y_val, color, legend_name, style in specs:
            x_cats.append(x_name)
            fig.add_trace(
                go.Bar(
                    name=legend_name,
                    x=[x_name],
                    y=[y_val],
                    marker_color=color,
                    showlegend=True,
                    text=[text_fn(y_val)],
                    customdata=[f"{y_val:.1f} млн руб"],
                    hovertemplate=(
                        f"<b>{legend_name}</b><br>{partner}<br>%{{customdata}}<extra></extra>"
                    ),
                    **style,
                )
            )
        return fig, x_cats, partner

    fig = go.Figure()
    x = chart_df[chart_label].astype(str)
    _value_cols_for_chart = [c for c in value_cols if c != "Отклонение"]
    _value_cols_for_chart = [c for c in ("Аванс", "КС-2") if c in _value_cols_for_chart]
    for col in _value_cols_for_chart:
        fig.add_trace(
            go.Bar(
                name=col,
                x=x,
                y=chart_df[col],
                marker_color=colors.get(col, None),
                text=chart_df[col].apply(text_fn),
                customdata=chart_df[col].apply(
                    lambda v: f"{v:.1f} млн руб" if pd.notna(v) else "0,0 млн руб"
                ),
                hovertemplate=f"<b>{col}</b><br>%{{x}}<br>%{{customdata}}<extra></extra>",
                showlegend=True,
                **bar_label_style,
            )
        )
    if has_deviation:
        _dev_s = pd.to_numeric(chart_df["Отклонение"], errors="coerce").fillna(0.0)
        _dev_pos = _dev_s.where(_dev_s >= 0, 0.0)
        _dev_neg = _dev_s.where(_dev_s < 0, 0.0)
        fig.add_trace(
            go.Bar(
                name="Отклонение, если больше или = 0",
                x=x,
                y=_dev_pos,
                marker_color="#95A5A6",
                showlegend=True,
                text=_dev_pos.apply(text_fn),
                customdata=_dev_pos.apply(
                    lambda v: f"{v:.1f} млн" if pd.notna(v) else "0,0 млн"
                ),
                hovertemplate="<b>Отклонение ≥0</b><br>%{x}<br>%{customdata}<extra></extra>",
                **_dev_pos_style,
            )
        )
        fig.add_trace(
            go.Bar(
                name="Отклонение, если меньше 0",
                x=x,
                y=_dev_neg,
                marker_color="#F1948A",
                text=_dev_neg.apply(text_fn),
                customdata=_dev_neg.apply(
                    lambda v: f"{v:.1f} млн" if pd.notna(v) else "0,0 млн"
                ),
                hovertemplate="<b>Отклонение &lt;0</b><br>%{x}<br>%{customdata}<extra></extra>",
                showlegend=True,
                **_dev_pos_style,
            )
        )
    return fig, chart_df[chart_label].astype(str).tolist(), None


def _dk_make_stack_bar_figure(
    chart_df: pd.DataFrame,
    chart_label: str,
    *,
    has_deviation: bool,
    text_fn,
) -> go.Figure:
    """Стек ДЗ/КЗ: отклонение ≥0 → КС-2 → Аванс (один столбец на подрядчика)."""
    x = chart_df[chart_label].astype(str).tolist()
    traces: list = []
    _bar_style = dict(
        textposition="outside",
        textangle=0,
        cliponaxis=False,
        textfont=dict(size=11, color=_fin_chart_label_color(dark="#e8eef5", light="#111827")),
        width=0.82,
    )
    _series: list[tuple[str, np.ndarray, str, str]] = []
    if has_deviation and "Отклонение" in chart_df.columns:
        _dev_pos = (
            pd.to_numeric(chart_df["Отклонение"], errors="coerce")
            .fillna(0.0)
            .clip(lower=0.0)
            .to_numpy(dtype=float)
        )
        _series.append(
            (
                "Отклонение, если больше или = 0",
                _dev_pos,
                "#95A5A6",
                "<b>Отклонение ≥0</b><br>%{x}<br>%{text}<extra></extra>",
            )
        )
    for col, color in (("КС-2", "#F1C40F"), ("Аванс", "#2E86AB")):
        if col not in chart_df.columns:
            continue
        _y = pd.to_numeric(chart_df[col], errors="coerce").fillna(0.0).to_numpy(dtype=float)
        _series.append((col, _y, color, f"<b>{col}</b><br>%{{x}}<br>%{{text}}<extra></extra>"))
    for name, y_vals, color, hover_tpl in _series:
        traces.append(
            go.Bar(
                name=name,
                x=x,
                y=y_vals,
                marker=dict(color=color),
                showlegend=True,
                text=[text_fn(v) for v in y_vals],
                hovertemplate=hover_tpl,
                **_bar_style,
            )
        )
    fig = go.Figure(data=traces, layout=go.Layout(barmode="stack", bargroupgap=0.04))
    _dk_plotly_finalize_stack_bars(fig, n_cats=len(x))
    return fig


def _dk_chart_legend_items(*, stack: bool) -> list[tuple[str, str]]:
    """Фиксированная легенда ДЗ/КЗ (визуал 1 / визуал 2), не зависит от нулевых серий."""
    if stack:
        return [
            ("Отклонение, если больше или = 0", "#95A5A6"),
            ("КС-2", "#F1C40F"),
            ("Аванс", "#2E86AB"),
        ]
    return [
        ("Аванс", "#2E86AB"),
        ("КС-2", "#F1C40F"),
        ("Отклонение, если больше или = 0", "#95A5A6"),
        ("Отклонение, если меньше 0", "#F1948A"),
    ]


def _render_dk_chart_html_legend(_leg_items: list[tuple[str, str]]) -> None:
    """Статичная легенда под графиком ДЗ/КЗ (plotly showlegend отключён)."""
    if not _leg_items:
        return
    try:
        import streamlit.components.v1 as components

        _lh = (
            '<div style="display:flex;flex-wrap:wrap;gap:8px 20px;'
            'padding:10px 4px 4px 4px;font-size:12px;line-height:1.4;">'
        )
        for _ln, _lc in _leg_items:
            _lh += (
                f'<span style="display:flex;align-items:center;gap:5px;">'
                f'<span style="display:inline-block;width:14px;height:14px;'
                f'border-radius:2px;background:{_lc};flex-shrink:0;"></span>'
                f'<span style="color:{_fin_chart_legend_text_color()};">{_ln}</span></span>'
            )
        _lh += "</div>"
        _leg_h = int(max(44, 28 + 22 * max(1, (len(_leg_items) + 1) // 2)))
        components.html(_lh, height=_leg_h, scrolling=False)
    except Exception:
        pass


def _render_debit_credit_bar_chart(
    fig,
    *,
    categories: list,
    stack: bool = False,
    caption_below: str = "",
    tick_labels: list | None = None,
) -> None:
    # ДЗ/КЗ: широкие столбцы; длинный ряд - гориз. скролл (как БДДС).
    import uuid

    _leg_items: list[tuple[str, str]] = _dk_chart_legend_items(stack=stack)
    try:
        fig.update_layout(showlegend=False)
    except Exception:
        pass

    cats = [str(c) for c in (categories or [])]
    ticktext = [str(t) for t in (tick_labels or cats)]
    if len(ticktext) != len(cats):
        ticktext = cats
    n = max(1, len(cats))
    stack = bool(stack)
    fig_h = int(max(720, min(1120, 680 + n * 14)))
    need_hscroll, canvas_w = _dk_plotly_canvas_width(n, grouped=not stack)
    fixed_w = int(canvas_w) if need_hscroll else None

    _bg = 0.10 if need_hscroll else max(0.05, min(0.12, 1.6 / n))
    if stack:
        if n <= 2:
            _gaps = _plotly_bargaps_sparse_x_like_gdrs(n)
            if _gaps:
                fig.update_layout(barmode="stack", **_gaps)
            else:
                fig.update_layout(barmode="stack", bargap=_bg, bargroupgap=0.04)
        else:
            fig.update_layout(barmode="stack", bargap=_bg, bargroupgap=0.04)
        _dk_plotly_finalize_stack_bars(fig, n_cats=n)
    else:
        try:
            _dk_plotly_finalize_group_bars(fig, n_cats=n, bargap=_bg)
        except Exception:
            pass

    try:
        fig.update_layout(height=fig_h, autosize=not need_hscroll)
        if need_hscroll and fixed_w:
            fig.update_layout(width=fixed_w)
        else:
            fig.update_layout(width=None)
    except Exception:
        pass

    _tick_size = 11 if need_hscroll else 12
    try:
        if cats:
            fig.update_xaxes(
                type="category",
                categoryorder="array",
                categoryarray=cats,
                tickmode="array",
                tickvals=cats,
                ticktext=ticktext,
                tickangle=0,
                ticklabelstandoff=28 if need_hscroll else 20,
                tickfont=dict(size=_tick_size, color=_fin_chart_axis_color()),
                automargin=True,
            )
        else:
            fig.update_xaxes(
                tickangle=0 if need_hscroll else -42,
                tickfont=dict(size=_tick_size, color=_fin_chart_axis_color()),
                automargin=True,
            )
        fig.update_yaxes(tickfont=dict(size=14, color=_fin_chart_axis_color()))
    except Exception:
        pass

    try:
        fig.update_layout(uniformtext=dict(minsize=7, mode="show"))
    except Exception:
        pass

    if caption_below:
        try:
            fig.update_layout(title_text="")
        except Exception:
            pass
    _apply_plotly_spec_411_labels(fig)
    if stack:
        _dk_plotly_finalize_stack_bars(fig, n_cats=n)

    _resync_plotly_chart_theme(fig)
    _apply_finance_light_preview_chart_colors(fig)

    if not need_hscroll:
        render_chart(
            fig,
            caption_below=caption_below,
            height=fig_h,
            max_height=None,
            omit_default_width=True,
        )
        _render_dk_chart_html_legend(_leg_items)
        return

    uid = uuid.uuid4().hex[:8]
    w = int(fixed_w or canvas_w)
    h = int(fig_h)
    cfg = dict(_PLOTLY_CONFIG)
    cfg["responsive"] = False
    try:
        _m = fig.layout.margin
        _b = int(_m.b) if _m is not None and _m.b is not None else 96
        _leg_b = max(_b, 168) if need_hscroll else min(_b, 110)
        fig.update_layout(
            margin=dict(
                l=int(_m.l or 56) if _m is not None else 56,
                r=int(_m.r or 36) if _m is not None else 36,
                t=int(_m.t or 88) if _m is not None else 88,
                b=_leg_b,
            )
        )
    except Exception:
        pass
    try:
        import streamlit.components.v1 as components

        if stack:
            _dk_plotly_finalize_stack_bars(fig, n_cats=n)
        # inline plotly.js — стабильный stack без split столбцов.
        plot_div = fig.to_html(
            full_html=False,
            include_plotlyjs=True,
            config=cfg,
            default_width=f"{w}px",
            default_height=f"{h}px",
        )
        _dk_wrap_cls = f"pf-dkbar-{uid}-wrap"
        _dk_inner_cls = f"pf-dkbar-{uid}-inner"
        _dk_modebar_pin_css = _finance_plotly_hscroll_modebar_pin_css(wrap_class=_dk_wrap_cls)
        _dk_modebar_pin_js = _finance_plotly_hscroll_modebar_pin_script(
            wrap_class=_dk_wrap_cls,
            inner_class=_dk_inner_cls,
        )
        shell = (
            "<!DOCTYPE html><html><head><meta charset='utf-8'>"
            f"<style>"
            f"html,body{{margin:0;padding:0;background:transparent;overflow:hidden;}}"
            f".{_dk_wrap_cls}{{width:100%;max-width:100%;overflow-x:auto;overflow-y:hidden;"
            f"-webkit-overflow-scrolling:touch;box-sizing:border-box;}}"
            f".{_dk_inner_cls}{{width:{w}px;min-width:{w}px;display:block;}}"
            f".{_dk_inner_cls} .plotly-graph-div,.{_dk_inner_cls} .js-plotly-plot{{"
            f"width:{w}px!important;min-width:{w}px!important;height:{h}px!important;}}"
            f"{_dk_modebar_pin_css}"
            f"</style></head><body>"
            f'<div class="{_dk_wrap_cls}"><div class="{_dk_inner_cls}">{plot_div}</div></div>'
            "<script>"
            "function _dkRsz(){try{var gd=document.querySelector('.plotly-graph-div');"
            "if(gd&&window.Plotly)Plotly.Plots.resize(gd);}catch(e){}}"
            "window.addEventListener('load',_dkRsz);setTimeout(_dkRsz,120);setTimeout(_dkRsz,600);"
            "</script>"
            f"{_dk_modebar_pin_js}"
            "</body></html>"
        )
        components.html(shell, height=int(h + 8), scrolling=False)
        if need_hscroll:
            st.caption("Длинный ряд подрядчиков — **прокрутите график вправо** в полосе под диаграммой.")
        if caption_below:
            _chart_caption_below(caption_below)
        _render_dk_chart_html_legend(_leg_items)
    except Exception:
        render_chart(
            fig,
            caption_below=caption_below,
            height=fig_h,
            max_height=None,
            omit_default_width=True,
            plotly_config_extra={"responsive": False},
        )
        _render_dk_chart_html_legend(_leg_items)


def dashboard_budget_by_period(df):

    from dashboards.finance_from_1c import resolve_reference_1c_dannye

    _bdds_ref_boot = resolve_reference_1c_dannye()
    if _bdds_ref_boot is not None and not _bdds_ref_boot.empty:
        st.session_state["reference_1c_dannye"] = _bdds_ref_boot

    def _derive_bdds_dimensions(_df: pd.DataFrame) -> pd.DataFrame:
        """
        ТЗ БДДС:
        - Лот: брать из MSP и прокидывать на дочерние задачи.
        - Этап: название задачи уровня 2.
        """
        if _df is None or getattr(_df, "empty", True):
            return _df
        out = _df.copy()
        task_col = "task name" if "task name" in out.columns else ("Название" if "Название" in out.columns else None)
        lvl_col = "level structure" if "level structure" in out.columns else ("level" if "level" in out.columns else None)
        proj_col = "project name" if "project name" in out.columns else None
        lot_src = (
            "lot" if "lot" in out.columns else ("ЛОТ" if "ЛОТ" in out.columns else None)
        )
        if task_col is None or lvl_col is None:
            if "stage_l2" not in out.columns:
                out["stage_l2"] = ""
            if "lot_effective" not in out.columns:
                out["lot_effective"] = out.get(lot_src, "")
            return out

        if "task id seq" in out.columns:
            sort_col = "task id seq"
        elif "Ид" in out.columns:
            sort_col = "Ид"
        else:
            sort_col = None

        def _norm_text(v):
            if v is None or (isinstance(v, float) and pd.isna(v)):
                return ""
            return str(v).replace("\xa0", " ").replace("\u200b", "").replace("\ufeff", "").strip()

        def _process_group(g: pd.DataFrame) -> pd.DataFrame:
            gg = g.copy()
            if sort_col and sort_col in gg.columns:
                gg = gg.sort_values(sort_col, key=lambda s: pd.to_numeric(s, errors="coerce")).copy()
            stage_vals = []
            lot_vals = []
            stack_task = {}
            stack_lot = {}
            for _, r in gg.iterrows():
                lv = pd.to_numeric(r.get(lvl_col), errors="coerce")
                try:
                    lvi = int(lv)
                except Exception:
                    lvi = -1
                if lvi > 0:
                    for k in list(stack_task.keys()):
                        if k >= lvi:
                            del stack_task[k]
                    for k in list(stack_lot.keys()):
                        if k >= lvi:
                            del stack_lot[k]

                tname = _norm_text(r.get(task_col))
                lot_here = _norm_text(r.get(lot_src)) if lot_src else ""
                if lvi == 2 and tname:
                    stage = tname
                else:
                    stage = stack_task.get(2, "")

                if lot_here:
                    lot_eff = lot_here
                else:
                    lot_eff = stack_lot.get(2, "") or stack_lot.get(3, "") or stack_lot.get(1, "")

                stage_vals.append(stage)
                lot_vals.append(lot_eff)

                if lvi > 0 and tname:
                    stack_task[lvi] = tname
                if lvi > 0 and lot_here:
                    stack_lot[lvi] = lot_here
            gg["stage_l2"] = stage_vals
            gg["lot_effective"] = lot_vals
            return gg

        if proj_col and proj_col in out.columns:
            parts = []
            for _, g in out.groupby(out[proj_col].astype(str), sort=False):
                parts.append(_process_group(g))
            out = pd.concat(parts, axis=0)
        else:
            out = _process_group(out)
        return out

    # Сетка фильтров; чекбоксы — после фильтров (П.9)
    df = _derive_bdds_dimensions(df)
    if "project name" in df.columns:
        df = _project_column_apply_canonical(df, "project name")

    hide_adjusted = True

    filtered_df = df.copy()
    with filters_panel(
        st,
        reset_keys=["budget_project", "budget_period*", "_bdds_period_scope"],
        reset_defaults={
            "budget_project": [],
            "budget_period": "Месяц",
            "budget_period_view": "По месяцам",
            "budget_period_show_deviation": False,
        },
    ):
        with filters_selectors(st):
            col1, col2, col3, col4, col5 = st.columns(5, gap="small")

            with col1:
                if "project name" in filtered_df.columns:
                    from dashboards.finance_from_1c import (
                        restrict_project_filter_labels_to_finance_data,
                    )

                    _project_opts = restrict_project_filter_labels_to_finance_data(
                        _unique_project_labels_for_select(filtered_df["project name"]),
                        filtered_df,
                        kind="bdds",
                    )
                    selected_projects, _bdds_all_projects = project_filter_multiselect(st, _project_opts,
                        key="budget_project",
                    )
                else:
                    selected_projects = []
                    _bdds_all_projects = True

            _bdds_sel_projects = list(selected_projects or [])
            _bdds_proj_df = filtered_df.copy()
            if _bdds_sel_projects and "project name" in _bdds_proj_df.columns:
                _bdds_proj_df = _filter_df_by_project_labels(
                    _bdds_proj_df, _bdds_sel_projects
                )

            ensure_date_columns(_bdds_proj_df)
            _period_from, _period_to = None, None
            with col2:
                if "plan end" in _bdds_proj_df.columns:
                    _pe_series = pd.to_datetime(_bdds_proj_df["plan end"], errors="coerce")
                    _def_start = None
                    _def_end = None
                    _bdds_min_all = None
                    _bdds_max_all = None
                    if _pe_series.notna().any():
                        _pe_min = _pe_series.min()
                        _pe_max = _pe_series.max()
                        _def_start = _pe_min.date() if pd.notna(_pe_min) else None
                        _def_end = _pe_max.date() if pd.notna(_pe_max) else None
                        try:
                            _pe_all = pd.to_datetime(df["plan end"], errors="coerce")
                            if _pe_all.notna().any():
                                _bdds_min_all = _pe_all.min().date()
                                _bdds_max_all = _pe_all.max().date()
                            else:
                                _bdds_min_all, _bdds_max_all = _def_start, _def_end
                        except Exception:
                            _bdds_min_all, _bdds_max_all = _def_start, _def_end
                    if (
                        not _bdds_all_projects
                        and len(_bdds_sel_projects or []) == 1
                    ):
                        try:
                            from dashboards.finance_from_1c import (
                                bdds_project_turnover_date_bounds,
                            )

                            _1c_lo, _1c_hi = bdds_project_turnover_date_bounds(
                                str(_bdds_sel_projects[0]),
                                reference_1c_dannye=_bdds_ref_boot,
                            )
                            if _1c_lo is not None and _1c_hi is not None:
                                if _def_start is None or _1c_lo < _def_start:
                                    _def_start = _1c_lo
                                if _def_end is None or _1c_hi > _def_end:
                                    _def_end = _1c_hi
                                if _bdds_min_all is None or _1c_lo < _bdds_min_all:
                                    _bdds_min_all = _1c_lo
                                if _bdds_max_all is None or _1c_hi > _bdds_max_all:
                                    _bdds_max_all = _1c_hi
                        except Exception:
                            pass
                    if _def_start and _def_end:
                        _bdds_scope = tuple(sorted(_bdds_sel_projects)) if _bdds_sel_projects else ("__all__",)
                        if st.session_state.get("_bdds_period_scope") != _bdds_scope:
                            st.session_state["_bdds_period_scope"] = _bdds_scope
                            st.session_state.pop("budget_period_range", None)
                        _period_from, _period_to = period_date_range_input(
                            st,
                            "budget_period_range",
                            min_value=_bdds_min_all or _def_start,
                            max_value=_bdds_max_all or _def_end,
                            default=(_def_start, _def_end) if _def_start and _def_end else None,
                            help="Диапазон по полю «Конец план» / оборотам 1С.",
                        )

            with col3:
                period_type = st.selectbox(
                    "Группировать по", ["Месяц", "Квартал", "Год"], key="budget_period"
                )
            period_map = {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year"}
            period_type_en = period_map.get(period_type, "Month")

            with col4:
                st.selectbox(
                    "Представление",
                    ["По месяцам", "Накопительно"],
                    key="budget_period_view",
                    help="Как строить график и нижнюю сводную таблицу: по периодам или накопительно.",
                )

        selected_projects = list(selected_projects or [])
        filtered_df = _bdds_proj_df.copy()
        _bdds_cal_start = None
        _bdds_cal_end = None
        if _period_from is not None and _period_to is not None and "plan end" in filtered_df.columns:
            _pe_series = pd.to_datetime(filtered_df["plan end"], errors="coerce")
            _start_dt = pd.to_datetime(_period_from, errors="coerce")
            _end_dt = pd.to_datetime(_period_to, errors="coerce")
            if pd.notna(_start_dt) and pd.notna(_end_dt):
                if _start_dt > _end_dt:
                    _start_dt, _end_dt = _end_dt, _start_dt
                _end_inclusive = _end_dt + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)
                if "plan start" in filtered_df.columns:
                    _ps_series = pd.to_datetime(filtered_df["plan start"], errors="coerce")
                    filtered_df = filtered_df[
                        _pe_series.notna()
                        & _ps_series.notna()
                        & (_ps_series <= _end_inclusive)
                        & (_pe_series >= _start_dt)
                    ].copy()
                else:
                    filtered_df = filtered_df[
                        (_pe_series >= _start_dt) & (_pe_series <= _end_inclusive)
                    ].copy()
                _bdds_cal_start = _start_dt
                _bdds_cal_end = _end_dt

        with filters_toggles(st):
            st.checkbox(
                "Показать отклонение",
                value=False,
                key="budget_period_show_deviation",
                help="По умолчанию на графике только план и факт; при включении добавляются столбцы отклонения.",
            )
            if period_type_en == "Month" and str(st.session_state.get("budget_period_view", "По месяцам")) == "По месяцам":
                st.checkbox(
                    "Скрывать месяцы, где план и факт равны 0",
                    value=bool(_bdds_all_projects),
                    key="budget_period_hide_zero_months",
                    help="Скрывает месяцы с нулевым планом и фактом на графике и в таблице ниже.",
                )

    show_deviation = bool(st.session_state.get("budget_period_show_deviation", False))
    hide_reserve = not show_deviation

    # Единый fallback бюджета: MSP -> 1С dannye при пустых budget колонках.
    ensure_budget_columns(filtered_df)
    from dashboards.finance_from_1c import ensure_budget_frame_with_fallback

    _bdds_narrow_pk = (
        _project_filter_norm_key(selected_projects[0])
        if (not _bdds_all_projects) and len(selected_projects or []) == 1
        else ""
    )
    _bdds_narrow_pk = (_bdds_narrow_pk or "").strip() or None

    filtered_df, _bdds_used_1c = ensure_budget_frame_with_fallback(
        filtered_df,
        show_caption=True,
        restrict_projects_from_df=True,
        period_start=_bdds_cal_start,
        period_end=_bdds_cal_end,
        force_from_1c=False,
        narrow_to_project_norm_key=_bdds_narrow_pk,
    )
    # После подстановки из 1С повторно применяем фильтр проекта,
    # чтобы в таблицы/графики не попадали другие проекты.
    # Правки куратора 08.05.2026: при первом выборе проекта в БДДС иногда «залипал»
    # фильтр и в таблице/графике показывались другие проекты (1С-fallback мог
    # вернуть данные сразу по нескольким). Применяем СТРОГОЕ сравнение
    # по нормализованному ключу, а не «нестрогое» соответствие через
    # _project_norm_key_matches_msp_keys (которое допускало частичные совпадения).
    if not _bdds_all_projects and "project name" in filtered_df.columns:
        filtered_df = _filter_df_by_project_labels(filtered_df, selected_projects)
    ensure_date_columns(filtered_df)
    ensure_budget_columns(filtered_df)
    from dashboards.data_quality_hints import collect_budget_1c_hints, render_quality_hints

    _bdds_q_hints: list[str] = []
    has_budget = "budget plan" in filtered_df.columns and "budget fact" in filtered_df.columns
    if not has_budget:
        st.warning("Столбцы бюджета (budget plan, budget fact) не найдены: загрузите MSP с бюджетом и/или `*_dannye.json` с **Сценарий** + **Сумма**.")
        return

    # Determine adjusted budget column name
    adjusted_budget_col = None
    if "budget adjusted" in filtered_df.columns:
        adjusted_budget_col = "budget adjusted"
    elif "adjusted budget" in filtered_df.columns:
        adjusted_budget_col = "adjusted budget"

    # Determine period column and ensure it exists (create from plan end if missing)
    if "plan end" in filtered_df.columns:
        plan_end = pd.to_datetime(filtered_df["plan end"], errors="coerce")
        mask = plan_end.notna()
        if mask.any():
            if "plan_month" not in filtered_df.columns:
                filtered_df.loc[mask, "plan_month"] = plan_end.loc[mask].dt.to_period("M")
            if "plan_quarter" not in filtered_df.columns:
                filtered_df.loc[mask, "plan_quarter"] = plan_end.loc[mask].dt.to_period("Q")
            if "plan_year" not in filtered_df.columns:
                filtered_df.loc[mask, "plan_year"] = plan_end.loc[mask].dt.to_period("Y")

    if period_type_en == "Month":
        period_col = "plan_month"
        period_label = "Месяц"
    elif period_type_en == "Quarter":
        period_col = "plan_quarter"
        period_label = "Квартал"
    else:
        period_col = "plan_year"
        period_label = "Год"

    if period_col not in filtered_df.columns:
        st.warning(f"Столбец периода '{period_col}' не найден. Убедитесь, что в данных есть колонка дат (например, «Конец План» / plan end).")
        return

    # Отклонение = план − факт; отрицательное — красный, положительное — зелёный.
    filtered_df["budget plan"] = pd.to_numeric(
        filtered_df["budget plan"], errors="coerce"
    )
    filtered_df["budget fact"] = pd.to_numeric(
        filtered_df["budget fact"], errors="coerce"
    )
    filtered_df = _bdds_recalc_reserve(filtered_df)

    # Convert adjusted budget to numeric if it exists
    if adjusted_budget_col:
        filtered_df[adjusted_budget_col] = pd.to_numeric(
            filtered_df[adjusted_budget_col], errors="coerce"
        )

    # Group by period and project
    agg_dict = {"budget plan": "sum", "budget fact": "sum", "reserve budget": "sum"}
    if adjusted_budget_col:
        agg_dict[adjusted_budget_col] = "sum"

    _is_1c_only_frame = bool(_bdds_used_1c) and bool(
        getattr(filtered_df, "attrs", {}).get("data_source_1c_synthetic")
    )
    budget_summary = pd.DataFrame()
    if (
        period_type_en == "Month"
        and not _is_1c_only_frame
        and "plan start" in filtered_df.columns
        and "plan end" in filtered_df.columns
    ):
        budget_summary = _bdds_build_monthly_summary_from_msp(filtered_df, period_col=period_col)
    if budget_summary.empty:
        budget_summary = (
            filtered_df.groupby([period_col, "project name"]).agg(agg_dict).reset_index()
        )

    # Store original period values for sorting before formatting
    budget_summary["period_original"] = budget_summary[period_col]
    budget_summary[period_col] = budget_summary[period_col].apply(format_period_ru)

    from dashboards.finance_from_1c import (
        build_bdds_plan_fact_analysis_table,
        expand_budget_month_grid,
        overlay_1c_on_budget_summary,
        overlay_turnover_monthly_on_budget_summary,
        resolve_budget_turnover_dannye,
    )

    _bdds_proj_keys: set[str] = set()
    if not _bdds_all_projects and selected_projects:
        _bdds_proj_keys = {_project_filter_norm_key(p) for p in selected_projects}
        _bdds_proj_keys.discard("")

    _bdds_ref_1c = resolve_reference_1c_dannye(_bdds_ref_boot)
    budget_summary, _bdds_overlay_1c = overlay_1c_on_budget_summary(
        budget_summary,
        period_col=period_col,
        period_start=_bdds_cal_start,
        period_end=_bdds_cal_end,
        project_norm_keys=_bdds_proj_keys or None,
        narrow_to_project_norm_key=_bdds_narrow_pk,
        reference_1c_dannye=_bdds_ref_1c,
    )
    if _bdds_overlay_1c:
        _bdds_used_1c = True

    try:
        from dashboards.finance_from_1c import try_synthetic_budget_from_1c_dannye

        _syn_hint = try_synthetic_budget_from_1c_dannye(reference_1c_dannye=_bdds_ref_1c)
        if _syn_hint is not None and not _syn_hint.empty and "plan_month" in _syn_hint.columns:
            _lm = pd.Period(_syn_hint["plan_month"].max(), freq="M")
            if not hasattr(filtered_df, "attrs") or filtered_df.attrs is None:
                filtered_df.attrs = {}
            filtered_df.attrs["bdds_1c_latest_month"] = format_period_ru(_lm)
    except Exception:
        pass

    if not _bdds_all_projects and len(selected_projects or []) == 1:
        budget_summary, _bdds_overlay_turn = overlay_turnover_monthly_on_budget_summary(
            budget_summary,
            period_col=period_col,
            project_name=str(selected_projects[0]),
            period_start=_bdds_cal_start,
            period_end=_bdds_cal_end,
            reference_1c_dannye=resolve_budget_turnover_dannye(_bdds_ref_1c),
            project_norm_keys=_bdds_proj_keys or None,
            narrow_to_project_norm_key=_bdds_narrow_pk,
        )

    budget_summary = _bdds_recalc_reserve(budget_summary)
    budget_summary = _bdds_normalize_period_original(budget_summary)

    _bdds_grid_fill = ["budget plan", "budget fact", "reserve budget"]
    if adjusted_budget_col:
        _bdds_grid_fill.append(adjusted_budget_col)
    if (
        period_type_en == "Month"
        and str(st.session_state.get("budget_period_view", "По месяцам")) == "По месяцам"
    ):
        budget_summary = expand_budget_month_grid(
            budget_summary,
            period_col=period_col,
            cal_start=_bdds_cal_start,
            cal_end=_bdds_cal_end,
            fill_columns=tuple(_bdds_grid_fill),
            group_by="project name" if "project name" in budget_summary.columns else None,
        )
        budget_summary = _bdds_recalc_reserve(budget_summary)
        budget_summary = _bdds_normalize_period_original(budget_summary)

    from dashboards.finance_from_1c import finalize_budget_summary_for_display

    budget_summary = finalize_budget_summary_for_display(
        budget_summary,
        period_col=period_col,
        period_start=_bdds_cal_start,
        period_end=_bdds_cal_end,
        project_norm_keys=_bdds_proj_keys or None,
        narrow_to_project_norm_key=_bdds_narrow_pk,
        reference_1c_dannye=_bdds_ref_1c,
    )
    budget_summary = _bdds_recalc_reserve(budget_summary)
    budget_summary = _bdds_normalize_period_original(budget_summary)

    # График и таблица — один источник; на графике пустые месяцы отфильтровываются отдельно.
    budget_summary_chart = budget_summary.copy()

    def _budget_period_chart():
        view_type = str(st.session_state.get("budget_period_view", "По месяцам"))
        _chart_src = budget_summary_chart

        def _bdds_chart_aggregate_by_period(src: pd.DataFrame) -> pd.DataFrame:
            if src is None or src.empty:
                return pd.DataFrame()
            agg_dict_all = {
                "budget plan": "sum",
                "budget fact": "sum",
                "reserve budget": "sum",
            }
            if adjusted_budget_col and adjusted_budget_col in src.columns:
                agg_dict_all[adjusted_budget_col] = "sum"
            grp_key = "period_original" if "period_original" in src.columns else period_col
            out = src.groupby(grp_key, dropna=False).agg(agg_dict_all).reset_index()
            if grp_key != period_col:
                out[period_col] = out[grp_key].apply(format_period_ru)
            try:
                out = out.sort_values(grp_key).reset_index(drop=True)
            except Exception:
                pass
            return out

        if not _bdds_all_projects:
            _sel_keys = {_project_filter_norm_key(p) for p in (selected_projects or [])}
            _sel_keys.discard("")
            project_data = _chart_src[
                _chart_src["project name"]
                .map(_project_filter_norm_key)
                .map(lambda rk: _project_norm_key_matches_msp_keys(rk, _sel_keys))
            ].copy()
        else:
            project_data = _chart_src.copy()
        project_data = _bdds_chart_aggregate_by_period(project_data)
        if project_data["period_original"].dtype == "object":
            try:
                project_data["period_sort"] = project_data["period_original"].apply(
                    lambda x: (
                        x if isinstance(x, pd.Period)
                        else (pd.Period(str(x), freq=period_type_en[0]) if pd.notna(x) else None)
                    )
                )
                project_data = project_data.sort_values("period_sort").copy()
                project_data = project_data.drop("period_sort", axis=1)
            except Exception:
                project_data = project_data.sort_values("period_original").copy()
        else:
            project_data = project_data.sort_values("period_original").copy()

        _hide_zero_months = bool(
            period_type_en == "Month"
            and view_type == "По месяцам"
            and st.session_state.get("budget_period_hide_zero_months", _bdds_all_projects)
        )

        def _bdds_chart_drop_empty_months(_df: pd.DataFrame) -> pd.DataFrame:
            if _df is None or _df.empty:
                return _df
            _pl = _df["budget plan"].fillna(0.0)
            _fc = _df["budget fact"].fillna(0.0)
            _keep = (_pl.abs() + _fc.abs()) >= _FINANCE_CHART_MIN_MONTH_RUB
            if (
                adjusted_budget_col
                and adjusted_budget_col in _df.columns
                and not hide_adjusted
            ):
                _keep = _keep | (
                    _df[adjusted_budget_col].fillna(0.0).abs() >= _FINANCE_CHART_MIN_MONTH_RUB
                )
            return _df.loc[_keep].copy()

        if view_type == "Накопительно":
            project_data["budget plan"] = project_data["budget plan"].cumsum()
            project_data["budget fact"] = project_data["budget fact"].cumsum()
            project_data["reserve budget"] = project_data["reserve budget"].cumsum()
            if adjusted_budget_col and adjusted_budget_col in project_data.columns:
                project_data[adjusted_budget_col] = project_data[adjusted_budget_col].cumsum()
        _bdds_gran = format_report_granularity_label(
            period_label, cumulative=view_type == "Накопительно"
        )
        _bdds_date_suffix = format_date_range_title_suffix(_bdds_cal_start, _bdds_cal_end)

        if (
            _hide_zero_months
            and period_type_en == "Month"
            and view_type == "По месяцам"
            and not project_data.empty
        ):
            project_data = _bdds_chart_drop_empty_months(project_data)
        if project_data.empty:
            st.info(
                "Нет периодов для графика. Снимите «Скрывать месяцы, где план и факт равны 0» "
                "или расширьте период/фильтры."
            )
            return

        _n = len(project_data)
        _is_cumulative = view_type == "Накопительно"
        # Подписи значений на столбцах — по ТЗ/UX всегда (раньше скрывались при накопительно >10).
        _hide_bar_value_labels = False
        _tlbl = 0.005
        _tlbl_dev = 0.01 if not _hide_bar_value_labels else _tlbl
        _tfs = 10 if _n > 32 else 11 if _n > 20 else 12 if _n > 12 else 13
        _bg, _bgg, _bar_w = _bdds_plotly_bar_layout(_n)
        # Нижнее поле под наклонные подписи месяцев + легенда (см. _plotly_legend_horizontal_below_plot).
        # Высота фигуры должна быть >= margin.t + margin.b + минимум для самих столбцов, иначе область графика ~0 px.
        _leg_b_pre = 300
        if _is_cumulative:
            _leg_b_pre = max(340, min(520, 300 + int(_n * 4.8)))
        elif _n > 24:
            _leg_b_pre = max(300, min(460, 280 + int(_n * 3.5)))
        _top_px_pre = (
            168 if _n <= 12 else (188 if _n <= 20 else 208)
        ) if not _hide_bar_value_labels else (72 if _n > 20 else 88)
        _min_plot_core_px = 400
        _ch_base = 600 if _n <= 20 else int(min(1100, 520 + int(_n * 1.4)))
        _ch = max(_ch_base, _top_px_pre + _leg_b_pre + _min_plot_core_px)
        _ch = int(min(1400, _ch))
        _xangle = -45 if _n <= 18 else -50 if _n <= 36 else -55
        _x_standoff = 30 if _n <= 18 else (44 if _n <= 36 else 56)

        _plan_txt = (
            None
            if _hide_bar_value_labels
            else _finance_bar_text_mln_rub(project_data["budget plan"], min_abs_mln=_tlbl, unit_suffix=" млн. руб.")
        )
        _fact_txt = (
            None
            if _hide_bar_value_labels
            else _finance_bar_text_mln_rub(project_data["budget fact"], min_abs_mln=_tlbl, unit_suffix=" млн. руб.")
        )
        _txt_pos = "none" if _hide_bar_value_labels else "outside"

        fig = go.Figure()
        _bdds_show_plan = (
            float(project_data["budget plan"].fillna(0.0).abs().sum())
            >= _FINANCE_CHART_MIN_MONTH_RUB
        )
        if _bdds_show_plan:
            fig.add_trace(
                go.Bar(
                    x=project_data[period_col],
                    y=project_data["budget plan"].div(1e6),
                    name="БДДС план",
                    marker_color="#2E86AB",
                    text=_plan_txt,
                    textposition=_txt_pos,
                    textfont=dict(size=_tfs, color=_fin_chart_label_color()),
                    customdata=project_data["budget plan"].apply(format_million_rub),
                    hovertemplate="<b>%{x}</b><br>БДДС план: %{customdata}<br><extra></extra>",
                )
            )
        fig.add_trace(
            go.Bar(
                x=project_data[period_col],
                y=project_data["budget fact"].div(1e6),
                name="БДДС факт",
                marker_color="#A23B72",
                text=_fact_txt,
                textposition=_txt_pos,
                textfont=dict(size=_tfs, color=_fin_chart_label_color()),
                customdata=project_data["budget fact"].apply(format_million_rub),
                hovertemplate="<b>%{x}</b><br>БДДС факт: %{customdata}<br><extra></extra>",
            )
        )
        if not hide_reserve:
            _dev_mln = project_data["reserve budget"].div(1e6)
            _dev_x = project_data[period_col]
            # БДДС: reserve = факт − план; < 0 — факт < план (красный), > 0 — факт > план (зелёный).
            _dev_thr_mln = 0.01
            _y_fact_lt_plan = _dev_mln.where(_dev_mln < -_dev_thr_mln)
            _y_fact_gt_plan = _dev_mln.where(_dev_mln > _dev_thr_mln)
            _bdds_dev_txt_lt = _finance_deviation_bar_text_signed_mln(
                _y_fact_lt_plan,
                min_abs_mln=_tlbl_dev,
                decimals=1,
                unit_suffix=" млн. руб.",
            )
            _bdds_dev_txt_gt = _finance_deviation_bar_text_signed_mln(
                _y_fact_gt_plan,
                min_abs_mln=_tlbl_dev,
                decimals=1,
                unit_suffix=" млн. руб.",
            )
            if _y_fact_lt_plan.notna().any():
                _txt_under = (
                    None
                    if _hide_bar_value_labels
                    else _bdds_dev_txt_lt
                )
                fig.add_trace(
                    go.Bar(
                        x=_dev_x,
                        y=_y_fact_lt_plan,
                        name="Отклонение (факт < план)",
                        marker_color=_FINANCE_DEV_BAR_RED,
                        text=_txt_under,
                        textposition="outside" if not _hide_bar_value_labels else "none",
                        textfont=dict(size=_tfs, color=_FINANCE_DEV_LABEL_RED),
                        cliponaxis=False,
                        customdata=_y_fact_lt_plan.map(
                            lambda v: format_million_rub(float(v) * 1e6) if pd.notna(v) else ""
                        ),
                        hovertemplate="<b>%{x}</b><br>Отклонение: %{customdata}<br><extra></extra>",
                    )
                )
            if _y_fact_gt_plan.notna().any():
                _txt_over = (
                    None
                    if _hide_bar_value_labels
                    else _bdds_dev_txt_gt
                )
                fig.add_trace(
                    go.Bar(
                        x=_dev_x,
                        y=_y_fact_gt_plan,
                        name="Отклонение (факт > план)",
                        marker_color=_FINANCE_DEV_BAR_GREEN,
                        text=_txt_over,
                        textposition="outside" if not _hide_bar_value_labels else "none",
                        textfont=dict(size=_tfs, color=_FINANCE_DEV_LABEL_GREEN),
                        cliponaxis=False,
                        customdata=_y_fact_gt_plan.map(
                            lambda v: format_million_rub(float(v) * 1e6) if pd.notna(v) else ""
                        ),
                        hovertemplate="<b>%{x}</b><br>Отклонение: %{customdata}<br><extra></extra>",
                    )
                )
        if (
            adjusted_budget_col
            and adjusted_budget_col in project_data.columns
            and not hide_adjusted
        ):
            _adj_txt = (
                None
                if _hide_bar_value_labels
                else _finance_bar_text_mln_rub(
                    project_data[adjusted_budget_col], min_abs_mln=_tlbl
                )
            )
            fig.add_trace(
                go.Bar(
                    x=project_data[period_col],
                    y=project_data[adjusted_budget_col].div(1e6),
                    name="Скорректированный бюджет",
                    marker_color="#F18F01",
                    text=_adj_txt,
                    textposition=_txt_pos,
                    textfont=dict(size=_tfs, color=_fin_chart_label_color()),
                    customdata=project_data[adjusted_budget_col].apply(format_million_rub),
                    hovertemplate="<b>%{x}</b><br>Скорректированный бюджет: %{customdata}<br><extra></extra>",
                )
            )
        fig.update_layout(
            title_text="",
            yaxis_title="млн рублей",
            barmode="group",
            bargap=_bg,
            bargroupgap=_bgg,
            xaxis=dict(
                title=dict(text=period_label, standoff=_x_standoff),
                tickangle=_xangle,
                tickfont=dict(size=finance_axis_tick_font_size(_n)),
                nticks=min(64, max(12, _n)),
            ),
        )
        fig = _apply_finance_bar_label_layout(fig)
        try:
            fig.update_layout(uniformtext=dict(minsize=1, mode="show"))
        except Exception:
            pass
        # Легенда под графиком (margin b согласован с расчётом высоты _ch выше).
        _leg_b = _leg_b_pre
        _leg_y = -0.34 if _n <= 20 else (-0.38 if _n <= 36 else -0.44)
        _top_px = _top_px_pre
        fig = _plotly_legend_horizontal_below_plot(
            fig, bottom_px=_leg_b, legend_y=_leg_y, top_px=_top_px
        )
        try:
            fig.update_xaxes(
                title=dict(text=period_label, standoff=_x_standoff),
                automargin=True,
            )
        except Exception:
            pass
        if not project_data.empty:
            _ymax = float(
                np.nanmax(
                    np.concatenate(
                        [
                            project_data["budget plan"].div(1e6).to_numpy(),
                            project_data["budget fact"].div(1e6).to_numpy(),
                            *(
                                [project_data["reserve budget"].div(1e6).to_numpy()]
                                if not hide_reserve
                                else []
                            ),
                        ]
                    )
                )
            )
            _ymin = 0.0
            if not hide_reserve:
                _ymin_dev = float(np.nanmin(_dev_mln.to_numpy()))
                if np.isfinite(_ymin_dev) and _ymin_dev < 0:
                    _ymin = _ymin_dev * 1.15
            if np.isfinite(_ymax):
                if _ymax > 0 or _ymin < 0:
                    pad = max(abs(_ymax), abs(_ymin), 1e-6) * 0.28
                    span = float(max(_ymax - _ymin, 1e-6))
                    head = max(span * 0.32, abs(_ymax) * 0.2, 0.75)
                    foot = pad if _ymin >= 0 else max(pad, abs(_ymin) * 0.24)
                    fig.update_layout(yaxis=dict(range=[_ymin - foot, _ymax + pad + head]))
        fig = apply_chart_background(fig)
        _bdds_bar_slots = 2 + (0 if hide_reserve else 2)
        if (
            adjusted_budget_col
            and adjusted_budget_col in project_data.columns
            and not hide_adjusted
        ):
            _bdds_bar_slots += 1
        _bdds_chart_caption = f"БДДС {_bdds_gran}"
        if _bdds_date_suffix:
            _bdds_chart_caption = f"{_bdds_chart_caption} ({_bdds_date_suffix})"
        _render_finance_bar_chart(
            fig,
            n_periods=_n,
            height=_ch,
            caption_below=_bdds_chart_caption,
            categories=project_data[period_col].astype(str).tolist(),
            px_per_month=400,
            force_hscroll=True,
            n_bar_slots=_bdds_bar_slots,
        )

        # Сводная таблица синхронизирована с «Вид отображения» (по месяцам / накопительно).
        _bdds_dev_tbl = "Отклонение, млн. руб."
        _bdds_sel = ", ".join(selected_projects) if selected_projects else "Все"
        render_table_subheader(
            st,
            f"БДДС {_bdds_gran}",
            filters_suffix=_bdds_date_suffix,
        )

        def _bdds_fmt_cell_rub(val) -> str:
            return format_million_rub(val, decimals=1)

        def _bdds_build_formatted_block(_src: pd.DataFrame, *, project_col_label: str) -> tuple[pd.DataFrame, dict]:
            """Возвращает отформатированный блок строк и сырые итоги по блоку (для одного проекта)."""
            _src = _src.sort_values("period_original").reset_index(drop=True)
            if _src.empty:
                return pd.DataFrame(), {}
            if (
                period_type_en == "Month"
                and view_type == "По месяцам"
                and bool(st.session_state.get("budget_period_hide_zero_months", _bdds_all_projects))
            ):
                _dp = pd.to_numeric(_src["budget plan"], errors="coerce").fillna(0.0)
                _df = pd.to_numeric(_src["budget fact"], errors="coerce").fillna(0.0)
                _src = _src.loc[(_dp.abs() + _df.abs()) >= _FINANCE_CHART_MIN_MONTH_RUB].copy()
                if _src.empty:
                    return pd.DataFrame(), {}
            _bdc = _src.copy()
            _bdc["_per_disp"] = _bdc[period_col]
            _bdc["Проект"] = project_col_label
            if hide_adjusted and adjusted_budget_col and adjusted_budget_col in _bdc.columns:
                _bdc = _bdc.drop(columns=[adjusted_budget_col], errors="ignore")
            num_triple = ["budget plan", "budget fact", "reserve budget"]
            if view_type == "Накопительно":
                for _cn in num_triple:
                    _bdc[_cn] = _bdc[_cn].fillna(0.0).cumsum()
                if adjusted_budget_col and adjusted_budget_col in _bdc.columns and not hide_adjusted:
                    _bdc[adjusted_budget_col] = (
                        pd.to_numeric(_bdc[adjusted_budget_col], errors="coerce").fillna(0.0).cumsum()
                    )
            _bdc = _bdds_recalc_reserve(_bdc)
            _bdc = _bdc.drop(columns=["period_original", period_col, "project name"], errors="ignore")
            # Правки куратора 08.05.2026: порядок колонок — Проект первый, Период второй.
            _cols_bdd = ["Проект", "_per_disp", "budget plan", "budget fact", "reserve budget"]
            if adjusted_budget_col and adjusted_budget_col in _bdc.columns and not hide_adjusted:
                _cols_bdd.append(adjusted_budget_col)
            _bdc = _bdc[_cols_bdd].copy()
            _bdc_fmt = _bdc.copy()
            for _cn in num_triple + (
                [adjusted_budget_col]
                if adjusted_budget_col and adjusted_budget_col in _bdc_fmt.columns
                else []
            ):
                if _cn in _bdc_fmt.columns:
                    _bdc_fmt[_cn] = _bdc_fmt[_cn].map(_bdds_fmt_cell_rub)
            _bdc_fmt["_row_kind"] = ""
            _tot_block: dict = {}
            if view_type == "Накопительно":
                _lr = _bdc.iloc[-1]
                _tot_block = {
                    "budget plan": float(_lr["budget plan"]),
                    "budget fact": float(_lr["budget fact"]),
                    "reserve budget": float(_lr["reserve budget"]),
                }
                if adjusted_budget_col and adjusted_budget_col in _bdc.columns and not hide_adjusted:
                    _tot_block[adjusted_budget_col] = float(_lr[adjusted_budget_col])
            else:
                _tot_block = {
                    "budget plan": float(_bdc["budget plan"].fillna(0.0).sum()),
                    "budget fact": float(_bdc["budget fact"].fillna(0.0).sum()),
                    "reserve budget": float(
                        _bdc["budget fact"].fillna(0.0).sum() - _bdc["budget plan"].fillna(0.0).sum()
                    ),
                }
                if adjusted_budget_col and adjusted_budget_col in _bdc.columns and not hide_adjusted:
                    _tot_block[adjusted_budget_col] = float(_bdc[adjusted_budget_col].fillna(0.0).sum())
            return _bdc_fmt, _tot_block

        _bdds_proj_labels_for_tbl: list[str] = []
        if "project name" in budget_summary.columns:
            if _bdds_all_projects:
                _bdds_proj_labels_for_tbl = _unique_project_labels_for_select(
                    budget_summary["project name"], apply_exclude_names=False
                )
            else:
                _bdds_proj_labels_for_tbl = list(selected_projects or [])

        def _bdds_slice_for_project(_pl: str) -> pd.DataFrame:
            _pk2 = _project_filter_norm_key(_pl)
            _slice = budget_summary[
                budget_summary["project name"]
                .map(_project_filter_norm_key)
                .map(lambda rk: _project_norm_key_matches_msp_keys(rk, {_pk2}))
            ].copy()
            if _slice.empty or "period_original" not in _slice.columns:
                return _slice
            _agg_slice: dict[str, str] = {
                "budget plan": "sum",
                "budget fact": "sum",
                "reserve budget": "sum",
                period_col: "first",
            }
            if adjusted_budget_col and adjusted_budget_col in _slice.columns:
                _agg_slice[adjusted_budget_col] = "sum"
            _slice = (
                _slice.groupby("period_original", dropna=False)
                .agg(_agg_slice)
                .reset_index()
            )
            return _bdds_recalc_reserve(_slice)

        _bdds_proj_labels_for_tbl = [
            _pl for _pl in _bdds_proj_labels_for_tbl if not _bdds_slice_for_project(_pl).empty
        ]

        def _bdds_tot_raw_from_summary(_bs_for_tot: pd.DataFrame) -> dict:
            if view_type == "Накопительно":
                _agg_tbl_tot = {
                    "budget plan": "sum",
                    "budget fact": "sum",
                    "reserve budget": "sum",
                    "period_original": "first",
                }
                if adjusted_budget_col and adjusted_budget_col in _bs_for_tot.columns:
                    _agg_tbl_tot[adjusted_budget_col] = "sum"
                _ag_tot = _bs_for_tot.groupby(period_col, dropna=False).agg(_agg_tbl_tot).reset_index()
                _ag_tot = _ag_tot.sort_values("period_original").reset_index(drop=True)
                for _cn in ["budget plan", "budget fact", "reserve budget"]:
                    _ag_tot[_cn] = _ag_tot[_cn].fillna(0.0).cumsum()
                if adjusted_budget_col and adjusted_budget_col in _ag_tot.columns and not hide_adjusted:
                    _ag_tot[adjusted_budget_col] = (
                        pd.to_numeric(_ag_tot[adjusted_budget_col], errors="coerce").fillna(0.0).cumsum()
                    )
                _ag_tot = _bdds_recalc_reserve(_ag_tot)
                _lr_gr = _ag_tot.iloc[-1]
                _out = {
                    "budget plan": float(_lr_gr["budget plan"]),
                    "budget fact": float(_lr_gr["budget fact"]),
                    "reserve budget": float(_lr_gr["reserve budget"]),
                }
                if adjusted_budget_col and adjusted_budget_col in _ag_tot.columns and not hide_adjusted:
                    _out[adjusted_budget_col] = float(_lr_gr[adjusted_budget_col])
                return _out
            _plan_tot = float(_bs_for_tot["budget plan"].fillna(0.0).sum())
            _fact_tot = float(_bs_for_tot["budget fact"].fillna(0.0).sum())
            _out = {
                "budget plan": _plan_tot,
                "budget fact": _fact_tot,
                "reserve budget": float(_fact_tot - _plan_tot),
            }
            if adjusted_budget_col and adjusted_budget_col in _bs_for_tot.columns and not hide_adjusted:
                _out[adjusted_budget_col] = float(_bs_for_tot[adjusted_budget_col].fillna(0.0).sum())
            return _out

        if len(_bdds_proj_labels_for_tbl) > 1:
            _parts_bdd: list[pd.DataFrame] = []
            for _pl in _bdds_proj_labels_for_tbl:
                _slice = _bdds_slice_for_project(_pl)
                _fmt_body, _ = _bdds_build_formatted_block(_slice, project_col_label="")
                if _fmt_body.empty:
                    continue
                _hdr_cells: dict = {
                    "Проект": str(_pl),
                    "_per_disp": "",
                    "budget plan": "",
                    "budget fact": "",
                    "reserve budget": "",
                    "_row_kind": "project",
                }
                if adjusted_budget_col and adjusted_budget_col in _fmt_body.columns and not hide_adjusted:
                    _hdr_cells[adjusted_budget_col] = ""
                _parts_bdd.append(pd.DataFrame([_hdr_cells]))
                _parts_bdd.append(_fmt_body)
            _bdc_fmt = pd.concat(_parts_bdd, ignore_index=True) if _parts_bdd else pd.DataFrame()
            _bs_for_tot = budget_summary
            if not _bdds_all_projects:
                _bs_for_tot = _filter_df_by_project_labels(budget_summary, selected_projects)
            _tot_raw = _bdds_tot_raw_from_summary(_bs_for_tot)
        elif len(_bdds_proj_labels_for_tbl) == 1:
            _pl_one = _bdds_proj_labels_for_tbl[0]
            _tbl_src2 = _bdds_slice_for_project(_pl_one)
            _bdc_fmt, _tot_raw = _bdds_build_formatted_block(
                _tbl_src2, project_col_label=str(_pl_one)
            )
        elif not _bdds_all_projects and len(selected_projects or []) == 1:
            _tbl_pk2 = _project_filter_norm_key(selected_projects[0])
            _tbl_src2 = budget_summary[
                budget_summary["project name"]
                .map(_project_filter_norm_key)
                .map(lambda rk: _project_norm_key_matches_msp_keys(rk, {_tbl_pk2}))
            ].copy()
            _tbl_src2 = _tbl_src2.sort_values("period_original").reset_index(drop=True)
            if _tbl_src2.empty:
                _bdc_fmt = pd.DataFrame()
                _tot_raw = {}
            else:
                _proj_one = str(selected_projects[0])
                _bdc_fmt, _tot_one = _bdds_build_formatted_block(_tbl_src2, project_col_label=_proj_one)
                _tot_raw = _tot_one
        else:
            _agg_tbl2 = {
                "budget plan": "sum",
                "budget fact": "sum",
                "reserve budget": "sum",
                "period_original": "first",
            }
            if adjusted_budget_col and adjusted_budget_col in budget_summary.columns:
                _agg_tbl2[adjusted_budget_col] = "sum"
            _tbl_src2 = budget_summary.groupby(period_col, dropna=False).agg(_agg_tbl2).reset_index()
            _tbl_src2 = _tbl_src2.sort_values("period_original").reset_index(drop=True)
            _bdc_fmt = pd.DataFrame()
            _tot_raw = {}
            if not _tbl_src2.empty:
                _bdc_fmt, _tot_raw = _bdds_build_formatted_block(_tbl_src2, project_col_label="Все")

        if (_bdds_all_projects and "project name" not in budget_summary.columns) or (
            not _bdds_all_projects and _bdc_fmt.empty and str(_bdds_sel).strip() != "Все"
        ):
            st.info("Нет строк для сводной таблицы по выбранным фильтрам.")
        elif _bdc_fmt.empty:
            st.info("Нет строк для сводной таблицы по выбранным фильтрам.")
        else:
            def _bdds_period_total_disp() -> str:
                if _bdds_cal_start is not None and _bdds_cal_end is not None:
                    try:
                        _s = pd.Timestamp(_bdds_cal_start).date()
                        _e = pd.Timestamp(_bdds_cal_end).date()
                        return f"{_s.strftime('%d.%m.%Y')} — {_e.strftime('%d.%m.%Y')}"
                    except Exception:
                        pass
                if not budget_summary.empty and "period_original" in budget_summary.columns:
                    try:
                        _po = budget_summary["period_original"].dropna()
                        if not _po.empty:
                            _p_min, _p_max = _po.min(), _po.max()
                            _fm = format_period_ru(_p_min)
                            _fx = format_period_ru(_p_max)
                            return _fm if _fm == _fx else f"{_fm} — {_fx}"
                    except Exception:
                        pass
                return ""

            _tot_vals_fmt: dict = {
                "Проект": "ИТОГО",
                "_per_disp": _bdds_period_total_disp(),
                "_row_kind": "total",
            }
            for _k, _v in _tot_raw.items():
                _tot_vals_fmt[_k] = _bdds_fmt_cell_rub(_v)

            _bdc_fmt = pd.concat([_bdc_fmt, pd.DataFrame([_tot_vals_fmt])], ignore_index=True)

            _rename_tbl = {
                "_per_disp": "Период",
                "budget plan": "План, млн. руб.",
                "budget fact": "Факт, млн. руб.",
                "reserve budget": _bdds_dev_tbl,
                **(
                    {adjusted_budget_col: "Скорр. бюджет, млн. руб."}
                    if adjusted_budget_col
                    and adjusted_budget_col in _bdc_fmt.columns
                    and not hide_adjusted
                    else {}
                ),
            }
            table_display = _bdc_fmt.rename(columns=_rename_tbl)

            _render_budget_table_html(
                    table_display,
                    finance_deviation_column=_bdds_dev_tbl,
                    deviation_color_fact_vs_plan=True,
                    row_kind_column="_row_kind",
                    emphasize_row_kinds=("project", "total"),
                    **_finance_table_html_kwargs(),
                )

    _budget_period_chart()

    if not _bdds_all_projects and len(selected_projects or []) == 1:
        _pf_proj = str(selected_projects[0])
        _pf_kw = _finance_table_html_kwargs(table_font_size_px=14)
        try:
            _pf_tbl = build_bdds_plan_fact_analysis_table(
                project_name=_pf_proj,
                period_start=_bdds_cal_start,
                period_end=_bdds_cal_end,
                reference_1c_dannye=resolve_budget_turnover_dannye(_bdds_ref_1c),
            )
            if _pf_tbl is not None and not _pf_tbl.empty:
                _pf_name, _pf_dates = report_title_parts(
                    "БДДС план-фактный анализ",
                    granularity=f"по проекту {_pf_proj}",
                    date_start=_bdds_cal_start,
                    date_end=_bdds_cal_end,
                )
                render_table_subheader(st, _pf_name, filters_suffix=_pf_dates)
                _render_budget_table_html(
                        _pf_tbl,
                        finance_deviation_column="Отклонение, млн. руб.",
                        deviation_color_fact_vs_plan=True,
                        row_kind_column="_row_kind",
                        emphasize_row_kinds=("project", "total"),
                        **{**_pf_kw, "table_scroll_max_height_vh": 55.0},
                    )
        except Exception as _pf_exc:
            st.error(
                f"Ошибка при построении таблицы «План-фактный анализ» по проекту {_pf_proj}: {_pf_exc}"
            )

    # R23-13.2 (стр.35): в БДДС дополнительно вывести таблицу
    # «Сводка бюджета по проекту» (как в БДР) с итоговой строкой «Итого».
    if "project name" in filtered_df.columns:
        _bdds_proj_name, _bdds_proj_dates = report_title_parts(
            "БДДС",
            granularity="по проектам",
            date_start=_bdds_cal_start,
            date_end=_bdds_cal_end,
        )
        render_table_subheader(
            st,
            _bdds_proj_name,
            filters_suffix=_bdds_proj_dates,
        )
        _bs_proj_tbl = budget_summary.copy()
        if (
            period_type_en == "Month"
            and str(st.session_state.get("budget_period_view", "По месяцам")) == "По месяцам"
            and bool(st.session_state.get("budget_period_hide_zero_months", _bdds_all_projects))
        ):
            _dp_pt = pd.to_numeric(_bs_proj_tbl["budget plan"], errors="coerce").fillna(0.0)
            _df_pt = pd.to_numeric(_bs_proj_tbl["budget fact"], errors="coerce").fillna(0.0)
            _bs_proj_tbl = _bs_proj_tbl.loc[
                (_dp_pt.abs() + _df_pt.abs()) >= _FINANCE_CHART_MIN_MONTH_RUB
            ].copy()
        if not _bdds_all_projects and selected_projects:
            _bs_proj_tbl = _filter_df_by_project_labels(_bs_proj_tbl, selected_projects)
        _bs_proj_tbl = _bs_proj_tbl.copy()
        _bs_proj_tbl["_norm_pk"] = _bs_proj_tbl["project name"].map(_project_filter_norm_key)
        _name_by_pk: dict[str, str] = {}
        for _nm, _pk in zip(_bs_proj_tbl["project name"], _bs_proj_tbl["_norm_pk"]):
            if _pk and (_pk not in _name_by_pk or len(str(_nm)) > len(_name_by_pk[_pk])):
                _name_by_pk[str(_pk)] = str(_nm)
        _bp = (
            _bs_proj_tbl.groupby("_norm_pk", dropna=False)
            .agg({"budget plan": "sum", "budget fact": "sum"})
            .reset_index()
        )
        _bp["project name"] = _bp["_norm_pk"].map(lambda k: _name_by_pk.get(str(k), str(k)))
        _bp["_dev"] = _bp["budget fact"] - _bp["budget plan"]
        _proj_tbl = pd.DataFrame(
            {
                "Проект": _bp["project name"].astype(str),
                "План, млн. руб.": _bp["budget plan"].map(lambda v: format_million_rub(v, decimals=1)),
                "Факт, млн. руб.": _bp["budget fact"].map(lambda v: format_million_rub(v, decimals=1)),
                "Отклонение, млн. руб.": _bp["_dev"].map(lambda v: format_million_rub(v, decimals=1)),
                "_row_kind": "",
            }
        )
        if not _proj_tbl.empty:
            _plan_sum = float(_bp["budget plan"].fillna(0.0).sum())
            _fact_sum = float(_bp["budget fact"].fillna(0.0).sum())
            _total_row = pd.DataFrame(
                [
                    {
                        "Проект": "ИТОГО",
                        "План, млн. руб.": format_million_rub(_plan_sum, decimals=1),
                        "Факт, млн. руб.": format_million_rub(_fact_sum, decimals=1),
                        "Отклонение, млн. руб.": format_million_rub(_fact_sum - _plan_sum, decimals=1),
                        "_row_kind": "total",
                    }
                ]
            )
            _proj_tbl = pd.concat([_proj_tbl, _total_row], ignore_index=True)
        _render_budget_table_html(
                _proj_tbl,
                finance_deviation_column="Отклонение, млн. руб.",
                deviation_color_fact_vs_plan=True,
                row_kind_column="_row_kind",
                emphasize_row_kinds=("total",),
                **_finance_table_html_kwargs(),
            )

    from dashboards.finance_from_1c import bddds_project_norm_keys_without_plan_scenario

    _bdds_hint_attrs = dict(getattr(filtered_df, "attrs", {}) or {})
    _bs_for_hints = budget_summary.copy()
    if not _bdds_all_projects and selected_projects:
        _bs_for_hints = _filter_df_by_project_labels(_bs_for_hints, selected_projects)
    _hint_plan_sum = float(
        pd.to_numeric(_bs_for_hints.get("budget plan"), errors="coerce").fillna(0.0).sum()
    )
    _hint_fact_sum = float(
        pd.to_numeric(_bs_for_hints.get("budget fact"), errors="coerce").fillna(0.0).sum()
    )
    if _hint_plan_sum < _FINANCE_CHART_MIN_MONTH_RUB:
        _bdds_hint_attrs.pop("bddds_plan_imputed_ratio", None)
    _no_plan_keys = bddds_project_norm_keys_without_plan_scenario(_bdds_ref_1c)
    _display_no_plan = False
    if _no_plan_keys and _hint_fact_sum >= _FINANCE_CHART_MIN_MONTH_RUB:
        if not _bdds_all_projects and selected_projects:
            _display_no_plan = any(
                _project_filter_norm_key(p) in _no_plan_keys for p in selected_projects
            )
        elif _bdds_all_projects:
            _display_no_plan = True
    _bdds_q_hints = collect_budget_1c_hints(
        _bdds_hint_attrs,
        used_fallback_1c=bool(_bdds_used_1c),
        display_has_plan=_hint_plan_sum >= _FINANCE_CHART_MIN_MONTH_RUB,
        display_no_plan_scenario=_display_no_plan,
    )

    render_quality_hints(_bdds_q_hints)


# ==================== DASHBOARD 6.5: Budget Cumulative ====================
def dashboard_budget_cumulative(df):


    with filters_panel(st, reset_keys=["budget_cum_"]):
        with filters_selectors(st):
            col1, col2, col3, col4, col5 = st.columns(5, gap="small")

            with col1:
                period_type = st.selectbox(
                    "Группировать по", ["Месяц", "Квартал", "Год"], key="budget_cum_period"
                )
            period_map = {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year"}
            period_type_en = period_map.get(period_type, "Month")

            with col2:
                if "project name" in df.columns:
                    projects = ["Все"] + _unique_project_labels_for_select(df["project name"])
                    selected_project = st.selectbox(
                        "Проект", projects, key="budget_cum_project"
                    )
                else:
                    selected_project = "Все"

            with col3:
                if "section" in df.columns:
                    sections = ["Все"] + sorted(df["section"].dropna().unique().tolist())
                    selected_section = st.selectbox(
                        "Этап", sections, key="budget_cum_section"
                    )
                else:
                    selected_section = "Все"

            _bcc_preview = df.copy()
            if selected_project != "Все" and "project name" in _bcc_preview.columns:
                _bcc_preview = _bcc_preview[
                    _bcc_preview["project name"].map(_project_filter_norm_key)
                    == _project_filter_norm_key(selected_project)
                ]
            if selected_section != "Все" and "section" in _bcc_preview.columns:
                _bcc_preview = _bcc_preview[
                    _bcc_preview["section"].astype(str).str.strip()
                    == str(selected_section).strip()
                ]
            selected_year = "Все"
            ensure_date_columns(_bcc_preview)
            with col4:
                if "plan end" in _bcc_preview.columns:
                    pe_y = pd.to_datetime(_bcc_preview["plan end"], errors="coerce")
                    if pe_y.notna().any():
                        _years = sorted({int(y) for y in pe_y.dt.year.dropna().unique().tolist()})
                        selected_year = st.selectbox(
                            "Год",
                            ["Все"] + [str(y) for y in _years],
                            key="budget_cum_year",
                        )

        with filters_toggles(st):
            _bcc_cb1, _bcc_cb2, _bcc_cb3, _bcc_cb4, _bcc_cb5 = st.columns(5, gap="small")
            with _bcc_cb1:
                hide_reserve = st.checkbox(
                    "Скрыть отклонение (столбец на графике)",
                    value=False,
                    key="budget_cum_hide_reserve",
                )

    filtered_df = df.copy()
    if selected_project != "Все" and "project name" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["project name"].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ]
    if selected_section != "Все" and "section" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["section"].astype(str).str.strip()
            == str(selected_section).strip()
        ]
    if selected_year != "Все":
        ensure_date_columns(filtered_df)
        if "plan end" in filtered_df.columns:
            pe_y = pd.to_datetime(filtered_df["plan end"], errors="coerce")
            try:
                filtered_df = filtered_df[pe_y.dt.year == int(selected_year)].copy()
            except (TypeError, ValueError):
                pass

    ensure_budget_columns(filtered_df)
    from dashboards.finance_from_1c import ensure_budget_frame_with_fallback
    from dashboards.data_quality_hints import collect_budget_1c_hints, render_quality_hints

    filtered_df, _bcc_used_1c = ensure_budget_frame_with_fallback(
        filtered_df,
        show_caption=True,
        restrict_projects_from_df=True,
        force_from_1c=False,
    )
    _bcc_q_hints = collect_budget_1c_hints(
        dict(getattr(filtered_df, "attrs", {}) or {}),
        used_fallback_1c=bool(_bcc_used_1c),
    )
    ensure_budget_columns(filtered_df)
    has_budget = (
        "budget plan" in filtered_df.columns and "budget fact" in filtered_df.columns
    )
    if not has_budget:
        st.warning("Столбцы бюджета (budget plan, budget fact) не найдены в данных.")
        return

    adjusted_budget_col = None
    if "budget adjusted" in filtered_df.columns:
        adjusted_budget_col = "budget adjusted"
    elif "adjusted budget" in filtered_df.columns:
        adjusted_budget_col = "adjusted budget"

    if "plan end" in filtered_df.columns:
        plan_end = pd.to_datetime(filtered_df["plan end"], errors="coerce")
        mask = plan_end.notna()
        if mask.any():
            if "plan_month" not in filtered_df.columns:
                filtered_df.loc[mask, "plan_month"] = plan_end.loc[mask].dt.to_period("M")
            if "plan_quarter" not in filtered_df.columns:
                filtered_df.loc[mask, "plan_quarter"] = plan_end.loc[mask].dt.to_period("Q")
            if "plan_year" not in filtered_df.columns:
                filtered_df.loc[mask, "plan_year"] = plan_end.loc[mask].dt.to_period("Y")

    if period_type_en == "Month":
        period_col = "plan_month"
        period_label = "Месяц"
    elif period_type_en == "Quarter":
        period_col = "plan_quarter"
        period_label = "Квартал"
    else:
        period_col = "plan_year"
        period_label = "Год"

    if period_col not in filtered_df.columns:
        st.warning(
            f"Столбец периода '{period_col}' не найден. Нужна дата в данных (например «Конец План» / plan end)."
        )
        return

    filtered_df["budget plan"] = pd.to_numeric(filtered_df["budget plan"], errors="coerce")
    filtered_df["budget fact"] = pd.to_numeric(filtered_df["budget fact"], errors="coerce")
    if adjusted_budget_col:
        filtered_df[adjusted_budget_col] = pd.to_numeric(
            filtered_df[adjusted_budget_col], errors="coerce"
        )
    filtered_df["reserve budget"] = filtered_df["budget plan"] - filtered_df["budget fact"]

    agg_dict = {"budget plan": "sum", "budget fact": "sum", "reserve budget": "sum"}
    if adjusted_budget_col:
        agg_dict[adjusted_budget_col] = "sum"

    budget_summary = (
        filtered_df.groupby([period_col, "project name"], dropna=False).agg(agg_dict).reset_index()
    )
    budget_summary["period_original"] = budget_summary[period_col]

    def _sort_period_df(b: pd.DataFrame) -> pd.DataFrame:
        if b.empty:
            return b
        po = b["period_original"]
        if po.dtype == "object":
            try:
                b = b.copy()
                b["_ps"] = po.apply(
                    lambda x: (
                        x
                        if isinstance(x, pd.Period)
                        else (pd.Period(str(x), freq=period_type_en[0]) if pd.notna(x) else pd.NaT)
                    )
                )
                b = b.sort_values("_ps").drop(columns=["_ps"])
            except Exception:
                b = b.sort_values("period_original")
        else:
            b = b.sort_values("period_original")
        return b

    # --- Таблица «по периоду» (не накопительно)
    render_table_subheader(
        st,
        f"БДДС {format_report_granularity_label(period_label, cumulative=False)}",
    )
    tbl_period = _sort_period_df(budget_summary.copy())
    tbl_period_disp = tbl_period.drop(columns=["period_original"], errors="ignore").copy()
    tbl_period_disp[period_col] = tbl_period_disp[period_col].apply(format_period_ru)
    tbl_period_disp["_row_kind"] = ""
    _tot_p = {
        period_col: "Итого",
        "project name": "",
        "budget plan": tbl_period_disp["budget plan"].sum(),
        "budget fact": tbl_period_disp["budget fact"].sum(),
        "reserve budget": (
            tbl_period_disp["budget plan"].sum() - tbl_period_disp["budget fact"].sum()
        ),
        "_row_kind": "total",
    }
    if adjusted_budget_col and adjusted_budget_col in tbl_period_disp.columns:
        _tot_p[adjusted_budget_col] = tbl_period_disp[adjusted_budget_col].sum()
    tbl_period_disp = pd.concat([tbl_period_disp, pd.DataFrame([_tot_p])], ignore_index=True)
    for c in ["budget plan", "budget fact", "reserve budget"] + (
        [adjusted_budget_col] if adjusted_budget_col and adjusted_budget_col in tbl_period_disp.columns else []
    ):
        if c in tbl_period_disp.columns:
            tbl_period_disp[c] = tbl_period_disp[c].map(format_million_rub)
    ren_p = {
        "budget plan": "БДДС план, млн. руб.",
        "budget fact": "БДДС факт, млн. руб.",
        "reserve budget": "Отклонение, млн. руб.",
        "project name": "Проект",
    }
    if adjusted_budget_col and adjusted_budget_col in tbl_period_disp.columns:
        ren_p[adjusted_budget_col] = "Скорр. бюджет, млн. руб."
    tbl_period_disp = tbl_period_disp.rename(columns=ren_p)
    if period_col in tbl_period_disp.columns:
        tbl_period_disp = tbl_period_disp.rename(columns={period_col: period_label})
    _render_budget_table_html(
            tbl_period_disp,
            finance_deviation_column="Отклонение, млн. руб.",
            deviation_red_if_negative=True,
            row_kind_column="_row_kind",
            emphasize_row_kinds=("total",),
            **_FINANCE_TABLE_HTML_KW,
        )

    # --- Накопительные ряды для графика (по выбранному проекту или сумма по всем)
    bs = _sort_period_df(budget_summary.copy())
    if selected_project != "Все":
        chart_src = bs[
            bs["project name"].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ].copy()
    else:
        agg_c = {"budget plan": "sum", "budget fact": "sum", "reserve budget": "sum"}
        if adjusted_budget_col:
            agg_c[adjusted_budget_col] = "sum"
        chart_src = bs.groupby(period_col, as_index=False).agg(agg_c)
        chart_src["period_original"] = chart_src[period_col]

    chart_src = _sort_period_df(chart_src)
    if chart_src.empty:
        st.info("Нет данных для графика накопительно по выбранным фильтрам.")
        render_quality_hints(_bcc_q_hints)
    else:
        chart_src["budget plan_cum"] = chart_src["budget plan"].cumsum()
        chart_src["budget fact_cum"] = chart_src["budget fact"].cumsum()
        chart_src["reserve_cum"] = chart_src["budget plan_cum"] - chart_src["budget fact_cum"]
        if adjusted_budget_col and adjusted_budget_col in chart_src.columns:
            chart_src[f"{adjusted_budget_col}_cum"] = chart_src[adjusted_budget_col].cumsum()

        x_labels = chart_src[period_col].apply(format_period_ru)

        fig_cum = go.Figure()
        fig_cum.add_trace(
            go.Bar(
                x=x_labels,
                y=chart_src["budget plan_cum"].div(1e6),
                name="БДДС план (накопительно)",
                marker_color="#2E86AB",
                text=_finance_bar_text_mln_rub(chart_src["budget plan_cum"]),
                textposition="outside",
                textfont=dict(size=11, color="#f0f4f8"),
                customdata=chart_src["budget plan_cum"].apply(format_million_rub),
                hovertemplate="<b>%{x}</b><br>БДДС план (накоп.): %{customdata}<extra></extra>",
            )
        )
        fig_cum.add_trace(
            go.Bar(
                x=x_labels,
                y=chart_src["budget fact_cum"].div(1e6),
                name="БДДС факт (накопительно)",
                marker_color="#A23B72",
                text=_finance_bar_text_mln_rub(chart_src["budget fact_cum"]),
                textposition="outside",
                textfont=dict(size=11, color="#f0f4f8"),
                customdata=chart_src["budget fact_cum"].apply(format_million_rub),
                hovertemplate="<b>%{x}</b><br>БДДС факт (накоп.): %{customdata}<extra></extra>",
            )
        )
        if not hide_reserve:
            fig_cum.add_trace(
                go.Bar(
                    x=x_labels,
                    y=chart_src["reserve_cum"].div(1e6),
                    name="Отклонение (накопительно)",
                    marker_color="#e74c3c",
                    text=_finance_deviation_bar_text_signed_mln(chart_src["reserve_cum"].div(1e6), decimals=1, unit_suffix=" млн. руб."),
                    textposition="outside",
                    textfont=dict(size=11, color="#f0f4f8"),
                    visible="legendonly",
                )
            )
        if adjusted_budget_col and adjusted_budget_col in chart_src.columns:
            fig_cum.add_trace(
                go.Bar(
                    x=x_labels,
                    y=chart_src[f"{adjusted_budget_col}_cum"].div(1e6),
                    name="Скорректированный бюджет (накопительно)",
                    marker_color="#F18F01",
                    text=_finance_bar_text_mln_rub(chart_src[f"{adjusted_budget_col}_cum"]),
                    textposition="outside",
                    textfont=dict(size=11, color="#f0f4f8"),
                )
            )

        fig_cum.update_layout(
            title_text="",
            yaxis_title="млн. руб.",
            barmode="group",
            bargap=0.18,
            bargroupgap=0.08,
            xaxis=dict(
                title=dict(text=period_label, standoff=26),
                tickangle=-45,
                tickfont=dict(size=10),
                nticks=18,
            ),
        )
        fig_cum = _apply_finance_bar_label_layout(fig_cum)
        fig_cum = _plotly_legend_horizontal_below_plot(fig_cum)
        _yc = [
            chart_src["budget plan_cum"].div(1e6).max(),
            chart_src["budget fact_cum"].div(1e6).max(),
            chart_src["reserve_cum"].div(1e6).max(),
        ]
        if adjusted_budget_col and f"{adjusted_budget_col}_cum" in chart_src.columns:
            _yc.append(chart_src[f"{adjusted_budget_col}_cum"].div(1e6).max())
        _ymax = float(np.nanmax(_yc)) if _yc else 0.0
        if np.isfinite(_ymax) and _ymax > 0:
            fig_cum.update_layout(yaxis=dict(range=[0, _ymax * 1.22]))
        fig_cum = apply_chart_background(fig_cum)
        render_chart(
            fig_cum,
            caption_below=report_chart_caption_body("БДДС", cumulative=True),
            height=600,
        )
        render_quality_hints(_bcc_q_hints)

    # --- Таблица «накопительно»: по каждому проекту — нарастающий итог по периодам
    render_table_subheader(
        st,
        f"БДДС {format_report_granularity_label(period_label, cumulative=True)}",
    )
    bs2 = _sort_period_df(budget_summary.copy())
    if selected_project != "Все":
        bs2 = bs2[
            bs2["project name"].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ].copy()
        bs2 = _sort_period_df(bs2)
    bs2["budget plan_cum"] = bs2.groupby("project name", dropna=False)["budget plan"].cumsum()
    bs2["budget fact_cum"] = bs2.groupby("project name", dropna=False)["budget fact"].cumsum()
    bs2["reserve_cum"] = bs2["budget plan_cum"] - bs2["budget fact_cum"]
    tbl_c = bs2[
        [
            period_col,
            "project name",
            "budget plan_cum",
            "budget fact_cum",
            "reserve_cum",
        ]
    ].copy()
    tbl_c["_row_kind"] = ""
    if not tbl_c.empty:
        if selected_project != "Все":
            lr = bs2.iloc[-1]
            _tot_c = {
                period_col: "Итого",
                "project name": "",
                "budget plan_cum": lr["budget plan_cum"],
                "budget fact_cum": lr["budget fact_cum"],
                "reserve_cum": lr["reserve_cum"],
                "_row_kind": "total",
            }
        else:
            last_pp = (
                bs2.sort_values("period_original")
                .groupby("project name", dropna=False)
                .last()
                .reset_index()
            )
            _tot_c = {
                period_col: "Итого",
                "project name": "",
                "budget plan_cum": last_pp["budget plan_cum"].sum(),
                "budget fact_cum": last_pp["budget fact_cum"].sum(),
                "reserve_cum": last_pp["budget plan_cum"].sum() - last_pp["budget fact_cum"].sum(),
                "_row_kind": "total",
            }
        tbl_c[period_col] = tbl_c[period_col].apply(format_period_ru)
        tbl_c = pd.concat([tbl_c, pd.DataFrame([_tot_c])], ignore_index=True)
    else:
        tbl_c[period_col] = tbl_c[period_col].apply(format_period_ru)
    for c in ["budget plan_cum", "budget fact_cum", "reserve_cum"]:
        tbl_c[c] = tbl_c[c].map(format_million_rub)
    tbl_c = tbl_c.rename(
        columns={
            period_col: period_label,
            "project name": "Проект",
            "budget plan_cum": "БДДС план (накоп.), млн. руб.",
            "budget fact_cum": "БДДС факт (накоп.), млн. руб.",
            "reserve_cum": "Отклонение (накоп.), млн. руб.",
        }
    )
    _render_budget_table_html(
            tbl_c,
            finance_deviation_column="Отклонение (накоп.), млн. руб.",
            deviation_red_if_negative=True,
            row_kind_column="_row_kind",
            emphasize_row_kinds=("total",),
            **_FINANCE_TABLE_HTML_KW,
        )
    render_quality_hints(_bcc_q_hints)


# ==================== DASHBOARD 7: Budget Plan/Fact/Reserve by Section by Period ====================
def dashboard_budget_by_section(df):
    with st.expander("Вид отображения", expanded=False):
        suppress_caption("По месяцам или накопительно — переключатель в блоке графика ниже.")

    with filters_panel(st, reset_keys=["budget_section*"]):
        col1, col2, col3 = st.columns(3, gap="small")

        with col1:
            period_type = st.selectbox(
                "Группировать по", ["Месяц", "Квартал", "Год"], key="budget_section_period"
            )
            period_map = {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year"}
            period_type_en = period_map.get(period_type, "Month")

        with col2:
            if "section" in df.columns:
                sections = ["Все"] + sorted(df["section"].dropna().unique().tolist())
                selected_section = st.selectbox(
                    "Этап", sections, key="budget_section"
                )
            else:
                selected_section = "Все"

        with col3:
            pass

        with filters_toggles(st):
            hide_reserve = st.checkbox(
                "Скрыть отклонение", value=True, key="budget_section_hide_reserve"
            )

    # Apply filters
    filtered_df = df.copy()
    if selected_section != "Все" and "section" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["section"].astype(str).str.strip()
            == str(selected_section).strip()
        ]

    # Check for budget columns (нормализуем русские названия)
    ensure_budget_columns(filtered_df)
    from dashboards.finance_from_1c import ensure_budget_frame_with_fallback
    from dashboards.data_quality_hints import collect_budget_1c_hints, render_quality_hints

    filtered_df, _bss_used_1c = ensure_budget_frame_with_fallback(
        filtered_df,
        show_caption=True,
        restrict_projects_from_df=True,
        force_from_1c=False,
    )
    _bss_q_hints = collect_budget_1c_hints(
        dict(getattr(filtered_df, "attrs", {}) or {}),
        used_fallback_1c=bool(_bss_used_1c),
    )
    ensure_budget_columns(filtered_df)
    has_budget = (
        "budget plan" in filtered_df.columns and "budget fact" in filtered_df.columns
    )

    if not has_budget:
        st.warning("Столбцы бюджета (budget plan, budget fact) не найдены в данных.")
        return

    # Determine period column
    if period_type_en == "Month":
        period_col = "plan_month"
        period_label = "Месяц"
    elif period_type_en == "Quarter":
        period_col = "plan_quarter"
        period_label = "Квартал"
    else:
        period_col = "plan_year"
        period_label = "Год"

    if period_col not in filtered_df.columns:
        st.warning(f"Столбец периода '{period_col}' не найден.")
        return

    # Отклонение = план − факт; отрицательное — красный, положительное — зелёный.
    filtered_df["budget plan"] = pd.to_numeric(
        filtered_df["budget plan"], errors="coerce"
    )
    filtered_df["budget fact"] = pd.to_numeric(
        filtered_df["budget fact"], errors="coerce"
    )
    filtered_df["reserve budget"] = (
        filtered_df["budget plan"] - filtered_df["budget fact"]
    )

    # Group by period and section
    budget_summary = (
        filtered_df.groupby([period_col, "section"])
        .agg({"budget plan": "sum", "budget fact": "sum", "reserve budget": "sum"})
        .reset_index()
    )

    # Store original period values for sorting before formatting
    budget_summary["period_original"] = budget_summary[period_col]
    budget_summary[period_col] = budget_summary[period_col].apply(format_period_ru)

    @st.fragment
    def _budget_section_chart():
        if selected_section != "Все":
            section_data = budget_summary[
                budget_summary["section"] == selected_section
            ].copy()
            if section_data["period_original"].dtype == "object":
                try:
                    section_data["period_sort"] = section_data["period_original"].apply(
                        lambda x: (
                            x if isinstance(x, pd.Period)
                            else (pd.Period(str(x), freq=period_type_en[0]) if pd.notna(x) else None)
                        )
                    )
                    section_data = section_data.sort_values("period_sort").copy()
                    section_data = section_data.drop("period_sort", axis=1)
                except Exception:
                    section_data = section_data.sort_values("period_original").copy()
            else:
                section_data = section_data.sort_values("period_original").copy()
            view_type = st.selectbox(
                "Вид отображения", ["По месяцам", "Накопительно"], key="budget_section_view"
            )
            if view_type == "Накопительно":
                section_data = section_data.copy()
                section_data["budget plan"] = section_data["budget plan"].cumsum()
                section_data["budget fact"] = section_data["budget fact"].cumsum()
                section_data["reserve budget"] = section_data["reserve budget"].cumsum()
            _bss_gran = format_report_granularity_label(
                period_label, cumulative=view_type == "Накопительно"
            )
            fig = go.Figure()
            fig.add_trace(
                go.Bar(
                    x=section_data[period_col],
                    y=section_data["budget plan"].div(1e6),
                    name="Бюджет План",
                    marker_color="#2E86AB",
                    text=_finance_bar_text_mln_rub(section_data["budget plan"]),
                    textposition="outside",
                    textfont=dict(size=18, color="white"),
                )
            )
            fig.add_trace(
                go.Bar(
                    x=section_data[period_col],
                    y=section_data["budget fact"].div(1e6),
                    name="Бюджет Факт",
                    marker_color="#A23B72",
                    text=_finance_bar_text_mln_rub(section_data["budget fact"]),
                    textposition="outside",
                    textfont=dict(size=18, color="white"),
                )
            )
            if not hide_reserve:
                dev_colors_sec = ["#e74c3c" if v >= 0 else "#27ae60" for v in section_data["reserve budget"]]
                fig.add_trace(
                    go.Bar(
                        x=section_data[period_col],
                        y=section_data["reserve budget"].div(1e6),
                        name="Отклонение",
                        marker_color=dev_colors_sec,
                        text=_finance_deviation_bar_text_signed_mln(section_data["reserve budget"].div(1e6), decimals=1, unit_suffix=" млн. руб."),
                        textposition="outside",
                        textfont=dict(size=18, color="white"),
                    )
                )
            fig.update_layout(
                title_text="",
                xaxis_title=dict(text=period_label, font=dict(size=20)),
                yaxis_title=dict(text="млн руб.", font=dict(size=20)),
                barmode="group",
                xaxis=dict(tickangle=0, tickfont=dict(size=16)),
                yaxis=dict(tickfont=dict(size=16)),
                legend=dict(font=dict(size=18)),
                height=600,
            )
            _lot_budget_caption = report_chart_caption_body(
                f"Бюджет по этапу «{selected_section}»",
                granularity=_bss_gran,
            )
        else:
            # Все этапы: ось Y = этапы, ось X = млн руб.
            section_chart_data = (
                budget_summary.groupby("section")
                .agg({"budget plan": "sum", "budget fact": "sum", "reserve budget": "sum"})
                .reset_index()
            )
            section_chart_data = section_chart_data.sort_values("budget plan", ascending=True)
            fig = go.Figure()
            fig.add_trace(
                go.Bar(
                    y=section_chart_data["section"],
                    x=section_chart_data["budget plan"].div(1e6),
                    name="Бюджет План",
                    marker_color="#2E86AB",
                    text=_finance_bar_text_mln_rub(section_chart_data["budget plan"]),
                    textposition="outside",
                    textfont=dict(size=18, color="white"),
                    orientation="h",
                )
            )
            fig.add_trace(
                go.Bar(
                    y=section_chart_data["section"],
                    x=section_chart_data["budget fact"].div(1e6),
                    name="Бюджет Факт",
                    marker_color="#A23B72",
                    text=_finance_bar_text_mln_rub(section_chart_data["budget fact"]),
                    textposition="outside",
                    textfont=dict(size=18, color="white"),
                    orientation="h",
                )
            )
            if not hide_reserve:
                dev_colors_sec = ["#e74c3c" if v >= 0 else "#27ae60" for v in section_chart_data["reserve budget"]]
                fig.add_trace(
                    go.Bar(
                        y=section_chart_data["section"],
                        x=section_chart_data["reserve budget"].div(1e6),
                        name="Отклонение",
                        marker_color=dev_colors_sec,
                        text=_finance_deviation_bar_text_signed_mln(section_chart_data["reserve budget"].div(1e6), decimals=1, unit_suffix=" млн. руб."),
                        textposition="outside",
                        textfont=dict(size=18, color="white"),
                        orientation="h",
                    )
                )
            fig.update_layout(
                title_text="",
                xaxis_title=dict(text="млн руб.", font=dict(size=20)),
                yaxis_title=dict(text="Этапы", font=dict(size=20)),
                barmode="group",
                xaxis=dict(tickangle=0, tickfont=dict(size=16)),
                yaxis=dict(tickfont=dict(size=16), categoryorder="trace order"),
                legend=dict(font=dict(size=18)),
                height=max(400, len(section_chart_data) * 44),
            )
            _lot_budget_caption = report_chart_caption_body(
                "Бюджет по этапам", granularity="по этапам"
            )
        fig = _apply_finance_bar_label_layout(fig)
        fig = apply_chart_background(fig)
        render_chart(fig, caption_below=_lot_budget_caption)
        render_quality_hints(_bss_q_hints)

    _budget_section_chart()

    # Summary table — в млн руб., два знака после запятой
    _bss_tbl_name, _ = report_title_parts("Бюджет по этапам", period_label)
    render_table_subheader(st, _bss_tbl_name)
    table_section = budget_summary.drop(columns=["period_original"], errors="ignore").copy()
    for col in ["budget plan", "budget fact", "reserve budget"]:
        if col in table_section.columns:
            table_section[col] = (table_section[col] / 1e6).round(2).apply(
                lambda x: f"{float(x):.2f} млн руб." if pd.notna(x) else ""
            )
    table_section = table_section.rename(columns={
        "budget plan": "Бюджет План, млн руб.",
        "budget fact": "Бюджет Факт, млн руб.",
        "reserve budget": "Отклонение, млн руб.",
    })
    _render_budget_table_html(
            table_section,
            finance_deviation_column="Отклонение, млн руб.",
            deviation_red_if_negative=True,
            **_FINANCE_TABLE_HTML_KW,
        )
    render_quality_hints(_bss_q_hints)


# ==================== DASHBOARD: БДР (бюджет доходов и расходов) ====================
def dashboard_bdr(df):
    """
    БДР: режим ТЗ (план/факт/отклонение расходов из 1С по статьям «(БДР)» и сценариям)
    или классический режим доходы / расходы / сальдо; помесячно / накопительно.
    Fallback из 1С — обороты БДР по расходам (не БДДС).
    """
    if df is None or not hasattr(df, "columns") or df.empty:
        st.warning("⚠️ Нет данных для отображения. Загрузите данные проекта.")
        return
    from dashboards.finance_from_1c import ensure_bdr_frame_with_fallback

    df_src = df.copy()

    def _clean_filter_label(v) -> str:
        if v is None or (isinstance(v, float) and pd.isna(v)):
            return ""
        s = str(v).replace("\xa0", " ").replace("\u200b", "").replace("\ufeff", "").strip()
        if not s:
            return ""
        for ch in ('"', "'", "`", "«", "»", "“", "”", "‘", "’"):
            s = s.replace(ch, "")
        s = re.sub(r"^[\*\-–—•·\s]+", "", s)
        s = re.sub(r"\s+", " ", s)
        s = re.sub(r"\s*[,;:.-]\s*$", "", s).strip()
        return s

    def _derive_bdr_dimensions(_df: pd.DataFrame) -> pd.DataFrame:
        if _df is None or getattr(_df, "empty", True):
            return _df
        out = _df.copy()
        task_col = "task name" if "task name" in out.columns else ("Название" if "Название" in out.columns else None)
        lvl_col = "level structure" if "level structure" in out.columns else ("level" if "level" in out.columns else None)
        proj_col = "project name" if "project name" in out.columns else None
        lot_src = "lot" if "lot" in out.columns else ("ЛОТ" if "ЛОТ" in out.columns else None)
        if task_col is None or lvl_col is None:
            if "stage_l2" not in out.columns:
                out["stage_l2"] = ""
            if "lot_effective" not in out.columns:
                out["lot_effective"] = out.get(lot_src, "")
            return out

        sort_col = "task id seq" if "task id seq" in out.columns else ("Ид" if "Ид" in out.columns else None)

        def _norm_text(v):
            if v is None or (isinstance(v, float) and pd.isna(v)):
                return ""
            return str(v).replace("\xa0", " ").replace("\u200b", "").replace("\ufeff", "").strip()

        def _process_group(g: pd.DataFrame) -> pd.DataFrame:
            gg = g.copy()
            if sort_col and sort_col in gg.columns:
                gg = gg.sort_values(sort_col, key=lambda s: pd.to_numeric(s, errors="coerce")).copy()
            stage_vals, lot_vals = [], []
            stack_task, stack_lot = {}, {}
            for _, r in gg.iterrows():
                lv = pd.to_numeric(r.get(lvl_col), errors="coerce")
                try:
                    lvi = int(lv)
                except Exception:
                    lvi = -1
                if lvi > 0:
                    for k in list(stack_task.keys()):
                        if k >= lvi:
                            del stack_task[k]
                    for k in list(stack_lot.keys()):
                        if k >= lvi:
                            del stack_lot[k]
                tname = _norm_text(r.get(task_col))
                lot_here = _norm_text(r.get(lot_src)) if lot_src else ""
                stage = tname if (lvi == 2 and tname) else stack_task.get(2, "")
                lot_eff = lot_here if lot_here else (stack_lot.get(2, "") or stack_lot.get(3, "") or stack_lot.get(1, ""))
                stage_vals.append(stage)
                lot_vals.append(lot_eff)
                if lvi > 0 and tname:
                    stack_task[lvi] = tname
                if lvi > 0 and lot_here:
                    stack_lot[lvi] = lot_here
            gg["stage_l2"] = stage_vals
            gg["lot_effective"] = lot_vals
            return gg

        if proj_col and proj_col in out.columns:
            parts = []
            for _, g in out.groupby(out[proj_col].astype(str), sort=False):
                parts.append(_process_group(g))
            return pd.concat(parts, axis=0)
        return _process_group(out)

    def _coerce_bdr_amount_series(raw: pd.Series) -> pd.Series:
        """
        Нормализует денежные значения из 1С/CSV:
        - пробелы/неразрывные пробелы как разделители тысяч;
        - десятичная запятая;
        - скобки для отрицательных значений;
        - хвосты вида «руб.», «₽», мусорные символы.
        """
        if raw is None:
            return pd.Series(dtype="float64")
        s = raw.astype(str).str.strip()
        s = s.replace({"": np.nan, "nan": np.nan, "None": np.nan, "null": np.nan})

        # (123,45) -> -123,45
        s = s.str.replace(r"^\((.*)\)$", r"-\1", regex=True)

        # Убираем валютные/служебные символы, оставляя только знаки/цифры/разделители.
        s = s.str.replace(r"[^0-9,\.\-]", "", regex=True)

        # Если есть и точка, и запятая — считаем точку разделителем тысяч, запятую десятичной.
        mixed = s.str.contains(",", na=False) & s.str.contains(r"\.", na=False)
        s.loc[mixed] = s.loc[mixed].str.replace(".", "", regex=False)

        # Если только запятая — делаем её десятичной.
        only_comma = s.str.contains(",", na=False) & ~s.str.contains(r"\.", na=False)
        s.loc[only_comma] = s.loc[only_comma].str.replace(",", ".", regex=False)

        # Если несколько точек, оставляем последнюю как десятичный разделитель.
        multi_dot = s.str.count(r"\.").fillna(0) > 1
        if bool(multi_dot.any()):
            s.loc[multi_dot] = s.loc[multi_dot].str.replace(
                r"\.(?=.*\.)", "", regex=True
            )

        return pd.to_numeric(s, errors="coerce")

    def _bdr_dimension_combos_by_project_key(msp_derived: pd.DataFrame) -> dict[str, list[dict]]:
        """Уникальные пары лот/этап по нормализованному ключу проекта (как в фильтрах БДДС)."""
        out: dict[str, list[dict]] = {}
        if (
            msp_derived is None
            or getattr(msp_derived, "empty", True)
            or "project name" not in msp_derived.columns
        ):
            return out
        for _, rr in msp_derived.iterrows():
            pk = _project_filter_norm_key(rr.get("project name"))
            if not pk:
                continue
            lr = rr.get("lot_effective") if "lot_effective" in msp_derived.columns else rr.get("lot")
            sr = rr.get("stage_l2") if "stage_l2" in msp_derived.columns else rr.get("section")
            lr_s = "" if lr is None or (isinstance(lr, float) and pd.isna(lr)) else str(lr).strip()
            sr_s = "" if sr is None or (isinstance(sr, float) and pd.isna(sr)) else str(sr).strip()
            cl = _clean_filter_label(lr_s)
            cs = _clean_filter_label(sr_s)
            if not cl and not cs:
                continue
            bucket = out.setdefault(pk, [])
            entry = {"lot_disp": lr_s or lr, "stage_disp": sr_s or sr, "clean_lot": cl, "clean_stage": cs}
            if entry not in bucket:
                bucket.append(entry)
        return out

    def _spread_bdr_synthetic_with_msp_dims(
        synth: pd.DataFrame,
        msp_derived: pd.DataFrame,
    ) -> pd.DataFrame:
        """
        Синтетика БДР из 1С без лота/этапа: добавляем комбинации из MSP на проект и делим суммы поровну,
        чтобы фильтры по лоту/этапу работали и не раздували итоги при выборе «Все».
        """
        if synth is None or getattr(synth, "empty", True):
            return synth
        if not bool(getattr(synth, "attrs", {}).get("data_source_1c_synthetic_bdr")):
            return synth
        combos_map = _bdr_dimension_combos_by_project_key(msp_derived)
        if not combos_map:
            return synth
        money_cols = [
            c
            for c in (
                "bdr_plan_expense",
                "bdr_fact_expense",
                "bdr_expense_deviation",
                "bdr_income",
                "bdr_expense",
                "bdr_saldo",
            )
            if c in synth.columns
        ]
        base_need = ("project name", "plan end")
        if not money_cols or any(c not in synth.columns for c in base_need):
            return synth
        rows_exp: list[dict] = []
        for _, r in synth.iterrows():
            pj = r.get("project name")
            pk_s = _project_filter_norm_key(pj)
            combos: list[dict] = combos_map.get(pk_s, []) if pk_s else []
            if not combos:
                cand: list[list[dict]] = []
                for k_msp, combos_m in combos_map.items():
                    if _project_norm_key_matches_msp_keys(pk_s, {k_msp}):
                        cand.append(combos_m)
                    elif pk_s and k_msp and _project_norm_key_matches_msp_keys(k_msp, {pk_s}):
                        cand.append(combos_m)
                if cand:
                    seen_k: set[tuple[str, str]] = set()
                    merged: list[dict] = []
                    for block in cand:
                        for ent in block:
                            tkey = (str(ent.get("clean_lot")), str(ent.get("clean_stage")))
                            if tkey in seen_k:
                                continue
                            seen_k.add(tkey)
                            merged.append(ent)
                    combos = merged
            k = len(combos) if combos else 0
            if k <= 0:
                rr = dict(r)
                rr.setdefault("lot_effective", "")
                rr.setdefault("stage_l2", "")
                rows_exp.append(rr)
                continue
            inv = 1.0 / float(k)
            for ent in combos:
                rr = dict(r)
                for money in money_cols:
                    try:
                        v = float(rr.get(money, np.nan))
                    except Exception:
                        v = np.nan
                    rr[money] = (v * inv) if np.isfinite(v) else v
                rr["lot_effective"] = str(ent.get("lot_disp") or "")
                rr["stage_l2"] = str(ent.get("stage_disp") or "")
                if "section" in synth.columns:
                    rr["section"] = (
                        ent.get("clean_stage") or rr.get("section") or rr.get("stage_l2") or ""
                    )
                rows_exp.append(rr)
        if not rows_exp:
            return synth
        odf = pd.DataFrame(rows_exp)
        try:
            odf.attrs.update(dict(getattr(synth, "attrs", {}) or {}))
        except Exception:
            pass
        odf.attrs["bdr_synthetic_split_by_msp_dims"] = True
        # Периоды после explode
        if "plan end" in odf.columns:
            _pe2 = pd.to_datetime(odf["plan end"], errors="coerce")
            odf["plan_month"] = _pe2.dt.to_period("M")
            odf["plan_quarter"] = _pe2.dt.to_period("Q")
            odf["plan_year"] = _pe2.dt.to_period("Y")
        return odf

    if "project name" in df_src.columns:
        df_src = _project_column_apply_canonical(df_src, "project name")
    df_derived_filters = _derive_bdr_dimensions(df_src)
    df_work = df_derived_filters.copy()
    ensure_budget_columns(df_work)
    df_work, _ = ensure_bdr_frame_with_fallback(df_work)
    df_work = _spread_bdr_synthetic_with_msp_dims(df_work, df_derived_filters)
    ensure_budget_columns(df_work)
    ensure_date_columns(df_work)

    def find_col(df, variants):
        for v in variants:
            for c in df.columns:
                if str(c).strip().lower() == v.lower() or v.lower() in str(c).lower():
                    return c
        return None

    plan_ec = find_col(df_work, ["bdr_plan_expense"])
    fact_ec = find_col(df_work, ["bdr_fact_expense"])
    dev_ec = find_col(df_work, ["bdr_expense_deviation", "bdr_expense_deviance"])
    if plan_ec is None or fact_ec is None:
        from dashboards.finance_from_1c import try_synthetic_bdr_from_1c_dannye

        _bdr_syn_only = try_synthetic_bdr_from_1c_dannye()
        if _bdr_syn_only is not None and not getattr(_bdr_syn_only, "empty", True):
            df_work = _spread_bdr_synthetic_with_msp_dims(_bdr_syn_only, df_derived_filters)
            ensure_budget_columns(df_work)
            ensure_date_columns(df_work)
            plan_ec = find_col(df_work, ["bdr_plan_expense"])
            fact_ec = find_col(df_work, ["bdr_fact_expense"])
            dev_ec = find_col(df_work, ["bdr_expense_deviation", "bdr_expense_deviance"])
    bdr_tz_mode = False
    if plan_ec is not None and fact_ec is not None:
        bdr_tz_mode = True

    income_col = None
    expense_col = None
    if not bdr_tz_mode:
        income_col = find_col(
            df_work,
            [
                "bdr_income",
                "доходы",
                "доход",
                "revenue",
                "income",
            ],
        )
        expense_col = find_col(
            df_work,
            [
                "bdr_expense",
                "расходы",
                "расход",
                "expenses",
                "expense",
            ],
        )
        if income_col is None or expense_col is None:
            st.warning(
                "Для отчёта БДР нужны столбцы доходов и расходов "
                "(например «доходы» / «расходы» после загрузки `*_dannye.json`)."
            )
            return

    _bdr_cal_start = None
    _bdr_cal_end = None
    # Как БДДС: период / проект / год — список проектов из MSP; год после фильтра по проекту.
    with filters_panel(
        st,
        reset_keys=["bdr_project", "bdr_period*", "_bdr_period_scope"],
        reset_defaults={
            "bdr_project": "Все",
            "bdr_period": "Месяц",
            "bdr_period_view": "По месяцам",
        },
    ):
        with filters_selectors(st):
            col1, col2, col3, col4, _col5 = st.columns(5, gap="small")
            with col1:
                _bdr_opts_src = (
                    df_work
                    if (
                        df_work is not None
                        and not getattr(df_work, "empty", True)
                        and "project name" in df_work.columns
                    )
                    else df_src
                )
                if "project name" in getattr(_bdr_opts_src, "columns", []):
                    from dashboards.finance_from_1c import (
                        restrict_project_filter_labels_to_finance_data,
                    )

                    _bdr_proj_opts = restrict_project_filter_labels_to_finance_data(
                        _unique_project_labels_for_select(_bdr_opts_src["project name"]),
                        _bdr_opts_src,
                        kind="bdr",
                    )
                    projects = ["Все"] + list(_bdr_proj_opts)
                    try:
                        _cur_bdr = str(st.session_state.get("bdr_project") or "").strip()
                        if _cur_bdr and _cur_bdr != "Все" and _cur_bdr not in projects:
                            st.session_state["bdr_project"] = "Все"
                    except Exception:
                        pass
                    selected_project = st.selectbox(
                        "Проект", projects, key="bdr_project"
                    )
                else:
                    selected_project = "Все"
            with col2:
                _bdr_proj_df = df_work.copy()
                if selected_project != "Все" and "project name" in _bdr_proj_df.columns:
                    _bdr_proj_df = _bdr_proj_df[
                        _bdr_proj_df["project name"].map(_project_filter_norm_key)
                        == _project_filter_norm_key(selected_project)
                    ].copy()
                ensure_date_columns(_bdr_proj_df)
                _bdr_period_from, _bdr_period_to = None, None
                if "plan end" in _bdr_proj_df.columns:
                    _pe_series_bdr = pd.to_datetime(_bdr_proj_df["plan end"], errors="coerce")
                    if _pe_series_bdr.notna().any():
                        _bdr_min = _pe_series_bdr.min()
                        _bdr_max = _pe_series_bdr.max()
                        _bdr_start = _bdr_min.date() if pd.notna(_bdr_min) else None
                        _bdr_end = _bdr_max.date() if pd.notna(_bdr_max) else None
                        try:
                            _pe_all_bdr = pd.to_datetime(df["plan end"], errors="coerce")
                            if _pe_all_bdr.notna().any():
                                _bdr_min_all = _pe_all_bdr.min().date()
                                _bdr_max_all = _pe_all_bdr.max().date()
                            else:
                                _bdr_min_all, _bdr_max_all = _bdr_start, _bdr_end
                        except Exception:
                            _bdr_min_all, _bdr_max_all = _bdr_start, _bdr_end
                        if _bdr_start and _bdr_end:
                            _bdr_scope = str(selected_project or "Все").strip() or "Все"
                            if st.session_state.get("_bdr_period_scope") != _bdr_scope:
                                st.session_state["_bdr_period_scope"] = _bdr_scope
                                st.session_state.pop("bdr_period_range", None)
                        _bdr_period_from, _bdr_period_to = period_date_range_input(
                            st,
                            "bdr_period_range",
                            min_value=_bdr_min_all or _bdr_start,
                            max_value=_bdr_max_all or _bdr_end,
                            default=(_bdr_start, _bdr_end) if _bdr_start and _bdr_end else None,
                            help="Диапазон по полю «Конец план».",
                        )
            with col3:
                period_type = st.selectbox(
                    "Группировать по", ["Месяц", "Квартал", "Год"], key="bdr_period"
                )
            period_map = {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year"}
            period_type_en = period_map.get(period_type, "Month")
            with col4:
                st.selectbox(
                    "Представление",
                    ["По месяцам", "Накопительно"],
                    key="bdr_period_view",
                    help="Как строить график и сводную таблицу: по периодам или накопительно.",
                )

        if period_type_en == "Month":
            period_col = "plan_month"
            period_label = "Месяц"
        elif period_type_en == "Quarter":
            period_col = "plan_quarter"
            period_label = "Квартал"
        else:
            period_col = "plan_year"
            period_label = "Год"

        if period_col not in df_work.columns:
            st.warning(f"Столбец периода «{period_col}» не найден. Добавьте даты в данные.")
            return

        filtered_df = _bdr_proj_df.copy()
        if _bdr_period_from is not None and _bdr_period_to is not None and "plan end" in filtered_df.columns:
            _pe_series_bdr = pd.to_datetime(filtered_df["plan end"], errors="coerce")
            _bdr_from = pd.to_datetime(_bdr_period_from, errors="coerce")
            _bdr_to = pd.to_datetime(_bdr_period_to, errors="coerce")
            if pd.notna(_bdr_from) and pd.notna(_bdr_to):
                if _bdr_from > _bdr_to:
                    _bdr_from, _bdr_to = _bdr_to, _bdr_from
                filtered_df = filtered_df[
                    (_pe_series_bdr >= _bdr_from)
                    & (_pe_series_bdr <= (_bdr_to + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)))
                ].copy()
                _bdr_cal_start = _bdr_from
                _bdr_cal_end = _bdr_to

        _bdr_all_projects = str(selected_project).strip() in ("", "Все")
        _bdr_view_monthly = str(st.session_state.get("bdr_period_view", "По месяцам")) == "По месяцам"
        with filters_toggles(st):
            _bdr_cb1, _bdr_cb2, _bdr_cb3, _bdr_cb4, _bdr_cb5 = st.columns(5, gap="small")
            with _bdr_cb1:
                if bdr_tz_mode:
                    st.checkbox(
                        "Скрыть отклонение",
                        value=False,
                        key="bdr_hide_deviation_tz",
                    )
            with _bdr_cb2:
                if period_type_en == "Month" and _bdr_view_monthly:
                    if bdr_tz_mode:
                        st.checkbox(
                            "Скрывать месяцы, где план и факт расходов равны 0",
                            value=bool(_bdr_all_projects),
                            key="bdr_hide_zero_months_tz",
                        )
                    else:
                        st.checkbox(
                            "Скрывать месяцы, где доходы и расходы равны 0",
                            value=True,
                            key="bdr_hide_zero_months",
                        )
    
    if bdr_tz_mode:
        filtered_df["_plan_exp"] = _coerce_bdr_amount_series(filtered_df[plan_ec]).fillna(0.0)
        filtered_df["_fact_exp"] = _coerce_bdr_amount_series(filtered_df[fact_ec]).fillna(0.0)
        if dev_ec is not None:
            filtered_df["_dev"] = _coerce_bdr_amount_series(filtered_df[dev_ec]).fillna(0.0)
        else:
            filtered_df["_dev"] = filtered_df["_fact_exp"] - filtered_df["_plan_exp"]
        bdr_summary = (
            filtered_df.groupby(period_col, dropna=False)
            .agg({"_plan_exp": "sum", "_fact_exp": "sum"})
            .reset_index()
        )
        bdr_summary = bdr_summary.rename(
            columns={
                "_plan_exp": "План расходов",
                "_fact_exp": "Факт расходов",
            }
        )
        bdr_summary["Отклонение"] = (
            bdr_summary["Факт расходов"] - bdr_summary["План расходов"]
        )
    else:
        filtered_df["_inc"] = _coerce_bdr_amount_series(filtered_df[income_col]).fillna(0.0)
        filtered_df["_exp"] = _coerce_bdr_amount_series(filtered_df[expense_col]).fillna(0.0)
        filtered_df["_saldo"] = filtered_df["_inc"] - filtered_df["_exp"]

        agg_dict = {"_inc": "sum", "_exp": "sum", "_saldo": "sum"}
        bdr_summary = filtered_df.groupby(period_col).agg(agg_dict).reset_index()
        bdr_summary = bdr_summary.rename(
            columns={
                "_inc": "Доходы",
                "_exp": "Расходы",
                "_saldo": "Сальдо",
            }
        )

    bdr_summary["Период"] = bdr_summary[period_col].apply(format_period_ru)

    from dashboards.data_quality_hints import collect_bdr_hints, render_quality_hints

    _bdr_q_hints = collect_bdr_hints(dict(getattr(df_work, "attrs", {}) or {}))

    @st.fragment
    def _bdr_chart():
        view_type = str(st.session_state.get("bdr_period_view", "По месяцам"))
        chart_df = bdr_summary.copy()
        _bdr_cumulative = view_type == "Накопительно"
        _bdr_gran = format_report_granularity_label(
            period_label, cumulative=_bdr_cumulative
        )
        _bdr_date_suffix = format_date_range_title_suffix(_bdr_cal_start, _bdr_cal_end)

        if bdr_tz_mode:
            hide_deviation = bool(st.session_state.get("bdr_hide_deviation_tz", False))
            if view_type == "Накопительно":
                chart_df["План расходов"] = chart_df["План расходов"].cumsum()
                chart_df["Факт расходов"] = chart_df["Факт расходов"].cumsum()
                chart_df["Отклонение"] = chart_df["Факт расходов"] - chart_df["План расходов"]
            else:
                chart_df["Отклонение"] = chart_df["Факт расходов"] - chart_df["План расходов"]

            _bdr_all_projects = str(st.session_state.get("bdr_project", selected_project)).strip() in (
                "",
                "Все",
            )

            def _bdr_drop_empty_months(_cdf: pd.DataFrame) -> pd.DataFrame:
                if _cdf is None or _cdf.empty:
                    return _cdf
                _dp = _cdf["План расходов"].fillna(0.0)
                _dfx = _cdf["Факт расходов"].fillna(0.0)
                _keep = (_dp.abs() + _dfx.abs()) >= _FINANCE_CHART_MIN_MONTH_RUB
                return _cdf.loc[_keep].copy()

            _bdr_hide_zero = bool(
                period_type_en == "Month"
                and view_type == "По месяцам"
                and st.session_state.get("bdr_hide_zero_months_tz", _bdr_all_projects)
            )
            if period_type_en == "Month" and view_type == "По месяцам" and not chart_df.empty:
                chart_df = _bdr_drop_empty_months(chart_df)
            if (
                _bdr_hide_zero
                and period_type_en == "Month"
                and view_type == "По месяцам"
                and not chart_df.empty
            ):
                chart_df = _bdr_drop_empty_months(chart_df)
            if chart_df.empty:
                st.info(
                    "Нет периодов для графика. Снимите фильтр скрытия нулевых периодов "
                    "или расширьте фильтры."
                )
                return

            _nb = len(chart_df)
            _is_cumulative = view_type == "Накопительно"
            # Подписи значений на столбцах — по ТЗ/UX всегда (раньше скрывались при >6 периодов).
            _hide_bar_value_labels = False
            _tlbl_b = 0.005
            _tlbl_dev = 0.01 if not _hide_bar_value_labels else _tlbl_b
            _tfs_b = 10 if _nb > 32 else 11 if _nb > 20 else 12 if _nb > 12 else 13
            if _nb > 32:
                _bgb, _bggb = 0.04, 0.01
            elif _nb > 18:
                _bgb, _bggb = 0.06, 0.02
            else:
                _bgb, _bggb = 0.1, 0.04
            _leg_b_pre = 300
            if _is_cumulative:
                _leg_b_pre = max(340, min(520, 300 + int(_nb * 4.8)))
            elif _nb > 24:
                _leg_b_pre = max(300, min(460, 280 + int(_nb * 3.5)))
            # Больше верхнего поля — чтобы подписи «outside» и высокие столбцы не обрезались при прокрутке/зуме.
            _top_px_pre = (
                168 if _nb <= 12 else (188 if _nb <= 20 else 208)
            ) if not _hide_bar_value_labels else (72 if _nb > 20 else 88)
            _min_plot_core_px = 400
            _bdr_h_base = 600 if _nb <= 20 else int(min(1100, 520 + int(_nb * 1.4)))
            _bdr_h = max(_bdr_h_base, _top_px_pre + _leg_b_pre + _min_plot_core_px)
            _bdr_h = int(min(1400, _bdr_h))
            _xb = -45 if _nb <= 18 else -50 if _nb <= 36 else -55
            _x_standoff = 30 if _nb <= 18 else (44 if _nb <= 36 else 56)
            _txt_pos_b = "none" if _hide_bar_value_labels else "outside"
            # Короткий суффикс чтобы подпись влезла в ширину бара при горизонтальном расположении
            _suf_b = " млн. руб."
            _plan_txt_b = (
                None
                if _hide_bar_value_labels
                else _finance_bar_text_mln_rub(
                    chart_df["План расходов"],
                    min_abs_mln=_tlbl_b,
                    decimals=1,
                    unit_suffix=_suf_b,
                )
            )
            _fact_txt_b = (
                None
                if _hide_bar_value_labels
                else _finance_bar_text_mln_rub(
                    chart_df["Факт расходов"],
                    min_abs_mln=_tlbl_b,
                    decimals=1,
                    unit_suffix=_suf_b,
                )
            )

            fig = go.Figure()
            x_vals = chart_df["Период"]
            fig.add_trace(
                go.Bar(
                    x=x_vals,
                    y=chart_df["План расходов"].div(1e6),
                    name="План расходов",
                    marker_color="#2E86AB",
                    text=_plan_txt_b,
                    textposition=_txt_pos_b,
                    textfont=dict(size=_tfs_b, color=_fin_chart_label_color()),
                    customdata=chart_df["План расходов"].apply(lambda v: format_million_rub(v, decimals=1)),
                    hovertemplate="<b>%{x}</b><br>План расходов: %{customdata}<br><extra></extra>",
                )
            )
            fig.add_trace(
                go.Bar(
                    x=x_vals,
                    y=chart_df["Факт расходов"].div(1e6),
                    name="Факт расходов",
                    marker_color="#A23B72",
                    text=_fact_txt_b,
                    textposition=_txt_pos_b,
                    textfont=dict(size=_tfs_b, color=_fin_chart_label_color()),
                    customdata=chart_df["Факт расходов"].apply(lambda v: format_million_rub(v, decimals=1)),
                    hovertemplate="<b>%{x}</b><br>Факт расходов: %{customdata}<br><extra></extra>",
                )
            )
            if not hide_deviation:
                _dev_thr_b = 0.01
                # БДДС-конвенция: отклонение = факт − план; <0 (факт<план) — красный и ниже нуля, >0 (факт>план) — зелёный и выше нуля.
                _dev_mln_b = chart_df["Отклонение"].div(1e6)
                _y_b_fact_lt = _dev_mln_b.where(_dev_mln_b < -_dev_thr_b)
                _y_b_fact_gt = _dev_mln_b.where(_dev_mln_b > _dev_thr_b)
                _dev_txt_lt = _finance_deviation_bar_text_signed_mln(
                    _y_b_fact_lt,
                    min_abs_mln=_tlbl_dev,
                    decimals=1,
                    unit_suffix=" млн. руб.",
                )
                _dev_txt_gt = _finance_deviation_bar_text_signed_mln(
                    _y_b_fact_gt,
                    min_abs_mln=_tlbl_dev,
                    decimals=1,
                    unit_suffix=" млн. руб.",
                )
                if _y_b_fact_lt.notna().any():
                    fig.add_trace(
                        go.Bar(
                            x=x_vals,
                            y=_y_b_fact_lt,
                            name="Отклонение (факт < план)",
                            marker_color=_FINANCE_DEV_BAR_RED,
                            text=None if _hide_bar_value_labels else _dev_txt_lt,
                            textposition="outside" if not _hide_bar_value_labels else "none",
                            textfont=dict(size=_tfs_b, color=_FINANCE_DEV_LABEL_RED),
                            cliponaxis=False,
                            customdata=_y_b_fact_lt.map(
                                lambda v: format_million_rub(float(v) * 1e6) if pd.notna(v) else ""
                            ),
                            hovertemplate="<b>%{x}</b><br>Отклонение: %{customdata}<br><extra></extra>",
                        )
                    )
                if _y_b_fact_gt.notna().any():
                    fig.add_trace(
                        go.Bar(
                            x=x_vals,
                            y=_y_b_fact_gt,
                            name="Отклонение (факт > план)",
                            marker_color=_FINANCE_DEV_BAR_GREEN,
                            text=None if _hide_bar_value_labels else _dev_txt_gt,
                            textposition="outside" if not _hide_bar_value_labels else "none",
                            textfont=dict(size=_tfs_b, color=_FINANCE_DEV_LABEL_GREEN),
                            cliponaxis=False,
                            customdata=_y_b_fact_gt.map(
                                lambda v: format_million_rub(float(v) * 1e6) if pd.notna(v) else ""
                            ),
                            hovertemplate="<b>%{x}</b><br>Отклонение: %{customdata}<br><extra></extra>",
                        )
                    )

            fig.update_layout(
                title_text="",
                yaxis_title="млн. руб.",
                barmode="group",
                bargap=_bgb,
                bargroupgap=_bggb,
                uniformtext=dict(minsize=1, mode="show"),
                xaxis=dict(
                    title=dict(text=period_label, standoff=_x_standoff),
                    tickangle=_xb,
                    tickfont=dict(size=finance_axis_tick_font_size(_nb)),
                    nticks=min(64, max(12, _nb)),
                ),
            )
            if not chart_df.empty:
                _series_for_range = [
                    chart_df["План расходов"].div(1e6).to_numpy(),
                    chart_df["Факт расходов"].div(1e6).to_numpy(),
                ]
                if not hide_deviation:
                    _series_for_range.append(chart_df["Отклонение"].div(1e6).to_numpy())
                _ymax = float(np.nanmax(np.concatenate(_series_for_range)))
                _ymin = float(np.nanmin(np.concatenate(_series_for_range)))
                if np.isfinite(_ymax) and np.isfinite(_ymin):
                    pad = max(abs(_ymax), abs(_ymin), 1e-6) * 0.28
                    span = float(max(_ymax - _ymin, 1e-6))
                    head = max(span * 0.32, abs(_ymax) * 0.2, 0.75)
                    foot = pad if _ymin >= 0 else max(pad, abs(_ymin) * 0.24)
                    fig.update_layout(yaxis=dict(range=[_ymin - foot, _ymax + pad + head]))
            fig = _apply_finance_bar_label_layout(fig, y_rangemode=None)
            _leg_b = _leg_b_pre
            _leg_y = -0.34 if _nb <= 20 else (-0.38 if _nb <= 36 else -0.44)
            _top_px = _top_px_pre
            try:
                fig.update_xaxes(
                    title=dict(text=period_label, standoff=_x_standoff),
                    automargin=True,
                )
            except Exception:
                pass
            fig = apply_chart_background(fig)
            # px_per_month=400; статичная легенда под скроллом через _render_finance_bar_chart
            _bdr_bar_slots = 4 if not hide_deviation else 2
            _render_finance_bar_chart(
                fig,
                n_periods=_nb,
                height=_bdr_h,
                caption_below=report_chart_caption_body(
                    "БДР план/факт расходов",
                    granularity=_bdr_gran,
                    date_start=_bdr_cal_start,
                    date_end=_bdr_cal_end,
                ),
                categories=chart_df["Период"].astype(str).tolist(),
                px_per_month=400,
                force_hscroll=True,
                n_bar_slots=_bdr_bar_slots,
            )

            _bdr_tbl_name, _bdr_tbl_dates = report_title_parts(
                "БДР",
                period_label,
                cumulative=_bdr_cumulative,
                date_start=_bdr_cal_start,
                date_end=_bdr_cal_end,
            )
            render_table_subheader(st, _bdr_tbl_name, filters_suffix=_bdr_tbl_dates)

            _proj_sel = st.session_state.get("bdr_project", selected_project)
            _bdr_show_all_split = (
                str(_proj_sel).strip() == "Все"
                and "project name" in filtered_df.columns
            )

            if _bdr_show_all_split:
                _parts_bdr: list[pd.DataFrame] = []
                for _pl in _unique_project_labels_for_select(
                    filtered_df["project name"], apply_exclude_names=False
                ):
                    _pk_b = _project_filter_norm_key(_pl)
                    _sub_b = filtered_df[
                        filtered_df["project name"]
                        .map(_project_filter_norm_key)
                        .map(lambda rk: _project_norm_key_matches_msp_keys(rk, {_pk_b}))
                    ].copy()
                    if _sub_b.empty:
                        continue
                    _s = (
                        _sub_b.groupby(period_col, dropna=False)
                        .agg({"_plan_exp": "sum", "_fact_exp": "sum"})
                        .reset_index()
                    )
                    _s = _s.rename(
                        columns={
                            "_plan_exp": "План расходов",
                            "_fact_exp": "Факт расходов",
                        }
                    )
                    if view_type == "Накопительно":
                        _s["План расходов"] = _s["План расходов"].cumsum()
                        _s["Факт расходов"] = _s["Факт расходов"].cumsum()
                    _s["Отклонение"] = _s["Факт расходов"] - _s["План расходов"]
                    if (
                        _bdr_hide_zero
                        and period_type_en == "Month"
                        and view_type == "По месяцам"
                        and not _s.empty
                    ):
                        _dp = _s["План расходов"].fillna(0.0)
                        _dfx = _s["Факт расходов"].fillna(0.0)
                        _s = _s.loc[_dp.abs() + _dfx.abs() >= _FINANCE_CHART_MIN_MONTH_RUB].copy()
                    if _s.empty:
                        continue
                    _s["Период"] = _s[period_col].apply(format_period_ru)
                    _hdr_b = pd.DataFrame(
                        [
                            {
                                "Проект": str(_pl),
                                "Период": "",
                                "План расходов": "",
                                "Факт расходов": "",
                                "Отклонение": "",
                                "__rk": "project",
                            }
                        ]
                    )
                    _body_b = _s[
                        ["Период", "План расходов", "Факт расходов", "Отклонение"]
                    ].copy()
                    # Проект в каждой строке — чтобы при сортировке по другим колонкам название не пропадало.
                    _body_b.insert(0, "Проект", str(_pl))
                    _body_b["__rk"] = ""
                    _parts_bdr.extend([_hdr_b, _body_b])
                tbl_raw = (
                    pd.concat(_parts_bdr, ignore_index=True) if _parts_bdr else pd.DataFrame()
                )
            else:
                _bdr_tz_proj = "Все" if str(_proj_sel).strip() == "Все" else str(_proj_sel).strip()
                tbl_raw = chart_df[
                    ["Период", "План расходов", "Факт расходов", "Отклонение"]
                ].copy()
                # Правки куратора 08.05.2026: Проект — первый, Период — второй.
                tbl_raw.insert(0, "Проект", _bdr_tz_proj)

            if tbl_raw.empty:
                st.info("Нет данных для сводной таблицы по выбранным фильтрам.")
                return

            def _bdr_tz_period_total_disp(_cdf: pd.DataFrame) -> str:
                if _bdr_cal_start is not None and _bdr_cal_end is not None:
                    try:
                        _s = pd.Timestamp(_bdr_cal_start).date()
                        _e = pd.Timestamp(_bdr_cal_end).date()
                        return f"{_s.strftime('%d.%m.%Y')} — {_e.strftime('%d.%m.%Y')}"
                    except Exception:
                        pass
                if not _cdf.empty and period_col in _cdf.columns:
                    try:
                        _po = _cdf[period_col].dropna()
                        if not _po.empty:
                            _p_min, _p_max = _po.min(), _po.max()
                            _fm = format_period_ru(_p_min)
                            _fx = format_period_ru(_p_max)
                            return _fm if _fm == _fx else f"{_fm} — {_fx}"
                    except Exception:
                        pass
                return ""

            _tz_per_total = _bdr_tz_period_total_disp(chart_df)

            if view_type == "Накопительно":
                _lr_tz = chart_df.iloc[-1]
                tot_row_tz = {
                    "Период": _tz_per_total,
                    "Проект": "ИТОГО",
                    "__rk": "total",
                    "План расходов": float(_lr_tz["План расходов"]),
                    "Факт расходов": float(_lr_tz["Факт расходов"]),
                    "Отклонение": float(_lr_tz["Отклонение"]),
                }
            else:
                _sums = chart_df[["План расходов", "Факт расходов"]].sum()
                _tot_plan = float(_sums["План расходов"])
                _tot_fact = float(_sums["Факт расходов"])
                tot_row_tz = {
                    "Период": _tz_per_total,
                    "Проект": "ИТОГО",
                    "__rk": "total",
                    "План расходов": _tot_plan,
                    "Факт расходов": _tot_fact,
                    "Отклонение": _tot_fact - _tot_plan,
                }
            tbl_disp = pd.concat([tbl_raw, pd.DataFrame([tot_row_tz])], ignore_index=True)
            tbl_disp = tbl_disp.rename(columns={"Период": period_label})
            _tz_money_cols = ("План расходов", "Факт расходов", "Отклонение")

            def _fmt_tz_cell(v):
                if v is None or v == "" or (isinstance(v, float) and pd.isna(v)):
                    return ""
                return format_million_rub(v, decimals=1)

            def _fmt_tz_dev_cell(v):
                return _finance_fmt_signed_million_deviation(v)

            for _cn in _tz_money_cols:
                if _cn == "Отклонение":
                    tbl_disp[_cn] = tbl_disp[_cn].map(_fmt_tz_dev_cell)
                else:
                    tbl_disp[_cn] = tbl_disp[_cn].map(_fmt_tz_cell)
            tbl_disp = tbl_disp.rename(
                columns={
                    period_label: "Период",
                    "План расходов": "План, млн. руб.",
                    "Факт расходов": "Факт, млн. руб.",
                    "Отклонение": "Отклонение, млн. руб.",
                }
            )
            _bdr_tz_dev_col = "Отклонение, млн. руб."
            _render_budget_table_html(
                    tbl_disp,
                    row_kind_column="__rk",
                    finance_deviation_column=_bdr_tz_dev_col,
                    deviation_color_fact_vs_plan=True,
                    emphasize_row_kinds=("project", "total"),
                    **_finance_table_html_kwargs(),
                )
            return

        if view_type == "Накопительно":
            chart_df["Доходы"] = chart_df["Доходы"].cumsum()
            chart_df["Расходы"] = chart_df["Расходы"].cumsum()
            chart_df["Сальдо"] = chart_df["Доходы"] - chart_df["Расходы"]

        _bdr_hide_zero = bool(
            period_type_en == "Month"
            and view_type == "По месяцам"
            and st.session_state.get("bdr_hide_zero_months", True)
        )
        if (
            _bdr_hide_zero
            and period_type_en == "Month"
            and view_type == "По месяцам"
            and not chart_df.empty
        ):
            _di = chart_df["Доходы"].fillna(0.0)
            _dx = chart_df["Расходы"].fillna(0.0)
            chart_df = chart_df.loc[_di.abs() + _dx.abs() > 0.5].copy()
        if chart_df.empty:
            st.info(
                "Нет периодов для графика. Снимите «Скрывать месяцы, где доходы и расходы равны 0» "
                "или расширьте фильтры."
            )
            return

        _nb = len(chart_df)
        _is_cumulative = view_type == "Накопительно"
        _hide_bar_value_labels = False
        _tlbl_b = 0.005
        _tlbl_dev = 0.01 if not _hide_bar_value_labels else _tlbl_b
        _tfs_b = 8 if _nb > 32 else 9 if _nb > 20 else 10 if _nb > 12 else 11
        if _nb > 32:
            _bgb, _bggb = 0.04, 0.01
        elif _nb > 18:
            _bgb, _bggb = 0.06, 0.02
        else:
            _bgb, _bggb = 0.1, 0.04
        _leg_b_pre = 300
        if _is_cumulative:
            _leg_b_pre = max(340, min(520, 300 + int(_nb * 4.8)))
        elif _nb > 24:
            _leg_b_pre = max(300, min(460, 280 + int(_nb * 3.5)))
        _top_px_pre = 124 if not _hide_bar_value_labels else (72 if _nb > 20 else 88)
        _min_plot_core_px = 400
        _bdr_h_base = 600 if _nb <= 20 else int(min(1100, 520 + int(_nb * 1.4)))
        _bdr_h = max(_bdr_h_base, _top_px_pre + _leg_b_pre + _min_plot_core_px)
        _bdr_h = int(min(1400, _bdr_h))
        _xb = -45 if _nb <= 18 else -50 if _nb <= 36 else -55
        _x_standoff = 30 if _nb <= 18 else (44 if _nb <= 36 else 56)
        _txt_pos_b = "none" if _hide_bar_value_labels else "outside"
        _plan_txt_b = (
            None
            if _hide_bar_value_labels
            else _finance_bar_text_mln_rub(chart_df["Доходы"], min_abs_mln=_tlbl_b)
        )
        _fact_txt_b = (
            None
            if _hide_bar_value_labels
            else _finance_bar_text_mln_rub(chart_df["Расходы"], min_abs_mln=_tlbl_b)
        )
        _dev_txt_b = (
            None
            if _hide_bar_value_labels
            else _finance_bar_text_mln_rub(chart_df["Сальдо"], min_abs_mln=_tlbl_dev)
        )

        fig = go.Figure()
        x_vals = chart_df["Период"]
        fig.add_trace(
            go.Bar(
                x=x_vals,
                y=chart_df["Доходы"].div(1e6),
                name="Доходы",
                marker_color="#2E86AB",
                text=_plan_txt_b,
                textposition=_txt_pos_b,
                textfont=dict(size=_tfs_b, color=_fin_chart_label_color()),
                customdata=chart_df["Доходы"].apply(format_million_rub),
                hovertemplate="<b>%{x}</b><br>Доходы: %{customdata}<br><extra></extra>",
            )
        )
        fig.add_trace(
            go.Bar(
                x=x_vals,
                y=chart_df["Расходы"].div(1e6),
                name="Расходы",
                marker_color="#A23B72",
                text=_fact_txt_b,
                textposition=_txt_pos_b,
                textfont=dict(size=_tfs_b, color=_fin_chart_label_color()),
                customdata=chart_df["Расходы"].apply(format_million_rub),
                hovertemplate="<b>%{x}</b><br>Расходы: %{customdata}<br><extra></extra>",
            )
        )
        dev_colors = [
            "#e74c3c" if v >= 0 else "#27ae60" for v in chart_df["Сальдо"]
        ]
        fig.add_trace(
            go.Bar(
                x=x_vals,
                y=chart_df["Сальдо"].div(1e6),
                name="Сальдо",
                marker_color=dev_colors,
                text=_dev_txt_b,
                textposition=_txt_pos_b,
                textfont=dict(size=_tfs_b, color=_fin_chart_label_color()),
                customdata=chart_df["Сальдо"].apply(format_million_rub),
                hovertemplate="<b>%{x}</b><br>Сальдо: %{customdata}<br><extra></extra>",
            )
        )
        fig.update_layout(
            title_text="",
            yaxis_title="млн. руб.",
            barmode="group",
            bargap=_bgb,
            bargroupgap=_bggb,
            uniformtext=dict(minsize=7, mode="show"),
            xaxis=dict(
                title=dict(text=period_label, standoff=_x_standoff),
                tickangle=_xb,
                tickfont=dict(size=finance_axis_tick_font_size(_nb)),
                nticks=min(64, max(12, _nb)),
            ),
        )
        if not chart_df.empty:
            _ymax = float(
                np.nanmax(
                    np.concatenate(
                        [
                            chart_df["Доходы"].div(1e6).to_numpy(),
                            chart_df["Расходы"].div(1e6).to_numpy(),
                            chart_df["Сальдо"].div(1e6).to_numpy(),
                        ]
                    )
                )
            )
            _ymin = float(
                np.nanmin(
                    np.concatenate(
                        [
                            chart_df["Доходы"].div(1e6).to_numpy(),
                            chart_df["Расходы"].div(1e6).to_numpy(),
                            chart_df["Сальдо"].div(1e6).to_numpy(),
                        ]
                    )
                )
            )
            if np.isfinite(_ymax) and np.isfinite(_ymin):
                pad = max(abs(_ymax), abs(_ymin), 1e-6) * 0.22
                span = float(max(_ymax - _ymin, 1e-6))
                head = max(span * 0.22, abs(_ymax) * 0.14, 0.55)
                foot = pad if _ymin >= 0 else max(pad, abs(_ymin) * 0.18)
                fig.update_layout(yaxis=dict(range=[_ymin - foot, _ymax + pad + head]))
        fig = _apply_finance_bar_label_layout(fig, y_rangemode=None)
        _leg_b = _leg_b_pre
        _leg_y = -0.34 if _nb <= 20 else (-0.38 if _nb <= 36 else -0.44)
        _top_px = _top_px_pre
        fig = _plotly_legend_horizontal_below_plot(
            fig, bottom_px=_leg_b, legend_y=_leg_y, top_px=_top_px
        )
        try:
            fig.update_xaxes(
                title=dict(text=period_label, standoff=_x_standoff),
                automargin=True,
            )
        except Exception:
            pass
        fig = apply_chart_background(fig)
        try:
            _finance_plotly_apply_bar_width(
                fig,
                _nb,
                chart_df["Период"].astype(str).tolist(),
            )
        except Exception:
            pass
        _apply_finance_light_preview_chart_colors(fig)
        render_chart(
            fig,
            caption_below=report_chart_caption_body(
                "БДР",
                period_label,
                cumulative=_bdr_cumulative,
                date_start=_bdr_cal_start,
                date_end=_bdr_cal_end,
            ),
            height=_bdr_h,
            max_height=None,
        )

        _bdr_tbl_name, _bdr_tbl_dates = report_title_parts(
            "БДР",
            period_label,
            cumulative=_bdr_cumulative,
            date_start=_bdr_cal_start,
            date_end=_bdr_cal_end,
        )
        render_table_subheader(st, _bdr_tbl_name, filters_suffix=_bdr_tbl_dates)
        display_df = chart_df[
            [c for c in ["Период", "Доходы", "Расходы", "Сальдо"] if c in chart_df.columns]
        ].copy()
        display_df = display_df.rename(columns={"Период": period_label})
        for col in ["Доходы", "Расходы", "Сальдо"]:
            if col in display_df.columns:
                display_df[col] = display_df[col].map(format_million_rub)
        display_df = display_df.rename(columns={
            "Доходы": "Доходы, млн. руб.",
            "Расходы": "Расходы, млн. руб.",
            "Сальдо": "Сальдо, млн. руб.",
        })
        _render_budget_table_html(
                display_df,
                finance_deviation_column="Сальдо, млн. руб.",
                deviation_red_if_negative=True,
                **_finance_table_html_kwargs(),
            )

    _bdr_chart()

    if "project name" in filtered_df.columns:
        render_table_subheader(st, "БДР по проектам")
        if bdr_tz_mode:
            by_p = (
                filtered_df.groupby("project name", dropna=False)
                .agg({"_plan_exp": "sum", "_fact_exp": "sum"})
                .reset_index()
            )
            by_p["Отклонение"] = by_p["_fact_exp"] - by_p["_plan_exp"]
            proj_tbl = pd.DataFrame(
                {
                    "Проект": by_p["project name"].astype(str),
                    "План, млн. руб.": by_p["_plan_exp"].map(format_million_rub),
                    "Факт, млн. руб.": by_p["_fact_exp"].map(format_million_rub),
                    "Отклонение, млн. руб.": by_p["Отклонение"].map(
                        _finance_fmt_signed_million_deviation
                    ),
                    "_row_kind": "",
                }
            )
            if not proj_tbl.empty:
                _bdr_plan_tot = float(by_p["_plan_exp"].fillna(0.0).sum())
                _bdr_fact_tot = float(by_p["_fact_exp"].fillna(0.0).sum())
                proj_tbl = pd.concat(
                    [
                        proj_tbl,
                        pd.DataFrame(
                            [
                                {
                                    "Проект": "ИТОГО",
                                    "План, млн. руб.": format_million_rub(_bdr_plan_tot),
                                    "Факт, млн. руб.": format_million_rub(_bdr_fact_tot),
                                    "Отклонение, млн. руб.": _finance_fmt_signed_million_deviation(
                                        _bdr_fact_tot - _bdr_plan_tot
                                    ),
                                    "_row_kind": "total",
                                }
                            ]
                        ),
                    ],
                    ignore_index=True,
                )
            suppress_caption(
                "План/факт расходов и отклонение (факт минус план) по проекту за выбранные фильтры."
            )
            _render_budget_table_html(
                    proj_tbl,
                    finance_deviation_column="Отклонение, млн. руб.",
                    deviation_color_fact_vs_plan=True,
                    row_kind_column="_row_kind",
                    emphasize_row_kinds=("total",),
                    **_finance_table_html_kwargs(),
                )
        else:
            by_p = (
                filtered_df.groupby("project name", dropna=False)
                .agg({"_inc": "sum", "_exp": "sum"})
                .reset_index()
            )
            by_p["Итого (сальдо)"] = by_p["_inc"] - by_p["_exp"]
            proj_tbl = pd.DataFrame(
                {
                    "Проект": by_p["project name"].astype(str),
                    "Доходы, млн. руб.": by_p["_inc"].map(format_million_rub),
                    "Расходы, млн. руб.": by_p["_exp"].map(format_million_rub),
                    "Сальдо, млн. руб.": by_p["Итого (сальдо)"].map(format_million_rub),
                    "_row_kind": "",
                }
            )
            if not proj_tbl.empty:
                _bdr_inc_tot = float(by_p["_inc"].fillna(0.0).sum())
                _bdr_exp_tot = float(by_p["_exp"].fillna(0.0).sum())
                proj_tbl = pd.concat(
                    [
                        proj_tbl,
                        pd.DataFrame(
                            [
                                {
                                    "Проект": "ИТОГО",
                                    "Доходы, млн. руб.": format_million_rub(_bdr_inc_tot),
                                    "Расходы, млн. руб.": format_million_rub(_bdr_exp_tot),
                                    "Сальдо, млн. руб.": format_million_rub(
                                        _bdr_inc_tot - _bdr_exp_tot
                                    ),
                                    "_row_kind": "total",
                                }
                            ]
                        ),
                    ],
                    ignore_index=True,
                )
            suppress_caption(
                "Колонка «Сальдо» — доходы минус расходы по проекту за выбранные фильтры."
            )
            _render_budget_table_html(
                    proj_tbl,
                    finance_deviation_column="Сальдо, млн. руб.",
                    deviation_red_if_negative=True,
                    row_kind_column="_row_kind",
                    emphasize_row_kinds=("total",),
                    **_finance_table_html_kwargs(),
                )

    render_quality_hints(_bdr_q_hints)


# ==================== B-12/13.2 (2026-05-07): RD/PD plan fallback view =====================
# Дашборды «Рабочая/Проектная документация» и «Просрочка выдачи РД/ПД» исторически
# рассчитаны на `sample_project_data_fixed.csv` со столбцами «Количество разделов РД по
# Договору», «На согласовании», «Выдано в производство работ», «Отклонение разделов РД».
# В реальных выгрузках (`web/AI/other_*_rd.csv`, `other_*_pd.csv`) этих колонок нет ни в
# старом 5-колоночном формате (Номер · Шифр · Наименование · Количество разделов по
# Договору · Дата выдачи), ни в новом 10–29-колоночном (ID_проекта · Шифр · Дата выдачи
# по Договору · Прогнозная дата · Статус РД · Загрузка в ЭДО Tessa · Выдан в
# Производство работ подрядчикам …). Этот fallback показывает план выдачи разделов
# и отклонение «Прогноз − План» в днях, чтобы дашборд не зиял пустотой при отсутствии
# MSP-выгрузки с РД/ПД-полями. Параметр source_key переключает источник:
# `rd_plan_data` — для РД, `pd_plan_data` — для ПД.
_RD_PLAN_FOOTER_RE = re.compile(
    r"^(всего|не\s+выдано|не\s+принято|на\s+рассмотрении|принято)\s*:",
    re.IGNORECASE,
)


def _drop_rd_detail_empty_rows(tbl: pd.DataFrame) -> pd.DataFrame:
    """ТЗ п.8: убрать полностью пустые строки в конце/середине детальной таблицы РД."""
    if tbl is None or getattr(tbl, "empty", True):
        return tbl
    keys = [
        c
        for c in (
            "Проект",
            "Шифр",
            "Наименование разделов работ",
            "Наименование раздела",
            "Полный шифр",
            "Наименование",
        )
        if c in tbl.columns
    ]
    if not keys:
        return tbl
    _empty_vals = {"", "—", "-", "nan", "none", "<na>", "nat"}

    def _row_empty(row) -> bool:
        return all(str(row.get(c, "")).strip().casefold() in _empty_vals for c in keys)

    return tbl.loc[~tbl.apply(_row_empty, axis=1)].reset_index(drop=True)


def _rd_plan_csv_pick_columns(df: pd.DataFrame) -> dict[str, str | None]:
    """Колонки other_*_rd.csv после нормализации заголовков."""
    cols = {
        str(c).replace("\r", " ").replace("\n", " ").strip(): c for c in df.columns
    }

    def _pick(names: tuple[str, ...]) -> str | None:
        for n in names:
            if n in cols:
                return cols[n]
        return None

    def _pick_fuzzy(must: tuple[str, ...]) -> str | None:
        lows = tuple(w.casefold() for w in must)
        best, best_len = None, 10**9
        for cl in cols:
            lc = cl.casefold()
            if all(w in lc for w in lows) and len(lc) < best_len:
                best, best_len = cols[cl], len(lc)
        return best

    return {
        "proj": _pick(("project name", "Проект", "ID_проекта")),
        "code": _pick(("Шифр",)) or _pick_fuzzy(("шифр",)),
        "name": _pick(
            (
                "Наименование  работ (разделов работ).",
                "Наименование работ (разделов работ).",
                "Наименование раздела",
                "Наименование",
            )
        )
        or _pick_fuzzy(("наименование", "раздел"))
        or _pick_fuzzy(("наименование",)),
        "plan": _pick(("Дата выдачи разделов по Договору", "Дата выдачи", "plan end"))
        or _pick_fuzzy(("дата", "выдачи", "договор"))
        or _pick_fuzzy(("дата", "выдачи")),
        "forecast": _pick(
            ("Прогнозная дата выдачи разделов", "Прогнозная дата", "actual finish")
        ),
        "status": _pick(("Статус РД", "Статус ПД", "Статус")),
        "full_cipher": _pick(("Шифр полный", "InternalID", "Internal Id")),
        "contract": _pick(("№ Договора", "Договор")),
    }


def _rd_plan_section_key_series(df: pd.DataFrame, pc: dict[str, str | None]) -> pd.Series:
    """Ключ раздела: (проект, полный шифр) или (проект, шифр, наименование)."""
    proj_c = pc.get("proj")
    fc_c = pc.get("full_cipher")
    code_c = pc.get("code")
    name_c = pc.get("name")
    keys: list[tuple] = []
    for _i, row in df.iterrows():
        pk = (
            _project_filter_norm_key(row.get(proj_c, ""))
            if proj_c and proj_c in row.index
            else ""
        )
        if fc_c and fc_c in row.index:
            fc = _rd_csv_cell_str(row.get(fc_c))
            if fc:
                keys.append(("fc", pk, fc.casefold()))
                continue
        cc = _rd_csv_cell_str(row.get(code_c, "")) if code_c and code_c in row.index else ""
        nm = _rd_csv_cell_str(row.get(name_c, "")) if name_c and name_c in row.index else ""
        keys.append(("pn", pk, cc.casefold(), nm.casefold()))
    return pd.Series(keys, index=df.index)


def _rd_plan_dedupe_sections_df(
    df: pd.DataFrame,
    pc: dict[str, str | None],
) -> pd.DataFrame:
    """1 строка = 1 раздел: дубликаты из нескольких other_*_rd.csv схлопываются."""
    if df is None or getattr(df, "empty", True):
        return df
    out = df.copy()
    if "_plan_dt" not in out.columns and pc.get("plan") and pc["plan"] in out.columns:
        out["_plan_dt"] = pd.to_datetime(
            out[pc["plan"]], errors="coerce", dayfirst=True, format="mixed"
        )
    out["_sec_key"] = _rd_plan_section_key_series(out, pc)
    out["_sort_tessa"] = 0
    if "_tessa_production_dt" in out.columns:
        out["_sort_tessa"] = out["_tessa_production_dt"].notna().astype(int)
    if "_plan_dt" not in out.columns:
        out["_plan_dt"] = pd.NaT
    out = out.sort_values(
        ["_plan_dt", "_sort_tessa"],
        ascending=[False, False],
        na_position="last",
    )
    out = out.drop_duplicates("_sec_key", keep="first")
    return out.drop(columns=["_sec_key", "_sort_tessa"], errors="ignore")


def _rd_plan_section_total(selected_projects: list[str] | None = None) -> int:
    secs = _rd_plan_csv_sections_df(selected_projects)
    return int(len(secs)) if not secs.empty else 0


def _rd_plan_detail_filter_by_plan(
    df: pd.DataFrame,
    detail_tbl: pd.DataFrame,
    proj_col: str | None,
    code_col: str | None,
    name_col: str | None,
    full_cipher_col: str | None,
) -> pd.DataFrame:
    """Строки detail (TESSA), соответствующие разделам из df плана."""
    if detail_tbl.empty or df.empty:
        return detail_tbl.iloc[0:0].copy()
    keys_pn: set[tuple[str, str, str]] = set()
    keys_fc: set[tuple[str, str]] = set()
    _rp = (
        df[proj_col].map(_project_filter_norm_key)
        if proj_col and proj_col in df.columns
        else pd.Series("", index=df.index)
    )
    _rc = (
        df[code_col].astype(str).str.strip().str.casefold()
        if code_col and code_col in df.columns
        else pd.Series("", index=df.index)
    )
    _rn = (
        df[name_col].astype(str).str.strip().str.casefold()
        if name_col and name_col in df.columns
        else pd.Series("", index=df.index)
    )
    for pk, cc, nm in zip(_rp.tolist(), _rc.tolist(), _rn.tolist()):
        keys_pn.add((pk, cc, nm))
    if full_cipher_col and full_cipher_col in df.columns:
        _fk = df[full_cipher_col].map(_rd_csv_cell_str).str.casefold()
        for pk, fc in zip(_rp.tolist(), _fk.tolist()):
            if fc:
                keys_fc.add((pk, fc))
    _dpk = detail_tbl["Проект"].map(_project_filter_norm_key)
    _dcc = detail_tbl["Шифр"].astype(str).str.strip().str.casefold()
    _dnm = detail_tbl["Наименование разделов работ"].astype(str).str.strip().str.casefold()
    _mk = pd.Series(list(zip(_dpk.tolist(), _dcc.tolist(), _dnm.tolist())), index=detail_tbl.index)
    _m = _mk.isin(keys_pn)
    if "Шифр полный" in detail_tbl.columns and keys_fc:
        _dfc = detail_tbl["Шифр полный"].map(_rd_csv_cell_str).str.casefold()
        _mk_fc = pd.Series(list(zip(_dpk.tolist(), _dfc.tolist())), index=detail_tbl.index)
        _m = _m | _mk_fc.isin(keys_fc)
    return detail_tbl[_m.fillna(False)].copy()


def _rd_plan_df_filter_by_detail(
    df: pd.DataFrame,
    detail_tbl: pd.DataFrame,
    proj_col: str | None,
    code_col: str | None,
    name_col: str | None,
    full_cipher_col: str | None,
) -> pd.DataFrame:
    """Строки плана df, для которых есть строка в detail (после фильтра статуса)."""
    if detail_tbl.empty or df.empty:
        return df.iloc[0:0].copy()
    keys_pn: set[tuple[str, str, str]] = set()
    keys_fc: set[tuple[str, str]] = set()
    for _, r in detail_tbl.iterrows():
        pk = _project_filter_norm_key(r.get("Проект", ""))
        cc = str(r.get("Шифр", "") or "").strip().casefold()
        nm = str(r.get("Наименование разделов работ", "") or "").strip().casefold()
        keys_pn.add((pk, cc, nm))
        fc = str(r.get("Шифр полный", "") or "").strip().casefold()
        if fc and fc not in ("nan", "none"):
            keys_fc.add((pk, fc))
    _rp = (
        df[proj_col].map(_project_filter_norm_key)
        if proj_col and proj_col in df.columns
        else pd.Series("", index=df.index)
    )
    _rc = (
        df[code_col].astype(str).str.strip().str.casefold()
        if code_col and code_col in df.columns
        else pd.Series("", index=df.index)
    )
    _rn = (
        df[name_col].astype(str).str.strip().str.casefold()
        if name_col and name_col in df.columns
        else pd.Series("", index=df.index)
    )
    _mk = pd.Series(list(zip(_rp.tolist(), _rc.tolist(), _rn.tolist())), index=df.index)
    _m = _mk.isin(keys_pn)
    if full_cipher_col and full_cipher_col in df.columns and keys_fc:
        _fk = df[full_cipher_col].map(_rd_csv_cell_str).str.casefold()
        _mk_fc = pd.Series(list(zip(_rp.tolist(), _fk.tolist())), index=df.index)
        _m = _m | _mk_fc.isin(keys_fc)
    return df[_m.fillna(False)].copy()


def _rd_plan_df_align_to_detail(
    df: pd.DataFrame,
    detail_tbl: pd.DataFrame,
    proj_col: str | None,
    code_col: str | None,
    name_col: str | None,
    full_cipher_col: str | None,
) -> pd.DataFrame:
    """Обратная совместимость: фильтр detail по плану."""
    return _rd_plan_detail_filter_by_plan(
        df, detail_tbl, proj_col, code_col, name_col, full_cipher_col
    )


def _rd_plan_coalesce_case_variant_columns(df: pd.DataFrame) -> pd.DataFrame:
    """Сливает построчно колонки-варианты, различающиеся только регистром/пробелами.

    Разные форматы снапшотов other_*_rd.csv используют разные заголовки:
    «шифр»/«Шифр», «номер шифра»/«Номер шифра», «блок»/«Блок», «Дата выдачи
    разделов по договору»/«… по Договору». В каждой строке заполнен только один
    вариант, поэтому `_rd_plan_csv_pick_columns` выбирает один заголовок и для
    части проектов он пуст (например «Дмитровский-1»: заполнена «шифр», а
    выбирается пустая «Шифр» → «Нет строк после фильтра»). Объединяем варианты в
    самую заполненную колонку, заполняя её пустые значения из остальных.
    """
    if df is None or getattr(df, "empty", True):
        return df
    _groups: dict[str, list[str]] = {}
    for _c in df.columns:
        _groups.setdefault(str(_c).strip().casefold(), []).append(_c)
    _dups = {k: v for k, v in _groups.items() if len(v) > 1}
    if not _dups:
        return df
    out = df.copy()
    _drop: list[str] = []
    for _cols in _dups.values():
        _cols_sorted = sorted(
            _cols, key=lambda c: int(out[c].notna().sum()), reverse=True
        )
        _canon = _cols_sorted[0]
        _base = out[_canon]
        if isinstance(_base, pd.DataFrame):
            _base = _base.iloc[:, 0]
        _base = _base.copy()
        for _other in _cols_sorted[1:]:
            _oser = out[_other]
            if isinstance(_oser, pd.DataFrame):
                _oser = _oser.iloc[:, 0]
            _empty = _base.isna() | _base.astype(str).str.strip().isin(
                ["", "nan", "none", "None", "<NA>", "NaT"]
            )
            _base = _base.where(~_empty, _oser)
            _drop.append(_other)
        out[_canon] = _base
    if _drop:
        out = out.drop(columns=_drop)
    return out


def _rd_plan_keep_most_filled_dupe_columns(df: pd.DataFrame) -> pd.DataFrame:
    """Из одноимённых колонок (после нормализации пробелов) оставляет самую заполненную.

    Иначе «Дата выдачи … по  Договору» (двойной пробел, мало строк) затирает
    одноимённую полную колонку, и «План на текущую дату» сильно занижается.
    Дополнительно сливает построчно варианты, различающиеся только регистром
    («шифр»/«Шифр»), т.к. разные форматы снапшотов заполняют разные заголовки.
    """
    if df.columns.duplicated().any():
        _seen_best: dict[str, tuple[int, int]] = {}
        for _pos, _name in enumerate(df.columns):
            _nn = int(df.iloc[:, _pos].notna().sum())
            _prev = _seen_best.get(_name)
            if _prev is None or _nn > _prev[1]:
                _seen_best[_name] = (_pos, _nn)
        _keep = sorted(p for p, _ in _seen_best.values())
        df = df.iloc[:, _keep].copy()
    return _rd_plan_coalesce_case_variant_columns(df)


def _rd_plan_keep_latest_snapshot(
    df: pd.DataFrame, proj_col: str | None = None
) -> pd.DataFrame:
    """Оставляет только последнюю выгрузку (по snapshot_date) на проект.

    other_*_rd.csv / other_*_pd.csv накапливаются по снапшотам в
    rd_plan_data / pd_plan_data (concat в web_loader). Без этого счётчик
    «Всего разделов» = ОБЪЕДИНЕНИЕ разделов всех выгрузок проекта, а не
    текущий план (например по «Ленинскому» — 241 вместо 198).
    Строки без snapshot_date оставляем как есть.
    """
    if df is None or getattr(df, "empty", True):
        return df
    if "snapshot_date" not in df.columns:
        return df
    out = df
    _snap_col = out["snapshot_date"]
    if isinstance(_snap_col, pd.DataFrame):
        _snap_col = _snap_col.iloc[:, 0]
    _snap = pd.to_datetime(_snap_col, errors="coerce")
    if not _snap.notna().any():
        return out
    _pcol = proj_col if (proj_col and proj_col in out.columns) else None
    if _pcol is None:
        for _cand in ("project name", "Проект", "ID_проекта"):
            if _cand in out.columns:
                _pcol = _cand
                break
    if _pcol:
        _pser = out[_pcol]
        if isinstance(_pser, pd.DataFrame):
            _pser = _pser.iloc[:, 0]
        _grp = _pser.map(_project_filter_norm_key)
    else:
        _grp = pd.Series("", index=out.index)
    _tmp = pd.DataFrame({"_snap_dt": _snap.to_numpy(), "_grp": _grp.to_numpy()}, index=out.index)
    _latest = _tmp.groupby("_grp")["_snap_dt"].transform("max")
    # оставляем строки без даты снапшота ИЛИ с максимальной датой в своём проекте
    _keep = _tmp["_snap_dt"].isna() | (_tmp["_snap_dt"] == _latest)
    return out[_keep.to_numpy()].copy()


def _rd_plan_cancelled_row_mask(df: pd.DataFrame) -> pd.Series:
    """RD-01: маска отменённых разделов по ЛЮБОЙ колонке со «статус» в имени.

    В other_*_rd.csv статус лежит то в «Статус», то в «Статус РД» (разные
    снапшоты), а `_rd_plan_csv_pick_columns` выбирает лишь одну колонку —
    «отменено» из другой иначе не отсекается (Дмитровский-1: 6 отменённых в
    «Статус», тогда как pick берёт «Статус РД»).
    """
    if df is None or getattr(df, "empty", True):
        return pd.Series(False, index=getattr(df, "index", pd.RangeIndex(0)))
    mask = pd.Series(False, index=df.index)
    for c in df.columns:
        if "статус" not in str(c).casefold():
            continue
        col = df[c]
        if isinstance(col, pd.DataFrame):
            col = col.iloc[:, 0]
        s = col.map(_rd_csv_cell_str).str.casefold()
        mask = mask | s.str.contains("отмен", na=False) | s.isin({"cancelled", "canceled"})
    return mask


def _rd_plan_csv_sections_df(
    selected_projects: list[str] | None = None,
) -> pd.DataFrame:
    """Строки плана РД из rd_plan_data: 1 строка = 1 раздел, без итогов CSV."""
    try:
        rd = st.session_state.get("rd_plan_data")
    except Exception:
        rd = None
    if rd is None or getattr(rd, "empty", True):
        return pd.DataFrame()
    df = rd.copy()
    df.columns = [
        re.sub(r"\s+", " ", str(c).replace("\r", " ").replace("\n", " ").replace("\u00a0", " "))
        .strip()
        for c in df.columns
    ]
    df = _rd_plan_keep_most_filled_dupe_columns(df)
    pc = _rd_plan_csv_pick_columns(df)
    if not pc.get("plan"):
        return pd.DataFrame()
    df = _rd_plan_keep_latest_snapshot(df, pc.get("proj"))
    if selected_projects and pc.get("proj") and pc["proj"] in df.columns:
        _pk = {_project_filter_norm_key(p) for p in selected_projects}
        df = df[df[pc["proj"]].map(_project_filter_norm_key).isin(_pk)].copy()
    df = _rd_plan_drop_footer_rows(
        df,
        code_col=pc.get("code"),
        name_col=pc.get("name"),
        status_col=pc.get("status"),
    )
    if df.empty:
        return df
    if pc.get("code") and pc["code"] in df.columns:
        _cd = df[pc["code"]].fillna("").astype(str).str.strip()
        df = df[
            _cd.ne("")
            & ~_cd.str.lower().isin({"nan", "none", "-", "—", "блок"})
        ].copy()
    if df.empty:
        return df
    # RD-01: отменённые разделы не входят в план (напр. «Дмитровский-1» — 6
    # строк со статусом «отменено»; без этого «Всего разделов» завышается).
    # Исключаем ТОЛЬКО отмену — «принят»/«не принят»/«на рассмотрении» и т.п.
    # остаются в плане. Проверяем ВСЕ колонки со «статус» (отмена бывает в
    # «Статус», хотя pick выбрал «Статус РД»).
    _canc = _rd_plan_cancelled_row_mask(df)
    if bool(_canc.any()):
        df = df[~_canc].copy()
    if df.empty:
        return df
    df["_plan_dt"] = pd.to_datetime(
        df[pc["plan"]], errors="coerce", dayfirst=True, format="mixed"
    )
    df["_rd_plan_n"] = 1.0
    if pc.get("forecast") and pc["forecast"] in df.columns:
        df["_fact_dt"] = pd.to_datetime(
            df[pc["forecast"]], errors="coerce", dayfirst=True, format="mixed"
        )
    else:
        df["_fact_dt"] = pd.NaT
    if pc.get("name") and pc["name"] in df.columns:
        df[pc["name"]] = df[pc["name"]].map(_rd_plan_unglue_section_name)
    return _rd_plan_dedupe_sections_df(df, pc)


def _rd_plan_db_contract_lookup(
    selected_projects: list[str] | None = None,
) -> dict[str, dict]:
    """Даты «по Договору»/«Прогнозная» из БД rd_plan_data — fallback к файловому
    lookup `other_*_rd.csv`.

    Файловый `_r23_12_load_rd_plan_lookup()` читает CSV с диска и не срабатывает,
    когда у файла нестандартная шапка (строки с названием объекта до заголовков —
    например ранняя выгрузка «Ленинского»), из-за чего в детальной таблице РД
    пропадают договорные даты и не строится график просрочки. Берём те же даты
    из БД (активная версия), ключи — (проект, Шифр полный) и (проект, Шифр,
    Наименование).
    """
    out = {"fc": {}, "pcn": {}}
    try:
        secs = _rd_plan_csv_sections_df(selected_projects)
    except Exception:
        secs = pd.DataFrame()
    if secs is None or getattr(secs, "empty", True):
        return out
    pc = _rd_plan_csv_pick_columns(secs)
    proj_c = pc.get("proj")
    code_c = pc.get("code")
    name_c = pc.get("name")
    fc_c = pc.get("full_cipher")
    for _i, row in secs.iterrows():
        contract = _rd_format_chart_date_cell(
            row["_plan_dt"] if "_plan_dt" in secs.columns and pd.notna(row.get("_plan_dt")) else ""
        )
        forecast = _rd_format_chart_date_cell(
            row["_fact_dt"] if "_fact_dt" in secs.columns and pd.notna(row.get("_fact_dt")) else ""
        )
        if not contract and not forecast:
            continue
        _entry: dict[str, str] = {}
        if contract:
            _entry["contract"] = contract
        if forecast:
            _entry["forecast"] = forecast
        pk = _project_filter_norm_key(row.get(proj_c, "")) if proj_c else ""
        _fcv = _rd_csv_cell_str(row.get(fc_c, "")).casefold() if fc_c else ""
        if _fcv:
            out["fc"].setdefault((pk, _fcv), _entry)
        _cc = _rd_csv_cell_str(row.get(code_c, "")).casefold() if code_c else ""
        _nn = _rd_csv_cell_str(row.get(name_c, "")).casefold() if name_c else ""
        if _cc:
            out["pcn"].setdefault((pk, _cc, _nn), _entry)
    return out


def _rd_plan_tessa_internal_ids(selected_projects: list[str] | None = None) -> set[str]:
    """InternalID карточек TESSA с заполненным шифром (для «Не выдан»)."""
    ids: set[str] = set()
    try:
        trd = st.session_state.get("tessa_data")
    except Exception:
        return ids
    if trd is None or getattr(trd, "empty", True):
        return ids
    t = trd.copy()
    t.columns = [str(c).strip() for c in t.columns]
    tp = _tessa_find_column(t, ["ObjectProjectName", "ProjectName", "ObjectName"])
    ti = _tessa_find_column(t, ["InternalID", "InternalId", "Internal Id"])
    tk = _tessa_find_column(t, ["DivisionCipher", "Cipher"])
    if not ti or not tk or ti not in t.columns or tk not in t.columns:
        return ids
    if selected_projects and tp and tp in t.columns:
        _pk_set = {_project_filter_norm_key(p) for p in selected_projects}
        _pk_set.discard("")
        t = t[
            t[tp]
            .map(_project_filter_norm_key)
            .map(lambda rk: _project_norm_key_matches_msp_keys(rk, _pk_set))
        ]
    if t.empty or tk not in t.columns:
        return ids
    t = t[t[tk].map(_tessa_cell_has_value).fillna(False)]
    if t.empty or ti not in t.columns:
        return ids
    for _v in t[ti].tolist():
        s = str(_v or "").strip()
        if s and s.lower() not in ("nan", "none", "<na>", "nat"):
            ids.add(s.casefold())
    return ids


def _rd_csv_cell_str(val: Any) -> str:
    if val is None:
        return ""
    try:
        if pd.isna(val):
            return ""
    except (TypeError, ValueError):
        pass
    s = str(val).strip()
    if s.lower() in ("nan", "none", "<na>", "nat"):
        return ""
    return s


def _rd_format_contract_no(val: Any) -> str:
    """RD-06: номер договора целым числом — без хвоста «.0» и научной нотации.

    Числовые номера из 1С/DK приходят float («12345.0», «1.2345e+04»);
    приводим к int-строке. Нечисловые номера («Д-123/45») оставляем как есть.
    """
    s = _rd_csv_cell_str(val)
    if not s:
        return ""
    _num = s.replace("\u00a0", "").replace(" ", "").replace(",", ".")
    try:
        f = float(_num)
    except (TypeError, ValueError):
        return s
    if f.is_integer():
        return str(int(f))
    return s


# other_*_rd.csv / other_*_pd.csv иногда склеивают уровни иерархии без разделителя:
# «Конструкции железобетонныеПлиты перекрытий», «…+4.500Покрытие…».
_RD_PLAN_GLUED_NAME_RE = re.compile(
    r"(?<=[а-яёa-z])(?=[А-ЯЁA-Z])|(?<=[0-9])(?=[А-ЯЁA-Z])"
)


def _rd_plan_unglue_section_name(val: Any) -> str:
    """Вставляет пробел на границе слитного «camelCase» в наименовании раздела."""
    s = _rd_csv_cell_str(val)
    if not s or not _RD_PLAN_GLUED_NAME_RE.search(s):
        return s
    return re.sub(r"\s+", " ", _RD_PLAN_GLUED_NAME_RE.sub(" ", s)).strip()


def _rd_plan_row_is_not_issued_csv_status(raw: Any) -> bool:
    s = _rd_csv_cell_str(raw).casefold()
    return s in ("не выдан", "не выдано") or s.startswith("не выдан")


def _rd_dynamics_plan_increment_series(
    sub: pd.DataFrame,
    value_col: str,
    date_col: str,
) -> pd.Series:
    """Прирост плана по строкам: 1 раздел/строка, если колонка не накопительная."""
    vals = pd.to_numeric(
        sub[value_col]
        .astype(str)
        .str.replace(" ", "", regex=False)
        .str.replace(",", ".", regex=False),
        errors="coerce",
    ).fillna(0.0)
    n = len(sub)
    if n == 0:
        return vals
    ordered = sub.assign(_v=vals).sort_values(date_col)
    v_ord = ordered["_v"]
    vmax = float(v_ord.max()) if v_ord.notna().any() else 0.0
    if vmax > max(n * 1.15, 3.0):
        prev = 0.0
        inc: list[float] = []
        for x in v_ord.tolist():
            xf = float(x) if pd.notna(x) else 0.0
            inc.append(max(xf - prev, 0.0))
            prev = max(prev, xf)
        return pd.Series(inc, index=ordered.index).reindex(sub.index).fillna(0.0)
    out = vals.where(vals > 0, 1.0)
    return out


def _pd_monthly_dedupe_by_cipher(
    month_df: pd.DataFrame,
    *,
    cipher_col: str | None,
    project_col: str | None = None,
) -> pd.DataFrame:
    """Один раздел на шифр (и проект): в MSP Ленинского одни и те же разделы
    дублируются со старым и новым БО → иначе 17+17 на графике при 17 уникальных.

    Берём строку с максимальной датой плана; просрочка/факт — OR по группе.
    """
    if month_df is None or getattr(month_df, "empty", True):
        return month_df
    if not cipher_col or cipher_col not in month_df.columns:
        return month_df
    out = month_df.copy()
    _ck = out[cipher_col].fillna("").astype(str).str.strip()
    _ck = _ck.mask(_ck.str.lower().isin({"", "nan", "none", "<na>"}), "")
    if project_col and project_col in out.columns:
        _pk = out[project_col].fillna("").astype(str).str.strip()
        out["_pd_dedupe_key"] = _pk + "||" + _ck
    else:
        out["_pd_dedupe_key"] = _ck
    # Строки без шифра не схлопываем между собой.
    _empty = out["_pd_dedupe_key"].isin({"", "||"})
    keep_empty = out.loc[_empty].copy()
    has_key = out.loc[~_empty].copy()
    if has_key.empty:
        return month_df.drop(columns=["_pd_dedupe_key"], errors="ignore")

    rows: list[pd.Series] = []
    for _, g in has_key.groupby("_pd_dedupe_key", sort=False):
        _ord = g["_plan_end_dt"]
        i = _ord.idxmax() if _ord.notna().any() else g.index[0]
        row = g.loc[i].copy()
        if "_pd_row_overdue" in g.columns:
            row["_pd_row_overdue"] = int(
                pd.to_numeric(g["_pd_row_overdue"], errors="coerce").fillna(0).gt(0).any()
            )
        if "_rd_fact_n" in g.columns:
            row["_rd_fact_n"] = float(
                pd.to_numeric(g["_rd_fact_n"], errors="coerce").fillna(0).max()
            )
        if "_pd_row_fact" in g.columns:
            row["_pd_row_fact"] = int(
                pd.to_numeric(g["_pd_row_fact"], errors="coerce").fillna(0).gt(0).any()
            )
        # Пересчёт после OR: иначе «факт вовремя» остаётся от строки с max БО
        # (часто 0), а в график уходит сырой факт → зелёные 18 + красные 17.
        if "_pd_row_fact" in row.index and "_pd_row_overdue" in row.index:
            row["_pd_row_fact_ontime"] = int(
                int(row["_pd_row_fact"]) > 0 and int(row["_pd_row_overdue"]) <= 0
            )
        rows.append(row)
    deduped = pd.DataFrame(rows)
    merged = pd.concat([deduped, keep_empty], ignore_index=True)
    out_m = merged.drop(columns=["_pd_dedupe_key"], errors="ignore")
    if (
        not out_m.empty
        and "_pd_row_fact" in out_m.columns
        and "_pd_row_overdue" in out_m.columns
    ):
        out_m["_pd_row_fact_ontime"] = (
            (pd.to_numeric(out_m["_pd_row_fact"], errors="coerce").fillna(0) > 0)
            & (pd.to_numeric(out_m["_pd_row_overdue"], errors="coerce").fillna(0) <= 0)
        ).astype(int)
    return out_m


def _rd_monthly_sections_aggregate(
    month_df: pd.DataFrame,
    *,
    overdue_col: str | None = None,
) -> pd.DataFrame:
    """Агрегат по месяцам плановой даты: plan / done / overdue.

    ``overdue_col`` — явная просрочка по строке (ПД: Finish > БО). Тогда
    «Выполнено» только у непросроченных с фактом; просроченные всегда в
    красном сегменте (в т.ч. «сданные с опозданием»), как на карточке KPI.
    Без колонки — прежняя логика РД: overdue = план − факт при прошедшей дате.
    """
    if month_df is None or getattr(month_df, "empty", True):
        return pd.DataFrame()
    today_ts = pd.Timestamp(date.today())
    mdf = month_df.copy()
    mdf["_month"] = mdf["_plan_end_dt"].dt.to_period("M")
    if overdue_col and overdue_col in mdf.columns:
        _ov = pd.to_numeric(mdf[overdue_col], errors="coerce").fillna(0.0).gt(0)
        _fact = pd.to_numeric(mdf["_rd_fact_n"], errors="coerce").fillna(0.0)
        _plan = pd.to_numeric(mdf["_rd_plan_n"], errors="coerce").fillna(0.0)
        mdf["_overdue_n"] = np.where(_ov, _plan, 0.0)
        mdf["_done_n"] = np.where(~_ov & (_fact > 0), np.minimum(_plan, _fact), 0.0)
    else:
        mdf["_done_n"] = np.where(
            mdf["_rd_fact_n"] > 0,
            np.minimum(mdf["_rd_plan_n"], mdf["_rd_fact_n"]),
            0.0,
        )
        mdf["_overdue_n"] = np.where(
            (mdf["_rd_plan_n"] > mdf["_done_n"]) & (mdf["_plan_end_dt"] < today_ts),
            mdf["_rd_plan_n"] - mdf["_done_n"],
            0.0,
        )
    monthly = (
        mdf.groupby("_month", as_index=False)
        .agg(
            plan=("_rd_plan_n", "sum"),
            done=("_done_n", "sum"),
            overdue=("_overdue_n", "sum"),
        )
        .sort_values("_month")
    )
    return monthly[monthly["plan"] > 0].copy()


def _rd_monthly_to_cumulative(monthly: pd.DataFrame) -> pd.DataFrame:
    """Помесячный агрегат → накопительные plan/fact и прирост факта за месяц."""
    if monthly is None or getattr(monthly, "empty", True):
        return pd.DataFrame()
    out = monthly.sort_values("_month", ascending=True).copy()
    plan_n = pd.to_numeric(out["plan"], errors="coerce").fillna(0.0).clip(lower=0.0)
    done_n = pd.to_numeric(out["done"], errors="coerce").fillna(0.0).clip(lower=0.0)
    # Факт за месяц: выполнено + просрочено (сдано с опозданием тоже «выдано»).
    if "overdue" in out.columns:
        ovd_n = pd.to_numeric(out["overdue"], errors="coerce").fillna(0.0).clip(lower=0.0)
        fact_inc = (done_n + ovd_n).clip(lower=0.0)
    else:
        fact_inc = done_n
    out["plan"] = plan_n.cumsum()
    out["done"] = fact_inc.cumsum()
    out["fact_inc"] = fact_inc
    out["overdue"] = 0.0
    return out


def _render_rd_monthly_overlay_chart(
    monthly: pd.DataFrame,
    *,
    metric_mode: str,
    orientation: str = "v",
    subheader: str | None = None,
    chart_key: str | None = None,
    caption_parts: tuple[str, str] | None = None,
    cumulative: bool = False,
) -> None:
    """
    «Динамика по месяцам».

    ``cumulative=False`` — стек внутри плана месяца:
      • зелёный — выполнено вовремя;
      • жёлтый — остаток плана;
      • красный — просрочено.

    ``cumulative=True`` — накопительно на дату месяца (overlay):
      • жёлтый — план накопительно;
      • зелёный — факт накопительно;
      • справа «+N» — прирост факта за этот месяц.
    Порядок месяцев (гориз.): последний сверху (h-bar: первая категория = сверху).
    """
    if monthly is None or getattr(monthly, "empty", True):
        return
    monthly = monthly.copy()
    if cumulative and not str(metric_mode).strip().startswith("%"):
        monthly = _rd_monthly_to_cumulative(monthly)
        if monthly.empty:
            return
    monthly["Месяц"] = monthly["_month"].apply(
        lambda p: f"{RUSSIAN_MONTHS.get(p.month, str(p.month))} {p.year}"
    )
    use_pct = str(metric_mode).strip().startswith("%")
    plan_n = pd.to_numeric(monthly["plan"], errors="coerce").fillna(0.0).clip(lower=0.0)
    done_n = pd.to_numeric(monthly["done"], errors="coerce").fillna(0.0).clip(lower=0.0)
    overdue_n = pd.to_numeric(monthly.get("overdue", 0.0), errors="coerce").fillna(0.0).clip(lower=0.0)

    def _lbl(v: float, pct: bool) -> str:
        if pd.isna(v) or float(v) <= 0:
            return ""
        return f"{float(v):.0f}%" if pct else f"{int(round(float(v)))}"

    def _inc_lbl(v: float) -> str:
        if pd.isna(v) or float(v) <= 0:
            return ""
        return f"+{int(round(float(v)))}"

    if subheader:
        st.subheader(subheader)

    is_h = orientation == "h"
    # Хронология по возрастанию; для h — numeric Y (0 снизу = ранний, n-1 сверху = последний).
    plot_df = monthly.sort_values("_month", ascending=True).reset_index(drop=True)
    cat = plot_df["Месяц"].tolist()

    fig = go.Figure()
    _ax = _fin_chart_axis_color()
    _lbl_out = _fin_chart_label_color(dark="#e8eef5", light="#111827")
    _use_numeric_y = False

    if cumulative and not use_pct:
        plot_df = plot_df.copy()
        plot_df["plan_v"] = pd.to_numeric(plot_df["plan"], errors="coerce").fillna(0.0)
        plot_df["done_v"] = pd.to_numeric(plot_df["done"], errors="coerce").fillna(0.0)
        plot_df["fact_inc_v"] = pd.to_numeric(
            plot_df.get("fact_inc", 0.0), errors="coerce"
        ).fillna(0.0)
        _x_max = float(
            max(
                float(plot_df["plan_v"].max() if len(plot_df) else 0.0),
                float(plot_df["done_v"].max() if len(plot_df) else 0.0),
                1.0,
            )
        )
        x_title = "Количество разделов (накопительно)"
        _inc_txt = [_inc_lbl(v) for v in plot_df["fact_inc_v"]]
        # «+N» — только прирост за месяц (не накопленный итог).
        _plan_longer = (plot_df["plan_v"] >= plot_df["done_v"]).tolist()
        _plan_inc = [t if longer else "" for t, longer in zip(_inc_txt, _plan_longer)]
        _fact_inc = [t if not longer else "" for t, longer in zip(_inc_txt, _plan_longer)]
        _month_hover = plot_df["Месяц"].tolist()
        _plan_kw = dict(
            name="План",
            marker_color="#F39C12",
            opacity=0.92,
            text=_plan_inc,
            texttemplate="%{text}",
            textposition="outside",
            textfont=dict(size=15, color=_lbl_out),
            cliponaxis=False,
            constraintext="none",
            customdata=_month_hover,
            hovertemplate=(
                "<b>%{customdata}</b><br>План (накопительно): %{x}<extra></extra>"
                if is_h
                else "<b>%{x}</b><br>План (накопительно): %{y}<extra></extra>"
            ),
        )
        _fact_kw = dict(
            name="Факт",
            marker_color="#27AE60",
            opacity=0.95,
            text=_fact_inc,
            texttemplate="%{text}",
            textposition="outside",
            textfont=dict(size=15, color=_lbl_out),
            cliponaxis=False,
            constraintext="none",
            customdata=_month_hover,
            hovertemplate=(
                "<b>%{customdata}</b><br>Факт (накопительно): %{x}<extra></extra>"
                if is_h
                else "<b>%{x}</b><br>Факт (накопительно): %{y}<extra></extra>"
            ),
        )
        if is_h:
            _use_numeric_y = True
            # plot_df по возрастанию: y=0 ранний (низ), y=n-1 последний (верх).
            cat = plot_df["Месяц"].tolist()
            y_idx = list(range(len(plot_df)))
            fig.add_trace(
                go.Bar(y=y_idx, x=plot_df["plan_v"], orientation="h", **_plan_kw)
            )
            fig.add_trace(
                go.Bar(y=y_idx, x=plot_df["done_v"], orientation="h", **_fact_kw)
            )
            fig.update_layout(xaxis_title=x_title, yaxis_title="Месяц")
        else:
            fig.add_trace(go.Bar(x=cat, y=plot_df["plan_v"], **_plan_kw))
            fig.add_trace(go.Bar(x=cat, y=plot_df["done_v"], **_fact_kw))
            fig.update_layout(xaxis_title="Месяц", yaxis_title=x_title)
        _n_leg = 2
        _barmode = "overlay"
        _margin_r = 80 if is_h else 36
    else:
        # Доли не больше плана; остаток плана = plan − done − overdue.
        overdue_n = np.minimum(overdue_n, plan_n)
        done_n = np.minimum(done_n, (plan_n - overdue_n).clip(lower=0.0))
        rest_n = (plan_n - done_n - overdue_n).clip(lower=0.0)
        if use_pct:
            monthly["done_v"] = np.where(plan_n > 0, (done_n / plan_n * 100).round(1), 0.0)
            monthly["rest_v"] = np.where(plan_n > 0, (rest_n / plan_n * 100).round(1), 0.0)
            monthly["overdue_v"] = np.where(
                plan_n > 0, (overdue_n / plan_n * 100).round(1), 0.0
            )
            x_title = "% РД (по месяцу плановой даты)"
        else:
            monthly["done_v"] = done_n.round(1)
            monthly["rest_v"] = rest_n.round(1)
            monthly["overdue_v"] = overdue_n.round(1)
            x_title = "Количество разделов"
        monthly["plan_v"] = plan_n.round(1)
        plot_df = monthly.sort_values("_month", ascending=True).reset_index(drop=True)
        cat = plot_df["Месяц"].tolist()
        _x_max = float(
            pd.to_numeric(plot_df["plan_v"], errors="coerce").fillna(0.0).max()
            if len(plot_df)
            else 1.0
        )
        _x_max = max(_x_max, 1.0)

        _bar_text_common = dict(
            textposition="auto",
            textangle=0,
            constraintext="none",
            cliponaxis=False,
        )
        _done_kw = dict(
            name="Выполнено",
            marker_color="#27AE60",
            text=[_lbl(v, use_pct) for v in plot_df["done_v"]],
            insidetextfont=dict(size=18, color="white"),
            outsidetextfont=dict(size=18, color="#1a1a1a"),
            customdata=cat,
            hovertemplate="<b>%{customdata}</b><br>Выполнено: %{x}<extra></extra>"
            if is_h
            else "<b>%{x}</b><br>Выполнено: %{y}<extra></extra>",
            **_bar_text_common,
        )
        _plan_kw = dict(
            name="План (остаток)",
            marker_color="#F39C12",
            text=[_lbl(v, use_pct) for v in plot_df["rest_v"]],
            customdata=list(zip(cat, plot_df["plan_v"].tolist())),
            insidetextfont=dict(size=18, color="#1a1a1a"),
            outsidetextfont=dict(size=18, color="#1a1a1a"),
            hovertemplate="<b>%{customdata[0]}</b><br>Остаток плана: %{x}<br>План всего: %{customdata[1]}<extra></extra>"
            if is_h
            else "<b>%{x}</b><br>Остаток плана: %{y}<br>План всего: %{customdata[1]}<extra></extra>",
            **_bar_text_common,
        )
        _ovd_kw = dict(
            name="Просрочено",
            marker_color="#C0392B",
            text=[_lbl(v, use_pct) for v in plot_df["overdue_v"]],
            insidetextfont=dict(size=18, color="white"),
            outsidetextfont=dict(size=18, color="#1a1a1a"),
            customdata=cat,
            hovertemplate="<b>%{customdata}</b><br>Просрочено: %{x}<extra></extra>"
            if is_h
            else "<b>%{x}</b><br>Просрочено: %{y}<extra></extra>",
            **_bar_text_common,
        )
        if is_h:
            _use_numeric_y = True
            cat = plot_df["Месяц"].tolist()
            y_idx = list(range(len(plot_df)))
            fig.add_trace(
                go.Bar(y=y_idx, x=plot_df["done_v"], orientation="h", **_done_kw)
            )
            fig.add_trace(
                go.Bar(y=y_idx, x=plot_df["rest_v"], orientation="h", **_plan_kw)
            )
            fig.add_trace(
                go.Bar(y=y_idx, x=plot_df["overdue_v"], orientation="h", **_ovd_kw)
            )
            fig.update_layout(xaxis_title=x_title, yaxis_title="Месяц")
        else:
            # Вертикально: слева направо от текущего к ранним.
            plot_df = plot_df.iloc[::-1].reset_index(drop=True)
            cat = plot_df["Месяц"].tolist()
            fig.add_trace(go.Bar(x=cat, y=plot_df["done_v"], **{
                **_done_kw,
                "text": [_lbl(v, use_pct) for v in plot_df["done_v"]],
                "customdata": cat,
            }))
            fig.add_trace(go.Bar(x=cat, y=plot_df["rest_v"], **{
                **_plan_kw,
                "text": [_lbl(v, use_pct) for v in plot_df["rest_v"]],
                "customdata": list(zip(cat, plot_df["plan_v"].tolist())),
            }))
            fig.add_trace(go.Bar(x=cat, y=plot_df["overdue_v"], **{
                **_ovd_kw,
                "text": [_lbl(v, use_pct) for v in plot_df["overdue_v"]],
                "customdata": cat,
            }))
            fig.update_layout(xaxis_title="Месяц", yaxis_title=x_title)
        _n_leg = 3
        _barmode = "stack"
        _margin_r = 36

    _n_rows = max(1, len(cat))
    _yaxis_kw: dict = dict(
        tickfont=dict(color=_ax),
        title_font=dict(color=_ax),
    )
    if is_h and _use_numeric_y:
        # Обычная ось: 0 снизу (ранний), n-1 сверху (последний). Не reversed.
        _yaxis_kw.update(
            tickmode="array",
            tickvals=list(range(_n_rows)),
            ticktext=cat,
            range=[-0.5, _n_rows - 0.5],
            autorange=False,
            fixedrange=False,
        )
    elif use_pct:
        _yaxis_kw.update(range=[0, 100], ticksuffix="%")
    _leg_m = _line_chart_legend_below(n_items=_n_leg, long_labels=False)
    _leg_m["font"] = dict(size=12, color=_fin_chart_legend_text_color())
    fig.update_layout(
        barmode=_barmode,
        legend=_leg_m,
        showlegend=True,
        height=max(520, min(900, _n_rows * 36)) if is_h else 520,
        margin=dict(l=60, r=_margin_r, t=48, b=140),
        xaxis=dict(tickfont=dict(color=_ax), title_font=dict(color=_ax)),
        yaxis=_yaxis_kw,
        bargap=0.25,
    )
    if is_h:
        if use_pct:
            fig.update_layout(
                xaxis=dict(
                    range=[0, 100],
                    ticksuffix="%",
                    tickfont=dict(color=_ax),
                    title_font=dict(color=_ax),
                )
            )
        else:
            fig.update_layout(
                xaxis=dict(
                    range=[0, _x_max * (1.18 if cumulative else 1.12)],
                    tickfont=dict(color=_ax),
                    title_font=dict(color=_ax),
                )
            )
    elif not use_pct:
        fig.update_layout(
            yaxis=dict(
                range=[0, _x_max * (1.18 if cumulative else 1.12)],
                tickfont=dict(color=_ax),
                title_font=dict(color=_ax),
            )
        )
    fig = apply_chart_background(fig)
    _leg_m = _line_chart_legend_below(n_items=_n_leg, long_labels=False)
    _leg_m["font"] = dict(size=12, color=_fin_chart_legend_text_color())
    fig.update_layout(
        legend=_leg_m,
        showlegend=True,
        margin=dict(l=60, r=_margin_r, t=48, b=150),
        barmode=_barmode,
    )
    if is_h and _use_numeric_y:
        fig.update_yaxes(
            tickmode="array",
            tickvals=list(range(_n_rows)),
            ticktext=cat,
            range=[-0.5, _n_rows - 0.5],
            autorange=False,
        )
    _cap = (
        report_chart_caption_body(caption_parts[0], caption_parts[1])
        if caption_parts
        else report_chart_caption_body("Выдача рабочей документации", "по месяцам")
    )
    render_chart(fig, key=chart_key, caption_below=_cap)


def _rd_status_filter_expand(labels: set[str] | list[str]) -> set[str]:
    """Синонимы статусов плана CSV и TESSA для фильтра «Статус»."""
    _groups: tuple[tuple[str, frozenset[str]], ...] = (
        (
            "согласован",
            frozenset(
                {
                    "согласован",
                    "принят",
                    "принято",
                    "подписан",
                    "зарегистрирован",
                    "approved",
                    "signed",
                    "registered",
                }
            ),
        ),
        (
            "на согласовании",
            frozenset(
                {
                    "на согласовании",
                    "на рассмотрении",
                    "на рассм.",
                    "на подписании",
                    "на регистрации",
                    "на ознакомлении",
                    "проект",
                    "draft",
                    "approving",
                    "signing",
                    "registration",
                    "reviewing",
                }
            ),
        ),
        (
            "на доработке",
            frozenset({"на доработке", "amending", "возвр.", "возврат"}),
        ),
        (
            "не принят",
            frozenset(
                {
                    "не принят",
                    "не принято",
                    "отказ",
                    "declined",
                    "не согласован",
                    "not approved",
                    "отмена",
                    "cancelled",
                    "canceled",
                }
            ),
        ),
        (
            "выдано в производство работ",
            frozenset({"выдано в производство работ", "направлен в производство работ"}),
        ),
        (
            "на рассмотрении у гип",
            frozenset(
                {
                    "на рассмотрении у гип",
                    "на рассмотрение у гип",
                    "на рассмотрении",
                }
            ),
        ),
        (
            "возвращено на доработку",
            frozenset(
                {
                    "возвращено на доработку",
                    "возвращен на доработку",
                    "на доработке",
                    "возвр.",
                }
            ),
        ),
        (
            "не выдано",
            frozenset({"не выдано", "не выдан"}),
        ),
        (
            "передано подрядчику",
            frozenset(
                {
                    "передано подрядчику",
                    "выдана подрядчику",
                    "выдан в производство работ подрядчикам",
                }
            ),
        ),
    )
    out: set[str] = set()
    for lbl in labels:
        s = str(lbl).strip()
        if not s:
            continue
        sl = s.casefold()
        out.add(s)
        out.add(sl)
        for _key, syns in _groups:
            if sl == _key or sl in syns:
                out |= syns
                out.add(_key)
    return out


def _rd_status_label_matches_filter(label: str, expanded: set[str]) -> bool:
    s = str(label or "").strip()
    if not s:
        return False
    sl = s.casefold()
    exp_cf = {str(x).casefold() for x in expanded}
    return s in expanded or sl in exp_cf


def _fmt_rd_deviation_days_display(series) -> pd.Series:
    """Подпись отклонения в днях: «+N» / «−N» / «0» / «—»."""
    _s = pd.to_numeric(series, errors="coerce")

    def _one(x):
        if pd.isna(x):
            return "—"
        n = int(round(float(x)))
        if n > 0:
            return f"+{n}"
        return str(n)

    return _s.apply(_one)


def _apply_rd_detail_deviation_columns(tbl: pd.DataFrame) -> pd.DataFrame:
    """Отклонения РД по ТЗ. Числитель един для обеих колонок: «Дата выдачи в
    производство работ», а если раздел ещё не выдан — сегодняшняя дата.
    Знак по ТЗ: просрочка — ОТРИЦАТЕЛЬНАЯ (красная с «−»), опережение/в срок —
    положительное (зелёное). Т.е. отклонение = дата − (факт|сегодня).
      • «от даты по договору» = Дата по договору − (факт выдачи | сегодня);
        без плановой даты по договору — пусто «—»;
      • «от прогнозной даты» = Прогнозная дата (срок по распоряжениям/указаниям
        ПИГ) − (факт выдачи | сегодня); без прогнозной — пусто «—».
    """
    if tbl is None or getattr(tbl, "empty", True):
        return tbl
    out = tbl.copy()
    plan_col = "Дата выдачи разделов по Договору"
    fc_col = "Прогнозная дата выдачи разделов"
    prod_col = "Дата выдачи в производство работ"
    if plan_col not in out.columns:
        return out
    _empty = {"", "—", "-", "nan", "none", "<na>", "nat"}

    def _to_dt(series: pd.Series) -> pd.Series:
        if pd.api.types.is_datetime64_any_dtype(series):
            return pd.to_datetime(series, errors="coerce")
        s = series.map(
            lambda v: (
                v.strftime("%d.%m.%Y")
                if isinstance(v, (pd.Timestamp,))
                else str(v).strip()
            )
        )
        s = s.where(~s.str.casefold().isin(_empty), other=pd.NA)
        return pd.to_datetime(s, errors="coerce", dayfirst=True, format="mixed")

    plan_dt = _to_dt(out[plan_col])
    prod_dt = (
        _to_dt(out[prod_col])
        if prod_col in out.columns
        else pd.Series(pd.NaT, index=out.index)
    )
    fc_dt = (
        _to_dt(out[fc_col])
        if fc_col in out.columns
        else pd.Series(pd.NaT, index=out.index)
    )
    _today = pd.Timestamp.now().normalize()
    _issued = prod_dt.notna()
    # ТЗ: числитель = факт выдачи в производство работ; если раздел не выдан —
    # сегодняшняя дата (текущая просрочка). Единый базис для обеих колонок.
    _base = prod_dt.where(_issued, _today)
    # Знак: дата − (факт|сегодня) → просрочка отрицательная (красная с «−»),
    # опережение/в срок — положительное (зелёное). Нет плановой даты → NaT → «—».
    out["Отклонение от даты по договору, дн"] = (plan_dt - _base).dt.days
    # «От прогнозной даты»: прогнозная − (факт|сегодня). Нет прогнозной → «—».
    out["Отклонение от прогнозной даты, дн"] = (fc_dt - _base).dt.days
    out["Отклонение, дн"] = out["Отклонение от прогнозной даты, дн"]
    return out


# Финальная схема детальной таблицы РД (по ТЗ-скрину): внутренние имена → подписи.
_RD_DETAIL_DISPLAY_RENAME = {
    "Шифр полный": "Полный шифр",
    "Дата выдачи разделов по Договору": "Дата выдачи по договору",
    "Прогнозная дата выдачи разделов": "Прогнозная дата выдачи",
    "Дата загрузки раздела генпроектировщиком": "Дата выдачи генпроектировщиком",
    "Отклонение от даты по договору, дн": "Отклонение от даты по договору",
    "Отклонение от прогнозной даты, дн": "Отклонение от прогнозной даты",
}
_RD_DETAIL_DISPLAY_ORDER = [
    "Проект",
    "Наименование разделов работ",
    "Номер договора",
    "Полный шифр",
    "Версия",
    "Статус",
    "Дата выдачи по договору",
    "Прогнозная дата выдачи",
    "Дата выдачи генпроектировщиком",
    "Дата выдачи в производство работ",
    "Отклонение от даты по договору",
    "Отклонение от прогнозной даты",
    "Подрядчик",
    "ID документа в Тессе",
]


def _rd_detail_prepare_for_display(
    tbl: pd.DataFrame, *, show_forecast: bool = True
) -> pd.DataFrame:
    """Финальная нормализация детальной таблицы РД к виду по ТЗ-скрину:
    форматирование дат/отклонений, скрытие прогноза (по флагу), переименование
    колонок и фиксированный порядок."""
    if tbl is None or getattr(tbl, "empty", True):
        return tbl
    out = tbl.copy()
    for _dc in (
        "Дата выдачи разделов по Договору",
        "Прогнозная дата выдачи разделов",
        "Дата выдачи в производство работ",
        "Дата загрузки раздела генпроектировщиком",
    ):
        if _dc not in out.columns:
            continue
        out[_dc] = out[_dc].map(
            lambda v: (
                v.strftime("%d.%m.%Y")
                if isinstance(v, (pd.Timestamp,))
                else (
                    str(v).strip()
                    if v is not None
                    and not (isinstance(v, float) and pd.isna(v))
                    and str(v).strip().lower()
                    not in ("nan", "none", "<na>", "nat")
                    else ""
                )
            )
        )
        out[_dc] = out[_dc].replace({"": "—"})
    out = _apply_rd_detail_deviation_columns(out)
    for _dev_c in ("Отклонение от даты по договору, дн", "Отклонение от прогнозной даты, дн"):
        if _dev_c in out.columns:
            out[_dev_c] = _fmt_rd_deviation_days_display(out[_dev_c])
    # Финальная схема (переименование + фиксированный порядок) применяется только
    # к таблице билдера РД. Прочие вызовы (CSV-only fallback) не трогаем.
    _is_builder = (
        "Дата выдачи в производство работ" in out.columns
        or "Наименование разделов работ" in out.columns
    )
    if not _is_builder:
        return out
    if not show_forecast:
        out = out.drop(
            columns=[
                c
                for c in ("Прогнозная дата выдачи разделов", "Отклонение от прогнозной даты, дн")
                if c in out.columns
            ]
        )
    # RD-06: колонку «Номер договора» показываем, только если хотя бы у одного
    # раздела номер заполнен (иначе — сплошные «—», DK.json не подгружен).
    if "Номер договора" in out.columns:
        _cn = out["Номер договора"].map(_rd_format_contract_no).astype(str).str.strip()
        if _cn.eq("").all():
            out = out.drop(columns=["Номер договора"])
        else:
            out["Номер договора"] = _cn.replace({"": "—"})
    if "Наименование разделов работ" in out.columns:
        out["Наименование разделов работ"] = out["Наименование разделов работ"].map(
            _rd_plan_unglue_section_name
        )
    if "ID документа в Тессе" in out.columns:
        out["ID документа в Тессе"] = out["ID документа в Тессе"].map(_exec_int_str)
    out = out.rename(columns=_RD_DETAIL_DISPLAY_RENAME)
    _cols = [c for c in _RD_DETAIL_DISPLAY_ORDER if c in out.columns]
    return out[_cols]


def _build_rd_work_doc_detail_table(
    selected_projects: list[str] | None = None,
    selected_section: str | None = None,
) -> pd.DataFrame:
    """
    Детальная таблица РД (RD-01): ровно 1 строка на раздел плана other_*_rd.csv.
    Карточка TESSA обогащает статус/даты; без карточки — «Не выдано».
    Число строк экспорта = плановое кол-во разделов по срезу.
    """
    csv_df = _rd_plan_csv_sections_df(selected_projects)
    tessa_tbl = _build_tessa_rd_detail_table(
        selected_projects=selected_projects,
        selected_section=None,
    )
    if csv_df.empty:
        # Нет плана — показываем только TESSA (legacy), с фильтром секции.
        if (
            selected_section
            and selected_section != "Все"
            and not tessa_tbl.empty
        ):
            _c = tessa_tbl["Шифр"].fillna("").astype(str).str.strip()
            _n = (
                tessa_tbl["Наименование разделов работ"]
                .fillna("")
                .astype(str)
                .str.strip()
            )
            _comb = (_c + " — " + _n).where(_c.ne("") & _n.ne(""), _c.where(_c.ne(""), _n))
            tessa_tbl = tessa_tbl.loc[_comb.eq(selected_section)].copy()
        return tessa_tbl

    pc = _rd_plan_csv_pick_columns(csv_df)
    if not isinstance(pc, dict):
        pc = {}

    # Индексы TESSA: шифр / полный шифр → список (proj_key, idx).
    # Проект сопоставляем толерантно (_project_norm_key_matches_msp_keys),
    # иначе «Дмитровский»↔«Дмитровский 1» даёт все строки «Не выдано».
    # Каждая карточка — не более одного раза (1 план ↔ 1 TESSA).
    by_pn: dict[tuple[str, str], list[tuple[str, int]]] = {}
    by_fc: dict[str, list[tuple[str, int]]] = {}
    by_cipher: dict[str, list[tuple[str, int]]] = {}
    used_tessa: set[int] = set()
    if not tessa_tbl.empty:
        for _ti, _tr in tessa_tbl.iterrows():
            _pk = _project_filter_norm_key(_tr.get("Проект", ""))
            _cc = str(_tr.get("Шифр", "") or "").strip().casefold()
            _nm = str(_tr.get("Наименование разделов работ", "") or "").strip().casefold()
            _fc = str(_tr.get("Шифр полный", "") or "").strip().casefold()
            if _fc and _fc not in ("nan", "none"):
                by_fc.setdefault(_fc, []).append((_pk, _ti))
            if _cc:
                by_pn.setdefault((_cc, _nm), []).append((_pk, _ti))
                by_cipher.setdefault(_cc, []).append((_pk, _ti))

    def _pick_tessa(pk: str, candidates: list[tuple[str, int]] | None) -> int | None:
        if not candidates:
            return None
        _pk_set = {pk} if pk else set()
        for _tpk, _ti in candidates:
            if _ti in used_tessa:
                continue
            if not _pk_set:
                return _ti
            if _project_norm_key_matches_msp_keys(_tpk, _pk_set) or (
                _tpk and _project_norm_key_matches_msp_keys(pk, {_tpk})
            ):
                return _ti
        return None

    out_rows: list[dict[str, Any]] = []
    for _i, row in csv_df.iterrows():
        proj = _rd_csv_cell_str(row.get(pc["proj"], "")) if pc.get("proj") else ""
        cipher = _rd_csv_cell_str(row.get(pc["code"], "")) if pc.get("code") else ""
        sect = _rd_csv_cell_str(row.get(pc["name"], "")) if pc.get("name") else ""
        full_c = (
            _rd_csv_cell_str(row.get(pc["full_cipher"], ""))
            if pc.get("full_cipher") and pc["full_cipher"] in row.index
            else ""
        )
        if not cipher and not sect:
            continue
        if selected_section and selected_section != "Все":
            _comb = (
                (cipher + " — " + sect) if cipher and sect else (sect or cipher)
            )
            if _comb != selected_section:
                continue

        pk = _project_filter_norm_key(proj)
        tessa_idx = None
        if full_c:
            tessa_idx = _pick_tessa(pk, by_fc.get(full_c.casefold()))
        if tessa_idx is None:
            tessa_idx = _pick_tessa(pk, by_pn.get((cipher.casefold(), sect.casefold())))
        if tessa_idx is None and cipher:
            tessa_idx = _pick_tessa(pk, by_cipher.get(cipher.casefold()))

        plan_s = (
            row["_plan_dt"].strftime("%d.%m.%Y")
            if pd.notna(row.get("_plan_dt"))
            else "—"
        )
        fc_s = (
            row["_fact_dt"].strftime("%d.%m.%Y")
            if pd.notna(row.get("_fact_dt"))
            else "—"
        )
        contract_no_csv = (
            _rd_format_contract_no(row.get(pc["contract"], ""))
            if pc.get("contract") and pc["contract"] in row.index
            else ""
        )

        if tessa_idx is not None:
            used_tessa.add(tessa_idx)
            tr = tessa_tbl.loc[tessa_idx]
            _plan_from_t = str(tr.get("Дата выдачи разделов по Договору", "") or "").strip()
            _fc_from_t = str(tr.get("Прогнозная дата выдачи разделов", "") or "").strip()
            out_rows.append(
                {
                    "Проект": proj or str(tr.get("Проект", "") or ""),
                    "Наименование разделов работ": sect
                    or str(tr.get("Наименование разделов работ", "") or ""),
                    "Номер договора": (
                        str(tr.get("Номер договора", "") or "").strip()
                        or contract_no_csv
                    ),
                    "Шифр": cipher or str(tr.get("Шифр", "") or ""),
                    "Шифр полный": full_c or str(tr.get("Шифр полный", "") or ""),
                    "Версия": str(tr.get("Версия", "") or ""),
                    "Статус": str(tr.get("Статус", "") or _RD_TESSA_STATUS_NOT_ISSUED),
                    "Дата выдачи разделов по Договору": (
                        _plan_from_t
                        if _plan_from_t and _plan_from_t not in ("—", "-", "nan")
                        else plan_s
                    ),
                    "Прогнозная дата выдачи разделов": (
                        _fc_from_t
                        if _fc_from_t and _fc_from_t not in ("—", "-", "nan")
                        else (fc_s if fc_s != "—" else "")
                    ),
                    "Дата загрузки раздела генпроектировщиком": str(
                        tr.get("Дата загрузки раздела генпроектировщиком", "") or ""
                    ),
                    "Дата выдачи в производство работ": str(
                        tr.get("Дата выдачи в производство работ", "") or ""
                    ),
                    "Подрядчик": str(tr.get("Подрядчик", "") or ""),
                    "ID документа в Тессе": _exec_int_str(
                        tr.get("ID документа в Тессе", "")
                    ),
                }
            )
        else:
            # RD-09: раздел плана без карточки TESSA = «Не выдано».
            out_rows.append(
                {
                    "Проект": proj,
                    "Наименование разделов работ": sect,
                    "Номер договора": contract_no_csv,
                    "Шифр": cipher,
                    "Шифр полный": full_c,
                    "Версия": "",
                    "Статус": _RD_TESSA_STATUS_NOT_ISSUED,
                    "Дата выдачи разделов по Договору": plan_s,
                    "Прогнозная дата выдачи разделов": fc_s if fc_s != "—" else "",
                    "Дата загрузки раздела генпроектировщиком": "",
                    "Дата выдачи в производство работ": "",
                    "Подрядчик": "",
                    "ID документа в Тессе": "",
                }
            )

    if not out_rows:
        return pd.DataFrame()
    out = pd.DataFrame(out_rows)
    return _drop_rd_detail_empty_rows(_apply_rd_detail_deviation_columns(out))


def _count_rd_fact_to_date_tessa(
    selected_projects: list[str] | None = None,
    *,
    section_labels_allowlist: set[str] | None = None,
) -> float:
    """
    ТЗ п.4: факт на текущую дату — разделы РД в статусе «Выдано в производство работ»
    или «На рассмотрении» (KrState / дата выдачи в производство).
    """
    try:
        detail = _build_rd_work_doc_detail_table(
            selected_projects=selected_projects,
            selected_section=None,
        )
    except Exception:
        detail = pd.DataFrame()
    if not detail.empty and section_labels_allowlist:
        _lbl = (
            detail["Шифр"].fillna("").astype(str).str.strip()
            + " "
            + detail["Наименование разделов работ"].fillna("").astype(str).str.strip()
        ).str.replace(r"\s+", " ", regex=True).str.strip()
        detail = detail.loc[_lbl.isin(section_labels_allowlist)].copy()
    if not detail.empty:
        detail = _drop_rd_detail_empty_rows(detail)
    if not detail.empty and "Статус" in detail.columns:
        # RD-02: факт на текущую дату = разделы РД в статусе «Выдано в
        # производство работ» + «На рассмотрении у ГИП» (ровно по полю Status
        # tessa_*_rd.csv). Раньше факт завышался: считались все карточки с
        # датой выдачи в производство ИЛИ статусом «согласован», а также
        # CSV-разделы без карточки TESSA — это давало ~428 вместо ~374.
        _st = detail["Статус"].astype(str).str.strip()
        _is_prod = _st.eq(_RD_TESSA_STATUS_PRODUCTION)
        _is_review = _st.eq(_RD_TESSA_STATUS_REVIEW) | _st.str.casefold().str.contains(
            "рассмотр", na=False
        )
        return float((_is_prod | _is_review).sum())
    _stage = _count_tessa_rd_stages(
        selected_projects, section_labels_allowlist=section_labels_allowlist
    )
    _kr = _count_tessa_rd_krstates(
        selected_projects, section_labels_allowlist=section_labels_allowlist
    )
    return float(
        int(_stage.get("Выдано в производство работ", 0))
        + int(_kr.get("На рассм.", 0))
    )


def _render_rd_working_doc_monthly_and_detail(
    *,
    work_df: pd.DataFrame,
    selected_projects: list[str] | None,
    selected_sections: list[str] | None,
    selected_statuses: list[str] | None = None,
    status_options: list[str] | None = None,
    metric_mode: str,
    show_forecast_date: bool,
    doc_fk: str,
    plan_end_col: str | None,
    rd_count_col: str | None,
    in_production_col: str | None,
) -> None:
    """ТЗ п.2: динамика по месяцам и детальная таблица РД (как на вкладке просрочки)."""
    if work_df is None or getattr(work_df, "empty", True):
        return

    # RD-10: единый классификатор статусов — детальная таблица и круговая
    # «Исполнение РД» должны показывать один и тот же выбранный статус.
    _status_allow: set[str] | None = None
    if (
        selected_statuses
        and status_options
        and set(selected_statuses) != set(status_options)
    ):
        _status_allow = _rd_status_filter_expand(selected_statuses)

    def _to_numeric_series(series):
        return pd.to_numeric(
            series.astype(str)
            .str.replace(" ", "", regex=False)
            .str.replace(",", ".", regex=False),
            errors="coerce",
        ).fillna(0.0)

    _sec_allow: set[str] | None = None
    if selected_sections:
        _sec_allow = {str(x).strip() for x in selected_sections if str(x).strip()}

    month_source = work_df.copy()
    csv_secs = _rd_plan_csv_sections_df(selected_projects)
    if not csv_secs.empty:
        month_source = csv_secs.copy()
        month_source["_plan_end_dt"] = month_source["_plan_dt"]
        pc0 = _rd_plan_csv_pick_columns(csv_secs)
        if not isinstance(pc0, dict):
            pc0 = {}
        if pc0.get("proj") and pc0.get("code"):
            try:
                month_source = _augment_df_with_tessa_rd(
                    month_source, pc0["proj"], pc0["code"]
                )
            except Exception:
                pass
        _prod_m = _rd_in_production_mask(month_source, in_production_col)
        month_source["_rd_fact_n"] = np.where(_prod_m, month_source["_rd_plan_n"], 0.0)
    elif plan_end_col and plan_end_col in work_df.columns and rd_count_col and rd_count_col in work_df.columns:
        month_source = work_df.copy()
        month_source["_plan_end_dt"] = pd.to_datetime(
            month_source[plan_end_col].astype(str),
            errors="coerce",
            dayfirst=True,
            format="mixed",
        )
        month_source["_rd_plan_n"] = _rd_dynamics_plan_increment_series(
            month_source, rd_count_col, "_plan_end_dt"
        )
        _prod_m = _rd_in_production_mask(work_df, in_production_col)
        month_source["_rd_fact_n"] = np.where(
            _prod_m.reindex(month_source.index, fill_value=False),
            month_source["_rd_plan_n"],
            0.0,
        )

    if (
        month_source is not None
        and not getattr(month_source, "empty", True)
        and "_plan_end_dt" in month_source.columns
    ):
        month_df = month_source[month_source["_plan_end_dt"].notna()].copy()
        if _sec_allow:
            pc_m = _rd_plan_csv_pick_columns(month_df)
            if not isinstance(pc_m, dict):
                pc_m = {}
            if pc_m.get("code") and pc_m.get("name"):
                _lbl_m = (
                    month_df[pc_m["code"]].fillna("").astype(str).str.strip()
                    + " "
                    + month_df[pc_m["name"]].fillna("").astype(str).str.strip()
                ).str.replace(r"\s+", " ", regex=True).str.strip()
                month_df = month_df.loc[_lbl_m.isin(_sec_allow)].copy()
        if not month_df.empty:
            monthly = _rd_monthly_sections_aggregate(month_df)
            if not monthly.empty:
                _render_rd_monthly_overlay_chart(
                    monthly,
                    metric_mode=metric_mode,
                    orientation="v",
                    subheader=(
                        "Динамика по месяцам (% по плану)"
                        if str(metric_mode).strip().startswith("%")
                        else "Динамика по месяцам"
                    ),
                    chart_key=f"{doc_fk}rd_months",
                    caption_parts=("Выдача рабочей документации", "Месяц"),
                    cumulative=not str(metric_mode).strip().startswith("%"),
                )

    try:
        _tessa_tbl = _build_rd_work_doc_detail_table(
            selected_projects=selected_projects or None,
            selected_section=None,
        )
    except Exception:
        _tessa_tbl = pd.DataFrame()
    if _tessa_tbl.empty:
        return
    if _sec_allow:
        _lbl_d = (
            _tessa_tbl["Шифр"].fillna("").astype(str).str.strip()
            + " "
            + _tessa_tbl["Наименование разделов работ"]
            .fillna("")
            .astype(str)
            .str.strip()
        ).str.replace(r"\s+", " ", regex=True).str.strip()
        _tessa_tbl = _tessa_tbl.loc[_lbl_d.isin(_sec_allow)].copy()
    if _status_allow is not None and "Статус" in _tessa_tbl.columns:
        _tessa_tbl = _tessa_tbl[
            _tessa_tbl["Статус"]
            .map(lambda x: _rd_status_label_matches_filter(x, _status_allow))
            .fillna(False)
        ].copy()
    _tessa_tbl = _drop_rd_detail_empty_rows(_tessa_tbl)
    if _tessa_tbl.empty:
        return
    _tessa_tbl = _rd_detail_prepare_for_display(
        _tessa_tbl, show_forecast=show_forecast_date
    )
    st.subheader("Детальная таблица")
    _render_styled_table_report(
        style_dataframe_for_dark_theme(
            _tessa_tbl,
            days_column="Отклонение от даты по договору",
            extra_days_columns=("Отклонение от прогнозной даты",),
            days_deviation_gradient=True,
            # ТЗ: < 0 — красный (с «−»), ≥ 0 — зелёный.
            days_positive_is_ahead=True,
        ),
        _tessa_tbl,
        file_stem="rd_work_doc_detail",
        key_prefix=f"{doc_fk}rd_detail",
        full_width=True,
    )


def _rd_plan_drop_footer_rows(
    df: pd.DataFrame,
    code_col: str | None = None,
    name_col: str | None = None,
    status_col: str | None = None,
) -> pd.DataFrame:
    """Убирает итоговые строки CSV (Всего:/Не выдано:), иначе в фильтр «Статус» попадают числа."""
    if df is None or getattr(df, "empty", True):
        return df
    try:

        def _is_footer(row) -> bool:
            for v in row:
                s = str(v).strip()
                if s and _RD_PLAN_FOOTER_RE.match(s):
                    return True
            return False

        mask = ~df.apply(_is_footer, axis=1)
        if status_col and status_col in df.columns:
            st = df[status_col].fillna("").astype(str).str.strip()
            num_st = st.str.fullmatch(r"\d+(?:\.\d+)?", na=False)
            if code_col and code_col in df.columns:
                cd = df[code_col].fillna("").astype(str).str.strip()
                mask &= ~(cd.eq("") & num_st)
            if name_col and name_col in df.columns:
                nm = df[name_col].fillna("").astype(str).str.strip()
                mask &= ~(nm.eq("") & num_st)
        return df.loc[mask].copy()
    except Exception:
        return df


def _rd_plan_status_display_series(series: pd.Series) -> pd.Series:
    """Текстовые подписи статуса в плане РД/ПД (KrStateID → русский, иначе как в CSV)."""
    return series.map(_krstate_raw_to_label).replace("", pd.NA)


_RD_PIE_STATUS_COLORS: dict[str, str] = {
    "Согласован": "#27AE60",
    "Подписан": "#2ECC71",
    "Зарегистрирован": "#1ABC9C",
    "На согласовании": "#F1C40F",
    "На ознакомлении": "#F39C12",
    "На подписании": "#F1C40F",
    "На регистрации": "#E67E22",
    "На проверке": "#E67E22",
    "Проект": "#95A5A6",
    "На доработке": "#E67E22",
    "Отказ": "#C0392B",
    "Не принято": "#C0392B",
    "Снято": "#7F8C8D",
    "Не выдан": "#F5A9C0",
    "Не выдано": "#F5A9C0",
    "Выдано в производство работ": "#27AE60",
    "На рассмотрении у ГИП": "#F1C40F",
    "Возвращено на доработку": "#C0392B",
    "Передано подрядчику": "#8E44AD",
    "Выдано подрядчику": "#8E44AD",
    "На рассмотрении": "#F1C40F",
}


# Статусы, которых не должно быть в аналитике РД (фильтр «Статус», легенда пирога,
# подсчёты): «Проект» и «Отмена» (по ТЗ п.9 не учитываются; Tessa_Teg=Отмененный
# отсекается ещё при загрузке в web_loader), а также некорректные «принят»/«не
# принят» — таких статусов нет в маппинге KrState (tessa_status_utils).
_RD_STATUS_EXCLUDED_CF: frozenset[str] = frozenset(
    {"проект", "отмена", "принят", "не принят"}
)


def _rd_status_is_excluded(label: object) -> bool:
    s = str(label or "").strip().casefold()
    if not s:
        return False
    if s in _RD_STATUS_EXCLUDED_CF:
        return True
    # Любые варианты отмены: «Отмена», «отменено», «Отменённый», cancelled.
    if "отмен" in s or s in ("cancelled", "canceled"):
        return True
    return False


def _rd_normalize_pie_status_label(raw: object) -> str:
    """Подпись сегмента пирога = подпись в фильтре «Статус» (без N/A и сокращений)."""
    if raw is None or (isinstance(raw, float) and pd.isna(raw)):
        return _RD_TESSA_STATUS_NOT_ISSUED
    canon = _rd_canonical_tessa_rd_status(raw)
    if canon:
        return canon
    s = str(raw).strip()
    if not s or s.casefold() in ("nan", "none", "<na>", "nat", "n/a"):
        return _RD_TESSA_STATUS_NOT_ISSUED
    _legacy_short = {
        "принято": "Согласован",
        "на рассм.": "На согласовании",
        "возвр.": "На доработке",
    }
    sl = s.casefold()
    if sl in _legacy_short:
        return _legacy_short[sl]
    mapped = _krstate_raw_to_label(s)
    if mapped:
        return mapped
    return s


def _rd_plan_map_status_label_from_detail(
    df: pd.DataFrame,
    detail_tbl: pd.DataFrame,
    *,
    proj_col: str | None,
    code_col: str | None,
    name_col: str | None,
    full_cipher_col: str | None,
) -> pd.Series:
    """Статус раздела из TESSA detail — те же подписи, что в фильтре «Статус»."""
    out = pd.Series(pd.NA, index=df.index, dtype="object")
    if df.empty or detail_tbl.empty:
        return out
    ordered = detail_tbl.copy()
    if "Статус" in ordered.columns:
        ordered["_nv"] = (
            ordered["Статус"]
            .astype(str)
            .str.strip()
            .str.casefold()
            .isin({"не выдан", "не выдано"})
        )
        ordered = ordered.sort_values("_nv", kind="stable")
    status_by_fc: dict[str, str] = {}
    status_by_pcn: dict[tuple[str, str, str], str] = {}
    status_by_pc: dict[tuple[str, str], str] = {}
    for _, r in ordered.iterrows():
        st_raw = str(r.get("Статус", "") or "").strip()
        if not st_raw or st_raw.casefold() in ("nan", "none"):
            continue
        label = _rd_normalize_pie_status_label(st_raw)
        fc = str(r.get("Шифр полный", "") or "").strip().casefold()
        if fc and fc not in ("nan", "none"):
            status_by_fc[fc] = label
        pk = (
            _project_filter_norm_key(r.get("Проект", "")),
            str(r.get("Шифр", "") or "").strip().casefold(),
            str(r.get("Наименование разделов работ", "") or "").strip().casefold(),
        )
        status_by_pcn[pk] = label
        status_by_pc.setdefault((pk[0], pk[1]), label)

    for idx, row in df.iterrows():
        label = None
        if full_cipher_col and full_cipher_col in row.index:
            fc = _rd_csv_cell_str(row.get(full_cipher_col)).casefold()
            if fc:
                label = status_by_fc.get(fc)
        if not label and code_col and code_col in row.index:
            pk = (
                _project_filter_norm_key(row.get(proj_col, "")) if proj_col else "",
                _rd_csv_cell_str(row.get(code_col)).casefold(),
                _rd_csv_cell_str(row.get(name_col, "")).casefold()
                if name_col and name_col in row.index
                else "",
            )
            label = status_by_pcn.get(pk) or status_by_pc.get((pk[0], pk[1]))
        if label:
            out.at[idx] = label
    return out


def _rd_plan_pie_status_series(
    df: pd.DataFrame,
    *,
    status_col: str,
    detail_tbl: pd.DataFrame | None = None,
    proj_col: str | None = None,
    code_col: str | None = None,
    name_col: str | None = None,
    full_cipher_col: str | None = None,
) -> pd.Series:
    """Серия статусов для пирога (1 строка плана = 1 раздел).

    Источник статуса — TESSA-деталь (маппинг KrState), а не сырые «Статус»/
    «Статус РД» плана (свободный текст «принят»/«не принят», нет в маппинге).
    Деталь в приоритете; сырой план-статус — только если детали по разделу нет.
    Разделы без карточки TESSA → «Не выдан» (NA→«Не выдан» в нормализации).
    """
    labels = _rd_plan_status_display_series(df[status_col])
    if detail_tbl is not None and not detail_tbl.empty:
        _from_detail = _rd_plan_map_status_label_from_detail(
            df,
            detail_tbl,
            proj_col=proj_col,
            code_col=code_col,
            name_col=name_col,
            full_cipher_col=full_cipher_col,
        )
        _has_detail = _from_detail.notna() & _from_detail.astype(str).str.strip().ne("")
        labels = _from_detail.where(_has_detail, labels)
    return labels.map(_rd_normalize_pie_status_label)


def _rd_plan_pie_from_status_series(statuses: pd.Series) -> dict[str, int]:
    out: dict[str, int] = {}
    if statuses is None or statuses.empty:
        return out
    for v in statuses.tolist():
        if _rd_status_is_excluded(v):
            continue
        key = _rd_normalize_pie_status_label(v)
        if _rd_status_is_excluded(key):
            continue
        out[key] = out.get(key, 0) + 1
    return out


def _rd_plan_pie_sanitize(counts: dict[str, int]) -> dict[str, int]:
    merged: dict[str, int] = {}
    for k, v in (counts or {}).items():
        if int(v) <= 0 or _rd_status_is_excluded(k):
            continue
        key = _rd_normalize_pie_status_label(k)
        if _rd_status_is_excluded(key):
            continue
        merged[key] = merged.get(key, 0) + int(v)
    return merged


def _rd_plan_pie_color_map(keys: list[str]) -> dict[str, str]:
    _palette = (
        "#27AE60",
        "#2980B9",
        "#F1C40F",
        "#E67E22",
        "#C0392B",
        "#8E44AD",
        "#7F8C8D",
        "#16A085",
        "#3498DB",
    )
    out: dict[str, str] = {}
    for i, k in enumerate(keys):
        out[k] = _RD_PIE_STATUS_COLORS.get(k, _palette[i % len(_palette)])
    return out


def _rd_plan_map_buckets_from_detail(
    df: pd.DataFrame,
    detail_tbl: pd.DataFrame,
    *,
    proj_col: str | None,
    code_col: str | None,
    name_col: str | None,
    full_cipher_col: str | None,
) -> pd.Series:
    """Статус TESSA → bucket пирога для каждой строки плана (1 раздел)."""
    out = pd.Series(pd.NA, index=df.index, dtype="object")
    if df.empty or detail_tbl.empty:
        return out
    ordered = detail_tbl.copy()
    if "Статус" in ordered.columns:
        ordered["_nv"] = (
            ordered["Статус"]
            .astype(str)
            .str.strip()
            .str.casefold()
            .isin({"не выдан", "не выдано"})
        )
        ordered = ordered.sort_values("_nv", kind="stable")
    status_by_fc: dict[str, str] = {}
    status_by_pcn: dict[tuple[str, str, str], str] = {}
    status_by_pc: dict[tuple[str, str], str] = {}
    for _, r in ordered.iterrows():
        st_raw = r.get("Статус", "")
        canon = _rd_canonical_tessa_rd_status(st_raw)
        if canon:
            bucket = canon
        elif str(st_raw).strip().casefold() in ("не выдан", "не выдано"):
            bucket = _RD_TESSA_STATUS_NOT_ISSUED
        else:
            # «Статус» детали = категория «как на круговой»; если это не
            # KrState-метка — используем её саму как сегмент пирога.
            bucket = _tessa_krstate_to_pie_bucket(st_raw) or str(st_raw).strip()
        if not bucket:
            continue
        fc = str(r.get("Шифр полный", "") or "").strip().casefold()
        if fc and fc not in ("nan", "none"):
            status_by_fc[fc] = bucket
        pk = (
            _project_filter_norm_key(r.get("Проект", "")),
            str(r.get("Шифр", "") or "").strip().casefold(),
            str(r.get("Наименование разделов работ", "") or "").strip().casefold(),
        )
        status_by_pcn[pk] = bucket
        status_by_pc.setdefault((pk[0], pk[1]), bucket)

    for idx, row in df.iterrows():
        bucket = None
        if full_cipher_col and full_cipher_col in row.index:
            fc = _rd_csv_cell_str(row.get(full_cipher_col)).casefold()
            if fc:
                bucket = status_by_fc.get(fc)
        if not bucket and code_col and code_col in row.index:
            pk = (
                _project_filter_norm_key(row.get(proj_col, "")) if proj_col else "",
                _rd_csv_cell_str(row.get(code_col)).casefold(),
                _rd_csv_cell_str(row.get(name_col, "")).casefold()
                if name_col and name_col in row.index
                else "",
            )
            bucket = status_by_pcn.get(pk) or status_by_pc.get((pk[0], pk[1]))
        if bucket:
            out.at[idx] = bucket
    return out


def _rd_plan_proj_section_counts(
    plan_df: pd.DataFrame,
    proj_col: str | None,
) -> dict[str, int]:
    if plan_df is None or getattr(plan_df, "empty", True) or not proj_col or proj_col not in plan_df.columns:
        return {}
    return (
        plan_df.assign(_pk=plan_df[proj_col].map(_project_filter_norm_key))
        .groupby("_pk")
        .size()
        .astype(int)
        .to_dict()
    )


_RD_DETAIL_DATE_ALIASES: dict[str, tuple[str, ...]] = {
    "Дата выдачи разделов по Договору": (
        "Дата выдачи по договору",
        "План выдачи (по Договору)",
    ),
    "Прогнозная дата выдачи разделов": (
        "Прогнозная дата выдачи",
        "Прогноз/Факт выдачи",
    ),
    "Шифр": ("Шифр раздела",),
    "Наименование разделов работ": ("Наименование", "Наименование раздела"),
}


def _rd_parse_chart_date_cell(v) -> pd.Timestamp:
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return pd.NaT
    if isinstance(v, pd.Timestamp):
        return v.normalize() if pd.notna(v) else pd.NaT
    s = str(v).strip()
    if not s or s.casefold() in ("—", "-", "nan", "none", "<na>", "nat"):
        return pd.NaT
    if "/" in s:
        parts = [p.strip() for p in s.split("/") if p.strip()]
        dts: list[pd.Timestamp] = []
        for p in parts:
            dt = pd.to_datetime(p, errors="coerce", dayfirst=True, format="mixed")
            if pd.notna(dt):
                dts.append(pd.Timestamp(dt).normalize())
        return max(dts) if dts else pd.NaT
    dt = pd.to_datetime(s, errors="coerce", dayfirst=True, format="mixed")
    return pd.Timestamp(dt).normalize() if pd.notna(dt) else pd.NaT


def _rd_format_chart_date_cell(v) -> str:
    ts = _rd_parse_chart_date_cell(v)
    return ts.strftime("%d.%m.%Y") if pd.notna(ts) else ""


def _rd_delay_normalize_detail_columns(tbl: pd.DataFrame) -> pd.DataFrame:
    if tbl is None or getattr(tbl, "empty", True):
        return tbl
    out = tbl.copy()
    for canon, alts in _RD_DETAIL_DATE_ALIASES.items():
        if canon in out.columns:
            continue
        for alt in alts:
            if alt in out.columns:
                out[canon] = out[alt]
                break
    return out


def _rd_delay_enrich_detail_from_plan(
    detail_tbl: pd.DataFrame,
    plan_sec_df: pd.DataFrame | None,
    plan_proj_col: str | None,
) -> pd.DataFrame:
    out = _rd_delay_normalize_detail_columns(detail_tbl)
    if (
        out is None
        or getattr(out, "empty", True)
        or plan_sec_df is None
        or getattr(plan_sec_df, "empty", True)
    ):
        return out
    contract_c = "Дата выдачи разделов по Договору"
    forecast_c = "Прогнозная дата выдачи разделов"
    pc = _rd_plan_csv_pick_columns(plan_sec_df)
    code_c = pc.get("code")
    name_c = pc.get("name")
    proj_c = plan_proj_col or pc.get("proj")
    plan_dt_s = (
        plan_sec_df["_plan_dt"]
        if "_plan_dt" in plan_sec_df.columns
        else pd.Series(pd.NaT, index=plan_sec_df.index)
    )
    fact_dt_s = (
        plan_sec_df["_fact_dt"]
        if "_fact_dt" in plan_sec_df.columns
        else pd.Series(pd.NaT, index=plan_sec_df.index)
    )
    if pc.get("plan") and pc["plan"] in plan_sec_df.columns and plan_dt_s.isna().all():
        plan_dt_s = pd.to_datetime(
            plan_sec_df[pc["plan"]], errors="coerce", dayfirst=True, format="mixed"
        )
    if pc.get("forecast") and pc["forecast"] in plan_sec_df.columns and fact_dt_s.isna().all():
        fact_dt_s = pd.to_datetime(
            plan_sec_df[pc["forecast"]], errors="coerce", dayfirst=True, format="mixed"
        )
    lookup: dict[tuple[str, str, str], tuple[str, str]] = {}
    for _i, row in plan_sec_df.iterrows():
        pk = _project_filter_norm_key(row.get(proj_c, "")) if proj_c else ""
        cc = _rd_csv_cell_str(row.get(code_c, "")).casefold() if code_c else ""
        nn = _rd_csv_cell_str(row.get(name_c, "")).casefold() if name_c else ""
        contract = (
            _rd_format_chart_date_cell(plan_dt_s.loc[_i])
            if _i in plan_dt_s.index and pd.notna(plan_dt_s.loc[_i])
            else ""
        )
        forecast = (
            _rd_format_chart_date_cell(fact_dt_s.loc[_i])
            if _i in fact_dt_s.index and pd.notna(fact_dt_s.loc[_i])
            else ""
        )
        if not contract and not forecast:
            continue
        lookup[(pk, cc, nn)] = (contract, forecast)
        if cc:
            lookup.setdefault((pk, cc, ""), (contract, forecast))
    if not lookup:
        return out
    _empty = {"", "—", "-", "nan", "none", "<na>", "nat"}

    def _needs_fill(val) -> bool:
        return str(val or "").strip().casefold() in _empty

    for idx, row in out.iterrows():
        pk = _project_filter_norm_key(row.get("Проект", ""))
        cc = str(row.get("Шифр", "") or "").strip().casefold()
        nn = str(row.get("Наименование разделов работ", "") or "").strip().casefold()
        entry = lookup.get((pk, cc, nn)) or lookup.get((pk, cc, ""))
        if not entry:
            continue
        contract, forecast = entry
        if contract_c in out.columns and _needs_fill(out.at[idx, contract_c]):
            out.at[idx, contract_c] = contract
        if forecast_c in out.columns and _needs_fill(out.at[idx, forecast_c]):
            out.at[idx, forecast_c] = forecast
    return out


def _rd_delay_chart_segments(
    start_n: pd.Timestamp,
    contract_n: pd.Timestamp,
    forecast_n: pd.Timestamp | None,
    *,
    done: bool,
) -> dict:
    """Сегменты графика просрочки РД (как ПД по ТЗ):
      • жёлтый — start → «Дата по договору» (подпись — дата по договору);
      • зелёный — только если все «Завершено» и прогнозная ≤ по договору;
      • красный — от даты по договору до прогнозной, если прогнозная позже
        (и для незавершённых, и для завершённых с опозданием).
    """
    start_n = pd.Timestamp(start_n).normalize()
    contract_n = pd.Timestamp(contract_n).normalize()
    forecast_ts = (
        pd.Timestamp(forecast_n).normalize()
        if forecast_n is not None and pd.notna(forecast_n)
        else pd.NaT
    )
    base_dur = max(int((contract_n - start_n).days), 0)
    contract_lbl = _pd_chart_date_label(contract_n)
    forecast_lbl = _pd_chart_date_label(forecast_ts) if pd.notna(forecast_ts) else ""
    if pd.notna(forecast_ts) and forecast_ts > contract_n:
        delay_dur = int((forecast_ts - contract_n).days)
        # RD-09: раздел выдан в производство с опозданием — рисуем зелёный
        # (start → дата по договору) + красный (по договору → факт), чтобы у
        # выданных разделов всегда была зелёная линия, а не только красная.
        return {
            "_start_dt": start_n,
            "_bf_dt": contract_n,
            "_fin_dt": contract_n if done else pd.NaT,
            "_delay_end_dt": forecast_ts,
            "_base_dur": float(base_dur),
            "_fact_dur": float(base_dur) if done else 0.0,
            "_delay_dur": float(delay_dur),
            "_lbl_yellow": contract_lbl,
            "_lbl_green": "",
            "_lbl_red": forecast_lbl,
        }
    if done and pd.notna(forecast_ts):
        fact_dur = max(int((forecast_ts - start_n).days), 0)
        gap_small = abs(int((contract_n - forecast_ts).days)) <= 5
        return {
            "_start_dt": start_n,
            "_bf_dt": contract_n,
            "_fin_dt": forecast_ts,
            "_delay_end_dt": pd.NaT,
            "_base_dur": float(base_dur),
            "_fact_dur": float(fact_dur),
            "_delay_dur": 0.0,
            "_lbl_yellow": contract_lbl,
            "_lbl_green": "" if gap_small or fact_dur <= 0 else forecast_lbl,
            "_lbl_red": "",
        }
    return {
        "_start_dt": start_n,
        "_bf_dt": contract_n,
        "_fin_dt": pd.NaT,
        "_delay_end_dt": pd.NaT,
        "_base_dur": float(base_dur),
        "_fact_dur": 0.0,
        "_delay_dur": 0.0,
        "_lbl_yellow": contract_lbl,
        "_lbl_green": "",
        "_lbl_red": "",
    }


def _rd_delay_build_date_rows(
    tbl: pd.DataFrame,
    *,
    by_section: bool,
    ts_report: pd.Timestamp,
    show_forecast: bool = True,
) -> tuple[pd.DataFrame, str]:
    """Строки для Gantt просрочки РД (схема ПД): дата по договору (жёлтый),
    прогнозная дата (зелёный/красный), зелёный — если все задачи «Завершено»."""
    contract_c = "Дата выдачи разделов по Договору"
    forecast_c = "Прогнозная дата выдачи разделов"
    work = _rd_delay_normalize_detail_columns(tbl.copy())
    work["_contract_dt"] = work.get(contract_c, pd.Series(index=work.index)).map(
        _rd_parse_chart_date_cell
    )
    work["_forecast_dt"] = work.get(forecast_c, pd.Series(index=work.index)).map(
        _rd_parse_chart_date_cell
    )
    _prod_col = "Дата выдачи в производство работ"
    if _prod_col in work.columns:
        work["_production_dt"] = work[_prod_col].map(_rd_parse_chart_date_cell)
    else:
        work["_production_dt"] = pd.NaT
    if "_rd_done" in work.columns:
        _archive_done = work["_rd_done"].fillna(False).astype(bool)
    else:
        _archive_done = pd.Series(False, index=work.index)
    if "Статус" in work.columns:
        _st_cf = work["Статус"].fillna("").astype(str).str.strip().str.casefold()
        _status_done = _st_cf.eq("выдано в производство работ") | _st_cf.eq(
            "завершено"
        )
    else:
        _status_done = pd.Series(False, index=work.index)
    # Зелёный: «Завершено» (архив TESSA) / выдано в производство / есть дата выдачи.
    work["_done_flag"] = (
        _archive_done | _status_done | work["_production_dt"].notna()
    )
    if by_section:
        work["_y"] = (
            work["Шифр"].fillna("").astype(str).str.strip()
            + " "
            + work["Наименование разделов работ"].fillna("").astype(str).str.strip()
        ).str.replace(r"\s+", " ", regex=True).str.strip()
        y_col = "Раздел"
    else:
        work["_y"] = work["Проект"].fillna("").astype(str).str.strip()
        y_col = "Проект"
    work["_y"] = work["_y"].replace({"": "—", "nan": "—"})

    # Отсекаем мусорные даты до расчёта шкалы (иначе max → 2080 и ломает ось).
    _ymax = pd.Timestamp(ts_report).normalize() + pd.DateOffset(years=10)
    _ymin = pd.Timestamp("2000-01-01")
    _c_bad = work["_contract_dt"].notna() & (
        (work["_contract_dt"] < _ymin) | (work["_contract_dt"] > _ymax)
    )
    work.loc[_c_bad, "_contract_dt"] = pd.NaT
    _f_bad = work["_forecast_dt"].notna() & (
        (work["_forecast_dt"] < _ymin) | (work["_forecast_dt"] > _ymax)
    )
    work.loc[_f_bad, "_forecast_dt"] = pd.NaT
    # «Дата выдачи в производство работ» имеет приоритет над прогнозной при выборе
    # конца красной полосы — её мусорные значения (напр. 01.01.2080) тоже отсекаем,
    # иначе красный сегмент уезжает в далёкое будущее.
    if "_production_dt" in work.columns:
        _p_bad = work["_production_dt"].notna() & (
            (work["_production_dt"] < _ymin) | (work["_production_dt"] > _ymax)
        )
        work.loc[_p_bad, "_production_dt"] = pd.NaT

    # Глобальное начало шкалы — самая ранняя из дат (договор/прогноз) минус отступ,
    # чтобы у самого раннего срока жёлтый сегмент имел видимую ширину.
    _all_dates = pd.concat([work["_contract_dt"], work["_forecast_dt"]]).dropna()
    if _all_dates.empty:
        return pd.DataFrame(), y_col
    _dmin = _all_dates.min()
    _dmax = _all_dates.max()
    _span = max(int((_dmax - _dmin).days), 1)
    _start = (_dmin - pd.Timedelta(days=max(int(_span * 0.04), 3))).normalize()

    rows: list[dict] = []
    for y_lbl, grp in work.groupby("_y", sort=False):
        _contracts = grp["_contract_dt"].dropna()
        if _contracts.empty:
            continue
        # По проекту/разделу: конец жёлтого = последнее «по договору» (как max БО у ПД).
        contract_n = pd.Timestamp(_contracts.max()).normalize()
        # Несколько версий TESSA на один шифр: «не выдан» у старых версий не должен
        # блокировать зелёный, если есть завершённая/выданная карточка.
        _done_grp = grp.loc[grp["_done_flag"]]
        done = not _done_grp.empty
        forecast_n = None
        if show_forecast:
            _src = _done_grp if done else grp
            _prod = _src["_production_dt"].dropna()
            if not _prod.empty:
                forecast_n = pd.Timestamp(_prod.max()).normalize()
            else:
                _forecasts = _src["_forecast_dt"].dropna()
                if _forecasts.empty and done:
                    _forecasts = grp["_forecast_dt"].dropna()
                if not _forecasts.empty:
                    forecast_n = pd.Timestamp(_forecasts.max()).normalize()
        seg = _rd_delay_chart_segments(
            _start,
            contract_n,
            forecast_n,
            done=done,
        )
        rows.append({y_col: str(y_lbl), **seg})
    return pd.DataFrame(rows), y_col


def _render_rd_delay_fallback_chart(
    detail_tbl: pd.DataFrame,
    *,
    view_mode: str,
    doc_code: str,
    metric_mode: str = "Количество разделов",
    show_forecast: bool = True,
    plan_sec_df: pd.DataFrame | None = None,
    plan_proj_col: str | None = None,
) -> None:
    """График «Просрочка выдачи РД»: Gantt по датам (стиль ПД) — жёлтый «Дата по
    договору», зелёный/красный «Прогнозная дата выдачи разделов», зелёный — для
    разделов, у которых все задачи «Завершено». Фолбэк — столбчатый график."""
    if detail_tbl is None or getattr(detail_tbl, "empty", True):
        st.info("Нет данных для графика просрочки.")
        return
    # RD-11: в режиме «% от общего объёма» основной график — столбчатый с долей
    # просроченных разделов от объёма; date-Gantt остаётся для «Количество разделов».
    if str(metric_mode or "").strip().startswith("%"):
        _render_rd_delay_overdue_bar_chart(
            detail_tbl,
            view_mode=view_mode,
            doc_code=doc_code,
            metric_mode=metric_mode,
            plan_sec_df=plan_sec_df,
            plan_proj_col=plan_proj_col,
        )
        return
    # Основной график — date-Gantt (как на ТЗ) для режима «Количество разделов».
    _tbl_g = _rd_delay_enrich_detail_from_plan(
        _drop_rd_detail_empty_rows(detail_tbl.copy()),
        plan_sec_df,
        plan_proj_col,
    )
    _gantt_ok = (
        not _tbl_g.empty
        and "Дата выдачи разделов по Договору" in _tbl_g.columns
        and "Шифр" in _tbl_g.columns
        and "Наименование разделов работ" in _tbl_g.columns
    )
    if _gantt_ok:
        by_section = str(view_mode or "").strip().casefold() == "по разделу"
        ts_report = pd.Timestamp.today().normalize()
        _rows, _y_col = _rd_delay_build_date_rows(
            _tbl_g,
            by_section=by_section,
            ts_report=ts_report,
            show_forecast=show_forecast,
        )
        if not _rows.empty:
            _rows = _rows.rename(columns={_y_col: "_rd_chart_y"})
            fig = _pd_delay_section_duration_figure(
                _rows,
                y_col="_rd_chart_y",
                yellow_name="Дата по договору",
                green_name="Прогнозная дата",
                yellow_hover="Дата по договору",
                green_hover="Прогнозная дата выдачи",
                show_forecast=show_forecast,
                delay_label_as_days=True,
            )
            # Ключ зависит от checkbox/режима — иначе Streamlit кэширует старый fig.
            _ck = (
                f"rd_delay_gantt_{doc_code}_"
                f"{'fc1' if show_forecast else 'fc0'}_"
                f"{'sec' if by_section else 'proj'}"
            )
            _render_pd_delay_duration_chart(
                fig, f"Просрочка выдачи {doc_code}", chart_key=_ck
            )
            return
    _render_rd_delay_overdue_bar_chart(
        detail_tbl,
        view_mode=view_mode,
        doc_code=doc_code,
        metric_mode=metric_mode,
        plan_sec_df=plan_sec_df,
        plan_proj_col=plan_proj_col,
    )


def _render_rd_delay_overdue_bar_chart(
    detail_tbl: pd.DataFrame,
    *,
    view_mode: str,
    doc_code: str,
    metric_mode: str = "Количество разделов",
    plan_sec_df: pd.DataFrame | None = None,
    plan_proj_col: str | None = None,
) -> None:
    """Фолбэк: столбчатый график просрочки РД (кол-во/% просроченных разделов)."""
    if detail_tbl is None or getattr(detail_tbl, "empty", True):
        st.info("Нет данных для графика просрочки.")
        return
    tbl = _drop_rd_detail_empty_rows(detail_tbl.copy())
    dev_c = "Отклонение от даты по договору, дн"
    if dev_c not in tbl.columns:
        st.info("Нет колонки отклонения для графика просрочки.")
        return
    dev_num = pd.to_numeric(tbl[dev_c], errors="coerce").fillna(0.0)
    # По ТЗ просрочка — отрицательное отклонение; величина просрочки = |min(0, dev)|.
    tbl["_dev_n"] = (-dev_num).clip(lower=0.0)
    tbl["_sec_key"] = _rd_delay_detail_section_keys(tbl)
    by_section = str(view_mode or "").strip().casefold() == "по разделу"
    if by_section:
        tbl["_y"] = (
            tbl["Шифр"].fillna("").astype(str).str.strip()
            + " "
            + tbl["Наименование разделов работ"].fillna("").astype(str).str.strip()
        ).str.replace(r"\s+", " ", regex=True).str.strip()
        y_col = "Раздел"
        y_title = ""
    else:
        tbl["_y"] = tbl["Проект"].fillna("").astype(str).str.strip()
        y_col = "Проект"
        y_title = ""
    tbl["_y"] = tbl["_y"].replace({"": "—", "nan": "—"})
    _sec_tbl = (
        tbl.groupby(["_y", "_sec_key"], as_index=False)
        .agg(_dev_max=("_dev_n", "max"))
    )
    _sec_tbl["_overdue"] = _sec_tbl["_dev_max"] > 0
    use_pct = str(metric_mode or "").strip().startswith("%")
    _proj_totals_norm = _rd_plan_proj_section_counts(plan_sec_df, plan_proj_col)
    if by_section:
        chart_data = (
            _sec_tbl.groupby("_y", as_index=False)
            .agg(
                _overdue_cnt=("_overdue", lambda s: int(s.sum())),
                _total_cnt=("_sec_key", "nunique"),
            )
            .rename(columns={"_y": y_col})
        )
    else:
        chart_data = (
            _sec_tbl.groupby("_y", as_index=False)
            .agg(_overdue_cnt=("_overdue", lambda s: int(s.sum())))
            .rename(columns={"_y": y_col})
        )
        chart_data["_pk"] = chart_data[y_col].map(_project_filter_norm_key)
        chart_data["_total_cnt"] = chart_data["_pk"].map(
            lambda k: int(_proj_totals_norm.get(k, 0))
        )
        _miss = chart_data["_total_cnt"] <= 0
        if _miss.any():
            _fb_tot = (
                _sec_tbl.groupby("_y")["_sec_key"]
                .nunique()
                .rename("_total_cnt")
                .reset_index()
                .rename(columns={"_y": y_col})
            )
            chart_data = chart_data.drop(columns=["_total_cnt"], errors="ignore").merge(
                _fb_tot, on=y_col, how="left"
            )
            chart_data["_total_cnt"] = chart_data["_total_cnt"].fillna(0).astype(int)
        chart_data = chart_data.drop(columns=["_pk"], errors="ignore")
    chart_data["_overdue_cnt"] = np.where(
        chart_data["_total_cnt"] > 0,
        np.minimum(
            chart_data["_overdue_cnt"].astype(int),
            chart_data["_total_cnt"].astype(int),
        ),
        chart_data["_overdue_cnt"].astype(int),
    )
    chart_data["_overdue_pct"] = np.where(
        chart_data["_total_cnt"] > 0,
        chart_data["_overdue_cnt"] / chart_data["_total_cnt"] * 100.0,
        0.0,
    )
    val_col = "_overdue_pct" if use_pct else "_overdue_cnt"
    x_title = (
        "% просроченных разделов от объёма"
        if use_pct
        else "Количество просроченных разделов"
    )
    chart_data = chart_data[chart_data[val_col] > 0].copy()
    if chart_data.empty:
        st.info("Нет просрочки для выбранных фильтров.")
        return
    chart_data = chart_data.sort_values(val_col, ascending=False)
    text_values = []
    for _, row in chart_data.iterrows():
        ovd = int(row.get("_overdue_cnt", 0) or 0)
        tot = int(row.get("_total_cnt", 0) or 0)
        pct = float(row.get("_overdue_pct", 0) or 0)
        if use_pct:
            text_values.append(
                f"{pct:.0f}% ({ovd} из {tot})" if tot > 0 else f"{pct:.0f}%"
            )
        else:
            text_values.append(
                f"{ovd} из {tot} ({pct:.0f}%)" if tot > 0 else str(ovd)
            )
    chart_data["_severity"] = pd.to_numeric(chart_data[val_col], errors="coerce").fillna(0.0).clip(
        lower=0.0
    )
    severity_max = max(float(chart_data["_severity"].max()), 1.0)
    _dev_vals = chart_data["_severity"]
    _tick_labels = [
        (f"🔴 {lbl}" if float(d) > 0 else f"🟢 {lbl}")
        for lbl, d in zip(chart_data[y_col].astype(str).tolist(), _dev_vals.tolist())
    ]
    fig = px.bar(
        chart_data,
        x=val_col,
        y=y_col,
        orientation="h",
        title=None,
        labels={y_col: y_title, val_col: x_title},
        text=text_values,
        color="_severity",
        color_continuous_scale=[(0.0, "#27AE60"), (0.5, "#F1C40F"), (1.0, "#C0392B")],
        range_color=(0.0, severity_max if not use_pct else max(severity_max, 100.0)),
    )
    fig.update_traces(
        textposition="outside",
        textangle=0,
        textfont=dict(size=12, color="white"),
        marker=dict(line=dict(width=1, color="white")),
        showlegend=False,
    )
    category_list = chart_data[y_col].tolist()
    def _wrap_tick(text: str, width: int = 28) -> str:
        words = str(text).split()
        if not words:
            return str(text)
        lines: list[str] = []
        cur = ""
        for w in words:
            if not cur:
                cur = w
            elif len(cur) + 1 + len(w) <= width:
                cur = f"{cur} {w}"
            else:
                lines.append(cur)
                cur = w
        if cur:
            lines.append(cur)
        return "<br>".join(lines)

    _tick_wrapped = (
        [_wrap_tick(lbl) for lbl in _tick_labels] if by_section else list(_tick_labels)
    )
    _chart_h = _pd_delay_chart_height_for_labels(
        max(1, len(chart_data)), _tick_wrapped, min_px=480, layout_pad=56
    )
    fig.update_layout(
        xaxis_title=x_title,
        yaxis_title=y_title,
        height=_chart_h,
        showlegend=False,
        coloraxis_showscale=False,
        xaxis=dict(range=[0, 100], ticksuffix="%") if use_pct else {},
        yaxis=dict(
            tickangle=0,
            categoryorder="array",
            categoryarray=list(reversed(category_list)),
            tickmode="array",
            tickvals=category_list,
            ticktext=list(reversed(_tick_wrapped)),
            automargin=True,
        ),
        bargap=0.12,
    )
    fig = _apply_bar_uniformtext(fig)
    fig = apply_chart_background(fig)
    _viewport = min(
        _chart_h, max(520, _PD_DELAY_CHART_VISIBLE_ROWS * _PD_DELAY_CHART_ROW_PX)
    )
    render_chart(
        fig,
        caption_below=report_chart_caption_body(f"Просрочка выдачи {doc_code}"),
        height=_chart_h,
        max_height=None,
        scroll_viewport_height=_viewport if _chart_h > _viewport else None,
        skip_clamp_zoom=True,
        compact=_chart_h <= _viewport,
    )


def _rd_plan_fallback_view(
    page_title: str = "",
    doc_code: str = "РД",
    source_key: str = "rd_plan_data",
) -> bool:
    try:
        rd_plan = st.session_state.get(source_key) if hasattr(st, "session_state") else None
    except Exception:
        rd_plan = None
    if rd_plan is None or getattr(rd_plan, "empty", True):
        return False

    df = rd_plan.copy()
    df.columns = [
        re.sub(r"\s+", " ", str(c).replace("\r", " ").replace("\n", " ").replace("\u00a0", " ")).strip()
        for c in df.columns
    ]
    # Двухстрочные заголовки CSV (например «Дата выдачи разделов по\nДоговору»)
    # после нормализации могут давать дублирующиеся имена колонок — иначе
    # df[col] вернёт DataFrame и pd.to_datetime упадёт «cannot assemble with
    # duplicate keys». Из одноимённых оставляем САМУЮ ЗАПОЛНЕННУЮ колонку
    # (а не первую): иначе «План на текущую дату» берётся из разрежённого
    # дубля «Дата выдачи … по  Договору» (двойной пробел) и сильно занижается.
    df = _rd_plan_keep_most_filled_dupe_columns(df)

    def _pick(cols):
        for c in cols:
            if c in df.columns:
                return c
        return None

    def _pick_fuzzy(must_have: tuple[str, ...]):
        lows = tuple(str(w).lower() for w in must_have)
        best = None
        best_len = 10**9
        for c in df.columns:
            cl = str(c).strip().lower()
            if all(w in cl for w in lows):
                ln = len(cl)
                if ln < best_len:
                    best_len = ln
                    best = c
        return best

    proj_col = _pick(["project name", "Проект", "ID_проекта"])
    code_col = (
        _pick(["Шифр", "Шифр полный", "Шифр раздела", "section"]) or _pick_fuzzy(("шифр",))
    )
    name_col = (
        _pick([
            "Наименование  работ (разделов работ).",
            "Наименование работ (разделов работ).",
            "Наименование раздела",
            "Наименование",
        ])
        or _pick_fuzzy(("наименование", "раздел"))
        or _pick_fuzzy(("наименование",))
    )
    plan_col = (
        _pick(["Дата выдачи разделов по Договору", "Дата выдачи", "plan end"])
        or _pick_fuzzy(("дата", "выдачи", "договор"))
        or _pick_fuzzy(("дата", "выдачи"))
    )
    forecast_col = _pick([
        "Прогнозная дата выдачи разделов",
        "Прогнозная дата",
        "actual finish",
        "Выдан в Производство работ подрядчикам",
    ])
    status_col = _pick(["Статус РД", "Статус ПД", "Статус"])
    block_col = _pick(["Блок", "block"])
    contract_col = _pick(["№ Договора", "Договор"])

    if not (code_col and plan_col):
        return False

    # other_*_rd.csv/other_*_pd.csv накапливаются по снапшотам (concat в web_loader):
    # берём только последнюю выгрузку на проект, иначе «Всего разделов» = объединение
    # разделов всех выгрузок (например «Ленинский» — 241 вместо 198).
    df = _rd_plan_keep_latest_snapshot(df, proj_col)
    if df.empty:
        return False
    if name_col and name_col in df.columns:
        df[name_col] = df[name_col].map(_rd_plan_unglue_section_name)

    fb_k_shared = f"{source_key}_{doc_code}"

    if source_key == "rd_plan_data" and proj_col and code_col:
        try:
            df = _augment_df_with_tessa_rd(df, proj_col, code_col)
        except Exception:
            pass

    df["_plan_dt"] = pd.to_datetime(df[plan_col], errors="coerce", dayfirst=True, format="mixed")
    if "_tessa_production_dt" in df.columns and df["_tessa_production_dt"].notna().any():
        df["_fact_dt"] = pd.to_datetime(df["_tessa_production_dt"], errors="coerce")
    elif forecast_col:
        df["_fact_dt"] = pd.to_datetime(df[forecast_col], errors="coerce", dayfirst=True, format="mixed")
    else:
        df["_fact_dt"] = pd.NaT

    _is_delay_fb = "просрочка" in str(page_title or "").casefold()
    if not _is_delay_fb:
        st.subheader(f"План выдачи {doc_code}")

    if proj_col and proj_col in df.columns:
        try:
            projects = sorted({str(x).strip() for x in df[proj_col].dropna() if str(x).strip()})
        except Exception:
            projects = []
        if projects:
            sel, _ = project_filter_multiselect(
                st,
                projects,
                key=f"rd_fb_proj_{fb_k_shared}",
                label="Проекты",
            )
            if sel:
                df = df[df[proj_col].astype(str).str.strip().isin(sel)]

    df = _rd_plan_drop_footer_rows(
        df, code_col=code_col, name_col=name_col, status_col=status_col
    )
    # Как в _rd_plan_csv_sections_df: строки без валидного «Шифр» — не разделы
    # (пустые/«-»/«блок»/итоги). Иначе они схлопываются дедупом в фантомные
    # разделы и «Всего разделов» завышается (например «Ленинский» — 209 вместо 198).
    if code_col and code_col in df.columns:
        _cd_fb = df[code_col].fillna("").astype(str).str.strip()
        df = df[
            _cd_fb.ne("")
            & ~_cd_fb.str.lower().isin({"nan", "none", "-", "—", "блок"})
        ].copy()
    # RD-01: отменённые разделы не входят в план (как в _rd_plan_csv_sections_df).
    # По всем колонкам со «статус» (отмена бывает в «Статус», а не «Статус РД»).
    _canc_fb = _rd_plan_cancelled_row_mask(df)
    if bool(_canc_fb.any()):
        df = df[~_canc_fb].copy()
    if df.empty:
        st.info("Нет строк после фильтра.")
        return True

    _pc_fb = {
        "proj": proj_col,
        "code": code_col,
        "name": name_col,
        "plan": plan_col,
        "forecast": forecast_col,
        "status": status_col,
        "full_cipher": _pick(["Шифр полный", "InternalID", "Internal Id", "internalid"]),
    }
    df = _rd_plan_dedupe_sections_df(df, _pc_fb)
    if df.empty:
        st.info("Нет строк после фильтра.")
        return True

    fb_k = f"{fb_k_shared}_{page_title or 'doc'}"

    _detail_tbl_rd = pd.DataFrame()
    _tessa_loaded = False
    if source_key == "rd_plan_data":
        try:
            _td0 = st.session_state.get("tessa_data")
        except Exception:
            _td0 = None
        _tessa_loaded = _td0 is not None and not getattr(_td0, "empty", True)
        if _tessa_loaded:
            _sel_projects_fb = list(sel) if proj_col and sel else None
            _detail_tbl_rd = _build_rd_work_doc_detail_table(
                selected_projects=_sel_projects_fb,
                selected_section=None,
            )

    nm_s = (
        df[name_col].fillna("").astype(str).str.strip()
        if name_col and name_col in df.columns
        else pd.Series("", index=df.index)
    )
    cd_s = df[code_col].fillna("").astype(str).str.strip()
    nm_s = nm_s.where(~nm_s.str.lower().isin({"nan", "none"}), "")
    cd_s = cd_s.where(~cd_s.str.lower().isin({"nan", "none", "-", "—"}), "")
    _sec_lbl = (cd_s + " " + nm_s).str.replace(r"\s+", " ", regex=True).str.strip()
    _sec_lbl = _sec_lbl.mask(_sec_lbl.eq(""), "(не указано)")
    sec_opts = sorted(
        {str(v).strip() for v in _sec_lbl.tolist() if str(v).strip()},
        key=lambda x: x.casefold(),
    )

    stat_vals: list[str] = []
    _plan_status_labels: set[str] = set()
    if status_col and status_col in df.columns:
        _plan_status_labels = {
            str(v).strip()
            for v in _rd_plan_status_display_series(df[status_col]).dropna().tolist()
            if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
        }
    _tessa_status_labels: set[str] = set()
    _use_tessa_status_filter = (
        source_key == "rd_plan_data" and _tessa_loaded and not _detail_tbl_rd.empty
    )
    if _use_tessa_status_filter and "Статус" in _detail_tbl_rd.columns:
        _tessa_status_labels = {
            str(v).strip()
            for v in _detail_tbl_rd["Статус"].dropna().tolist()
            if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
        }
    # Статусы фильтра — из маппинга KrState (TESSA), а не сырые «Статус»/«Статус
    # РД» плана (там свободный текст «принят»/«не принят»/«на рассмотрении», нет в
    # маппинге). Если TESSA загружена — берём её метки, иначе fallback на план.
    if _use_tessa_status_filter and _tessa_status_labels:
        _src_status_labels = _tessa_status_labels
    else:
        _src_status_labels = _plan_status_labels | _tessa_status_labels
    stat_vals = sorted(
        {s for s in _src_status_labels if not _rd_status_is_excluded(s)},
        key=lambda x: x.casefold(),
    )
    if source_key == "rd_plan_data" and _RD_TESSA_STATUS_NOT_ISSUED not in stat_vals:
        if "Не выдан" in stat_vals:
            stat_vals = [s for s in stat_vals if s != "Не выдан"]
        stat_vals = sorted(
            stat_vals + [_RD_TESSA_STATUS_NOT_ISSUED], key=lambda x: x.casefold()
        )

    if st.button(
        "Сбросить фильтры",
        key=f"rd_fb_reset_{fb_k}",
        help="Вернуть все фильтры этой вкладки к значениям по умолчанию.",
    ):
        for _rk in (
            f"rd_fb_proj_{fb_k_shared}",
            f"rd_fb_sec_{fb_k_shared}",
            f"rd_fb_per_mode_{fb_k_shared}",
            f"rd_fb_dr_{fb_k_shared}",
            f"rd_fb_st_{fb_k_shared}",
            f"rd_fb_delay_view_{fb_k}",
            f"rd_fb_forecast_{fb_k}",
            f"rd_fb_delay_metric_{fb_k}",
            f"rd_fb_metric_{fb_k}",
        ):
            try:
                st.session_state.pop(_rk, None)
            except Exception:
                pass
        st.rerun()

    f2a, f2b, f2c = st.columns(3, gap="small")
    with f2a:
        sel_sec = st.multiselect(
            "Раздел",
            options=sec_opts,
            default=sec_opts,
            key=f"rd_fb_sec_{fb_k_shared}",
            placeholder="Все разделы",
            help="Подпись: шифр раздела и наименование через пробел.",
        )
    d_start = None
    d_end = None
    with f2b:
        dm = st.selectbox(
            "Период",
            ["Весь период (за всё время)", "Выбор диапазона дат"],
            index=0,
            key=f"rd_fb_per_mode_{fb_k_shared}",
        )
        _pv = df["_plan_dt"].dropna()
        if dm != "Весь период (за всё время)" and not _pv.empty:
            mn_d = _pv.min().date()
            mx_d = _pv.max().date()
            dr = st.date_input(
                "",
                value=(mn_d, mx_d),
                min_value=mn_d,
                max_value=mx_d,
                key=f"rd_fb_dr_{fb_k_shared}",
                format="DD.MM.YYYY",
                label_visibility="collapsed",
            )
            if isinstance(dr, tuple) and len(dr) == 2:
                d_start, d_end = dr[0], dr[1]
            else:
                d_start = d_end = dr
        elif dm != "Весь период (за всё время)" and _pv.empty:
            suppress_caption("Нет валидных плановых дат для фильтра периода.")
    with f2c:
        sel_st: list[str] = []
        if stat_vals:
            sel_st = st.multiselect(
                "Статус",
                options=stat_vals,
                default=stat_vals,
                key=f"rd_fb_st_{fb_k_shared}",
                placeholder="Все статусы",
            )
        else:
            suppress_caption("В источнике нет заполненной колонки статуса.")

    fb_metric_mode = "Количество разделов"
    fb_show_forecast = True
    fb_delay_view_mode = "По проекту"
    if source_key == "rd_plan_data":
        if _is_delay_fb:
            fb_delay_view_mode = st.selectbox(
                "Отображение",
                ["По проекту", "По разделу"],
                index=0,
                key=f"rd_fb_delay_view_{fb_k}",
            )
            fb_show_forecast = st.checkbox(
                "Показать прогнозную дату выдачи разделов",
                value=True,
                key=f"rd_fb_forecast_{fb_k}",
            )
            fb_metric_mode = st.radio(
                "Единица отображения",
                ["Количество разделов", "% от общего объёма"],
                horizontal=True,
                key=f"rd_fb_delay_metric_{fb_k}",
            )
        else:
            _fbm1, _fbm2 = st.columns(2, gap="small")
            with _fbm1:
                fb_metric_mode = st.radio(
                    "Единица отображения",
                    ["Количество разделов", "% от общего объёма"],
                    horizontal=True,
                    key=f"rd_fb_metric_{fb_k}",
                )
            with _fbm2:
                fb_show_forecast = st.checkbox(
                    "Показать прогнозную дату выдачи разделов",
                    value=True,
                    key=f"rd_fb_forecast_{fb_k}",
                )

    if sel_sec and sec_opts and set(sel_sec) != set(sec_opts):
        df = df[_sec_lbl.isin(sel_sec)].copy()

    if (
        d_start is not None
        and d_end is not None
        and dm != "Весь период (за всё время)"
    ):
        _pn = df["_plan_dt"].dt.normalize().dt.date
        df = df[df["_plan_dt"].notna() & (_pn >= d_start) & (_pn <= d_end)].copy()

    if sel_st and stat_vals and set(sel_st) != set(stat_vals):
        _sel_st_expanded = _rd_status_filter_expand(sel_st)
        if _use_tessa_status_filter and "Статус" in _detail_tbl_rd.columns:
            # Фильтр и легенда используют один словарь статусов («как на круговой»):
            # фильтруем детальную таблицу по её «Статус», затем ограничиваем план df
            # разделами из отфильтрованной детали.
            _detail_tbl_rd = _detail_tbl_rd[
                _detail_tbl_rd["Статус"]
                .map(lambda x: _rd_status_label_matches_filter(x, _sel_st_expanded))
                .fillna(False)
            ].copy()
            df = _rd_plan_df_filter_by_detail(
                df,
                _detail_tbl_rd,
                proj_col,
                code_col,
                name_col,
                _pc_fb.get("full_cipher"),
            )
        elif status_col and status_col in df.columns:
            _st_lbl = _rd_plan_status_display_series(df[status_col]).astype(str).str.strip()
            _mask = _st_lbl.map(lambda x: _rd_status_label_matches_filter(x, _sel_st_expanded))
            _sel_not_issued = bool(
                {"Не выдан", _RD_TESSA_STATUS_NOT_ISSUED} & set(sel_st)
            )
            if _sel_not_issued:
                _sel_proj = list(sel) if proj_col and sel else None
                _internal_ids = _rd_plan_tessa_internal_ids(_sel_proj)
                _fc_col = _pc_fb.get("full_cipher")
                if _fc_col and _fc_col in df.columns:
                    _fc_s = df[_fc_col].map(_rd_csv_cell_str).str.casefold()
                    _nv = _fc_s.eq("") | ~_fc_s.isin({x.casefold() for x in _internal_ids})
                elif "_tessa_production_dt" in df.columns:
                    _nv = df["_tessa_production_dt"].isna()
                else:
                    _nv = df["_fact_dt"].isna()
                if set(sel_st) <= {"Не выдан", _RD_TESSA_STATUS_NOT_ISSUED}:
                    _mask = _nv.fillna(False)
                else:
                    _mask = _mask | _nv.fillna(False)
            df = df[_mask].copy()

    if df.empty and (_detail_tbl_rd.empty if _use_tessa_status_filter else True):
        st.info("Нет строк после фильтра.")
        return True

    def _safe_str(series_or_default) -> pd.Series:
        if isinstance(series_or_default, pd.Series):
            s = series_or_default
        else:
            s = pd.Series([series_or_default] * len(df), index=df.index)
        s = s.where(s.notna(), "")
        s = s.astype(str).str.strip()
        s = s.replace({"nan": "", "None": "", "<NA>": "", "NaT": ""})
        return s

    _status_label = f"Статус {doc_code}"

    qty_col = _pick(
        [
            "Количество разделов по Договору",
            "Количество разделов РД по Договору",
            "Количество разделов РД",
        ]
    )
    try:
        if qty_col and qty_col in df.columns:
            df["_rd_plan_n"] = pd.to_numeric(df[qty_col], errors="coerce").fillna(1.0)
        else:
            df["_rd_plan_n"] = 1.0
    except Exception:
        df["_rd_plan_n"] = 1.0
    df["_rd_plan_n"] = df["_rd_plan_n"].clip(lower=0.0)
    df.loc[df["_rd_plan_n"].eq(0) | df["_rd_plan_n"].isna(), "_rd_plan_n"] = 1.0

    _sec_allow: set[str] | None = None
    if sel_sec and sec_opts and set(sel_sec) != set(sec_opts):
        _sec_allow = {str(x).strip() for x in sel_sec}

    if not _detail_tbl_rd.empty and _sec_allow is not None:
        _lbl_d = (
            _detail_tbl_rd["Шифр"].fillna("").astype(str).str.strip()
            + " "
            + _detail_tbl_rd["Наименование разделов работ"]
            .fillna("")
            .astype(str)
            .str.strip()
        ).str.replace(r"\s+", " ", regex=True).str.strip()
        _detail_tbl_rd = _detail_tbl_rd.loc[_lbl_d.isin(_sec_allow)].reset_index(drop=True)

    if source_key == "rd_plan_data" and not _detail_tbl_rd.empty:
        _detail_tbl_rd = _rd_plan_detail_filter_by_plan(
            df,
            _detail_tbl_rd,
            proj_col,
            code_col,
            name_col,
            _pc_fb.get("full_cipher"),
        )

    use_tessa_detail = source_key == "rd_plan_data" and not _detail_tbl_rd.empty
    _plan_sec_n = int(len(df))

    if use_tessa_detail:
        total_sections = _plan_sec_n
        overdue, avg_delay = _rd_delay_section_overdue_kpis(_detail_tbl_rd)
        detail_rows = _detail_tbl_rd.copy()
    else:
        detail_rows = pd.DataFrame(
            {
                "№ п/п": _safe_str(df["№ п/п"]) if "№ п/п" in df.columns else _safe_str(""),
                "Шифр": _safe_str(df[code_col]) if code_col else _safe_str(""),
                "Наименование": _safe_str(df[name_col]) if name_col else _safe_str(""),
                "Блок": (
                    _safe_str(df[block_col])
                    if block_col and block_col in df.columns
                    else _safe_str("")
                ),
                "№ Договора": (
                    _safe_str(df[contract_col])
                    if contract_col and contract_col in df.columns
                    else _safe_str("")
                ),
                "План выдачи (по Договору)": df["_plan_dt"].dt.strftime("%d.%m.%Y").fillna(
                    "—"
                ),
                "Прогноз/Факт выдачи": df["_fact_dt"].dt.strftime("%d.%m.%Y").fillna("—"),
                # По ТЗ просрочка отрицательная: дата по договору − прогноз/факт.
                "Отклонение, дн.": (df["_plan_dt"] - df["_fact_dt"]).dt.days,
                _status_label: (
                    _rd_plan_status_display_series(df[status_col]).fillna("").astype(str)
                    if status_col and status_col in df.columns
                    else _safe_str("")
                ),
            }
        )

        if proj_col and proj_col in df.columns:
            detail_rows.insert(0, "Проект", _safe_str(df[proj_col]).to_numpy())

        total_sections = int(len(detail_rows))
        delta_num = pd.to_numeric(detail_rows["Отклонение, дн."], errors="coerce")
        overdue = int((delta_num < 0).sum())
        avg_delay = float(delta_num[delta_num < 0].abs().mean()) if overdue > 0 else 0.0

    try:
        full_cipher_fb = _pick(["Шифр полный", "InternalID", "Internal Id", "internalid"])
        if (
            source_key == "rd_plan_data"
            and _tessa_loaded
            and proj_col
            and proj_col in df.columns
            and code_col
            and not _detail_tbl_rd.empty
        ):
            df["_bucket"] = _rd_plan_map_buckets_from_detail(
                df,
                _detail_tbl_rd,
                proj_col=proj_col,
                code_col=code_col,
                name_col=name_col,
                full_cipher_col=full_cipher_fb,
            )
        else:
            df["_bucket"] = pd.Series(pd.NA, index=df.index, dtype="object")
        df["_rd_fact_n"] = np.where(
            (
                df["_bucket"].notna()
                & df["_bucket"].isin(["Принято", "Передано подрядчику"])
            )
            | (
                df["_bucket"].isna()
                & (
                    df["_tessa_production_dt"].notna()
                    if "_tessa_production_dt" in df.columns
                    else df["_fact_dt"].notna()
                )
            ),
            df["_rd_plan_n"],
            0.0,
        )
    except Exception:
        df["_rd_fact_n"] = 0.0

    m1, m2, m3 = st.columns(3, gap="small")
    m1.metric("Всего разделов", f"{total_sections}")
    m2.metric("С отклонением (дн. < 0)", f"{overdue}")
    m3.metric("Ср. задержка, дн.", f"{avg_delay:.1f}" if overdue > 0 else "0")

    _pie_sec_allow: set[str] | None = _sec_allow
    if (
        code_col
        and name_col
        and code_col in df.columns
        and name_col in df.columns
        and not df.empty
    ):
        _pie_lbl = (
            df[code_col].fillna("").astype(str).str.strip()
            + " "
            + df[name_col].fillna("").astype(str).str.strip()
        ).str.replace(r"\s+", " ", regex=True).str.strip()
        _pie_sec_allow = {
            str(x).strip() for x in _pie_lbl.tolist() if str(x).strip()
        }

    if _is_delay_fb:
        if use_tessa_detail and not _detail_tbl_rd.empty:
            _render_rd_delay_fallback_chart(
                _detail_tbl_rd,
                view_mode=fb_delay_view_mode,
                doc_code=doc_code,
                metric_mode=fb_metric_mode,
                show_forecast=fb_show_forecast,
                plan_sec_df=df,
                plan_proj_col=proj_col,
            )
            try:
                month_df_fb = df[df["_plan_dt"].notna()].copy()
                if (
                    not month_df_fb.empty
                    and "_rd_plan_n" in month_df_fb.columns
                    and "_rd_fact_n" in month_df_fb.columns
                ):
                    month_df_fb["_plan_end_dt"] = month_df_fb["_plan_dt"]
                    monthly_fb = _rd_monthly_sections_aggregate(month_df_fb)
                    if not monthly_fb.empty:
                        _render_rd_monthly_overlay_chart(
                            monthly_fb,
                            metric_mode=fb_metric_mode,
                            orientation="h",
                            subheader=(
                                "Динамика по месяцам (% по плану)"
                                if str(fb_metric_mode).strip().startswith("%")
                                else "Динамика по месяцам"
                            ),
                            chart_key=f"rdfb_delay_months_{fb_k}",
                            caption_parts=("Выдача рабочей документации", "по месяцам"),
                            cumulative=not str(fb_metric_mode).strip().startswith("%"),
                        )
            except Exception:
                pass
        else:
            st.info(
                "Для графика просрочки нужны карточки TESSA (`tessa_*_rd.csv`) "
                "с датами по договору и фактом выдачи."
            )

    if source_key == "rd_plan_data" and not _is_delay_fb:
        try:
            _pie_fb: dict[str, int] = {}
            _pie_caption_fb = ""
            _pie_color_map_fb: dict[str, str] = {}
            _pie_skip_sanitize = False
            _full_cipher_pie = _pick(
                ["Шифр полный", "InternalID", "Internal Id", "internalid"]
            )
            # Исполнение РД: 100% = разделы other_*_rd.csv; доли из Status
            # tessa_*_rd.csv (три значения); «Не выдано» = остаток.
            _tz_counts = (
                _count_rd_pie_tz(list(sel) if proj_col and sel else None)
                if _tessa_loaded
                else {}
            )
            _tz_sum = sum(int(v) for v in _tz_counts.values())
            if source_key == "rd_plan_data" and _tz_sum > 0:
                _total_units = _plan_sec_n if _plan_sec_n > 0 else max(int(len(df)), 1)
                _tz_capped = dict(_tz_counts)
                if _tz_sum > _total_units > 0:
                    _sc = float(_total_units) / float(_tz_sum)
                    _tz_capped = {
                        k: max(int(round(float(v) * _sc)), 0)
                        for k, v in _tz_counts.items()
                    }
                _not_issued_tz = max(
                    _total_units - sum(int(v) for v in _tz_capped.values()), 0
                )
                _pie_fb = {k: int(v) for k, v in _tz_capped.items() if int(v) > 0}
                if _not_issued_tz > 0:
                    _pie_fb[_RD_TESSA_STATUS_NOT_ISSUED] = _not_issued_tz
                _pie_color_map_fb = {
                    _RD_TESSA_STATUS_PRODUCTION: "#27AE60",
                    _RD_TESSA_STATUS_REVIEW: "#F1C40F",
                    _RD_TESSA_STATUS_REWORK: "#C0392B",
                    _RD_TESSA_STATUS_NOT_ISSUED: "#F5A9C0",
                }
                _pie_caption_fb = (
                    "Исполнение РД: статусы из tessa_*_rd.csv (поле Status) — "
                    "«Выдано в производство работ», «На рассмотрении у ГИП», "
                    "«Возвращено на доработку»; «Не выдано» = разделы "
                    "other_*_rd.csv минус эти три категории."
                )
                _pie_skip_sanitize = True
            elif status_col and status_col in df.columns and not df.empty:
                _pie_status_s = _rd_plan_pie_status_series(
                    df,
                    status_col=status_col,
                    detail_tbl=_detail_tbl_rd,
                    proj_col=proj_col,
                    code_col=code_col,
                    name_col=name_col,
                    full_cipher_col=_full_cipher_pie,
                )
                _pie_fb = _rd_plan_pie_from_status_series(_pie_status_s)
                _pie_caption_fb = (
                    "Доли разделов по статусу — те же названия, что в фильтре «Статус»."
                )
                _pie_color_map_fb = _rd_plan_pie_color_map(list(_pie_fb.keys()))
            elif _tessa_loaded:
                _pie_fb = _rd_plan_pie_from_section_df(df)
                _mapped = (
                    int(df["_bucket"].notna().sum())
                    if "_bucket" in df.columns
                    else 0
                )
                if _mapped < max(int(len(df) * 0.05), 1) and len(df) > 0:
                    _pie_fb = {}
                    _total_units = _plan_sec_n if _plan_sec_n > 0 else max(int(len(df)), 1)
                    _not_issued_csv = 0
                    if "_bucket" in df.columns:
                        _not_issued_csv = int(
                            (df["_bucket"].astype(str).str.strip() == "Не выдано").sum()
                        )
                    elif not _detail_tbl_rd.empty and "Статус" in _detail_tbl_rd.columns:
                        _not_issued_csv = int(
                            _detail_tbl_rd["Статус"]
                            .astype(str)
                            .str.strip()
                            .str.casefold()
                            .isin({"не выдан", "не выдано"})
                            .sum()
                        )
                    _stage_fb = _count_tessa_rd_stages(
                        list(sel) if proj_col and sel else None,
                        section_labels_allowlist=_pie_sec_allow,
                    )
                    _stage_fb_any = any(int(v) > 0 for v in _stage_fb.values())
                    if _stage_fb_any:
                        _tessa_target = max(_total_units - _not_issued_csv, 0)
                        _active_fb = sum(int(v) for v in _stage_fb.values())
                        if _active_fb > _tessa_target > 0:
                            _sc = float(_tessa_target) / float(_active_fb)
                            _stage_fb = {
                                k: max(int(round(float(v) * _sc)), 0)
                                for k, v in _stage_fb.items()
                            }
                        _not_issued_fb = max(
                            _total_units - sum(int(v) for v in _stage_fb.values()), 0
                        )
                        _pie_fb = {k: int(v) for k, v in _stage_fb.items() if int(v) > 0}
                        if _not_issued_fb > 0:
                            _pie_fb["Не выдано"] = _not_issued_fb
                        _pie_caption_fb = (
                            "Стадии — по задачам TESSA (подписание проектировщиком/ГИП, "
                            "назначение подрядчика, отказ ГИП); «Не выдано» — разделы плана без карточки TESSA."
                        )
                        _pie_color_map_fb = {
                            "Передано заказчику": "#27AE60",
                            "Выдано в производство работ": "#2980B9",
                            "Выдано подрядчику": "#8E44AD",
                            "Отклонённая (на доработке)": "#C0392B",
                            "Не выдано": "#7F8C8D",
                        }
                    else:
                        _counts_fb = _count_tessa_rd_krstates(
                            list(sel) if proj_col and sel else None,
                            section_labels_allowlist=_pie_sec_allow,
                        )
                        _sum_parts = sum(int(v) for v in _counts_fb.values())
                        _tessa_target = max(_total_units - _not_issued_csv, 0)
                        if _sum_parts > _tessa_target > 0:
                            _scale = float(_tessa_target) / float(_sum_parts)
                            _counts_fb = {
                                k: max(int(round(float(v) * _scale)), 0)
                                for k, v in _counts_fb.items()
                            }
                        elif _sum_parts > _total_units > 0:
                            _scale = float(_total_units) / float(_sum_parts)
                            _counts_fb = {
                                k: max(int(round(float(v) * _scale)), 0)
                                for k, v in _counts_fb.items()
                            }
                        _not_issued_fb = max(
                            _total_units - sum(int(v) for v in _counts_fb.values()), 0
                        )
                        _pie_fb = {
                            k: int(v)
                            for k, v in {
                                "Принято": _counts_fb.get("Принято", 0),
                                "На рассм.": _counts_fb.get("На рассм.", 0),
                                "Возвр.": _counts_fb.get("Возвр.", 0),
                                "Не принято": _counts_fb.get("Не принято", 0),
                                "Передано подрядчику": _counts_fb.get("Передано подрядчику", 0),
                                "Не выдано": _not_issued_fb,
                            }.items()
                            if int(v) > 0
                        }
                        _pie_caption_fb = (
                            "Статусы Принято/На рассм./Возвр./Не принято — из TESSA (KrState); "
                            "«Не выдано» — разделы плана без карточки TESSA."
                        )
                        _pie_color_map_fb = {
                            "Принято": "#27AE60",
                            "На рассм.": "#F1C40F",
                            "Возвр.": "#E67E22",
                            "Не принято": "#C0392B",
                            "Передано подрядчику": "#8E44AD",
                            "Не выдано": "#7F8C8D",
                        }
                else:
                    _pie_caption_fb = (
                        "По строкам плана (1 раздел = 1 строка): статус из TESSA; "
                        "«Не выдано» — разделы other_*_rd.csv без карточки."
                    )
                    _pie_color_map_fb = {
                        "Принято": "#27AE60",
                        "На рассм.": "#F1C40F",
                        "Возвр.": "#E67E22",
                        "Не принято": "#C0392B",
                        "Передано подрядчику": "#8E44AD",
                        "Не выдано": "#7F8C8D",
                        "Передано заказчику": "#27AE60",
                        "Выдано в производство работ": "#2980B9",
                        "Выдано подрядчику": "#8E44AD",
                        "Отклонённая (на доработке)": "#C0392B",
                    }
            if not _pie_skip_sanitize:
                _pie_fb = _rd_plan_pie_sanitize(_pie_fb)
            if _pie_fb:
                if not _pie_color_map_fb:
                    _pie_color_map_fb = _rd_plan_pie_color_map(list(_pie_fb.keys()))
                st.subheader("Исполнение РД")
                suppress_caption(_pie_caption_fb)
                _nk_fb = len(_pie_fb)
                fig_pie_fb = px.pie(
                    values=list(_pie_fb.values()),
                    names=list(_pie_fb.keys()),
                    color=list(_pie_fb.keys()),
                    title=None,
                    color_discrete_map=_pie_color_map_fb,
                )
                fig_pie_fb = apply_standard_pie_layout(
                    fig_pie_fb,
                    height=960,
                    pct_fontsize=26 if _nk_fb <= 5 else 22,
                    text_show_value_and_percent=True,
                )
                fig_pie_fb.update_traces(
                    hovertemplate=(
                        "<b>%{label}</b><br>Значение: %{value}<br>Доля: %{percent}<br><extra></extra>"
                    ),
                )
                fig_pie_fb = apply_chart_background(fig_pie_fb)
                render_chart(
                    fig_pie_fb,
                    key=f"rdfb_pie_{fb_k}",
                    caption_below=report_chart_caption_body("Исполнение РД"),
                )
        except Exception:
            pass

        try:
            month_df_fb = df[df["_plan_dt"].notna()].copy()
            if (
                not month_df_fb.empty
                and "_rd_plan_n" in month_df_fb.columns
                and "_rd_fact_n" in month_df_fb.columns
            ):
                month_df_fb["_plan_end_dt"] = month_df_fb["_plan_dt"]
                monthly_fb = _rd_monthly_sections_aggregate(month_df_fb)
                if not monthly_fb.empty:
                    _render_rd_monthly_overlay_chart(
                        monthly_fb,
                        metric_mode=fb_metric_mode,
                        orientation="h",
                        subheader=(
                            "Динамика по месяцам (% по плану)"
                            if str(fb_metric_mode).strip().startswith("%")
                            else "Динамика по месяцам"
                        ),
                        chart_key=f"rdfb_months_{fb_k}",
                        caption_parts=("Выдача рабочей документации", "по месяцам"),
                        cumulative=not str(fb_metric_mode).strip().startswith("%"),
                    )
        except Exception:
            pass

    # Накопительная динамика по строкам CSV (аналог основного отчёта РД), если нет MSP-колонок.
    if source_key == "rd_plan_data" and not _is_delay_fb:
        try:
            if "_tessa_production_dt" in df.columns:
                df["_fact_dyn_dt"] = pd.to_datetime(
                    df["_tessa_production_dt"], errors="coerce"
                )
            else:
                df["_fact_dyn_dt"] = pd.NaT
            _dyn_parts: list[pd.DataFrame] = []
            _pm = df["_plan_dt"].notna()
            if _pm.any():
                _gp = df.loc[_pm].copy()
                # Помесячный шаг (правка ТЗ): подписи на накопительной кривой не
                # наслаиваются, т.к. точек на оси в разы меньше, чем при по-дневной.
                _gp["_dn"] = _gp["_plan_dt"].dt.to_period("M").dt.to_timestamp()
                _pg = _gp.groupby("_dn").size().reset_index(name="Количество")
                _pg.columns = ["Дата", "Количество"]
                _pg["Тип"] = "План"
                _dyn_parts.append(_pg)
            _fm = df["_fact_dyn_dt"].notna()
            if _fm.any():
                _gf = df.loc[_fm].copy()
                _gf["_dn"] = _gf["_fact_dyn_dt"].dt.to_period("M").dt.to_timestamp()
                _fg = _gf.groupby("_dn").size().reset_index(name="Количество")
                _fg.columns = ["Дата", "Количество"]
                _fg["Тип"] = "Факт"
                _dyn_parts.append(_fg)
            if _dyn_parts:
                dynamics_df = pd.concat(_dyn_parts, ignore_index=True)
                all_dates = pd.to_datetime(dynamics_df["Дата"], errors="coerce").dropna()
                if not all_dates.empty:
                    start_anchor = (all_dates.min() - pd.Timedelta(days=1)).normalize()
                    dynamics_df = pd.concat(
                        [
                            pd.DataFrame(
                                {
                                    "Дата": [start_anchor, start_anchor],
                                    "Количество": [0.0, 0.0],
                                    "Тип": ["План", "Факт"],
                                }
                            ),
                            dynamics_df,
                        ],
                        ignore_index=True,
                    )
                dynamics_df = dynamics_df.sort_values(["Тип", "Дата"])
                _pt_cap = float(len(df)) if len(df) > 0 else 0.0
                for _typ in dynamics_df["Тип"].unique():
                    _mk = dynamics_df["Тип"] == _typ
                    dynamics_df.loc[_mk, "Количество"] = dynamics_df.loc[
                        _mk, "Количество"
                    ].cumsum()
                if _pt_cap > 0:
                    _pl_m = dynamics_df["Тип"] == "План"
                    dynamics_df.loc[_pl_m, "Количество"] = dynamics_df.loc[
                        _pl_m, "Количество"
                    ].clip(upper=_pt_cap)
                    # ТЗ: синяя кривая «План» должна доходить до общего плана
                    # («Всего разделов» = other_*_rd.csv). Разделы без плановой
                    # даты не входят в накопление — добавляем остаток к последней
                    # плановой точке, чтобы кривая заканчивалась на общем плане.
                    if _pl_m.any():
                        _cur_pl_max = float(dynamics_df.loc[_pl_m, "Количество"].max())
                        if _cur_pl_max + 0.5 < _pt_cap:
                            _pidx_fb = pd.to_datetime(
                                dynamics_df.loc[_pl_m, "Дата"], errors="coerce"
                            ).idxmax()
                            dynamics_df.loc[_pidx_fb, "Количество"] = _pt_cap
                dynamics_df["Текст"] = dynamics_df["Количество"].apply(
                    lambda x: f"{float(x):.0f}" if pd.notna(x) and float(x) != 0.0 else ""
                )
                if str(page_title or "").strip() == "Рабочая документация":
                    st.subheader("Динамика выдачи РД")
                    _fb_msp_prod: Optional[dict[str, Any]] = None
                    try:
                        _today_fb = date.today()
                        _pl_fb = dynamics_df[dynamics_df["Тип"] == "План"].sort_values("Дата")
                        _fc_fb = dynamics_df[dynamics_df["Тип"] == "Факт"].sort_values("Дата")
                        _sel_proj_dyn = list(sel) if proj_col and sel else None
                        _rd_summ_fb = _compute_rd_exec_summary_from_csv_tessa(_sel_proj_dyn)
                        _pt_fb = _pt_cap if _pt_cap > 0 else (
                            float(_rd_summ_fb["plan_total"]) if _rd_summ_fb else 0.0
                        )
                        _pd_fb = 0.0
                        if not _pl_fb.empty:
                            _dtp_fb = pd.to_datetime(_pl_fb["Дата"])
                            _past_pl = _pl_fb[_dtp_fb.dt.date <= _today_fb]
                            _pd_fb = (
                                float(_past_pl["Количество"].iloc[-1])
                                if not _past_pl.empty
                                else 0.0
                            )
                        _fd_fb = 0.0
                        if not _fc_fb.empty:
                            _dtf_fb = pd.to_datetime(_fc_fb["Дата"])
                            _past_fc = _fc_fb[_dtf_fb.dt.date <= _today_fb]
                            _fd_fb = (
                                float(_past_fc["Количество"].iloc[-1])
                                if not _past_fc.empty
                                else 0.0
                            )
                        _pd_fb, _fd_fb, _dev_fb = _rd_kpi_plan_fact_deviation_today(
                            today=_today_fb,
                            csv_df=df,
                            plan_curve=_pd_fb,
                            fact_curve=_fd_fb,
                            rd_summ=_rd_summ_fb,
                        )
                        # RD-01/RD-02: «Факт на текущую дату» = «Выдано в
                        # производство работ» + «На рассмотрении у ГИП» из
                        # tessa_*_rd.csv (как в pie «Исполнение РД»), а НЕ по
                        # прогнозным датам CSV (иначе факт≠pie и завышен).
                        if _tessa_loaded:
                            _tz_fact_kpi = _count_rd_pie_tz(
                                list(sel) if proj_col and sel else None
                            )
                            _fd_tessa = float(
                                int(_tz_fact_kpi.get(_RD_TESSA_STATUS_PRODUCTION, 0))
                                + int(_tz_fact_kpi.get(_RD_TESSA_STATUS_REVIEW, 0))
                            )
                            if _fd_tessa > 0:
                                _fd_fb = _fd_tessa
                                _dev_fb = float(_pd_fb - _fd_fb)
                        _max_plan_fb = (
                            df["_plan_dt"].max().date()
                            if df["_plan_dt"].notna().any()
                            else None
                        )
                        _min_plan_fb = (
                            df["_plan_dt"].min().date()
                            if df["_plan_dt"].notna().any()
                            else None
                        )
                        _max_fact_fb = (
                            df["_fact_dt"].max().date()
                            if df["_fact_dt"].notna().any()
                            else None
                        )
                        _last_pl_fb = _pl_fb["Дата"].max() if not _pl_fb.empty else None
                        _ld_fb = (
                            pd.Timestamp(_last_pl_fb).date()
                            if _last_pl_fb is not None
                            else _today_fb
                        )
                        _fb_msp_prod = {
                            "plan_to_date": _pd_fb,
                            "fact_to_date": _fd_fb,
                            "deviation_to_date": _dev_fb,
                            "fact_to_date_msp": _fd_fb,
                            "max_plan_end_date": _max_plan_fb,
                            "min_plan_start_date": _min_plan_fb,
                            "plan_total": _pt_fb,
                            "max_fact_end_date": _max_fact_fb,
                            "last_plan_date": _ld_fb,
                        }
                        _rd_kpi_box_fb = st.container(key="rd_exec_summary_kpi_fb")
                        with _rd_kpi_box_fb:
                            _kc1, _kc2, _kc3, _kc4 = st.columns(4, gap="small")
                            with _kc1:
                                st.metric("План по проекту", _fmt_rd_whole_metric(_pt_fb))
                            with _kc2:
                                st.metric("План на текущую дату", _fmt_rd_whole_metric(_pd_fb))
                            with _kc3:
                                st.metric("Факт на текущую дату", _fmt_rd_whole_metric(_fd_fb))
                            with _kc4:
                                _render_rd_deviation_metric(
                                    "Отклонение на текущую дату",
                                    _dev_fb,
                                )
                            try:
                                _render_rd_weekly_productivity_kpis(
                                    list(sel) if proj_col and sel else None,
                                    msp_fallback=_fb_msp_prod,
                                )
                            except Exception as _e_prod_fb:
                                suppress_caption(
                                    f"Производительность разделов в неделю: {_e_prod_fb}"
                                )
                    except Exception:
                        _fb_msp_prod = None
                fig_fb = px.line(
                    dynamics_df,
                    x="Дата",
                    y="Количество",
                    color="Тип",
                    title=None,
                    markers=True,
                    labels={"Количество": "Количество разделов", "Дата": "Дата"},
                    text="Текст",
                    color_discrete_map={"План": "#2E86AB", "Факт": "#F39C12"},
                )
                _rd_tickvals, _rd_ticktext = _rd_dynamics_chart_month_ticks_ru(dynamics_df["Дата"])
                fig_fb.update_layout(
                    xaxis_title="Дата (Старт План)",
                    yaxis_title="Количество",
                    hovermode="x unified",
                    height=550,
                    xaxis=dict(
                        tickmode="array",
                        tickvals=_rd_tickvals,
                        ticktext=_rd_ticktext,
                        tickangle=-45,
                        tickfont=dict(size=10),
                    ),
                    yaxis=dict(rangemode="tozero"),
                    legend=standard_chart_legend(),
                )
                fig_fb.update_traces(
                    line=dict(width=2),
                    marker=dict(size=6),
                    mode="lines+markers+text",
                    textposition="top center",
                    textfont=dict(size=20, color="white"),
                )
                _apply_rd_dynamics_line_chart_theme(fig_fb)
                fig_fb.for_each_trace(
                    lambda t: t.update(
                        name=(
                            "План (РД по Договору)"
                            if str(t.name) == "План"
                            else (
                                "Факт (Выдано в производство работ)"
                                if str(t.name) == "Факт"
                                else t.name
                            )
                        )
                    )
                )
                fig_fb = apply_chart_background(fig_fb)
                if str(page_title or "").strip() != "Рабочая документация":
                    st.subheader("Динамика выдачи РД")
                render_chart(
                    fig_fb,
                    key=f"rdfb_dyn_{fb_k}",
                    caption_below=report_chart_caption_body("Динамика выдачи РД"),
                )
        except Exception:
            pass

    detail_show = _rd_detail_prepare_for_display(
        detail_rows.copy(), show_forecast=fb_show_forecast
    )
    if use_tessa_detail:
        pass
    else:
        detail_show["Отклонение, дн."] = delta_num.apply(
            lambda x: ("+" + str(int(x))) if pd.notna(x) and x > 0 else (str(int(x)) if pd.notna(x) else "—")
        )

        drop_cols = [
            c
            for c in ("№ п/п", "Блок", "№ Договора", _status_label)
            if c in detail_show.columns and (detail_show[c].astype(str).str.strip() == "").all()
        ]
        if drop_cols:
            detail_show = detail_show.drop(columns=drop_cols)

    detail_show = _drop_rd_detail_empty_rows(detail_show)

    def _rd_detail_cell_display(val) -> str:
        if val is None:
            return "—"
        try:
            if pd.isna(val):
                return "—"
        except (TypeError, ValueError):
            pass
        if isinstance(val, (pd.Timestamp,)):
            return val.strftime("%d.%m.%Y")
        s = str(val).strip()
        if not s or s.lower() in ("nan", "none", "<na>", "nat"):
            return "—"
        return s

    for c in detail_show.columns:
        detail_show[c] = detail_show[c].map(_rd_detail_cell_display)

    st.subheader("Детальная таблица")
    if use_tessa_detail:
        _render_styled_table_report(
            style_dataframe_for_dark_theme(
                detail_show,
                days_column="Отклонение от даты по договору",
                extra_days_columns=("Отклонение от прогнозной даты",),
                days_deviation_gradient=True,
                # ТЗ: < 0 — красный (с «−»), ≥ 0 — зелёный.
                days_positive_is_ahead=True,
            ),
            detail_show,
            file_stem="rd_fb_detail",
            key_prefix=f"rdfb_detail_{fb_k}",
            full_width=True,
        )
    else:
        _render_html_table(
            detail_show,
            scroll=True,
            colored_dev_columns=(
                {
                    "Отклонение от даты по договору, дн",
                    "Отклонение от прогнозной даты, дн",
                }
                if use_tessa_detail
                else None
            ),
        )
    return True


# ==================== DASHBOARD 8.6: RD Delay Chart ====================
def dashboard_rd_delay(df, is_pd: bool = False):
    # R23-07 (стр.19): в контексте ПД все видимые лейблы используют «ПД».
    doc_code = "ПД" if is_pd else "РД"
    # st.subheader(f"⏱️ Просрочка выдачи {doc_code}")
    st.subheader(f"Просрочка выдачи {doc_code}")

    _pd_masks_delay = _pd_section_masks(df) if is_pd else None

    # Find column names (they might have different formats)
    # Try to find columns by partial name matching
    def find_column(df, possible_names):
        """Find column by possible names"""
        for col in df.columns:
            # Normalize column name: remove newlines, extra spaces, normalize case
            col_normalized = str(col).replace("\n", " ").replace("\r", " ").strip()
            col_lower = col_normalized.lower()

            for name in possible_names:
                name_lower = name.lower().strip()
                # Exact match (case insensitive)
                if name_lower == col_lower:
                    return col
                # Substring match
                if name_lower in col_lower or col_lower in name_lower:
                    return col
                # Check if all key words from name are in column
                name_words = [w for w in name_lower.split() if len(w) > 2]
                if name_words and all(word in col_lower for word in name_words):
                    return col

        # Special handling for RD count column with key words
        if any(
            "разделов" in n.lower() and "рд" in n.lower() and "договор" in n.lower()
            for n in possible_names
        ):
            for col in df.columns:
                col_lower = str(col).lower().replace("\n", " ").replace("\r", " ")
                key_words = ["разделов", "рд", "договор", "количество"]
                if all(word in col_lower for word in key_words if len(word) > 3):
                    return col

        return None

    # Find required columns
    # Имя колонки в CSV может быть «Отклонение разделов РД» (также для ПД-MSP — как есть).
    _rd_dev_csv_name = "Отклонение разделов " + "РД"
    rd_deviation_col = None

    if _rd_dev_csv_name in df.columns:
        rd_deviation_col = _rd_dev_csv_name
    else:
        rd_deviation_col = find_column(
            df,
            [
                _rd_dev_csv_name,
                "Отклонение разделов рд",
                "отклонение разделов рд",
                "Отклон. Количества разделов РД",
                "Отклонение количества разделов РД",
                "Отклон. разделов РД",
                _rd_dev_csv_name + " по Договору",
            ],
        )

        # Special handling: if not found, try to find by key words
        if not rd_deviation_col:
            for col in df.columns:
                col_lower = str(col).lower().replace("\n", " ").replace("\r", " ")
                key_words = ["отклон", "раздел", "рд"]
                if all(word in col_lower for word in key_words if len(word) > 3):
                    rd_deviation_col = col
                    break

    # Видимый лейбл в графиках/таблицах/легендах: "Отклонение разделов ПД" или dev_col.
    dev_col = f"Отклонение разделов {doc_code}"

    _rd_delay_use_synthetic = False
    if not rd_deviation_col:
        if is_pd:
            _rd_delay_use_synthetic = True
            rd_deviation_col = "_rd_delay_dev_synth"
        else:
            _src_key = "pd_plan_data" if is_pd else "rd_plan_data"
            if _rd_plan_fallback_view(page_title=f"Просрочка выдачи {doc_code}", doc_code=doc_code, source_key=_src_key):
                return
            st.warning(f"⚠️ Колонка 'Отклонение разделов {doc_code}' не найдена.")
            return

    # Find required columns
    plan_start_col = (
        "plan start"
        if "plan start" in df.columns
        else find_column(df, ["Старт План", "План Старт"])
    )
    project_col = (
        "project name"
        if "project name" in df.columns
        else find_column(df, ["Проект", "project"])
    )
    section_col = (
        "section" if "section" in df.columns else find_column(df, ["Раздел", "section"])
    )
    task_col = (
        "task name"
        if "task name" in df.columns
        else find_column(df, ["Задача", "task"])
    )
    rd_plan_col = find_column(df, ["РД по Договору", "РД по договору", "Количество разделов РД по Договору"])
    rd_fact_col = find_column(
        df,
        [
            "Выдано в производство работ",
            "Разработано",
            "В работе",
            "Выдана подрядчику",
            "Всего загружено",
            "выдано в производство",
        ],
    )
    plan_end_col = "plan end" if "plan end" in df.columns else find_column(df, ["Конец План", "План Конец", "План окончания ПД/РД"])
    actual_finish_col = (
        "actual finish"
        if "actual finish" in df.columns
        else find_column(
            df,
            ["actual finish", "Фактическое окончание", "Окончание факт", "Факт окончание"],
        )
    )
    fact_end_col = (
        actual_finish_col
        if actual_finish_col and actual_finish_col in df.columns
        else (
            "base end"
            if "base end" in df.columns
            else find_column(df, ["Конец Факт", "Факт Конец", "Факт окончания ПД/РД"])
        )
    )

    on_approval_col_rd = find_column(df, ["На согласовании", "согласовании"])
    in_production_col_rd = find_column(
        df,
        [
            "Выдано в производство работ",
            "Разработано",
            "В работе",
            "производство работ",
            "в производство",
        ],
    )
    contractor_transfer_col_rd = find_column(
        df,
        [
            "Выдана подрядчику",
            "Передано подрядчику",
            "подрядчику",
            "TransferToCustomer",
        ],
    )
    rework_col_rd = find_column(df, ["На доработке", "доработке"])

    if not is_pd:
        _cipher_enrich_col = find_column(
            df,
            [
                "abbreviation",
                "Шифр_ПД_и_РД",
                "Шифр ПД и РД",
                "Шифр ПД/РД",
                "Шифр раздела",
                "Шифр",
                "DivisionCipher",
            ],
        )
        if project_col and _cipher_enrich_col and _cipher_enrich_col in df.columns:
            try:
                df = _augment_df_with_tessa_rd(df, project_col, _cipher_enrich_col)
            except Exception:
                pass

    # Check if required columns exist (section optional — заменён фильтром по виду документации)
    missing_cols = []
    if not project_col or project_col not in df.columns:
        missing_cols.append("Проект (project name)")
    if not task_col or task_col not in df.columns:
        missing_cols.append("Задача (task name)")

    if missing_cols:
        _src_key = "pd_plan_data" if is_pd else "rd_plan_data"
        if _rd_plan_fallback_view(page_title=f"Просрочка выдачи {doc_code}", doc_code=doc_code, source_key=_src_key):
            return
        st.warning(f"⚠️ Отсутствуют необходимые колонки: {', '.join(missing_cols)}")
        st.info("Пожалуйста, убедитесь, что файл содержит все необходимые колонки.")
        return

    if is_pd:
        try:
            _pd_snap_all = st.session_state.get("project_data_all_snapshots")
        except Exception:
            _pd_snap_all = None
        if _pd_snap_all is not None and not getattr(_pd_snap_all, "empty", True):
            df = _pd_snap_all.copy()
    if project_col and project_col in df.columns:
        df = _project_column_apply_canonical(df, project_col)
    if is_pd:
        df = _pd_dedupe_msp_tasks_latest(df)
        _pd_masks_delay = _pd_section_masks(df)

    def _to_numeric_series(series):
        return pd.to_numeric(
            series.astype(str)
            .str.replace(" ", "", regex=False)
            .str.replace(",", ".", regex=False),
            errors="coerce",
        ).fillna(0.0)

    def _to_datetime_series(series):
        return pd.to_datetime(series.astype(str), errors="coerce", dayfirst=True, format="mixed")

    # Add filters (развёрнуты по умолчанию — как на экранах «как было»).
    # panel_key _v2 — сброс старого session_state свёрнутого expander.
    with filters_panel(
        st,
        panel_key=f"rd_delay_{doc_code}_v2",
        reset_keys=["rd_delay_"],
        expanded=True,
    ):
        filter_col1, filter_col2, filter_col3 = st.columns(3, gap="small")

        # Project filter (несколько проектов)
        selected_projects: list[str] = []
        with filter_col1:
            try:
                projects = _unique_project_labels_for_select(df[project_col])
                selected_projects, _ = project_filter_multiselect(st, projects,
                    key="rd_delay_projects",
                )
            except Exception as e:
                st.error(f"Ошибка при загрузке списка проектов: {str(e)}")
                return

        # R23-07/TESSA: ключ MSP-разделов — колонка «Шифр_ПД_и_РД» / «Шифр».
        # По ней делаем join с TESSA (DivisionCipher, в рамках проекта) и строим
        # фильтр «Шифр + Наименование раздела» из MSP (Шифр + section_col/task_col).
        _msp_cipher_col = find_column(
            df,
            [
                "abbreviation",
                "Шифр_ПД_и_РД",
                "Шифр ПД и РД",
                "Шифр ПД/РД",
                "Шифр ПД РД",
                "Шифр раздела",
                "Шифр",
                "DivisionCipher",
                "Cipher",
            ],
        )
        if is_pd and (
            not _msp_cipher_col
            or _msp_cipher_col not in df.columns
            or _msp_cipher_col == section_col
        ):
            _pd_cc_delay, _ = _pd_cipher_filled_mask(df)
            if _pd_cc_delay and _pd_cc_delay in df.columns:
                _msp_cipher_col = _pd_cc_delay
            elif _pd_masks_delay and _pd_masks_delay.get("cipher_col"):
                _pd_cc2 = _pd_masks_delay["cipher_col"]
                if _pd_cc2 and _pd_cc2 in df.columns:
                    _msp_cipher_col = _pd_cc2
        # Наименование раздела: MSP "Наименование разделов работ" / section_col / task_col.
        _msp_section_name_col = find_column(
            df, ["Наименование разделов работ", "Наименование раздела", "Раздел"]
        )
        _msp_name_col_for_label = (
            _msp_section_name_col
            if _msp_section_name_col and _msp_section_name_col in df.columns
            else (section_col if section_col and section_col in df.columns else task_col)
        )
        # R23-07: «иной путь». В текущих MSP-файлах РД-шифры не задаются (только ПД: АР/КР/ПЗ…),
        # а в TESSA — только РД (АС/КЖ/КМ…). Прямой join MSP↔TESSA по (Проект, Шифр) не даёт
        # совпадений → колонки «Задача»/«Шифр» оставались пустыми, а попутные обращения к
        # TESSA могли ронять построение графика. Поэтому для «Просрочки выдачи РД/ПД»
        # берём всё из MSP, а TESSA-карточки используются в отдельных отчётах
        # («Исполнение РД», круговая статусов) там, где они применимы.

        rd_delay_view_mode = "По проекту"
        with filter_col2:
            rd_delay_view_mode = st.selectbox(
                "Отображение",
                ["По проекту", "По разделу"],
                index=0,
                key=f"rd_delay_view_mode_{doc_code}",
            )
        # Filter by RD section kind
        selected_section = "Все"
        with filter_col3:
            if _msp_cipher_col and _msp_cipher_col in df.columns:
                # R23-07 (стр.17/21): значения = «Шифр — Наименование раздела» из MSP.
                _sec_src_df = df
                if is_pd and _pd_masks_delay is not None:
                    _met_opt = _pd_delay_row_mask(df, _pd_masks_delay)
                    if bool(_met_opt.any()):
                        _sec_src_df = df.loc[_met_opt]
                _cip = _sec_src_df[_msp_cipher_col].astype(str).str.strip()
                _cip = _cip.where(~_cip.str.lower().isin({"nan", "none", "<na>"}), other="")
                if is_pd:
                    section_options = sorted(
                        {
                            v
                            for v in _cip.tolist()
                            if isinstance(v, str)
                            and v.strip()
                            and v.strip().lower() not in ("nan", "none", "<na>")
                        },
                        key=lambda x: x.casefold(),
                    )
                    _rd_sec_opts = ["Все"] + section_options
                    _sync_selectbox_session_state("rd_delay_section", _rd_sec_opts)
                    selected_section = st.selectbox(
                        "Вид раздела",
                        _rd_sec_opts,
                        key="rd_delay_section",
                    )
                else:
                    if _msp_name_col_for_label and _msp_name_col_for_label in _sec_src_df.columns:
                        _nm = _sec_src_df[_msp_name_col_for_label].astype(str).str.strip()
                        _nm = _nm.where(~_nm.str.lower().isin({"nan", "none", "<na>"}), other="")
                    else:
                        _nm = pd.Series([""] * len(_sec_src_df), index=_sec_src_df.index)
                    _combined = pd.Series([""] * len(_sec_src_df), index=_sec_src_df.index, dtype=object)
                    _both = _cip.ne("") & _nm.ne("")
                    _only_cip = _cip.ne("") & ~_both
                    _only_nm = _nm.ne("") & ~_both
                    _combined.loc[_both] = _cip[_both] + " — " + _nm[_both]
                    _combined.loc[_only_cip] = _cip[_only_cip]
                    _combined.loc[_only_nm] = _nm[_only_nm]
                    _combined = _combined.astype(str).replace(
                        {"nan": "", "None": "", "<NA>": "", "NaT": ""}
                    )
                    section_options = sorted(
                        {
                            v.strip()
                            for v in _combined.tolist()
                            if isinstance(v, str) and v.strip()
                        },
                        key=lambda x: x.casefold(),
                    )
                    selected_section = st.selectbox(
                        "Вид раздела",
                        ["Все"] + section_options,
                        key="rd_delay_section",
                    )
                    _full_combined = pd.Series([""] * len(df), index=df.index, dtype=object)
                    _full_combined.loc[_combined.index] = _combined
                    df["_tessa_section_label"] = _full_combined
            elif (not is_pd) and section_col and section_col in df.columns:
                section_options = sorted(
                    {
                        str(v).strip()
                        for v in df[section_col].dropna().tolist()
                        if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
                    },
                    key=lambda x: x.casefold(),
                )
                selected_section = st.selectbox(
                    "Вид раздела",
                    ["Все"] + section_options,
                    key="rd_delay_section",
                )
            else:
                suppress_caption("Колонка раздела ПД не найдена." if is_pd else "Колонка раздела РД не найдена.")

        selected_statuses_rd: list[str] = []
        rd_status_options_rd: list[str] = []
        if on_approval_col_rd and on_approval_col_rd in df.columns:
            rd_status_options_rd.append("На согласовании")
        if not is_pd and (
            ("_tessa_production_dt" in df.columns and df["_tessa_production_dt"].notna().any())
            or (in_production_col_rd and in_production_col_rd in df.columns)
            or _rd_has_tessa_production_dates()
        ):
            rd_status_options_rd.append("Выдано в производство работ")
        if contractor_transfer_col_rd and contractor_transfer_col_rd in df.columns:
            rd_status_options_rd.append("Передано подрядчику")
        if rework_col_rd and rework_col_rd in df.columns:
            rd_status_options_rd.append("На доработке")
        if not is_pd and _RD_TESSA_STATUS_NOT_ISSUED not in rd_status_options_rd:
            rd_status_options_rd.append(_RD_TESSA_STATUS_NOT_ISSUED)
        # R23-06 (стр.17): добавить статус «Просрочено подрядчиком» и в «Просрочке выдачи РД/ПД».
        if "Просрочено подрядчиком" not in rd_status_options_rd:
            rd_status_options_rd.append("Просрочено подрядчиком")
        if rd_status_options_rd:
            selected_statuses_rd = st.pills(
                "Статус",
                rd_status_options_rd,
                selection_mode="multi",
                default=rd_status_options_rd,
                key="rd_delay_status_filter",
            )
            if selected_statuses_rd is None:
                selected_statuses_rd = []
        else:
            suppress_caption("Нет колонок статусов РД для фильтра.")
        rd_delay_show_forecast = True
        rd_delay_metric_mode = "Количество разделов"
        if not is_pd:
            rd_delay_show_forecast = st.checkbox(
                "Показать прогнозную дату выдачи разделов",
                value=True,
                key=f"rd_delay_show_forecast_{doc_code}",
            )
            rd_delay_metric_mode = st.radio(
                "Единица отображения",
                ["Количество разделов", "% от общего объёма"],
                horizontal=True,
                key=f"rd_delay_metric_mode_{doc_code}",
            )
        pd_report_date = date.today()
        if is_pd:
            pd_report_date = st.date_input(
                "Дата отчёта",
                value=date.today(),
                key=f"rd_delay_pd_report_date_{doc_code}",
                format="DD.MM.YYYY",
            )
    # Apply filters (проект — после раздела/статуса; индикаторы — без фильтра проекта)
    filtered_df = df.copy()

    if selected_section != "Все":
        if (
            is_pd
            and _msp_cipher_col
            and _msp_cipher_col in filtered_df.columns
        ):
            filtered_df = filtered_df[
                filtered_df[_msp_cipher_col].astype(str).str.strip() == selected_section
            ]
        elif "_tessa_section_label" in filtered_df.columns:
            filtered_df = filtered_df[
                filtered_df["_tessa_section_label"].astype(str).str.strip() == selected_section
            ]
        elif section_col and section_col in filtered_df.columns:
            filtered_df = filtered_df[
                filtered_df[section_col].astype(str).str.strip() == selected_section
            ]

    if (
        selected_statuses_rd
        and rd_status_options_rd
        and set(selected_statuses_rd) != set(rd_status_options_rd)
    ):
        status_mask = pd.Series([False] * len(filtered_df), index=filtered_df.index)
        if (
            "На согласовании" in selected_statuses_rd
            and on_approval_col_rd
            and on_approval_col_rd in filtered_df.columns
        ):
            on_approval_series = (
                filtered_df[on_approval_col_rd]
                .astype(str)
                .str.replace(",", ".", regex=False)
            )
            on_approval_numeric = pd.to_numeric(
                on_approval_series, errors="coerce"
            ).fillna(0)
            status_mask = status_mask | (on_approval_numeric > 0)
        if "Выдано в производство работ" in selected_statuses_rd:
            status_mask = status_mask | _rd_in_production_mask(
                filtered_df, in_production_col_rd
            )
        if (
            "Передано подрядчику" in selected_statuses_rd
            and contractor_transfer_col_rd
            and contractor_transfer_col_rd in filtered_df.columns
        ):
            contractor_series = (
                filtered_df[contractor_transfer_col_rd]
                .astype(str)
                .str.replace(",", ".", regex=False)
            )
            contractor_numeric = pd.to_numeric(
                contractor_series, errors="coerce"
            ).fillna(0)
            status_mask = status_mask | (contractor_numeric > 0)
        if (
            "На доработке" in selected_statuses_rd
            and rework_col_rd
            and rework_col_rd in filtered_df.columns
        ):
            rework_series = (
                filtered_df[rework_col_rd].astype(str).str.replace(",", ".", regex=False)
            )
            rework_numeric = pd.to_numeric(rework_series, errors="coerce").fillna(0)
            status_mask = status_mask | (rework_numeric > 0)
        # R23-06 (стр.17): просрочено подрядчиком = выдано подрядчику И plan_end в прошлом,
        # при этом (facторовое окончание не попадает в план).
        if "Просрочено подрядчиком" in selected_statuses_rd:
            _today_d = date.today()
            _pe = pd.Series(pd.NaT, index=filtered_df.index)
            if plan_end_col and plan_end_col in filtered_df.columns:
                _pe = pd.to_datetime(
                    filtered_df[plan_end_col].astype(str),
                    errors="coerce",
                    dayfirst=True,
                    format="mixed",
                )
            _fe = pd.Series(pd.NaT, index=filtered_df.index)
            if fact_end_col and fact_end_col in filtered_df.columns:
                _fe = pd.to_datetime(
                    filtered_df[fact_end_col].astype(str),
                    errors="coerce",
                    dayfirst=True,
                    format="mixed",
                )
            _issued = pd.Series(False, index=filtered_df.index)
            if contractor_transfer_col_rd and contractor_transfer_col_rd in filtered_df.columns:
                _issued = (
                    pd.to_numeric(
                        filtered_df[contractor_transfer_col_rd]
                        .astype(str)
                        .str.replace(",", ".", regex=False),
                        errors="coerce",
                    ).fillna(0)
                    > 0
                )
            _done_on_time = _fe.notna() & _pe.notna() & (_fe.dt.normalize() <= _pe.dt.normalize())
            _overdue_plan = _pe.notna() & (_pe.dt.date < _today_d)
            status_mask = status_mask | (_issued & _overdue_plan & (~_done_on_time))
        if not is_pd and (
            "Не выдан" in selected_statuses_rd
            or _RD_TESSA_STATUS_NOT_ISSUED in selected_statuses_rd
        ):
            _nv_mask = ~_rd_in_production_mask(filtered_df, in_production_col_rd)
            if on_approval_col_rd and on_approval_col_rd in filtered_df.columns:
                _oa = pd.to_numeric(
                    filtered_df[on_approval_col_rd]
                    .astype(str)
                    .str.replace(",", ".", regex=False),
                    errors="coerce",
                ).fillna(0)
                _nv_mask &= _oa <= 0
            if contractor_transfer_col_rd and contractor_transfer_col_rd in filtered_df.columns:
                _ct = pd.to_numeric(
                    filtered_df[contractor_transfer_col_rd]
                    .astype(str)
                    .str.replace(",", ".", regex=False),
                    errors="coerce",
                ).fillna(0)
                _nv_mask &= _ct <= 0
            if rework_col_rd and rework_col_rd in filtered_df.columns:
                _rw = pd.to_numeric(
                    filtered_df[rework_col_rd].astype(str).str.replace(",", ".", regex=False),
                    errors="coerce",
                ).fillna(0)
                _nv_mask &= _rw <= 0
            if "_tessa_card_count" in filtered_df.columns:
                _nv_mask &= pd.to_numeric(
                    filtered_df["_tessa_card_count"], errors="coerce"
                ).fillna(0) <= 0
            elif "_tessa_production_dt" in filtered_df.columns:
                _nv_mask &= filtered_df["_tessa_production_dt"].isna()
            status_mask = status_mask | _nv_mask.fillna(False)
        filtered_df = filtered_df[status_mask].copy()

    if selected_projects:
        _pk_set = {_project_filter_norm_key(p) for p in selected_projects}
        filtered_df = filtered_df[
            filtered_df[project_col].map(_project_filter_norm_key).isin(_pk_set)
        ]

    if filtered_df.empty:
        st.info("Нет данных для выбранных фильтров.")
        return

    # TESSA: наименование задачи для колонки «Задача» (если загружен tessa_tasks_data)
    if task_col and task_col in filtered_df.columns:
        try:
            _td = _rd_tessa_task_display_series(filtered_df, task_col)
            if _td is not None:
                filtered_df = filtered_df.copy()
                filtered_df["_task_display_tessa"] = _td
        except Exception:
            pass

    # Prepare data for "Просрочка выдачи РД"
    # X-axis: "Задача" (each task is a separate bar)
    # Y-axis: dev_col (deviation values)
    try:
        _bfin = _pd_msp_find_baseline_finish_col(filtered_df) or (
            plan_end_col if plan_end_col and plan_end_col in filtered_df.columns else None
        )
        _sfin = _pd_msp_find_schedule_finish_col(filtered_df) or (
            plan_end_col if plan_end_col and plan_end_col in filtered_df.columns else None
        )
        _afin = _pd_msp_actual_finish_col(filtered_df) or (
            fact_end_col if fact_end_col and fact_end_col in filtered_df.columns else None
        )
        filtered_df["_plan_end_dt"] = (
            _to_datetime_series(filtered_df[_bfin])
            if _bfin and _bfin in filtered_df.columns
            else (
                _to_datetime_series(filtered_df[plan_end_col])
                if plan_end_col and plan_end_col in filtered_df.columns
                else pd.NaT
            )
        )
        filtered_df["_fact_end_dt"] = (
            _to_datetime_series(filtered_df[_afin])
            if _afin and _afin in filtered_df.columns
            else (
                _to_datetime_series(filtered_df[fact_end_col])
                if fact_end_col and fact_end_col in filtered_df.columns
                else pd.NaT
            )
        )
        if _rd_delay_use_synthetic and rd_deviation_col == "_rd_delay_dev_synth":
            filtered_df["_rd_delay_dev_synth"] = _rd_delay_synthetic_deviation_days(
                filtered_df,
                plan_end_col=_sfin or plan_end_col,
                base_end_col=_bfin,
                actual_finish_col=_afin,
            )
        _bs_col = (
            "base start"
            if "base start" in filtered_df.columns
            else find_column(filtered_df, ["Baseline Start", "базовое начало", "Старт План"])
        )
        _bf_dt = (
            _to_datetime_series(filtered_df[_bfin])
            if _bfin and _bfin in filtered_df.columns
            else pd.Series(pd.NaT, index=filtered_df.index)
        )
        _bs_dt = (
            _to_datetime_series(filtered_df[_bs_col])
            if _bs_col and _bs_col in filtered_df.columns
            else pd.Series(pd.NaT, index=filtered_df.index)
        )
        _ss_col = (
            "plan start"
            if "plan start" in filtered_df.columns
            else _pd_msp_find_schedule_start_col(filtered_df)
        )
        _ss_dt = (
            _to_datetime_series(filtered_df[_ss_col])
            if _ss_col and _ss_col in filtered_df.columns
            else pd.Series(pd.NaT, index=filtered_df.index)
        )
        _sf_dt = (
            _to_datetime_series(filtered_df[_sfin])
            if _sfin and _sfin in filtered_df.columns
            else filtered_df["_fact_end_dt"]
        )
        _start = _bs_dt.where(_bs_dt.notna(), _bf_dt)
        filtered_df["_base_dur"] = (_bf_dt - _start).dt.days.clip(lower=0).fillna(0)
        filtered_df["_cur_dur"] = (_sf_dt - _start).dt.days.clip(lower=0).fillna(0)
        filtered_df["_dev_dur"] = (
            filtered_df["_cur_dur"] - filtered_df["_base_dur"]
        ).clip(lower=0)

        rd_deviation_raw = filtered_df[rd_deviation_col].copy()
        rd_deviation_str = rd_deviation_raw.astype(str)
        rd_deviation_str = rd_deviation_str.replace(
            ["nan", "None", "NaN", "NaT", "<NA>", "None"], ""
        )
        rd_deviation_str = rd_deviation_str.str.strip()
        rd_deviation_str = rd_deviation_str.str.replace(",", ".", regex=False)
        rd_deviation_str = rd_deviation_str.replace("", "0")
        filtered_df["rd_deviation_numeric"] = pd.to_numeric(
            rd_deviation_str, errors="coerce"
        ).fillna(0)

        # Числовые колонки для % выполнения РД/ПД
        if rd_plan_col and rd_plan_col in filtered_df.columns:
            filtered_df["_rd_plan_n"] = _to_numeric_series(filtered_df[rd_plan_col])
        else:
            filtered_df["_rd_plan_n"] = 0
        if rd_fact_col and rd_fact_col in filtered_df.columns:
            filtered_df["_rd_fact_n"] = _to_numeric_series(filtered_df[rd_fact_col])
        else:
            filtered_df["_rd_fact_n"] = 0

        show_by_section = str(rd_delay_view_mode).strip() == "По разделу"
        show_by_tasks = False

        if is_pd and _pd_masks_delay is not None:
            _pd_pre_delay_df = filtered_df.copy()
            _pd_dt_bs = _bs_dt.copy()
            _pd_dt_ss = _ss_dt.copy()
            _pd_dt_bf = _bf_dt.copy()
            _pd_dt_sf = _sf_dt.copy()
            _pd_dt_af = filtered_df["_fact_end_dt"].copy()
            _pd_pct_col_all = _pd_msp_pct_complete_col(_pd_pre_delay_df)
            _pd_chart_src_m = _pd_delay_chart_source_mask(
                _pd_pre_delay_df, _pd_masks_delay
            ).reindex(_pd_pre_delay_df.index, fill_value=False)
            _pd_chart_src_df = _pd_pre_delay_df.loc[_pd_chart_src_m.fillna(False)].copy()
            _pd_pct_all = (
                pd.to_numeric(_pd_pre_delay_df[_pd_pct_col_all], errors="coerce").fillna(0.0)
                if _pd_pct_col_all and _pd_pct_col_all in _pd_pre_delay_df.columns
                else pd.Series(0.0, index=_pd_pre_delay_df.index)
            )
            _pd_delay_m = _pd_delay_row_mask(filtered_df, _pd_masks_delay).reindex(
                filtered_df.index, fill_value=False
            )
            filtered_df = filtered_df.loc[_pd_delay_m.fillna(False)].copy()
            if filtered_df.empty:
                st.info("Нет разделов ПД (ур.4) для выбранных фильтров.")
                return
            # Даты считали до среза metrics_mask — выровнять индекс, иначе в
            # детальной таблице появляются строки с датами и nan в «Проект»/«Раздел».
            _bf_dt = _bf_dt.reindex(filtered_df.index)
            _sf_dt = _sf_dt.reindex(filtered_df.index)
            _bs_dt = _bs_dt.reindex(filtered_df.index)
            _ss_dt = _ss_dt.reindex(filtered_df.index)
            _af_dt = filtered_df["_fact_end_dt"].reindex(filtered_df.index)
            _ts_pd = pd.Timestamp(pd_report_date).normalize()
            _pct_pd_col = _pd_msp_pct_complete_col(filtered_df)
            if _pct_pd_col and _pct_pd_col in filtered_df.columns:
                _pc_raw = (
                    filtered_df[_pct_pd_col]
                    .astype(str)
                    .str.replace("%", "", regex=False)
                    .str.replace(",", ".", regex=False)
                    .str.strip()
                )
                _pc_pd = pd.to_numeric(_pc_raw, errors="coerce").fillna(0.0)
                # Доля 0..1 → проценты (как «1» = 100%).
                if _pc_pd.gt(0).any() and _pc_pd.max() <= 1.0 + 1e-9:
                    _pc_pd = _pc_pd * 100.0
            else:
                _pc_pd = pd.Series(0.0, index=filtered_df.index)
            _pd_plan_fin_dt = _pd_delay_plan_finish_dt_series(
                filtered_df,
                baseline_col=_bfin,
                schedule_col=_sfin or plan_end_col,
            ).reindex(filtered_df.index)
            _pd_start_dt = _bs_dt.where(_bs_dt.notna(), _ss_dt).reindex(filtered_df.index)
            _af_pd = filtered_df["_fact_end_dt"].reindex(filtered_df.index)
            filtered_df["_pd_row_plan"] = _pd_delay_plan_due_row_mask(
                _pd_plan_fin_dt, _pd_start_dt, _ts_pd
            ).astype(int)
            filtered_df["_pd_row_fact"] = (
                (_pc_pd >= 99.99)
                | (_af_pd.notna() & (_af_pd.dt.normalize() <= _ts_pd))
            ).astype(int)
            # Просрочка: разделы с «Окончание» > «Базовое окончание» среди сроков плана
            # (базовое окончание на дату отчёта или раньше — тот же охват, что «План ПД»).
            _pd_bf_n = _bf_dt.dt.normalize()
            _pd_sf_n = _sf_dt.dt.normalize()
            filtered_df["_pd_row_overdue"] = (
                _bf_dt.notna()
                & (_pd_bf_n <= _ts_pd)
                & _sf_dt.notna()
                & (_pd_sf_n > _pd_bf_n)
            ).astype(int)
            # Факт для stacked-графика: только вовремя (иначе 100%+просрочка
            # дублируют длину бара: зелёные 35 + красные 17).
            filtered_df["_pd_row_fact_ontime"] = (
                (filtered_df["_pd_row_fact"].astype(int) > 0)
                & (filtered_df["_pd_row_overdue"].astype(int) <= 0)
            ).astype(int)
            # Дубли шифра — только для KPI/карточек/сводки (Gantt/деталка без среза).
            _pd_dedupe_cipher = (
                _msp_cipher_col
                if _msp_cipher_col and _msp_cipher_col in filtered_df.columns
                else find_column(
                    filtered_df, ["abbreviation", "Шифр_ПД_и_РД", "Шифр"]
                )
            )
            _pd_kpi_df = filtered_df.copy()
            _pd_kpi_df["_plan_end_dt"] = pd.to_datetime(
                _pd_plan_fin_dt.reindex(filtered_df.index), errors="coerce"
            )
            _pd_kpi_df = _pd_monthly_dedupe_by_cipher(
                _pd_kpi_df,
                cipher_col=_pd_dedupe_cipher,
                project_col=(
                    project_col if project_col and project_col in _pd_kpi_df.columns else None
                ),
            )
            for _c in (
                "_pd_row_plan",
                "_pd_row_fact",
                "_pd_row_overdue",
            ):
                if _c in _pd_kpi_df.columns:
                    _pd_kpi_df[_c] = (
                        pd.to_numeric(_pd_kpi_df[_c], errors="coerce")
                        .fillna(0)
                        .astype(int)
                    )
            if (
                "_pd_row_fact" in _pd_kpi_df.columns
                and "_pd_row_overdue" in _pd_kpi_df.columns
            ):
                _pd_kpi_df["_pd_row_fact_ontime"] = (
                    (_pd_kpi_df["_pd_row_fact"] > 0)
                    & (_pd_kpi_df["_pd_row_overdue"] <= 0)
                ).astype(int)

            if show_by_section:
                _cipher_pd = (
                    _msp_cipher_col
                    if _msp_cipher_col and _msp_cipher_col in filtered_df.columns
                    else find_column(filtered_df, ["abbreviation", "Шифр_ПД_и_РД", "Шифр"])
                )
                _, _pd_raz_lbl = _pd_detail_table_labels(
                    filtered_df,
                    task_col=task_col,
                    cipher_col=_cipher_pd,
                )
                if _cipher_pd and _cipher_pd in filtered_df.columns:
                    _ci = filtered_df[_cipher_pd].astype(str).str.strip()
                    _ci_ok = _ci.ne("") & ~_ci.str.lower().isin({"nan", "none", "<na>"})
                    _pd_y_core = _pd_raz_lbl.where(
                        _pd_raz_lbl.astype(str).str.contains("Раздел", case=False, na=False),
                        _ci.where(_ci_ok, _pd_raz_lbl.astype(str)),
                    )
                    filtered_df["_pd_chart_y"] = _pd_y_core.astype(str)
                else:
                    filtered_df["_pd_chart_y"] = _pd_raz_lbl.astype(str)
                if project_col and project_col in filtered_df.columns:
                    _proj_lbl = filtered_df[project_col].astype(str).str.strip()
                    filtered_df["_pd_chart_y"] = (
                        _proj_lbl + " | " + filtered_df["_pd_chart_y"].astype(str)
                    )
                filtered_df["_pd_chart_y"] = (
                    filtered_df["_pd_chart_y"].astype(str).str.strip().replace({"": "—", "nan": "—"})
                )
                _sec_rows = _pd_build_delay_section_rows(
                    filtered_df,
                    y_col="_pd_chart_y",
                    source_df=_pd_pre_delay_df,
                    project_col=project_col,
                    cipher_col=_cipher_pd,
                    hier_col=_pd_masks_delay.get("hier_col"),
                    bs_dt=_pd_dt_bs,
                    ss_dt=_pd_dt_ss,
                    bf_dt=_pd_dt_bf,
                    sf_dt=_pd_dt_sf,
                    af_dt=_pd_dt_af,
                    pct=_pd_pct_all,
                    report_date=pd_report_date,
                )
                if _sec_rows.empty:
                    st.info("Нет данных для построения графика.")
                else:
                    fig = _pd_delay_section_duration_figure(
                        _sec_rows, y_col="_pd_chart_y"
                    )
                    _render_pd_delay_duration_chart(
                        fig, f"Просрочка выдачи {doc_code}"
                    )
                _pd_fact_agg = (
                    "_pd_row_fact_ontime"
                    if "_pd_row_fact_ontime" in _pd_kpi_df.columns
                    else "_pd_row_fact"
                )
                if project_col and project_col in _pd_kpi_df.columns:
                    chart_data = (
                        _pd_kpi_df.groupby(project_col, as_index=False)
                        .agg(
                            _pd_plan_cnt=("_pd_row_plan", "sum"),
                            _pd_fact_cnt=(_pd_fact_agg, "sum"),
                            _pd_overdue_cnt=("_pd_row_overdue", "sum"),
                        )
                        .rename(columns={project_col: "Проект"})
                    )
                    y_column = "Проект"
                    if not chart_data.empty:
                        _render_pd_delay_project_indicators(
                            chart_data, y_column, doc_code
                        )
                else:
                    chart_data = filtered_df[
                        ["_pd_chart_y", "_pd_row_plan", _pd_fact_agg, "_pd_row_overdue"]
                    ].copy()
                    # Без project_col дедуп по шифру на уровне подписей раздела.
                    chart_data = chart_data.drop_duplicates(
                        subset=["_pd_chart_y"], keep="first"
                    )
                    chart_data = chart_data.rename(
                        columns={
                            "_pd_chart_y": "Раздел",
                            "_pd_row_plan": "_pd_plan_cnt",
                            _pd_fact_agg: "_pd_fact_cnt",
                            "_pd_row_overdue": "_pd_overdue_cnt",
                        }
                    )
                    y_column = "Раздел"
            else:
                _pd_fact_agg = (
                    "_pd_row_fact_ontime"
                    if "_pd_row_fact_ontime" in _pd_kpi_df.columns
                    else "_pd_row_fact"
                )
                chart_data = pd.DataFrame()
                y_column = "Проект"
                if project_col and project_col in _pd_kpi_df.columns:
                    chart_data = (
                        _pd_kpi_df.groupby(project_col, as_index=False)
                        .agg(
                            _pd_plan_cnt=("_pd_row_plan", "sum"),
                            _pd_fact_cnt=(_pd_fact_agg, "sum"),
                            _pd_overdue_cnt=("_pd_row_overdue", "sum"),
                        )
                        .rename(columns={project_col: "Проект"})
                    )
                    # Gantt по датам (ТЗ): жёлтый → max БО, красный/зелёный по Окончанию.
                    # filtered_df: индекс совпадает с _bs_dt/_bf_dt.
                    _proj_rows = _pd_build_delay_project_rows(
                        filtered_df,
                        project_col=project_col,
                        display_projects=filtered_df[project_col],
                        bs_dt=_bs_dt,
                        ss_dt=_ss_dt,
                        bf_dt=_bf_dt,
                        sf_dt=_sf_dt,
                        af_dt=_af_dt,
                        pct=_pc_pd,
                        report_date=pd_report_date,
                    )
                    if _proj_rows.empty:
                        st.info("Нет данных для построения графика.")
                    else:
                        if project_col != "Проект":
                            _proj_rows = _proj_rows.rename(
                                columns={project_col: "Проект"}
                            )
                        fig = _pd_delay_section_duration_figure(
                            _proj_rows,
                            y_col="Проект",
                            yellow_name="Базовое окончание",
                            green_name="Окончание",
                            yellow_hover="Базовое окончание",
                            green_hover="Окончание",
                        )
                        _render_pd_delay_duration_chart(
                            fig, f"Просрочка выдачи {doc_code}"
                        )
                    if not chart_data.empty:
                        _render_pd_delay_project_indicators(
                            chart_data, y_column, doc_code
                        )
                else:
                    st.info("Нет данных для построения графика.")

            # Помесячная динамика ПД (раньше была только у РД — «график пропал»).
            try:
                _pd_plan_fin_m = _pd_delay_plan_finish_dt_series(
                    filtered_df,
                    baseline_col=_bfin,
                    schedule_col=_sfin or plan_end_col,
                ).reindex(filtered_df.index)
                _pd_m_src = filtered_df.copy()
                _pd_m_src["_plan_end_dt"] = pd.to_datetime(
                    _pd_plan_fin_m, errors="coerce"
                )
                _pd_m_src = _pd_m_src[_pd_m_src["_plan_end_dt"].notna()].copy()
                if not _pd_m_src.empty:
                    # По месяцу планового срока — каждый раздел = 1 (не «due»-флаг).
                    _pd_m_src["_rd_plan_n"] = 1.0
                    _pd_m_src["_rd_fact_n"] = pd.to_numeric(
                        _pd_m_src.get("_pd_row_fact", 0), errors="coerce"
                    ).fillna(0.0).clip(lower=0.0, upper=1.0)
                    _pd_m_cipher = (
                        _msp_cipher_col
                        if _msp_cipher_col and _msp_cipher_col in _pd_m_src.columns
                        else find_column(
                            _pd_m_src, ["abbreviation", "Шифр_ПД_и_РД", "Шифр"]
                        )
                    )
                    # Дубли шифра (старый/новый БО) → одна строка, просрочка OR.
                    _pd_m_src = _pd_monthly_dedupe_by_cipher(
                        _pd_m_src,
                        cipher_col=_pd_m_cipher,
                        project_col=project_col if project_col in _pd_m_src.columns else None,
                    )
                    # После OR факт/просрочки обновить вход агрегата по месяцам.
                    if "_pd_row_fact" in _pd_m_src.columns:
                        _pd_m_src["_rd_fact_n"] = (
                            pd.to_numeric(_pd_m_src["_pd_row_fact"], errors="coerce")
                            .fillna(0.0)
                            .clip(lower=0.0, upper=1.0)
                        )
                    if "_pd_row_overdue" in _pd_m_src.columns:
                        _pd_m_src["_pd_row_overdue"] = (
                            pd.to_numeric(_pd_m_src["_pd_row_overdue"], errors="coerce")
                            .fillna(0)
                            .astype(int)
                        )
                    # Просрочка как на карточке KPI: Finish > Базовое окончание.
                    _pd_monthly = _rd_monthly_sections_aggregate(
                        _pd_m_src, overdue_col="_pd_row_overdue"
                    )
                    if _pd_monthly is not None and not _pd_monthly.empty:
                        # От текущего месяца к более ранним (сверху вниз на горизонт. графике).
                        try:
                            _cur_m = pd.Period(
                                pd.Timestamp.today().normalize(), freq="M"
                            )
                            _pd_monthly = _pd_monthly[
                                _pd_monthly["_month"] <= _cur_m
                            ].copy()
                        except Exception:
                            pass
                        if not _pd_monthly.empty:
                            _render_rd_monthly_overlay_chart(
                                _pd_monthly,
                                metric_mode="Количество разделов",
                                orientation="h",
                                subheader=f"Динамика выдачи {doc_code} по месяцам",
                                chart_key="pd_delay_monthly_cum_v3",
                                caption_parts=(
                                    "Выдача проектной документации",
                                    "по месяцам",
                                ),
                                cumulative=True,
                            )
            except Exception as _pd_m_err:
                suppress_caption(f"Динамика ПД по месяцам: {_pd_m_err}")
        elif show_by_tasks:
            # Prepare data for chart - each task is a separate bar
            if section_col and section_col in filtered_df.columns:
                filtered_df["Задача_полная"] = (
                    filtered_df[section_col].astype(str)
                    + " | "
                    + filtered_df[task_col].astype(str)
                )
            else:
                filtered_df["Задача_полная"] = filtered_df[task_col].astype(str)

            agg_map = {"rd_deviation_numeric": "sum", "_rd_plan_n": "sum", "_rd_fact_n": "sum"}
            agg_map.update(
                {
                    "_overdue_cnt": ("rd_deviation_numeric", _rd_delay_overdue_row_count),
                    "_total_cnt": ("_rd_plan_n", _rd_delay_total_sections),
                    "_row_cnt": ("rd_deviation_numeric", "count"),
                }
            )
            agg_map = {k: v for k, v in agg_map.items() if k == "_overdue_cnt" or k == "_total_cnt" or k == "_row_cnt" or k in filtered_df.columns}
            chart_data = (
                filtered_df.groupby("Задача_полная", as_index=False).agg(agg_map)
            )
            chart_data = chart_data.rename(columns={"rd_deviation_numeric": dev_col})
            chart_data["Задача"] = chart_data["Задача_полная"]

            # % выполнения РД/ПД = факт / план * 100
            chart_data["% выполнения РД/ПД"] = ""
            mask_plan = chart_data["_rd_plan_n"] > 0
            chart_data.loc[mask_plan, "% выполнения РД/ПД"] = (
                (chart_data.loc[mask_plan, "_rd_fact_n"] / chart_data.loc[mask_plan, "_rd_plan_n"] * 100)
                .round(1)
                .astype(str)
                .str.replace(r"\.0$", "", regex=True)
            ) + "%"
            chart_data.loc[~mask_plan, "% выполнения РД/ПД"] = "—"
            chart_data["_overdue_share_pct"] = 0.0
            chart_data.loc[mask_plan, "_overdue_share_pct"] = (
                chart_data.loc[mask_plan, dev_col]
                / chart_data.loc[mask_plan, "_rd_plan_n"]
                * 100.0
            ).round(1)

            chart_data = chart_data.sort_values(dev_col, ascending=False)
            y_column = "Задача_полная"
            y_title = "Задача"
        elif show_by_section:
            _sec_lbl = _rd_delay_section_label_series(
                filtered_df,
                is_pd=is_pd,
                find_column_fn=find_column,
                section_col=section_col,
                task_col=task_col,
                msp_cipher_col=_msp_cipher_col if "_msp_cipher_col" in dir() else None,
                msp_name_col=_msp_name_col_for_label if "_msp_name_col_for_label" in dir() else None,
            )
            filtered_df["_rd_delay_section_label"] = _sec_lbl
            agg_map = {
                "rd_deviation_numeric": "sum",
                "_rd_plan_n": "sum",
                "_rd_fact_n": "sum",
                "_base_dur": "max",
                "_cur_dur": "max",
                "_dev_dur": "max",
                "_overdue_cnt": ("rd_deviation_numeric", _rd_delay_overdue_row_count),
                "_total_cnt": ("_rd_plan_n", _rd_delay_total_sections),
                "_row_cnt": ("rd_deviation_numeric", "count"),
            }
            agg_map = {k: v for k, v in agg_map.items() if k in ("_overdue_cnt", "_total_cnt", "_row_cnt") or k in filtered_df.columns}
            chart_data = (
                filtered_df.groupby("_rd_delay_section_label", as_index=False).agg(agg_map)
            )
            chart_data = chart_data.rename(
                columns={"rd_deviation_numeric": dev_col, "_rd_delay_section_label": "Раздел"}
            )
            chart_data["% выполнения РД/ПД"] = ""
            mask_plan = chart_data["_rd_plan_n"] > 0 if "_rd_plan_n" in chart_data.columns else pd.Series(False, index=chart_data.index)
            if "_rd_plan_n" in chart_data.columns and "_rd_fact_n" in chart_data.columns:
                chart_data.loc[mask_plan, "% выполнения РД/ПД"] = (
                    (chart_data.loc[mask_plan, "_rd_fact_n"] / chart_data.loc[mask_plan, "_rd_plan_n"] * 100)
                    .round(1)
                    .astype(str)
                    .str.replace(r"\.0$", "", regex=True)
                ) + "%"
            chart_data.loc[~mask_plan, "% выполнения РД/ПД"] = "—"
            chart_data = chart_data.sort_values(dev_col, ascending=False)
            y_column = "Раздел"
            y_title = ""
        else:
            # Group by project and sum deviations
            if project_col and project_col in filtered_df.columns:
                agg_map = {
                    "rd_deviation_numeric": "sum",
                    "_rd_plan_n": "sum",
                    "_rd_fact_n": "sum",
                    "_base_dur": "max",
                    "_cur_dur": "max",
                    "_dev_dur": "max",
                    "_overdue_cnt": ("rd_deviation_numeric", _rd_delay_overdue_row_count),
                    "_total_cnt": ("_rd_plan_n", _rd_delay_total_sections),
                    "_row_cnt": ("rd_deviation_numeric", "count"),
                }
                agg_map = {k: v for k, v in agg_map.items() if k in ("_overdue_cnt", "_total_cnt", "_row_cnt") or k in filtered_df.columns}
                chart_data = (
                    filtered_df.groupby(project_col, as_index=False).agg(agg_map)
                )
                chart_data = chart_data.rename(
                    columns={"rd_deviation_numeric": dev_col, project_col: "Проект"}
                )
                chart_data["% выполнения РД/ПД"] = ""
                mask_plan = chart_data["_rd_plan_n"] > 0
                chart_data.loc[mask_plan, "% выполнения РД/ПД"] = (
                    (chart_data.loc[mask_plan, "_rd_fact_n"] / chart_data.loc[mask_plan, "_rd_plan_n"] * 100)
                    .round(1)
                    .astype(str)
                    .str.replace(r"\.0$", "", regex=True)
                ) + "%"
                chart_data.loc[~mask_plan, "% выполнения РД/ПД"] = "—"
                chart_data["_overdue_share_pct"] = 0.0
                chart_data.loc[mask_plan, "_overdue_share_pct"] = (
                    chart_data.loc[mask_plan, dev_col]
                    / chart_data.loc[mask_plan, "_rd_plan_n"]
                    * 100.0
                ).round(1)
                chart_data = chart_data.sort_values(dev_col, ascending=False)
                y_column = "Проект"
                y_title = ""
            else:
                st.info("Нет данных для построения графика.")
                return

        if not is_pd:
            if chart_data.empty:
                st.info("Нет данных для построения графика.")
                return
            _use_pct = str(rd_delay_metric_mode).strip().startswith("%")
            _rd_delay_apply_overdue_metric_chart(
                chart_data,
                y_col=y_column,
                y_title=y_title,
                use_pct=_use_pct,
                doc_code=doc_code,
            )

            # R23-07 (стр.22): индикаторы просрочки по проектам — карточки с градиентом зелёный→красный.
            try:
                if (
                    y_column == "Проект"
                    and not chart_data.empty
                    and project_col
                    and project_col in filtered_df.columns
                ):
                    st.markdown(f"**Индикаторы просрочки {doc_code} по проектам**")
                    _ind_df = (
                        chart_data[["Проект", "_overdue_cnt"]]
                        .rename(columns={"_overdue_cnt": "_dev"})
                        .reset_index(drop=True)
                    )
                    _dev_series = pd.to_numeric(_ind_df["_dev"], errors="coerce").fillna(0.0)
                    _dev_max = float(_dev_series.max()) if not _dev_series.empty else 0.0
                    _ind_df = _ind_df.sort_values("_dev", ascending=False).reset_index(drop=True)
                    _n = len(_ind_df)
                    _cols_n = min(4, max(1, _n))
                    _cols_row = st.columns(_cols_n, gap="small")
                    for _i, (_idx, _row) in enumerate(_ind_df.iterrows()):
                        _proj = str(_row["Проект"])
                        _dev = float(_row["_dev"]) if pd.notna(_row["_dev"]) else 0.0
                        _bg = _pd_delay_indicator_color(_dev, _dev_max)
                        with _cols_row[_i % _cols_n]:
                            st.markdown(
                                _pd_delay_project_indicator_card_html(
                                    _proj,
                                    int(round(_dev)),
                                    bg=_bg,
                                    unit="разд.",
                                ),
                                unsafe_allow_html=True,
                            )
            except Exception as _ind_err:
                suppress_caption(f"Не удалось построить индикаторы просрочки: {_ind_err}")

        if not is_pd and plan_end_col and plan_end_col in filtered_df.columns:
            month_df = filtered_df[filtered_df["_plan_end_dt"].notna()].copy()
            if not month_df.empty:
                today_ts = pd.Timestamp(date.today())
                month_df["_month"] = month_df["_plan_end_dt"].dt.to_period("M")
                month_df["_done_n"] = np.where(
                    month_df["_rd_fact_n"] > 0,
                    np.minimum(month_df["_rd_plan_n"], month_df["_rd_fact_n"]),
                    0.0,
                )
                month_df["_remaining_n"] = (
                    month_df["_rd_plan_n"] - month_df["_done_n"]
                ).clip(lower=0.0)
                month_df["_overdue_n"] = np.where(
                    (month_df["_remaining_n"] > 0)
                    & (month_df["_plan_end_dt"] < today_ts),
                    month_df["_remaining_n"],
                    0.0,
                )
                month_df["_delta_n"] = (
                    month_df["_remaining_n"] - month_df["_overdue_n"]
                ).clip(lower=0.0)

                monthly = (
                    month_df.groupby("_month", as_index=False)
                    .agg(
                        plan=("_rd_plan_n", "sum"),
                        done=("_done_n", "sum"),
                        delta=("_delta_n", "sum"),
                        overdue=("_overdue_n", "sum"),
                    )
                    .sort_values("_month")
                )
                monthly = monthly[monthly["plan"] > 0].copy()
                if not monthly.empty:
                    monthly["Месяц"] = monthly["_month"].apply(
                        lambda p: f"{RUSSIAN_MONTHS.get(p.month, str(p.month))} {p.year}"
                    )
                    monthly["Выполнено"] = (monthly["done"] / monthly["plan"] * 100).round(1)
                    monthly["Разница план/факт"] = (
                        monthly["delta"] / monthly["plan"] * 100
                    ).round(1)
                    monthly["Просрочено"] = (
                        monthly["overdue"] / monthly["plan"] * 100
                    ).round(1)

                    monthly_plot_df = monthly.melt(
                        id_vars=["Месяц"],
                        value_vars=["Выполнено", "Разница план/факт", "Просрочено"],
                        var_name="Статус",
                        value_name="Процент",
                    )
                    monthly_plot_df["Подпись"] = monthly_plot_df["Процент"].apply(
                        lambda v: f"{v:.0f}%" if pd.notna(v) and float(v) > 0 else ""
                    )

                    render_table_subheader(st, "Выдача рабочей документации по месяцам")
                    fig_months = px.bar(
                        monthly_plot_df,
                        x="Месяц",
                        y="Процент",
                        color="Статус",
                        barmode="stack",
                        text="Подпись",
                        color_discrete_map={
                            "Выполнено": "#27AE60",
                            "Разница план/факт": "#F39C12",
                            "Просрочено": "#C0392B",
                        },
                    )
                    fig_months.update_layout(
                        xaxis_title="Месяц",
                        yaxis_title="% РД",
                        yaxis=dict(
                            range=[0, 100],
                            ticksuffix="%",
                            tickfont=dict(color=_fin_chart_axis_color()),
                            title_font=dict(color=_fin_chart_axis_color()),
                        ),
                        xaxis=dict(
                            tickfont=dict(color=_fin_chart_axis_color()),
                            title_font=dict(color=_fin_chart_axis_color()),
                        ),
                        legend=dict(
                            orientation="h",
                            yanchor="bottom",
                            y=1.02,
                            xanchor="left",
                            x=0,
                            title_text="",
                        ),
                        height=520,
                    )
                    fig_months.update_traces(textposition="inside", textfont=dict(size=10))
                    fig_months = apply_chart_background(fig_months)
                    render_chart(fig_months, caption_below=report_chart_caption_body("Выдача рабочей документации", "Месяц"))

        st.subheader("Детальная таблица")

        # R23-07 part 8: для РД, если загружены карточки TESSA `tessa_*_rd.csv`, —
        # строим детальную таблицу из TESSA (все нужные поля: Шифр, Раздел,
        # Задача, Номер шифра, Шифр полный, Статус, а Номер договора —
        # построчно через `1C_ID_DOG` ↔ DK.json). Для ПД остаётся MSP-источник.
        _tessa_rd_detail_active = False
        if not is_pd:
            try:
                _t_src = st.session_state.get("tessa_data")
            except Exception:
                _t_src = None
            if _t_src is not None and not getattr(_t_src, "empty", True):
                _t_section_selected = (
                    selected_section if selected_section and selected_section != "Все" else None
                )
                _tessa_detail_table = _build_rd_work_doc_detail_table(
                    selected_projects=selected_projects or None,
                    selected_section=_t_section_selected,
                )
                if not _tessa_detail_table.empty:
                    _tessa_rd_detail_active = True
                    _tessa_detail_table = _drop_rd_detail_empty_rows(_tessa_detail_table)
                    _tessa_detail_table = _rd_detail_prepare_for_display(
                        _tessa_detail_table, show_forecast=rd_delay_show_forecast
                    )
                    suppress_caption(
                        "Источник: карточки TESSA (`tessa_*_rd.csv`) и план из "
                        "`other_*_rd.csv`."
                    )
                    sort_col1, sort_col2 = st.columns([3, 1], gap="small")
                    with sort_col1:
                        _t_sort_col = st.selectbox(
                            "Сортировка по колонке",
                            options=list(_tessa_detail_table.columns),
                            index=0,
                            key="rd_delay_tessa_sort_col",
                        )
                    with sort_col2:
                        _t_sort_desc = st.checkbox(
                            "Отображать в порядке убывания",
                            value=False,
                            key="rd_delay_tessa_sort_desc",
                        )
                    if _t_sort_col not in _tessa_detail_table.columns:
                        _t_sort_col = (
                            _tessa_detail_table.columns[0]
                            if len(_tessa_detail_table.columns)
                            else None
                        )
                    if _t_sort_col is not None:
                        _tessa_detail_table = _tessa_detail_table.sort_values(
                            by=_t_sort_col,
                            ascending=not _t_sort_desc,
                            na_position="last",
                            kind="mergesort",
                        ).reset_index(drop=True)
                    _render_styled_table_report(
                        style_dataframe_for_dark_theme(
                            _tessa_detail_table,
                            days_column="Отклонение от даты по договору",
                            extra_days_columns=("Отклонение от прогнозной даты",),
                            days_deviation_gradient=True,
                            # ТЗ: < 0 — красный (с «−»), ≥ 0 — зелёный.
                            days_positive_is_ahead=True,
                        ),
                        _tessa_detail_table,
                        file_stem="rd_delay_tessa_detail",
                        key_prefix=f"rd_tessa_{abs(id(_tessa_detail_table))}",
                    )

        # Если TESSA-детальная отрисована выше — MSP-ветку детальной таблицы
        # пропускаем, но последующие блоки «Сводка по просрочке», «План и факт
        # окончания ПД/РД» и KPI-метрики продолжают строиться как обычно.
        _msp_detail_disabled = _tessa_rd_detail_active

        detail_cipher_col = find_column(
            filtered_df,
            ["Шифр полный", "Полный шифр", "DivisionCipher", "Cipher", "Аббревиатура"],
        )
        forecast_date_col = find_column(
            filtered_df,
            [
                "Прогнозная дата выдачи разделов",
                "Прогнозная дата выдачи РД",
                "Прогнозная дата",
                "ForecastDate",
                "Forecast date",
            ],
        )
        upload_date_col = find_column(
            filtered_df,
            [
                "Дата загрузки раздела РД",
                "Дата загрузки",
                "Completed",
                "CompletedDate",
                "UploadDate",
                "Upload date",
            ],
        )
        production_issue_date_col = find_column(
            filtered_df,
            [
                "Дата выдачи РД в производство работ",
                "Дата выдачи в производство работ",
                "Дата выдачи в производство",
                "Дата выдачи РД",
                "Дата выдачи",
            ],
        )

        # R23-07 (стр.20): доп. колонки для таблицы РД/ПД — Номер договора / Шифр / Номер шифра / Блок.
        contract_no_col = find_column(
            filtered_df,
            ["Номер договора", "№ договора", "Номер контракта", "Договор", "Contract Number", "ContractNo"],
        )
        cipher_col = find_column(
            filtered_df,
            ["Шифр", "Cipher", "DivisionCipher"],
        )
        cipher_no_col = find_column(
            filtered_df,
            ["Номер шифра", "№ шифра", "CipherNo", "CipherNumber"],
        )
        block_col = find_column(
            filtered_df,
            ["Блок", "БЛОК", "block", "Block", "Наименование блока"],
        )

        detail_df = filtered_df.copy()
        detail_df["_detail_section_name"] = (
            detail_df[section_col].astype(str).str.strip()
            if section_col and section_col in detail_df.columns
            else (
                detail_df[task_col].astype(str).str.strip()
                if task_col and task_col in detail_df.columns
                else ""
            )
        )
        detail_df["_detail_cipher"] = (
            detail_df[detail_cipher_col].astype(str).str.strip()
            if detail_cipher_col and detail_cipher_col in detail_df.columns
            else ""
        )
        detail_df["_detail_plan_date"] = (
            _to_datetime_series(detail_df[plan_end_col])
            if plan_end_col and plan_end_col in detail_df.columns
            else pd.Series(pd.NaT, index=detail_df.index)
        )
        detail_df["_detail_forecast_date"] = (
            _to_datetime_series(detail_df[forecast_date_col])
            if forecast_date_col and forecast_date_col in detail_df.columns
            else detail_df["_detail_plan_date"].copy()
        )
        detail_df["_detail_upload_date"] = (
            _to_datetime_series(detail_df[upload_date_col])
            if upload_date_col and upload_date_col in detail_df.columns
            else pd.Series(pd.NaT, index=detail_df.index)
        )
        if "_tessa_production_dt" in detail_df.columns:
            detail_df["_detail_production_issue_date"] = pd.to_datetime(
                detail_df["_tessa_production_dt"], errors="coerce"
            )
        else:
            detail_df["_detail_production_issue_date"] = (
                _to_datetime_series(detail_df[production_issue_date_col])
                if production_issue_date_col and production_issue_date_col in detail_df.columns
                else detail_df["_fact_end_dt"].copy()
            )

        def _resolve_rd_status_label(row) -> str:
            if "_tessa_production_dt" in row.index and pd.notna(row.get("_tessa_production_dt")):
                return "Выдано в производство работ"
            if contractor_transfer_col_rd and contractor_transfer_col_rd in row.index:
                if float(_to_numeric_series(pd.Series([row[contractor_transfer_col_rd]])).iloc[0]) > 0:
                    return "Передано подрядчику"
            if in_production_col_rd and in_production_col_rd in row.index:
                _prod_dt = pd.to_datetime(
                    str(row[in_production_col_rd]), errors="coerce", dayfirst=True, format="mixed"
                )
                if pd.notna(_prod_dt):
                    return "Выдано в производство работ"
                if float(_to_numeric_series(pd.Series([row[in_production_col_rd]])).iloc[0]) > 0:
                    return "Выдано в производство работ"
            if on_approval_col_rd and on_approval_col_rd in row.index:
                if float(_to_numeric_series(pd.Series([row[on_approval_col_rd]])).iloc[0]) > 0:
                    return "На согласовании"
            if rework_col_rd and rework_col_rd in row.index:
                if float(_to_numeric_series(pd.Series([row[rework_col_rd]])).iloc[0]) > 0:
                    return "На доработке"
            return "Не выдан"

        detail_df["_detail_status"] = detail_df.apply(_resolve_rd_status_label, axis=1)
        detail_df["_detail_actual_issue_date"] = detail_df["_detail_production_issue_date"].where(
            detail_df["_detail_production_issue_date"].notna(),
            detail_df["_detail_upload_date"],
        )
        detail_df["_detail_actual_issue_date"] = detail_df["_detail_actual_issue_date"].where(
            detail_df["_detail_actual_issue_date"].notna(),
            detail_df["_detail_plan_date"],
        )
        # ТЗ: числитель = дата выдачи в производство работ; не выдан → сегодня.
        # Знак: дата − (факт|сегодня) → просрочка отрицательная (красная с «−»).
        _rd_today = pd.Timestamp.now().normalize()
        _rd_base = detail_df["_detail_production_issue_date"].where(
            detail_df["_detail_production_issue_date"].notna(), _rd_today
        )
        detail_df["_detail_delta_vs_contract"] = (
            detail_df["_detail_plan_date"] - _rd_base
        ).dt.days
        detail_df["_detail_delta_vs_forecast"] = (
            detail_df["_detail_forecast_date"] - _rd_base
        ).dt.days

        def _fmt_date_or_blank(series: pd.Series) -> pd.Series:
            parsed = pd.to_datetime(series, errors="coerce")
            return parsed.dt.strftime("%d.%m.%Y").fillna("—")

        # R23-07 (стр.20): порядок колонок — Проект, Название разделов работ, Номер договора, Шифр,
        # Номер шифра, Блок, Шифр полный, даты, статус, отклонения.
        _col_series = {}

        def _safe_str_col(col_name):
            if col_name and col_name in detail_df.columns:
                s = detail_df[col_name].astype(str).str.strip().replace(
                    {"nan": "", "None": "", "<NA>": "", "NaT": ""}
                )
                return s.where(s.ne(""), "—")
            return pd.Series(["—"] * len(detail_df), index=detail_df.index)

        _col_series["Наименование разделов работ"] = detail_df["_detail_section_name"]
        # «Номер договора»: приоритет MSP-колонке, если она есть; иначе —
        # агрегированно по проекту из 1С (DK.json + dannye.json).
        _contract_source_note = ""
        if contract_no_col and contract_no_col in detail_df.columns:
            _col_series["Номер договора"] = _safe_str_col(contract_no_col)
        elif project_col and project_col in detail_df.columns:
            _1c_lookup = _build_project_to_contract_numbers_lookup()
            _col_series["Номер договора"] = _project_contract_numbers_series(
                detail_df[project_col]
            )
            if not _1c_lookup:
                _contract_source_note = (
                    "⚠ Колонка «Номер договора» заполняется из 1С "
                    "(`1с_*_DK.json` + `1с_*_dannye.json`) агрегированно по проекту — "
                    "сейчас эти файлы не подгружены в сессию. "
                    "Подгрузите их через «Источник данных → Из папки web»."
                )
            else:
                _matched = sum(
                    1
                    for pk in detail_df[project_col].map(_project_filter_norm_key).unique()
                    if pk and _1c_lookup.get(pk)
                )
                _total = len(
                    [
                        pk
                        for pk in detail_df[project_col].map(_project_filter_norm_key).unique()
                        if pk
                    ]
                )
                _contract_source_note = (
                    f"Источник «Номер договора»: 1С (`DK.json` + `dannye.json`), "
                    f"найдено по {_matched}/{_total} проектам выборки."
                )
        else:
            _col_series["Номер договора"] = _safe_str_col(contract_no_col)
        # R23-07: «Шифр» — из MSP (Шифр_ПД_и_РД/Шифр) приоритетно, fallback на
        # общий cipher_col (find_column(["Шифр","Cipher","DivisionCipher"])).
        _cipher_for_detail = None
        if _msp_cipher_col and _msp_cipher_col in detail_df.columns:
            _cipher_for_detail = _msp_cipher_col
        elif cipher_col and cipher_col in detail_df.columns:
            _cipher_for_detail = cipher_col
        _col_series["Шифр"] = _safe_str_col(_cipher_for_detail)
        _col_series["Номер шифра"] = _safe_str_col(cipher_no_col).map(
            lambda x: (
                _fmt_rd_cipher_number(x)
                if str(x).strip() not in ("—", "")
                else x
            )
        )
        _col_series["Блок"] = _safe_str_col(block_col)
        _col_series["Шифр полный"] = detail_df["_detail_cipher"]
        # §4.4 / R23-07: «Задача» — при наличии `_rd_tessa_task_display_series` из
        # TESSA (разделы RD), иначе MSP task_col / «Название».
        _task_for_detail = None
        if task_col and task_col in detail_df.columns:
            _task_for_detail = task_col
        else:
            _task_for_detail = find_column(detail_df, ["Название", "task name", "Задача"])
        _msp_task_s = (
            detail_df[_task_for_detail].astype(str).str.strip().replace(
                {"nan": "", "None": "", "<NA>": "", "NaT": ""}
            )
            if _task_for_detail and _task_for_detail in detail_df.columns
            else pd.Series(["—"] * len(detail_df), index=detail_df.index)
        )
        _msp_task_s = _msp_task_s.where(_msp_task_s.ne(""), "—")
        if "_task_display_tessa" in detail_df.columns:
            _tessa_t = detail_df["_task_display_tessa"].astype(str).str.strip()
            _tessa_t = _tessa_t.replace({"nan": "", "None": "", "<NA>": ""})
            _col_series["Задача"] = _tessa_t.where(_tessa_t.ne(""), _msp_task_s)
        else:
            _col_series["Задача"] = _msp_task_s
        _col_series["Дата выдачи разделов по договору"] = _fmt_date_or_blank(
            detail_df["_detail_plan_date"]
        )
        _col_series["Прогнозная дата выдачи разделов"] = _fmt_date_or_blank(
            detail_df["_detail_forecast_date"]
        )
        _col_series["Статус"] = detail_df["_detail_status"]
        _col_series["Дата загрузки раздела РД"] = _fmt_date_or_blank(
            detail_df["_detail_upload_date"]
        )
        _col_series["Дата выдачи РД в производство работ"] = _fmt_date_or_blank(
            detail_df["_detail_production_issue_date"]
        )
        _col_series["Отклонение от даты по договору, дн."] = detail_df[
            "_detail_delta_vs_contract"
        ].apply(lambda x: int(round(float(x), 0)) if pd.notna(x) else "")
        _col_series["Отклонение от прогнозной даты, дн."] = detail_df[
            "_detail_delta_vs_forecast"
        ].apply(lambda x: int(round(float(x), 0)) if pd.notna(x) else "")

        detail_table = pd.DataFrame(_col_series)

        # Убираем пустые доп.колонки (если их нет в источнике — не засоряем таблицу).
        for _optional in (
            "Номер договора",
            "Шифр",
            "Номер шифра",
            "Блок",
            "Шифр полный",
            "Задача",
        ):
            if _optional in detail_table.columns and (
                detail_table[_optional].astype(str).str.strip().eq("").all()
            ):
                detail_table = detail_table.drop(columns=[_optional])

        if project_col and project_col in detail_df.columns:
            detail_table.insert(0, "Проект", detail_df[project_col].astype(str).str.strip())

        if is_pd:
            # П.3 (ПД): детальная таблица — только нужные колонки из MSP
            # (Проект, Наименование раздела работ, Раздел, Статус по % MSP,
            #  Начало/Базовое начало/Отклонение начала, Окончание/Базовое
            #  окончание/Отклонение окончания) с прокраской отклонений.
            # П.1: селекторы сортировки убраны — сортировка кликом по заголовку.
            _pd_sstart_col = (
                "start"
                if "start" in filtered_df.columns
                else find_column(
                    filtered_df,
                    ["Начало", "Старт План", "Plan Start", "Дата начала", "Start"],
                )
            )
            _pd_sstart_dt = (
                _to_datetime_series(filtered_df[_pd_sstart_col])
                if _pd_sstart_col and _pd_sstart_col in filtered_df.columns
                else pd.Series(pd.NaT, index=filtered_df.index)
            )
            _pd_pct_col = _pd_msp_pct_complete_col(filtered_df)
            _pd_pct = (
                pd.to_numeric(filtered_df[_pd_pct_col], errors="coerce").fillna(0.0)
                if _pd_pct_col and _pd_pct_col in filtered_df.columns
                else pd.Series(0.0, index=filtered_df.index)
            )

            def _pd_status_label(p) -> str:
                try:
                    pv = float(p)
                except Exception:
                    pv = 0.0
                if pv >= 99.99:
                    return "Завершено (100%)"
                if pv <= 0.0001:
                    return "Не начато (0%)"
                return f"В работе ({pv:.0f}%)"

            def _fmt_pd_date(series: pd.Series) -> pd.Series:
                return (
                    pd.to_datetime(series, errors="coerce")
                    .dt.strftime("%d.%m.%Y")
                    .fillna("—")
                )

            _pd_dev_start = (_bs_dt - _pd_sstart_dt).dt.days
            _pd_dev_end = (_bf_dt - _sf_dt).dt.days
            _pd_cipher_detail = (
                _msp_cipher_col
                if _msp_cipher_col and _msp_cipher_col in filtered_df.columns
                else find_column(filtered_df, ["abbreviation", "Шифр_ПД_и_РД", "Шифр"])
            )
            _pd_section_name, _pd_razdel = _pd_detail_table_labels(
                filtered_df,
                task_col=task_col,
                cipher_col=_pd_cipher_detail,
            )
            _pd_tbl = pd.DataFrame(
                {
                    "Проект": (
                        filtered_df[project_col].astype(str).str.strip()
                        if project_col and project_col in filtered_df.columns
                        else ""
                    ),
                    "Наименование раздела работ": _pd_section_name.where(
                        _pd_section_name.astype(str).str.strip().ne(""), "—"
                    ),
                    "Раздел": _pd_razdel.where(_pd_razdel.astype(str).str.strip().ne(""), "—"),
                    "Статус": _pd_pct.map(_pd_status_label),
                    "Начало": _fmt_pd_date(_pd_sstart_dt),
                    "Базовое начало": _fmt_pd_date(_bs_dt),
                    "_dev_start_n": _pd_dev_start,
                    "Окончание": _fmt_pd_date(_sf_dt),
                    "Базовое окончание": _fmt_pd_date(_bf_dt),
                    "_dev_end_n": _pd_dev_end,
                }
            )
            if _pd_masks_delay is not None:
                _pd_tbl_m = _pd_delay_row_mask(filtered_df, _pd_masks_delay).reindex(
                    _pd_tbl.index, fill_value=False
                )
                if bool(_pd_tbl_m.any()):
                    _pd_tbl = _pd_tbl.loc[_pd_tbl_m.fillna(False)].copy()
            _pd_tbl = _pd_tbl.assign(
                _ord=pd.to_numeric(_pd_tbl["_dev_end_n"], errors="coerce").fillna(-(10**9))
            ).sort_values("_ord", ascending=True).drop(columns=["_ord"])
            _pd_tbl["Отклонение начала, дн"] = _pd_tbl["_dev_start_n"].map(_pd_fmt_deviation_days)
            _pd_tbl["Отклонение окончания, дн"] = _pd_tbl["_dev_end_n"].map(_pd_fmt_deviation_days)
            _pd_tbl = _pd_tbl.drop(columns=["_dev_start_n", "_dev_end_n"]).reset_index(drop=True)
            if _pd_tbl.empty:
                st.info("Нет данных для детальной таблицы ПД.")
            else:
                _render_styled_table_report(
                    style_dataframe_for_dark_theme(
                        _pd_tbl,
                        days_column="Отклонение окончания, дн",
                        extra_days_columns=("Отклонение начала, дн",),
                        days_positive_is_ahead=True,
                        days_deviation_gradient=True,
                    ),
                    export_df=_pd_tbl,
                    file_stem="pd_delay_detail",
                    key_prefix="pd_delay_detail",
                    full_width=True,
                )
        elif not _msp_detail_disabled:
            sort_col1, sort_col2 = st.columns([3, 1], gap="small")
            with sort_col1:
                detail_sort_column = st.selectbox(
                    "Сортировка по колонке",
                    options=list(detail_table.columns),
                    index=0,
                    key="rd_delay_detail_sort_col",
                )
            with sort_col2:
                detail_sort_desc = st.checkbox(
                    "Отображать в порядке убывания",
                    value=False,
                    key="rd_delay_detail_sort_desc",
                )

            def _detail_sort_series(table: pd.DataFrame, column: str) -> pd.Series:
                if "дата" in column.lower():
                    return pd.to_datetime(table[column], format="%d.%m.%Y", errors="coerce")
                if "дн." in column.lower():
                    return pd.to_numeric(table[column], errors="coerce")
                return table[column].astype(str).str.casefold()

            detail_table = detail_table.assign(
                _sort_key=_detail_sort_series(detail_table, detail_sort_column)
            ).sort_values(
                by=["_sort_key", "Наименование разделов работ"],
                ascending=[not detail_sort_desc, True],
                na_position="last",
            )
            detail_table = detail_table.drop(columns=["_sort_key"], errors="ignore").reset_index(
                drop=True
            )

            if _contract_source_note:
                suppress_caption(_contract_source_note)
            if detail_table.empty and not filtered_df.empty:
                st.info("Детальная таблица не собрана, хотя строки в источнике есть.")
            elif detail_table.empty:
                st.info("Нет данных для детальной таблицы.")
            else:
                _render_format_dataframe_html(
                    detail_table,
                    file_stem="rd_delay_detail",
                    key_prefix="rd_delay_detail",
                )

        # Summary table
        render_table_subheader(st, "Сводка по просрочке выдачи документации")
        if is_pd and {"_pd_plan_cnt", "_pd_fact_cnt"}.issubset(chart_data.columns):
            _pd_sum_y = y_column if y_column in chart_data.columns else chart_data.columns[0]
            _pd_sum_src = chart_data.copy()
            if "_pd_overdue_cnt" not in _pd_sum_src.columns:
                if "_pd_dev_cnt" in _pd_sum_src.columns:
                    _pd_sum_src["_pd_overdue_cnt"] = _pd_sum_src["_pd_dev_cnt"]
                else:
                    _pd_sum_src["_pd_overdue_cnt"] = 0
            summary_table = _pd_sum_src[
                [_pd_sum_y, "_pd_plan_cnt", "_pd_fact_cnt", "_pd_overdue_cnt"]
            ].copy()
            summary_table = summary_table.rename(
                columns={
                    "_pd_plan_cnt": f"План {doc_code}",
                    "_pd_fact_cnt": f"Факт {doc_code}",
                    "_pd_overdue_cnt": f"Просрочка {doc_code}",
                }
            )
            for _cnt_col in (f"План {doc_code}", f"Факт {doc_code}"):
                summary_table[_cnt_col] = summary_table[_cnt_col].apply(
                    lambda x: int(round(float(x), 0)) if pd.notna(x) else 0
                )
            _ovd_col = f"Просрочка {doc_code}"
            if _ovd_col in summary_table.columns:
                # Число разделов с «Окончание» > «Базовое окончание»; для оформления
                # как «Отклонение окончания, дн»: минус = просрочка (красный), плюс = опережение.
                summary_table[_ovd_col] = summary_table[_ovd_col].apply(
                    lambda x: int(round(float(x), 0)) if pd.notna(x) else 0
                ).map(lambda n: _pd_fmt_deviation_days(-int(n)))
        elif show_by_tasks:
            summary_table = chart_data[
                ["Задача_полная", dev_col, "% выполнения РД/ПД"]
            ].copy()
            summary_table = summary_table.rename(columns={"Задача_полная": "Задача"})
            if dev_col in summary_table.columns:
                summary_table[dev_col] = summary_table[dev_col].apply(
                    lambda x: int(round(float(x), 0)) if pd.notna(x) else ""
                )
        elif not is_pd:
            summary_table = chart_data[["Проект", dev_col, "% выполнения РД/ПД"]].copy()
            if dev_col in summary_table.columns:
                summary_table[dev_col] = summary_table[dev_col].apply(
                    lambda x: int(round(float(x), 0)) if pd.notna(x) else ""
                )
        else:
            st.info("Нет данных для сводки по просрочке.")
            summary_table = pd.DataFrame()
        if not summary_table.empty:
            if is_pd and f"Просрочка {doc_code}" in summary_table.columns:
                _render_styled_table_report(
                    style_dataframe_for_dark_theme(
                        summary_table,
                        days_column=f"Просрочка {doc_code}",
                        days_positive_is_ahead=True,
                        days_deviation_gradient=True,
                    ),
                    export_df=summary_table,
                    file_stem="rd_delay_summary",
                    key_prefix="rd_delay_summary",
                    full_width=True,
                )
            else:
                _render_format_dataframe_html(
                    summary_table,
                    file_stem="rd_delay_summary",
                    key_prefix="rd_delay_summary",
                )

        # Таблица: План окончания ПД/РД и Факт окончания ПД/РД
        # Для ПД скрыта (легаси-таблица выводит все строки MSP без ограничения и
        # засоряет страницу; нужный срез дат уже есть в детальной таблице).
        if not is_pd and (
            (plan_end_col and plan_end_col in filtered_df.columns)
            or (fact_end_col and fact_end_col in filtered_df.columns)
        ):
            st.subheader("План и факт окончания ПД/РД")
            date_df = filtered_df.copy()
            if plan_end_col and plan_end_col in date_df.columns:
                date_df["План окончания ПД/РД"] = _to_datetime_series(date_df[plan_end_col])
                date_df["План окончания ПД/РД"] = date_df["План окончания ПД/РД"].dt.strftime("%d.%m.%Y")
            else:
                date_df["План окончания ПД/РД"] = ""
            if fact_end_col and fact_end_col in date_df.columns:
                date_df["Факт окончания ПД/РД"] = _to_datetime_series(date_df[fact_end_col])
                date_df["Факт окончания ПД/РД"] = date_df["Факт окончания ПД/РД"].dt.strftime("%d.%m.%Y")
            else:
                date_df["Факт окончания ПД/РД"] = ""
            tab_cols = []
            if project_col and project_col in date_df.columns:
                tab_cols.append(project_col)
            if section_col and section_col in date_df.columns:
                tab_cols.append(section_col)
            tab_cols.extend(["План окончания ПД/РД", "Факт окончания ПД/РД"])
            date_table = date_df[[c for c in tab_cols if c in date_df.columns]].drop_duplicates()
            rename_map = {}
            if project_col and project_col in date_table.columns:
                rename_map[project_col] = "Проект"
            if section_col and section_col in date_table.columns:
                rename_map[section_col] = "Направление раздела РД"
            date_table = date_table.rename(columns=rename_map)
            st.markdown(
                plan_fact_dates_table_to_html(
                    date_table,
                    plan_date_column="План окончания ПД/РД",
                    fact_date_column="Факт окончания ПД/РД",
                ),
                unsafe_allow_html=True,
            )

            # R23-06 (стр.18): динамика накопительного плана/факта окончания ПД/РД.
            try:
                _dyn_plan = (
                    _to_datetime_series(filtered_df[plan_end_col])
                    if plan_end_col and plan_end_col in filtered_df.columns
                    else pd.Series(pd.NaT, index=filtered_df.index)
                )
                _dyn_fact = (
                    _to_datetime_series(filtered_df[fact_end_col])
                    if fact_end_col and fact_end_col in filtered_df.columns
                    else pd.Series(pd.NaT, index=filtered_df.index)
                )
                _dyn_plan_m = _dyn_plan.dropna().dt.to_period("M").dt.to_timestamp()
                _dyn_fact_m = _dyn_fact.dropna().dt.to_period("M").dt.to_timestamp()
                # П.4 (ПД): накопительный график «Динамика окончания» скрыт по требованию —
                # кривая без подписей и накопительный вид не нужны. Для РД оставляем.
                if (not _dyn_plan_m.empty or not _dyn_fact_m.empty) and not is_pd:
                    _start = min(
                        [s.min() for s in [_dyn_plan_m, _dyn_fact_m] if not s.empty]
                    )
                    _end = max(
                        [s.max() for s in [_dyn_plan_m, _dyn_fact_m] if not s.empty]
                    )
                    _today_m = pd.Timestamp(date.today()).to_period("M").to_timestamp()
                    _end = max(_end, _today_m)
                    _months = pd.date_range(_start, _end, freq="MS")
                    _plan_by = _dyn_plan_m.value_counts().reindex(_months, fill_value=0).sort_index()
                    _fact_by = _dyn_fact_m.value_counts().reindex(_months, fill_value=0).sort_index()
                    _plan_cum = _plan_by.cumsum()
                    _fact_cum = _fact_by.cumsum()
                    _fig_dyn = go.Figure()
                    _fig_dyn.add_trace(go.Scatter(
                        x=_months, y=_plan_cum.values, mode="lines+markers",
                        name="План (накопительно)",
                        line=dict(color="#5DADE2", width=2, dash="dash"),
                        hovertemplate="%{x|%m.%Y}<br>План: %{y}<extra></extra>",
                    ))
                    _fact_for_plot = _fact_cum.copy()
                    _fact_for_plot[_months > _today_m] = None
                    _fig_dyn.add_trace(go.Scatter(
                        x=_months, y=_fact_for_plot.values, mode="lines+markers",
                        name="Факт (накопительно)",
                        line=dict(color="#F39C12", width=2),
                        hovertemplate="%{x|%m.%Y}<br>Факт: %{y}<extra></extra>",
                    ))
                    _fig_dyn.add_vline(
                        x=_today_m, line_dash="dot", line_color="#7F8C8D",
                        annotation_text="Сегодня", annotation_position="top",
                    )
                    _fig_dyn.update_layout(
                        title="Динамика окончания ПД/РД (накопительно по месяцам)",
                        xaxis_title="Месяц", yaxis_title="Количество разделов",
                        hovermode="x unified",
                        legend=standard_chart_legend(),
                        height=420, margin=dict(l=10, r=10, t=60, b=40),
                    )
                    _fig_dyn.update_xaxes(tickformat="%m.%Y")
                    st.plotly_chart(
                        _fig_dyn,
                        use_container_width=True,
                        config=dict(_PLOTLY_CONFIG),
                    )
            except Exception as _e_dyn:
                suppress_caption(f"Не удалось построить динамику окончания ПД/РД: {_e_dyn}")

        # Summary metrics
        # П.2/П.4 (ПД): суммарные дни отклонений вводят в заблуждение (десятки тысяч) —
        # для ПД метрики «Сумма/Положительные/Отрицательные отклонения» (в днях) скрыты.
        # Счёт документов с просрочкой показывается в индикаторах по проектам (выше).
        if not is_pd:
            col1, col2, col3 = st.columns(3, gap="small")
            with col1:
                total_deviation = chart_data[dev_col].sum()
                st.metric(
                    "Сумма отклонений",
                    f"{total_deviation:,.0f}" if pd.notna(total_deviation) else "Н/Д",
                )
            with col2:
                positive_deviation = chart_data[chart_data[dev_col] > 0][
                    dev_col
                ].sum()
                st.metric(
                    "Положительные отклонения",
                    f"{positive_deviation:,.0f}" if pd.notna(positive_deviation) else "0",
                )
            with col3:
                negative_deviation = chart_data[chart_data[dev_col] < 0][
                    dev_col
                ].sum()
                st.metric(
                    "Отрицательные отклонения",
                    f"{negative_deviation:,.0f}" if pd.notna(negative_deviation) else "0",
                )

    except Exception as e:
        st.error(f"Ошибка при построении графика 'Просрочка выдачи {doc_code}': {str(e)}")


# ==================== DASHBOARD 8.6.5: Technique Visualization ====================
def dashboard_technique(df):

    technique_df = st.session_state.get("technique_data", None)
    resources_df = st.session_state.get("resources_data", None)

    def _cols_lc_gdrs(pdf):
        if pdf is None or getattr(pdf, "empty", True):
            return []
        return [str(c).lower().strip() for c in pdf.columns]

    def _technique_shape_from_resources(pdf_res):
        """Общая выгрузка web часто попадает только в resources_data."""
        if pdf_res is None or getattr(pdf_res, "empty", True):
            return None
        cl = _cols_lc_gdrs(pdf_res)
        if any("среднее значение за день" in c for c in cl):
            return pdf_res
        if any("среднее за недел" in c for c in cl):
            return pdf_res
        n_d = sum(1 for c in pdf_res.columns if _gdrs_header_is_dd_mm_yyyy(c))
        if n_d >= 2 and any("тип ресурсов" in c for c in cl):
            return pdf_res
        return None

    if technique_df is None or technique_df.empty:
        technique_df = _technique_shape_from_resources(resources_df)

    if technique_df is None or technique_df.empty:
        st.warning(
            "Для отображения аналитики по технике необходимо загрузить файл с данными о технике."
        )
        st.info(
            "Ожидаемые колонки: Проект, Контрагент, Период, План, Среднее за месяц или Среднее за неделю, 1–5 неделя; «Дельта» / «Отклонение %» в отчёте: отклонение и отклонение %."
        )
        return

    key_prefix = "gdrs_technique"
    work_df = technique_df.copy()
    work_df.columns = [
        str(c).replace("\ufeff", "").replace("\n", " ").replace("\r", " ").strip()
        for c in work_df.columns
    ]
    _plan_src_t = _gdrs_resolve_plan_column(work_df)
    if _plan_src_t and _plan_src_t != "План":
        work_df["План"] = work_df[_plan_src_t]

    date_cols_found = [c for c in work_df.columns if _gdrs_header_is_dd_mm_yyyy(c)]
    _daily_dates: list[pd.Timestamp] = []
    if date_cols_found:
        _hdr_norm = (
            pd.Series(date_cols_found)
            .astype(str)
            .str.replace(r"\.{2,3}", ".", regex=True)
            .str.strip()
        )
        _parsed = pd.to_datetime(_hdr_norm, errors="coerce", dayfirst=True).dropna()
        if not _parsed.empty:
            _daily_dates = sorted(
                list({pd.Timestamp(d).normalize() for d in _parsed.tolist()})
            )
    # Даты из заголовков (ДД.ММ.ГГГГ / DD.MM.YY) — для фильтра периода по дням.
    _daily_dates: list[pd.Timestamp] = []
    if date_cols_found:
        _hdr_norm = (
            pd.Series(date_cols_found)
            .astype(str)
            .str.replace(r"\.{2,3}", ".", regex=True)
            .str.strip()
        )
        _daily_dates = [
            pd.Timestamp(x).normalize()
            for x in pd.to_datetime(_hdr_norm, errors="coerce", dayfirst=True).dropna().tolist()
        ]
        _daily_dates = sorted(list({d for d in _daily_dates}))
    _period_missing_or_empty = (
        "Период" not in work_df.columns
        or work_df["Период"].astype(str).str.strip().replace({"nan": "", "None": ""}).eq("").all()
    )
    if date_cols_found and _period_missing_or_empty:
        # Формируем период по датам заголовков (для файлов, где период не задан отдельной колонкой).
        _hdr_ser = pd.Series(date_cols_found).astype(str).str.replace(r"\.{2,3}", ".", regex=True)
        _parsed_header_dates = pd.to_datetime(
            _hdr_ser, errors="coerce", dayfirst=True
        ).dropna()
        _period_from_headers = None
        if not _parsed_header_dates.empty:
            _period_from_headers = _parsed_header_dates.iloc[0].to_period("M")

        id_cols = [c for c in ["Проект", "Контрагент", "тип ресурсов", "data_source"]
                   if c in work_df.columns]
        avg_month_col = None
        for c in work_df.columns:
            cl = str(c).lower()
            if "среднее" in cl and ("за месяц" in cl or "количество ресурсов" in cl):
                vals = pd.to_numeric(work_df[c], errors="coerce")
                if vals.notna().any() and (vals != 0).any():
                    avg_month_col = c
                    break
        if not avg_month_col:
            for c in reversed(list(work_df.columns)):
                cl = str(c).lower()
                if "среднее" in cl and not cl.startswith("тип"):
                    vals = pd.to_numeric(work_df[c], errors="coerce")
                    if vals.notna().any() and (vals != 0).any():
                        avg_month_col = c
                        break

        for dc in date_cols_found:
            work_df[dc] = pd.to_numeric(work_df[dc], errors="coerce")

        if id_cols:
            agg_spec = {dc: (dc, "mean") for dc in date_cols_found}
            if "План" in work_df.columns and "План" not in id_cols:
                agg_spec["План"] = ("План", "first")
            for _wk in range(1, 6):
                wn = f"{_wk} неделя"
                if wn in work_df.columns and wn not in id_cols:
                    agg_spec[wn] = (wn, "first")
            agg = work_df.groupby(id_cols, dropna=False).agg(**agg_spec).reset_index()
            agg["Среднее за месяц"] = agg[date_cols_found].mean(axis=1).round(1)
            if _period_from_headers is not None:
                agg["Период"] = _period_from_headers
            if avg_month_col and avg_month_col in work_df.columns:
                month_avg = work_df.groupby(id_cols, dropna=False)[avg_month_col].first().reset_index()
                month_avg["_avg_num"] = pd.to_numeric(month_avg[avg_month_col], errors="coerce")
                if month_avg["_avg_num"].notna().any() and (month_avg["_avg_num"] != 0).any():
                    agg["Среднее за месяц"] = month_avg["_avg_num"].values
            agg = agg.drop(columns=date_cols_found, errors="ignore")
            work_df = agg
        else:
            work_df["Среднее за месяц"] = work_df[date_cols_found].mean(axis=1).round(1)
            if _period_from_headers is not None:
                work_df["Период"] = _period_from_headers
            work_df = work_df.drop(columns=date_cols_found, errors="ignore")

    def find_column_by_partial(df, possible_names):
        """Find column by possible names (exact or partial match)"""
        for col in df.columns:
            col_lower = str(col).lower().strip()
            for name in possible_names:
                name_lower = str(name).lower().strip()
                if (
                    name_lower == col_lower
                    or name_lower in col_lower
                    or col_lower in name_lower
                ):
                    return col
        return None

    # sample_resources_data.csv: Проект, Контрагент, Период, План, Среднее за месяц, 1–5 неделя, Дельта, Отклонение %
    # Use Russian column names directly

    # Check required columns - Контрагент is essential
    if "Контрагент" not in work_df.columns:
        # Try to find contractor column by partial match
        contractor_col = find_column_by_partial(
            work_df,
            [
                "Контрагент",
                "контрагент",
                "Подразделение",
                "подразделение",
                "contractor",
            ],
        )
        if contractor_col:
            work_df["Контрагент"] = work_df[contractor_col]
        else:
            st.error(f"Отсутствует необходимая колонка 'Контрагент'")
            st.info(f"Доступные колонки: {', '.join(work_df.columns)}")
            return

    # Find week columns dynamically - also try partial match
    week_columns = []
    for week_num in range(1, 7):
        week_col = f"{week_num} неделя"
        if week_col in work_df.columns:
            week_columns.append(week_col)
        else:
            # Try to find by partial match
            found_col = find_column_by_partial(
                work_df,
                [
                    week_col,
                    f"{week_num} недел",
                    f"недел {week_num}",
                    f"week {week_num}",
                ],
            )
            if found_col:
                week_columns.append(found_col)

    # Check if we have any data
    if work_df.empty:
        st.warning("⚠️ Данные пусты после обработки.")
        return

    # Process numeric columns
    # Process План
    if "План" in work_df.columns:
        work_df["План_numeric"] = pd.to_numeric(
            work_df["План"].astype(str).str.replace(",", ".").str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
    else:
        work_df["План_numeric"] = 0

    # Process week columns - convert to numeric, handle empty strings
    for week_col in week_columns:
        work_df[f"{week_col}_numeric"] = pd.to_numeric(
            work_df[week_col]
            .astype(str)
            .str.replace(",", ".")
            .str.replace(" ", "")
            .replace("", "0"),
            errors="coerce",
        ).fillna(0)

    # Факт: при наличии недельных колонок берём сумму 1..5 недели (приоритетнее средних).
    if week_columns:
        week_numeric_cols = [f"{col}_numeric" for col in week_columns]
        work_df["week_sum"] = work_df[week_numeric_cols].sum(axis=1)
    elif "Среднее за месяц" in work_df.columns:
        work_df["Среднее_за_месяц_numeric"] = pd.to_numeric(
            work_df["Среднее за месяц"]
            .astype(str)
            .str.replace(",", ".")
            .str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
        work_df["week_sum"] = work_df["Среднее_за_месяц_numeric"]
    elif "Среднее за неделю" in work_df.columns:
        work_df["Среднее_за_неделю_numeric"] = pd.to_numeric(
            work_df["Среднее за неделю"]
            .astype(str)
            .str.replace(",", ".")
            .str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
        _nw = len(week_columns) if week_columns else 4
        work_df["week_sum"] = work_df["Среднее_за_неделю_numeric"] * _nw
    else:
        work_df["week_sum"] = 0

    # Process Дельта (Delta) if available - try to find column by partial match
    delta_col = None
    if "Дельта" in work_df.columns:
        delta_col = "Дельта"
    else:
        delta_col = find_column_by_partial(
            work_df, ["Дельта", "дельта", "delta", "Delta", "Дельта (без %)"]
        )

    if delta_col and delta_col in work_df.columns:
        work_df["Дельта_numeric"] = pd.to_numeric(
            work_df[delta_col].astype(str).str.replace(",", ".").str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
    else:
        # Calculate delta as plan - fact (week_sum)
        work_df["Дельта_numeric"] = work_df["План_numeric"] - work_df["week_sum"]

    # Process Отклонение % (Delta %) if available - extract numeric value from percentage string
    # Try to find column by partial match
    delta_pct_col = None
    if "Отклонение %" in work_df.columns:
        delta_pct_col = "Отклонение %"
    else:
        delta_pct_col = find_column_by_partial(
            work_df,
            [
                "Дельта (%)",
                "Отклонение %",
                "Дельта %",
                "дельта (%)",
                "дельта %",
                "Delta %",
                "delta %",
                "Дельта(%)",
                "Дельта%",
            ],
        )

    if delta_pct_col and delta_pct_col in work_df.columns:

        def extract_percentage(value):
            """Extract numeric value from percentage string like '-90%' or '90%', or numeric value"""
            if pd.isna(value):
                return 0
            # If already numeric, return as is
            if isinstance(value, (int, float)):
                return float(value)
            # Otherwise, try to extract from string
            value_str = str(value).strip()
            # Remove % sign and convert to float
            value_str = value_str.replace("%", "").replace(",", ".").replace(" ", "")
            try:
                return float(value_str)
            except:
                return 0

        work_df["Дельта_процент_numeric"] = work_df[delta_pct_col].apply(
            extract_percentage
        )
    else:
        # Calculate delta percentage if we have delta and plan
        work_df["Дельта_процент_numeric"] = 0.0
        if "Дельта_numeric" in work_df.columns and "План_numeric" in work_df.columns:
            mask = work_df["План_numeric"] != 0
            work_df.loc[mask, "Дельта_процент_numeric"] = (
                work_df.loc[mask, "Дельта_numeric"] / work_df.loc[mask, "План_numeric"]
            ) * 100
        work_df["Дельта_процент_numeric"] = work_df["Дельта_процент_numeric"].fillna(0)

    # Find Проект column
    # Период: нельзя искать через «месяц» в подстроке — матчится «среднее … за месяц» и ломает графики.
    src_period = _gdrs_resolve_period_column(work_df)
    if src_period:
        if src_period != "Период":
            def parse_period(period_val):
                if pd.isna(period_val):
                    return None
                period_str = str(period_val).strip()
                if "." in period_str:
                    parts = period_str.split(".")
                    if len(parts) >= 2:
                        month_part = parts[0].strip()
                        year_part = parts[1].strip()
                        try:
                            year = int(year_part)
                            if year < 100:
                                year = 2000 + year
                            return f"{month_part}.{year}"
                        except Exception:
                            pass
                return period_str

            work_df["Период"] = work_df[src_period].apply(parse_period)

    has_plan_data = (
        "План_numeric" in work_df.columns
        and work_df["План_numeric"].sum() > 0
    )

    project_col = None
    if "Проект" in work_df.columns:
        project_col = "Проект"
    else:
        project_col = find_column_by_partial(
            work_df, ["Проект", "проект", "project", "Project"]
        )

    period_col = _gdrs_resolve_period_column(work_df)
    # Жёсткий fallback: если «Период» не найден, восстанавливаем его из датовых заголовков.
    if period_col is None:
        _date_cols_fb = [c for c in work_df.columns if _gdrs_header_is_dd_mm_yyyy(c)]
        if _date_cols_fb:
            _hdr_fb = pd.Series(_date_cols_fb).astype(str).str.replace(r"\.{2,3}", ".", regex=True)
            _dt_fb = pd.to_datetime(_hdr_fb, errors="coerce", dayfirst=True).dropna()
            if not _dt_fb.empty:
                work_df = work_df.copy()
                work_df["Период"] = _dt_fb.iloc[0].to_period("M")
                period_col = "Период"

    col1, col2, col3 = st.columns(3, gap="small")

    with col1:
        if project_col and project_col in work_df.columns:
            all_projects = _unique_project_labels_for_select(work_df[project_col])
            selected_projects, _ = project_filter_multiselect(st, all_projects,
                key="technique_projects",
            )
        else:
            selected_projects = []
            st.info("Колонка 'Проект' не найдена")

    with col2:
        if "Контрагент" in work_df.columns:
            contractors = ["Все"] + sorted(
                work_df["Контрагент"].dropna().unique().tolist()
            )
            selected_contractor = st.selectbox(
                "Контрагент", contractors, key="technique_contractor"
            )
        else:
            selected_contractor = "Все"
            st.info("Колонка 'Контрагент' не найдена")

    selected_periods = []
    selected_period_from = "Все"
    selected_period_to = "Все"
    period_value_by_label = {}
    period_labels_sorted = []

    def _gdrs_period_value_to_ts(v):
        if v is None:
            return pd.NaT
        try:
            ts = pd.to_datetime(v, errors="coerce", dayfirst=True)
            if pd.notna(ts):
                return ts.normalize()
        except Exception:
            pass
        s = str(v).strip().lower()
        if not s:
            return pd.NaT
        # "ноя.25" / "ноя 25" / "ноябрь 2025" -> 01.MM.YYYY
        m = re.match(r"^([а-яa-z\.]+)[\s\.\-_/]*(\d{2,4})$", s, flags=re.IGNORECASE)
        if m:
            mon_raw, yy_raw = m.group(1), m.group(2)
            mon_raw = mon_raw.replace(".", "")
            mon_map = {
                "янв": 1, "январь": 1,
                "фев": 2, "февраль": 2,
                "мар": 3, "март": 3,
                "апр": 4, "апрель": 4,
                "май": 5, "мая": 5,
                "июн": 6, "июнь": 6,
                "июл": 7, "июль": 7,
                "авг": 8, "август": 8,
                "сен": 9, "сент": 9, "сентябрь": 9,
                "окт": 10, "октябрь": 10,
                "ноя": 11, "ноябрь": 11,
                "дек": 12, "декабрь": 12,
                "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
                "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
            }
            mm = mon_map.get(mon_raw)
            if mm:
                y = int(yy_raw)
                if y < 100:
                    y = 2000 + y
                try:
                    return pd.Timestamp(year=y, month=mm, day=1)
                except Exception:
                    return pd.NaT
        return pd.NaT

    with col3:
        if period_col and period_col in work_df.columns:
            raw_vals = (
                work_df[period_col].dropna().astype(str).str.strip().tolist()
            )
            raw_vals = [v for v in raw_vals if v]
            uniq_vals = sorted(set(raw_vals))
            if uniq_vals:
                parsed = [(v, _gdrs_period_value_to_ts(v)) for v in uniq_vals]
                has_any_ts = any(pd.notna(ts) for _, ts in parsed)
                if has_any_ts:
                    parsed.sort(key=lambda it: (0, it[1]) if pd.notna(it[1]) else (1, str(it[0])))
                    for v, ts in parsed:
                        label = ts.strftime("%d.%m.%Y") if pd.notna(ts) else str(v)
                        if label not in period_value_by_label:
                            period_value_by_label[label] = v
                            period_labels_sorted.append(label)
                    _gdrs_dates = [
                        ts.date() for _, ts in parsed if pd.notna(ts)
                    ]
                    if _gdrs_dates:
                        _gmin, _gmax = min(_gdrs_dates), max(_gdrs_dates)
                        _gf, _gt = period_date_range_input(
                            st,
                            f"{key_prefix}_period_range",
                            min_value=_gmin,
                            max_value=_gmax,
                            default=(_gmin, _gmax),
                        )
                        if _gf is not None and _gt is not None:
                            if _gf > _gt:
                                _gf, _gt = _gt, _gf
                            selected_periods = [
                                v
                                for v, ts in parsed
                                if pd.notna(ts)
                                and _gf <= ts.date() <= _gt
                            ]
                else:
                    period_labels_sorted = sorted(uniq_vals)
                    period_value_by_label = {v: v for v in period_labels_sorted}
                    selected_period_from = st.selectbox(
                        "Период",
                        ["Все"] + period_labels_sorted,
                        key=f"{key_prefix}_period_from",
                    )
                    selected_period_to = st.selectbox(
                        "",
                        ["Все"] + period_labels_sorted,
                        key=f"{key_prefix}_period_to",
                        label_visibility="collapsed",
                    )
                    if period_labels_sorted:
                        i_from = period_labels_sorted.index(selected_period_from) if selected_period_from in period_labels_sorted else 0
                        i_to = period_labels_sorted.index(selected_period_to) if selected_period_to in period_labels_sorted else (len(period_labels_sorted) - 1)
                        if selected_period_from == "Все":
                            i_from = 0
                        if selected_period_to == "Все":
                            i_to = len(period_labels_sorted) - 1
                        if i_from > i_to:
                            i_from, i_to = i_to, i_from
                        selected_periods = [
                            period_value_by_label[lbl]
                            for lbl in period_labels_sorted[i_from : i_to + 1]
                        ]
            else:
                st.info("Нет значений периода")
        else:
            st.info("Колонка 'Период' не найдена")
    # Apply filters
    filtered_df = work_df.copy()
    if selected_projects and project_col and project_col in filtered_df.columns:
        selected_project_keys = {
            _project_filter_norm_key(p)
            for p in selected_projects
            if _project_filter_norm_key(p)
        }
        project_mask = filtered_df[project_col].map(_project_filter_norm_key).isin(selected_project_keys)
        filtered_df = filtered_df[project_mask]
    if selected_contractor != "Все" and "Контрагент" in filtered_df.columns:
        # Use string comparison with strip to handle whitespace
        filtered_df = filtered_df[
            filtered_df["Контрагент"].astype(str).str.strip()
            == str(selected_contractor).strip()
        ]

    if filtered_df.empty:
        st.info("Нет данных для отображения с выбранными фильтрами.")
        return

    # Ensure Контрагент column exists and has values
    if (
        "Контрагент" not in filtered_df.columns
        or filtered_df["Контрагент"].isna().all()
    ):
        st.error("Колонка 'Контрагент' отсутствует или пуста после фильтрации.")
        return

    # Remove rows where Контрагент is NaN before grouping
    filtered_df = filtered_df[filtered_df["Контрагент"].notna()].copy()

    if filtered_df.empty:
        st.info("Нет данных с указанными контрагентами после фильтрации.")
        return

    # Определяем список проектов для обработки
    if selected_projects and project_col and project_col in filtered_df.columns:
        projects_to_process = selected_projects
    else:
        # Если проекты не выбраны или колонка не найдена, обрабатываем все проекты
        if project_col and project_col in filtered_df.columns:
            projects_to_process = sorted(
                filtered_df[project_col].dropna().unique().tolist()
            )
        else:
            projects_to_process = ["Все проекты"]

    # Гистограммы: факт по периодам (люди и техника отдельно), количество и %
    period_col_hist = _gdrs_resolve_period_column(filtered_df)
    if period_col_hist and "week_sum" in filtered_df.columns:
        # Линейный график (по ТЗ): план — 100% (синий), факт — % от плана (оранжевый), округление до целых %.
        try:
            _p = pd.to_numeric(filtered_df.get("План_numeric"), errors="coerce").fillna(0.0)
            _f = pd.to_numeric(filtered_df.get("week_sum"), errors="coerce").fillna(0.0)
            _pp = pd.to_datetime(filtered_df[period_col_hist], errors="coerce", dayfirst=True)
            if _pp.notna().any():
                _tmp = pd.DataFrame({"period": _pp.dt.to_period("M"), "plan": _p, "fact": _f})
                _by = _tmp.groupby("period", as_index=False).agg({"plan": "sum", "fact": "sum"})
                _by = _by[_by["plan"] > 0].copy()
                if not _by.empty:
                    _by["period_str"] = _by["period"].map(format_period_ru)
                    _by["fact_pct"] = (_by["fact"] / _by["plan"] * 100.0).clip(lower=0.0)
                    _by["fact_pct_int"] = _by["fact_pct"].map(lambda x: int(np.ceil(float(x))) if pd.notna(x) else 0)
                    fig_pct = go.Figure()
                    fig_pct.add_trace(
                        go.Scatter(
                            x=_by["period_str"],
                            y=[100] * len(_by.index),
                            name="План",
                            mode="lines+markers+text",
                            line=dict(color="#3498db", width=3),
                            marker=dict(size=8, color="#3498db"),
                            text=["100"] * len(_by.index),
                            textposition="top center",
                            textfont=dict(color="white", size=10),
                            hovertemplate="Период: %{x}<br>План: 100%<extra></extra>",
                            cliponaxis=False,
                        )
                    )
                    fig_pct.add_trace(
                        go.Scatter(
                            x=_by["period_str"],
                            y=_by["fact_pct_int"],
                            name="Факт",
                            mode="lines+markers+text",
                            line=dict(color="#e67e22", width=3),
                            marker=dict(size=8, color="#e67e22"),
                            text=[str(v) for v in _by["fact_pct_int"].tolist()],
                            textposition="top center",
                            textfont=dict(color="white", size=10),
                            customdata=np.stack(
                                [
                                    _by["plan"].map(lambda v: int(np.ceil(float(v))) if pd.notna(v) else 0).values,
                                    _by["fact"].map(lambda v: int(np.ceil(float(v))) if pd.notna(v) else 0).values,
                                ],
                                axis=-1,
                            ),
                            hovertemplate="Период: %{x}<br>План: %{customdata[0]}<br>Факт: %{customdata[1]}<br>Факт/план: %{y}%<extra></extra>",
                            cliponaxis=False,
                        )
                    )
                    fig_pct.update_layout(
                        height=460,
                        showlegend=True,
                        legend=standard_chart_legend(),
                        xaxis_title="Период",
                        yaxis_title="Факт к плану, %",
                        margin=dict(l=56, r=140, t=72, b=120),
                        xaxis=dict(automargin=True),
                        yaxis=dict(automargin=True),
                        uniformtext=dict(minsize=7, mode="show"),
                    )
                    fig_pct = apply_chart_background(fig_pct, skip_uniformtext=True)
                    try:
                        fig_pct.update_layout(
                            margin=dict(l=56, r=150, t=88, b=140),
                            uniformtext=dict(minsize=6, mode="show"),
                        )
                    except Exception:
                        pass
                    render_chart(fig_pct, key=f"{key_prefix}_planfact_pct_line", caption_below="Динамика: план = 100%, факт = % от плана (округление вверх).")
        except Exception:
            pass

        sources_hist = []
        if "data_source" in filtered_df.columns:
            sources_hist = filtered_df["data_source"].dropna().unique().tolist()
        else:
            sources_hist = [None]
        source_labels_hist = []
        for s in sources_hist:
            if s is None:
                source_labels_hist.append("Данные")
            elif str(s).strip() == "Ресурсы":
                source_labels_hist.append("Люди (ресурсы)")
            elif str(s).strip() == "Техника":
                source_labels_hist.append("Техника")
            else:
                source_labels_hist.append(str(s))
        hist_cols = st.columns(max(1, len(sources_hist, gap="small")))
        for idx, (src, label) in enumerate(zip(sources_hist, source_labels_hist)):
            if src is None:
                df_hist = filtered_df.copy()
            else:
                df_hist = filtered_df[_gdrs_match_data_source(filtered_df["data_source"], src)].copy()
            if df_hist.empty:
                with hist_cols[idx]:
                    st.info(f"**{label}** — нет данных для графика «Факт по периодам».")
                continue
            # Колонки по неделям (1 неделя_numeric, 2 неделя_numeric, ...)
            week_numeric_cols_hist = [
                c for c in df_hist.columns
                if isinstance(c, str) and "_numeric" in c and "недел" in c.lower()
            ]
            if not week_numeric_cols_hist:
                for i in range(1, 6):
                    cn = f"{i} неделя_numeric"
                    if cn in df_hist.columns:
                        week_numeric_cols_hist.append(cn)
            week_numeric_cols_hist = sorted(week_numeric_cols_hist, key=lambda c: (
                int(c.split()[0]) if c.split() and c.split()[0].isdigit() else 99
            ))
            if week_numeric_cols_hist:
                # Группировка по периоду, точки — по неделям: melt по неделям, затем groupby(период, неделя)
                id_vars = [period_col_hist]
                value_vars = [c for c in week_numeric_cols_hist if c in df_hist.columns]
                if value_vars:
                    long_df = df_hist[id_vars + value_vars].melt(
                        id_vars=id_vars,
                        value_vars=value_vars,
                        var_name="Неделя",
                        value_name="Факт",
                    )
                    long_df["Неделя"] = long_df["Неделя"].str.replace("_numeric", "").str.strip()
                    long_df["Факт"] = pd.to_numeric(long_df["Факт"], errors="coerce").fillna(0)
                    by_period_week = (
                        long_df.groupby([period_col_hist, "Неделя"], as_index=False)["Факт"]
                        .sum()
                    )
                    by_period_week["Период_стр"] = by_period_week[period_col_hist].astype(str).str.strip()
                    by_period_week = _gdrs_point_pct_of_period_plan(
                        by_period_week, df_hist, period_col_hist, "Факт"
                    )
                else:
                    by_period_week = None
            else:
                by_period_week = None
            if by_period_week is not None and not by_period_week.empty:
                fig_hist = go.Figure()
                is_resources = "Ресурсы" in label or "Люди" in label
                base_color = "#2E86AB" if is_resources else "#F39C12"
                weeks = by_period_week["Неделя"].unique().tolist()
                # Люди и техника: точечная диаграмма — одна линия через все точки по порядку (период → неделя)
                by_period_week = by_period_week.copy()
                by_period_week["x_label"] = (
                    by_period_week["Период_стр"].astype(str)
                    + " — "
                    + by_period_week["Неделя"].astype(str).str.replace(" неделя", "н", regex=False)
                )
                # Короткая подпись оси X: длинный вариант оставляем в hover.
                _week_num = (
                    by_period_week["Неделя"]
                    .astype(str)
                    .str.extract(r"(\d+)", expand=False)
                    .fillna("?")
                )
                by_period_week["x_tick"] = (
                    by_period_week["Период_стр"].astype(str) + " · н" + _week_num
                )
                by_period_week = by_period_week.sort_values([period_col_hist, "Неделя"])
                x_order = by_period_week["x_label"].tolist()
                _mk_week_lbl = lambda r: (
                    f"{int(r['Факт'])} ({int(np.ceil(float(r['%'])))}%)"
                )
                _mk_week_hover = lambda r: (
                    f"Факт: {int(r['Факт'])}<br>"
                    f"План (период): {int(np.ceil(float(r['План_период']))) if pd.notna(r.get('План_период')) and float(r.get('План_период') or 0) > 0 else '—'}<br>"
                    f"К плану: {int(np.ceil(float(r['%'])))}%"
                )
                fig_hist.add_trace(
                    go.Scatter(
                        x=by_period_week["x_label"],
                        y=by_period_week["Факт"],
                        name="Факт",
                        mode="lines+markers+text",
                        line=dict(color=base_color, width=2),
                        marker=dict(size=10, color=base_color, line=dict(width=1, color="white")),
                        text=[_mk_week_lbl(r) for _, r in by_period_week.iterrows()],
                        textposition="top center",
                        textfont=dict(size=9, color="white"),
                        hovertext=[_mk_week_hover(r) for _, r in by_period_week.iterrows()],
                        hovertemplate="%{x}<br>%{hovertext}<extra></extra>",
                        connectgaps=False,
                        cliponaxis=False,
                    )
                )
                fig_hist.update_layout(
                    title_text="",
                    xaxis_title="Период — неделя",
                    yaxis_title="Количество",
                    height=520,
                    showlegend=False,
                    margin=dict(l=56, r=28, t=88, b=230),
                    uniformtext=dict(minsize=7, mode="show"),
                    xaxis=dict(
                        tickangle=-35,
                        categoryorder="array",
                        categoryarray=x_order,
                        tickmode="array",
                        tickvals=by_period_week["x_label"].tolist(),
                        ticktext=by_period_week["x_tick"].tolist(),
                        automargin=True,
                    ),
                    yaxis=dict(automargin=True, rangemode="tozero"),
                )
                fig_hist = apply_chart_background(fig_hist)
                with hist_cols[idx]:
                    render_chart(
                        fig_hist,
                        key=f"{key_prefix}_hist_period_{idx}",
                        caption_below=(
                            f"Факт по периодам (недели), % к сумме плана периода (округление вверх): {label}"
                        ),
                    )
            else:
                # Нет колонок по неделям — один столбец/точка на период (сумма)
                by_period = (
                    df_hist.groupby(period_col_hist, as_index=False)["week_sum"]
                    .sum()
                    .rename(columns={"week_sum": "Факт"})
                )
                by_period["Период_стр"] = by_period[period_col_hist].astype(str).str.strip()
                by_period = _gdrs_point_pct_of_period_plan(
                    by_period, df_hist, period_col_hist, "Факт"
                )
                by_period = by_period.sort_values(period_col_hist)
                with hist_cols[idx]:
                    fig_hist = go.Figure()
                    is_resources_fb = "Ресурсы" in label or "Люди" in label
                    if is_resources_fb:
                        fig_hist.add_trace(
                            go.Scatter(
                                x=by_period["Период_стр"],
                                y=by_period["Факт"],
                                mode="markers+text",
                                name="Факт",
                                marker=dict(size=14, color="#2E86AB", line=dict(width=1, color="white")),
                                text=[
                                    f"{int(row['Факт'])} ({int(np.ceil(float(row['%'])))}%)"
                                    for _, row in by_period.iterrows()
                                ],
                                textposition="top center",
                                textfont=dict(size=11, color="white"),
                                cliponaxis=False,
                            )
                        )
                    else:
                        fig_hist.add_trace(
                            go.Bar(
                                x=by_period["Период_стр"],
                                y=by_period["Факт"],
                                text=[
                                    f"{int(row['Факт'])} ({int(np.ceil(float(row['%'])))}%)"
                                    for _, row in by_period.iterrows()
                                ],
                                textposition="outside",
                                textfont=dict(size=11, color="white"),
                                marker_color="#F39C12",
                                name="Факт",
                                cliponaxis=False,
                            )
                        )
                    fig_hist.update_layout(
                        title_text="",
                        xaxis_title="Период",
                        yaxis_title="Количество",
                        height=440,
                        showlegend=False,
                        margin=dict(l=56, r=28, t=56, b=168),
                        uniformtext=dict(minsize=7, mode="show"),
                        xaxis=dict(tickangle=-45, automargin=True),
                        yaxis=dict(automargin=True),
                    )
                    fig_hist = _apply_finance_bar_label_layout(fig_hist)
                    try:
                        fig_hist.update_layout(
                            uniformtext=dict(minsize=6, mode="show"),
                            margin=dict(l=56, r=36, t=88, b=180),
                        )
                    except Exception:
                        pass
                    fig_hist = apply_chart_background(fig_hist)
                    render_chart(
                        fig_hist,
                        key=f"{key_prefix}_hist_period_fallback_{idx}",
                        caption_below=f"Факт по периодам, % к сумме плана периода (округление вверх): {label}",
                    )

    elif "week_sum" in filtered_df.columns:
        # Нет отдельной колонки периода (типично для web-выгрузки только с датами в заголовках): факт по подрядчикам
        with st.expander("Нет колонки «Период» в файле", expanded=False):
            suppress_caption(
                "Показан суммарный факт по подрядчикам (агрегация без оси периода в данных)."
            )
            suppress_caption(
                "Если суммы «План» и «Факт» по контрагенту почти совпадают: в части web-выгрузок колонка «План» "
                "задана на строку как норма/лимит рядом с теми же неделями, либо строки дублируют одну и ту же "
                "запись — тогда агрегированные суммы сходятся. Сверьте исходный файл: уникальность строк "
                "(проект·контрагент·период), что именно означает «План» в шапке и нет ли копирования блоков."
            )
        sources_fb = []
        if "data_source" in filtered_df.columns:
            sources_fb = filtered_df["data_source"].dropna().unique().tolist()
        else:
            sources_fb = [None]
        labels_fb = []
        for s in sources_fb:
            if s is None:
                labels_fb.append("Данные")
            elif str(s).strip().lower() in ("ресурсы", "ресурс"):
                labels_fb.append("Люди (ресурсы)")
            elif str(s).strip().lower() in ("техника", "tech", "technique"):
                labels_fb.append("Техника")
            else:
                labels_fb.append(str(s))
        fb_cols = st.columns(max(1, len(sources_fb, gap="small")))
        for fbi, (src_fb, lab_fb) in enumerate(zip(sources_fb, labels_fb)):
            if src_fb is None:
                df_fb = filtered_df.copy()
            else:
                df_fb = filtered_df[_gdrs_match_data_source(filtered_df["data_source"], src_fb)].copy()
            if df_fb.empty or "Контрагент" not in df_fb.columns:
                with fb_cols[fbi]:
                    st.info(f"**{lab_fb}** — нет данных для «Факт по подрядчикам».")
                continue
            agg_map = {
                "week_sum": lambda s: pd.to_numeric(s, errors="coerce").fillna(0).sum(),
            }
            if "План_numeric" in df_fb.columns:
                agg_map["План_numeric"] = "sum"
            by_c = df_fb.groupby("Контрагент", as_index=False).agg(agg_map)
            by_c = by_c.rename(columns={"week_sum": "Факт"})
            if "План_numeric" not in by_c.columns:
                by_c["План"] = 0.0
            else:
                by_c["План"] = pd.to_numeric(by_c["План_numeric"], errors="coerce").fillna(0.0)
                by_c = by_c.drop(columns=["План_numeric"], errors="ignore")
            by_c["Факт"] = pd.to_numeric(by_c["Факт"], errors="coerce").fillna(0.0)
            by_c = by_c[(by_c["Факт"].abs() > 0) | (by_c["План"].abs() > 0)].sort_values(
                "Факт", ascending=True
            )
            if by_c.empty:
                with fb_cols[fbi]:
                    st.info(f"**{lab_fb}** — нет ненулевых значений по подрядчикам.")
                continue
            tot = float(by_c["Факт"].sum())
            by_c["pct"] = (by_c["Факт"] / tot * 100.0).round(1) if tot else 0.0
            is_res = "ресурс" in lab_fb.lower() or "люди" in lab_fb.lower()
            col_bar = "#2ecc71" if is_res else "#e67e22"
            col_plan = "#5dade2" if is_res else "#af7ac5"
            _h = max(420, int(28 * max(6, len(by_c))) )
            fig_fb = go.Figure()
            show_plan = float(by_c["План"].sum()) > 0
            _plan_vals = by_c["План"].to_numpy(dtype=float, copy=False)
            _fact_vals = by_c["Факт"].to_numpy(dtype=float, copy=False)
            _near = np.isfinite(_plan_vals) & np.isfinite(_fact_vals) & (
                np.abs(_plan_vals - _fact_vals) <= np.maximum(1.0, np.abs(_plan_vals) * 0.05)
            )
            _near_n = int(np.sum(_near)) if _near.size else 0
            if show_plan:
                _pdiff = _fact_vals - _plan_vals
                _ppct = np.where(
                    np.abs(_plan_vals) > 1e-9,
                    (_pdiff / _plan_vals) * 100.0,
                    np.nan,
                )
                fig_fb.add_trace(
                    go.Bar(
                        y=by_c["Контрагент"].astype(str),
                        x=by_c["План"],
                        name="План (договор)",
                        orientation="h",
                        marker=dict(color=col_plan, line=dict(width=1, color="#aed6f1")),
                        text=[f"{int(round(p))}" if pd.notna(p) else "" for p in by_c["План"]],
                        textposition="outside",
                        textfont=dict(size=10, color="white"),
                        customdata=np.stack(
                            [_fact_vals, _pdiff, _ppct],
                            axis=-1,
                        ),
                        hovertemplate=(
                            "<b>%{y}</b><br>План (договор): %{x:,.0f}"
                            "<br>Факт: %{customdata[0]:,.0f}"
                            "<br>Δ (факт−план): %{customdata[1]:,.0f}"
                            "<br>Отклонение к плану: %{customdata[2]:.1f}%<extra></extra>"
                        ),
                    )
                )
            # R23-05 стр.12: градиент красный при отставании факта от плана, салатовый при выполнении.
            if show_plan:
                _fact_colors = [
                    _gdrs_fact_bar_color(float(p), float(f))
                    for p, f in zip(_plan_vals, _fact_vals)
                ]
            else:
                _fact_colors = col_bar
            # Проект для hover (если в df_fb есть колонка).
            _proj_col_fb = None
            for _pc in ("project name", "Проект", "project_name"):
                if _pc in df_fb.columns:
                    _proj_col_fb = _pc
                    break
            if _proj_col_fb:
                _proj_by_ka = (
                    df_fb.groupby("Контрагент")[_proj_col_fb]
                    .apply(lambda s: ", ".join(sorted({str(x) for x in s.dropna() if str(x).strip()}))[:120])
                    .to_dict()
                )
                _proj_list = [_proj_by_ka.get(k, "—") for k in by_c["Контрагент"].astype(str).tolist()]
            else:
                _proj_list = ["—"] * len(by_c)
            fig_fb.add_trace(
                go.Bar(
                    y=by_c["Контрагент"].astype(str),
                    x=by_c["Факт"],
                    name="Факт",
                    orientation="h",
                    marker=dict(color=_fact_colors, line=dict(width=1, color="white")),
                    text=[
                        f"{int(r['Факт'])} ({r['pct']}%)" for _, r in by_c.iterrows()
                    ],
                    textposition="outside",
                    textfont=dict(size=11, color="white"),
                    customdata=np.stack(
                        [
                            by_c["План"].values,
                            np.where(
                                by_c["План"].abs() > 1e-9,
                                (by_c["Факт"] - by_c["План"]) / by_c["План"] * 100.0,
                                np.nan,
                            ),
                            np.array(_proj_list, dtype=object),
                            (by_c["Факт"] - by_c["План"]).values,
                        ],
                        axis=-1,
                    ),
                    hovertemplate=(
                        "<b>%{y}</b><br>Проект: %{customdata[2]}"
                        "<br>План (договор): %{customdata[0]:,.0f}"
                        "<br>Факт: %{x:,.0f}"
                        "<br>Δ (факт−план): %{customdata[3]:,.0f}"
                        "<br>Отклонение к плану: %{customdata[1]:.1f}%<extra></extra>"
                    ),
                )
            )
            fig_fb.update_layout(
                title_text="",
                xaxis_title="Человеко-смены / ед. (сумма по строкам)",
                yaxis_title="",
                height=_h,
                barmode="group",
                bargap=0.18,
                showlegend=show_plan,
                legend=standard_chart_legend(font=dict(size=11, color="#e8eef5")),
                yaxis=dict(autorange="reversed", automargin=True),
                xaxis=dict(automargin=True),
                margin=dict(l=12, r=28, t=72 if show_plan else 56, b=96),
            )
            fig_fb = _apply_finance_bar_label_layout(fig_fb)
            fig_fb = apply_chart_background(fig_fb)
            _cap_fb = (
                f"Факт и план по подрядчикам (горизонтально; в выгрузке нет колонки периода): {lab_fb}. "
                "Подсказка: план (синий/фиолетовый), факт (зелёный/оранжевый); в hover — план и факт рядом."
            )
            if _near_n > 0:
                _cap_fb += (
                    f" По {_near_n} контрагент(ам) план≈факт (≤5% или ≤1 ед.) — типично для норм/дублей строк в выгрузке; "
                    "сверьте уникальность строк в исходном файле."
                )
            with fb_cols[fbi]:
                render_chart(
                    fig_fb,
                    key=f"{key_prefix}_hist_noperiod_{fbi}",
                    caption_below=_cap_fb,
                )

    plan_fact_row_done = False
    for project_name in projects_to_process:
        project_filtered_df = filtered_df.copy()
        if (
            project_col
            and project_col in project_filtered_df.columns
            and project_name != "Все проекты"
        ):
            project_filtered_df = project_filtered_df[
                project_filtered_df[project_col].astype(str).str.strip()
                == str(project_name).strip()
            ]

        if project_filtered_df.empty:
            continue

        if len(projects_to_process) > 1:
            st.markdown("---")
            st.subheader(f"Проект: {project_name}")

        _pslug = str(project_name).replace(" ", "_")[:20]

        if not has_plan_data and "Контрагент" in project_filtered_df.columns and "week_sum" in project_filtered_df.columns:
            _bar_avg = (
                project_filtered_df.groupby("Контрагент", as_index=False)["week_sum"]
                .sum()
                .rename(columns={"week_sum": "Среднее за месяц"})
            )
            _bar_avg["Среднее за месяц"] = _bar_avg["Среднее за месяц"].round(1)
            _bar_avg = _bar_avg[_bar_avg["Среднее за месяц"] > 0].sort_values("Среднее за месяц", ascending=False)
            if not _bar_avg.empty:
                fig_avg = px.bar(
                    _bar_avg, x="Контрагент", y="Среднее за месяц",
                    text=_bar_avg["Среднее за месяц"].apply(lambda v: f"{v:.0f}"),
                    color_discrete_sequence=["#2ecc71"],
                )
                fig_avg.update_traces(textposition="outside", textfont=dict(size=12, color="white"))
                fig_avg.update_layout(height=500, xaxis=dict(tickangle=-45), yaxis_title="Среднее за месяц")
                fig_avg = _apply_finance_bar_label_layout(fig_avg)
                fig_avg = apply_chart_background(fig_avg)
                render_chart(fig_avg, key=f"{key_prefix}_avg_bar_{_pslug}", caption_below=f"Среднее количество ресурсов — {project_name}")

                total_avg = _bar_avg["Среднее за месяц"].sum()
                if total_avg > 0:
                    fig_pie_avg = px.pie(
                        _bar_avg, values="Среднее за месяц", names="Контрагент",
                        title=None, color_discrete_sequence=px.colors.qualitative.Set3,
                    )
                    fig_pie_avg = apply_standard_pie_layout(
                        fig_pie_avg,
                        height=500,
                        pct_fontsize=18,
                    )
                    fig_pie_avg.update_traces(
                        hovertemplate="<b>%{label}</b><br>Среднее: %{value:,.1f}<br>%{percent:.0%}<extra></extra>",
                    )
                    fig_pie_avg = apply_chart_background(fig_pie_avg)
                    render_chart(fig_pie_avg, key=f"{key_prefix}_avg_pie_{_pslug}", caption_below=f"Распределение ресурсов — {project_name}")
            else:
                st.info("Нет данных для отображения.")

        if not plan_fact_row_done:
            df_people = project_filtered_df.copy()
            if "data_source" in df_people.columns:
                df_people = df_people[
                    df_people["data_source"].astype(str).str.strip().str.lower() == "ресурсы"
                ].copy()
            if not df_people.empty and "План_numeric" in df_people.columns and "week_sum" in df_people.columns:
                plan_sum = df_people["План_numeric"].sum()
                _ws_sp = pd.to_numeric(df_people["week_sum"], errors="coerce").fillna(0.0)
                fact_sum = (
                    float((_ws_sp / 6.0).sum())
                    if week_columns
                    else float(_ws_sp.sum())
                )
                total_pf = plan_sum + fact_sum
                if total_pf > 0:
                    _ps = float(plan_sum)
                    _fs = float(fact_sum)
                    _dv = _ps - _fs
                    plan_i = int(np.ceil(_ps)) if _ps >= 0 else -int(np.ceil(abs(_ps)))
                    fact_i = int(np.ceil(_fs)) if _fs >= 0 else -int(np.ceil(abs(_fs)))
                    dev_i = int(np.ceil(_dv)) if _dv >= 0 else -int(np.ceil(abs(_dv)))
                    fact_color = _gdrs_fact_bar_color(_ps, _fs)
                    render_table_subheader(st, report_title_name("ГДРС план/факт", "по проекту"))
                    fig_pf_pf = go.Figure(
                        data=[
                            go.Bar(
                                x=["План", "Факт"],
                                y=[_ps, _fs],
                                marker_color=["#2E86AB", fact_color],
                                text=[f"{plan_i}", f"{fact_i}<br>Δ {dev_i}"],
                                textposition="outside",
                                textfont=dict(size=13, color="#ffffff"),
                                cliponaxis=False,
                                customdata=[
                                    [str(project_name), plan_i, fact_i, dev_i],
                                    [str(project_name), plan_i, fact_i, dev_i],
                                ],
                                hovertemplate=(
                                    "<b>%{x}</b><br>"
                                    "Проект: %{customdata[0]}<br>"
                                    "План: %{customdata[1]}<br>"
                                    "Факт: %{customdata[2]}<br>"
                                    "Отклонение: %{customdata[3]}<extra></extra>"
                                ),
                            )
                        ]
                    )
                    fig_pf_pf.update_layout(
                        height=460,
                        showlegend=False,
                        margin=dict(l=48, r=28, t=56, b=72),
                        yaxis=dict(title=""),
                        uniformtext=dict(minsize=7, mode="show"),
                    )
                    fig_pf_pf = _apply_bar_uniformtext(fig_pf_pf)
                    try:
                        fig_pf_pf.update_layout(uniformtext=dict(minsize=6, mode="show"))
                    except Exception:
                        pass
                    fig_pf_pf = apply_chart_background(fig_pf_pf)
                    render_chart(fig_pf_pf, caption_below=f"План и факт — {project_name}")

        # ========== Chart 1: Pie Chart by Contractor (Delta %) ==========
        render_table_subheader(st, "Круговая диаграмма: Распределение дельты (%) по контрагентам")

        # Group by Контрагент and aggregate for pie chart (Delta %)
        # Ensure Дельта_процент_numeric exists - check if it was created in work_df
        if "Дельта_процент_numeric" not in project_filtered_df.columns:
            # Try to find Отклонение % column by partial match
            delta_pct_col = None
            if "Отклонение %" in project_filtered_df.columns:
                delta_pct_col = "Отклонение %"
            else:
                delta_pct_col = find_column_by_partial(
                    project_filtered_df,
                    [
                        "Отклонение %",
                        "Дельта %",
                        "дельта (%)",
                        "дельта %",
                        "Delta %",
                        "delta %",
                        "Дельта(%)",
                        "Дельта%",
                    ],
                )

            if delta_pct_col and delta_pct_col in project_filtered_df.columns:
                # Extract percentage values from the column
                def extract_percentage(value):
                    """Extract numeric value from percentage string like '-90%' or '90%', or numeric value"""
                    if pd.isna(value):
                        return 0
                    # If already numeric, return as is
                    if isinstance(value, (int, float)):
                        return float(value)
                    # Otherwise, try to extract from string
                    value_str = str(value).strip()
                    # Remove % sign and convert to float
                    value_str = (
                        value_str.replace("%", "").replace(",", ".").replace(" ", "")
                    )
                    try:
                        return float(value_str)
                    except:
                        return 0

                project_filtered_df["Дельта_процент_numeric"] = project_filtered_df[
                    delta_pct_col
                ].apply(extract_percentage)
            else:
                # Try to calculate from Дельта and План if available
                if (
                    "Дельта_numeric" in project_filtered_df.columns
                    and "План_numeric" in project_filtered_df.columns
                ):
                    project_filtered_df["Дельта_процент_numeric"] = 0.0
                    mask = project_filtered_df["План_numeric"] != 0
                    project_filtered_df.loc[mask, "Дельта_процент_numeric"] = (
                        project_filtered_df.loc[mask, "Дельта_numeric"]
                        / project_filtered_df.loc[mask, "План_numeric"]
                    ) * 100
                    project_filtered_df["Дельта_процент_numeric"] = project_filtered_df[
                        "Дельта_процент_numeric"
                    ].fillna(0)
                else:
                    st.error(
                        "Не удалось найти или рассчитать отклонение %. Отсутствуют необходимые колонки."
                    )
                    st.info(
                        f"Доступные колонки: {', '.join(project_filtered_df.columns)}"
                    )
                    contractor_delta_pct = pd.DataFrame(
                        columns=["Контрагент", "Отклонение %"]
                    )

        # Group by contractor and aggregate
        if "Дельта_процент_numeric" in project_filtered_df.columns:
            # Check if we have any data before grouping
            if (
                not project_filtered_df.empty
                and "Контрагент" in project_filtered_df.columns
            ):
                contractor_delta_pct = (
                    project_filtered_df.groupby("Контрагент")
                    .agg({"Дельта_процент_numeric": "sum"})  # Sum of delta percentages
                    .reset_index()
                )

                contractor_delta_pct.columns = ["Контрагент", "Отклонение %"]
            else:
                contractor_delta_pct = pd.DataFrame(
                    columns=["Контрагент", "Отклонение %"]
                )
        else:
            contractor_delta_pct = pd.DataFrame(columns=["Контрагент", "Отклонение %"])

        # Check if we have data (внутри цикла по проектам — круговая и столбчатая по каждому проекту)
        if contractor_delta_pct.empty or len(contractor_delta_pct) == 0:
            st.info("Нет данных для отображения круговой диаграммы.")
        else:
            # Ensure «Отклонение %» is numeric
            contractor_delta_pct["Отклонение %"] = pd.to_numeric(
                contractor_delta_pct["Отклонение %"], errors="coerce"
            ).fillna(0)

            # Check if we have any non-zero values
            total_abs_sum = contractor_delta_pct["Отклонение %"].abs().sum()

            if total_abs_sum == 0:
                st.info(
                    "Все значения отклонения % равны нулю. Диаграмма не может быть построена."
                )
            else:
                # Remove only exactly zero values (not small values)
                non_zero_data = contractor_delta_pct[
                    contractor_delta_pct["Отклонение %"] != 0
                ].copy()

                # Use non-zero data if available
                if not non_zero_data.empty:
                    contractor_delta_pct = non_zero_data

                # Sort by absolute value for better visualization
                contractor_delta_pct = contractor_delta_pct.sort_values(
                    "Отклонение %", key=abs, ascending=False
                )

                # Create a copy with absolute values for pie chart (pie charts don't support negative values)
                contractor_delta_pct_abs = contractor_delta_pct.copy()
                contractor_delta_pct_abs["Отклонение %_abs"] = contractor_delta_pct_abs[
                    "Отклонение %"
                ].abs()

                # Store original values for display
                original_values = contractor_delta_pct_abs["Отклонение %"].tolist()

                # Create pie chart using absolute values
                fig_pie = px.pie(
                    contractor_delta_pct_abs,
                    values="Отклонение %_abs",
                    names="Контрагент",
                    title=None,
                    color_discrete_sequence=px.colors.qualitative.Set3,
                )
                fig_pie = apply_standard_pie_layout(
                    fig_pie,
                    height=600,
                    pct_fontsize=17,
                    extra_layout=dict(title_font_size=16),
                )
                fig_pie.update_traces(
                    customdata=list(
                        zip(
                            original_values,
                            contractor_delta_pct_abs["Отклонение %_abs"].tolist(),
                        )
                    ),
                    hovertemplate=(
                        "<b>%{label}</b><br>Сумма |Δ%|: %{customdata[1]:.0f}<br>"
                        "Δ% (знак): %{customdata[0]:+.0f}%<br>"
                        "Доля: %{percent:.0%}<extra></extra>"
                    ),
                )

                fig_pie = apply_chart_background(fig_pie)
                render_chart(
                    fig_pie,
                    caption_below=report_chart_caption_body(
                        "ГДРС", granularity="распределение дельты по контрагентам"
                    ),
                )

        # ========== Таблица по подрядчикам: план, факт, % (факт/план), отклонение ==========
        if "data_source" in project_filtered_df.columns and "Контрагент" in project_filtered_df.columns and "week_sum" in project_filtered_df.columns:
            for _type, type_label, type_key in [
                ("ресурсы", "Люди", "people"),
                ("техника", "Техника", "technique"),
            ]:
                df_type = project_filtered_df[
                    project_filtered_df["data_source"].astype(str).str.strip().str.lower() == _type
                ]
                if df_type.empty:
                    continue
                _agg = {"week_sum": "sum"}
                if "План_numeric" in df_type.columns:
                    _agg["План_numeric"] = "sum"
                _group_cols = []
                if project_col and project_col in df_type.columns:
                    _group_cols.append(project_col)
                _group_cols.append("Контрагент")
                by_contractor = df_type.groupby(_group_cols, as_index=False).agg(_agg)
                by_contractor = by_contractor.rename(
                    columns={"week_sum": "Факт", "План_numeric": "План"}
                )
                if "План" not in by_contractor.columns:
                    by_contractor["План"] = 0.0
                by_contractor["Факт"] = pd.to_numeric(
                    by_contractor["Факт"], errors="coerce"
                ).fillna(0.0)
                by_contractor["План"] = pd.to_numeric(
                    by_contractor["План"], errors="coerce"
                ).fillna(0.0)
                by_contractor["Отклонение"] = by_contractor["План"] - by_contractor["Факт"]
                by_contractor["%"] = by_contractor.apply(
                    lambda r: (
                        round(float(r["Факт"]) / float(r["План"]) * 100.0, 1)
                        if float(r["План"]) != 0.0
                        else None
                    ),
                    axis=1,
                )
                by_contractor = by_contractor[
                    (by_contractor["Факт"] != 0) | (by_contractor["План"] != 0)
                ].copy()
                if by_contractor.empty:
                    continue
                by_contractor = by_contractor.sort_values("План", ascending=False)
                with st.expander(f"Формулы столбцов ({type_label})", expanded=False):
                    suppress_caption(
                        "План (из договора), Факт (СКУД / выгрузка ресурсов), «%» = факт/план×100%, отклонение = план − факт."
                    )
                _display_cols = ["Контрагент", "План", "Факт", "%", "Отклонение"]
                if project_col and project_col in by_contractor.columns:
                    by_contractor = by_contractor.rename(columns={project_col: "Проект"})
                    _display_cols = ["Проект"] + _display_cols
                display_df = by_contractor[_display_cols].copy()
                display_df["План"] = display_df["План"].apply(
                    lambda x: int(round(x, 0)) if pd.notna(x) else 0
                )
                display_df["Факт"] = display_df["Факт"].apply(
                    lambda x: int(round(x, 0)) if pd.notna(x) else 0
                )
                render_table_subheader(
                    st,
                    report_title_name("ГДРС", f"доля факта ({type_label}) по контрагентам"),
                )
                display_df["%"] = display_df["%"].apply(
                    lambda v: f"{v:.1f}%" if v is not None and pd.notna(v) else "—"
                )
                display_df["Отклонение"] = display_df["Отклонение"].apply(
                    lambda x: int(round(x, 0)) if pd.notna(x) else 0
                )
                _render_budget_table_html(
                        display_df,
                        finance_deviation_column="Отклонение",
                        deviation_red_if_positive_only=True,
                        
                    )

        # ========== Chart 2: Bar Chart by Contractor (Plan, Fact, Отклонение) ==========
        st.subheader(
            "Столбчатая диаграмма: План, Факт, Отклонение (группировка по контрагенту)"
        )

        # Filter by selected period(s) for this chart
        bar_df = project_filtered_df.copy()
        if period_col and period_col in bar_df.columns and selected_periods:
            bar_df = bar_df[
                bar_df[period_col].astype(str).str.strip().isin([str(p).strip() for p in selected_periods])
            ]

        # Group by Контрагент and aggregate
        if "Дельта_numeric" not in bar_df.columns:
            if "План_numeric" in bar_df.columns and "week_sum" in bar_df.columns:
                bar_df = bar_df.copy()
                bar_df["Дельта_numeric"] = bar_df["План_numeric"] - bar_df["week_sum"]
            else:
                bar_df = bar_df.copy()
                bar_df["Дельта_numeric"] = 0

        contractor_data = (
            bar_df.groupby("Контрагент")
            .agg(
                {
                    "План_numeric": "sum",
                    "week_sum": "sum",
                    "Дельта_numeric": "sum",
                }
            )
            .reset_index()
        )
        contractor_data.columns = ["Контрагент", "План", "Факт", "Отклонение"]

        contractor_data["Отклонение"] = pd.to_numeric(
            contractor_data["Отклонение"], errors="coerce"
        ).fillna(0)

        _sort_bar_label = st.radio(
            "Сортировка контрагентов по",
            options=("План", "Факт", "Отклонение"),
            index=0,
            horizontal=True,
            key=f"{key_prefix}_bar_sort_technique_{_pslug}",
        )
        _sort_col_map = {"План": "План", "Факт": "Факт", "Отклонение": "Отклонение"}
        contractor_data = contractor_data.sort_values(
            _sort_col_map[_sort_bar_label], ascending=False
        ).reset_index(drop=True)

        # Столбцы — как в макете PDF: синий план, серый факт, дельта по модулю; оранжевый если > 0, зелёный если ≤ 0.
        delta_values = contractor_data["Отклонение"].fillna(0)
        delta_abs = delta_values.abs()

        plan_text = []
        fact_text = []
        delta_text = []
        for i in range(len(contractor_data)):
            pv = float(
                pd.to_numeric(contractor_data["План"].iloc[i], errors="coerce") or 0.0
            )
            fv = float(
                pd.to_numeric(contractor_data["Факт"].iloc[i], errors="coerce") or 0.0
            )
            dv = float(pd.to_numeric(delta_values.iloc[i], errors="coerce") or 0.0)
            av = abs(dv)
            if pv > 1e-9:
                plan_text.append(f"{int(round(pv))} (100%)")
                fact_text.append(f"{int(round(fv))} ({fv/pv*100:.0f}%)")
                if av < 0.5:
                    delta_text.append("0")
                else:
                    delta_text.append(f"{int(round(av))} ({dv/pv*100:+.0f}%)")
            else:
                plan_text.append("0")
                fact_text.append(f"{int(round(fv))}" if abs(fv) >= 0.5 else "0")
                delta_text.append(f"{int(round(av))}" if av >= 0.5 else "0")

        _pv_arr = pd.to_numeric(contractor_data["План"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
        _fv_arr = pd.to_numeric(contractor_data["Факт"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
        _fact_bar_colors_pf = [_gdrs_fact_bar_color(float(a), float(b)) for a, b in zip(_pv_arr, _fv_arr)]
        _hover_fact_pf = np.stack([_pv_arr, _fv_arr, _pv_arr - _fv_arr], axis=-1)

        fig_bar = go.Figure()
        fig_bar.add_trace(
            go.Bar(
                name="План",
                x=contractor_data["Контрагент"],
                y=contractor_data["План"],
                marker_color="#3498db",
                text=plan_text,
                textposition="outside",
                textfont=dict(size=12, color="white"),
                customdata=_hover_fact_pf,
                hovertemplate=(
                    "<b>%{x}</b><br>"
                    "План: %{y:.0f}<br>"
                    "Факт: %{customdata[1]:.0f}<br>"
                    "Отклонение (план−факт): %{customdata[2]:.0f}<extra></extra>"
                ),
            )
        )
        fig_bar.add_trace(
            go.Bar(
                name="Факт",
                x=contractor_data["Контрагент"],
                y=contractor_data["Факт"],
                marker=dict(color=_fact_bar_colors_pf, line=dict(width=1, color="#eaf2fb")),
                text=fact_text,
                textposition="outside",
                textfont=dict(size=12, color="white"),
                customdata=_hover_fact_pf,
                hovertemplate=(
                    "<b>%{x}</b><br>"
                    "План: %{customdata[0]:.0f}<br>"
                    "Факт: %{y:.0f}<br>"
                    "Отклонение (план−факт): %{customdata[2]:.0f}<extra></extra>"
                ),
            )
        )

        pos_mask = delta_values > 0
        nonpos_mask = delta_values <= 0
        if pos_mask.any():
            fig_bar.add_trace(
                go.Bar(
                    name="Отклонение > 0",
                    x=contractor_data.loc[pos_mask, "Контрагент"],
                    y=delta_abs[pos_mask],
                    marker_color="#e67e22",
                    text=[delta_text[i] for i in range(len(delta_text)) if pos_mask.iloc[i]],
                    textposition="outside",
                    textfont=dict(size=12, color="white"),
                    showlegend=True,
                )
            )
        if nonpos_mask.any():
            fig_bar.add_trace(
                go.Bar(
                    name="Отклонение ≤ 0",
                    x=contractor_data.loc[nonpos_mask, "Контрагент"],
                    y=delta_abs[nonpos_mask],
                    marker_color="#2ecc71",
                    text=[delta_text[i] for i in range(len(delta_text)) if nonpos_mask.iloc[i]],
                    textposition="outside",
                    textfont=dict(size=12, color="white"),
                    showlegend=True,
                )
            )

        period_caption = f" Период: {', '.join(str(p) for p in selected_periods[:5])}{'…' if len(selected_periods) > 5 else ''}" if (period_col and selected_periods) else ""
        fig_bar.update_layout(
            title_text="",
            xaxis_title="Контрагент",
            yaxis_title="Факт (сумма), план и отклонение",
            barmode="group",
            width=_RENDER_CHART_DEFAULT_WIDTH_PX,
            bargap=0.22,
            bargroupgap=0.09,
            height=620,
            legend=standard_chart_legend(),
            xaxis=dict(tickangle=-45, automargin=True),
            yaxis=dict(automargin=True, rangemode="tozero"),
        )

        fig_bar = _apply_finance_bar_label_layout(fig_bar, y_rangemode="tozero")
        try:
            fig_bar.update_layout(
                uniformtext=dict(minsize=6, mode="show"),
                margin=dict(l=56, r=150, t=100, b=200),
            )
            fig_bar.update_yaxes(rangemode="tozero")
            fig_bar.update_traces(cliponaxis=False, selector=dict(type="bar"))
        except Exception:
            pass
        fig_bar = apply_chart_background(fig_bar)
        render_chart(
            fig_bar,
            caption_below=(
                "План, Факт и Отклонение по контрагентам"
                + period_caption
                + ". Макет: высота отклонения — модуль; оранжевый при Отклонение > 0, зелёный при ≤ 0. Сортировка — виджет выше."
            ),
        )

        # ========== Chart 3: Pie Chart by Contractor (Plan + Average) ==========
        st.subheader(
            "Круговые диаграммы: Рабочие/техника (план/факт) и Рабочие/техника (% фактический по подрядчикам)"
        )

        # Group by Контрагент and aggregate for pie chart (Plan + Average)
        contractor_plan_avg = (
            project_filtered_df.groupby("Контрагент")
            .agg(
                {
                    "План_numeric": "sum",  # Sum of plans
                    "week_sum": "sum",  # Sum of weeks = среднее за месяц
                    "Дельта_numeric": "sum",  # Sum of deltas
                }
            )
            .reset_index()
        )

        contractor_plan_avg.columns = [
            "Контрагент",
            "План",
            "Среднее за месяц",
            "Отклонение",
        ]

        # Calculate sum of Plan + Average for each contractor
        contractor_plan_avg["Сумма"] = (
            contractor_plan_avg["План"] + contractor_plan_avg["Среднее за месяц"]
        )

        # Calculate доля факта (Среднее за месяц / Сумма * 100) and доля отклонения (Отклонение / План * 100)
        contractor_plan_avg["Доля факта (%)"] = 0.0
        contractor_plan_avg["Доля отклонения (%)"] = 0.0
        mask_sum = contractor_plan_avg["Сумма"] != 0
        contractor_plan_avg.loc[mask_sum, "Доля факта (%)"] = (
            contractor_plan_avg.loc[mask_sum, "Среднее за месяц"]
            / contractor_plan_avg.loc[mask_sum, "Сумма"]
        ) * 100
        mask_plan = contractor_plan_avg["План"] != 0
        contractor_plan_avg.loc[mask_plan, "Доля отклонения (%)"] = (
            contractor_plan_avg.loc[mask_plan, "Отклонение"]
            / contractor_plan_avg.loc[mask_plan, "План"]
        ) * 100

        # Remove zero values for pie chart
        contractor_plan_avg = contractor_plan_avg[
            contractor_plan_avg["Сумма"] != 0
        ].copy()

        if contractor_plan_avg.empty:
            st.info("Нет данных для отображения.")
        else:
            contractor_plan_avg.sort_values("Сумма", ascending=False, inplace=True)
            # Круговая «план + среднее по контрагентам» скрыта по макету — используйте сводную таблицу ниже.

        render_table_subheader(st, report_title_name("ГДРС", "по контрагентам"))

        # Format numbers for display
        summary_table = contractor_data.copy()
        summary_table["План"] = summary_table["План"].apply(
            lambda x: f"{int(x)}" if pd.notna(x) else "0"
        )
        summary_table["Среднее за месяц"] = summary_table["Среднее за месяц"].apply(
            lambda x: f"{int(x)}" if pd.notna(x) else "0"
        )
        summary_table["Отклонение"] = summary_table["Отклонение"].apply(
            lambda x: f"{int(x)}" if pd.notna(x) else "0"
        )

        _render_budget_table_html(summary_table, finance_deviation_column="Отклонение")

        # Summary metrics
        col1, col2, col3 = st.columns(3, gap="small")

        with col1:
            total_plan = contractor_data["План"].sum()
            st.metric("Общий план", f"{int(total_plan)}")

        with col2:
            total_average = contractor_data["Среднее за месяц"].sum()
            st.metric("Общее среднее за месяц", f"{int(total_average)}")

        with col3:
            total_delta = contractor_data["Отклонение"].sum()
            st.metric("Общее отклонение", f"{int(total_delta)}")


# ==================== DASHBOARD 8.6.7: Workforce Movement ====================
def dashboard_workforce_movement(df, data_source_filter=None, show_header=True, key_prefix="workforce"):
    """
    График движения рабочей силы (ресурсы и/или техника).
    data_source_filter: "Ресурсы" — только люди, "Техника" — только техника, None — оба.
    show_header: выводить ли заголовок (при вызове из табов можно False).
    key_prefix: префикс для ключей виджетов Streamlit (уникальный при вызове из нескольких табов).
    """
    resources_df = st.session_state.get("resources_data", None)
    technique_df = st.session_state.get("technique_data", None)
    combined_df = None
    _gdrs_src_diag = ""

    def _cols_lc(pdf):
        if pdf is None or getattr(pdf, "empty", True):
            return []
        return [str(c).lower().strip() for c in pdf.columns]

    def _has_pivot_date_columns(pdf):
        """Колонки вида ДД.ММ.ГГГГ (выгрузка web/ с суточными значениями)."""
        if pdf is None or getattr(pdf, "empty", True):
            return False
        return sum(1 for c in pdf.columns if _gdrs_header_is_dd_mm_yyyy(c)) >= 2

    def _like_technique(pdf):
        cl = _cols_lc(pdf)
        if any("среднее за недел" in c for c in cl):
            return True
        if any("среднее значение за день" in c for c in cl):
            return True
        if _has_pivot_date_columns(pdf) and any("тип ресурсов" in c for c in cl):
            return True
        return False

    def _like_resources(pdf):
        cl = _cols_lc(pdf)
        for c in cl:
            if "среднее за месяц" in c or "среднее за мес" in c:
                return True
            if "за месяц" in c and ("ресурс" in c or "количество" in c):
                return True
            if "среднее значение" in c and "за месяц" in c:
                return True
        return False

    def _ensure_row_data_source(pdf, default: str):
        """Не затираем колонку data_source из файла (в одной таблице могут быть и люди, и техника)."""
        out = pdf.copy()
        if "data_source" not in out.columns:
            out["data_source"] = default
        else:
            out["data_source"] = out["data_source"].astype(str).str.strip()
        return out

    # load_all_from_web кладёт *resursi*.csv в resources_data; тип по заголовкам / по колонке data_source строки.
    if data_source_filter == "Техника":
        if technique_df is not None and not technique_df.empty:
            combined_df = _ensure_row_data_source(technique_df.copy(), "Техника")
            _gdrs_src_diag = "session_state.technique_data"
        elif resources_df is not None and not resources_df.empty and (
            _like_technique(resources_df) or _has_pivot_date_columns(resources_df)
        ):
            combined_df = _ensure_row_data_source(resources_df.copy(), "Техника")
            _gdrs_src_diag = (
                "session_state.resources_data — структура как у техники (даты ДД.ММ.ГГГГ / «среднее значение за день» / data_source по строкам)"
            )
        elif resources_df is not None and not resources_df.empty and "data_source" in resources_df.columns:
            _rs = resources_df.copy()
            _ds = _rs["data_source"].astype(str).str.strip().str.lower()
            _tech_mask = _ds.isin({"техника", "tech", "technique"})
            if _tech_mask.any():
                combined_df = _ensure_row_data_source(_rs.loc[_tech_mask].copy(), "Техника")
                _gdrs_src_diag = "session_state.resources_data — строки с data_source = техника"
    elif data_source_filter == "Ресурсы":
        if resources_df is not None and not resources_df.empty:
            combined_df = _ensure_row_data_source(resources_df.copy(), "Ресурсы")
            _gdrs_src_diag = "session_state.resources_data"
        elif technique_df is not None and not technique_df.empty and _like_resources(technique_df):
            combined_df = _ensure_row_data_source(technique_df.copy(), "Ресурсы")
            _gdrs_src_diag = "session_state.technique_data — распознаны как ресурсы по месячному среднему"
    else:
        if resources_df is not None and not resources_df.empty:
            combined_df = _ensure_row_data_source(resources_df.copy(), "Ресурсы")
            _gdrs_src_diag = "session_state.resources_data"
        if technique_df is not None and not technique_df.empty:
            if combined_df is not None:
                technique_copy = _ensure_row_data_source(technique_df.copy(), "Техника")
                combined_df = pd.concat(
                    [combined_df, technique_copy], ignore_index=True, sort=False
                )
                _gdrs_src_diag += " + technique_data"
            else:
                combined_df = _ensure_row_data_source(technique_df.copy(), "Техника")
                _gdrs_src_diag = "session_state.technique_data"

    # df из главного приложения: только если структура совпадает (не подменяем людей техникой).
    if (combined_df is None or combined_df.empty) and df is not None and not getattr(df, "empty", True):
        if data_source_filter == "Техника" and (_like_technique(df) or _has_pivot_date_columns(df)):
            combined_df = _ensure_row_data_source(df.copy(), "Техника")
            _gdrs_src_diag = "аргумент df (техника / суточные колонки)"
        elif data_source_filter == "Ресурсы" and (_like_resources(df) or _has_pivot_date_columns(df)):
            combined_df = _ensure_row_data_source(df.copy(), "Ресурсы")
            _gdrs_src_diag = "аргумент df (ресурсы / сводная структура)"

    if combined_df is None or combined_df.empty:
        st.warning(
            "Для отображения графика движения рабочей силы необходимо загрузить файл с данными о ресурсах или технике."
        )
        if data_source_filter == "Техника":
            st.info(
                "**Вкладка «Техника»:** загрузите отдельный файл выгрузки техники (в имени часто есть «техника» / technique) "
                "или общий файл ресурсов, где в колонке **data_source** для строк указано «Техника», "
                "либо таблицу с колонками **«Среднее за неделю»** / суточными датами ДД.ММ.ГГГГ (см. ТЗ PDF, блок ГДРС)."
            )
        else:
            st.info(
                "Ожидаемые колонки: Проект (или Название), Контрагент, Период, План, "
                "**Среднее за месяц** (люди) или **Среднее за неделю** (техника), 1–5 неделя; "
                "при необходимости — «Дельта» / «Отклонение %». "
                "Файл техники из web/ с именем *resursi* может оказаться только в «ресурсах» — тогда "
                "техника определяется по наличию колонки «Среднее за неделю» или по строкам data_source=техника."
            )
        return

    # При фильтре по вкладке — без учёта регистра в колонке data_source
    if data_source_filter and "data_source" in combined_df.columns:
        combined_df = combined_df[_gdrs_match_data_source(combined_df["data_source"], data_source_filter)].copy()
        if combined_df.empty:
            st.warning(
                f"Нет данных по источнику «{data_source_filter}». Загрузите соответствующий файл."
            )
            return

    work_df = combined_df.copy()
    work_df.columns = [
        str(c).replace("\ufeff", "").replace("\n", " ").replace("\r", " ").strip()
        for c in work_df.columns
    ]
    _plan_src_w = _gdrs_resolve_plan_column(work_df)
    if _plan_src_w and _plan_src_w != "План":
        work_df["План"] = work_df[_plan_src_w]

    def _gdrs_sanitize_plan_column_if_dates(pdf: pd.DataFrame) -> None:
        """Если «План» по факту содержит даты/строки, а не чел.-дни — не используем как число."""
        if pdf is None or pdf.empty or "План" not in pdf.columns:
            return
        raw = pdf["План"]
        dt = pd.to_datetime(raw, errors="coerce", dayfirst=True)
        n = len(pdf)
        if n == 0:
            return
        date_share = float(dt.notna().sum()) / float(n)
        num = pd.to_numeric(
            raw.astype(str)
            .str.replace("\u00a0", "", regex=False)
            .str.replace(" ", "")
            .str.replace(",", "."),
            errors="coerce",
        )
        num_ok = float(num.notna().sum()) / float(n)
        num_sum = float(num.fillna(0).abs().sum())
        # Преобладают распознанные даты при слабом числовом содержании — сбрасываем в 0 (нет плана в файле)
        if date_share >= 0.45 and (num_ok < 0.35 or num_sum < max(1.0, n * 0.25)):
            pdf["План"] = 0

    _gdrs_sanitize_plan_column_if_dates(work_df)

    # На вкладке «всё вместе» — фильтр вида ресурсов; по умолчанию «Рабочие (ресурсы)»
    if (
        data_source_filter is None
        and "data_source" in work_df.columns
        and work_df["data_source"].astype(str).str.strip().nunique(dropna=True) > 1
    ):
        _rk = st.radio(
            "Вид ресурсов",
            ["Рабочие (ресурсы)", "Техника", "Все"],
            index=0,
            horizontal=True,
            key=f"{key_prefix}_resource_kind",
        )
        _ds = work_df["data_source"].astype(str).str.strip().str.lower()
        if _rk == "Рабочие (ресурсы)":
            work_df = work_df[_ds == "ресурсы"].copy()
        elif _rk == "Техника":
            work_df = work_df[_ds == "техника"].copy()
        if work_df.empty:
            st.warning(
                "Нет данных для выбранного вида ресурсов. Загрузите файл или выберите «Все»."
            )
            return

    date_cols_found = [c for c in work_df.columns if _gdrs_header_is_dd_mm_yyyy(c)]
    if date_cols_found and "Период" not in work_df.columns:
        # Определяем период (месяц) по КАЖДОЙ строке на основе датовых колонок,
        # чтобы строки из нескольких файлов (янв/фев) не схлопывались в один месяц.
        _dc_to_period: dict[str, pd.Period] = {}
        for dc in date_cols_found:
            _dc_norm = re.sub(r"\.{2,3}", ".", str(dc).strip())
            _dc_ts = pd.to_datetime(_dc_norm, errors="coerce", dayfirst=True)
            if pd.notna(_dc_ts):
                _dc_to_period[dc] = _dc_ts.to_period("M")

        id_cols = [c for c in ["Проект", "Контрагент", "тип ресурсов", "data_source"]
                   if c in work_df.columns]
        avg_month_col = None
        for c in work_df.columns:
            cl = str(c).lower()
            if "среднее" in cl and ("за месяц" in cl or "количество ресурсов" in cl):
                vals = pd.to_numeric(work_df[c], errors="coerce")
                if vals.notna().any() and (vals != 0).any():
                    avg_month_col = c
                    break
        if not avg_month_col:
            for c in reversed(list(work_df.columns)):
                cl = str(c).lower()
                if "среднее" in cl and not cl.startswith("тип"):
                    vals = pd.to_numeric(work_df[c], errors="coerce")
                    if vals.notna().any() and (vals != 0).any():
                        avg_month_col = c
                        break

        for dc in date_cols_found:
            work_df[dc] = pd.to_numeric(work_df[dc], errors="coerce")

        _row_period_col = "__gdrs_row_period"
        if _dc_to_period:
            _masks = []
            _vals = []
            for _dc, _pr in _dc_to_period.items():
                if _dc in work_df.columns:
                    _masks.append(work_df[_dc].notna())
                    _vals.append(_pr)
            if _masks:
                _row_period = pd.Series(pd.Period("1970-01", freq="M"), index=work_df.index)
                _has_any = pd.Series(False, index=work_df.index)
                for _mk, _pr in zip(_masks, _vals):
                    _set_now = _mk & (~_has_any)
                    if _set_now.any():
                        _row_period.loc[_set_now] = _pr
                        _has_any |= _set_now
                # fallback-1: если строка без датовых значений — пробуем период из source_file (дата в имени файла).
                _fallback_mask = ~_has_any
                if _fallback_mask.any() and "__source_file" in work_df.columns:
                    def _parse_snapshot_date_local(date_str: str):
                        if not date_str:
                            return None
                        for _fmt in ("%d-%m-%Y", "%d.%m.%Y", "%Y-%m-%d"):
                            try:
                                return datetime.strptime(str(date_str).strip(), _fmt).date()
                            except ValueError:
                                continue
                        return None

                    def _src_to_period(v):
                        if v is None:
                            return None
                        parts = str(v).replace("\\", "/").split("/")[-1].replace(".csv", "").replace(".CSV", "").split("_")
                        for p in reversed(parts):
                            sd = _parse_snapshot_date_local(p)
                            if sd is not None:
                                try:
                                    return pd.Timestamp(sd).to_period("M")
                                except Exception:
                                    return None
                        return None
                    _src_period = work_df["__source_file"].map(_src_to_period)
                    _src_ok = _src_period.notna() & _fallback_mask
                    if _src_ok.any():
                        _row_period.loc[_src_ok] = _src_period.loc[_src_ok]
                        _has_any |= _src_ok

                # fallback-2: если совсем нечего — используем первый доступный период.
                if _vals:
                    _row_period.loc[~_has_any] = _vals[0]
                work_df[_row_period_col] = _row_period
                if _row_period_col not in id_cols:
                    id_cols.append(_row_period_col)

        if id_cols:
            agg_spec = {dc: (dc, "mean") for dc in date_cols_found}
            if "План" in work_df.columns and "План" not in id_cols:
                agg_spec["План"] = ("План", "first")
            for _wk in range(1, 7):
                wn = f"{_wk} неделя"
                if wn in work_df.columns and wn not in id_cols:
                    agg_spec[wn] = (wn, "first")
            agg = work_df.groupby(id_cols, dropna=False).agg(**agg_spec).reset_index()
            agg["Среднее за месяц"] = agg[date_cols_found].mean(axis=1).round(1)
            if _row_period_col in agg.columns:
                agg["Период"] = agg[_row_period_col]
                agg = agg.drop(columns=[_row_period_col], errors="ignore")
            if avg_month_col and avg_month_col in work_df.columns:
                month_avg = work_df.groupby(id_cols, dropna=False)[avg_month_col].first().reset_index()
                month_avg["_avg_num"] = pd.to_numeric(month_avg[avg_month_col], errors="coerce")
                if month_avg["_avg_num"].notna().any() and (month_avg["_avg_num"] != 0).any():
                    agg["Среднее за месяц"] = month_avg["_avg_num"].values
            agg = agg.drop(columns=date_cols_found, errors="ignore")
            work_df = agg
        else:
            work_df["Среднее за месяц"] = work_df[date_cols_found].mean(axis=1).round(1)
            work_df = work_df.drop(columns=date_cols_found, errors="ignore")

    def find_column_by_partial(df, possible_names):
        """Find column by possible names (exact or partial match)"""
        for col in df.columns:
            col_lower = str(col).lower().strip()
            for name in possible_names:
                name_lower = str(name).lower().strip()
                if (
                    name_lower == col_lower
                    or name_lower in col_lower
                    or col_lower in name_lower
                ):
                    return col
        return None

    # sample_technique_data.csv: Проект, Контрагент, Период, План, Среднее за неделю, 1–5 неделя, Дельта, Отклонение %
    # Use Russian column names directly

    # Check required columns - Контрагент is essential
    if "Контрагент" not in work_df.columns:
        # Try to find contractor column by partial match
        contractor_col = find_column_by_partial(
            work_df,
            [
                "Контрагент",
                "контрагент",
                "Подразделение",
                "подразделение",
                "contractor",
            ],
        )
        if contractor_col:
            work_df["Контрагент"] = work_df[contractor_col]
        else:
            st.error(f"Отсутствует необходимая колонка 'Контрагент'")
            st.info(f"Доступные колонки: {', '.join(work_df.columns)}")
            return

    # Find week columns dynamically - also try partial match
    week_columns = []
    for week_num in range(1, 6):
        week_col = f"{week_num} неделя"
        if week_col in work_df.columns:
            week_columns.append(week_col)
        else:
            # Try to find by partial match
            found_col = find_column_by_partial(
                work_df,
                [
                    week_col,
                    f"{week_num} недел",
                    f"недел {week_num}",
                    f"week {week_num}",
                ],
            )
            if found_col:
                week_columns.append(found_col)

    # Check if we have any data
    if work_df.empty:
        st.warning("Данные пусты после обработки.")
        return

    for wc in week_columns:
        if wc in work_df.columns:
            work_df[wc] = work_df[wc].fillna(0)
    if "План" in work_df.columns:
        work_df["План"] = work_df["План"].fillna(0)

    # Process numeric columns
    # Process План
    if "План" in work_df.columns:
        work_df["План_numeric"] = pd.to_numeric(
            work_df["План"].astype(str).str.replace(",", ".").str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
    else:
        work_df["План_numeric"] = 0

    work_df = _gdrs_merge_plan_from_1c_spravochniki(
        work_df, st.session_state.get("reference_contractors"), data_source_filter
    )

    # Process week columns - convert to numeric, handle empty strings
    for week_col in week_columns:
        work_df[f"{week_col}_numeric"] = pd.to_numeric(
            work_df[week_col]
            .astype(str)
            .str.replace(",", ".")
            .str.replace(" ", "")
            .replace("", "0"),
            errors="coerce",
        ).fillna(0)

    def _period_weeks_series(pdf: pd.DataFrame, fallback_weeks: int) -> pd.Series:
        """Число недель в месяце по периоду строки: ceil(days_in_month / 7)."""
        out = pd.Series(float(fallback_weeks), index=pdf.index, dtype="float64")
        if not period_col or period_col not in pdf.columns:
            return out
        parsed_period = pd.to_datetime(pdf[period_col], errors="coerce", dayfirst=True)
        if parsed_period.notna().any():
            out.loc[parsed_period.notna()] = np.ceil(
                parsed_period.loc[parsed_period.notna()].dt.days_in_month / 7.0
            ).astype(float)
        return out

    # Факт: приоритет — явная сумма 1..5 недели; средние используем только как fallback.
    if week_columns:
        week_numeric_cols = [f"{col}_numeric" for col in week_columns]
        work_df["week_sum"] = work_df[week_numeric_cols].sum(axis=1)
        num_weeks = len(week_columns) if week_columns else 4
        work_df["Среднее_за_неделю_numeric"] = (
            work_df["week_sum"] / num_weeks if num_weeks > 0 else 0
        )
    elif "Среднее за месяц" in work_df.columns:
        # Если есть среднее за месяц — это fallback для факта за период
        work_df["Среднее_за_месяц_numeric"] = pd.to_numeric(
            work_df["Среднее за месяц"]
            .astype(str)
            .str.replace(",", ".")
            .str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
        work_df["week_sum"] = work_df["Среднее_за_месяц_numeric"]
        num_weeks = len(week_columns) if week_columns else 4
        work_df["Среднее_за_неделю_numeric"] = (
            work_df["week_sum"] / num_weeks if num_weeks > 0 else 0
        )
    elif "Среднее за неделю" in work_df.columns:
        # Если есть только среднее за неделю — приводим к факту периода умножением
        # на число недель месяца.
        work_df["Среднее_за_неделю_numeric"] = pd.to_numeric(
            work_df["Среднее за неделю"]
            .astype(str)
            .str.replace(",", ".")
            .str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
        num_weeks = len(week_columns) if week_columns else 4
        work_df["week_sum"] = work_df["Среднее_за_неделю_numeric"] * _period_weeks_series(
            work_df, num_weeks
        )
    else:
        work_df["week_sum"] = 0
        work_df["Среднее_за_неделю_numeric"] = 0

    # Факт (week_sum) не распознан по канонич. колонкам — пробуем типичные заголовки из файлов
    _ws_sum = float(
        pd.to_numeric(work_df.get("week_sum"), errors="coerce").fillna(0).abs().sum()
    )
    if _ws_sum == 0:
        _col_m = find_column_by_partial(
            work_df,
            ["Среднее за месяц", "среднее за месяц", "среднее за мес", "Среднее за мес"],
        )
        _col_w = find_column_by_partial(
            work_df, ["Среднее за неделю", "среднее за неделю", "средн за нед"]
        )
        if _col_m and _col_m in work_df.columns:
            work_df["week_sum"] = pd.to_numeric(
                work_df[_col_m].astype(str).str.replace(",", ".").str.replace(" ", ""),
                errors="coerce",
            ).fillna(0.0)
            nw = len(week_columns) if week_columns else 4
            if work_df["week_sum"].abs().sum() > 0:
                work_df["Среднее_за_неделю_numeric"] = (
                    work_df["week_sum"] / nw if nw else work_df["week_sum"]
                )
        elif _col_w and _col_w in work_df.columns:
            work_df["Среднее_за_неделю_numeric"] = pd.to_numeric(
                work_df[_col_w].astype(str).str.replace(",", ".").str.replace(" ", ""),
                errors="coerce",
            ).fillna(0.0)
            _nw = len(week_columns) if week_columns else 4
            work_df["week_sum"] = work_df["Среднее_за_неделю_numeric"] * _period_weeks_series(
                work_df, _nw
            )

    # ГДРС: при колонках «N неделя» week_sum — сумма недель; для сравнения с планом делим на 6 (фикс. сетка).
    week_fact_den = 6.0 if week_columns else 1.0

    # Process Дельта (Delta) if available - try to find column by partial match
    delta_col = None
    if "Дельта" in work_df.columns:
        delta_col = "Дельта"
    else:
        delta_col = find_column_by_partial(
            work_df, ["Дельта", "дельта", "delta", "Delta", "Дельта (без %)"]
        )

    if delta_col and delta_col in work_df.columns:
        work_df["Дельта_numeric"] = pd.to_numeric(
            work_df[delta_col].astype(str).str.replace(",", ".").str.replace(" ", ""),
            errors="coerce",
        ).fillna(0)
    else:
        # Отклонение по PDF правок ГДРС: План − Факт (Факт ≈ week_sum / 6 при недельных колонках).
        work_df["Дельта_numeric"] = work_df["План_numeric"] - (
            pd.to_numeric(work_df["week_sum"], errors="coerce").fillna(0.0) / week_fact_den
        )

    # Process Отклонение % (Delta %) if available - extract numeric value from percentage string
    # Try to find column by partial match
    delta_pct_col = None
    if "Отклонение %" in work_df.columns:
        delta_pct_col = "Отклонение %"
    else:
        delta_pct_col = find_column_by_partial(
            work_df,
            [
                "Дельта (%)",
                "Отклонение %",
                "Дельта %",
                "дельта (%)",
                "дельта %",
                "Delta %",
                "delta %",
                "Дельта(%)",
                "Дельта%",
            ],
        )

    if delta_pct_col and delta_pct_col in work_df.columns:

        def extract_percentage(value):
            """Extract numeric value from percentage string like '-90%' or '90%', or numeric value"""
            if pd.isna(value):
                return 0
            # If already numeric, return as is
            if isinstance(value, (int, float)):
                return float(value)
            # Otherwise, try to extract from string
            value_str = str(value).strip()
            # Remove % sign and convert to float
            value_str = value_str.replace("%", "").replace(",", ".").replace(" ", "")
            try:
                return float(value_str)
            except:
                return 0

        work_df["Дельта_процент_numeric"] = work_df[delta_pct_col].apply(
            extract_percentage
        )
    else:
        # Calculate delta percentage if we have delta and plan
        work_df["Дельта_процент_numeric"] = 0.0
        if "Дельта_numeric" in work_df.columns and "План_numeric" in work_df.columns:
            mask = work_df["План_numeric"] != 0
            work_df.loc[mask, "Дельта_процент_numeric"] = (
                work_df.loc[mask, "Дельта_numeric"] / work_df.loc[mask, "План_numeric"]
            ) * 100
        work_df["Дельта_процент_numeric"] = work_df["Дельта_процент_numeric"].fillna(0)

    if "Среднее_за_неделю_numeric" not in work_df.columns:
        num_weeks = len(week_columns) if week_columns else 4
        work_df["Среднее_за_неделю_numeric"] = (
            work_df["week_sum"] / num_weeks if num_weeks > 0 else 0
        )

    has_plan_data = (
        "План_numeric" in work_df.columns
        and work_df["План_numeric"].sum() > 0
    )

    # Find Проект column
    project_col = None
    if "Проект" in work_df.columns:
        project_col = "Проект"
    else:
        project_col = find_column_by_partial(
            work_df,
            [
                "Проект",
                "проект",
                "project",
                "Project",
                "Название",
                "название",
                "Название проекта",
                "Наименование проекта",
            ],
        )

    if project_col and project_col in work_df.columns:
        work_df = _project_column_apply_canonical(work_df, project_col)

    period_col = _gdrs_resolve_period_column(work_df)
    if period_col is None:
        work_df = work_df.copy()
        # 1) По заголовкам-датам (самый частый кейс web/AI resources).
        _date_cols_fb = [c for c in work_df.columns if _gdrs_header_is_dd_mm_yyyy(c)]
        _dt_fb = pd.Series(dtype="datetime64[ns]")
        if _date_cols_fb:
            _hdr_fb = (
                pd.Series(_date_cols_fb)
                .astype(str)
                .str.replace(r"\.{2,3}", ".", regex=True)
                .str.strip()
            )
            _dt_fb = pd.to_datetime(_hdr_fb, errors="coerce", dayfirst=True).dropna()
        # 2) Из snapshot_date, если есть.
        if _dt_fb.empty and "snapshot_date" in work_df.columns:
            _sdt = pd.to_datetime(work_df["snapshot_date"], errors="coerce").dropna()
            if not _sdt.empty:
                # Берём по строкам из snapshot_date, чтобы в фильтре был выбор месяцев.
                work_df["Период"] = pd.to_datetime(
                    work_df["snapshot_date"], errors="coerce"
                ).dt.to_period("M")
                period_col = "Период"
        if period_col is None and not _dt_fb.empty:
            work_df["Период"] = _dt_fb.iloc[0].to_period("M")
            period_col = "Период"
        if period_col is None:
            # Последний fallback для уже загруженных/старых версий без period/snapshot:
            # не даём фильтру периода пропасть из UI.
            work_df["Период"] = pd.Timestamp.today().to_period("M")
            period_col = "Период"

    with filters_panel(st, reset_keys=[
        f"{key_prefix}_projects", f"{key_prefix}_contractor",
        f"{key_prefix}_period_range", f"{key_prefix}_csv_resource_kind",
    ]):
        _gdrs_csv_kind_col = _gdrs_detect_csv_resource_kind_column(work_df)
        if _gdrs_csv_kind_col and _gdrs_csv_kind_col in work_df.columns:
            _kind_raw = work_df[_gdrs_csv_kind_col].astype(str).str.strip()
            _kind_ok = _kind_raw.ne("") & ~_kind_raw.str.lower().isin({"nan", "none"})
            _uniq_kind = sorted(_kind_raw[_kind_ok].unique().tolist())
            if len(_uniq_kind) >= 2:
                _kind_opts = ["Все"] + _uniq_kind
                _kind_sel = st.selectbox(
                    "Вид ресурсов (по файлу)",
                    _kind_opts,
                    key=f"{key_prefix}_csv_resource_kind",
                    help=f"Колонка признака в CSV: {_gdrs_csv_kind_col}",
                )
                if _kind_sel != "Все":
                    work_df = work_df.loc[_kind_raw.eq(str(_kind_sel).strip())].copy()

        col1, col2, col3 = st.columns(3, gap="small")

        with col1:
            if project_col and project_col in work_df.columns:
                all_projects = sorted(work_df[project_col].dropna().unique().tolist())
                selected_projects, _ = project_filter_multiselect(st, all_projects,
                    key=f"{key_prefix}_projects",
                )
            else:
                selected_projects = []
                st.info("Колонка 'Проект' не найдена")

        with col2:
            if "Контрагент" in work_df.columns:
                contractors = ["Все"] + sorted(
                    work_df["Контрагент"].dropna().unique().tolist()
                )
                selected_contractor = st.selectbox(
                    "Контрагент", contractors, key=f"{key_prefix}_contractor"
                )
            else:
                selected_contractor = "Все"
                st.info("Колонка 'Контрагент' не найдена")

        selected_periods = []
        selected_daily_dates: list[pd.Timestamp] = []
        # Локально вычисляем даты из заголовков, чтобы исключить NameError при любых рефакторах выше.
        _daily_dates: list[pd.Timestamp] = []
        _date_cols_local = [c for c in work_df.columns if _gdrs_header_is_dd_mm_yyyy(c)]
        if _date_cols_local:
            _hdr_local = (
                pd.Series(_date_cols_local)
                .astype(str)
                .str.replace(r"\.{2,3}", ".", regex=True)
                .str.strip()
            )
            _parsed_local = pd.to_datetime(_hdr_local, errors="coerce", dayfirst=True).dropna()
            if not _parsed_local.empty:
                _daily_dates = sorted(
                    list({pd.Timestamp(d).normalize() for d in _parsed_local.tolist()})
                )
        with col3:
            # По ТЗ: фильтр периода — диапазон дат.
            _min_dt = None
            _max_dt = None
            if len(_daily_dates) > 1:
                _min_dt = _daily_dates[0].date()
                _max_dt = _daily_dates[-1].date()
            elif period_col and period_col in work_df.columns:
                _pdt = pd.to_datetime(work_df[period_col], errors="coerce", dayfirst=True).dropna()
                if not _pdt.empty:
                    _min_dt = _pdt.min().date()
                    _max_dt = _pdt.max().date()
            if _min_dt is None or _max_dt is None:
                if period_col and period_col in work_df.columns:
                    _pdt_fb = pd.to_datetime(work_df[period_col], errors="coerce", dayfirst=True).dropna()
                    if not _pdt_fb.empty:
                        _min_dt = _pdt_fb.min().date()
                        _max_dt = _pdt_fb.max().date()
            if _min_dt is None or _max_dt is None:
                _min_dt = date.today().replace(day=1)
                _max_dt = date.today()

            _gdrs_range_kw = {
                "label": "Период",
                "key": f"{key_prefix}_period_range",
                "help": "Фильтр по диапазону дат (суточные столбцы или колонка «Период»).",
                "format": "DD.MM.YYYY",
            }
            if _min_dt and _max_dt and _min_dt <= _max_dt:
                _gdrs_range_kw["value"] = (_min_dt, _max_dt)
                _gdrs_range_kw["min_value"] = _min_dt
                _gdrs_range_kw["max_value"] = _max_dt
            _rng = st.date_input(**_gdrs_range_kw)
            components.html(
            """
                <script>
                (function() {
                  const dict = new Map([
                    ["January","Январь"],["February","Февраль"],["March","Март"],["April","Апрель"],
                    ["May","Май"],["June","Июнь"],["July","Июль"],["August","Август"],
                    ["September","Сентябрь"],["October","Октябрь"],["November","Ноябрь"],["December","Декабрь"],
                    ["Mo","Пн"],["Tu","Вт"],["We","Ср"],["Th","Чт"],["Fr","Пт"],["Sa","Сб"],["Su","Вс"],
                    ["None","Нет"]
                  ]);
                  const root = window.parent && window.parent.document ? window.parent.document : document;

                  const shouldSkip = (el) => {
                    if (!el || !el.tagName) return true;
                    const t = el.tagName.toLowerCase();
                    if (t === "script" || t === "style" || t === "textarea" || t === "input") return true;
                    if (t === "svg" || t === "path") return true;
                    if (el.isContentEditable) return true;
                    return false;
                  };

                  const replaceInTextNode = (node) => {
                    const raw = node.nodeValue || "";
                    const txt = raw.trim();
                    if (!txt) return;
                    if (dict.has(txt)) {
                      node.nodeValue = raw.replace(txt, dict.get(txt));
                      return;
                    }
                    let next = raw;
                    for (const [en, ru] of dict.entries()) {
                      next = next.replace(new RegExp("\\\\b" + en + "\\\\b", "g"), ru);
                    }
                    if (next !== raw) node.nodeValue = next;
                  };

                  const apply = () => {
                    const all = root.querySelectorAll("*");
                    all.forEach((el) => {
                      if (shouldSkip(el)) return;
                      const childs = el.childNodes || [];
                      for (let i = 0; i < childs.length; i++) {
                        const n = childs[i];
                        if (n && n.nodeType === Node.TEXT_NODE) replaceInTextNode(n);
                      }
                    });
                  };
                  apply();
                  const obs = new MutationObserver(apply);
                  obs.observe(root.body, { childList: true, subtree: true });
                })();
                </script>
                """,
                height=0,
                width=0,
            )
            _d_from = None
            _d_to = None
            try:
                if isinstance(_rng, (tuple, list)) and len(_rng) == 2:
                    _d_from, _d_to = _rng[0], _rng[1]
                else:
                    _d_from = _rng
                    _d_to = _rng
            except Exception:
                _d_from, _d_to = _min_dt, _max_dt
            if _d_from and _d_to and _d_from > _d_to:
                _d_from, _d_to = _d_to, _d_from
            if len(_daily_dates) > 1:
                selected_daily_dates = [
                    d for d in _daily_dates if (_d_from <= d.date() <= _d_to)
                ]
            elif period_col and period_col in work_df.columns:
                selected_periods = []
            else:
                st.info("Колонка 'Период' не найдена")

    # Apply filters
    filtered_df = work_df.copy()
    if selected_projects and project_col and project_col in filtered_df.columns:
        _sel_k = [_project_filter_norm_key(p) for p in selected_projects if _project_filter_norm_key(p)]
        project_mask = filtered_df[project_col].map(_project_filter_norm_key).isin(_sel_k)
        filtered_df = filtered_df[project_mask]
    if selected_contractor != "Все" and "Контрагент" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["Контрагент"].astype(str).str.strip()
            == str(selected_contractor).strip()
        ]
    # Для файлов с суточными колонками: пересчёт План/Факт пропорционально выбранному диапазону дат.
    if len(_daily_dates) > 1:
        total_days = len(_daily_dates)
        picked_days = len(selected_daily_dates) if selected_daily_dates else total_days
        day_ratio = (float(picked_days) / float(total_days)) if total_days else 1.0
        filtered_df = filtered_df.copy()
        if "week_sum" in filtered_df.columns:
            filtered_df["week_sum"] = (
                pd.to_numeric(filtered_df["week_sum"], errors="coerce").fillna(0.0) * day_ratio
            )
        if "План_numeric" in filtered_df.columns:
            filtered_df["План_numeric"] = (
                pd.to_numeric(filtered_df["План_numeric"], errors="coerce").fillna(0.0) * day_ratio
            )
        if "Дельта_numeric" in filtered_df.columns:
            filtered_df["Дельта_numeric"] = filtered_df["План_numeric"] - filtered_df["week_sum"]
    # Для месячных периодов (без суточных колонок): фильтрация/пересчёт по пересечению диапазона дат с месяцем строки.
    if len(_daily_dates) <= 1 and period_col and period_col in filtered_df.columns and _d_from and _d_to:
        _pf = pd.Timestamp(_d_from)
        _pt = pd.Timestamp(_d_to)
        _pser = pd.to_datetime(filtered_df[period_col], errors="coerce", dayfirst=True)
        if _pser.notna().any():
            _month_start = _pser.dt.to_period("M").dt.start_time
            _month_end = _pser.dt.to_period("M").dt.end_time
            _lo = pd.concat([_month_start, pd.Series([_pf] * len(filtered_df), index=filtered_df.index)], axis=1).max(axis=1)
            _hi = pd.concat([_month_end, pd.Series([_pt] * len(filtered_df), index=filtered_df.index)], axis=1).min(axis=1)
            _overlap_days = (_hi - _lo).dt.total_seconds() / 86400.0 + 1.0
            _overlap_days = _overlap_days.clip(lower=0.0)
            _days_in_month = _pser.dt.days_in_month.astype(float)
            _ratio = (_overlap_days / _days_in_month).fillna(0.0).clip(lower=0.0, upper=1.0)
            if bool((_ratio > 0.0).any()) is False and len(filtered_df) > 0:
                _ratio = pd.Series(1.0, index=filtered_df.index, dtype="float64")
                suppress_caption(
                    "Диапазон дат в фильтре не пересекается с месяцом данных (например, апрель в календаре, а "
                    "выгрузка — за другой месяц). Показаны исходные план/факт без сужения; уточните период."
                )
            else:
                keep = _ratio > 0.0
                filtered_df = filtered_df[keep].copy()
                if not filtered_df.empty:
                    _ratio = _ratio.loc[filtered_df.index]
                if filtered_df.empty:
                    _ratio = None
            if _ratio is not None and not filtered_df.empty:
                for _col in ("week_sum", "План_numeric", "Дельта_numeric"):
                    if _col in filtered_df.columns:
                        filtered_df[_col] = pd.to_numeric(filtered_df[_col], errors="coerce").fillna(0.0) * _ratio
                for _wk in range(1, 7):
                    _wn = f"{_wk} неделя_numeric"
                    if _wn in filtered_df.columns:
                        filtered_df[_wn] = pd.to_numeric(filtered_df[_wn], errors="coerce").fillna(0.0) * _ratio

    if filtered_df.empty:
        st.info("Нет данных для отображения с выбранными фильтрами.")
        return

    # Ensure Контрагент column exists and has values
    if (
        "Контрагент" not in filtered_df.columns
        or filtered_df["Контрагент"].isna().all()
    ):
        st.error("Колонка 'Контрагент' отсутствует или пуста после фильтрации.")
        return

    # Remove rows where Контрагент is NaN before grouping
    filtered_df = filtered_df[filtered_df["Контрагент"].notna()].copy()

    if filtered_df.empty:
        st.info("Нет данных с указанными контрагентами после фильтрации.")
        return

    # Определяем список проектов для обработки
    if selected_projects and project_col and project_col in filtered_df.columns:
        projects_to_process = selected_projects
    else:
        # Если проекты не выбраны или колонка не найдена, обрабатываем все проекты
        if project_col and project_col in filtered_df.columns:
            projects_to_process = sorted(
                filtered_df[project_col].dropna().unique().tolist()
            )
        else:
            projects_to_process = ["Все проекты"]

    def _gdrs_plan_fact_data_slice(pdf: pd.DataFrame) -> pd.DataFrame:
        if pdf is None or pdf.empty:
            return pdf
        if "data_source" not in pdf.columns:
            return pdf
        dst = (data_source_filter or "").strip().lower()
        if dst == "техника":
            return pdf[
                pdf["data_source"].astype(str).str.strip().str.lower() == "техника"
            ].copy()
        if dst == "ресурсы":
            return pdf[
                pdf["data_source"].astype(str).str.strip().str.lower() == "ресурсы"
            ].copy()
        rk = st.session_state.get(f"{key_prefix}_resource_kind", "Рабочие (ресурсы)")
        if rk == "Техника":
            return pdf[
                pdf["data_source"].astype(str).str.strip().str.lower() == "техника"
            ].copy()
        if rk == "Все":
            return pdf[
                pdf["data_source"].astype(str).str.strip().str.lower() == "ресурсы"
            ].copy()
        return pdf[pdf["data_source"].astype(str).str.strip().str.lower() == "ресурсы"].copy()

    def _gdrs_plan_fact_fig_and_metrics(pdf: pd.DataFrame):
        d = _gdrs_plan_fact_data_slice(pdf)
        if d is None or d.empty or "План_numeric" not in d.columns or "week_sum" not in d.columns:
            return None, None
        _plan_per_c = pd.to_numeric(d["План_numeric"], errors="coerce").fillna(0)
        if "Контрагент" in d.columns:
            _d_tmp = d[["Контрагент"]].copy()
            _d_tmp["_pn"] = _plan_per_c
            plan_sum = float(_d_tmp.groupby("Контрагент")["_pn"].max().sum())
        else:
            plan_sum = float(_plan_per_c.max())
        _ws_pf = pd.to_numeric(d["week_sum"], errors="coerce").fillna(0.0)
        fact_sum = float((_ws_pf / week_fact_den).sum())
        if plan_sum <= 0 and fact_sum <= 0:
            return None, None
        dev = plan_sum - fact_sum
        fp_pct = (fact_sum / plan_sum * 100.0) if plan_sum else 0.0
        proj_col_local = "project name" if "project name" in d.columns else ("Проект" if "Проект" in d.columns else None)
        proj_name = "Все проекты"
        if proj_col_local and proj_col_local in d.columns:
            _u = d[proj_col_local].dropna().astype(str).str.strip().unique().tolist()
            if len(_u) == 1:
                proj_name = _u[0]

        def _fact_bar_color(plan_v: float, fact_v: float) -> str:
            _light_green = "#2ECC71"
            _orange = "#F39C12"
            if plan_v <= 0:
                return _orange
            if float(fact_v) <= 0:
                return "#c0392b"
            if fact_v >= plan_v:
                return _light_green
            miss_ratio = max(0.0, min(1.0, (plan_v - fact_v) / plan_v))
            lo = (255, 179, 179)
            hi = (192, 57, 43)
            rr = int(round(lo[0] + (hi[0] - lo[0]) * miss_ratio))
            gg = int(round(lo[1] + (hi[1] - lo[1]) * miss_ratio))
            bb = int(round(lo[2] + (hi[2] - lo[2]) * miss_ratio))
            return f"#{rr:02x}{gg:02x}{bb:02x}"

        fact_color = _fact_bar_color(plan_sum, fact_sum)

        def _ceil_int(v: float) -> int:
            try:
                fv = float(v)
            except (TypeError, ValueError):
                return 0
            if fv >= 0:
                return int(np.ceil(fv))
            return -int(np.ceil(abs(fv)))

        plan_i = _ceil_int(plan_sum)
        fact_i = _ceil_int(fact_sum)
        dev_i = _ceil_int(dev)
        fig_pie_pf = go.Figure(
            data=[
                go.Bar(
                    x=["План", "Факт"],
                    y=[plan_sum, fact_sum],
                    marker_color=["#2E86AB", fact_color],
                    text=[f"{plan_i}", f"{fact_i}<br>Δ {dev_i}"],
                    textposition="outside",
                    textfont=dict(size=13, color="#ffffff"),
                    cliponaxis=False,
                    customdata=[
                        [proj_name, plan_i, fact_i, dev_i],
                        [proj_name, plan_i, fact_i, dev_i],
                    ],
                    hovertemplate=(
                        "<b>%{x}</b><br>"
                        "Проект: %{customdata[0]}<br>"
                        "План: %{customdata[1]}<br>"
                        "Факт: %{customdata[2]}<br>"
                        "Отклонение: %{customdata[3]}<extra></extra>"
                    ),
                )
            ]
        )
        fig_pie_pf.update_layout(
            height=460,
            showlegend=False,
            margin=dict(l=48, r=28, t=56, b=72),
            yaxis=dict(title=""),
            uniformtext=dict(minsize=7, mode="show"),
        )
        fig_pie_pf = _apply_bar_uniformtext(fig_pie_pf)
        try:
            fig_pie_pf.update_layout(uniformtext=dict(minsize=6, mode="show"))
        except Exception:
            pass
        fig_pie_pf = apply_chart_background(fig_pie_pf)
        return fig_pie_pf, {
            "plan": plan_sum,
            "fact": fact_sum,
            "dev": dev,
            "fp_pct": fp_pct,
        }

    def _gdrs_contractor_fact_fig_and_metrics(pdf: pd.DataFrame):
        """Круговая: доля факта по подрядчикам; в секторе только %; названия — легенда слева."""
        d = _gdrs_plan_fact_data_slice(pdf)
        if d is None or d.empty:
            return None, None
        if "Контрагент" not in d.columns or "week_sum" not in d.columns:
            return None, None
        d = d.copy()
        _ws_cf = pd.to_numeric(d["week_sum"], errors="coerce").fillna(0.0)
        d["_f"] = _ws_cf / week_fact_den
        d["_p"] = (
            pd.to_numeric(d["План_numeric"], errors="coerce").fillna(0)
            if "План_numeric" in d.columns
            else 0.0
        )
        by_c = d.groupby("Контрагент", as_index=False)["_f"].sum()
        by_c = by_c[by_c["_f"] > 0].sort_values("_f", ascending=False)
        if by_c.empty or float(by_c["_f"].sum()) <= 0:
            return None, None
        plan_by = d.groupby("Контрагент", as_index=False)["_p"].sum()
        pie_df = by_c.merge(plan_by, on="Контрагент", how="left").fillna({"_p": 0.0})
        pie_df = pie_df.rename(columns={"_f": "Факт", "_p": "План"})
        pie_df["Отклонение"] = pie_df["План"] - pie_df["Факт"]

        labels = pie_df["Контрагент"].astype(str).tolist()
        values = pie_df["Факт"].astype(float).tolist()

        _cd = []
        for i in range(len(pie_df)):
            _dev = float(pie_df.iloc[i]["Отклонение"])
            _dv = int(np.ceil(_dev)) if _dev >= 0 else -int(np.ceil(abs(_dev)))
            _cd.append(
                (
                    int(np.ceil(float(pie_df.iloc[i]["План"]))),
                    int(np.ceil(float(pie_df.iloc[i]["Факт"]))),
                    _dv,
                )
            )

        fig_cf = go.Figure(
            data=[
                go.Pie(
                    labels=labels,
                    values=values,
                    customdata=_cd,
                    sort=False,
                    direction="clockwise",
                    hole=0.0,
                    hovertemplate=(
                        "<b>%{label}</b><br>"
                        "План: %{customdata[0]}<br>"
                        "Факт: %{customdata[1]}<br>"
                        "Откл.: %{customdata[2]}<extra></extra>"
                    ),
                    showlegend=True,
                    marker=dict(line=dict(width=0)),
                )
            ]
        )
        fig_cf = apply_standard_pie_layout(
            fig_cf,
            height=440,
            pct_fontsize=17,
        )
        fig_cf = apply_chart_background(fig_cf, skip_uniformtext=True)

        if "План_numeric" in d.columns and "Контрагент" in d.columns:
            _dp = d[["Контрагент"]].copy()
            _dp["_pn"] = pd.to_numeric(d["План_numeric"], errors="coerce").fillna(0)
            plan_sum = float(_dp.groupby("Контрагент")["_pn"].max().sum())
        elif "План_numeric" in d.columns:
            plan_sum = float(pd.to_numeric(d["План_numeric"], errors="coerce").fillna(0).max())
        else:
            plan_sum = 0.0
        fact_sum = float(by_c["_f"].sum())
        dev = plan_sum - fact_sum
        fp_pct = (fact_sum / plan_sum * 100.0) if plan_sum else None
        return fig_cf, {"plan": plan_sum, "fact": fact_sum, "dev": dev, "fp_pct": fp_pct}

    def _gdrs_fp_pct_caption_line(met: dict) -> str:
        _pl = float(met.get("plan") or 0.0)
        _fp = met.get("fp_pct")
        if _pl <= 0 or _fp is None:
            return ""
        try:
            return f" ({float(_fp):.1f}% — факт/план)"
        except (TypeError, ValueError):
            return ""

    # Сводные KPI по текущим фильтрам (PDF / docs 17 — суммы план/факт/отклонение).
    if "week_sum" in filtered_df.columns:
        _ws_kpi = pd.to_numeric(filtered_df["week_sum"], errors="coerce").fillna(0.0)
        _kp_fact = float((_ws_kpi / week_fact_den).sum())
        if "План_numeric" in filtered_df.columns and "Контрагент" in filtered_df.columns:
            _kpi_tmp = filtered_df[["Контрагент"]].copy()
            _kpi_tmp["_pn"] = pd.to_numeric(filtered_df["План_numeric"], errors="coerce").fillna(0.0)
            _kp_plan = float(_kpi_tmp.groupby("Контрагент")["_pn"].max().sum())
        elif "План_numeric" in filtered_df.columns:
            _kp_plan = float(pd.to_numeric(filtered_df["План_numeric"], errors="coerce").fillna(0.0).max())
        else:
            _kp_plan = 0.0
        _kp_dev = _kp_plan - _kp_fact
        _kp_dev_color = (
            "#ff5454" if _kp_dev > 0 else ("#46d68a" if _kp_dev < 0 else "#8899aa")
        )
        _km1, _km2, _km3 = st.columns(3, gap="small")
        with _km1:
            st.metric("План (сумма)", f"{int(round(_kp_plan))}")
        with _km2:
            st.metric("Факт (сумма)", f"{int(round(_kp_fact))}")
        with _km3:
            _kp_dev_i = int(round(_kp_dev))
            _kp_dev_txt = f"{_kp_dev_i:+d}" if _kp_dev_i != 0 else "0"
            st.markdown(
                f"<div><span style='color:#aaa;font-size:13px;'>Отклонение (план − факт)</span><br>"
                f"<span style='font-size:24px;font-weight:700;color:{_kp_dev_color};'>{_kp_dev_txt}</span></div>",
                unsafe_allow_html=True,
            )

    # Референсная таблица ГДРС: проект -> контрагент -> вид работ.
    # По PDF: Отклонение = План − Факт (Факт ≈ СКУД / недели по методике экрана).
    if "Контрагент" in filtered_df.columns:
        _gdrs_tab_is_tech = (data_source_filter or "").strip().lower() in (
            "техника",
            "tech",
            "technique",
        )
        _ref_df = st.session_state.get("reference_contractors")
        _ref_empty = _ref_df is None or getattr(_ref_df, "empty", True)
        _fact_sum = float(
            pd.to_numeric(filtered_df.get("week_sum"), errors="coerce").fillna(0.0).abs().sum()
        )
        _plan_sum_f = float(
            pd.to_numeric(filtered_df.get("План_numeric"), errors="coerce").fillna(0.0).abs().sum()
        )
        _tbl = filtered_df.copy()

        def _to_num_safe(series):
            s = (
                series.astype(str)
                .str.replace("\u00a0", "", regex=False)
                .str.replace(" ", "", regex=False)
                .str.replace(",", ".", regex=False)
            )
            s = s.str.replace(r"[^0-9\.\-]+", "", regex=True)
            return pd.to_numeric(s, errors="coerce").fillna(0.0)

        # СКУД: по вкладке — из строк «Ресурсы» или «Техника» (см. data_source).
        if "data_source" in _tbl.columns:
            _skud_source_label = "Техника" if _gdrs_tab_is_tech else "Ресурсы"
            _res_mask = _gdrs_match_data_source(_tbl["data_source"], _skud_source_label)
            if _res_mask.any():
                _tbl = _tbl.loc[_res_mask].copy()

        # mapping_spec 4.3: вкладка «Ресурсы» — только рабочие; техника — в «ГДРС Техника».
        if (not _gdrs_tab_is_tech) and (not _tbl.empty):
            _tr_col = find_column_by_partial(
                _tbl,
                [
                    "тип ресурсов",
                    "тип ресурса",
                    "вид ресурсов",
                    "Вид работ",
                    "вид работ",
                    "Вид работы",
                ],
            )
            if _tr_col and _tr_col in _tbl.columns:
                _tv = _tbl[_tr_col].astype(str).str.strip().str.lower()
                _only_workers = _tv.str.contains("рабоч", na=False) & ~_tv.str.contains(
                    "техник",
                    na=False,
                )
                if _only_workers.any():
                    _tbl = _tbl.loc[_only_workers].copy()

        if not _tbl.empty:
            _work_type_col = find_column_by_partial(
                _tbl,
                ["Вид работ", "Вид работы", "вид работ", "вид работы", "тип ресурсов", "тип работ", "work type"],
            )

            # План: договор (если в resursi есть) → «План» в файле → План_numeric (merge 1С),
            # иначе пустой столбец «План» в выгрузке затирал план из справочника 1С.
            _tbl["_plan_ref_numeric"] = _gdrs_coalesce_plan_for_gdrs_table(
                _tbl, _to_num_safe
            )

            _daily_hdr_cols = [c for c in _tbl.columns if _gdrs_header_is_dd_mm_yyyy(c)]
            # В эталонной визуализации ГДРС фиксированная сетка 1..6 недель.
            _weeks_in_month = 6

            _week_cols_out = [f"{i} неделя" for i in range(1, _weeks_in_month + 1)]
            _week_map = {}
            for i in range(1, _weeks_in_month + 1):
                _wcol = find_column_by_partial(
                    _tbl, [f"{i} неделя", f"{i} недел", f"недел {i}", f"week {i}"]
                )
                if _wcol and _wcol in _tbl.columns:
                    _week_map[f"{i} неделя"] = _wcol

            if (not _week_map) and _daily_hdr_cols:
                for i in range(1, _weeks_in_month + 1):
                    _tbl[f"{i} неделя_numeric"] = 0.0
                for _dc in _daily_hdr_cols:
                    _ts = pd.to_datetime(
                        re.sub(r"\.{2,3}", ".", str(_dc).strip()),
                        errors="coerce",
                        dayfirst=True,
                    )
                    if pd.isna(_ts):
                        continue
                    _widx = max(1, min(_weeks_in_month, int(np.ceil(int(_ts.day) / 7.0))))
                    _vals = pd.to_numeric(_tbl[_dc], errors="coerce").fillna(0.0)
                    if float(_vals.abs().sum()) == 0.0:
                        _vals = _to_num_safe(_tbl[_dc])
                    _tbl[f"{_widx} неделя_numeric"] = (
                        pd.to_numeric(_tbl[f"{_widx} неделя_numeric"], errors="coerce").fillna(0.0)
                        + _vals
                    )
            # После groupby по суточным колонкам в work_df суток уже нет — week_sum остаётся, недели 0. Делим факт.
            if (not _week_map) and (not _daily_hdr_cols) and "week_sum" in _tbl.columns:
                _ws_line = pd.to_numeric(_tbl["week_sum"], errors="coerce").fillna(0.0)
                _den = float(max(1, int(_weeks_in_month)))
                for i in range(1, _weeks_in_month + 1):
                    _tbl[f"{i} неделя_numeric"] = _ws_line / _den

            for _w in _week_cols_out:
                if f"{_w}_numeric" not in _tbl.columns:
                    if _w in _week_map:
                        _src = _week_map[_w]
                        _vals = pd.to_numeric(_tbl[_src], errors="coerce").fillna(0.0)
                        if float(_vals.abs().sum()) == 0.0:
                            _vals = _to_num_safe(_tbl[_src])
                        _tbl[f"{_w}_numeric"] = _vals
                    else:
                        _tbl[f"{_w}_numeric"] = 0.0

            _group_cols = []
            if project_col and project_col in _tbl.columns:
                _group_cols.append(project_col)
            _group_cols.append("Контрагент")
            if _work_type_col and _work_type_col in _tbl.columns:
                _group_cols.append(_work_type_col)

            _agg = {"_plan_ref_numeric": "max"}
            for _w in _week_cols_out:
                _agg[f"{_w}_numeric"] = "sum"
            _ref = _tbl.groupby(_group_cols, as_index=False, dropna=False).agg(_agg)
            _ref = _ref.rename(columns={"_plan_ref_numeric": "План"})

            for _w in _week_cols_out:
                _ref[_w] = pd.to_numeric(_ref[f"{_w}_numeric"], errors="coerce").fillna(0.0)
            _ref["СКУД"] = (
                _ref[_week_cols_out].sum(axis=1) / float(_weeks_in_month)
            ).round(0)
            _ref["План"] = pd.to_numeric(_ref["План"], errors="coerce").fillna(0.0)
            _ref["Отклонение"] = _ref["План"] - _ref["СКУД"]
            _ref["Отклонение %"] = _ref.apply(
                lambda r: round(float(r["Отклонение"]) / float(r["План"]) * 100.0, 1)
                if float(r["План"]) != 0.0
                else None,
                axis=1,
            )

            if _work_type_col and _work_type_col in _ref.columns:
                _ref = _ref.rename(columns={_work_type_col: "Вид работы"})
            else:
                _ref["Вид работы"] = "Рабочие" if not _gdrs_tab_is_tech else "—"
            if not _gdrs_tab_is_tech:
                _vw = (
                    _ref["Вид работы"]
                    .astype(str)
                    .str.strip()
                    .replace({"nan": "", "None": "", "<NA>": ""})
                )
                _ref["Вид работы"] = _vw.mask(_vw.eq("") | _vw.eq("—"), "Рабочие")
            if (not project_col) or (project_col not in _ref.columns):
                _proj_fallback = find_column_by_partial(
                    _ref,
                    ["Проект", "проект", "Наименование_Проекта", "project name"],
                )
                if _proj_fallback and _proj_fallback in _ref.columns:
                    project_col = _proj_fallback
            if project_col and project_col in _ref.columns:
                _ref["_Проект"] = _ref[project_col].fillna("Без проекта").astype(str).str.strip()
            else:
                _ref["_Проект"] = "Все проекты"

            from dashboards.gdrs_resursi import (
                GDRS_WEEK_PLAN_KEYS,
                GDRS_WEEK_SKUD_KEYS,
                render_gdrs_matrix_table_html,
            )

            for _wi, (_pk, _sk, _wlbl) in enumerate(
                zip(GDRS_WEEK_PLAN_KEYS, GDRS_WEEK_SKUD_KEYS, _week_cols_out), start=1
            ):
                _ref[_pk] = (
                    pd.to_numeric(_ref["План"], errors="coerce").fillna(0.0).round(0).astype(int)
                )
                _ref[_sk] = (
                    pd.to_numeric(_ref[_wlbl], errors="coerce").fillna(0.0).round(0).astype(int)
                )

            def _agg_block(_sub: pd.DataFrame) -> dict:
                _plan = float(pd.to_numeric(_sub["План"], errors="coerce").fillna(0.0).sum())
                _ws = {
                    sk: float(pd.to_numeric(_sub[sk], errors="coerce").fillna(0.0).sum())
                    for sk in GDRS_WEEK_SKUD_KEYS
                }
                _skud = int(round(sum(_ws.values()) / float(_weeks_in_month), 0))
                _dev = float(_plan - _skud)
                _pct = round((_dev / _plan) * 100.0, 1) if _plan != 0.0 else None
                _plan_i = int(round(_plan))
                _pw = {pk: _plan_i for pk in GDRS_WEEK_PLAN_KEYS}
                return {"План": _plan, "СКУД": _skud, "Отклонение": _dev, **_pw, **_ws, "Отклонение %": _pct}

            _rows = []
            for _proj in sorted(_ref["_Проект"].unique(), key=lambda x: str(x)):
                _p = _ref[_ref["_Проект"] == _proj]
                # Заголовок блока проекта с агрегатами (как в эталонной таблице).
                _rows.append({"__row_kind": "project", "Контрагент": str(_proj), "Вид работы": "", **_agg_block(_p)})
                _d = _p.sort_values(["Контрагент", "Вид работы"], na_position="last")
                for _, _r in _d.iterrows():
                    _rows.append(
                        {
                            "__row_kind": "detail",
                            "Контрагент": str(_r.get("Контрагент", "") or ""),
                            "Вид работы": _r.get("Вид работы", ""),
                            "План": _r["План"],
                            "СКУД": _r["СКУД"],
                            "Отклонение": _r["Отклонение"],
                            **{pk: int(_r[pk]) for pk in GDRS_WEEK_PLAN_KEYS},
                            **{sk: int(_r[sk]) for sk in GDRS_WEEK_SKUD_KEYS},
                            "Отклонение %": _r["Отклонение %"],
                        }
                    )

            _view = pd.DataFrame(_rows)
            _grand = _agg_block(_ref)
            _view = pd.concat(
                [
                    _view,
                    pd.DataFrame(
                        [{"__row_kind": "total", "Контрагент": "Итого", "Вид работы": "", **_grand}]
                    ),
                ],
                ignore_index=True,
            )
            _view["_delta_pct_raw"] = pd.to_numeric(_view["Отклонение %"], errors="coerce")
            for _c in (
                ["План", "СКУД", "Отклонение"]
                + list(GDRS_WEEK_PLAN_KEYS)
                + list(GDRS_WEEK_SKUD_KEYS)
            ):
                _view[_c] = pd.to_numeric(_view[_c], errors="coerce").fillna(0).round(0).astype(int)
            _view["Отклонение %"] = _view["_delta_pct_raw"].apply(
                lambda v: f"{float(v):.1f}%" if v is not None and pd.notna(v) else "—"
            )

            # Проверка кейса «План = Факт»: в референсе это считается подозрительным.
            try:
                _pl_sum = float(pd.to_numeric(_ref["План"], errors="coerce").fillna(0.0).sum())
                _sk_sum = float(pd.to_numeric(_ref["СКУД"], errors="coerce").fillna(0.0).sum())
                if _pl_sum > 0 and _sk_sum > 0 and abs(_pl_sum - _sk_sum) <= max(1.0, 0.001 * _pl_sum):
                    suppress_caption(
                        "Проверка данных: сумма «План» ≈ сумме «СКУД» (план почти равен факту). "
                        "Если по проекту это не ожидается — проверьте маппинг колонок плана (договор) и факта (ресурсы/недели)."
                    )
            except Exception:
                pass

            _show_cols = (
                ["Контрагент", "Вид работы", "План", "СКУД", "Отклонение"]
                + list(GDRS_WEEK_PLAN_KEYS)
                + list(GDRS_WEEK_SKUD_KEYS)
                + ["Отклонение %"]
            )
            _render_cols = (
                (["__row_kind", "_delta_pct_raw"] + _show_cols)
                if "__row_kind" in _view.columns
                else (["_delta_pct_raw"] + _show_cols)
            )

            _period_title = ""
            if _d_from and _d_to:
                _period_title = _format_gdrs_period_range_dd_mm_yyyy(_d_from, _d_to)
                if not _period_title:
                    _period_title = f"{_d_from} - {_d_to}"
            elif period_col and period_col in filtered_df.columns:
                _pvals = pd.to_datetime(filtered_df[period_col], errors="coerce", dayfirst=True).dropna()
                if not _pvals.empty:
                    _pmin = _pvals.min()
                    _pmax = _pvals.max()
                    _ms = pd.Timestamp(_pmin).to_period("M").start_time.normalize().date()
                    _me = pd.Timestamp(_pmax).to_period("M").end_time.normalize().date()
                    _period_title = _format_gdrs_period_range_dd_mm_yyyy(_ms, _me)

            _period_row_display = _format_gdrs_month_year_title_ru(
                _d_from, _d_to, filtered_df, period_col
            ) or _period_title

            _gdrs_ref_line1 = (
                "График движения рабочей силы (техника)"
                if _gdrs_tab_is_tech
                else "График движения рабочей силы (люди)"
            )

            def _render_gdrs_ref_html(df_view: pd.DataFrame) -> str:
                ncols = len(_show_cols)
                wk_n = len(_week_cols_out)
                wrap_id = "gdrs_tbl_" + str(id(df_view))
                parts = [
                    f'<div id="{wrap_id}" style="overflow-x:auto;min-width:0;margin:0.75em 0;">',
                    f"<style>"
                    f"#{wrap_id} table{{border-collapse:collapse;background-color:{TABLE_BG_COLOR};color:{TABLE_TEXT_COLOR};font-size:13px;border:1px solid rgba(255,255,255,0.45);}}"
                    f"#{wrap_id} th{{border:1px solid rgba(255,255,255,0.45);padding:4px 6px;white-space:normal;word-wrap:break-word;overflow-wrap:anywhere;line-height:1.25;overflow:visible;text-overflow:clip;vertical-align:bottom;max-width:11em;}}"f"#{wrap_id} td{{border:1px solid rgba(255,255,255,0.45);padding:4px 6px;white-space:normal;word-wrap:break-word;overflow-wrap:anywhere;overflow:visible;text-overflow:clip;vertical-align:top;max-width:28em;}}"f"#{wrap_id} th.t-center,#{wrap_id} td.t-center{{white-space:nowrap;max-width:none;overflow:visible;text-overflow:clip;}}"
                    f"#{wrap_id} thead th{{background-color:{TABLE_BG_COLOR};font-weight:700;border:1px solid rgba(255,255,255,0.45)!important;}}"
                    f"#{wrap_id} thead tr{{border-bottom:1px solid rgba(255,255,255,0.45)!important;}}"
                    f"#{wrap_id} thead tr.title-row{{border-bottom:none!important;}}"
                    f"#{wrap_id} thead tr.title-row th{{border-bottom:none!important;}}"
                    f"#{wrap_id} thead tr.period-row th{{border-top:none!important;}}"
                    f"#{wrap_id} .t-center{{text-align:center !important;}}"
                    f"#{wrap_id} .rk-project td{{font-weight:700;background-color:rgba(255,255,255,0.08)!important;border-top:2px solid rgba(255,255,255,0.75)!important;border-bottom:2px solid rgba(255,255,255,0.75)!important;}}"
                    f"#{wrap_id} .rk-project td:first-child{{border-left:2px solid rgba(255,255,255,0.75)!important;}}"
                    f"#{wrap_id} .rk-project td:last-child{{border-right:2px solid rgba(255,255,255,0.75)!important;}}"
                    f"#{wrap_id} .rk-total td{{font-weight:700;background-color:rgba(80,180,255,0.18)!important;border-top:2px solid rgba(160,220,255,0.9)!important;border-bottom:2px solid rgba(160,220,255,0.9)!important;}}"
                    f"#{wrap_id} .rk-total td:first-child{{border-left:2px solid rgba(160,220,255,0.9)!important;}}"
                    f"#{wrap_id} .rk-total td:last-child{{border-right:2px solid rgba(160,220,255,0.9)!important;}}"
                    # Отклонение / Дельта %: та же семантика, что у подписей План/Факт на экране
                    # (красный при «недовыполнении» плана, зелёный при выполнении/перевыполнении).
                    f"#{wrap_id} td.neg{{color:#e74c3c !important;font-weight:700;}}"
                    f"#{wrap_id} td.pos{{color:#27ae60 !important;font-weight:700;}}"
                    f"</style>",
                    "<table>",
                    "<thead>",
                    f'<tr class="title-row"><th colspan="{ncols}" class="t-center" style="text-align:center !important;">{html_module.escape(_gdrs_ref_line1)}</th></tr>',
                    f'<tr class="period-row"><th colspan="{ncols}" class="t-center" style="text-align:center !important;">{html_module.escape(_period_row_display) if _period_row_display else ""}</th></tr>',
                    "<tr>",
                    '<th rowspan="2">Контрагент</th>',
                    '<th rowspan="2">Вид работы</th>',
                    '<th rowspan="2" class="t-center" style="text-align:center !important;">План</th>',
                    '<th rowspan="2" class="t-center" style="text-align:center !important;">СКУД</th>',
                    '<th rowspan="2" class="t-center" style="text-align:center !important;">Отклонение</th>',
                    f'<th colspan="{wk_n}" class="t-center" style="text-align:center !important;">План</th>',
                    f'<th colspan="{wk_n}" class="t-center" style="text-align:center !important;">СКУД</th>',
                    '<th rowspan="2" class="t-center" style="text-align:center !important;">Итого (%)</th>',
                    "</tr>",
                    "<tr>",
                ]
                for w in _week_cols_out:
                    parts.append(f'<th class="t-center">{html_module.escape(str(w))}</th>')
                for w in _week_cols_out:
                    parts.append(f'<th class="t-center">{html_module.escape(str(w))}</th>')
                parts.append("</tr></thead><tbody>")

                for _, row in df_view.iterrows():
                    rk = str(row.get("__row_kind", "")).strip().casefold()
                    tr_cls = f' class="rk-{rk}"' if rk else ""
                    parts.append(f"<tr{tr_cls}>")
                    for c in _show_cols:
                        val = row.get(c, "")
                        s = "" if (val is None or (isinstance(val, float) and pd.isna(val))) else str(val)
                        esc = html_module.escape(s)
                        cls = ""
                        td_style = ""
                        _span_style = ""
                        if c == "Отклонение":
                            num = pd.to_numeric(val, errors="coerce")
                            if pd.notna(num):
                                fn = float(num)
                                if fn > 0:
                                    cls = "neg"
                                    _span_style = "color:#e74c3c !important;font-weight:700;"
                                elif fn < 0:
                                    cls = "pos"
                                    _span_style = "color:#27ae60 !important;font-weight:700;"
                        elif c == "Отклонение %":
                            raw_pct = row.get("_delta_pct_raw")
                            num = pd.to_numeric(raw_pct, errors="coerce")
                            if pd.notna(num):
                                fn = float(num)
                                td_style = _gdrs_delta_pct_cell_bg_style(raw_pct) or ""
                                if fn > 0:
                                    cls = "neg"
                                    _span_style = "color:#e74c3c !important;font-weight:700;"
                                elif fn < 0:
                                    cls = "pos"
                                    _span_style = "color:#27ae60 !important;font-weight:700;"
                        if _span_style:
                            esc = f'<span style="{_span_style}">{esc}</span>'
                        tcenter = " t-center" if c not in ("Контрагент", "Вид работы") else ""
                        parts.append(
                            f'<td class="{(cls + tcenter).strip()}" style="{td_style}">{esc}</td>'
                        )
                    parts.append("</tr>")
                parts.append("</tbody></table></div>")
                return "".join(parts)

            from dashboards.gdrs_resursi import render_gdrs_matrix_table_html as _gdrs_mtx_html

            _ref_export = _view[_show_cols].copy()
            render_report_html_table(
                _gdrs_mtx_html(
                    _view[_render_cols],
                    fixed_cols=["Контрагент", "Вид работы", "План", "СКУД", "Отклонение"],
                    delta_col="Отклонение %",
                    kind_col="__row_kind",
                    title_line=_gdrs_ref_line1,
                    period_line=_period_row_display,
                    delta_bg_style=_gdrs_delta_pct_cell_bg_style,
                ),
                export_df=_ref_export,
                file_stem=_export_file_stem(_gdrs_ref_line1),
                key_prefix=f"gdrs_ref_matrix_{abs(id(_view))}",
            )
            suppress_caption(
                "Пояснение: «СКУД» в строке — среднее по столбцам 1–6 недели (как в методичке по неделям). "
                "В строке «Итого» значения по неделям — сумма по строкам таблицы; «СКУД» — среднее этих шести сумм "
                "(не сумма столбца «СКУД» по строкам)."
            )

    period_col_hist = _gdrs_resolve_period_column(filtered_df)
    if period_col_hist and "week_sum" in filtered_df.columns:
        sources_hist = []
        if "data_source" in filtered_df.columns:
            sources_hist = filtered_df["data_source"].dropna().unique().tolist()
        else:
            sources_hist = [None]
        source_labels_hist = []
        for s in sources_hist:
            if s is None:
                source_labels_hist.append("Данные")
            elif str(s).strip() == "Ресурсы":
                source_labels_hist.append("Люди (ресурсы)")
            elif str(s).strip() == "Техника":
                source_labels_hist.append("Техника")
            else:
                source_labels_hist.append(str(s))
        dyn_grain = st.radio(
            "Шкала динамики (ось X)",
            options=("Неделя", "Месяц", "Год"),
            index=0,
            horizontal=True,
            key=f"{key_prefix}_dyn_grain",
            help="PDF: «Динамика по рабочим/технике» — неделя / месяц / год.",
        )
        hist_cols = st.columns(max(1, len(sources_hist, gap="small")))
        for idx, (src, label) in enumerate(zip(sources_hist, source_labels_hist)):
            if src is None:
                df_hist = filtered_df.copy()
            else:
                df_hist = filtered_df[_gdrs_match_data_source(filtered_df["data_source"], src)].copy()
            if df_hist.empty:
                with hist_cols[idx]:
                    st.info(f"**{label}** — нет данных для графика «Факт по периодам».")
                continue
            # Колонки по неделям (1 неделя_numeric, 2 неделя_numeric, ...)
            week_numeric_cols_hist = [
                c for c in df_hist.columns
                if isinstance(c, str) and "_numeric" in c and "недел" in c.lower()
            ]
            if not week_numeric_cols_hist:
                for i in range(1, 7):
                    cn = f"{i} неделя_numeric"
                    if cn in df_hist.columns:
                        week_numeric_cols_hist.append(cn)
            week_numeric_cols_hist = sorted(week_numeric_cols_hist, key=lambda c: (
                int(c.split()[0]) if c.split() and c.split()[0].isdigit() else 99
            ))
            if week_numeric_cols_hist:
                # Группировка по периоду, точки — по неделям: melt по неделям, затем groupby(период, неделя)
                id_vars = [period_col_hist]
                value_vars = [c for c in week_numeric_cols_hist if c in df_hist.columns]
                if value_vars:
                    long_df = df_hist[id_vars + value_vars].melt(
                        id_vars=id_vars,
                        value_vars=value_vars,
                        var_name="Неделя",
                        value_name="Факт",
                    )
                    long_df["Неделя"] = long_df["Неделя"].str.replace("_numeric", "").str.strip()
                    long_df["Факт"] = pd.to_numeric(long_df["Факт"], errors="coerce").fillna(0)
                    by_period_week = (
                        long_df.groupby([period_col_hist, "Неделя"], as_index=False)["Факт"]
                        .sum()
                    )
                    by_period_week["Период_стр"] = by_period_week[period_col_hist].astype(str).str.strip()
                    by_period_week = _gdrs_point_pct_of_period_plan(
                        by_period_week, df_hist, period_col_hist, "Факт"
                    )
                    if dyn_grain == "Неделя":
                        by_period_week = _gdrs_hist_collapse_week_grain(
                            by_period_week, period_col_hist, df_hist
                        )
                    if dyn_grain == "Месяц":
                        _m = (
                            by_period_week.groupby(period_col_hist, as_index=False)["Факт"]
                            .sum()
                        )
                        _m["Период_стр"] = _m[period_col_hist].astype(str).str.strip()
                        _m = _gdrs_point_pct_of_period_plan(_m, df_hist, period_col_hist, "Факт")
                        _m["Неделя"] = ""
                        _m["x_label"] = _m["Период_стр"]
                        _m["План_нед"] = pd.to_numeric(_m["План_период"], errors="coerce")
                        by_period_week = _m.sort_values(period_col_hist)
                    elif dyn_grain == "Год":
                        _w = by_period_week.copy()
                        _w["_yr"] = _gdrs_period_series_to_year(_w[period_col_hist])
                        _y = _w.groupby("_yr", as_index=False)["Факт"].sum()
                        _y = _y[pd.notna(_y["_yr"])].copy()
                        if _y.empty:
                            by_period_week = _y
                        else:
                            _y["_yr"] = _y["_yr"].astype(int)
                            _y["Период_стр"] = _y["_yr"].astype(str)
                            _dfy = df_hist.copy()
                            _dfy["_yr"] = _gdrs_period_series_to_year(_dfy[period_col_hist])
                            _plan_y = (
                                _dfy.groupby("_yr")["План_numeric"]
                                .apply(lambda s: float(pd.to_numeric(s, errors="coerce").fillna(0.0).sum()))
                                .reset_index(name="_psum")
                            )
                            _y = _y.merge(_plan_y, on="_yr", how="left")
                            _y["План_период"] = pd.to_numeric(_y["_psum"], errors="coerce")
                            _y.drop(columns=["_psum"], inplace=True, errors="ignore")
                            fac = pd.to_numeric(_y["Факт"], errors="coerce").fillna(0.0)
                            psum = pd.to_numeric(_y["План_период"], errors="coerce").fillna(0.0)
                            _y["%"] = np.where(psum > 0, (fac / psum * 100.0).clip(lower=0.0), 0.0)
                            _y["Неделя"] = ""
                            _y["x_label"] = _y["Период_стр"]
                            _y["План_нед"] = _y["План_период"]
                            by_period_week = _y.sort_values("_yr")
                else:
                    by_period_week = None
            else:
                by_period_week = None
            if by_period_week is not None and not by_period_week.empty:
                fig_hist = go.Figure()
                # R23-05 стр.14: «Динамика» — цвета линий: план — голубой, факт — оранжевый.
                _plan_color = "#5DADE2"
                _fact_color = "#F39C12"
                plot_df = by_period_week.copy()
                if dyn_grain == "Неделя":
                    _wk_num = (
                        plot_df["Неделя"]
                        .astype(str)
                        .str.extract(r"(\d+)", expand=False)
                        .fillna("?")
                    )
                    plot_df["x_tick"] = (
                        plot_df["Период_стр"].astype(str).str.strip() + " · н" + _wk_num
                    )
                    plot_df["x_label"] = plot_df["x_tick"]
                    plot_df = plot_df.sort_values([period_col_hist, "Неделя"])
                    _weeks_per_period = plot_df.groupby("Период_стр")["Неделя"].nunique().to_dict()

                    def _plan_per_week(_row):
                        _pp = _row.get("План_период")
                        try:
                            _pp_f = float(_pp) if pd.notna(_pp) else float("nan")
                        except Exception:  # noqa: BLE001
                            return float("nan")
                        _nw = int(_weeks_per_period.get(_row["Период_стр"], 0) or 0)
                        if _nw <= 0 or not np.isfinite(_pp_f):
                            return float("nan")
                        return _pp_f / _nw

                    plot_df["План_нед"] = plot_df.apply(_plan_per_week, axis=1)
                    _x_title = "Период — неделя"
                    _plan_hover_line = "%{x}<br>План (на неделю): %{y:.0f}<extra></extra>"
                    _cap_grain = "недели"
                else:
                    if "x_label" not in plot_df.columns:
                        plot_df["x_label"] = plot_df["Период_стр"].astype(str)
                    _sort_keys = ["_yr"] if "_yr" in plot_df.columns else [period_col_hist]
                    plot_df = plot_df.sort_values(_sort_keys)
                    if "План_нед" not in plot_df.columns or plot_df["План_нед"].isna().all():
                        plot_df["План_нед"] = pd.to_numeric(plot_df.get("План_период"), errors="coerce")
                    _x_title = "Месяц (период выгрузки)" if dyn_grain == "Месяц" else "Год"
                    _plan_hover_line = "%{x}<br>План (за период): %{y:.0f}<extra></extra>"
                    _cap_grain = "месяц" if dyn_grain == "Месяц" else "год"
                by_period_week = plot_df
                _has_plan_line = bool(
                    by_period_week["План_нед"].notna().any()
                    and (by_period_week["План_нед"].fillna(0) > 0).any()
                )
                x_order = by_period_week["x_label"].tolist()
                _mk_week_lbl_w = lambda r: (
                    f"{int(r['Факт'])} ({int(np.ceil(float(r['%'])))}%)"
                )
                _mk_week_hover_w = lambda r: (
                    f"Факт: {int(r['Факт'])}<br>"
                    f"План (период): {int(np.ceil(float(r['План_период']))) if pd.notna(r.get('План_период')) and float(r.get('План_период') or 0) > 0 else '—'}<br>"
                    f"К плану: {int(np.ceil(float(r['%'])))}%"
                )
                if _has_plan_line:
                    fig_hist.add_trace(
                        go.Scatter(
                            x=by_period_week["x_label"],
                            y=by_period_week["План_нед"],
                            name="План",
                            mode="lines+markers",
                            line=dict(color=_plan_color, width=2, dash="dash"),
                            marker=dict(size=8, color=_plan_color, line=dict(width=1, color="white")),
                            hovertemplate=_plan_hover_line,
                            connectgaps=False,
                            cliponaxis=False,
                        )
                    )
                fig_hist.add_trace(
                    go.Scatter(
                        x=by_period_week["x_label"],
                        y=by_period_week["Факт"],
                        name="Факт",
                        mode="lines+markers+text",
                        line=dict(color=_fact_color, width=2),
                        marker=dict(size=10, color=_fact_color, line=dict(width=1, color="white")),
                        text=[_mk_week_lbl_w(r) for _, r in by_period_week.iterrows()],
                        textposition="top center",
                        textfont=dict(size=9, color="white"),
                        hovertext=[_mk_week_hover_w(r) for _, r in by_period_week.iterrows()],
                        hovertemplate="%{x}<br>%{hovertext}<extra></extra>",
                        connectgaps=False,
                        cliponaxis=False,
                    )
                )
                fig_hist.update_layout(
                    title_text="",
                    xaxis_title=_x_title,
                    yaxis_title="Количество",
                    height=max(400, 320 + min(len(x_order), 16) * 12),
                    showlegend=False,
                    margin=dict(l=56, r=28, t=72, b=max(168, 120 + min(len(x_order), 20) * 6)),
                    uniformtext=dict(minsize=6, mode="hide"),
                    xaxis=dict(
                        tickangle=-35 if len(x_order) > 4 else -25,
                        tickfont=dict(size=9),
                        categoryorder="array",
                        categoryarray=x_order,
                        automargin=True,
                    ),
                    yaxis=dict(automargin=True),
                )
                try:
                    fig_hist.update_xaxes(title_standoff=24)
                except Exception:
                    pass
                fig_hist = apply_chart_background(fig_hist)
                with hist_cols[idx]:
                    render_chart(
                        fig_hist,
                        key=f"{key_prefix}_hist_period_{idx}",
                        caption_below=None,
                    )
                    if _has_plan_line:
                        st.markdown(
                            "<div style='text-align:center;color:#e8eef5;font-size:13px;line-height:1.35;"
                            "margin:0.2rem 0 0.45rem;'>"
                            '<span style="margin-right:1.85rem;">'
                            '<span style="color:#5DADE2;font-weight:700">●</span> План'
                            "</span>"
                            '<span><span style="color:#F39C12;font-weight:700">●</span> Факт</span>'
                            "</div>",
                            unsafe_allow_html=True,
                        )
                    _chart_caption_below(
                        f"Факт по периодам ({_cap_grain}), % к сумме плана периода (округление вверх): {label}"
                    )
            else:
                # Нет колонок по неделям — агрегат по месяцу (период) или по году
                if dyn_grain == "Год":
                    _t = df_hist.copy()
                    _t["_yr"] = _gdrs_period_series_to_year(_t[period_col_hist])
                    by_period = (
                        _t.groupby("_yr", as_index=False)["week_sum"]
                        .sum()
                        .rename(columns={"week_sum": "Факт"})
                    )
                    by_period = by_period[pd.notna(by_period["_yr"])].copy()
                    if by_period.empty:
                        with hist_cols[idx]:
                            st.info(f"**{label}** — нет данных для годовой шкалы.")
                        continue
                    by_period["_yr"] = by_period["_yr"].astype(int)
                    by_period["Период_стр"] = by_period["_yr"].astype(str)
                    _pl = (
                        _t.groupby("_yr")["План_numeric"]
                        .apply(lambda s: float(pd.to_numeric(s, errors="coerce").fillna(0.0).sum()))
                        .reset_index(name="_psum")
                    )
                    by_period = by_period.merge(_pl, on="_yr", how="left")
                    by_period["План_период"] = pd.to_numeric(by_period["_psum"], errors="coerce")
                    by_period.drop(columns=["_psum"], inplace=True, errors="ignore")
                    fac = pd.to_numeric(by_period["Факт"], errors="coerce").fillna(0.0)
                    psum = pd.to_numeric(by_period["План_период"], errors="coerce").fillna(0.0)
                    by_period["%"] = np.where(psum > 0, (fac / psum * 100.0).clip(lower=0.0), 0.0)
                    by_period = by_period.sort_values("_yr")
                else:
                    by_period = (
                        df_hist.groupby(period_col_hist, as_index=False)["week_sum"]
                        .sum()
                        .rename(columns={"week_sum": "Факт"})
                    )
                    by_period["Период_стр"] = by_period[period_col_hist].astype(str).str.strip()
                    by_period = _gdrs_point_pct_of_period_plan(
                        by_period, df_hist, period_col_hist, "Факт"
                    )
                    by_period = by_period.sort_values(period_col_hist)
                with hist_cols[idx]:
                    fig_hist = go.Figure()
                    is_resources_fb = "Ресурсы" in label or "Люди" in label
                    if is_resources_fb:
                        fig_hist.add_trace(
                            go.Scatter(
                                x=by_period["Период_стр"],
                                y=by_period["Факт"],
                                mode="markers+text",
                                name="Факт",
                                marker=dict(size=14, color="#2E86AB", line=dict(width=1, color="white")),
                                text=[
                                    f"{int(row['Факт'])} ({int(np.ceil(float(row['%'])))}%)"
                                    for _, row in by_period.iterrows()
                                ],
                                textposition="top center",
                                textfont=dict(size=11, color="white"),
                                cliponaxis=False,
                            )
                        )
                    else:
                        fig_hist.add_trace(
                            go.Bar(
                                x=by_period["Период_стр"],
                                y=by_period["Факт"],
                                text=[
                                    f"{int(row['Факт'])} ({int(np.ceil(float(row['%'])))}%)"
                                    for _, row in by_period.iterrows()
                                ],
                                textposition="outside",
                                textfont=dict(size=11, color="white"),
                                marker_color="#F39C12",
                                name="Факт",
                                cliponaxis=False,
                            )
                        )
                    fig_hist.update_layout(
                        title_text="",
                        xaxis_title="Период",
                        yaxis_title="Количество",
                        height=440,
                        showlegend=False,
                        margin=dict(l=56, r=28, t=56, b=168),
                        uniformtext=dict(minsize=7, mode="show"),
                        xaxis=dict(tickangle=-45, automargin=True),
                        yaxis=dict(automargin=True),
                    )
                    fig_hist = _apply_finance_bar_label_layout(fig_hist)
                    try:
                        fig_hist.update_layout(
                            uniformtext=dict(minsize=6, mode="show"),
                            margin=dict(l=56, r=36, t=88, b=180),
                        )
                    except Exception:
                        pass
                    fig_hist = apply_chart_background(fig_hist)
                    render_chart(
                        fig_hist,
                        key=f"{key_prefix}_hist_period_fallback_{idx}",
                        caption_below=f"Факт по периодам, % к сумме плана периода (округление вверх): {label}",
                    )

    show_plan_fact_row = (
        has_plan_data
        and len(projects_to_process) > 1
        and project_col
        and project_col in filtered_df.columns
    )
    plan_fact_row_done = False
    if show_plan_fact_row:
        if (data_source_filter or "").strip().lower() == "техника":
            st.subheader("План/Факт техника")
        else:
            st.subheader("План/Факт рабочие")
        pf_cols = st.columns(len(projects_to_process, gap="small"))
        for _ix, _pname in enumerate(projects_to_process):
            _pdf = filtered_df.copy()
            if project_col in _pdf.columns and _pname != "Все проекты":
                _pdf = _pdf[
                    _pdf[project_col].astype(str).str.strip() == str(_pname).strip()
                ]
            fig_pf, met_pf = _gdrs_plan_fact_fig_and_metrics(_pdf)
            with pf_cols[_ix]:
                st.markdown(f"##### {_pname}")
                if fig_pf is not None and met_pf is not None:
                    a1, a2 = st.columns([3, 2], gap="small")
                    with a1:
                        render_chart(
                            fig_pf,
                            key=f"{key_prefix}_planfact_row_{_ix}",
                            caption_below="",
                        )
                    with a2:
                        _col = "#e74c3c" if met_pf["dev"] > 0 else "#27ae60"
                        st.markdown(
                            f"**План:** {int(round(met_pf['plan']))}\n\n"
                            f"**Факт:** {int(round(met_pf['fact']))}\n\n"
                            f"**Отклонение:** <span style='color:{_col};font-size:1.15em'>●</span> "
                            f"{int(round(met_pf['dev']))}"
                            f"{_gdrs_fp_pct_caption_line(met_pf)}",
                            unsafe_allow_html=True,
                        )
                else:
                    st.markdown("*Нет данных для плана/факта по этому проекту.*")
        plan_fact_row_done = True
        st.markdown("---")

    # R23-05 стр.12: «Факт по подрядчикам» показываем всегда при наличии week_sum
    # (раньше это был elif и при наличии колонки «Период» диаграмма пропадала).
    if "week_sum" in filtered_df.columns:
        if (data_source_filter or "").strip().lower() == "техника":
            st.subheader("План/Факт техника")
        else:
            st.subheader("План/Факт рабочие")
        sources_wfb = []
        if "data_source" in filtered_df.columns:
            sources_wfb = filtered_df["data_source"].dropna().unique().tolist()
        else:
            sources_wfb = [None]
        labels_wfb = []
        for s in sources_wfb:
            if s is None:
                labels_wfb.append("Данные")
            elif str(s).strip().lower() in ("ресурсы", "ресурс"):
                labels_wfb.append("Люди (ресурсы)")
            elif str(s).strip().lower() in ("техника", "tech", "technique"):
                labels_wfb.append("Техника")
            else:
                labels_wfb.append(str(s))
        wfb_cols = st.columns(max(1, len(sources_wfb, gap="small")))
        for wfi, (src_wfb, lab_wfb) in enumerate(zip(sources_wfb, labels_wfb)):
            if src_wfb is None:
                df_wfb = filtered_df.copy()
            else:
                df_wfb = filtered_df[_gdrs_match_data_source(filtered_df["data_source"], src_wfb)].copy()
            if df_wfb.empty or "Контрагент" not in df_wfb.columns:
                with wfb_cols[wfi]:
                    st.info(f"**{lab_wfb}** — нет данных для «Факт по подрядчикам».")
                continue
            _agg_dict = {"week_sum": "sum"}
            if "План_numeric" in df_wfb.columns:
                _agg_dict["План_numeric"] = "sum"
            by_w = df_wfb.groupby("Контрагент", as_index=False).agg(_agg_dict)
            _ws_grp = pd.to_numeric(by_w["week_sum"], errors="coerce").fillna(0)
            by_w["Факт"] = _ws_grp / week_fact_den
            if "План_numeric" in by_w.columns:
                by_w["План"] = pd.to_numeric(by_w["План_numeric"], errors="coerce").fillna(0)
            else:
                by_w["План"] = 0.0
            # Округление вверх до целого (R23-05): факт/план должны быть целыми.
            import math as _math
            by_w["Факт"] = by_w["Факт"].apply(lambda v: int(_math.ceil(float(v))) if float(v) > 0 else int(v))
            by_w["План"] = by_w["План"].apply(lambda v: int(_math.ceil(float(v))) if float(v) > 0 else int(v))
            by_w["Отклонение"] = by_w["План"] - by_w["Факт"]
            by_w = by_w[(by_w["Факт"].abs() > 0) | (by_w["План"].abs() > 0)].sort_values("Факт", ascending=False)
            if by_w.empty:
                with wfb_cols[wfi]:
                    st.info(f"**{lab_wfb}** — нет ненулевых значений по подрядчикам.")
                continue
            tw = float(by_w["Факт"].sum())
            by_w["pct"] = (by_w["Факт"] / tw * 100.0).round(1) if tw else 0.0
            # Проект — для hover (если в df_wfb есть «Проект»/«project name», собираем список).
            _proj_col_wfb = None
            for _pc in ("project name", "Проект", "project_name"):
                if _pc in df_wfb.columns:
                    _proj_col_wfb = _pc
                    break
            if _proj_col_wfb:
                _proj_by_ka = (
                    df_wfb.groupby("Контрагент")[_proj_col_wfb]
                    .apply(lambda s: ", ".join(sorted({str(x) for x in s.dropna() if str(x).strip()}))[:120])
                    .to_dict()
                )
                by_w["__project"] = by_w["Контрагент"].map(_proj_by_ka).fillna("—")
            else:
                by_w["__project"] = "—"
            # R23-05 стр.12: горизонтальная «План + Факт» по подрядчикам, факт — градиент.
            by_w = by_w.sort_values("Факт", ascending=True)
            _has_any_plan = bool((by_w["План"] > 0).any())
            is_rw = "ресурс" in lab_wfb.lower() or "люди" in lab_wfb.lower()
            _plan_color = "#5dade2" if is_rw else "#af7ac5"
            # Нейтральный цвет (когда нет плана) — синий, чтобы не путать с салатовым «план выполнен».
            _fact_neutral = "#3498db"
            if _has_any_plan:
                _fact_colors = [
                    _gdrs_fact_bar_color(float(r["План"]), float(r["Факт"]))
                    for _, r in by_w.iterrows()
                ]
            else:
                _fact_colors = _fact_neutral
            _customdata_wfb = list(zip(
                by_w["__project"].astype(str).tolist(),
                by_w["План"].astype(int).tolist(),
                by_w["Факт"].astype(int).tolist(),
                by_w["Отклонение"].astype(int).tolist(),
            ))
            _h_wfb = max(420, int(34 * max(6, len(by_w))))
            fig_wfb = go.Figure()
            if _has_any_plan:
                fig_wfb.add_trace(
                    go.Bar(
                        y=by_w["Контрагент"].astype(str),
                        x=by_w["План"],
                        name="План (договор)",
                        orientation="h",
                        marker=dict(color=_plan_color, line=dict(width=1, color="#aed6f1")),
                        text=[f"{int(p)}" for p in by_w["План"]],
                        textposition="outside",
                        textfont=dict(size=10, color="white"),
                        customdata=_customdata_wfb,
                        hovertemplate=(
                            "<b>%{y}</b><br>Проект: %{customdata[0]}"
                            "<br>План: %{customdata[1]}"
                            "<br>Факт: %{customdata[2]}"
                            "<br>Отклонение: %{customdata[3]}"
                            "<extra></extra>"
                        ),
                    )
                )
            fig_wfb.add_trace(
                go.Bar(
                    y=by_w["Контрагент"].astype(str),
                    x=by_w["Факт"],
                    name="Факт",
                    orientation="h",
                    marker=dict(color=_fact_colors, line=dict(width=1, color="white")),
                    text=[f"{int(r['Факт'])} ({r['pct']}%)" for _, r in by_w.iterrows()],
                    textposition="outside",
                    textfont=dict(size=11, color="white"),
                    customdata=_customdata_wfb,
                    hovertemplate=(
                        "<b>%{y}</b><br>Проект: %{customdata[0]}"
                        "<br>План: %{customdata[1]}"
                        "<br>Факт: %{customdata[2]}"
                        "<br>Отклонение: %{customdata[3]}"
                        "<extra></extra>"
                    ),
                )
            )
            fig_wfb.update_layout(
                title_text="",
                xaxis_title="Количество",
                yaxis_title="Контрагент",
                barmode="group" if _has_any_plan else "relative",
                height=_h_wfb,
                showlegend=False,
                xaxis=dict(automargin=True),
                yaxis=dict(automargin=True),
                margin=dict(l=120, r=36, t=72, b=56),
                uniformtext=dict(minsize=6, mode="show"),
            )
            fig_wfb = apply_chart_background(fig_wfb)
            with wfb_cols[wfi]:
                if not _has_any_plan:
                    suppress_caption(
                        f"**{lab_wfb}** — план по подрядчикам не заполнен в исходных данных. "
                        "Столбцы нейтрального цвета (план/факт не сравнивается)."
                    )
                render_chart(
                    fig_wfb,
                    key=f"{key_prefix}_hist_noperiod_{wfi}",
                    caption_below=None,
                )
                if _has_any_plan:
                    st.markdown(
                        "<div style='text-align:center;color:#e8eef5;font-size:12px;line-height:1.35;"
                        "margin:0.15rem 0 0.35rem;'>"
                        '<span style="margin-right:1.75rem;">'
                        '<span style="color:#5dade2;font-weight:700">●</span> План (договор)'
                        "</span>"
                        '<span><span style="color:#3498db;font-weight:700">●</span> Факт</span>'
                        "</div>",
                        unsafe_allow_html=True,
                    )
                _chart_caption_below(f"План и факт по подрядчикам: {lab_wfb}")

    show_contractor_fact_row = (
        len(projects_to_process) > 1
        and project_col
        and project_col in filtered_df.columns
        and "Контрагент" in filtered_df.columns
        and "week_sum" in filtered_df.columns
    )
    contractor_fact_row_done = False
    if show_contractor_fact_row:
        if (data_source_filter or "").strip().lower() == "техника":
            st.subheader("Доля факта по подрядчикам (техника)")
        else:
            st.subheader("Доля факта по подрядчикам (рабочие)")
        for _ix, _pname in enumerate(projects_to_process):
            _pdf = filtered_df.copy()
            if project_col in _pdf.columns and _pname != "Все проекты":
                _pdf = _pdf[
                    _pdf[project_col].astype(str).str.strip() == str(_pname).strip()
                ]
            fig_cf, met_cf = _gdrs_contractor_fact_fig_and_metrics(_pdf)
            st.markdown(f"#### {_pname}")
            if fig_cf is not None and met_cf is not None:
                render_chart(
                    fig_cf,
                    key=f"{key_prefix}_contractor_fact_row_{_ix}",
                    height=460,
                    max_height=620,
                    caption_below="",
                )
                _cfc = "#e74c3c" if met_cf["dev"] > 0 else "#27ae60"
                _pl = float(met_cf.get("plan") or 0)
                _pl_disp = "—" if _pl == 0.0 else str(int(round(_pl)))
                st.markdown(
                    f"**План:** {_pl_disp}  **Факт:** {int(round(met_cf['fact']))}  "
                    f"**Отклонение:** <span style='color:{_cfc};font-size:1.1em'>●</span> "
                    f"{int(round(met_cf['dev']))}  "
                    + _gdrs_fp_pct_caption_line(met_cf),
                    unsafe_allow_html=True,
                )
            else:
                st.markdown("*Нет данных по факту подрядчиков по этому проекту.*")
            if _ix < len(projects_to_process) - 1:
                st.markdown("---")
        contractor_fact_row_done = True
        st.markdown("---")

    for project_name in projects_to_process:
        project_filtered_df = filtered_df.copy()
        if (
            project_col
            and project_col in project_filtered_df.columns
            and project_name != "Все проекты"
        ):
            project_filtered_df = project_filtered_df[
                project_filtered_df[project_col].astype(str).str.strip()
                == str(project_name).strip()
            ]

        if project_filtered_df.empty:
            continue

        if len(projects_to_process) > 1:
            st.markdown("---")
            st.subheader(f"Проект: {project_name}")

        _pslug = str(project_name).replace(" ", "_")[:20]

        if not has_plan_data and "Контрагент" in project_filtered_df.columns and "week_sum" in project_filtered_df.columns:
            _bar_avg = (
                project_filtered_df.groupby("Контрагент", as_index=False)["week_sum"]
                .sum()
                .rename(columns={"week_sum": "Среднее за месяц"})
            )
            _bar_avg["Среднее за месяц"] = _bar_avg["Среднее за месяц"].round(1)
            _bar_avg = _bar_avg[_bar_avg["Среднее за месяц"] > 0].sort_values("Среднее за месяц", ascending=False)
            if not _bar_avg.empty:
                fig_avg = px.bar(
                    _bar_avg, x="Контрагент", y="Среднее за месяц",
                    text=_bar_avg["Среднее за месяц"].apply(lambda v: f"{v:.0f}"),
                    color_discrete_sequence=["#2ecc71"],
                )
                fig_avg.update_traces(
                    textposition="outside",
                    textfont=dict(size=12, color="white"),
                    cliponaxis=False,
                )
                fig_avg.update_layout(
                    height=520,
                    xaxis=dict(tickangle=-45, automargin=True),
                    yaxis=dict(title="Среднее за месяц", automargin=True),
                )
                fig_avg = _apply_finance_bar_label_layout(fig_avg)
                try:
                    fig_avg.update_layout(
                        uniformtext=dict(minsize=6, mode="show"),
                        margin=dict(l=56, r=36, t=88, b=168),
                    )
                except Exception:
                    pass
                fig_avg = apply_chart_background(fig_avg)
                render_chart(fig_avg, key=f"{key_prefix}_avg_bar_{_pslug}", caption_below=f"Среднее количество ресурсов — {project_name}")

                total_avg = _bar_avg["Среднее за месяц"].sum()
                if total_avg > 0:
                    fig_pie_avg = px.pie(
                        _bar_avg, values="Среднее за месяц", names="Контрагент",
                        title=None, color_discrete_sequence=px.colors.qualitative.Set3,
                    )
                    fig_pie_avg = apply_standard_pie_layout(
                        fig_pie_avg,
                        height=500,
                        pct_fontsize=18,
                    )
                    fig_pie_avg.update_traces(
                        hovertemplate="<b>%{label}</b><br>Среднее: %{value:,.1f}<br>%{percent:.0%}<extra></extra>",
                    )
                    fig_pie_avg = apply_chart_background(fig_pie_avg)
                    render_chart(fig_pie_avg, key=f"{key_prefix}_avg_pie_{_pslug}", caption_below=f"Распределение ресурсов — {project_name}")
            else:
                st.info("Нет данных для отображения.")

        if not plan_fact_row_done:
            df_people = project_filtered_df.copy()
            if "data_source" in df_people.columns:
                df_people = df_people[
                    df_people["data_source"].astype(str).str.strip().str.lower() == "ресурсы"
                ].copy()
            if not df_people.empty and "План_numeric" in df_people.columns and "week_sum" in df_people.columns:
                fig_pf, met_pf = _gdrs_plan_fact_fig_and_metrics(df_people)
                if fig_pf is not None and met_pf is not None:
                    st.subheader("План/Факт рабочие")
                    render_chart(fig_pf, key=f"{key_prefix}_planfact_single_{_pslug}", caption_below="")

        # ========== Chart 1: круговая — доля факта по подрядчикам ==========
        if not contractor_fact_row_done:
            if (data_source_filter or "").strip().lower() == "техника":
                st.subheader("Доля факта по подрядчикам (техника)")
            else:
                st.subheader("Доля факта по подрядчикам (рабочие)")
            fig_cf, met_cf = _gdrs_contractor_fact_fig_and_metrics(project_filtered_df)
            if fig_cf is not None and met_cf is not None:
                cf_c1, cf_c2 = st.columns([3, 2], gap="small")
                with cf_c1:
                    render_chart(
                        fig_cf,
                        key=f"{key_prefix}_contractor_fact_{_pslug}",
                        caption_below=f"Доля факта по подрядчикам — {project_name}",
                    )
                with cf_c2:
                    _cfc = "#e74c3c" if met_cf["dev"] > 0 else "#27ae60"
                    _pl = float(met_cf.get("plan") or 0)
                    _pl_disp = "—" if _pl == 0.0 else str(int(round(_pl)))
                    st.markdown(
                        f"**План:** {_pl_disp}\n\n"
                        f"**Факт:** {int(round(met_cf['fact']))}\n\n"
                        f"**Отклонение:** <span style='color:{_cfc};font-size:1.15em'>●</span> "
                        f"{int(round(met_cf['dev']))}",
                        unsafe_allow_html=True,
                    )
            else:
                st.info("Нет данных для отображения круговой диаграммы по подрядчикам.")
        # ========== Таблица по подрядчикам: план, факт, отклонение ==========
        if "data_source" in project_filtered_df.columns and "Контрагент" in project_filtered_df.columns and "week_sum" in project_filtered_df.columns:
            for _type, type_label, type_key in [
                ("ресурсы", "Люди", "people"),
                ("техника", "Техника", "technique"),
            ]:
                df_type = project_filtered_df[
                    project_filtered_df["data_source"].astype(str).str.strip().str.lower() == _type
                ]
                if df_type.empty:
                    continue
                _agg = {"week_sum": "sum"}
                if "План_numeric" in df_type.columns:
                    _agg["План_numeric"] = "sum"
                by_contractor = df_type.groupby("Контрагент", as_index=False).agg(_agg)
                by_contractor = by_contractor.rename(
                    columns={"week_sum": "Факт", "План_numeric": "План"}
                )
                if "План" not in by_contractor.columns:
                    by_contractor["План"] = 0.0
                by_contractor["Факт"] = pd.to_numeric(
                    by_contractor["Факт"], errors="coerce"
                ).fillna(0.0)
                by_contractor["План"] = pd.to_numeric(
                    by_contractor["План"], errors="coerce"
                ).fillna(0.0)
                by_contractor["Отклонение"] = by_contractor["План"] - by_contractor["Факт"]
                by_contractor["%"] = by_contractor.apply(
                    lambda r: (
                        round(float(r["Факт"]) / float(r["План"]) * 100.0, 1)
                        if float(r["План"]) != 0.0
                        else None
                    ),
                    axis=1,
                )
                by_contractor = by_contractor[
                    (by_contractor["Факт"] != 0) | (by_contractor["План"] != 0)
                ].copy()
                if by_contractor.empty:
                    continue
                by_contractor = by_contractor.sort_values("План", ascending=False)
                with st.expander(f"Формулы столбцов ({type_label})", expanded=False):
                    suppress_caption(
                        "План (из договора), Факт (СКУД / выгрузка ресурсов), «%» = факт/план×100%, отклонение = план − факт."
                    )
                _display_cols_w = ["Контрагент", "План", "Факт", "%", "Отклонение"]
                display_df = by_contractor[_display_cols_w].copy()
                display_df["План"] = display_df["План"].apply(
                    lambda x: int(round(x, 0)) if pd.notna(x) else 0
                )
                display_df["Факт"] = display_df["Факт"].apply(
                    lambda x: int(round(x, 0)) if pd.notna(x) else 0
                )
                render_table_subheader(
                    st,
                    report_title_name("ГДРС", f"доля факта ({type_label}) по контрагентам"),
                )
                display_df["%"] = display_df["%"].apply(
                    lambda v: f"{v:.1f}%" if v is not None and pd.notna(v) else "—"
                )
                display_df["Отклонение"] = display_df["Отклонение"].apply(
                    lambda x: int(round(x, 0)) if pd.notna(x) else 0
                )
                _render_budget_table_html(
                        display_df,
                        finance_deviation_column="Отклонение",
                        deviation_red_if_positive_only=True,
                        
                    )

        # ========== Chart 2: Bar Chart by Contractor (Plan, Fact, Отклонение) ==========
        st.subheader(
            "Столбчатая диаграмма: План, Факт, Отклонение (группировка по контрагенту)"
        )

        bar_df = project_filtered_df.copy()
        if period_col and period_col in bar_df.columns and selected_periods:
            bar_df = bar_df[
                bar_df[period_col].astype(str).str.strip().isin([str(p).strip() for p in selected_periods])
            ]
        if "Дельта_numeric" not in bar_df.columns and "План_numeric" in bar_df.columns and "week_sum" in bar_df.columns:
            bar_df = bar_df.copy()
            bar_df["Дельта_numeric"] = bar_df["План_numeric"] - (
                pd.to_numeric(bar_df["week_sum"], errors="coerce").fillna(0.0) / week_fact_den
            )
        elif "Дельта_numeric" not in bar_df.columns:
            bar_df = bar_df.copy()
            bar_df["Дельта_numeric"] = 0
        contractor_data = (
            bar_df.groupby("Контрагент")
            .agg(
                {
                    "План_numeric": "sum",  # Sum of plans
                    "week_sum": "sum",  # Sum of weeks (факт)
                    "Дельта_numeric": "sum",  # Sum of deltas
                }
            )
            .reset_index()
        )

        contractor_data.columns = ["Контрагент", "План", "Факт", "Отклонение"]
        contractor_data["Факт"] = (
            pd.to_numeric(contractor_data["Факт"], errors="coerce").fillna(0.0) / week_fact_den
        )

        contractor_data["Отклонение"] = (
            pd.to_numeric(contractor_data["План"], errors="coerce").fillna(0.0)
            - pd.to_numeric(contractor_data["Факт"], errors="coerce").fillna(0.0)
        )

        _sort_bar_label_w = st.radio(
            "Сортировка контрагентов по",
            options=("План", "Факт", "Отклонение"),
            index=0,
            horizontal=True,
            key=f"{key_prefix}_bar_sort_work_{_pslug}",
        )
        _sort_col_map_w = {"План": "План", "Факт": "Факт", "Отклонение": "Отклонение"}
        contractor_data = contractor_data.sort_values(
            _sort_col_map_w[_sort_bar_label_w], ascending=False
        ).reset_index(drop=True)

        contractor_data["%"] = np.where(
            contractor_data["План"] > 0,
            (contractor_data["Факт"] / contractor_data["План"] * 100.0).round(1),
            np.nan,
        )

        delta_values = contractor_data["Отклонение"].fillna(0)
        delta_abs = delta_values.abs()

        # Подписи как в макете: значение и (%) — план 100%, факт и дельта от плана; дельта на графике по модулю.
        plan_text: list[str] = []
        fact_text: list[str] = []
        delta_text: list[str] = []
        for i in range(len(contractor_data)):
            pv = float(
                pd.to_numeric(contractor_data["План"].iloc[i], errors="coerce") or 0.0
            )
            fv = float(
                pd.to_numeric(contractor_data["Факт"].iloc[i], errors="coerce") or 0.0
            )
            dv = float(pd.to_numeric(delta_values.iloc[i], errors="coerce") or 0.0)
            av = abs(dv)
            if pv > 1e-9:
                plan_text.append(f"{int(round(pv))} (100%)")
                fact_text.append(f"{int(round(fv))} ({fv/pv*100:.0f}%)")
                if av < 0.5:
                    delta_text.append("0")
                else:
                    delta_text.append(f"{int(round(av))} ({dv/pv*100:+.0f}%)")
            else:
                plan_text.append("0")
                fact_text.append(f"{int(round(fv))}" if abs(fv) >= 0.5 else "0")
                delta_text.append(f"{int(round(av))}" if av >= 0.5 else "0")

        _pv_arr = pd.to_numeric(contractor_data["План"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
        _fv_arr = pd.to_numeric(contractor_data["Факт"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
        _fact_bar_colors_pf = [_gdrs_fact_bar_color(float(a), float(b)) for a, b in zip(_pv_arr, _fv_arr)]
        _hover_fact_pf = np.stack([_pv_arr, _fv_arr, _pv_arr - _fv_arr], axis=-1)

        fig_bar = go.Figure()
        fig_bar.add_trace(
            go.Bar(
                name="План",
                x=contractor_data["Контрагент"],
                y=contractor_data["План"],
                marker_color="#3498db",
                text=plan_text,
                textposition="outside",
                textfont=dict(size=12, color="white"),
                customdata=_hover_fact_pf,
                hovertemplate=(
                    "<b>%{x}</b><br>"
                    "План: %{y:.0f}<br>"
                    "Факт: %{customdata[1]:.0f}<br>"
                    "Отклонение (план−факт): %{customdata[2]:.0f}<extra></extra>"
                ),
            )
        )
        fig_bar.add_trace(
            go.Bar(
                name="Факт",
                x=contractor_data["Контрагент"],
                y=contractor_data["Факт"],
                marker=dict(color=_fact_bar_colors_pf, line=dict(width=1, color="#eaf2fb")),
                text=fact_text,
                textposition="outside",
                textfont=dict(size=12, color="white"),
                customdata=_hover_fact_pf,
                hovertemplate=(
                    "<b>%{x}</b><br>"
                    "План: %{customdata[0]:.0f}<br>"
                    "Факт: %{y:.0f}<br>"
                    "Отклонение (план−факт): %{customdata[2]:.0f}<extra></extra>"
                ),
            )
        )

        # Эталон: отклонение всегда по модулю выше оси X; оранжевый если > 0, зелёный если ≤ 0.
        pos_mask = delta_values > 0
        nonpos_mask = delta_values <= 0
        if pos_mask.any():
            fig_bar.add_trace(
                go.Bar(
                    name="Отклонение > 0",
                    x=contractor_data.loc[pos_mask, "Контрагент"],
                    y=delta_abs[pos_mask],
                    marker_color="#e67e22",
                    text=[delta_text[i] for i in range(len(delta_text)) if pos_mask.iloc[i]],
                    textposition="outside",
                    textfont=dict(size=12, color="white"),
                    showlegend=True,
                )
            )
        if nonpos_mask.any():
            fig_bar.add_trace(
                go.Bar(
                    name="Отклонение ≤ 0",
                    x=contractor_data.loc[nonpos_mask, "Контрагент"],
                    y=delta_abs[nonpos_mask],
                    marker_color="#2ecc71",
                    text=[delta_text[i] for i in range(len(delta_text)) if nonpos_mask.iloc[i]],
                    textposition="outside",
                    textfont=dict(size=12, color="white"),
                    showlegend=True,
                )
            )

        period_caption = f" Период: {', '.join(str(p) for p in selected_periods[:5])}{'…' if len(selected_periods) > 5 else ''}" if (period_col and selected_periods) else ""
        fig_bar.update_layout(
            title_text="",
            xaxis_title="Контрагент",
            yaxis_title="Факт (сумма), план и отклонение",
            barmode="group",
            width=_RENDER_CHART_DEFAULT_WIDTH_PX,
            bargap=0.22,
            bargroupgap=0.09,
            height=620,
            legend=standard_chart_legend(),
            xaxis=dict(tickangle=-45, automargin=True),
            yaxis=dict(automargin=True, rangemode="tozero"),
        )

        fig_bar = _apply_finance_bar_label_layout(fig_bar, y_rangemode="tozero")
        try:
            fig_bar.update_layout(
                uniformtext=dict(minsize=6, mode="show"),
                margin=dict(l=56, r=150, t=100, b=200),
            )
            fig_bar.update_yaxes(rangemode="tozero")
            fig_bar.update_traces(cliponaxis=False, selector=dict(type="bar"))
        except Exception:
            pass
        fig_bar = apply_chart_background(fig_bar)
        render_chart(
            fig_bar,
            caption_below=(
                "План, Факт и Отклонение по контрагентам"
                + period_caption
                + ". Макет: высота отклонения — модуль; оранжевый при Отклонение > 0, зелёный при ≤ 0. Сортировка — виджет выше."
            ),
        )

        # Макет: круговые по подрядчикам — выше; отдельный блок «СКУД по неделям» здесь не показываем.

        # Group by Контрагент and aggregate for pie chart (Plan + Average)
        contractor_plan_avg = (
            project_filtered_df.groupby("Контрагент")
            .agg(
                {
                    "План_numeric": "sum",  # Sum of plans
                    "week_sum": "sum",  # Sum of weeks = среднее за месяц
                    "Дельта_numeric": "sum",  # Sum of deltas
                }
            )
            .reset_index()
        )

        contractor_plan_avg.columns = ["Контрагент", "План", "Среднее за месяц", "Отклонение"]

        # Calculate sum of Plan + Average for each contractor
        contractor_plan_avg["Сумма"] = (
            contractor_plan_avg["План"] + contractor_plan_avg["Среднее за месяц"]
        )

        # Calculate доля факта (Среднее за месяц / Сумма * 100) and доля отклонения (Отклонение / План * 100)
        contractor_plan_avg["Доля факта (%)"] = 0.0
        contractor_plan_avg["Доля отклонения (%)"] = 0.0
        mask_sum = contractor_plan_avg["Сумма"] != 0
        contractor_plan_avg.loc[mask_sum, "Доля факта (%)"] = (
            contractor_plan_avg.loc[mask_sum, "Среднее за месяц"]
            / contractor_plan_avg.loc[mask_sum, "Сумма"]
        ) * 100
        mask_plan = contractor_plan_avg["План"] != 0
        contractor_plan_avg.loc[mask_plan, "Доля отклонения (%)"] = (
            contractor_plan_avg.loc[mask_plan, "Отклонение"]
            / contractor_plan_avg.loc[mask_plan, "План"]
        ) * 100

        # Remove zero values for pie chart
        contractor_plan_avg = contractor_plan_avg[contractor_plan_avg["Сумма"] != 0].copy()

        if contractor_plan_avg.empty:
            st.info("Нет данных для отображения.")
        else:
            contractor_plan_avg.sort_values("Сумма", ascending=False, inplace=True)
            # Круговая «план + среднее по контрагентам» скрыта по макету — используйте сводную таблицу ниже.

            # ========== Summary Table ==========
            render_table_subheader(st, report_title_name("ГДРС", "по контрагентам"))

            # Format numbers for display
            summary_table = contractor_data.copy()
            _pct_fmt = summary_table["%"]
            summary_table["План"] = summary_table["План"].apply(
                lambda x: f"{int(x)}" if pd.notna(x) else "0"
            )
            summary_table["Факт"] = summary_table["Факт"].apply(
                lambda x: f"{int(x)}" if pd.notna(x) else "0"
            )
            summary_table["%"] = _pct_fmt.apply(
                lambda x: f"{float(x):.1f}%" if pd.notna(x) else "—"
            )
            summary_table["Отклонение"] = summary_table["Отклонение"].apply(
                lambda x: f"{int(x)}" if pd.notna(x) else "0"
            )
            summary_table = summary_table[
                ["Контрагент", "План", "Факт", "%", "Отклонение"]
            ]

            _render_budget_table_html(
                    summary_table,
                    finance_deviation_column="Отклонение",
                    deviation_red_if_positive_only=True,
                    
                )

            # Summary metrics
            col1, col2, col3 = st.columns(3, gap="small")

            with col1:
                total_plan = contractor_data["План"].sum()
                st.metric("Общий план", f"{int(total_plan)}")

            with col2:
                total_fact = contractor_data["Факт"].sum()
                st.metric("Общий факт", f"{int(total_fact)}")

            with col3:
                total_delta = contractor_data["Отклонение"].sum()
                st.metric("Общее отклонение", f"{int(total_delta)}")


