_gdrs_fragment = getattr(st, "fragment", None)


def _gdrs_dyn_nice_dtick(y_lo: float, y_hi: float, *, target_ticks: int = 5) -> float:
    """Шаг делений оси Y по масштабу данных (меньший шаг — заметнее динамика)."""
    import math

    span = max(float(y_hi) - float(y_lo), 1.0)
    raw = span / max(1, int(target_ticks))
    if raw <= 0:
        return 1.0
    mag = 10 ** math.floor(math.log10(raw))
    for mult in (1, 2, 2.5, 5, 10):
        step = mult * mag
        if span / step <= target_ticks + 1:
            return float(step)
    return float(raw)


def _gdrs_dyn_y_range(series, *, pad_ratio: float = 0.14, min_pad: float = 8.0) -> list[float]:
    vals = pd.to_numeric(series, errors="coerce").fillna(0.0)
    if vals.empty:
        return [0.0, 1.0]
    y_lo = float(vals.min())
    y_hi = float(vals.max())
    y_span = max(y_hi - y_lo, 1.0)
    y_pad = max(y_span * pad_ratio, min_pad)
    return [max(0.0, y_lo - y_pad), y_hi + y_pad]


def _gdrs_dyn_panel_dtick(
    y_lo: float,
    y_hi: float,
    agg_kind: str,
    *,
    series_kind: str = "fact",
) -> float:
    """Оптимальный шаг сетки Y для «День» / «Неделя» / «Месяц» / «Год» и ряда план/факт."""
    span = max(float(y_hi) - float(y_lo), 1.0)
    _agg = str(agg_kind or "").casefold()
    _sk = "plan" if str(series_kind).casefold().startswith("plan") else "fact"
    _presets = {
        "день": {"plan": (10, 0.08), "fact": (12, 0.10)},
        "неделя": {"plan": (12, 0.06), "fact": (14, 0.08)},
        "месяц": {"plan": (14, 0.05), "fact": (14, 0.06)},
        "год": {"plan": (10, 0.07), "fact": (12, 0.08)},
    }
    _target, _max_frac = _presets.get(_agg, _presets["день"])[_sk]
    _step = _gdrs_dyn_nice_dtick(y_lo, y_hi, target_ticks=_target)
    _cap = max(span * _max_frac, 1.0)
    if span <= 25:
        _cap = min(_cap, max(1.0, span / 5.0))
    elif span <= 60:
        _cap = min(_cap, max(2.0, span / 7.0))
    elif span <= 150:
        _cap = min(_cap, max(3.0, span / 9.0))
    return float(min(_step, _cap))


def _gdrs_dyn_point_label_indices(
    n_pts: int,
    agg_cf: str,
    *,
    sparse: bool = True,
) -> set[int]:
    """Индексы точек с подписями. sparse=False — все точки (широкий график со скроллом)."""
    if n_pts <= 0:
        return set()
    if not sparse:
        return set(range(n_pts))
    cf = str(agg_cf or "").casefold()
    if cf == "день":
        if n_pts > 24:
            step = 5
        elif n_pts > 16:
            step = 4
        elif n_pts > 10:
            step = 3
        elif n_pts > 6:
            step = 2
        else:
            step = 1
    elif cf == "неделя" and n_pts > 8:
        step = 2
    else:
        step = 1
    show = {i for i in range(0, n_pts, step)}
    show.add(n_pts - 1)
    return show


def _gdrs_dyn_plan_label_indices(n_pts: int, values) -> set[int]:
    """Подписи плана — только при смене значения (+ первая/последняя точка)."""
    show: set[int] = set()
    if n_pts <= 0:
        return show
    prev = None
    for i, v in enumerate(values):
        if v is None or (isinstance(v, float) and np.isnan(v)) or float(v) <= 0:
            continue
        iv = int(round(float(v)))
        if prev is None or iv != prev:
            show.add(i)
        prev = iv
    show.add(0)
    show.add(n_pts - 1)
    return show


def _gdrs_dyn_panel_y_range(series, agg_kind: str) -> list[float]:
    """Узкий диапазон Y вокруг min/max — чтобы была видна динамика, не «пол» 0…max."""
    _agg = str(agg_kind or "").casefold()
    if _agg in ("неделя", "месяц", "год"):
        return _gdrs_dyn_y_range(series, pad_ratio=0.05, min_pad=2.0)
    return _gdrs_dyn_y_range(series, pad_ratio=0.08, min_pad=4.0)


def _gdrs_dynamics_chart_panel(
    fact_dyn,
    dyn_from_iso: str,
    dyn_to_iso: str,
    version_id: int,
    db_mtime: float,
    plan_col: str,
    sel_vid: str,
    dyn_title: str,
    vid_locked: str | None,
    month_periods: list | None = None,
    term_index=None,
    *,
    plan_agg: str = "month_avg",
    skud_agg: str = "month_avg",
    theme: str = "dark",
    pairs_override=None,
):
    """Линейный график динамики — fragment: смена группировки без полной перезагрузки страницы.

    pairs_override: если факт по выбранным фильтрам пуст (у подрядчика есть план, но нет
    факта СКУД), пары «проект×подрядчик» для линии плана берём отсюда (из главной таблицы),
    иначе линию плана не на чем построить.
    """
    import plotly.graph_objects as _go
    from dashboards.gdrs_resursi import (
        gdrs_dynamics_build_series,
        gdrs_agg_week_num,
        GDRS_AGG_LABELS,
    )
    from dashboards.gdrs_theme import (
        apply_gdrs_chart_background,
        get_gdrs_theme,
        gdrs_render_subheader,
        gdrs_apply_grouped_bar_labels,
        gdrs_apply_bar_outside_labels,
        gdrs_sanitize_bar_text_labels,
        inject_gdrs_light_preview_css,
    )

    _th = get_gdrs_theme(theme)

    dyn_from = pd.Timestamp(dyn_from_iso)
    dyn_to = pd.Timestamp(dyn_to_iso)
    if theme == "light":
        inject_gdrs_light_preview_css(st)
    gdrs_render_subheader(st, dyn_title, theme=theme)
    _agg_options = ["День", "Неделя", "Месяц"]
    _agg_key = f"gdrs_dyn_kind_{vid_locked or 'any'}_{theme}"
    if st.session_state.get(_agg_key) not in _agg_options:
        st.session_state[_agg_key] = "День"
    agg_kind = st.radio(
        "Группировка", _agg_options, horizontal=True,
        key=_agg_key,
    )
    _plan_wn = gdrs_agg_week_num(plan_agg)
    _skud_wn = gdrs_agg_week_num(skud_agg)
    _wk_note = ""
    if _plan_wn is not None or _skud_wn is not None:
        _parts = []
        if _plan_wn is not None:
            _parts.append(f"план — **{GDRS_AGG_LABELS.get(f'week:{_plan_wn}', f'{_plan_wn} неделя')}**")
        if _skud_wn is not None:
            _parts.append(f"факт — **{GDRS_AGG_LABELS.get(f'week:{_skud_wn}', f'{_skud_wn} неделя')}**")
        _wk_note = " Фильтры «План»/«СКУД»: " + ", ".join(_parts) + "."
    st.caption(
        f"По всем загруженным датам: **{dyn_from.strftime('%d.%m.%Y')} — "
        f"{dyn_to.strftime('%d.%m.%Y')}** "
        f"(по выбранным месяцам в фильтре «Месяц»). "
        f"План и факт — **среднее за день** в выбранном периоде группировки.{_wk_note}"
    )
    if (
        (fact_dyn is None or getattr(fact_dyn, "empty", True))
        and pairs_override is not None
        and not getattr(pairs_override, "empty", True)
    ):
        uniq_pairs = pairs_override[
            ["project_id", "project_name", "contractor_id", "contractor_name"]
        ].drop_duplicates()
        st.caption(
            "У выбранного подрядчика есть план из 1С, но нет факта СКУД за период — "
            "показана только линия плана (факт = 0)."
        )
    else:
        uniq_pairs = fact_dyn[
            ["project_id", "project_name", "contractor_id", "contractor_name"]
        ].drop_duplicates()
    with st.spinner("Строим график динамики…"):
        dyn = gdrs_dynamics_build_series(
            fact_dyn, dyn_from, dyn_to, agg_kind,
            [], [], uniq_pairs, plan_col,
            plan_aggregate_loader=_gdrs_plan_loader(version_id, db_mtime),
            month_periods=month_periods,
            term_index=term_index,
            plan_agg=plan_agg,
            skud_agg=skud_agg,
        )
    if len(dyn) < 2:
        st.warning(
            "Для выбранной группировки доступен только один период. "
            "Выберите другую гранулярность или загрузите CSV за несколько месяцев."
        )
    try:
        _agg_cf = str(agg_kind or "").casefold()
        _use_cat_x = _agg_cf in ("неделя", "месяц")
        _x = dyn["x_label"] if _use_cat_x and "x_label" in dyn.columns else dyn["bucket"]
        _plan_s = pd.to_numeric(dyn["План"], errors="coerce").fillna(0.0)
        _fact_s = pd.to_numeric(dyn["Факт"], errors="coerce").fillna(0.0)
        _zero_plan_mask = _plan_s <= 0
        _zero_plan_n = int(_zero_plan_mask.sum())
        if _zero_plan_n > 0:
            _zdates = dyn.loc[_zero_plan_mask, "Период"].astype(str).tolist()
            _preview = ", ".join(_zdates[:5])
            _more = f" и ещё {_zero_plan_n - 5}" if _zero_plan_n > 5 else ""
            _fact_at_zero = int((_zero_plan_mask & (_fact_s > 0)).sum())
            _hint = (
                f" При этом в {_fact_at_zero} период(ах) факт > 0 — вероятна проблема с 1С "
                "(Dogovor / spravochniki на дату snapshot)."
                if _fact_at_zero > 0
                else " Проверьте загрузку Dogovor / spravochniki на даты snapshot."
            )
            st.warning(
                f"В {_zero_plan_n} период(ах) план из 1С равен 0 или отсутствует"
                f" ({_preview}{_more}).{_hint} "
                "На графике такие точки не соединяются линией плана."
            )

        _plan_plot = _plan_s.astype(float).copy()
        _plan_plot.loc[_zero_plan_mask] = np.nan

        _pct_hover = [
            f"{int(round(float(f) / float(p) * 100))}% от плана"
            if float(p) > 0
            else "—"
            for f, p in zip(_fact_s, _plan_s)
        ]
        _n_pts = len(dyn)
        _dyn_fs = (1.0 if _agg_cf == "неделя" else 1.5) * 1.5
        _dyn_sz = lambda base: max(8, int(round(float(base) * _dyn_fs)))
        _lbl_sz = _dyn_sz(10 if _n_pts <= 12 else (9 if _n_pts <= 20 else 8))
        _ann_sz = _dyn_sz(9 if _n_pts <= 12 else 8)
        _axis_tick_sz = _dyn_sz(10)
        _axis_title_sz = _dyn_sz(11)
        _hover_x = "%{x}" if _use_cat_x else "%{x|%d.%m.%Y}"

        _plan_for_range = _plan_plot.dropna()
        if _plan_for_range.empty:
            _plan_for_range = _plan_s
        _both = pd.concat([_plan_for_range, _fact_s], ignore_index=True)
        _comb_range = _gdrs_dyn_panel_y_range(_both, agg_kind)
        _comb_dtick = _gdrs_dyn_panel_dtick(
            _comb_range[0], _comb_range[1], agg_kind, series_kind="fact"
        )

        _dyn_hscroll = _agg_cf == "день" and _n_pts > 10
        _plan_label_idx = _gdrs_dyn_plan_label_indices(_n_pts, _plan_plot.tolist())
        _fact_label_idx = _gdrs_dyn_point_label_indices(
            _n_pts, _agg_cf, sparse=not _dyn_hscroll
        )

        fig = _go.Figure()
        fig.add_trace(
            _go.Scatter(
                x=_x,
                y=_plan_plot,
                mode="lines+markers+text",
                line=dict(color=_th.line_plan, width=2.5),
                marker=dict(size=8),
                name="План",
                connectgaps=False,
                text=[
                    f"{int(v)}"
                    if pd.notna(v) and float(v) > 0 and i in _plan_label_idx
                    else ""
                    for i, v in enumerate(_plan_plot)
                ],
                textposition="top center",
                textfont=dict(color=_th.line_plan, size=_lbl_sz),
                cliponaxis=False,
                hovertemplate=f"План: %{{y}}<br>{_hover_x}<extra></extra>",
            )
        )
        fig.add_trace(
            _go.Scatter(
                x=_x,
                y=dyn["Факт"],
                mode="lines+markers+text",
                line=dict(color=_th.line_fact, width=3),
                marker=dict(size=9),
                name="Факт",
                text=["" for _ in dyn["Факт"]],
                textposition="bottom center",
                textfont=dict(color=_th.line_fact, size=_lbl_sz),
                cliponaxis=False,
                customdata=_pct_hover,
                hovertemplate=f"Факт: %{{y}}<br>%{{customdata}}<br>{_hover_x}<extra></extra>",
            )
        )
        if _n_pts <= 14 or _agg_cf != "неделя":
            for i, (_xb, _f, _p) in enumerate(zip(_x, dyn["Факт"], dyn["План"])):
                if i not in _fact_label_idx:
                    continue
                if int(_p) <= 0:
                    _ann_text = f"{int(_f)}"
                    _pct_color = _th.bad
                else:
                    _pct = int(round(float(_f) / float(_p) * 100.0))
                    if _pct == 0:
                        continue
                    _pct_color = _th.good if float(_f) >= float(_p) else _th.bad
                    _ann_text = f"{int(_f)} ({_pct}%)"
                fig.add_annotation(
                    x=_xb,
                    y=int(_f),
                    text=_ann_text,
                    showarrow=False,
                    xref="x",
                    yref="y",
                    xanchor="center",
                    yanchor="top",
                    yshift=-10,
                    font=dict(size=_ann_sz, color=_pct_color),
                )

        _base_h = max(460, min(680, 34 * _n_pts + 100))
        _chart_h = int(_base_h if _agg_cf == "неделя" else 1.5 * _base_h)

        _x_dtick = None
        if not _use_cat_x and _agg_cf == "день":
            if _n_pts > 24:
                _x_dtick = "D5"
            elif _n_pts > 12:
                _x_dtick = "D3"
            else:
                _x_dtick = "D2"
        elif not _use_cat_x and _agg_cf == "неделя":
            _x_dtick = "D7"

        _x_margin_b = max(96, 72 + min(_n_pts, 18) * 4) if _use_cat_x else 96
        fig.update_layout(
            title=dict(
                text=f"Среднее за день — {sel_vid.lower()} (ресурсы)",
                font=dict(size=_dyn_sz(15), color=_th.text),
            ),
            plot_bgcolor=_th.chart_bg,
            paper_bgcolor=_th.chart_bg,
            font_color=_th.text,
            height=_chart_h,
            showlegend=True,
            margin=dict(l=62, r=32, t=104, b=_x_margin_b + 84),
            legend=dict(
                orientation="h",
                yanchor="top",
                y=-0.22,
                xanchor="center",
                x=0.5,
                font=dict(color=_th.text),
            ),
            yaxis=dict(
                title="Среднее за день",
                range=_comb_range,
                dtick=_comb_dtick,
                autorange=False,
                showgrid=True,
                gridcolor=_th.chart_grid,
            ),
        )
        fig.update_xaxes(
            title_text=f"Период — {agg_kind.lower()}",
            type="category" if _use_cat_x else "date",
            tickformat=None if _use_cat_x else "%d.%m.%Y",
            dtick=_x_dtick,
            tickangle=-35 if _use_cat_x and _n_pts > 5 else (-35 if _n_pts > 6 else 0),
            showgrid=True,
            gridcolor=_th.chart_grid,
            tickfont=dict(size=_axis_tick_sz, color=_th.text),
            title_font=dict(size=_axis_title_sz, color=_th.text),
            automargin=True,
        )
        fig.update_yaxes(
            tickfont=dict(size=_axis_tick_sz, color=_th.text),
            title_font=dict(size=_axis_title_sz, color=_th.text),
        )
        fig = apply_gdrs_chart_background(fig, _th)
        fig.update_xaxes(
            tickfont=dict(size=_axis_tick_sz, color=_th.text),
            title_font=dict(size=_axis_title_sz, color=_th.text),
        )
        fig.update_yaxes(
            tickfont=dict(size=_axis_tick_sz, color=_th.text),
            title_font=dict(size=_axis_title_sz, color=_th.text),
        )
        fig.update_layout(legend=dict(font=dict(size=_dyn_sz(12))))
        _dyn_plot_key = (
            f"gdrs_dyn_plot_{vid_locked or 'any'}_{theme}_{agg_kind}_{plan_agg}_{skud_agg}"
        )
        if _dyn_hscroll:
            _dyn_canvas_w = max(1180, int(_n_pts * 92))
            fig.update_layout(showlegend=False)
            _gdrs_render_bar_hscroll(
                st,
                fig,
                width_px=_dyn_canvas_w,
                height_px=_chart_h,
                theme=_th,
                key=_dyn_plot_key,
                legend_items=[
                    ("План", _th.line_plan),
                    ("Факт", _th.line_fact),
                ],
            )
        else:
            _gdrs_st_plotly_chart(st, fig, key=_dyn_plot_key)
        st.caption(
            "План и факт на одной шкале (среднее за день в периоде группировки); "
            "подписи у факта — значение и % от плана."
            + (
                " График прокручивается по горизонтали — все подписи дней видны без наложения."
                if _dyn_hscroll
                else (
                    " При группировке «День» часть подписей скрыта — полные данные в таблице "
                    "ниже и во всплывающей подсказке."
                    if _agg_cf == "день" and _n_pts > 10
                    else ""
                )
            )
        )

        _dyn_tbl = pd.DataFrame({
            "Период": dyn["Период"].astype(str),
            "План": _plan_s.round(0).astype(int),
            "Факт": _fact_s.round(0).astype(int),
        })
        _dyn_tbl["Отклонение"] = (_fact_s - _plan_s).round(0).astype(int)
        _dyn_tbl["Отклонение %"] = [
            ((float(f) - float(p)) / float(p) * 100.0)
            if float(p) > 0
            else float("nan")
            for f, p in zip(_fact_s, _plan_s)
        ]
        gdrs_render_subheader(st, "Детализация по периодам", theme=theme, level=4)
        render_report_html_table(
            _gdrs_summary_table_to_html(_dyn_tbl, theme=theme),
            export_df=_dyn_tbl,
            file_stem=_export_file_stem("Детализация по периодам"),
            key_prefix=f"gdrs_dyn_detail_{abs(id(_dyn_tbl))}",
        )
    except Exception as _e:
        st.warning(f"Plotly недоступен: {_e}")
        _plan_fb = pd.to_numeric(dyn["План"], errors="coerce").fillna(0.0)
        _fact_fb = pd.to_numeric(dyn["Факт"], errors="coerce").fillna(0.0)
        _fb_tbl = pd.DataFrame({
            "Период": dyn["Период"],
            "План": _plan_fb.round(0).astype(int),
            "Факт": _fact_fb.round(0).astype(int),
        })
        _fb_tbl["Отклонение"] = (_fact_fb - _plan_fb).round(0).astype(int)
        _fb_tbl["Отклонение %"] = [
            ((float(f) - float(p)) / float(p) * 100.0)
            if float(p) > 0
            else float("nan")
            for f, p in zip(_fact_fb, _plan_fb)
        ]
        render_report_html_table(
            _gdrs_summary_table_to_html(_fb_tbl, theme=theme),
            export_df=_fb_tbl,
            file_stem=_export_file_stem("Детализация по периодам"),
            key_prefix=f"gdrs_dyn_detail_fb_{abs(id(_fb_tbl))}",
        )


