def _gdrs_projects_summary_display(proj_df: pd.DataFrame) -> pd.DataFrame:
    d = proj_df.sort_values("plan", ascending=False).copy()
    _pn = d["project_name"].astype(str).str.strip()
    d = d[
        _pn.ne("")
        & ~_pn.str.casefold().isin(("nan", "none", "<na>", "nat", "—", "-", "null"))
    ].copy()
    out = pd.DataFrame({
        "Проект": d["project_name"].astype(str),
        "План": d["plan"].fillna(0).round(0).astype(int),
        "Факт": d["skud"].fillna(0).round(0).astype(int),
        "Отклонение": d["deviation"].round(0).astype(int),
    })
    if "delta_pct" in d.columns:
        out["Отклонение %"] = d["delta_pct"]
    return out


def _gdrs_build_contractors_chart_df(main_t: pd.DataFrame) -> pd.DataFrame:
    """Свод по контрагентам: одна строка на контрагента (нормализованное имя)."""
    from dashboards.gdrs_resursi import normalize_name

    cols = ["project_name", "contractor_name", "plan", "skud"]
    raw = main_t.loc[main_t["row_kind"] == "row", [c for c in cols if c in main_t.columns]].copy()
    if raw.empty or "contractor_name" not in raw.columns:
        return pd.DataFrame(columns=["Контрагент", "План", "Факт", "Отклонение"])
    if "project_name" in raw.columns:
        raw = raw.drop_duplicates(subset=["project_name", "contractor_name"], keep="first")
    raw["contractor_name"] = raw["contractor_name"].astype(str).str.strip()
    raw = raw[raw["contractor_name"] != ""]
    if raw.empty:
        return pd.DataFrame(columns=["Контрагент", "План", "Факт", "Отклонение"])
    raw["plan"] = pd.to_numeric(raw["plan"], errors="coerce").fillna(0.0)
    raw["skud"] = pd.to_numeric(raw["skud"], errors="coerce").fillna(0.0)
    raw["__cn__"] = raw["contractor_name"].map(normalize_name)

    def _pick_name(s: pd.Series) -> str:
        cnt = s.astype(str).str.strip().value_counts()
        return str(cnt.idxmax()) if not cnt.empty else ""

    agg = raw.groupby("__cn__", as_index=False).agg(
        contractor_name=("contractor_name", _pick_name),
        plan=("plan", "sum"),
        skud=("skud", "sum"),
    )
    agg = agg.drop(columns=["__cn__"], errors="ignore")
    agg.rename(
        columns={"contractor_name": "Контрагент", "plan": "План", "skud": "Факт"},
        inplace=True,
    )
    agg["План"] = agg["План"].round(0).astype(int)
    agg["Факт"] = agg["Факт"].round(0).astype(int)
    agg["Отклонение"] = (agg["Факт"] - agg["План"]).round(0).astype(int)
    return agg.sort_values("План", ascending=False).reset_index(drop=True)


def _gdrs_contractors_summary_display(chart_df: pd.DataFrame) -> pd.DataFrame:
    d = chart_df.sort_values("План", ascending=False).copy()
    return d[["Контрагент", "План", "Факт", "Отклонение"]].copy()



def _gdrs_pie_distribution_display(pie_df: pd.DataFrame) -> pd.DataFrame:
    """Таблица распределения: сортировка по плану; доля — от суммы факта."""
    sort_cols = [c for c in ("План", "Факт") if c in pie_df.columns]
    d = (
        pie_df.sort_values(sort_cols, ascending=False).copy()
        if sort_cols
        else pie_df.copy()
    )
    total = float(pd.to_numeric(d["Факт"], errors="coerce").fillna(0).sum())
    out = pd.DataFrame({
        "Контрагент": d["Контрагент"].astype(str),
    })
    if "План" in d.columns:
        out["План"] = pd.to_numeric(d["План"], errors="coerce").fillna(0).round(0).astype(int)
    out["Факт"] = pd.to_numeric(d["Факт"], errors="coerce").fillna(0).round(0).astype(int)
    if "Отклонение" in d.columns:
        out["Отклонение"] = pd.to_numeric(d["Отклонение"], errors="coerce").fillna(0).round(0).astype(int)
    if total > 0:
        out["Доля, %"] = (
            pd.to_numeric(d["Факт"], errors="coerce").fillna(0) / total * 100.0
        ).apply(lambda x: f"{float(x):.1f}%")
    else:
        out["Доля, %"] = "—"
    return out


def _gdrs_render_contractors_pie_block(
    st,
    chart_df: pd.DataFrame,
    *,
    unit_gen: str,
    theme: str,
    key_suffix: str = "",
) -> None:
    """Круговая «Распределение … по контрагентам» (топ-10 + «Прочие»)."""
    from dashboards.gdrs_theme import gdrs_render_subheader

    gdrs_render_subheader(st, f"Распределение {unit_gen} по контрагентам", theme=theme)
    pie_source = chart_df[chart_df["Факт"] > 0].copy()
    pie_df = pie_source[["Контрагент", "Факт"]].copy()
    if pie_df.empty:
        st.info("Нет фактических данных для круговой диаграммы.")
        return
    _pie_full_n = int(len(pie_df))
    _pie_chart_df = _gdrs_pie_contractors_chart_df(pie_df)
    if _pie_full_n > 10:
        st.caption(
            "Диаграмма: топ-10 контрагентов по факту; остальные объединены в «Прочие». "
            "Полный список (план или факт) — в таблице «Распределение …» ниже на странице."
        )
    try:
        fig3 = _gdrs_pie_contractors_figure(_pie_chart_df, theme=theme)
        fig3 = _ensure_pie_full_modebar(fig3)
        _inject_pie_modebar_zoom_sync()
        # На всю ширину блока (как bar). Круг ровный: без pull; Plotly вписывает
        # donut в min(domain) при responsive. Полный modebar — как у остальных графиков.
        _gdrs_st_plotly_chart(
            st,
            fig3,
            key=f"gdrs_pie_{key_suffix}" if key_suffix else "gdrs_pie",
            use_container_width=True,
            config=_PLOTLY_CONFIG_FULL_MODEBAR,
        )
    except Exception as _e:
        st.warning(f"Plotly недоступен: {_e}")


def _gdrs_deviation_vs_plan_text_and_color(plan_v, fact_v) -> tuple[str, str]:
    """Подпись отклонения (факт − план): факт < план — красный и «−», иначе зелёный и «+»."""
    p = float(pd.to_numeric(plan_v, errors="coerce") or 0)
    f = float(pd.to_numeric(fact_v, errors="coerce") or 0)
    d = int(round(f - p))
    if f < p:
        return f"{d:d}", "#ff5454"
    if f > p:
        return f"{d:+d}", "#46d68a"
    return "0", "#8899aa"


def _gdrs_deviation_display_cls(v) -> tuple[str, str]:
    """Отклонение = факт − план: «+» если факт > плана, «−» если наоборот."""
    fv = pd.to_numeric(v, errors="coerce")
    if pd.isna(fv):
        return "—", ""
    d = int(round(float(fv)))
    if d < 0:
        return f"{d:d}", "gdrs-u"
    if d > 0:
        return f"{d:+d}", "gdrs-o"
    return "0", "gdrs-z"


def _gdrs_pct_display_cls(v) -> tuple[str, str]:
    if isinstance(v, str) and "%" in v:
        try:
            fv = float(str(v).replace("%", "").replace(",", ".").strip())
        except (TypeError, ValueError):
            return str(v), ""
    else:
        fv = pd.to_numeric(v, errors="coerce")
    if pd.isna(fv):
        return "—", ""
    display = float(fv)
    text_v = f"{display:+.1f}%" if display != 0.0 else "0.0%"
    if display < 0:
        return text_v, "gdrs-u"
    if display > 0:
        return text_v, "gdrs-o"
    return text_v, "gdrs-z"


def _gdrs_deviation_cell_bg_style(raw, *, theme: str = "dark") -> str:
    from dashboards.gdrs_resursi import gdrs_deviation_cell_bg_style

    return gdrs_deviation_cell_bg_style(raw, theme=theme)


def _gdrs_append_summary_total_row(df: pd.DataFrame) -> pd.DataFrame:
    """Итоговая строка для сводных таблиц ГДРС (проекты / контрагенты)."""
    if df is None or df.empty:
        return df
    label_cols = {"Контрагент", "Проект"}
    int_cols = {"План", "Факт", "СКУД", "Отклонение"}
    row: dict = {}
    sum_plan: int | None = None
    sum_fact: int | None = None
    for col in df.columns:
        cl = str(col).strip()
        if cl in label_cols:
            row[col] = "Итого"
        elif cl in int_cols:
            val = int(round(pd.to_numeric(df[col], errors="coerce").fillna(0).sum()))
            row[col] = val
            if cl == "План":
                sum_plan = val
            elif cl in ("Факт", "СКУД"):
                sum_fact = val
        elif cl == "Доля, %":
            row[col] = "100.0%"
        else:
            row[col] = ""
    if "Отклонение" in df.columns and sum_plan is not None and sum_fact is not None:
        row["Отклонение"] = int(sum_fact - sum_plan)
    if "Отклонение %" in df.columns:
        sp = sum_plan if sum_plan is not None else int(
            round(pd.to_numeric(df["План"], errors="coerce").fillna(0).sum())
        )
        sf = sum_fact if sum_fact is not None else int(
            round(pd.to_numeric(df.get("Факт", df.get("СКУД", 0)), errors="coerce").fillna(0).sum())
        )
        row["Отклонение %"] = ((sf - sp) / sp * 100.0) if sp > 0 else float("nan")
    return pd.concat([df, pd.DataFrame([row])], ignore_index=True)


def _gdrs_render_pie_chart(st, fig, *, width_px: int, height_px: int, theme: Any, key: str) -> None:
    """Круговая ГДРС: блок 100% ширины, круг с фикс. px по центру (без CSS-растяжения)."""
    import uuid as _uuid

    w = int(max(width_px, 320))
    h = int(max(height_px, 320))
    cfg = {**_PLOTLY_CONFIG_FULL_MODEBAR, "responsive": False}
    try:
        fig.update_layout(width=w, height=h, autosize=False)
    except Exception:
        pass
    _chart_bg = getattr(theme, "chart_bg", "#ffffff")
    _border = getattr(theme, "border", "rgba(148,163,184,0.35)")
    uid = _uuid.uuid4().hex[:8]
    wrap_cls = f"gdrs-pie-{uid}-wrap"
    inner_cls = f"gdrs-pie-{uid}-inner"
    try:
        plot_div = fig.to_html(
            full_html=False,
            include_plotlyjs="cdn",
            config=cfg,
            default_width=f"{w}px",
            default_height=f"{h}px",
        )
        shell = (
            "<!DOCTYPE html><html><head><meta charset='utf-8'>"
            "<style>"
            f"html,body{{margin:0;padding:0;background:transparent;overflow:visible;}}"
            f".{wrap_cls}{{width:100%;max-width:100%;overflow-x:auto;overflow-y:visible;"
            f"-webkit-overflow-scrolling:touch;box-sizing:border-box;line-height:normal;"
            f"border:1px solid {_border};border-radius:8px;background:{_chart_bg};"
            f"display:flex;justify-content:center;padding:4px 0 8px 0;}}"
            f".{inner_cls}{{width:{w}px;min-width:{w}px;max-width:{w}px;display:block;line-height:normal;}}"
            f".{inner_cls} .plotly-graph-div,.{inner_cls} .js-plotly-plot{{"
            f"width:{w}px!important;min-width:{w}px!important;max-width:{w}px!important;"
            f"height:{h}px!important;}}"
            f".{wrap_cls}::-webkit-scrollbar{{height:13px;}}"
            f".{wrap_cls}::-webkit-scrollbar-thumb{{background:rgba(148,163,184,0.6);border-radius:6px;}}"
            "</style></head><body>"
            f'<div class="{wrap_cls}"><div class="{inner_cls}">{plot_div}</div></div>'
            "</body></html>"
        )
        components.html(shell, height=h + 20, scrolling=False)
    except Exception:
        _gdrs_st_plotly_chart(
            st,
            fig,
            key=key,
            use_container_width=True,
            config=_PLOTLY_CONFIG_FULL_MODEBAR,
        )


def _gdrs_st_plotly_chart(st, fig, *, key: str | None = None, **kwargs) -> None:
    """Plotly в ГДРС: единый config с постоянной панелью инструментов."""
    cfg = dict(_PLOTLY_CONFIG)
    extra = kwargs.pop("config", None)
    if extra:
        cfg.update(extra)
    kw = {"use_container_width": True, "config": cfg, **kwargs}
    if key is not None:
        kw["key"] = key
    st.plotly_chart(fig, **kw)


def _gdrs_legend_below_html(items: list[tuple[str, str]], theme: Any) -> str:
    """Статичная легенда под графиком (как в других дашбордах) в палитре ГДРС."""
    if not items:
        return ""
    _txt = getattr(theme, "text", "#111827")
    _bg = getattr(theme, "chart_bg", "transparent")
    _bd = getattr(theme, "border", "rgba(148,163,184,0.35)")
    html = (
        '<div style="display:flex;flex-wrap:wrap;gap:10px 26px;justify-content:center;'
        f'padding:12px 8px 6px 8px;margin:4px 0 2px 0;font-size:15px;line-height:1.5;'
        f'background:{_bg};border-top:1px solid {_bd};">'
    )
    for _name, _color in items:
        html += (
            '<span style="display:inline-flex;align-items:center;gap:8px;">'
            f'<span style="display:inline-block;width:18px;height:18px;border-radius:3px;'
            f'background:{_color};flex-shrink:0;"></span>'
            f'<span style="color:{_txt};font-weight:600;">{html_module.escape(str(_name))}</span>'
            '</span>'
        )
    html += "</div>"
    return html


def _gdrs_render_bar_hscroll(
    st,
    fig,
    *,
    width_px: int,
    height_px: int,
    theme: Any,
    key: str,
    legend_items: list[tuple[str, str]] | None = None,
) -> None:
    """Широкий столбчатый график ГДРС с горизонтальным скроллом + статичная легенда снизу."""
    import uuid as _uuid

    w = int(max(width_px, 320))
    h = int(max(height_px, 320))
    cfg = dict(_PLOTLY_CONFIG)
    cfg["responsive"] = False
    try:
        fig.update_layout(width=w, height=h, autosize=False, showlegend=False)
    except Exception:
        pass

    _chart_bg = getattr(theme, "chart_bg", "#ffffff")
    _border = getattr(theme, "border", "rgba(148,163,184,0.35)")
    uid = _uuid.uuid4().hex[:8]
    wrap_cls = f"gdrs-bar-hscroll-{uid}-wrap"
    inner_cls = f"gdrs-bar-hscroll-{uid}-inner"
    _scroll_px = 24
    try:
        plot_div = fig.to_html(
            full_html=False,
            include_plotlyjs="cdn",
            config=cfg,
            default_width=f"{w}px",
            default_height=f"{h}px",
        )
        _pin_css = _finance_plotly_hscroll_modebar_pin_css(wrap_class=wrap_cls)
        _pin_js = _finance_plotly_hscroll_modebar_pin_script(
            wrap_class=wrap_cls, inner_class=inner_cls
        )
        shell = (
            "<!DOCTYPE html><html><head><meta charset='utf-8'>"
            "<style>"
            f"html,body{{margin:0;padding:0;background:transparent;overflow:visible;min-height:{h + _scroll_px}px;}}"
            f".{wrap_cls}{{width:100%;max-width:100%;overflow-x:auto;overflow-y:visible;"
            f"-webkit-overflow-scrolling:touch;box-sizing:border-box;line-height:normal;"
            f"padding:0 0 {_scroll_px}px 0;scrollbar-gutter:stable both-edges;"
            f"border:1px solid {_border};border-radius:8px;background:{_chart_bg};"
            f"min-height:{h + _scroll_px}px;}}"
            f".{inner_cls}{{width:{w}px;min-width:{w}px;max-width:{w}px;display:block;line-height:normal;}}"
            f".{inner_cls} .plotly-graph-div,.{inner_cls} .js-plotly-plot{{"
            f"width:{w}px!important;min-width:{w}px!important;max-width:{w}px!important;height:{h}px!important;}}"
            f".{wrap_cls}::-webkit-scrollbar{{height:13px;}}"
            f".{wrap_cls}::-webkit-scrollbar-thumb{{background:rgba(148,163,184,0.6);border-radius:6px;}}"
            f".{wrap_cls}::-webkit-scrollbar-track{{background:rgba(148,163,184,0.18);border-radius:6px;}}"
            f"{_pin_css}"
            "</style></head><body>"
            f'<div class="{wrap_cls}"><div class="{inner_cls}">{plot_div}</div></div>'
            f"{_pin_js}"
            "</body></html>"
        )
        components.html(shell, height=h + _scroll_px + 14, scrolling=False)
    except Exception:
        _gdrs_st_plotly_chart(st, fig, key=key, config={"responsive": False})

    _leg = _gdrs_legend_below_html(legend_items or [], theme)
    if _leg:
        st.markdown(_leg, unsafe_allow_html=True)


def _gdrs_summary_table_to_html(
    df: pd.DataFrame,
    *,
    theme: str = "dark",
    total_row_index: int | None = None,
) -> str:
    from dashboards.gdrs_theme import get_gdrs_theme

    _th = get_gdrs_theme(theme)
    if df is None or df.empty:
        return "<p>Нет данных для отображения.</p>"
    wrap_id = "gdrs_sum_" + str(abs(id(df)))
    tag = "d" + "iv"
    _wrap_cls = "gdrs-summary-table-wrap gdrs-light-table" if _th.name == "light" else "gdrs-summary-table-wrap"
    parts = [
        f"<{tag} id=\"{wrap_id}\" class=\"{_wrap_cls}\" "
        f"style=\"overflow-x:auto;min-width:0;margin:0.75em 0;\">",
        f"<style>"
        f"#{wrap_id} table {{ width:100%; table-layout:fixed; border-collapse:collapse; font-size:15px; "
        f"background-color:{_th.table_bg}; color:{_th.table_text}; }}"
        f"#{wrap_id} th.col-num, #{wrap_id} td.col-num {{ width:6.5rem; min-width:5rem; max-width:7.5rem; white-space:nowrap!important; }}"
        f"#{wrap_id} th.col-text, #{wrap_id} td.col-text {{ width:auto; min-width:9rem; }}"
        f"#{wrap_id} th, #{wrap_id} td {{ border:1px solid {_th.border}; padding:8px 10px; color:{_th.table_text} !important; font-weight:700; }}"
        f"#{wrap_id} th, #{wrap_id} td, #{wrap_id} th *, #{wrap_id} td * {{ color:{_th.table_text} !important; }}"
        f"#{wrap_id} th {{ background-color:{_th.table_header_bg}; {_th.table_header_font_css}; text-align:center!important; white-space:normal;word-wrap:break-word;overflow-wrap:anywhere;line-height:1.25;max-width:11em;overflow:visible;text-overflow:clip;vertical-align:bottom; }}"
        f"#{wrap_id} td {{ text-align:center;vertical-align:middle;white-space:normal;word-wrap:break-word;overflow-wrap:anywhere;overflow:visible;text-overflow:clip;max-width:28em; }}"
        f"#{wrap_id} td.col-text {{ text-align:left!important;vertical-align:top;max-width:36em; }}"
        f"#{wrap_id} th.col-text {{ text-align:center!important; }}"
        f"#{wrap_id} td.gdrs-u, #{wrap_id} td.gdrs-u span {{ color:{_th.bad} !important; font-weight:800; }}"
        f"#{wrap_id} td.gdrs-o, #{wrap_id} td.gdrs-o span {{ color:{_th.good} !important; font-weight:800; }}"
        f"#{wrap_id} td.gdrs-z, #{wrap_id} td.gdrs-z span {{ color:{_th.neutral} !important; }}"
        f"#{wrap_id} tr.gdrs-total-row td, #{wrap_id} tr.bd-total-row td {{ background-color:{_th.table_header_bg}; "
        f"border-top:2px solid {_th.border}; font-weight:800; text-transform:uppercase; }}"
        f"#{wrap_id} tbody {{ padding-bottom:4px; }}"
        f"</style>",
        '<table class="bi-sortable-table"><thead><tr>',
    ]
    for col in df.columns:
        _cc = table_column_css_class(str(col))
        _ce = html_module.escape(str(col))
        parts.append(
            f'<th class="{_cc}" data-sort-label="{_ce}">'
            f'<span class="bi-sort-label">{_ce} \u21c5</span></th>'
        )
    parts.append("</tr></thead><tbody>")
    _int_cols = {"План", "Факт", "СКУД"}
    for ri, (_, row) in enumerate(df.iterrows()):
        _tr_cls = ""
        if total_row_index is not None and ri == total_row_index:
            _tr_cls = ' class="gdrs-total-row bd-total-row"'
        parts.append(f"<tr{_tr_cls}>")
        for col in df.columns:
            val = row[col]
            cl = str(col).strip()
            extra_cls = ""
            extra_style = ""
            if cl == "Отклонение":
                inner, extra_cls = _gdrs_deviation_display_cls(val)
                extra_style = _gdrs_deviation_cell_bg_style(val, theme=theme)
            elif cl == "Отклонение %":
                inner, extra_cls = _gdrs_pct_display_cls(val)
                extra_style = _gdrs_delta_pct_cell_bg_style(val, theme=theme)
            elif cl in _int_cols:
                num = pd.to_numeric(val, errors="coerce")
                inner = "0" if pd.isna(num) else str(int(round(float(num))))
            else:
                inner = "" if val is None or (isinstance(val, float) and pd.isna(val)) else str(val)
            _cc = table_column_css_class(cl)
            _td_cls = f"{_cc} {extra_cls}".strip() if extra_cls else _cc
            cls_attr = f' class="{_td_cls}"' if _td_cls else ""
            st_attr = f' style="{extra_style}"' if extra_style else ""
            parts.append(f"<td{cls_attr}{st_attr}><span>{html_module.escape(inner)}</span></td>")
        parts.append("</tr>")
    parts.append(f"</tbody></table></{tag}>")
    return mark_html_table_sortable("".join(parts))

def _gdrs_render_plan_fact_summary_table(
    st,
    display_df: pd.DataFrame,
    *,
    table_title: str,
    theme: str = "dark",
) -> None:
    from dashboards.gdrs_theme import gdrs_render_table_subheader

    if display_df is None or display_df.empty:
        st.info("Нет данных для таблицы.")
        return
    gdrs_render_table_subheader(st, table_title, theme=theme)
    display_with_total = _gdrs_append_summary_total_row(display_df)
    total_ix = len(display_with_total) - 1
    render_report_html_table(
        _gdrs_summary_table_to_html(
            display_with_total,
            theme=theme,
            total_row_index=total_ix,
        ),
        export_df=display_with_total,
        file_stem=_export_file_stem(table_title),
        key_prefix=f"gdrs_sum_{abs(id(display_df))}",
    )


