def dashboard_gdrs(df, vid_locked: str | None = None, *, theme: str | None = None):
    """
    ГДРС — переписанный по ТЗ заказчика 2026-05-07 (см. docs/TZ_GDRS_2026-05-07.md).

    Параметры:
        vid_locked: "Рабочие" / "Техника" / None.
            Если задан — radio-фильтр «Вид ресурсов» скрывается, дашборд работает в этом режиме
            (используется обёртками dashboard_gdrs_people / dashboard_gdrs_equipment_v2).

    Источники:
      • web/AI/other_<DD-MM-YYYY>_resursi.csv  → план/факт по неделям, по контрагентам.
      • web/1с_*_Dogovor.json (все snapshot)   → план (Количество_Людей / Количество_Техники)
                                                 + Наименование_Договора (для «Вид работы»).
      • web/1с_*_spravochniki.json (все)       → fallback план (КоличествоРаботников / СпецТехники).

    UI: одна страница — 4 визуала (проекты, контрагенты, динамика, круговая) и таблица.
    Фильтры сверху: Проект (multi), Контрагент (multi), [Вид ресурсов — только если не locked],
                    Период (date range), «Только с планом» (checkbox).

    theme: None → авто по cutover (светлая, если ``is_light_preview_active()``); иначе
    "light"/"dark" явно (превью-обёртки заказчика передают "light").
    ГДРС-графики выводятся через ``_gdrs_st_plotly_chart`` (прямой ``st.plotly_chart``,
    минуя ``render_chart``/``_resync_plotly_chart_theme``), поэтому цвет фона фигуры не
    переустанавливается на выводе — тему обязательно резолвим здесь, иначе под глобальным
    cutover канонические экраны рисуются с тёмным ``chart_bg`` из GDRS_THEME_DARK.
    """
    import os
    import sys
    from pathlib import Path as _Path
    import pandas as _pd
    import numpy as _np
    from dashboards.gdrs_theme import (
        apply_gdrs_chart_background,
        get_gdrs_theme,
        gdrs_deviation_vs_plan_text_and_color,
        gdrs_render_subheader,
        gdrs_render_table_subheader,
        gdrs_apply_grouped_bar_labels,
        gdrs_apply_bar_outside_labels,
        gdrs_sanitize_bar_text_labels,
        gdrs_apply_bottom_chart_legend,
        inject_gdrs_light_preview_css,
    )

    if theme is None:
        try:
            from dashboards.light_theme import is_light_preview_active

            theme = "light" if is_light_preview_active() else "dark"
        except Exception:
            theme = "dark"

    _th = get_gdrs_theme(theme)
    if theme == "light":
        inject_gdrs_light_preview_css(st)
        _gdrs_light_preview_active = True
    else:
        _gdrs_light_preview_active = False

    _this = os.path.dirname(os.path.abspath(__file__))
    _root = os.path.dirname(_this)
    if _root not in sys.path:
        sys.path.insert(0, _root)
    from dashboards.gdrs_resursi import (
        build_main_table,
        gdrs_agg_label_to_key,
        gdrs_agg_week_num,
        GDRS_AGG_LABELS,
        gdrs_agg_select_options,
        gdrs_agg_select_options_for_weeks,
        gdrs_week_numbers_with_fact,
        gdrs_filter_fact_by_months,
        gdrs_filter_fact_resursi_source_for_periods,
        gdrs_matrix_show_week_columns,
        gdrs_matrix_week_count,
        gdrs_matrix_week_labels,
        build_gdrs_audit_export_frames,
        gdrs_month_select_options,
        gdrs_default_month_labels,
        gdrs_resolve_month_periods,
        gdrs_months_date_range,
        gdrs_plan_snapshot_date,
        load_1c_dannye_article_maps,
        load_plan_aggregate,
        load_resursi_files,
        load_1c_kontr_index,
        enrich_gdrs_fact_contractor_ids,
        enrich_gdrs_fact_project_ids,
        gdrs_apply_kontr_contractor_names,
        _gdrs_cached_termination_index,
        _gdrs_cached_enriched_fact,
        gdrs_filter_fact_by_termination,
        week_end_in_filtered_fact,
        gdrs_week_numbers_in_period,
        _gdrs_plan_loader,
        _gdrs_dogovor_sources_sig,
        gdrs_contractor_filter_options,
    )

    from web_db_read import json_records_by_source, resolve_version_id, web_db_mtime

    _version_id = resolve_version_id(st.session_state.get("web_version_id"))
    if not _version_id:
        st.warning(
            "Нет активной версии данных в БД. Выполните загрузку «FTP → web/ → БД» в админке."
        )
        return

    _db_mtime = web_db_mtime()
    _dog_records = json_records_by_source(_version_id, "dogovor_json")
    _spr_records = json_records_by_source(_version_id, "spravochniki_json")
    _kontr_records = json_records_by_source(_version_id, "kontr_json")
    _kontr_flat = [r for recs in _kontr_records.values() for r in recs]
    _extra_source_names = sorted(set(_dog_records.keys()) | set(_spr_records.keys()))

    _dog_sig = _gdrs_dogovor_sources_sig(_version_id)
    with st.spinner("Загрузка ресурсов…"):
        long_fact = _gdrs_cached_enriched_fact(_version_id, _db_mtime, _dog_sig)
    if long_fact is None or long_fact.empty:
        st.error(
            "Нет данных ресурсов в БД (gdrs_fact). Выполните загрузку FTP → web/ → БД."
        )
        return
    # _kontr_index нужен ниже для gdrs_contractor_filter_options; сам факт уже обогащён
    # и отфильтрован по termination внутри кэшированной _gdrs_cached_enriched_fact.
    _kontr_index = load_1c_kontr_index(records=_kontr_flat) if _kontr_flat else None
    _term_index = _gdrs_cached_termination_index(_version_id, _db_mtime, _dog_sig)

    _month_options = gdrs_month_select_options(
        long_fact,
        extra_paths=_extra_source_names,
        dogovor_records=_dog_records,
    )
    _month_labels = [lbl for lbl, _ in _month_options]
    _month_label_to_period = {lbl: per for lbl, per in _month_options}

    use_radio = vid_locked is None
    _gdrs_vid_key = vid_locked or "any"
    _gdrs_key_suffix = f"{_gdrs_vid_key}_light" if theme == "light" else _gdrs_vid_key
    _gdrs_reset_keys = [
        f"gdrs_filter_projects_{_gdrs_key_suffix}",
        f"gdrs_filter_contractors_{_gdrs_key_suffix}",
        f"gdrs_filter_months_{_gdrs_key_suffix}",
        f"gdrs_filter_only_plan_{_gdrs_key_suffix}",
        f"gdrs_filter_plan_agg_{_gdrs_key_suffix}",
        f"gdrs_filter_skud_agg_{_gdrs_key_suffix}",
    ]
    if use_radio:
        _gdrs_reset_keys.append(f"gdrs_filter_vid_{_gdrs_key_suffix}")
    with filters_panel(st, reset_keys=_gdrs_reset_keys):
        project_options = project_labels_for_filter(
            long_fact["project_name"],
            apply_exclude_names=False,
        )
        _agg_opts = gdrs_agg_select_options()
        with filters_selectors(st):
            if use_radio:
                _fc1, _fc2, _fc3, _fc4, _fc5, _fc6 = st.columns(6, gap="small")
            else:
                _fc1, _fc2, _fc3, _fc4, _fc5 = st.columns(5, gap="small")
            with _fc1:
                sel_projects, _ = project_filter_multiselect(
                    st,
                    project_options,
                    key=f"gdrs_filter_projects_{_gdrs_key_suffix}",
                )
            _lf_proj = filter_dataframe_by_project_labels(
                long_fact, sel_projects, col="project_name"
            )
            _filter_plan_snap = (
                _pd.Timestamp(_month_label_to_period[_month_labels[-1]].end_time).normalize()
                if _month_labels
                else None
            )
            contractor_options = gdrs_contractor_filter_options(
                long_fact,
                dogovor_records=_dog_records,
                sprav_records=_spr_records,
                projects=sel_projects or None,
                snapshot_date=_filter_plan_snap,
                kontr=_kontr_index,
            )
            with _fc2:
                sel_contractors = st.multiselect(
                    "Контрагент",
                    contractor_options,
                    default=[],
                    key=f"gdrs_filter_contractors_{_gdrs_key_suffix}",
                    help="Пусто = все контрагенты выбранных проектов",
                    placeholder="Выберите контрагентов",
                )
            if use_radio:
                with _fc3:
                    sel_vid = st.radio(
                        "Вид ресурсов",
                        ["Рабочие", "Техника"],
                        horizontal=True,
                        key=f"gdrs_filter_vid_{_gdrs_key_suffix}",
                    )
                _month_col = _fc4
                _plan_col = _fc5
                _skud_col = _fc6
            else:
                sel_vid = vid_locked
                _month_col = _fc3
                _plan_col = _fc4
                _skud_col = _fc5
            with _month_col:
                _default_months = gdrs_default_month_labels(_month_options, long_fact)
                migrate_gdrs_month_multiselect_state(
                    st,
                    f"gdrs_filter_months_{_gdrs_key_suffix}",
                    _month_labels,
                    default_labels=_default_months,
                )
                sel_month_labels = st.multiselect(
                    "Месяц",
                    _month_labels,
                    default=_default_months,
                    key=f"gdrs_filter_months_{_gdrs_key_suffix}",
                    placeholder="Все месяцы",
                    help="Один или несколько календарных месяцев. Пусто — все месяцы с данными.",
                )
            # Опции недель — только те, где реально есть факт СКУД в выбранном
            # периоде (нумерация ISO-недель месяца как в resursi 1С). Иначе выбор
            # пустой недели даёт пустые диаграмму и таблицу.
            _wk_periods, _ = gdrs_resolve_month_periods(_month_options, sel_month_labels)
            _wk_from, _wk_to = gdrs_months_date_range(_wk_periods)
            _wk_from = _pd.to_datetime(_wk_from)
            _wk_to = _pd.to_datetime(_wk_to)
            _wk_fact = gdrs_filter_fact_by_months(long_fact, _wk_periods)
            _wk_fact = gdrs_filter_fact_resursi_source_for_periods(_wk_fact, _wk_periods)
            _weeks_with_fact = gdrs_week_numbers_with_fact(
                _wk_fact,
                vid=sel_vid,
                date_from=_wk_from,
                date_to=_wk_to,
                projects=sel_projects or None,
                contractors=sel_contractors or None,
            )
            _agg_opts = gdrs_agg_select_options_for_weeks(_weeks_with_fact)
            for _agg_key in (
                f"gdrs_filter_plan_agg_{_gdrs_key_suffix}",
                f"gdrs_filter_skud_agg_{_gdrs_key_suffix}",
            ):
                if st.session_state.get(_agg_key) not in _agg_opts:
                    st.session_state.pop(_agg_key, None)
            with _plan_col:
                _plan_lbl = st.selectbox(
                    "План",
                    _agg_opts,
                    index=0,
                    key=f"gdrs_filter_plan_agg_{_gdrs_key_suffix}",
                    help="Среднее за месяц — план из 1С на конец периода; "
                    "N неделя — план из 1С на последний день этой недели в периоде",
                )
            with _skud_col:
                _skud_lbl = st.selectbox(
                    "СКУД",
                    _agg_opts,
                    index=0,
                    key=f"gdrs_filter_skud_agg_{_gdrs_key_suffix}",
                    help="Среднее за месяц — среднее факт/день за весь период (CSV); "
                    "N неделя — среднее факт/день только в выбранной неделе",
                )

        with filters_toggles(st):
            only_with_plan = st.checkbox(
                "Только с планом",
                value=False,
                key=f"gdrs_filter_only_plan_{_gdrs_key_suffix}",
                help="Скрыть подрядчиков без плана в активном договоре",
            )


    _sel_periods, _month_stale = gdrs_resolve_month_periods(_month_options, sel_month_labels)
    if _month_stale:
        st.warning(
            "Выбранный месяц отсутствует в данных — показаны все доступные месяцы. "
            "Выберите период из списка (например, Февраль 2026)."
        )
    date_from, date_to = gdrs_months_date_range(_sel_periods)
    date_from = _pd.to_datetime(date_from)
    date_to = _pd.to_datetime(date_to)
    long_fact_period = gdrs_filter_fact_by_months(long_fact, _sel_periods)
    long_fact_period = gdrs_filter_fact_resursi_source_for_periods(long_fact_period, _sel_periods)
    if (
        long_fact is not None
        and not long_fact.empty
        and (long_fact_period is None or long_fact_period.empty)
    ):
        _fact_periods = set(
            pd.to_datetime(long_fact["date"], errors="coerce").dt.to_period("M").dropna().unique()
        )
        _avail_labels = [lbl for lbl, per in _month_options if per in _fact_periods]
        _hint = (
            f" Доступные месяцы с фактом СКУД: {', '.join(_avail_labels[-6:])}."
            if _avail_labels
            else ""
        )
        st.warning(
            "За выбранный месяц нет фактических данных СКУД (план 1С может отображаться). "
            "Выберите период с загруженным фактом."
            + _hint
        )

    _plan_agg = gdrs_agg_label_to_key(_plan_lbl)
    _skud_agg = gdrs_agg_label_to_key(_skud_lbl)
    _plan_snap = gdrs_plan_snapshot_date(
        long_fact_period,
        vid=sel_vid,
        date_from=date_from,
        date_to=date_to,
        plan_agg=_plan_agg,
        projects=sel_projects or None,
        contractors=sel_contractors or None,
    )
    _plan_loader = _gdrs_plan_loader(_version_id, _db_mtime)
    plan = _plan_loader(_pd.Timestamp(_plan_snap).normalize())

    _weekly_plan_by_week: dict[int, _pd.DataFrame] = {}
    _weekly_plan_as_of: dict[int, _pd.Timestamp] = {}
    if gdrs_matrix_show_week_columns(_plan_agg, _skud_agg, date_from=date_from, date_to=date_to):
        for _wn in gdrs_week_numbers_in_period(date_from, date_to):
            _w_end = week_end_in_filtered_fact(
                long_fact_period,
                vid=sel_vid,
                date_from=date_from,
                date_to=date_to,
                week_num=_wn,
                projects=sel_projects or None,
                contractors=sel_contractors or None,
            )
            if _w_end is None or not _pd.notna(_w_end):
                continue
            _weekly_plan_as_of[_wn] = _pd.Timestamp(_w_end).normalize()
            _weekly_plan_by_week[_wn] = _plan_loader(_weekly_plan_as_of[_wn])

    _by_dog, _by_pc, _by_sig_pc, _by_sig, _by_pc_sets = _gdrs_cached_dannye_maps(
        _version_id, _db_mtime
    )

    main_t = build_main_table(
        long_fact_period, plan,
        vid=sel_vid,
        date_from=date_from, date_to=date_to,
        projects=sel_projects or None,
        contractors=sel_contractors or None,
        only_with_plan=only_with_plan,
        article_by_contract_norm=_by_dog if _by_dog else None,
        article_sig_pc_sets=_by_sig_pc if _by_sig_pc else None,
        article_sig_sets=_by_sig if _by_sig else None,
        article_by_project_contractor=_by_pc if _by_pc else None,
        article_pc_sets=_by_pc_sets if _by_pc_sets else None,
        plan_agg=_plan_agg,
        skud_agg=_skud_agg,
        weekly_plan_by_week=_weekly_plan_by_week or None,
        weekly_plan_as_of=_weekly_plan_as_of or None,
        kontr_index=_kontr_index,
        term_index=_term_index,
        plan_as_of=_pd.Timestamp(_plan_snap).normalize(),
        plan_aggregate_loader=_gdrs_plan_loader(_version_id, _db_mtime),
        resursi_all_fact=long_fact,
    )
    if main_t is None or main_t.empty:
        st.info("Нет данных для выбранных фильтров.")
        return

    period_label = (
        f"{date_from.strftime('%d.%m.%Y')} — {date_to.strftime('%d.%m.%Y')}"
        if date_from != date_to else date_from.strftime("%d.%m.%Y")
    )
    unit = "люди" if sel_vid == "Рабочие" else "техника"
    _unit_gen = "людей" if sel_vid == "Рабочие" else "техники"

    chart_df = _gdrs_build_contractors_chart_df(main_t)

    gdrs_render_subheader(st, "ГДРС по выбранным проектам", theme=theme)
    proj_df = main_t[main_t["row_kind"] == "subtotal"][
        ["project_name", "plan", "skud", "deviation", "delta_pct"]
    ].copy()
    if not proj_df.empty:
        _pn_mask = proj_df["project_name"].astype(str).str.strip()
        proj_df = proj_df[
            _pn_mask.ne("")
            & ~_pn_mask.str.casefold().isin(("nan", "none", "<na>", "nat", "—", "-", "null"))
        ].copy()
    if not proj_df.empty:
        try:
            import plotly.graph_objects as _go
            proj_df = proj_df.sort_values("plan", ascending=False).reset_index(drop=True)
            _proj_labels = proj_df["project_name"].astype(str).tolist()
            _plan_vals = proj_df["plan"].fillna(0).astype(int).tolist()
            _fact_vals = proj_df["skud"].fillna(0).astype(int).tolist()
            _dev_text, _dev_colors, _dev_abs = [], [], []
            for _pv, _fv in zip(proj_df["plan"], proj_df["skud"]):
                _lbl, _col = gdrs_deviation_vs_plan_text_and_color(_pv, _fv, _th)
                _dev_text.append(_lbl)
                _dev_colors.append(_col)
                _dev_abs.append(abs(int(round(float(_fv) - float(_pv)))))
            _bar_axis_sz = 22 if theme == "light" else 14
            _proj_x_tick_sz = 44 if theme == "light" else 34
            _bar_title_sz = 22 if theme == "light" else 16
            _bar_margin_b = 120 if theme == "light" else 100
            fig_pf = _go.Figure()
            _bar_x_labels, _bar_title_suffix, _bar_x_cfg = _gdrs_add_plan_fact_deviation_traces(
                fig_pf,
                _proj_labels,
                _plan_vals,
                _fact_vals,
                _dev_abs,
                _dev_colors,
                _th,
            )
            _metrics_axis = len(_proj_labels) == 1
            _fixed_bar_slots = _bar_x_cfg is not None
            fig_pf.update_layout(
                title=dict(
                    text=f"План / Факт / Отклонение по проектам{_bar_title_suffix}",
                    font=dict(size=_bar_title_sz, color=_th.text, family="Inter, sans-serif"),
                    x=0.0, xanchor="left", y=0.96, yanchor="top",
                ),
                barmode="group",
                plot_bgcolor=_th.chart_bg,
                paper_bgcolor=_th.chart_bg,
                font_color=_th.text,
                xaxis=dict(
                    showgrid=False,
                    tickfont=dict(size=_proj_x_tick_sz, color=_th.text, family="Inter, sans-serif"),
                    tickangle=0,
                ),
                yaxis=dict(
                    showgrid=True,
                    gridcolor=_th.chart_grid,
                    tickfont=dict(size=_bar_axis_sz if theme == "light" else 12, color=_th.text),
                ),
                height=560 if theme == "light" else 520,
                margin=dict(l=56, r=24, t=88, b=_bar_margin_b),
                showlegend=True,
            )
            fig_pf = apply_gdrs_chart_background(fig_pf, _th, skip_uniformtext=True)
            # apply_gdrs_chart_background сбрасывает tickfont оси X — восстанавливаем крупные горизонтальные подписи проектов.
            _proj_xaxis_kw: dict[str, Any] = dict(
                tickfont=dict(size=_proj_x_tick_sz, color=_th.text, family="Inter, sans-serif"),
                tickangle=0,
                ticklabelstandoff=14,
                automargin=True,
            )
            if _bar_x_cfg:
                _proj_xaxis_kw.update(_bar_x_cfg)
            fig_pf.update_xaxes(**_proj_xaxis_kw)
            fig_pf.update_layout(margin=dict(l=56, r=24, t=88, b=_bar_margin_b))
            fig_pf = gdrs_apply_grouped_bar_labels(
                fig_pf,
                _th,
                _bar_x_labels,
                [
                    ([f"{v}" for v in _plan_vals], _th.bar_plan_text),
                    ([f"{v}" for v in _fact_vals], _th.bar_fact_text),
                    (_dev_text, _dev_colors),
                ],
            )
            fig_pf = _gdrs_apply_plan_fact_grouped_bar_spacing(
                fig_pf,
                len(_proj_labels),
                metrics_axis=_metrics_axis,
                fixed_slots=_fixed_bar_slots,
            )
            fig_pf = gdrs_apply_bottom_chart_legend(
                fig_pf, _th, min_margin_b=_bar_margin_b
            )
            _gdrs_st_plotly_chart(
                st,
                fig_pf,
                key=f"gdrs_proj_bar_{_gdrs_key_suffix}_{_plan_agg}_{_skud_agg}",
            )
        except Exception as _e:
            st.warning(f"Plotly недоступен: {_e}")
        _gdrs_render_plan_fact_summary_table(
            st,
            _gdrs_projects_summary_display(proj_df),
            table_title="ГДРС по выбранным проектам",
            theme=theme,
        )
    else:
        st.info("Нет данных по проектам.")

    st.markdown("---")
    _gdrs_render_contractors_pie_block(
        st,
        chart_df,
        unit_gen=_unit_gen,
        theme=theme,
        key_suffix=_gdrs_key_suffix,
    )

    _gdrs_tbl_name, _gdrs_tbl_dates = report_title_parts(
        f"ГДРС ({unit})",
        period_label,
        date_start=date_from,
        date_end=date_to,
    )
    gdrs_render_table_subheader(st, _gdrs_tbl_name, filters_suffix=_gdrs_tbl_dates, theme=theme)
    period_days = max(1, (date_to - date_from).days + 1)
    if period_days > 45:
        st.warning(
            f"Выбран период {period_days} дн.: в таблице отображаются только первые 6 ISO-недель "
            f"({date_from.strftime('%d.%m.%Y')} — {(date_from + _pd.Timedelta(days=42)).strftime('%d.%m.%Y')}); "
            f"неделя 7+ не помещается в макет ТЗ. Сократите период до месяца, чтобы увидеть все недели."
        )
    _show_week_cols = gdrs_matrix_show_week_columns(
        _plan_agg, _skud_agg, date_from=date_from, date_to=date_to
    )
    if _show_week_cols:
        st.caption(
            "Колонки «План / СКУД / Отклонение» — **среднее по неделям месяца** (только реальные недели: "
            f"{gdrs_matrix_week_count(date_from, date_to) or '—'} в выбранном периоде). "
            "Колонки «N нед» — календарные недели месяца (1–7, 8–14, …); "
            "план по неделе — срез 1С на последний день этой недели."
        )
    else:
        _wk_parts: list[str] = []
        _pwn = gdrs_agg_week_num(_plan_agg)
        _swn = gdrs_agg_week_num(_skud_agg)
        if _pwn is not None:
            _wk_parts.append(f"план — **{GDRS_AGG_LABELS.get(f'week:{_pwn}', f'{_pwn} неделя')}**")
        if _swn is not None:
            _wk_parts.append(f"СКУД — **{GDRS_AGG_LABELS.get(f'week:{_swn}', f'{_swn} неделя')}**")
        if _wk_parts:
            st.caption(
                "Колонки «План / СКУД / Отклонение» — данные **выбранной недели** "
                f"({', '.join(_wk_parts)}). "
                "СКУД = 0, если в resursi.csv нет факта за эту неделю."
            )
    view = main_t.copy()
    view["Контрагент"] = view.apply(
        lambda r: (
            r["project_name"] if r["row_kind"] == "subtotal"
            else ("Итого" if r["row_kind"] == "grand_total" else r["contractor_name"])
        ),
        axis=1,
    )
    if "vid_raboty" in view.columns:
        vid_col = view["vid_raboty"].fillna("").astype(str)
        view["Вид работ"] = [v if v.strip() else "—" for v in vid_col]
    else:
        view["Вид работ"] = view["contract_name"].fillna("").astype(str).apply(
            lambda s: s if s else "—"
        )
    view["План"] = view["plan"].fillna(0).round(0).astype(int)
    view["СКУД"] = view["skud"].fillna(0).round(0).astype(int)
    view["Отклонение"] = view["deviation"].round(0).astype(int)
    view["__kind__"] = view["row_kind"]
    view["_delta_pct_raw"] = view["delta_pct"]
    for _pk in ("p1", "p2", "p3", "p4", "p5", "p6"):
        if _pk in view.columns:
            view[_pk] = view[_pk].fillna(0).astype(int)
    for _wk in ("w1", "w2", "w3", "w4", "w5", "w6"):
        view[_wk] = view[_wk].fillna(0).astype(int)
    from dashboards.gdrs_resursi import render_gdrs_matrix_table_html
    _tbl_title = _gdrs_tbl_name
    _tbl_period = (
        _format_gdrs_month_year_title_ru(date_from, date_to, long_fact_period, None) or period_label
    )
    _week_ren = {
        "p1": "План 1 нед", "p2": "План 2 нед", "p3": "План 3 нед",
        "p4": "План 4 нед", "p5": "План 5 нед", "p6": "План 6 нед",
        "w1": "СКУД 1 нед", "w2": "СКУД 2 нед", "w3": "СКУД 3 нед",
        "w4": "СКУД 4 нед", "w5": "СКУД 5 нед", "w6": "СКУД 6 нед",
    }
    _mtx_drop = {
        "__kind__", "_delta_pct_raw", "row_kind", "project_name", "contractor_name",
        "contract_name", "vid_raboty", "plan", "skud", "deviation", "delta_pct",
    }
    _mtx_export = view.drop(columns=[c for c in view.columns if c in _mtx_drop], errors="ignore")
    _mtx_export = _mtx_export.rename(columns={k: v for k, v in _week_ren.items() if k in _mtx_export.columns})
    _week_hdr_labels = (
        gdrs_matrix_week_labels(date_from, date_to, long_fact_period["date"])
        if _show_week_cols
        else None
    )
    render_report_html_table(
        render_gdrs_matrix_table_html(
            view,
            fixed_cols=["Контрагент", "Вид работ", "План", "СКУД", "Отклонение"],
            delta_col="Отклонение %",
            kind_col="__kind__",
            title_line=_tbl_title,
            period_line=_tbl_period,
            delta_bg_style=lambda raw: _gdrs_delta_pct_cell_bg_style(raw, theme=theme),
            show_week_columns=_show_week_cols,
            week_labels=_week_hdr_labels,
            theme=theme,
        ),
        export_df=_mtx_export,
        file_stem=_export_file_stem(_tbl_title),
        key_prefix=f"gdrs_matrix_{abs(id(view))}",
    )
    try:
        _fact_aud, _plan_aud, _contract_aud = build_gdrs_audit_export_frames(
            long_fact_period,
            plan,
            dogovor_files,
            vid=sel_vid,
            date_from=date_from,
            date_to=date_to,
            plan_snapshot=_plan_snap,
            projects=sel_projects or None,
            contractors=sel_contractors or None,
        )
        from utils import render_dataframe_excel_csv_downloads

        with st.expander("Выгрузка CSV для проверки расчёта", expanded=False):
            st.caption(
                "Факт — строки СКУД из resursi.csv по текущим фильтрам; "
                "План (пары) — агрегат 1С на дату среза; "
                "План (договоры) — каждый договор из последнего Dogovor.json ≤ даты среза."
            )
            if _fact_aud is not None and not _fact_aud.empty:
                render_dataframe_excel_csv_downloads(
                    _fact_aud,
                    file_stem="gdrs_audit_fact_skud",
                    key_prefix=f"gdrs_audit_fact_{_gdrs_key_suffix}",
                    popover_label="СКУД (факт по дням)",
                    csv_label="СКУД (факт по дням, CSV)",
                )
            if _plan_aud is not None and not _plan_aud.empty:
                render_dataframe_excel_csv_downloads(
                    _plan_aud,
                    file_stem="gdrs_audit_plan_pairs",
                    key_prefix=f"gdrs_audit_plan_{_gdrs_key_suffix}",
                    popover_label="План по проект×контрагент",
                    csv_label="План по проект×контрагент (CSV)",
                )
            if _contract_aud is not None and not _contract_aud.empty:
                render_dataframe_excel_csv_downloads(
                    _contract_aud,
                    file_stem="gdrs_audit_plan_dogovor",
                    key_prefix=f"gdrs_audit_dog_{_gdrs_key_suffix}",
                    popover_label="План по договорам 1С",
                    csv_label="План по договорам 1С (CSV)",
                )
            if (
                (_fact_aud is None or _fact_aud.empty)
                and (_plan_aud is None or _plan_aud.empty)
                and (_contract_aud is None or _contract_aud.empty)
            ):
                st.info("Нет строк для выгрузки по текущим фильтрам.")
    except Exception as _aud_e:
        st.warning(f"Выгрузка для проверки: {_aud_e}")

    st.markdown("---")
    gdrs_render_subheader(st, "ГДРС по выбранным контрагентам", theme=theme)
    if chart_df.empty:
        st.info("Нет данных по контрагентам.")
    else:
        try:
            import plotly.graph_objects as _go
            _bar_axis_sz = 27 if theme == "light" else 18
            _ctr_labels = chart_df["Контрагент"].astype(str).tolist()
            _ctr_plan = chart_df["План"].fillna(0).astype(int).tolist()
            _ctr_fact = chart_df["Факт"].fillna(0).astype(int).tolist()
            _ctr_dev_text, _ctr_dev_colors, _ctr_dev_abs = [], [], []
            for _pv, _fv in zip(chart_df["План"], chart_df["Факт"]):
                _lbl, _col = gdrs_deviation_vs_plan_text_and_color(_pv, _fv, _th)
                _ctr_dev_text.append(_lbl)
                _ctr_dev_colors.append(_col)
                _ctr_dev_abs.append(abs(int(round(float(_fv) - float(_pv)))))
            fig2 = _go.Figure()
            _ctr_bar_x, _ctr_title_suffix, _ctr_x_cfg = _gdrs_add_plan_fact_deviation_traces(
                fig2,
                _ctr_labels,
                _ctr_plan,
                _ctr_fact,
                _ctr_dev_abs,
                _ctr_dev_colors,
                _th,
            )
            _ctr_metrics_axis = len(_ctr_labels) == 1
            _ctr_fixed_slots = _ctr_x_cfg is not None
            _ctr_tickangle, _bar_margin_b = _gdrs_grouped_bar_x_tick_settings(
                len(_ctr_labels),
                metrics_axis=_ctr_metrics_axis,
                light=(theme == "light"),
            )
            _ctr_xaxis_kw: dict[str, Any] = dict(
                tickangle=_ctr_tickangle,
                tickfont=dict(size=_bar_axis_sz, color=_th.text, family="Inter, system-ui, sans-serif"),
                automargin=True,
                ticklabelstandoff=10 if _ctr_tickangle == 0 else 6,
            )
            if _ctr_x_cfg:
                _ctr_xaxis_kw.update(_ctr_x_cfg)
            # Столбцы в 3× выше и шире: высокий холст + фикс. пиксельная ширина под
            # горизонтальный скролл (иначе use_container_width сжимает всё в экран).
            _bar_h = 1500 if theme == "light" else 1320
            fig2.update_layout(
                title=dict(text=f"План / Факт / Отклонение{_ctr_title_suffix}") if _ctr_title_suffix else {},
                barmode="group",
                plot_bgcolor=_th.chart_bg,
                paper_bgcolor=_th.chart_bg,
                font_color=_th.text,
                xaxis=_ctr_xaxis_kw,
                yaxis=dict(
                    tickfont=dict(size=_bar_axis_sz if theme == "light" else 16, color=_th.text),
                ),
                height=_bar_h,
                margin=dict(l=64, r=28, t=88, b=_bar_margin_b),
                showlegend=True,
            )
            fig2 = apply_gdrs_chart_background(fig2, _th, skip_uniformtext=True)
            fig2.update_xaxes(**_ctr_xaxis_kw)
            fig2.update_layout(margin=dict(l=64, r=28, t=88, b=_bar_margin_b))
            fig2 = gdrs_apply_grouped_bar_labels(
                fig2,
                _th,
                _ctr_bar_x,
                [
                    ([f"{int(v)}" for v in _ctr_plan], _th.bar_plan_text),
                    ([f"{int(v)}" for v in _ctr_fact], _th.bar_fact_text),
                    (_ctr_dev_text, _ctr_dev_colors),
                ],
            )
            fig2 = _gdrs_apply_plan_fact_grouped_bar_spacing(
                fig2,
                len(_ctr_labels),
                metrics_axis=_ctr_metrics_axis,
                fixed_slots=_ctr_fixed_slots,
            )
            fig2 = gdrs_apply_bottom_chart_legend(
                fig2, _th, min_margin_b=_bar_margin_b
            )
            # Крупнее подписи значений над столбцами.
            _bar_lbl_sz = 21 if theme == "light" else 16
            try:
                fig2.update_traces(
                    selector=dict(type="bar"),
                    textfont=dict(size=_bar_lbl_sz),
                    outsidetextfont=dict(size=_bar_lbl_sz),
                )
            except Exception:
                pass
            _n_ctr = max(1, len(_ctr_labels))
            if _n_ctr > 1:
                # ~3× ширины на слот категории → холст шире экрана, включаем скролл.
                _slot_px = 128 if theme == "light" else 116
                _canvas_w = max(1180, int(_n_ctr * _slot_px))
                _leg_items = [
                    ("План", _th.bar_plan),
                    ("Факт", _th.bar_fact),
                    ("Отклонение (факт − план)", getattr(_th, "neutral", _th.text)),
                ]
                _gdrs_render_bar_hscroll(
                    st,
                    fig2,
                    width_px=_canvas_w,
                    height_px=_bar_h,
                    theme=_th,
                    key=f"gdrs_ctr_bar_{_gdrs_key_suffix}_{_plan_agg}_{_skud_agg}",
                    legend_items=_leg_items,
                )
            else:
                _gdrs_st_plotly_chart(
                    st,
                    fig2,
                    key=f"gdrs_ctr_bar_{_gdrs_key_suffix}_{_plan_agg}_{_skud_agg}",
                )
        except Exception as _e:
            st.warning(f"Plotly недоступен: {_e}")

    st.markdown("---")
    if str(sel_vid).casefold() == "рабочие":
        _dyn_title = "Динамика людей"
    elif str(sel_vid).casefold() == "техника":
        _dyn_title = "Динамика техники"
    else:
        _dyn_title = "Динамика людей и техники"
    fact_dyn = long_fact_period.copy()
    fact_dyn = fact_dyn[fact_dyn["vid_resursa"].astype(str).str.casefold() == sel_vid.casefold()]
    if sel_projects:
        fact_dyn = fact_dyn[fact_dyn["project_name"].isin(sel_projects)]
    if sel_contractors:
        fact_dyn = fact_dyn[fact_dyn["contractor_name"].isin(sel_contractors)]
    plan_col = "plan_workers" if sel_vid.casefold() == "рабочие" else "plan_equipment"
    # Факта нет, но у подрядчика есть план → строим динамику плана по парам из главной
    # таблицы (иначе «Нет данных для графика динамики» при наличии плана вводит в заблуждение).
    _dyn_plan_pairs = None
    if fact_dyn.empty and main_t is not None and not main_t.empty:
        _dyn_detail = main_t[main_t["row_kind"] == "row"].copy()
        if not _dyn_detail.empty:
            _dyn_detail = _dyn_detail[
                pd.to_numeric(_dyn_detail["plan"], errors="coerce").fillna(0) > 0
            ]
        if not _dyn_detail.empty:
            _cols = ["project_id", "project_name", "contractor_id", "contractor_name"]
            for _c in _cols:
                if _c not in _dyn_detail.columns:
                    _dyn_detail[_c] = ""
            _dyn_plan_pairs = _dyn_detail[_cols].drop_duplicates()
    if fact_dyn.empty and (_dyn_plan_pairs is None or _dyn_plan_pairs.empty):
        st.info("Нет данных для графика динамики.")
    else:
        if not fact_dyn.empty:
            fact_dyn["date"] = _pd.to_datetime(fact_dyn["date"])
        if _pd.notna(date_from):
            _dyn_from = date_from.normalize()
        elif not fact_dyn.empty:
            _dyn_from = fact_dyn["date"].min().normalize()
        else:
            _dyn_from = _pd.Timestamp.today().normalize()
        if _pd.notna(date_to):
            _dyn_to = date_to.normalize()
        elif not fact_dyn.empty:
            _dyn_to = fact_dyn["date"].max().normalize()
        else:
            _dyn_to = _dyn_from
        _gdrs_dynamics_chart_panel(
            fact_dyn,
            _dyn_from.isoformat(),
            _dyn_to.isoformat(),
            _version_id,
            _db_mtime,
            plan_col,
            sel_vid,
            _dyn_title,
            vid_locked,
            month_periods=_sel_periods,
            term_index=_term_index,
            plan_agg=_plan_agg,
            skud_agg=_skud_agg,
            theme=theme,
            pairs_override=_dyn_plan_pairs,
        )

    st.markdown("---")
    # Полный список: план или факт (не только Факт>0 — иначе пропадают plan-only,
    # заказчик: при «все проекты» ожидает ~39, а не ~18 с фактом).
    _dist_src = chart_df[
        (pd.to_numeric(chart_df["План"], errors="coerce").fillna(0) > 0)
        | (pd.to_numeric(chart_df["Факт"], errors="coerce").fillna(0) > 0)
    ].copy()
    if _dist_src.empty:
        st.info("Нет данных для таблицы распределения.")
    else:
        _gdrs_render_plan_fact_summary_table(
            st,
            _gdrs_pie_distribution_display(_dist_src),
            table_title=f"Распределение {_unit_gen} по контрагентам",
            theme=theme,
        )


# ==================== DASHBOARD: Дебиторская и кредиторская задолженность подрядчиков ====================
def _find_col(df, names):
    """Поиск колонки по частичному совпадению (без учёта регистра)."""
    cols_lower = [str(c).lower().strip() for c in df.columns]
    for n in names:
        n_lower = n.lower().strip()
        for i, c in enumerate(cols_lower):
            if n_lower in c or c in n_lower:
                return df.columns[i]
    return None


_RE_UUID_PROJECT = re.compile(
    r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
)


def _is_uuid_like(val) -> bool:
    s = str(val or "").strip()
    return bool(s and _RE_UUID_PROJECT.match(s))


def _load_project_id_to_name_lookup() -> dict[str, str]:
    """ID_Проекта → Наименование_Проекта из projekts_json в БД."""
    try:
        from web_db_read import load_project_id_to_name_lookup

        return load_project_id_to_name_lookup()
    except Exception:
        return {}


def _find_project_display_col(df: pd.DataFrame) -> str | None:
    """Колонка с названием проекта (не id/guid)."""
    if df is None or getattr(df, "empty", True):
        return None
    preferred = (
        "project name",
        "наименование_проекта",
        "наименование проекта",
        "название проекта",
        "проект",
    )
    cols = list(df.columns)
    for cand in preferred:
        cl = cand.lower()
        for c in cols:
            sl = str(c).lower().strip().replace("_", " ")
            if sl == cl or cl in sl:
                if "id" in sl.replace(" ", "") and "наименование" not in sl and "название" not in sl:
                    continue
                return c
    return None


def _resolve_project_display_labels(series: pd.Series, lookup: dict[str, str]) -> pd.Series:
    """Подмена GUID проекта на наименование из справочника Projekts.json."""
    if series is None or lookup is None or not lookup:
        return series

    def _one(v):
        s = str(v or "").strip()
        if not s or s.lower() in ("nan", "none", "nat"):
            return ""
        if _is_uuid_like(s):
            return lookup.get(s.lower(), s)
        return s

    return series.map(_one)


def _to_num(series):
    """Приведение к числу (пробелы; запятая — десятичный или тысячный разделитель)."""
    s = (
        series.astype(str)
        .str.replace("\u00a0", "", regex=False)
        .str.replace(" ", "", regex=False)
        .str.strip()
    )
    # 11,700,000.00 — запятая как разделитель тысяч при наличии точки.
    _both_sep = s.str.contains(",") & s.str.contains(r"\.")
    s = s.where(~_both_sep, s.str.replace(",", "", regex=False))
    s = s.str.replace(",", ".", regex=False)
    return pd.to_numeric(s, errors="coerce").fillna(0)


def _ref_score_contractor_column(name: str) -> int:
    """Выбор колонки с наименованием контрагента в справочнике 1С (не ИНН/КПП)."""
    n = str(name).lower().replace("_", " ").strip()
    if "инн" in n or "кпп" in n:
        return -100
    if "наименование" not in n and n.startswith("id"):
        return -90
    sc = 0
    if "наименование" in n and "контрагент" in n:
        sc += 60
    if n in ("контрагент", "контрагенты", "название контрагента", "название контрагента"):
        sc += 55
    if "контрагент" in n and "договор" not in n:
        sc += 25
    if "организация" in n:
        sc += 10
    return sc


def _ref_score_project_column(name: str) -> int:
    n = str(name).lower().replace("_", " ").strip()
    sc = 0
    if "номенклатур" in n:
        sc -= 30
    if n == "проект":
        sc += 80
    if "проект" in n and "проектн" not in n:
        sc += 40
    if "id" in n and "проект" in n:
        sc += 15
    return sc


def _ref_pick_best_column(df: pd.DataFrame, scorer) -> str | None:
    best_c = None
    best_s = -10**9
    for c in df.columns:
        s = scorer(str(c))
        if s > best_s:
            best_s = s
            best_c = c
    return best_c if best_s > 0 else None


def _gdrs_score_spravochnik_plan_column(name: str) -> int:
    """Приоритизация колонки плановых показателей ГДРС в выгрузке 1С `spravochniki`."""
    n = str(name).lower().replace("_", " ").strip()
    if n in ("количествоработников", "количество работников"):
        return 95
    if n in ("количествоспецтехники", "количество спецтехники"):
        return 95
    if "инн" in n or "кпп" in n or "огрн" in n:
        return -100
    if n.startswith("id") and "план" not in n and "проект" not in n:
        return -20
    sc = 0
    if "план" in n:
        sc += 80
    for frag in ("гдр", "гдрс", "ресурс", "чел", "рабоч", "средн", "сутк"):
        if frag in n:
            sc += 20
    if "факт" in n or "отклон" in n or "дельт" in n:
        sc -= 45
    return sc


def _gdrs_pick_spravochnik_plan_column(ref: pd.DataFrame) -> str | None:
    if ref is None or getattr(ref, "empty", True):
        return None
    nrows = len(ref)
    best: str | None = None
    best_s = 0
    for c in ref.columns:
        s = _gdrs_score_spravochnik_plan_column(str(c))
        if s < 1:
            continue
        v = pd.to_numeric(ref[c], errors="coerce")
        if int(v.notna().sum()) < max(1, min(3, nrows // 20 if nrows else 1)):
            continue
        if s > best_s:
            best_s = s
            best = str(c)
    if best:
        return best
    for c in ref.columns:
        tl = str(c).strip().casefold()
        if tl in ("план", "plan", "плангдрс", "план_гдрс", "план гдрс"):
            v = pd.to_numeric(ref[c], errors="coerce")
            if v.notna().any():
                return str(c)
    return None


def _gdrs_spravochnik_ref_column(
    ref: pd.DataFrame, candidates: tuple[str, ...] | list[str]
) -> str | None:
    """
    Находит колонку в выгрузке 1С по точному имени, регистру или без подчёркиваний/пробелов
    (например, «КоличествоРаботники» / «количество_работников»).
    """
    if ref is None or getattr(ref, "empty", True):
        return None

    def _norm_name(s: str) -> str:
        return re.sub(r"[_\s]+", "", str(s).strip().casefold())

    want = {_norm_name(x) for x in candidates}
    for c in ref.columns:
        if _norm_name(c) in want:
            return str(c)
    for c in ref.columns:
        if str(c).strip() in candidates:
            return str(c)
    return None


def _gdrs_coalesce_plan_for_gdrs_table(pdf: pd.DataFrame, _to_num_fn) -> pd.Series:
    """
    План для референс-таблицы ГДРС: (1) колонка плана/кол-ва в договоре из resursi; (2) колонка «План»
    в выгрузке; (3) `План_numeric` после merge с 1С. Иначе пустой «План»/лишняя договорная колонка
    перетирали подставленный из `1c_*_spravochniki.json` план (по «технике» часто не воспроизводилось).
    """
    if pdf is None or pdf.empty:
        return pd.Series(dtype="float64")
    idx = pdf.index
    pn = (
        pd.to_numeric(pdf.get("План_numeric"), errors="coerce").fillna(0.0)
        if "План_numeric" in pdf.columns
        else pd.Series(0.0, index=idx)
    )
    c_contract = None
    for c in pdf.columns:
        cl = str(c).lower()
        if "договор" in cl and ("план" in cl or "колич" in cl):
            c_contract = c
            break
    c_plan = _gdrs_resolve_plan_column(pdf)
    fc = (
        _to_num_fn(pdf[c_contract])
        if c_contract and c_contract in pdf.columns
        else pd.Series(0.0, index=idx)
    )
    if c_plan and c_plan in pdf.columns:
        fp = _to_num_fn(pdf[c_plan])
    else:
        fp = pd.Series(0.0, index=idx)
    fcv = fc.to_numpy(dtype="float64", copy=False)
    fpv = fp.to_numpy(dtype="float64", copy=False)
    pnv = pn.to_numpy(dtype="float64", copy=False)
    out = np.zeros(len(pdf), dtype="float64")
    for i in range(len(pdf)):
        if abs(fcv[i]) > 1e-9:
            out[i] = fcv[i]
        elif abs(fpv[i]) > 1e-9:
            out[i] = fpv[i]
        else:
            out[i] = pnv[i]
    return pd.Series(out, index=idx)


def _gdrs_work_row_uses_tech(
    out: pd.DataFrame, i, data_source_filter: Optional[str]
) -> bool:
    """Строка факта — техника (иначе рабочие/люди) для выбора плановой колонки 1С."""
    if "тип ресурсов" in out.columns:
        t = str(out.at[i, "тип ресурсов"] or "").lower()
        if "тех" in t:
            return True
        if "рабоч" in t:
            return False
    dsf = (data_source_filter or "").strip().casefold()
    if dsf == "техника":
        return True
    if dsf == "ресурсы":
        return False
    if "data_source" in out.columns:
        ds = str(out.at[i, "data_source"] or "").strip().casefold()
        if ds in ("техника", "tech", "technique"):
            return True
    return False


def _gdrs_merge_plan_from_1c_spravochniki(
    work_df: pd.DataFrame,
    ref_df: Optional[pd.DataFrame],
    data_source_filter: Optional[str] = None,
) -> pd.DataFrame:
    """
    Подставляет план в «План_numeric»/«План» из `st.session_state['reference_contractors']`
    (файл `1c_*_spravochniki.json`), если в resursi план 0. В выгрузке 1С: `КоличествоРаботников`
    (план на период для людей) и `КоличествоСпецТехники` (для техники) при наличии в JSON.
    Ключ: норм. имя подрядчика; при `Наименование_Проекта` (справочник) и «Проект» (факт) — пара (контрагент+проект).
    """
    from utils import norm_partner_join_key

    out = work_df.copy()
    if ref_df is None or getattr(ref_df, "empty", True) or out is None or out.empty:
        return out
    if "Контрагент" not in out.columns or "План_numeric" not in out.columns:
        return out
    ref = ref_df.copy()
    ref.columns = [str(c).strip() for c in ref.columns]
    col_people = _gdrs_spravochnik_ref_column(
        ref,
        (
            "КоличествоРаботников",
            "Количество_Работников",
            "Количество работников",
        ),
    )
    col_tech = _gdrs_spravochnik_ref_column(
        ref,
        (
            "КоличествоСпецТехники",
            "Количество_СпецТехники",
            "Количество спецтехники",
            "Количество спец. техники",
        ),
    )
    plan_c_generic = None
    if not col_people and not col_tech:
        plan_c_generic = _gdrs_pick_spravochnik_plan_column(ref)
        if not plan_c_generic or plan_c_generic not in ref.columns:
            return out
    cont_c = _ref_pick_best_column(ref, _ref_score_contractor_column)
    if not cont_c:
        for nm in (
            "Наименование_Контрагента",
            "Наименование Контрагента",
            "Контрагент",
            "Подрядчик",
            "подрядчик",
        ):
            if nm in ref.columns:
                cont_c = nm
                break
    if not cont_c or cont_c not in ref.columns:
        return out
    proj_c_r = _ref_pick_best_column(ref, _ref_score_project_column)
    for nm in ("Наименование_Проекта", "ID_Проекта"):
        if not proj_c_r and nm in ref.columns:
            proj_c_r = nm
            break
    proj_c_w = None
    for nm in ("Проект", "проект", "project name"):
        if nm in out.columns:
            proj_c_w = nm
            break
    if proj_c_w is None:
        for c in out.columns:
            if str(c).lower().replace("_", " ").strip() == "проект":
                proj_c_w = c
                break

    def _gdrs_scalar_ref_float(cell) -> float | None:
        if cell is None:
            return None
        if isinstance(cell, (list, dict, np.ndarray)):
            return None
        v = float(pd.to_numeric(cell, errors="coerce"))
        if not np.isfinite(v):
            return None
        return v

    def _parse_ref_dt(v):
        ts = pd.to_datetime(v, errors="coerce", dayfirst=True)
        if pd.isna(ts):
            return None
        if getattr(ts, "tzinfo", None) is not None:
            ts = ts.tz_localize(None)
        return ts

    date_end_col = _gdrs_spravochnik_ref_column(
        ref,
        (
            "Дата_Окончания_Договора",
            "Дата Окончания Договора",
            "ДатаОкончанияДоговора",
            "Дата_Окончания",
        ),
    )

    def _gdrs_plan_specs_from_spravochnik_cell(cell) -> tuple[float | None, list[tuple[pd.Timestamp, float]]]:
        """
        Нормализует план из 1С:
        - scalar: число без явной даты;
        - timeline: массив [{Дата, Количество}, ...], сортированный по дате.
        """
        if cell is None:
            return (None, [])
        if isinstance(cell, dict):
            q = cell.get("Количество") if "Количество" in cell else cell.get("количество")
            dt_raw = cell.get("Дата") if "Дата" in cell else cell.get("дата")
            w = float(pd.to_numeric(q, errors="coerce"))
            if not np.isfinite(w):
                return (None, [])
            dt = _parse_ref_dt(dt_raw)
            if dt is not None:
                return (None, [(dt, float(w))])
            return (float(w), [])
        if isinstance(cell, (list, tuple)) and len(cell) > 0:
            timeline: list[tuple[pd.Timestamp, float]] = []
            nums: list[float] = []
            for it in cell:
                if isinstance(it, dict):
                    q = it.get("Количество") if "Количество" in it else it.get("количество")
                    dt_raw = it.get("Дата") if "Дата" in it else it.get("дата")
                    w = float(pd.to_numeric(q, errors="coerce"))
                    if not np.isfinite(w):
                        continue
                    dt = _parse_ref_dt(dt_raw)
                    if dt is not None:
                        timeline.append((dt, float(w)))
                    else:
                        nums.append(float(w))
                else:
                    w = float(pd.to_numeric(it, errors="coerce"))
                    if np.isfinite(w):
                        nums.append(float(w))
            if timeline:
                timeline.sort(key=lambda x: x[0])
                return (None, timeline)
            if nums:
                return (float(max(nums)), [])
            return (None, [])
        return (_gdrs_scalar_ref_float(cell), [])

    def _period_bounds(row_period) -> tuple[pd.Timestamp | None, pd.Timestamp | None]:
        if isinstance(row_period, pd.Period):
            return (row_period.start_time, row_period.end_time)
        ts = pd.to_datetime(row_period, errors="coerce", dayfirst=True)
        if pd.isna(ts):
            return (None, None)
        if getattr(ts, "tzinfo", None) is not None:
            ts = ts.tz_localize(None)
        # Для дат/таймстемпов в периоде используем границы месяца.
        p = ts.to_period("M")
        return (p.start_time, p.end_time)

    def _pick_plan_for_period(
        specs: list[tuple[float | None, list[tuple[pd.Timestamp, float]], pd.Timestamp | None]],
        period_start: pd.Timestamp | None,
        period_end: pd.Timestamp | None,
    ) -> float | None:
        vals: list[float] = []
        for scalar_v, timeline, contract_end in specs:
            if contract_end is not None and period_start is not None and period_start > contract_end:
                continue
            if timeline:
                if period_end is not None:
                    active = [v for d, v in timeline if d <= period_end]
                    if active:
                        vals.append(float(active[-1]))
                else:
                    vals.append(float(timeline[-1][1]))
                continue
            if scalar_v is not None:
                vals.append(float(scalar_v))
        if not vals:
            return None
        return float(max(vals))

    def _one_map(
        plan_col: str,
    ) -> tuple[
        dict[tuple[str, str], list[tuple[float | None, list[tuple[pd.Timestamp, float]], pd.Timestamp | None]]],
        dict[str, list[tuple[float | None, list[tuple[pd.Timestamp, float]], pd.Timestamp | None]]],
    ]:
        by_cp: dict[
            tuple[str, str], list[tuple[float | None, list[tuple[pd.Timestamp, float]], pd.Timestamp | None]]
        ] = {}
        by_c: dict[str, list[tuple[float | None, list[tuple[pd.Timestamp, float]], pd.Timestamp | None]]] = {}
        for _, r in ref.iterrows():
            k = norm_partner_join_key(r.get(cont_c, ""))
            if not k:
                continue
            raw = r.get(plan_col, np.nan)
            scalar_v, timeline = _gdrs_plan_specs_from_spravochnik_cell(raw)
            if scalar_v is None and not timeline:
                continue
            contract_end = _parse_ref_dt(r.get(date_end_col, None)) if date_end_col else None
            spec = (scalar_v, timeline, contract_end)
            if proj_c_r and str(proj_c_r) in ref.columns and proj_c_w and str(proj_c_w) in out.columns:
                pk = _project_filter_norm_key(r.get(proj_c_r, ""))
                if pk:
                    by_cp.setdefault((k, pk), []).append(spec)
            by_c.setdefault(k, []).append(spec)
        return by_cp, by_c

    maps: dict[str, tuple[dict, dict] | None] = {}
    if col_people:
        maps["people"] = _one_map(col_people)
    if col_tech:
        maps["tech"] = _one_map(col_tech)
    if plan_c_generic:
        maps["generic"] = _one_map(plan_c_generic)

    n_fill = 0
    for i in out.index:
        try:
            cur = float(out.at[i, "План_numeric"])
        except (TypeError, ValueError):
            cur = 0.0
        if cur > 0:
            continue
        k = norm_partner_join_key(out.at[i, "Контрагент"])
        if not k:
            continue
        use_tech = _gdrs_work_row_uses_tech(out, i, data_source_filter)
        mkey = "tech" if use_tech else "people"
        if mkey not in maps and "generic" in maps:
            mkey = "generic"
        if mkey not in maps or maps[mkey] is None:
            continue
        by_cp, by_c = maps[mkey]
        period_start, period_end = _period_bounds(out.at[i, "Период"] if "Период" in out.columns else None)
        pick = None
        if (
            proj_c_r
            and str(proj_c_r) in ref.columns
            and proj_c_w
            and str(proj_c_w) in out.columns
        ):
            pk = _project_filter_norm_key(out.at[i, proj_c_w])
            if pk and (k, pk) in by_cp:
                pick = _pick_plan_for_period(by_cp[(k, pk)], period_start, period_end)
        if pick is None and k in by_c:
            pick = _pick_plan_for_period(by_c[k], period_start, period_end)
        if pick is not None and pick > 0:
            out.at[i, "План_numeric"] = pick
            n_fill += 1
    if n_fill:
        out["План"] = out["План_numeric"]
    return out


def _dc_is_dk_summary_row(
    row: pd.Series,
    *,
    contractor_col: str | None,
    contract_col: str | None,
    extract_partner_name,
    extract_partner_id,
) -> bool:
    """Итоговая строка DK без контрагента и договора (даёт «пустой» столбец на графике)."""
    keys: list[str] = []
    if contractor_col and contractor_col in row.index:
        keys.append(str(extract_partner_name(row.get(contractor_col)) or "").strip())
        keys.append(str(extract_partner_id(row.get(contractor_col)) or "").strip())
    if contract_col and contract_col in row.index:
        keys.append(str(row.get(contract_col, "") or "").strip())
    if "_id_dogovor_norm" in row.index:
        keys.append(str(row.get("_id_dogovor_norm", "") or "").strip())
    for _idc in ("ID_Контрагента", "Контрагент_ID_Контрагента", "Контрагент.ID_Контрагента"):
        if _idc in row.index:
            keys.append(str(row.get(_idc, "") or "").strip().lower())
            break
    for k in keys:
        if k and k.lower() not in ("nan", "none", "nat", "<na>"):
            return False
    return True


def _dc_partner_brand_key(name: str) -> str:
    """Ключ «семейства» контрагента (ИС ЕСИПОВО 5 / ИС ЕСИПОВО → одна группа)."""
    k = norm_partner_join_key(name)
    if not k:
        return k
    m = re.search(r"\b(ис\s+есипово)\b", k)
    if m:
        return m.group(1)
    return k


def _dc_merge_chart_rows_by_partner_key(
    chart_df: pd.DataFrame, chart_label: str, value_cols: list[str]
) -> pd.DataFrame:
    """Один столбец на контрагента: объединение вариантов написания по norm_partner_join_key."""
    if chart_df is None or chart_df.empty or chart_label not in chart_df.columns:
        return chart_df
    out = chart_df.copy()
    out[chart_label] = out[chart_label].astype(str).str.strip()
    out["_dk_join_key"] = out[chart_label].map(_dc_partner_brand_key)
    _empty_key = out["_dk_join_key"].astype(str).str.len().eq(0)
    if _empty_key.any():
        out = out.loc[~_empty_key].copy()
    if out.empty:
        return out
    _num_cols = [c for c in value_cols if c in out.columns]
    _label_by_key = (
        out.groupby("_dk_join_key", as_index=True)[chart_label]
        .agg(lambda s: max(s, key=lambda x: (len(str(x)), str(x).casefold())))
    )
    grouped = out.groupby("_dk_join_key", as_index=False)[_num_cols].sum()
    grouped[chart_label] = grouped["_dk_join_key"].map(_label_by_key)
    return grouped.drop(columns=["_dk_join_key"], errors="ignore")


def _dc_apply_orphan_advances_to_chart(
    chart_df: pd.DataFrame,
    chart_label: str,
    orphan_totals: dict[str, float],
    *,
    advance_col_name: str = "Аванс",
    ks2_col_name: str = "КС-2",
) -> pd.DataFrame:
    """
    Аванс из итоговой строки DK (отдельный «пустой» столбец) переносим в стек
    контрагента с max КС-2 — чтобы серый/жёлтый/синий были в одном столбце.
    """
    if chart_df is None or chart_df.empty or chart_label not in chart_df.columns:
        return chart_df
    _orph_adv = float(orphan_totals.get(advance_col_name, 0.0) or 0.0)
    if _orph_adv <= 1e-6 or ks2_col_name not in chart_df.columns:
        return chart_df
    out = chart_df.copy()
    _ks2 = pd.to_numeric(out[ks2_col_name], errors="coerce").fillna(0.0)
    if not (_ks2 > 1e-6).any():
        return out
    _adv = (
        pd.to_numeric(out[advance_col_name], errors="coerce").fillna(0.0)
        if advance_col_name in out.columns
        else pd.Series(0.0, index=out.index)
    )
    # Приоритет: «ис есипово», иначе max КС-2 при нулевом авансе на строке.
    _brand_keys = out[chart_label].map(_dc_partner_brand_key)
    _pick_idx = None
    _esipovo = _brand_keys.eq("ис есипово") & (_ks2 > 1e-6)
    if _esipovo.any():
        _pick_idx = _ks2.loc[_esipovo].idxmax()
    else:
        _candidates = out.index[_adv.abs() <= 1e-6]
        if len(_candidates):
            _pick_idx = _ks2.loc[_candidates].idxmax()
        else:
            _pick_idx = _ks2.idxmax()
    if advance_col_name not in out.columns:
        out[advance_col_name] = 0.0
    out.at[_pick_idx, advance_col_name] = float(out.at[_pick_idx, advance_col_name]) + _orph_adv
    if "Отклонение" in out.columns and ks2_col_name in out.columns:
        out["Отклонение"] = (
            pd.to_numeric(out[ks2_col_name], errors="coerce").fillna(0.0)
            - pd.to_numeric(out[advance_col_name], errors="coerce").fillna(0.0)
        )
    return out


def _dc_read_orphan_advance_mln(work: pd.DataFrame, *, advance_num_col: str | None) -> float:
    """Аванс из итоговой строки DK (отфильтрован в web_loader, сохранён в attrs/session)."""
    _rub = 0.0
    try:
        _rub = float(getattr(work, "attrs", {}).get("dk_summary_advance_rub", 0) or 0)
    except (TypeError, ValueError):
        _rub = 0.0
    if _rub <= 1e-6:
        try:
            _rub = float(st.session_state.get("dk_summary_advance_rub", 0) or 0)
        except (TypeError, ValueError):
            _rub = 0.0
    if _rub <= 1e-6 and advance_num_col and advance_num_col in work.columns:
        _summary_mask = work.index.to_series().map(lambda _i: False)
        try:
            _summary_mask = work.apply(
                lambda r: _dc_is_dk_summary_row(
                    r,
                    contractor_col=None,
                    contract_col=None,
                    extract_partner_name=lambda v: str(v or "").strip(),
                    extract_partner_id=lambda v: "",
                ),
                axis=1,
            )
        except Exception:
            pass
        if _summary_mask.any():
            _rub = float(work.loc[_summary_mask, advance_num_col].sum())
    if _rub <= 1e-6:
        try:
            import glob
            import json as _json
            import os as _os
            from pathlib import Path as _Path

            _web = _Path(__file__).resolve().parent.parent / "web"
            for _fp in sorted(_web.glob("1*DK*.json"), key=_os.path.getmtime, reverse=True)[:5]:
                try:
                    _raw = _json.loads(_fp.read_text(encoding="utf-8-sig"))
                except Exception:
                    continue
                if not isinstance(_raw, list):
                    continue
                _tot = 0.0
                for _item in _raw:
                    if not isinstance(_item, dict):
                        continue
                    _contr = _item.get("Контрагент") or {}
                    _dog = _item.get("Договор") or {}
                    _org = _item.get("Организация") or {}
                    _hc = bool(
                        isinstance(_contr, dict)
                        and (
                            str(_contr.get("НаименованиеКонтрагента", "") or "").strip()
                            or str(_contr.get("ID_Контрагента", "") or "").strip()
                        )
                    )
                    _hd = bool(
                        isinstance(_dog, dict)
                        and (
                            str(_dog.get("ID_Договора", "") or "").strip()
                            or str(_dog.get("НомерДоговора", "") or "").strip()
                        )
                    )
                    _ho = bool(
                        isinstance(_org, dict)
                        and str(_org.get("ID_Организации", "") or "").strip()
                    )
                    if not _hc and not _hd and not _ho:
                        try:
                            _tot += float(_item.get("ОстатокНаКонецПериодаПоАвансам", 0) or 0)
                        except (TypeError, ValueError):
                            pass
                if _tot > 1e-6:
                    _rub = _tot
                    break
        except Exception:
            pass
    return _rub / 1e6


def _dc_advance_semaphore_level(delta, contract_mln) -> str:
    """Уровень индикатора авансирования: green | yellow | red | пусто."""
    try:
        p = float(contract_mln) if pd.notna(contract_mln) else 0.0
        d = float(delta) if pd.notna(delta) else 0.0
    except (TypeError, ValueError):
        return ""
    if p <= 0:
        return "green" if d <= 0 else "red"
    if d <= 0:
        return "green"
    ratio = d / p
    if ratio <= 0.30:
        return "green"
    if ratio < 0.80:
        return "yellow"
    return "red"


def _dc_advance_semaphore_ball(level: str) -> str:
    return {"green": "🟢", "yellow": "🟡", "red": "🔴"}.get(str(level or "").strip(), "")


def _dc_advance_assumption_label(delta, contract_mln, level: str) -> str:
    """Индикатор + доля (Аванс − КС-2) от стоимости договора."""
    ball = _dc_advance_semaphore_ball(level)
    if not ball:
        return ""
    try:
        p = float(contract_mln) if pd.notna(contract_mln) else 0.0
        d = float(delta) if pd.notna(delta) else 0.0
    except (TypeError, ValueError):
        return ball
    if p <= 0:
        return f"{ball} 0.0%" if d <= 0 else f"{ball} —"
    pct = d / p * 100.0
    return f"{ball} {pct:.1f}%"


def _dc_advance_semaphore_bg(level: str, *, light: bool = False) -> str:
    if level == "green":
        return "rgba(34,197,94,0.28)" if light else "rgba(70,214,138,0.35)"
    if level == "yellow":
        return "rgba(234,179,8,0.35)" if light else "rgba(241,196,15,0.32)"
    if level == "red":
        return "rgba(248,113,113,0.35)" if light else "rgba(255,84,84,0.32)"
    return ""


def _render_dc_advance_semaphore_legend(st) -> None:
    """Легенда цветовых индикаторов «Допущения по авансированию %»."""
    try:
        from dashboards.light_theme import is_light_preview_active

        _light = is_light_preview_active()
    except Exception:
        _light = False
    _fg = "#334155" if _light else "rgba(232,238,245,0.92)"
    _sub = "#64748b" if _light else "rgba(232,238,245,0.72)"
    st.markdown(
        f'<div class="dc-adv-legend" style="margin:0.65em 0 0;font-size:13px;color:{_fg};">'
        f'<strong>Цветовые индикаторы (Аванс − КС-2):</strong> '
        f'🟢 ≤ 0 или &gt; 0, но ≤ 30% стоимости договора • '
        f'🟡 &gt; 30% и &lt; 80% стоимости договора • '
        f'🔴 ≥ 80% стоимости договора'
        f'<div style="margin-top:0.35em;color:{_sub};font-size:12px;">'
        f'Колонки «Допущения по авансированию %» и «Аванс − КС-2»: заливка ячейки по тем же порогам; '
        f'при нулевой стоимости договора — 🟢 0.0% или 🔴 —.</div></div>',
        unsafe_allow_html=True,
    )


def dashboard_debit_credit(df):
    """Дебиторская и кредиторская задолженность подрядчиков: график и таблица по данным из файла."""

    # КС-2 берётся из оборотов 1С (reference_1c_dannye). В отличие от БДДС/прогноза
    # этот дашборд раньше только читал session_state, поэтому при rerun/навигации
    # КС-2 «пропадал» (есть до переключения вида, нет — после). Бутстрапим референс
    # на каждом рендере, как это делают БДДС и «Прогнозный бюджет».
    try:
        from dashboards.finance_from_1c import resolve_reference_1c_dannye

        _dk_ref_boot = resolve_reference_1c_dannye()
        if _dk_ref_boot is not None and not getattr(_dk_ref_boot, "empty", True):
            st.session_state["reference_1c_dannye"] = _dk_ref_boot
    except Exception:
        pass

    data = st.session_state.get("debit_credit_data", None)
    if (data is None or data.empty) and (df is not None and not df.empty):
        data = df
    if data is None or data.empty:
        st.warning(
            "Для отчёта загрузите файл с данными по дебиторской/кредиторской задолженности. "
            "Ожидаемые колонки: подрядчик (название организации), тип подрядчика, договор, сумма в договоре, выплачено, аванс, остаток на конец периода."
        )
        return

    work = data.copy()
    work.columns = [str(c).strip() for c in work.columns]

    def _dc_clean_project_val(v) -> str:
        s = str(v or "").strip()
        if not s or s.lower() in ("nan", "none", "nat", "<na>"):
            return ""
        return s

    contractor_col = _find_col(work, ["Название контрагента", "Название организации", "подрядчик", "Подрядчик", "contractor", "Организация"])
    project_col = _find_project_display_col(work) or _find_col(
        work,
        [
            "project name",
            "Наименование_Проекта",
            "Проект",
            "проект",
            "Project",
            "название проекта",
        ],
    )
    project_from_reference = False
    if (not project_col or project_col not in work.columns) and contractor_col:
        keymap_from_ref = {}
        ref_df = st.session_state.get("reference_contractors")
        if ref_df is not None and not getattr(ref_df, "empty", True):
            ref_df = ref_df.copy()
            ref_df.columns = [str(c).strip() for c in ref_df.columns]
            rc = _ref_pick_best_column(ref_df, _ref_score_contractor_column) or _find_col(
                ref_df,
                [
                    "Наименование_Контрагента",
                    "Наименование Контрагента",
                    "Подрядчик",
                    "Контрагент",
                    "контрагент",
                    "организация",
                    "партнёр",
                    "Partner",
                    "Название контрагента",
                    "Название организации",
                    "Наименование контрагента",
                    "Наименование",
                    "полное наименование",
                    "Контрагент (полное наименование)",
                    "Наименование для печати",
                    "name",
                ],
            )
            rp = _ref_pick_best_column(ref_df, _ref_score_project_column) or _find_col(
                ref_df,
                [
                    "Проект",
                    "project name",
                    "ID проекта",
                    "проект",
                    "название проекта",
                    "код проекта",
                    "проект (id)",
                    "идентификатор проекта",
                ],
            )
            if rc and rp and rc in ref_df.columns and rp in ref_df.columns:
                for _, rr in ref_df.iterrows():
                    k = norm_partner_join_key(rr.get(rc, ""))
                    if k:
                        keymap_from_ref[k] = str(rr.get(rp, "")).strip()

        pmap = st.session_state.get("reference_partner_to_project") or {}
        merged = dict(pmap)
        merged.update(keymap_from_ref)

        if merged:
            work["_project_mapped"] = work[contractor_col].map(
                lambda x: merged.get(norm_partner_join_key(x), "")
            )
            if work["_project_mapped"].map(_dc_clean_project_val).ne("").any():
                project_col = "_project_mapped"
                project_from_reference = True
    _proj_name_lookup: dict[str, str] = {}
    try:
        _proj_name_lookup = _load_project_id_to_name_lookup()
    except Exception:
        _proj_name_lookup = {}
    if project_col and project_col in work.columns and _proj_name_lookup:
        work[project_col] = _resolve_project_display_labels(work[project_col], _proj_name_lookup)

    contract_col = _find_col(work, ["Номер договора", "Договор", "договор", "contract"])
    # Q15 (08.05.2026): «Сумма договора» — заказчик подтвердил, что лежит в справочнике
    # JSON. В выгрузке DK.json структура содержит вложенный объект `Договор.СуммаДоговора`,
    # после flatten в work колонка может называться `Договор_СуммаДоговора` /
    # `СуммаДоговора` / `Договор.СуммаДоговора` — расширяем кандидатов.
    total_col = _find_col(
        work,
        [
            "Сумма в договоре",
            "сумма в договоре",
            "Общая сумма",
            "contract sum",
            "Сумма_Договора",
            "СуммаДоговора",
            "Договор_СуммаДоговора",
            "Договор.СуммаДоговора",
            "Сумма договора",
            "СуммаПоДоговору",
            "Сумма по договору",
        ],
    )
    # Если в DK ничего похожего нет — подтягиваем сумму из 1с_*_Dogovor.json
    # по `ID_Договора` (Q15).
    id_dog_col = _find_col(
        work,
        [
            "ID_Договора",
            "Договор_ID_Договора",
            "Договор.ID_Договора",
            "ID_Dogovor",
            "1C_ID_DOG",
        ],
    )
    # Загружаем lookup из Dogovor.json (используется для суммы и для проекта).
    _dog_lookup_dc: dict = {}
    try:
        _dog_lookup_dc = _load_dogovor_lookup() or {}
    except Exception:
        _dog_lookup_dc = {}

    # Правки куратора 08.05.2026: в DK поле «Договор» хранится словарём
    # {id_договора, наименованиедоговора}, отдельной колонки ID_Договора может
    # не быть. Универсально извлекаем guid договора из dict/строки/colonok.
    _re_uuid = re.compile(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}")

    def _extract_dogovor_id(v) -> str:
        if v is None:
            return ""
        if isinstance(v, dict):
            for k in ("id_договора", "ID_Договора", "id_dogovora", "id", "ID"):
                if k in v and v[k]:
                    return str(v[k]).strip().lower()
            return ""
        s = str(v)
        m = re.search(r"id_договора\s*[:=]\s*([0-9a-fA-F\-]+)", s, flags=re.IGNORECASE)
        if m:
            return m.group(1).strip().lower()
        m2 = _re_uuid.search(s)
        if m2:
            return m2.group(0).strip().lower()
        return ""

    # Гарантируем нормализованную колонку id договора.
    work["_id_dogovor_norm"] = ""
    _candidate_id_cols = [
        c for c in (id_dog_col, contract_col, "Договор", "Договор_ID_Договора", "ID_Договора")
        if c and c in work.columns
    ]
    for _cc in _candidate_id_cols:
        try:
            _vals = work[_cc].map(_extract_dogovor_id)
            mask_empty = work["_id_dogovor_norm"].astype(str).str.len() == 0
            work.loc[mask_empty, "_id_dogovor_norm"] = _vals[mask_empty]
        except Exception:
            pass

    if (not total_col) and _dog_lookup_dc:
        def _resolve_summa(v):
            if v is None or (isinstance(v, float) and pd.isna(v)):
                return None
            rec = _dog_lookup_dc.get(str(v).strip().lower())
            if not rec:
                return None
            return rec.get("Сумма_Договора")
        work["_summa_dogovora_lookup"] = work["_id_dogovor_norm"].map(_resolve_summa)
        if work["_summa_dogovora_lookup"].notna().any():
            total_col = "_summa_dogovora_lookup"

    _dog_num_to_summa: dict[str, float] = {}
    if _dog_lookup_dc:
        for _rec in (_dog_lookup_dc or {}).values():
            _nk = _contract_no_search_key(_rec.get("Номер_Договора"))
            try:
                _fv = float(_rec.get("Сумма_Договора") or 0)
            except (TypeError, ValueError):
                _fv = 0.0
            if _nk and _fv > 0:
                _dog_num_to_summa[_nk] = max(_dog_num_to_summa.get(_nk, 0.0), _fv)
        if total_col and total_col != "_summa_dogovora_lookup":

            def _resolve_summa_guid(v):
                if v is None or (isinstance(v, float) and pd.isna(v)):
                    return None
                rec = _dog_lookup_dc.get(str(v).strip().lower())
                if not rec:
                    return None
                return rec.get("Сумма_Договора")

            work["_summa_dogovora_lookup"] = work["_id_dogovor_norm"].map(_resolve_summa_guid)

    # «Проект» подтягиваем каскадом:
    #   1) Dogovor.json по guid договора → Наименование_Проекта
    #   2) reference_partner_to_project по ID_Контрагента / имени контрагента
    #      (карта строится из 1С dannye группировкой по проекту)
    # В DK контрагент хранится словарём — извлекаем id/имя.
    def _extract_partner_name(v) -> str:
        if v is None:
            return ""
        if isinstance(v, dict):
            for k in ("наименованиеконтрагента", "НаименованиеКонтрагента", "Наименование_Контрагента", "Контрагент", "name"):
                if k in v and v[k]:
                    return str(v[k]).strip()
            return ""
        s = str(v)
        m = re.search(r"наименованиеконтрагента\s*[:=]\s*([^,}]+)", s, flags=re.IGNORECASE)
        if m:
            return m.group(1).strip().strip("'\"")
        return s.strip()

    def _extract_partner_id_local(v) -> str:
        if v is None:
            return ""
        if isinstance(v, dict):
            for k in ("id_контрагента", "ID_Контрагента", "id_kontragenta", "id", "ID"):
                if k in v and v[k]:
                    return str(v[k]).strip().lower()
            return ""
        s = str(v)
        m = re.search(r"id_контрагента\s*[:=]\s*([0-9a-fA-F\-]+)", s, flags=re.IGNORECASE)
        if m:
            return m.group(1).strip().lower()
        m2 = _re_uuid.search(s)
        if m2:
            return m2.group(0).strip().lower()
        return ""

    def _dc_project_col_has_data(col) -> bool:
        if not col or col not in work.columns:
            return False
        return work[col].map(_dc_clean_project_val).ne("").any()

    def _dc_project_col_has_empty_rows(col) -> bool:
        """True, если колонки нет или есть хотя бы одна строка с пустым проектом.

        Раньше каскад догрузки проекта запускался только когда колонка пуста
        целиком (`not .any()`). Из-за этого при одной заполненной строке весь
        каскад пропускался, а остальные строки оставались без проекта.
        """
        if not col or col not in work.columns:
            return True
        return work[col].map(_dc_clean_project_val).eq("").any()

    def _dc_project_from_contract_text(text, known_names: list[str]) -> str:
        raw = str(text or "")
        low = raw.casefold().replace("ё", "е")
        for name in sorted(known_names, key=len, reverse=True):
            nlow = name.casefold().replace("ё", "е")
            if nlow in low:
                return name
            ncompact = re.sub(r"[\s\-]+", "", nlow)
            if ncompact and ncompact in re.sub(r"[\s\-]+", "", low):
                return name
        m = re.search(r"есипово[\s\-]*(\d+)", low)
        if m:
            return f"Есипово-{m.group(1)}"
        m = re.search(r"дмитровский[\s\-]*(\d+)", low)
        if m:
            return f"Дмитровский-{m.group(1)}"
        if "ленинский" in low:
            return "Ленинский"
        return ""

    _known_project_names = sorted(
        {str(v).strip() for v in (_proj_name_lookup or {}).values() if _dc_clean_project_val(v)},
        key=len,
        reverse=True,
    )
    for _rec in (_dog_lookup_dc or {}).values():
        _pname = _dc_clean_project_val(_rec.get("Наименование_Проекта"))
        if _pname and _pname not in _known_project_names:
            _known_project_names.append(_pname)

    _dog_num_to_project: dict[str, str] = {}
    _dog_partner_to_project: dict[str, str] = {}
    for _rec in (_dog_lookup_dc or {}).values():
        _pname = _dc_clean_project_val(_rec.get("Наименование_Проекта"))
        if not _pname:
            continue
        _num_key = _contract_no_search_key(_rec.get("Номер_Договора"))
        if _num_key:
            _dog_num_to_project.setdefault(_num_key, _pname)
        _name_key = _contract_no_search_key(_rec.get("Наименование_Договора"))
        if _name_key and _name_key not in _dog_num_to_project:
            _dog_num_to_project.setdefault(_name_key, _pname)
        _pk = norm_partner_join_key(_rec.get("Наименование_Контрагента"))
        if _pk:
            _dog_partner_to_project.setdefault(_pk, _pname)

    if _dc_project_col_has_empty_rows(project_col):
        # Существующий проект (если колонка есть) остаётся приоритетом —
        # заполненные строки не меняем, каскад дозаполняет только пустые.
        _existing_project_col = project_col if (project_col and project_col in work.columns) else None
        # Шаг 1 — из Dogovor.json по guid договора
        if _dog_lookup_dc:
            def _resolve_project_name(v):
                if not v:
                    return ""
                rec = _dog_lookup_dc.get(str(v).strip().lower())
                if not rec:
                    return ""
                return _dc_clean_project_val(rec.get("Наименование_Проекта"))
            work["_project_from_dogovor"] = work["_id_dogovor_norm"].map(_resolve_project_name)
        else:
            work["_project_from_dogovor"] = ""

        # 1.1) Dogovor.json по текстовому № договора
        if contract_col and contract_col in work.columns and _dog_num_to_project:
            work["_project_from_dogovor_num"] = work[contract_col].map(
                lambda v: _dog_num_to_project.get(_contract_no_search_key(v), "")
            )
        else:
            work["_project_from_dogovor_num"] = ""

        # 1.2) Dogovor.json по подрядчику
        if contractor_col and contractor_col in work.columns and _dog_partner_to_project:
            work["_project_from_dogovor_partner"] = work[contractor_col].map(
                lambda v: _dog_partner_to_project.get(norm_partner_join_key(_extract_partner_name(v)), "")
            )
        else:
            work["_project_from_dogovor_partner"] = ""

        # 1.3) Из текста № договора в DK (напр. «… (Есипово-5)»)
        if contract_col and contract_col in work.columns and _known_project_names:
            work["_project_from_contract_text"] = work[contract_col].map(
                lambda v: _dc_project_from_contract_text(v, _known_project_names)
            )
        else:
            work["_project_from_contract_text"] = ""

        # Правки куратора 08.05.2026: только 5 из 121 ID_Договора в DK совпадают
        # с Dogovor.json — поэтому добавляем основной маппинг по ID_Договора через
        # 1С dannye (где «Проект» проставлен на каждой строке оборотов).
        ref_dn = st.session_state.get("reference_1c_dannye")
        _dann_dog_to_project: dict = {}
        _dann_partner_to_project: dict = {}
        _dann_contract_to_project: dict = {}
        if ref_dn is not None and not getattr(ref_dn, "empty", True):
            try:
                _rdf = ref_dn.copy()
                _rdf.columns = [str(c).strip() for c in _rdf.columns]
                _id_dog_d = _find_col(_rdf, ["ID_Договора", "id_договора", "id_dogovora"])
                _idc = _find_col(_rdf, ["ID_Контрагента", "id_контрагента"])
                _prj = _find_col(_rdf, ["Проект", "project name", "Наименование_Проекта"])
                _dog_txt_d = _find_col(
                    _rdf,
                    ["ДоговорКонтрагента", "Договор", "Номер_Договора", "Номер договора"],
                )
                if _prj and _id_dog_d:
                    for _, r in _rdf[[_id_dog_d, _prj]].dropna().iterrows():
                        kk = str(r[_id_dog_d]).strip().lower()
                        vv = _dc_clean_project_val(r[_prj])
                        if kk and vv:
                            _dann_dog_to_project.setdefault(kk, vv)
                if _prj and _idc:
                    for _, r in _rdf[[_idc, _prj]].dropna().iterrows():
                        kk = str(r[_idc]).strip().lower()
                        vv = _dc_clean_project_val(r[_prj])
                        if kk and vv:
                            _dann_partner_to_project.setdefault(kk, vv)
                if _prj and _dog_txt_d:
                    for _, r in _rdf[[_dog_txt_d, _prj]].dropna().iterrows():
                        kk = _contract_no_search_key(r[_dog_txt_d])
                        vv = _dc_clean_project_val(r[_prj])
                        if kk and vv:
                            _dann_contract_to_project.setdefault(kk, vv)
            except Exception:
                pass

        if _dann_dog_to_project:
            work["_project_from_dannye_by_dog"] = work["_id_dogovor_norm"].map(
                lambda v: _dann_dog_to_project.get(str(v).strip().lower(), "")
            )
        else:
            work["_project_from_dannye_by_dog"] = ""

        if contract_col and contract_col in work.columns and _dann_contract_to_project:
            def _project_from_dannye_contract(v) -> str:
                key = _contract_no_search_key(v)
                if not key:
                    return ""
                if key in _dann_contract_to_project:
                    return _dann_contract_to_project[key]
                for _dk, _pv in _dann_contract_to_project.items():
                    if key in _dk or _dk in key:
                        return _pv
                return ""
            work["_project_from_dannye_by_contract"] = work[contract_col].map(
                _project_from_dannye_contract
            )
        else:
            work["_project_from_dannye_by_contract"] = ""

        pmap = st.session_state.get("reference_partner_to_project") or {}
        if contractor_col and contractor_col in work.columns and (pmap or _dann_partner_to_project):
            def _project_from_partner(v) -> str:
                pid = _extract_partner_id_local(v)
                if pid and pid in _dann_partner_to_project:
                    return _dann_partner_to_project[pid]
                pname = _extract_partner_name(v)
                k = norm_partner_join_key(pname)
                if k and k in pmap:
                    return _dc_clean_project_val(pmap[k])
                return ""
            work["_project_from_partner"] = work[contractor_col].map(_project_from_partner)
        else:
            work["_project_from_partner"] = ""

        _id_partner_col_dk = _find_col(
            work,
            [
                "ID_Контрагента",
                "Контрагент_ID_Контрагента",
                "Контрагент.ID_Контрагента",
            ],
        )
        if _id_partner_col_dk and _dann_partner_to_project:
            work["_project_from_partner_id_dk"] = work[_id_partner_col_dk].map(
                lambda v: _dann_partner_to_project.get(str(v).strip().lower(), "")
            )
        else:
            work["_project_from_partner_id_dk"] = ""

        def _dc_cascade_pick(*vals) -> str:
            for v in vals:
                s = _dc_clean_project_val(v)
                if s:
                    return s
            return ""

        work["_project_resolved"] = work.apply(
            lambda r: _dc_cascade_pick(
                r.get(_existing_project_col) if _existing_project_col else "",
                r.get("_project_from_dogovor"),
                r.get("_project_from_dogovor_num"),
                r.get("_project_from_dannye_by_dog"),
                r.get("_project_from_dannye_by_contract"),
                r.get("_project_from_contract_text"),
                r.get("_project_from_partner_id_dk"),
                r.get("_project_from_dogovor_partner"),
                r.get("_project_from_partner"),
            ),
            axis=1,
        )
        if _dc_project_col_has_data("_project_resolved"):
            project_col = "_project_resolved"
            project_from_reference = True
    paid_col = _find_col(work, ["Выплачено", "выплачено", "Выплаченная сумма", "ВсегоОплат", "paid"])
    advance_col = _find_col(work, ["Аванс", "аванс", "Авансированная сумма", "ВсегоОплат_Аванс", "advance"])
    balance_col = _find_col(work, ["Остаток на конец периода", "Остаток на период", "ОстатокНаКонецПериода", "остаток", "balance"])
    # §4.7 / выгрузка DK: нетто-остатки из компонент (если колонки есть)
    _dk_start_gross = _find_col(
        work,
        ["ОстатокНаНачалоПериода", "Остаток на начало периода", "остаток на начало периода"],
    )
    _dk_start_adv = _find_col(
        work,
        [
            "ОстатокНаНачалоПериодаПоАвансам",
            "Остаток на начало периода по авансам",
            "остаток на начало периода по авансам",
        ],
    )
    _dk_end_gross = _find_col(
        work,
        [
            "ОстатокНаКонецПериода",
            "Остаток на конец периода",
            "остаток на конец периода",
            "ОстатокНаКонец",
        ],
    )
    _dk_end_adv = _find_col(
        work,
        [
            "ОстатокНаКонецПериодаПоАвансам",
            "Остаток на конец периода по авансам",
            "остаток на конец периода по авансам",
        ],
    )
    _dk_col_net_start = None
    _dk_col_net_end = None
    if _dk_start_gross and _dk_start_adv and _dk_start_gross in work.columns and _dk_start_adv in work.columns:
        work["_dk_net_начало"] = _to_num(work[_dk_start_gross]) - _to_num(work[_dk_start_adv])
        _dk_col_net_start = "_dk_net_начало"
    if _dk_end_gross and _dk_end_adv and _dk_end_gross in work.columns and _dk_end_adv in work.columns:
        work["_dk_net_конец"] = _to_num(work[_dk_end_gross]) - _to_num(work[_dk_end_adv])
        _dk_col_net_end = "_dk_net_конец"

    if not contract_col:
        st.error("Не найдена колонка «Договор». Проверьте заголовки файла.")
        st.info("Доступные колонки: " + ", ".join(work.columns))
        return
    for label, col in [("Выплачено", paid_col), ("Аванс", advance_col), ("Остаток", balance_col)]:
        if not col:
            st.warning(f"Колонка «{label}» не найдена — соответствующие данные не отобразятся.")

    # Числовые колонки
    for c in [total_col, paid_col, advance_col, balance_col]:
        if c:
            work[f"_num_{c}"] = _to_num(work[c])
    if total_col and f"_num_{total_col}" in work.columns:
        if "_summa_dogovora_lookup" in work.columns:
            _lk = _to_num(work["_summa_dogovora_lookup"])
            _mask_zero = work[f"_num_{total_col}"].abs() <= 1e-6
            work.loc[_mask_zero, f"_num_{total_col}"] = _lk[_mask_zero]
        if contract_col and contract_col in work.columns and _dog_num_to_summa:
            _mask_zero = work[f"_num_{total_col}"].abs() <= 1e-6
            if _mask_zero.any():
                _by_num = work.loc[_mask_zero, contract_col].map(
                    lambda v: _dog_num_to_summa.get(_contract_no_search_key(v), 0.0)
                )
                work.loc[_mask_zero, f"_num_{total_col}"] = pd.to_numeric(
                    _by_num, errors="coerce"
                ).fillna(0.0)

    # В выгрузке DK колонка «Аванс» часто пустая (все нули) — фактический
    # остаток по авансам лежит в «ОстатокНаКонецПериодаПоАвансам». Если прямой
    # «Аванс» пуст, берём остаток по авансам, иначе столбец аванса в графике/таблице
    # не отображается (баг «все столбцы, кроме аванса» в режиме «С группировкой»).
    _adv_sum = (
        float(work[f"_num_{advance_col}"].abs().sum())
        if advance_col and f"_num_{advance_col}" in work.columns
        else 0.0
    )
    if _adv_sum <= 1e-6 and _dk_end_adv and _dk_end_adv in work.columns:
        _adv_alt = _to_num(work[_dk_end_adv])
        if float(_adv_alt.abs().sum()) > 1e-6:
            advance_col = _dk_end_adv
            work[f"_num_{advance_col}"] = _adv_alt

    _dc_orphan_adv_mln = _dc_read_orphan_advance_mln(
        work,
        advance_num_col=f"_num_{advance_col}" if advance_col and f"_num_{advance_col}" in work.columns else None,
    )
    _summary_mask = work.apply(
        lambda r: _dc_is_dk_summary_row(
            r,
            contractor_col=contractor_col,
            contract_col=contract_col,
            extract_partner_name=_extract_partner_name,
            extract_partner_id=_extract_partner_id_local,
        ),
        axis=1,
    )
    if _summary_mask.any():
        work = work.loc[~_summary_mask].copy()

    _dc_date_contract = _find_col(work, ["Дата договора", "ДатаДоговора", "Дата Договора"])
    work["_dc_period_dt"] = pd.NaT
    if _dc_date_contract and _dc_date_contract in work.columns:
        work["_dc_period_dt"] = _rd_naive_datetime_series(work[_dc_date_contract])
        _dc_sentinel_mask = work["_dc_period_dt"].notna() & (work["_dc_period_dt"].dt.year <= 1)
        work.loc[_dc_sentinel_mask, "_dc_period_dt"] = pd.NaT

    # Правки куратора 08.05.2026: считаем «Выполнено (КС-2)» из 1С dannye.
    # КС-2 = sum(Сумма) по строкам, у которых СтатьяОборотов содержит
    # «Поступление товаров и услуг» или «Поступление услуг из переработки».
    # Привязка — по ID_Контрагента (в DK подрядчик хранится словарём
    # {id_контрагента, наименованиеконтрагента}, поэтому матчинг по имени
    # бесполезен — извлекаем id из строки/dict и ищем по нему).
    work["_num_ks2"] = 0.0
    _ks2_diag: dict = {"reason": "", "rows": 0, "matched": 0}

    def _extract_partner_id(v) -> str:
        if v is None:
            return ""
        if isinstance(v, dict):
            for k in (
                "id_контрагента", "ID_Контрагента", "id_kontragenta",
                "id", "ID",
            ):
                if k in v and v[k]:
                    return str(v[k]).strip().lower()
            return ""
        s = str(v)
        m = re.search(r"id_контрагента\s*[:=]\s*([0-9a-fA-F\-]+)", s, flags=re.IGNORECASE)
        if m:
            return m.group(1).strip().lower()
        # Иногда v — это уже чистый UUID-id
        m2 = re.fullmatch(r"\s*([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s*", s)
        if m2:
            return m2.group(1).strip().lower()
        return ""

    try:
        ref_dannye = st.session_state.get("reference_1c_dannye")
        if ref_dannye is None or getattr(ref_dannye, "empty", True):
            _ks2_diag["reason"] = "reference_1c_dannye отсутствует в session_state (загрузите 1С dannye через web/ или FTP)"
        else:
            _rd = ref_dannye.copy()
            _rd.columns = [str(c).strip() for c in _rd.columns]
            _so_col = _find_col(_rd, ["СтатьяОборотов", "Статья оборотов", "turnover item"])
            _sum_col = _find_col(_rd, ["Сумма", "amount", "СуммаОборота"])
            _id_col_d = _find_col(_rd, ["ID_Контрагента", "id_контрагента", "id_kontragenta"])
            _name_col_d = _find_col(
                _rd,
                ["Контрагент", "Наименование_Контрагента", "Наименование Контрагента", "контрагент"],
            )
            if not _so_col or not _sum_col:
                _ks2_diag["reason"] = "в 1С dannye нет колонок «СтатьяОборотов» / «Сумма»"
            else:
                # КС-2: статьи из ТЗ + фактическая выгрузка 1С («Поступления по основной деятельности»).
                _ks2_articles_cf = {
                    "поступление товаров и услуг",
                    "поступление услуг из переработки",
                    "поступления по основной деятельности",
                }
                _so_cf = _rd[_so_col].astype(str).str.strip().str.casefold()
                _rd_ks2 = _rd[_so_cf.isin(_ks2_articles_cf)].copy()
                _ks2_diag["rows"] = int(len(_rd_ks2))
                if _rd_ks2.empty:
                    _ks2_diag["reason"] = (
                        "в 1С dannye нет строк с точными статьями "
                        "«Поступление товаров и услуг» / «Поступление услуг из переработки»"
                    )
                else:
                    _rd_ks2["_amt"] = _to_num(_rd_ks2[_sum_col])
                    # Q-08.05.2026: основной ключ — ID_Договора (есть и в DK, и в
                    # dannye), вторичный — ID_Контрагента, на крайний случай — имя.
                    _id_dog_col_d = _find_col(_rd_ks2, ["ID_Договора", "id_договора", "id_dogovora"])
                    _ks2_by_dog: dict = {}
                    if _id_dog_col_d and _id_dog_col_d in _rd_ks2.columns:
                        _ks2_by_dog = (
                            _rd_ks2.assign(_k=_rd_ks2[_id_dog_col_d].astype(str).str.strip().str.lower())
                            .groupby("_k", dropna=False)["_amt"]
                            .sum()
                            .to_dict()
                        )
                    _ks2_by_partner_id: dict = {}
                    if _id_col_d and _id_col_d in _rd_ks2.columns:
                        _ks2_by_partner_id = (
                            _rd_ks2.assign(_k=_rd_ks2[_id_col_d].astype(str).str.strip().str.lower())
                            .groupby("_k", dropna=False)["_amt"]
                            .sum()
                            .to_dict()
                        )
                    _ks2_by_partner_name: dict = {}
                    if _name_col_d and _name_col_d in _rd_ks2.columns:
                        _ks2_by_partner_name = (
                            _rd_ks2.assign(_k=_rd_ks2[_name_col_d].map(norm_partner_join_key))
                            .groupby("_k", dropna=False)["_amt"]
                            .sum()
                            .to_dict()
                        )

                    # Готовим ключи в work: ID_Договора и ID_Контрагента уже
                    # лежат отдельными колонками после flatten DK.
                    _id_partner_col_dk2 = _find_col(
                        work,
                        [
                            "ID_Контрагента",
                            "Контрагент_ID_Контрагента",
                            "Контрагент.ID_Контрагента",
                        ],
                    )
                    _ks2_series = pd.Series(0.0, index=work.index)
                    if "_id_dogovor_norm" in work.columns and _ks2_by_dog:
                        _ks2_series = work["_id_dogovor_norm"].map(
                            lambda v: float(_ks2_by_dog.get(str(v).strip().lower(), 0.0))
                            if v
                            else 0.0
                        )
                    if _id_partner_col_dk2 and _ks2_by_partner_id:
                        _alt = work[_id_partner_col_dk2].map(
                            lambda v: float(_ks2_by_partner_id.get(str(v).strip().lower(), 0.0))
                            if pd.notna(v) and str(v).strip()
                            else 0.0
                        )
                        # Дополняем нулевые значения партнёрским ключом.
                        _ks2_series = _ks2_series.where(_ks2_series != 0, _alt)
                    if contractor_col and contractor_col in work.columns and _ks2_by_partner_name:
                        _alt2 = work[contractor_col].map(
                            lambda v: float(_ks2_by_partner_name.get(norm_partner_join_key(v), 0.0))
                        )
                        _ks2_series = _ks2_series.where(_ks2_series != 0, _alt2)
                    work["_num_ks2"] = _ks2_series.fillna(0.0).astype(float)
                    _ks2_diag["matched"] = int((work["_num_ks2"] != 0).sum())
                    if _ks2_diag["matched"] == 0 and _ks2_diag["rows"] > 0:
                        _ks2_diag["reason"] = (
                            "КС-2 в 1С есть, но не получилось сопоставить "
                            "DK ↔ dannye по ID_Договора / ID_Контрагента / имени"
                        )
    except Exception as _e:
        _ks2_diag["reason"] = f"ошибка расчёта КС-2: {_e!r}"

    if _ks2_diag.get("reason"):
        suppress_caption(f"КС-2 (из dannye): {_ks2_diag['reason']}")

    _num_adv_fulfilled = (
        work[f"_num_{advance_col}"]
        if advance_col and f"_num_{advance_col}" in work.columns
        else pd.Series(0.0, index=work.index)
    )
    _num_ks2_fulfilled = (
        work["_num_ks2"]
        if "_num_ks2" in work.columns
        else pd.Series(0.0, index=work.index)
    )
    work["_num_fulfilled"] = _num_adv_fulfilled.fillna(0.0) + _num_ks2_fulfilled.fillna(0.0)

    issue_start = None
    issue_end = None

    with filters_panel(
        st,
        reset_keys=[
            "debit_credit_project",
            "debit_credit_contractor",
            "debit_credit_contract_q",
            "debit_credit_period_range",
            "debit_credit_display_view",
        ],
        reset_defaults={
            "debit_credit_project": "Все",
            "debit_credit_contractor": "Все",
            "debit_credit_contract_q": "",
            "debit_credit_display_view": "Без группировки",
        },
    ):
        with filters_selectors(st):
            fp1, fp2, fp3, fp4, fp5 = st.columns(5, gap="small")
            with fp1:
                if project_col and project_col in work.columns:
                    _proj_series = work[project_col].replace("", pd.NA).dropna()
                    all_projects = ["Все"] + _unique_project_labels_for_select(
                        _proj_series, apply_exclude_names=False
                    )
                    sel_project = st.selectbox("Проект", all_projects, key="debit_credit_project")
                else:
                    sel_project = "Все"
                    st.selectbox("Проект", ["—"], disabled=True, key="debit_credit_project_dis")
            with fp2:
                if contractor_col and contractor_col in work.columns:
                    all_contractors = ["Все"] + sorted(
                        {
                            str(v).strip()
                            for v in work[contractor_col].dropna().astype(str).tolist()
                            if str(v).strip()
                        },
                        key=lambda x: x.casefold(),
                    )
                    sel_contractor = st.selectbox("Подрядчик", all_contractors, key="debit_credit_contractor")
                else:
                    sel_contractor = "Все"
                    st.selectbox("Подрядчик", ["—"], disabled=True, key="debit_credit_contractor_dis")
            with fp3:
                contract_q = st.text_input(
                    "№ договора (частичный поиск)",
                    key="debit_credit_contract_q",
                    placeholder="Все договоры",
                )
            with fp4:
                _dc_valid_period = work["_dc_period_dt"].dropna()
                if _dc_valid_period.notna().any():
                    mn = _dc_valid_period.min().date()
                    mx = _dc_valid_period.max().date()
                    dr = st.date_input(
                        "Период",
                        value=(mn, mx),
                        min_value=mn,
                        max_value=mx,
                        key="debit_credit_period_range",
                        format="DD.MM.YYYY",
                    )
                    if isinstance(dr, tuple) and len(dr) == 2:
                        issue_start, issue_end = dr[0], dr[1]
                    elif hasattr(dr, "year"):
                        issue_start = issue_end = dr
                else:
                    st.caption("Нет колонки «Дата договора» — период не применяется.")
            with fp5:
                dk_display_view = st.selectbox(
                    "Вид отображения",
                    ["Без группировки", "С группировкой"],
                    index=0,
                    key="debit_credit_display_view",
                    help="Без группировки — столбцы рядом (визуал 1). "
                    "С группировкой — стек: отклонение ≥0, КС-2, аванс (визуал 2). "
                    "Отклонение <0 — только без группировки.",
                )

    if project_col and project_col in work.columns:
        try:
            _plu = _load_project_id_to_name_lookup()
            if _plu:
                work[project_col] = _resolve_project_display_labels(work[project_col], _plu)
        except Exception:
            pass

    filtered = work.copy()
    if sel_contractor != "Все" and contractor_col:
        filtered = filtered[filtered[contractor_col].astype(str).str.strip() == str(sel_contractor).strip()]
    q = (contract_q or "").strip() if isinstance(contract_q, str) else ""
    if q and contract_col:
        ql = q.casefold()
        filtered = filtered[
            filtered[contract_col].astype(str).apply(lambda s: ql in str(s).casefold())
        ]
    if sel_project != "Все" and project_col:
        filtered = filtered[
            filtered[project_col].map(_project_filter_norm_key)
            == _project_filter_norm_key(sel_project)
        ]
    if issue_start is not None and issue_end is not None and "_dc_period_dt" in filtered.columns:
        _pd = _rd_naive_datetime_series(filtered["_dc_period_dt"])
        _period_start = pd.Timestamp(issue_start).normalize()
        _period_end = pd.Timestamp(issue_end).normalize()
        filtered = filtered[
            _pd.isna()
            | (
                _pd.notna()
                & (_pd.dt.normalize() >= _period_start)
                & (_pd.dt.normalize() <= _period_end)
            )
        ]

    if filtered.empty:
        st.info("Нет данных при выбранных фильтрах.")
        return

    def _trunc_label(val, max_len: int = 22) -> str:
        s = str(val).strip()
        if len(s) <= max_len:
            return s
        return s[: max_len - 1] + "…"

    def _dk_x_tick_labels(vals) -> list[str]:
        import textwrap as _tw

        out: list[str] = []
        for v in vals:
            s = str(v).strip()
            if not s:
                out.append("")
                continue
            parts = _tw.wrap(s, width=16, break_long_words=False, break_on_hyphens=False)
            out.append("<br>".join(parts[:2]) if parts else s)
        return out

    chart_group_col = contractor_col if contractor_col else contract_col
    chart_label = "Подрядчик" if contractor_col else "Договор"
    if contractor_col and contractor_col in filtered.columns:
        filtered["_dc_chart_partner"] = filtered[contractor_col].map(
            lambda v: _extract_partner_name(v) or str(v or "").strip()
        )
        chart_group_col = "_dc_chart_partner"
    if not contractor_col:
        st.warning("Колонка подрядчика не найдена — диаграмма сгруппирована по договору.")

    built = {}
    # Правки куратора 08.05.2026: финансы → млн руб., до десятых.
    # Делим суммы на 1e6 уже на этапе агрегации, чтобы и подписи, и таблица работали в одних единицах.
    _SCALE_MLN = 1e6
    if total_col and f"_num_{total_col}" in filtered.columns:
        built["Договор стоимость"] = filtered.groupby(chart_group_col)[f"_num_{total_col}"].max() / _SCALE_MLN
    if advance_col and f"_num_{advance_col}" in filtered.columns:
        built["Аванс"] = filtered.groupby(chart_group_col)[f"_num_{advance_col}"].sum() / _SCALE_MLN
    if "_num_ks2" in filtered.columns:
        built["КС-2"] = filtered.groupby(chart_group_col)["_num_ks2"].sum() / _SCALE_MLN
    # Отклонение для визуала 1 = КС-2 − Аванс (по ТЗ заказчика, отдельный «зелёный/красный» столбец).
    if "Аванс" in built and "КС-2" in built:
        built["Отклонение"] = built["КС-2"] - built["Аванс"]

    if not built:
        st.warning("Нет числовых колонок для отображения (сумма в договоре, выплачено, аванс, остаток).")
        return

    chart_df = pd.DataFrame(built).reset_index()
    chart_df = chart_df.rename(columns={chart_group_col: chart_label})
    chart_df[chart_label] = chart_df[chart_label].astype(str).str.strip()
    _dk_num_cols = [c for c in chart_df.columns if c != chart_label]
    if _dk_num_cols:
        chart_df = _dc_merge_chart_rows_by_partner_key(chart_df, chart_label, _dk_num_cols)
    if _dc_orphan_adv_mln > 1e-6:
        chart_df = _dc_apply_orphan_advances_to_chart(
            chart_df,
            chart_label,
            {"Аванс": _dc_orphan_adv_mln},
        )

    # ТЗ: «Без группировки» — столбцы рядом (group); «С группировкой» — стек (stack).
    _dk_side_by_side = str(dk_display_view or "").strip() == "Без группировки"
    _dk_is_stack = not _dk_side_by_side
    _has_deviation_col = "Отклонение" in chart_df.columns

    value_cols = [c for c in chart_df.columns if c != chart_label]
    if not value_cols:
        st.info("Нет данных для графика.")
    else:
        # При большом числе категорий столбцы становятся слишком узкими:
        # оставляем топ по максимальной абсолютной метрике.
        _dk_max_bars = 28
        chart_df["_bar_rank"] = chart_df[value_cols].abs().max(axis=1)
        chart_df = _limit_bar_categories(
            chart_df, "_bar_rank", max_bars=_dk_max_bars, label="контрагентов/договоров"
        )
        chart_df = chart_df.drop(columns=["_bar_rank"], errors="ignore")
        value_cols = [c for c in chart_df.columns if c != chart_label]
        colors = {
            "Договор стоимость": "#27ae60",
            "Аванс": "#2E86AB",
            "КС-2": "#F1C40F",
        }

        def _dk_chart_bar_text(v, *, min_abs: float = 0.05) -> str:
            if v is None or (isinstance(v, float) and pd.isna(v)):
                return ""
            try:
                x = float(v)
            except (TypeError, ValueError):
                return ""
            if abs(x) < min_abs:
                return ""
            return f"{x:.1f} млн руб"

        _dk_bar_label_style = dict(
            textposition="outside",
            textangle=0,
            cliponaxis=False,
            textfont=dict(size=11, color=_fin_chart_label_color(dark="#e8eef5", light="#111827")),
        )
        _dk_single_partner = None
        if _dk_is_stack:
            fig = _dk_make_stack_bar_figure(
                chart_df,
                chart_label,
                has_deviation=_has_deviation_col,
                text_fn=_dk_chart_bar_text,
            )
            _cats_full = chart_df[chart_label].astype(str).tolist()
        else:
            fig, _cats_full, _dk_single_partner = _dk_make_side_by_side_bar_figure(
                chart_df,
                chart_label,
                has_deviation=_has_deviation_col,
                value_cols=value_cols,
                colors=colors,
                text_fn=_dk_chart_bar_text,
                bar_label_style=_dk_bar_label_style,
            )
        _yaxis_kw = _dk_chart_yaxis_layout(
            chart_df,
            has_deviation=_has_deviation_col,
            side_by_side=_dk_side_by_side,
        )
        fig.update_layout(
            barmode="stack" if _dk_is_stack else "group",
            showlegend=True,
            yaxis=_yaxis_kw,
            margin=dict(r=40, b=120, t=88, l=64),
        )
        fig = _apply_finance_bar_label_layout(fig)
        try:
            fig.update_traces(
                textposition="outside",
                cliponaxis=False,
                selector=dict(type="bar"),
            )
        except Exception:
            pass
        _nfc_dk = max(1, len(chart_df))
        _leg_bottom_dk = int(max(148, min(220, 128 + _nfc_dk * 2)))
        _leg_y_dk = -0.18 if _nfc_dk <= 12 else (-0.22 if _nfc_dk <= 18 else -0.28)
        fig = apply_chart_background(fig)
        fig = _plotly_legend_horizontal_below_plot(
            fig,
            bottom_px=_leg_bottom_dk,
            legend_y=_leg_y_dk,
            top_px=88,
        )
        try:
            fig.update_layout(showlegend=True)
        except Exception:
            pass
        base = "Суммы по подрядчику" if contractor_col else "Суммы по договору"
        if _dk_side_by_side:
            cap = (
                base
                + (f": {_dk_single_partner}" if _dk_single_partner else "")
                + ". Без группировки: Аванс (син.), КС-2 (жёлт.), "
                "отклонение ≥0 (сер.), отклонение <0 (красн., ниже 0)."
            )
        else:
            cap = (
                base
                + ". С группировкой (стек): отклонение ≥0 (сер.) → КС-2 (жёлт.) → Аванс (син.)."
            )
        _cats_tick = _dk_x_tick_labels(_cats_full)
        if _dk_is_stack:
            _dk_plotly_finalize_stack_bars(fig, n_cats=len(_cats_full))
        else:
            _nfc = max(1, len(_cats_full))
            _bg_dk = 0.10 if _nfc >= 5 else max(0.05, min(0.12, 1.6 / _nfc))
            _dk_plotly_finalize_group_bars(fig, n_cats=len(_cats_full), bargap=_bg_dk)
        _render_debit_credit_bar_chart(
            fig,
            categories=_cats_full,
            tick_labels=_cats_tick,
            stack=_dk_is_stack,
            caption_below=cap,
        )

    render_table_subheader(st, "Таблица по подрядчику и договору" if contractor_col else "Таблица по договорам")
    table_group_cols = [contract_col]
    if contractor_col:
        table_group_cols = [contractor_col, contract_col]
    _tbl_proj_lookup: dict[tuple[str, str], str] = {}
    if (
        project_col
        and project_col in filtered.columns
        and contractor_col
        and contract_col
        and contractor_col in filtered.columns
        and contract_col in filtered.columns
    ):
        for _, _pr in filtered[[contractor_col, contract_col, project_col]].iterrows():
            _pk = (str(_pr[contractor_col]).strip(), str(_pr[contract_col]).strip())
            _pv = _dc_clean_project_val(_pr[project_col])
            if _pv and _pk[0] and _pk[1]:
                _tbl_proj_lookup.setdefault(_pk, _pv)
    tbl_built = {}
    # Правки куратора 08.05.2026: всё в млн руб., до десятых.
    # Структура столбцов по ТЗ:
    #   Договор стоимость | Всего выполненных обязательств по платежам | Аванс |
    #   Допущения по авансированию % | Выполнено (КС-2) | Остаток | Аванс − КС-2
    if total_col and f"_num_{total_col}" in filtered.columns:
        tbl_built["Договор стоимость"] = filtered.groupby(table_group_cols)[f"_num_{total_col}"].max() / _SCALE_MLN
    if "_num_fulfilled" in filtered.columns:
        tbl_built["Всего выполненных обязательств по платежам"] = (
            filtered.groupby(table_group_cols)["_num_fulfilled"].sum() / _SCALE_MLN
        )
    if advance_col and f"_num_{advance_col}" in filtered.columns:
        tbl_built["Аванс"] = filtered.groupby(table_group_cols)[f"_num_{advance_col}"].sum() / _SCALE_MLN
    if "_num_ks2" in filtered.columns:
        tbl_built["Выполнено (КС-2)"] = filtered.groupby(table_group_cols)["_num_ks2"].sum() / _SCALE_MLN
    if _dk_col_net_end and _dk_col_net_end in filtered.columns:
        tbl_built["Остаток"] = filtered.groupby(table_group_cols)[_dk_col_net_end].sum() / _SCALE_MLN
    elif balance_col and f"_num_{balance_col}" in filtered.columns:
        tbl_built["Остаток"] = filtered.groupby(table_group_cols)[f"_num_{balance_col}"].sum() / _SCALE_MLN
    if not tbl_built:
        st.warning("Нет числовых колонок для таблицы.")
        return
    table_df = pd.DataFrame(tbl_built).reset_index()
    rename_map = {}
    if contractor_col and contractor_col in table_df.columns:
        rename_map[contractor_col] = "Подрядчик"
    if contract_col and contract_col in table_df.columns:
        rename_map[contract_col] = "Договор"
    if rename_map:
        table_df = table_df.rename(columns=rename_map)
    elif contract_col and contract_col in table_df.columns:
        table_df = table_df.rename(columns={contract_col: "Договор"})
    if _tbl_proj_lookup and "Подрядчик" in table_df.columns and "Договор" in table_df.columns:
        table_df["Проект"] = table_df.apply(
            lambda r: _tbl_proj_lookup.get(
                (str(r.get("Подрядчик", "")).strip(), str(r.get("Договор", "")).strip()),
                "",
            ),
            axis=1,
        )
    elif project_col and project_col in table_df.columns:
        table_df = table_df.rename(columns={project_col: "Проект"})
    # Убираем пустые ключи группировки, чтобы не было «пустой строки» в начале таблицы.
    if "Подрядчик" in table_df.columns:
        table_df = table_df[
            table_df["Подрядчик"].astype(str).str.strip().ne("")
            & table_df["Подрядчик"].astype(str).str.lower().str.strip().ne("nan")
        ].copy()
    if "Договор" in table_df.columns:
        table_df = table_df[
            table_df["Договор"].astype(str).str.strip().ne("")
            & table_df["Договор"].astype(str).str.lower().str.strip().ne("nan")
        ].copy()
    if table_df.empty:
        st.info("Нет строк подрядчик/договор после очистки пустых значений.")
        return
    group_dim_cols = [c for c in ("Проект", "Подрядчик", "Договор") if c in table_df.columns]
    value_cols_t = [c for c in table_df.columns if c not in group_dim_cols]

    # Правки куратора 08.05.2026: расчётная колонка «Аванс − КС-2».
    _ADV_DELTA_COL = "Аванс − КС-2"
    _ADV_ASSUMP_COL = "Допущения по авансированию %"
    if "Выполнено (КС-2)" in value_cols_t and "Аванс" in value_cols_t:
        _adv_num = pd.to_numeric(table_df["Аванс"], errors="coerce").fillna(0.0)
        _ks2_num = pd.to_numeric(table_df["Выполнено (КС-2)"], errors="coerce").fillna(0.0)
        table_df[_ADV_DELTA_COL] = _adv_num - _ks2_num
        value_cols_t.append(_ADV_DELTA_COL)

    if (
        "Аванс" in value_cols_t
        and "Договор стоимость" in value_cols_t
        and "Выполнено (КС-2)" in value_cols_t
    ):
        _plan_tbl = pd.to_numeric(table_df["Договор стоимость"], errors="coerce").fillna(0.0)
        _delta_tbl = pd.to_numeric(
            table_df.get(_ADV_DELTA_COL, table_df["Аванс"] - table_df["Выполнено (КС-2)"]),
            errors="coerce",
        ).fillna(0.0)
        table_df["_adv_sem"] = [
            _dc_advance_semaphore_level(d, p) for d, p in zip(_delta_tbl, _plan_tbl)
        ]
        table_df[_ADV_ASSUMP_COL] = [
            _dc_advance_assumption_label(d, p, lv)
            for d, p, lv in zip(_delta_tbl, _plan_tbl, table_df["_adv_sem"])
        ]
    total_row = {c: "" for c in group_dim_cols}
    if group_dim_cols:
        total_row[group_dim_cols[0]] = "ИТОГО"
    for col in value_cols_t:
        total_row[col] = table_df[col].sum()
    if _ADV_ASSUMP_COL in table_df.columns:
        try:
            _tp = float(pd.to_numeric(table_df["Договор стоимость"], errors="coerce").sum())
            _ta = float(pd.to_numeric(table_df["Аванс"], errors="coerce").sum())
            _tk = float(pd.to_numeric(table_df["Выполнено (КС-2)"], errors="coerce").sum())
            _tot_delta = _ta - _tk
            if _ADV_DELTA_COL in value_cols_t:
                total_row[_ADV_DELTA_COL] = _tot_delta
            _tot_lvl = _dc_advance_semaphore_level(_tot_delta, _tp)
            total_row[_ADV_ASSUMP_COL] = _dc_advance_assumption_label(_tot_delta, _tp, _tot_lvl)
            total_row["_adv_sem"] = _tot_lvl
        except Exception:
            total_row[_ADV_ASSUMP_COL] = ""
            total_row["_adv_sem"] = ""
    table_df = pd.concat([table_df, pd.DataFrame([total_row])], ignore_index=True)
    _sem_levels = table_df.get("_adv_sem", pd.Series("", index=table_df.index))
    display_df = table_df.drop(columns=["_adv_sem"], errors="ignore").copy()
    if "Проект" in display_df.columns:
        display_df["Проект"] = display_df["Проект"].map(_dc_clean_project_val)
    try:
        from dashboards.light_theme import is_light_preview_active

        _dc_light = is_light_preview_active()
    except Exception:
        _dc_light = False
    _cell_bg = pd.DataFrame("", index=display_df.index, columns=display_df.columns)
    _adv_sem_bg_cols = [c for c in (_ADV_ASSUMP_COL, _ADV_DELTA_COL) if c in _cell_bg.columns]
    if _adv_sem_bg_cols:
        for _ix, _lv in _sem_levels.items():
            _bg = _dc_advance_semaphore_bg(str(_lv or ""), light=_dc_light)
            if _bg:
                for _bg_col in _adv_sem_bg_cols:
                    _cell_bg.at[_ix, _bg_col] = _bg
    # Правки куратора 08.05.2026: финальный порядок колонок по ТЗ.
    desired_order_value = [
        "Договор стоимость",
        "Всего выполненных обязательств по платежам",
        "Аванс",
        _ADV_ASSUMP_COL,
        "Выполнено (КС-2)",
        "Остаток",
        _ADV_DELTA_COL,
    ]
    final_order = [c for c in group_dim_cols if c in display_df.columns]
    final_order += [c for c in desired_order_value if c in display_df.columns]
    for c in display_df.columns:
        if c not in final_order:
            final_order.append(c)
    display_df = display_df[final_order]
    _cell_bg = _cell_bg[final_order]
    _n_data_rows = max(0, len(display_df) - 1)
    suppress_caption(
        f"Строк данных: {_n_data_rows} • Финансы — млн руб., до десятых • "
        "Строка «ИТОГО» закреплена внизу при прокрутке; "
        f"колонки «Остаток», «{_ADV_DELTA_COL}» — прокрутите таблицу вправо →"
    )
    _render_format_dataframe_html(
        display_df,
        file_stem="debit_credit",
        key_prefix="debit_credit",
        cell_background=_cell_bg,
        finance_decimal_places=1,
        bold_row_indices={len(display_df) - 1},
        table_scroll_max_height_vh=52,
    )
    _render_dc_advance_semaphore_legend(st)


# ── TESSA: поиск колонок и дат (Исполнительная документация / Предписания) ──
def _tessa_find_column(df, candidates):
    """Возвращает имя колонки из df по списку возможных имён (точное и частичное совпадение)."""
    if df is None or not hasattr(df, "columns"):
        return None
    cols = list(df.columns)
    for cand in candidates:
        c0 = cand.strip().lower()
        for c in cols:
            if str(c).strip().lower() == c0:
                return c
    for cand in candidates:
        c0 = cand.strip().lower()
        for c in cols:
            if c0 in str(c).strip().lower():
                return c
    return None


def _tessa_cell_has_value(v) -> bool:
    if v is None:
        return False
    if isinstance(v, float) and pd.isna(v):
        return False
    s = str(v).strip().lower()
    return s not in ("", "nan", "none", "nat")


def _tessa_norm_join_key(val) -> str:
    """Единый ключ для DocID / CardId: 83, 83.0, «83» → «83»."""
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return ""
    try:
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            fv = float(val)
            if fv == int(fv):
                return str(int(fv))
    except (TypeError, ValueError, OverflowError):
        pass
    s = str(val).strip()
    if len(s) > 2 and s.endswith(".0") and s[:-2].replace("-", "").isdigit():
        return s[:-2]
    return s


def _tessa_row_join_key(row, doc_col, card_col) -> str:
    if doc_col and doc_col in row.index and _tessa_cell_has_value(row[doc_col]):
        return _tessa_norm_join_key(row[doc_col])
    if card_col and card_col in row.index and _tessa_cell_has_value(row[card_col]):
        return _tessa_norm_join_key(row[card_col])
    return ""


def _tessa_to_datetime(series):
    """Парсинг дат из TESSA (dd.mm.yyyy и пр.)."""
    if series is None:
        return pd.Series(dtype="datetime64[ns]")
    return pd.to_datetime(series, errors="coerce", dayfirst=True)


def _krstate_bucket(raw) -> str:
    """Сопоставление с KrStates_Doc_* из PDF (если в данных англ. идентификаторы)."""
    if raw is None or (isinstance(raw, float) and pd.isna(raw)):
        return "other"
    s = str(raw).strip()
    sl = s.lower()
    if "declined" in sl or "отказ" in sl:
        return "declined"
    if "active" in sl or "doc_active" in sl:
        return "active"
    if "signed" in sl:
        return "signed"
    return "other"


def _rd_has_tessa_production_dates() -> bool:
    try:
        return bool(_rd_task_dates_by_card())
    except Exception:
        return False


def _rd_in_production_mask(
    df: pd.DataFrame, in_production_col: str | None = None
) -> pd.Series:
    """Строки «выдано в производство»: приоритет — дата из tessa_tasks (ГИП/Подписан)."""
    if df is None or getattr(df, "empty", True):
        return pd.Series(dtype=bool)
    if "_tessa_production_dt" in df.columns:
        m = df["_tessa_production_dt"].notna()
        if m.any():
            return m.fillna(False)
    if in_production_col and in_production_col in df.columns:
        s = df[in_production_col]
        dt = pd.to_datetime(s.astype(str), errors="coerce", dayfirst=True, format="mixed")
        if dt.notna().any():
            return dt.notna()
        num = pd.to_numeric(
            s.astype(str).str.replace(",", ".", regex=False), errors="coerce"
        ).fillna(0)
        return num > 0
    return pd.Series(False, index=df.index)


def _rd_production_fact_date_series(
    df: pd.DataFrame,
    in_production_col: str | None = None,
    fallback_fact_col: str | None = None,
) -> pd.Series:
    if df is None or getattr(df, "empty", True):
        return pd.Series(dtype="datetime64[ns]")
    if "_tessa_production_dt" in df.columns:
        ts = pd.to_datetime(df["_tessa_production_dt"], errors="coerce")
        if ts.notna().any():
            return ts
    if in_production_col and in_production_col in df.columns:
        dt = pd.to_datetime(
            df[in_production_col].astype(str), errors="coerce", dayfirst=True, format="mixed"
        )
        if dt.notna().any():
            return dt
    if fallback_fact_col and fallback_fact_col in df.columns:
        return pd.to_datetime(
            df[fallback_fact_col].astype(str), errors="coerce", dayfirst=True, format="mixed"
        )
    return pd.Series(pd.NaT, index=df.index)


