def _exec_html_block_for_theme(body_html: str) -> str:
    block = _exec_css_for_theme(_EXEC_DOC_DETAIL_CSS) + (body_html or "")
    try:
        from dashboards.light_theme import is_light_preview_active

        if is_light_preview_active():
            return f'<div class="bi-light-table">{block}</div>'
    except Exception:
        pass
    return block


def _exec_muted_text_color() -> str:
    try:
        from dashboards.light_theme import is_light_preview_active

        if is_light_preview_active():
            return "#64748b"
    except Exception:
        pass
    return "#8892a0"


def _exec_status_pill_html(status: str) -> str:
    """Бейджи статуса как на макете: Принят / У Заказчика / У Подрядчика / Отказ."""
    esc = html_module.escape
    s = str(status or "").strip()
    if not s:
        return f'<span class="exec-pill-muted">{esc("—")}</span>'
    sl = s.lower()
    if "на согласован" in sl or sl == "на согласовании":
        return f'<span class="exec-pill exec-pill-customer">{esc("У Заказчика")}</span>'
    if "доработ" in sl:
        return f'<span class="exec-pill exec-pill-contractor">{esc("У Подрядчика")}</span>'
    if "подписан" in sl or ("согласован" in sl and "на согласован" not in sl) or "утвержд" in sl:
        return f'<span class="exec-pill exec-pill-signed">{esc("Принят")}</span>'
    if "отказ" in sl or "declined" in sl:
        return f'<span class="exec-pill exec-pill-declined">{esc("Отказ")}</span>'
    if "заказчик" in sl and "подряд" not in sl:
        return f'<span class="exec-pill exec-pill-customer">{esc("У Заказчика")}</span>'
    if "подряд" in sl and "заказ" not in sl and ("сдач" in sl or "возврат" in sl or "исправ" in sl):
        return f'<span class="exec-pill exec-pill-contractor">{esc("У Подрядчика")}</span>'
    return f'<span class="exec-pill exec-pill-default">{esc(s)}</span>'


def _exec_delay_cell_html(val: str) -> str:
    """Просрочка: выделение цианом для значений вида «+2 дня», «5 дн.»."""
    esc = html_module.escape
    s = str(val or "").strip()
    if not s or s == "—":
        return f'<span class="exec-dash">{esc("—")}</span>'
    if re.search(r"^[\d\s\+\-]+.*дн", s, re.I):
        return f'<span class="exec-delay-val">{esc(s)}</span>'
    return esc(s)


def _exec_int_str(v) -> str:
    """№ документа — целое число без дробной части (451.0 → «451»). ТЗ ИД, п.3."""
    if v is None:
        return ""
    try:
        if pd.isna(v):
            return ""
    except Exception:
        pass
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "nat"):
        return ""
    try:
        f = float(s.replace(" ", "").replace(",", "."))
        if f == int(f):
            return str(int(f))
    except (ValueError, TypeError):
        pass
    return re.sub(r"[.,]0+$", "", s)


def _exec_query_param_value(name: str, default: str = "") -> str:
    try:
        val = st.query_params.get(name, default)
    except Exception:
        return default
    if isinstance(val, list):
        return str(val[0]) if val else default
    return str(val)


def _exec_sort_link(column: str, current_sort: str, current_order: str) -> str:
    next_order = "desc" if current_sort == column and current_order == "asc" else "asc"
    params = {}
    try:
        params.update(st.query_params.to_dict())
    except Exception:
        pass
    params["exec_sort"] = column
    params["exec_order"] = next_order
    return "?" + urlencode(params, doseq=True)


def _exec_sort_series(df: pd.DataFrame, column: str) -> pd.Series:
    if column not in df.columns:
        return pd.Series(range(len(df)), index=df.index)
    if column in {
        "Плановая дата сдачи",
        "Факт сдачи",
        "Дата передачи заказчику",
        "Дата согласования",
        "Дата создания",
    }:
        return pd.to_datetime(df[column], errors="coerce", dayfirst=True)
    if column in {"Просрочка сдачи", "Просрочка соглас."}:
        return (
            df[column]
            .astype(str)
            .str.extract(r"(-?\d+)", expand=False)
            .pipe(pd.to_numeric, errors="coerce")
        )
    return df[column].astype(str).str.casefold()


def _exec_sort_table_df(df: pd.DataFrame, sort_col: str, sort_order: str) -> pd.DataFrame:
    if df is None or df.empty or sort_col not in df.columns:
        return df
    work = df.copy()
    work["_exec_sort_key"] = _exec_sort_series(work, sort_col)
    ascending = str(sort_order).lower() != "desc"
    work = work.sort_values(
        by=["_exec_sort_key", sort_col],
        ascending=[ascending, ascending],
        na_position="last",
        kind="mergesort",
    )
    return work.drop(columns=["_exec_sort_key"], errors="ignore")


def _exec_detail_col_class(col_name: str) -> str:
    """Класс колонки для фиксированного layout (узкие даты/цифры, шире — текст/объекты)."""
    c = str(col_name or "").strip()
    cl = c.casefold()
    if c == "№" or c.startswith("№") or c.startswith("No") or c.startswith("NO"):
        return "exec-col-num"
    if "дата" in cl or "date" in cl:
        return "exec-col-date"
    if "просроч" in cl or "срок" in cl or "delay" in cl or "overdue" in cl:
        return "exec-col-dly"
    if c == "Статус" or "статус" in cl or "state" in cl:
        return "exec-col-st"
    if any(k in cl for k in ("объект", "контрагент", "подряд", "документ", "наимен", "тем", "соглас", "переда", "выпуск")):
        return "exec-col-text"
    if any(k in cl for k in ("id", "ид", "карточ", "номер", "кол-во", "сумм")):
        return "exec-col-num"
    return "exec-col-text"


def _exec_detail_col_width(col_name: str) -> str:
    """Ширина колонки для colgroup — шапка и тело совпадают при прокрутке."""
    c = str(col_name or "").strip()
    cl = c.casefold()
    if c == "Контрагент":
        return "22ch"
    if c == "Объект":
        return "14ch"
    if c in {"№ документа", "Тип"} or c.startswith("№"):
        return "11ch"
    if "дата" in cl or c in {"Плановая дата сдачи", "Факт сдачи", "Дата создания"}:
        return "13ch"
    if "просроч" in cl:
        return "12ch"
    if c == "Статус":
        return "12em"
    return "16ch"


def _exec_metric_cards_html(cards: list[dict], *, caption: str | None = None) -> str:
    esc = html_module.escape
    parts = ['<div class="exec-kpi-grid">']
    for card in cards:
        tone = str(card.get("tone") or "").strip()
        title = esc(str(card.get("title", "")))
        value = esc(str(card.get("value", "—")))
        subtitle = esc(str(card.get("subtitle", "")).strip())
        delta = str(card.get("delta") or "").strip()
        delta_cls = ""
        if delta:
            delta_cls = "exec-kpi-delta-pos" if not delta.startswith("-") else "exec-kpi-delta-neg"
        parts.append(f'<div class="exec-kpi-card {"exec-kpi-" + tone if tone else ""}">')
        parts.append(f'<div class="exec-kpi-title">{title}</div>')
        parts.append(f'<div class="exec-kpi-value">{value}</div>')
        if delta:
            parts.append(f'<div class="{delta_cls}">{esc(delta)}</div>')
        if subtitle:
            parts.append(f'<div class="exec-kpi-subtitle">{subtitle}</div>')
        parts.append("</div>")
    parts.append("</div>")
    if caption:
        parts.append(f'<div class="exec-doc-caption">{esc(caption)}</div>')
    return _exec_css_for_theme(_EXEC_DOC_KPI_CSS) + "".join(parts)


def _exec_cell_sort_attr(col: str, row: pd.Series) -> str:
    """data-sort-val для клиентской сортировки (даты, просрочки)."""
    c = str(col).strip()
    if c in {
        "Плановая дата сдачи",
        "Факт сдачи",
        "Дата передачи заказчику",
        "Дата согласования",
        "Дата создания",
    }:
        ts = pd.to_datetime(row.get(c), errors="coerce", dayfirst=True)
        if pd.notna(ts):
            return f' data-sort-val="{float(ts.timestamp())}"'
    if c in {"Просрочка сдачи", "Просрочка соглас."}:
        m = re.search(r"-?\d+", str(row.get(c, "")).replace("\xa0", ""))
        if m:
            return f' data-sort-val="{int(m.group())}"'
    if c == "№ документа":
        m = re.search(r"-?\d+(?:[.,]\d+)?", str(row.get(c, "")).replace("\xa0", ""))
        if m:
            try:
                return f' data-sort-val="{float(m.group().replace(",", "."))}"'
            except (TypeError, ValueError):
                pass
    return ""


def _exec_detail_table_html(
    df: pd.DataFrame,
    max_rows: int = 500,
) -> str:
    """HTML-таблица детального отчёта ИД (клиентская сортировка по клику на заголовок)."""
    esc = html_module.escape
    header_alias = {
        "Контрагент": "Контрагент",
        "Объект": "Объект",
        "№ документа": "№ док",
        "Тип": "Тип",
        "Плановая дата сдачи": "План сдачи",
        "Факт сдачи": "Факт сдачи",
        "Просрочка сдачи": "Проср. сдачи",
        "Дата передачи заказчику": "Передача ЗК",
        "Дата согласования": "Согласование",
        "Просрочка соглас.": "Проср. согл.",
        "Статус": "Статус",
        "Дата создания": "Создан",
    }
    if df is None or df.empty:
        return f'<p style="color:{_exec_muted_text_color()};padding:12px;">{esc("Нет строк для отображения.")}</p>'
    show = df.head(max_rows)
    cols = list(show.columns)
    colgroup = ["<colgroup>"]
    for c in cols:
        w = _exec_detail_col_width(c)
        colgroup.append(f'<col style="width:{html_module.escape(w, quote=True)};">')
    colgroup.append("</colgroup>")
    head_parts = ["<thead><tr>"]
    for c in cols:
        c_cls = _exec_detail_col_class(c)
        caption = header_alias.get(str(c).strip(), str(c).strip())
        full_name = str(c).strip()
        head_parts.append(
            f'<th class="{esc(c_cls, quote=True)}" data-sort-label="{esc(full_name, quote=True)}" '
            f'title="{esc(full_name, quote=True)}">{esc(caption)}</th>'
        )
    head_parts.append("</tr></thead>")
    thead = "".join(head_parts)
    delay_cols = {"Просрочка сдачи", "Просрочка соглас."}
    status_col = "Статус"
    body_parts = ["<tbody>"]
    for _, row in show.iterrows():
        body_parts.append("<tr>")
        for c in cols:
            v = row.get(c, "")
            if pd.isna(v):
                v = ""
            raw = str(v) if v is not None else ""
            if c == status_col:
                inner = _exec_status_pill_html(raw)
            elif c in delay_cols:
                inner = _exec_delay_cell_html(raw)
            else:
                inner = esc(raw)
            c_cls = _exec_detail_col_class(c)
            sort_attr = _exec_cell_sort_attr(c, row)
            body_parts.append(f'<td class="{esc(c_cls, quote=True)}"{sort_attr}>{inner}</td>')
        body_parts.append("</tr>")
    body_parts.append("</tbody>")
    # ТЗ (скриншот, п.5): вертикальная прокрутка детальной таблицы (липкая шапка,
    # ограниченная высота) — класс exec-doc-scroll-wrap (не pred-detail-wrap).
    return (
        f'<div class="exec-doc-table-wrap exec-doc-scroll-wrap" data-bi-rows="{len(show)}" data-scroll-box-h="576">'
        '<table class="exec-doc-table bi-sortable-table bi-sort-click-only">'
        + "".join(colgroup)
        + thead
        + "".join(body_parts)
        + "</table></div>"
    )



def _exec_granularity_freq_map() -> dict[str, str]:
    """Подпись UI → код частоты pandas Period."""
    return {
        "День": "D",
        "Неделя": "W-MON",
        "Месяц": "M",
        "Квартал": "Q-DEC",
        "Год": "Y-DEC",
    }


def _exec_period_human_label(p: pd.Period) -> str:
    """Человекочитаемая метка периода для сравнения «к предыдущему»."""
    try:
        if not isinstance(p, pd.Period):
            return str(p)
        f = str(getattr(p, "freqstr", "") or getattr(p.freq, "freqstr", "") or "")
        fs = f.upper()
        if fs.startswith("Y"):
            return str(int(p.year))
        if fs.startswith("Q"):
            return f"{int(p.year)} Q{int(p.quarter)}"
        if fs.startswith("W"):
            st_d = p.start_time.strftime("%d.%m.%Y")
            en_d = p.end_time.strftime("%d.%m.%Y")
            return f"Неделя {int(p.week)} ({st_d}—{en_d})"
        if fs.startswith("D"):
            return p.strftime("%d.%m.%Y")
        return f"{RUSSIAN_MONTHS.get(p.month, str(p.month))} {p.year}"
    except Exception:
        return str(p)


def _exec_enrich_task_and_contract_dates(work: pd.DataFrame) -> pd.DataFrame:
    """Даты из `tessa_*task*.csv` и договорные даты ИД из `1с_*_Dogovor.json` (ТЗ ИД)."""
    out = work.copy()
    out["_exec_transfer_customer_dt"] = pd.NaT
    out["_exec_accept_print_dt"] = pd.NaT
    out["_dog_contract_end_dt"] = pd.NaT
    out["_dog_id_received_dt"] = pd.NaT

    doc_side_col = _tessa_find_column(
        out,
        ["DocID", "DocId", "DocumentID", "DocumentId", "ИдДокумента"],
    )
    card_side_col = _tessa_find_column(
        out,
        ["CardId", "CardID", "cardId", "ИдКарточки"],
    )

    try:
        tasks = st.session_state.get("tessa_tasks_data")
    except Exception:
        tasks = None
    if tasks is not None and not getattr(tasks, "empty", True):
        try:
            t = tasks.copy()
        except Exception:
            t = None
        if t is not None:
            t.columns = [str(c).strip() for c in t.columns]
            oc = _tessa_find_column(t, ["OptionCaption", "optioncaption", "Option"])
            comp = _tessa_find_column(
                t, ["Completed", "CompletionDate", "ДатаЗавершения", "Дата завершения"]
            )
            cid = _tessa_find_column(t, ["CardId", "CardID", "cardId", "ИдКарточки"])
            if oc and comp and cid:
                toc = t[oc].astype(str).str.strip().str.casefold()
                tcomp = pd.to_datetime(t[comp], errors="coerce", dayfirst=True)
                agree_mask = toc.str.contains("на согласование", na=False)
                print_mask = toc.str.contains("печатн", na=False) & toc.str.contains(
                    "форм", na=False
                )

                def _agg_min_dates(mask: pd.Series) -> dict[str, pd.Timestamp]:
                    sub = t.loc[mask].copy()
                    sub["_tc"] = tcomp.loc[mask]
                    sub = sub[sub["_tc"].notna()]
                    if sub.empty:
                        return {}
                    gb = sub.groupby(cid, dropna=False)["_tc"].min()
                    mp: dict[str, pd.Timestamp] = {}
                    for raw_k, dt in zip(gb.index.tolist(), gb.values.tolist()):
                        nk = _tessa_norm_join_key(raw_k)
                        if not nk or pd.isna(dt):
                            continue
                        if nk not in mp or dt < mp[nk]:
                            mp[nk] = dt
                    return mp

                mp_ag = _agg_min_dates(agree_mask)
                mp_pf = _agg_min_dates(print_mask)

                def _pick_dt(row, mp: dict[str, pd.Timestamp]):
                    for c in (doc_side_col, card_side_col):
                        if c and c in row.index:
                            nk = _tessa_norm_join_key(row.get(c))
                            if nk and nk in mp:
                                return mp[nk]
                    return pd.NaT

                if mp_ag:
                    out["_exec_transfer_customer_dt"] = out.apply(
                        lambda r: _pick_dt(r, mp_ag), axis=1
                    )
                if mp_pf:
                    out["_exec_accept_print_dt"] = out.apply(
                        lambda r: _pick_dt(r, mp_pf), axis=1
                    )

    try:
        lk_dog = _load_dogovor_lookup() or {}
    except Exception:
        lk_dog = {}
    dog_id_col = _tessa_find_column(out, ["1C_ID_DOG", "1C_ID_Dog", "1c_id_dog"])
    if lk_dog and dog_id_col and dog_id_col in out.columns:

        def _dog_pair(v) -> tuple[pd.Timestamp, pd.Timestamp]:
            key = str(v or "").strip().lower()
            rec = lk_dog.get(key) if key else None
            if not isinstance(rec, dict):
                return (pd.NaT, pd.NaT)
            end_raw = rec.get("Дата_Окончания_Договора") or ""
            recv_raw = rec.get("Дата_Получения_ИД") or ""
            end_dt = pd.to_datetime(end_raw, errors="coerce", dayfirst=True)
            recv_dt = pd.to_datetime(recv_raw, errors="coerce", dayfirst=True)
            return (end_dt, recv_dt)

        pairs = out[dog_id_col].apply(_dog_pair)
        out["_dog_contract_end_dt"] = pairs.map(lambda x: x[0])
        out["_dog_id_received_dt"] = pairs.map(lambda x: x[1])

    return out


