def _exec_doc_kinds_catalog_df() -> pd.DataFrame:
    """Справочник видов документов ИД (`web/ExecDocKinds.csv`)."""
    ref = None
    try:
        ref = st.session_state.get("reference_execdockinds")
    except Exception:
        ref = None
    if ref is not None and isinstance(ref, pd.DataFrame) and not ref.empty:
        out = ref.copy()
    else:
        from pathlib import Path as _Path

        _p = _Path(__file__).resolve().parent.parent / "web" / "ExecDocKinds.csv"
        if _p.is_file():
            try:
                from web_loader import _load_reference_csv

                loaded = _load_reference_csv(_p)
                if loaded is not None and not loaded.empty:
                    out = loaded.copy()
                else:
                    out = _EXEC_DOC_KINDS_DEFAULT.copy()
            except Exception:
                out = _EXEC_DOC_KINDS_DEFAULT.copy()
        else:
            out = _EXEC_DOC_KINDS_DEFAULT.copy()
    out.columns = [str(c).replace("\ufeff", "").strip() for c in out.columns]
    if "KindName" not in out.columns:
        return _EXEC_DOC_KINDS_DEFAULT.copy()
    out["KindName"] = out["KindName"].astype(str).str.strip()
    return out.drop_duplicates(subset=["KindName"], keep="first").reset_index(drop=True)


def _exec_doc_kind_in_report_flag(row: pd.Series) -> bool:
    flag_col = next(
        (c for c in row.index if "отч" in str(c).lower() and "ид" in str(c).lower()),
        "В отчёте ИД",
    )
    val = str(row.get(flag_col, "да")).strip().lower()
    return val not in ("нет", "no", "0", "false", "-", "")


def _exec_doc_kind_filter_options(
    work: pd.DataFrame,
    kind_col: str | None,
    catalog_df: pd.DataFrame,
) -> list[str]:
    """Варианты фильтра «Вид документа» — уникальные группы из справочника."""
    opts: list[str] = []
    seen: set[str] = set()
    if catalog_df is not None and not catalog_df.empty and "KindName" in catalog_df.columns:
        group_col = "Группа" if "Группа" in catalog_df.columns else None
        for _, r in catalog_df.iterrows():
            if not _exec_doc_kind_in_report_flag(r):
                continue
            if group_col:
                label = str(r.get(group_col, "")).strip()
            else:
                label = str(r.get("KindName", "")).strip()
            if not label or label in seen:
                continue
            opts.append(label)
            seen.add(label)
        if opts:
            return opts
    if not kind_col or kind_col not in work.columns:
        return []
    return sorted(
        {
            str(v).strip()
            for v in work[kind_col].dropna().astype(str)
            if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
        },
        key=lambda x: x.casefold(),
    )


def _exec_doc_kind_names_for_filter_label(label: str, catalog_df: pd.DataFrame) -> set[str]:
    """KindName, попадающие под выбранную группу (или точное имя без справочника)."""
    if not label or label == "Все":
        return set()
    if catalog_df is None or catalog_df.empty or "KindName" not in catalog_df.columns:
        return {label}
    group_col = "Группа" if "Группа" in catalog_df.columns else None
    if group_col:
        names = {
            str(r.get("KindName", "")).strip()
            for _, r in catalog_df.iterrows()
            if _exec_doc_kind_in_report_flag(r)
            and str(r.get(group_col, "")).strip() == label
            and str(r.get("KindName", "")).strip()
        }
        if names:
            return names
    return {label}


def _exec_doc_kinds_catalog_display(
    work: pd.DataFrame,
    kind_col: str | None,
    catalog_df: pd.DataFrame,
) -> pd.DataFrame:
    disp = catalog_df.copy()
    counts: dict[str, int] = {}
    if kind_col and kind_col in work.columns:
        counts = {
            str(k).strip(): int(v)
            for k, v in work[kind_col].astype(str).str.strip().value_counts().items()
        }
    disp["Строк в данных"] = disp["KindName"].astype(str).str.strip().map(
        lambda k: counts.get(k, 0)
    )
    known = set(disp["KindName"].astype(str).str.strip())
    extra_rows = []
    for k, n in sorted(counts.items(), key=lambda x: (-x[1], x[0].casefold())):
        if not k or k in known:
            continue
        if "предписан" in k.casefold():
            continue
        extra_rows.append(
            {
                "KindName": k,
                "Группа": k,
                "Описание": "Не описан в справочнике — добавьте строку в ExecDocKinds.csv",
                "В отчёте ИД": "да",
                "Строк в данных": int(n),
            }
        )
    if extra_rows:
        disp = pd.concat([disp, pd.DataFrame(extra_rows)], ignore_index=True)
    return disp


# ==================== DASHBOARD: Исполнительная документация (отдельный отчёт в группе «Прочее») ====================
def dashboard_executive_documentation(df):
    """
    Отчёт «Исполнительная документация» — TESSA.
    Исключаются строки KindName «Предписание» (отдельный отчёт «Предписания»).
    """
    tessa_df = st.session_state.get("tessa_data", None)
    work = None
    _source_label = ""
    if tessa_df is not None and not tessa_df.empty:
        work = tessa_df.copy()
        _source_label = "TESSA (session_state: tessa_data)"
    elif df is not None and not getattr(df, "empty", True):
        # F1: fallback — если TESSA не попала в session_state, но текущий датасет уже TESSA-выгрузка.
        _tessa_like = _tessa_find_column(df, ["KindName", "ObjectName", "CardId", "DocID", "KrStateID"])
        if _tessa_like:
            work = df.copy()
            _source_label = "TESSA (текущий загруженный файл)"
    if work is None or work.empty:
        st.warning(
            "Для отчёта «Исполнительная документация» необходимы данные из TESSA. "
            "Загрузите файлы tessa_*.csv через папку web/."
        )
        return

    work.columns = [str(c).strip() for c in work.columns]
    try:
        from web_loader import _tessa_drop_cancelled_tag_rows

        work = _tessa_drop_cancelled_tag_rows(work)
    except Exception:
        pass
    try:
        # Дополняем строки ИД данными карточки/задачи TESSA по ключам DocID/CardId.
        # Это выравнивает поля сроков, передачи заказчику и согласования с фактическими данными TESSA.
        work = _tessa_fill_card_from_doc_lookup(work)
    except Exception:
        pass

    kind_col = _tessa_find_column(work, ["KindName", "kindname", "Вид"])
    if kind_col:
        mask_pred = work[kind_col].astype(str).str.contains("Предписан", case=False, na=False)
        work = work[~mask_pred].reset_index(drop=True)

    # КРИТИЧНЫЙ ФИКС B-14 (08.05.2026 v2): web_loader сшивает в `tessa_data` строки
    # из `tessa_*-id.csv` И `tessa_*-rd.csv` (рабочая документация) без разделения.
    # Для B-14 «Исполнительная документация» нужны ТОЛЬКО строки из -id.csv.
    # Точный признак строк -id.csv (отсутствуют в -rd.csv): **наличие KrStateID или
    # KindName**. KrState заполнен и в rd-файлах (свои статусы РД: Проект/Отмена/
    # На ознакомлении/Согласован/...), поэтому фильтрация по KrState не сработала.
    _has_krsid = "KrStateID" in work.columns
    _has_kind = kind_col is not None and kind_col in work.columns
    if _has_krsid or _has_kind:
        _mask_id = pd.Series(False, index=work.index)
        if _has_krsid:
            _mask_id = _mask_id | work["KrStateID"].notna()
        if _has_kind:
            _mask_id = _mask_id | (
                work[kind_col].notna()
                & (~work[kind_col].astype(str).str.strip().isin(["", "nan", "None", "NaN"]))
            )
        work = work[_mask_id].reset_index(drop=True)

    obj_col = _tessa_find_column(work, ["ObjectName", "objectname", "Объект"])
    if obj_col:
        work = work[
            work[obj_col].notna()
            & (~work[obj_col].astype(str).str.strip().isin(["", "nan", "None", "NaN"]))
        ].reset_index(drop=True)

    if work.empty:
        st.info("Нет данных по исполнительной документации (после исключения предписаний и пустых объектов).")
        return

    try:
        work = _exec_enrich_task_and_contract_dates(work)
    except Exception:
        pass

    work["Статус"] = _tessa_resolve_status_series(work)

    work = _tessa_drop_project_state_rows(work)
    _proj_lookup_exec, _, _ = _pred_projekts_1c_lookup()
    if obj_col and obj_col in work.columns and _proj_lookup_exec:
        work[obj_col] = _resolve_project_display_labels(work[obj_col], _proj_lookup_exec)
    work = _pred_filter_by_projekts_registry(work, obj_col)
    if obj_col and obj_col in work.columns:
        work = work[
            ~work[obj_col].astype(str).str.strip().isin(MSP_PROJECT_FILTER_EXCLUDE_NAMES)
        ].reset_index(drop=True)
    if work.empty:
        st.info("Нет данных по проектам из справочника 1с_*_Projekts.json (после исключения тестовых объектов).")
        return

    _contr_candidates = ["CONTR", "Контрагент", "contr"]
    contr_col = _tessa_find_column(work, _contr_candidates)
    card_col = _tessa_find_column(work, ["CardId", "CardID", "cardId", "DocID", "DocId"])
    creation_col = _tessa_find_column(work, ["CreationDate", "creationdate", "Дата создания"])
    completed_col = _tessa_find_column(work, ["Completed", "completed", "CompletionDate", "Дата завершения"])
    plan_col = _tessa_find_column(work, ["id_Deadline", "id_deadline"])
    if not plan_col:
        plan_col = _tessa_find_column(work, ["PlanDate", "DueDate", "Срок", "Плановая дата"])
    transfer_col = _tessa_find_column(
        work,
        ["TransferToCustomer", "Дата передачи", "Передача заказчику", "DateToCustomer", "ПереданоЗаказчику"],
    )
    agree_col = _tessa_find_column(
        work,
        ["AgreementDate", "Дата согласования", "Согласовано", "ApprovalDate", "Дата подписания заказчиком"],
    )

    _fce = pd.Series(pd.NaT, index=work.index)
    if "_exec_accept_print_dt" in work.columns:
        _fce = pd.to_datetime(work["_exec_accept_print_dt"], errors="coerce", dayfirst=True)
    if completed_col and completed_col in work.columns:
        _fce = _fce.fillna(pd.to_datetime(work[completed_col], errors="coerce", dayfirst=True))
    work["_fact_completed_eff"] = _fce
    completed_eff_col = "_fact_completed_eff"

    _tre = pd.Series(pd.NaT, index=work.index)
    if "_exec_transfer_customer_dt" in work.columns:
        _tre = pd.to_datetime(work["_exec_transfer_customer_dt"], errors="coerce", dayfirst=True)
    if transfer_col and transfer_col in work.columns:
        _tre = _tre.fillna(pd.to_datetime(work[transfer_col], errors="coerce", dayfirst=True))
    work["_transfer_eff"] = _tre
    transfer_eff_col = "_transfer_eff"

    if creation_col:
        work["_cd"] = _tessa_to_datetime(work[creation_col])
    else:
        work["_cd"] = pd.NaT

    dmin = work["_cd"].min()
    dmax = work["_cd"].max()
    today = date.today()

    with filters_panel(
        st,
        reset_keys=[
            "exec_doc_object", "exec_doc_contr", "exec_doc_kind",
            "exec_doc_period", "exec_doc_granularity", "exec_doc_hide_overdue_signed",
        ],
        reset_defaults={
            "exec_doc_object": "Все",
            "exec_doc_contr": "Все",
            "exec_doc_kind": "Все",
            "exec_doc_granularity": "Месяц",
            "exec_doc_hide_overdue_signed": True,
        },
    ):
        # ТЗ (скриншот): блок фильтров как в «Отклонение от базового плана» —
        # все селекторы одной шириной в одну линию, чекбоксы отдельным блоком.
        _exec_kinds_catalog = _exec_doc_kinds_catalog_df()
        fc1, fc2, fc3, fc4, fc5 = st.columns(5, gap="small")
        with fc1:
            if obj_col:
                _exec_proj_opts = sorted(
                    set(_proj_lookup_exec.values()) if _proj_lookup_exec else set(),
                    key=lambda x: str(x).casefold(),
                )
                if not _exec_proj_opts:
                    _exec_proj_opts = _unique_project_labels_for_select(work[obj_col])
                objects = ["Все"] + _exec_proj_opts
                sel_obj = st.selectbox("Проект", objects, key="exec_doc_object")
            else:
                sel_obj = "Все"
        with fc2:
            if contr_col:
                contrs = ["Все"] + sorted(work[contr_col].dropna().astype(str).str.strip().unique().tolist())
                sel_contr = st.selectbox("Контрагент", contrs, key="exec_doc_contr")
            else:
                sel_contr = "Все"
        with fc3:
            if kind_col:
                kinds = ["Все"] + _exec_doc_kind_filter_options(work, kind_col, _exec_kinds_catalog)
                sel_kind = st.selectbox(
                    "Вид документа",
                    kinds,
                    key="exec_doc_kind",
                    help="Группы из справочника ExecDocKinds.csv (синонимы KindName объединены)",
                )
            else:
                sel_kind = "Все"
        with fc4:
            if pd.notna(dmin) and pd.notna(dmax):
                min_date = dmin.date() if hasattr(dmin, "date") else dmin
                max_date = dmax.date() if hasattr(dmax, "date") else dmax
                dr = st.date_input(
                    "Период",
                    value=(min_date, max_date),
                    min_value=min_date,
                    max_value=max_date,
                    key="exec_doc_period",
                    format="DD.MM.YYYY",
                )
                if isinstance(dr, tuple) and len(dr) == 2:
                    p_start, p_end = dr
                else:
                    p_start, p_end = dr, dr
            else:
                p_start = p_end = None
                with st.expander("Период по дате создания", expanded=False):
                    suppress_caption("В данных нет распознанной колонки даты создания — период не применяется.")
        with fc5:
            _gran_opts = list(_exec_granularity_freq_map().keys())
            try:
                _gi = _gran_opts.index("Месяц")
            except ValueError:
                _gi = min(2, max(len(_gran_opts) - 1, 0))
            st.selectbox(
                "Гранулярность",
                options=_gran_opts,
                index=_gi,
                key="exec_doc_granularity",
                help="Шаг агрегации для вкладки «Динамика».",
            )
        with filters_toggles(st):
            hide_overdue_if_done = st.checkbox(
                "Не отображать просрочку, если ИД сдана (подписана/согласована)",
                value=True,
                key="exec_doc_hide_overdue_signed",
            )

    suppress_caption(
        "Маппинг ИД: тип (`KindName`) и статус — из `tessa_*-id.csv`; справочник видов — `web/ExecDocKinds.csv`; "
        "крайний срок подписания — `id_Deadline`; "
        "передача заказчику — задача «На согласование» в `tessa_*-task.csv` (`Completed`); приёмка комплекта — "
        "«Печатная форма создана» (`Completed`); просрочка сдачи по договору — `Дата_Окончания_Договора` vs "
        "`Дата_Получения_ИД` в `1с_*_Dogovor.json` (поле связи `1C_ID_DOG`). Просрочка заказчика — уточняется (TBD)."
    )

    with st.expander("Справочник видов документов ИД", expanded=False):
        _exec_cat_disp = _exec_doc_kinds_catalog_display(work, kind_col, _exec_kinds_catalog)
        st.caption(
            "Файл `web/ExecDocKinds.csv`: соответствие KindName из TESSA группам отчёта "
            "(Комплект ИД, КС, Отказы). Колонка «Строк в данных» — по текущей выгрузке до фильтров."
        )
        render_report_html_table(
            format_dataframe_as_html(_exec_cat_disp),
            export_df=_exec_cat_disp,
            file_stem="exec_doc_kinds",
            key_prefix="exec_doc_kinds_ref",
        )

    filtered_base = work.copy()
    if sel_obj != "Все" and obj_col:
        filtered_base = _filter_df_by_norm_key_col(filtered_base, obj_col, sel_obj)
    if sel_contr != "Все" and contr_col:
        filtered_base = filtered_base[filtered_base[contr_col].astype(str).str.strip() == sel_contr]
    if sel_kind != "Все" and kind_col:
        _kind_names = _exec_doc_kind_names_for_filter_label(sel_kind, _exec_kinds_catalog)
        filtered_base = filtered_base[
            filtered_base[kind_col].astype(str).str.strip().isin(_kind_names)
        ]

    # tessa_data объединяет все snapshot-файлы → один документ может иметь несколько
    # записей (по дате snapshot). Для «текущего состояния» (карточки, бар-чарт
    # по статусам, по объектам) нужна одна запись на документ — последняя по snapshot.
    # Колонка `Import_data` — дата snapshot файла (присутствует во всех TESSA-CSV).
    def _latest_snapshot(dfp: pd.DataFrame) -> pd.DataFrame:
        if dfp is None or dfp.empty or not card_col or card_col not in dfp.columns:
            return dfp
        sort_cols = []
        if "Import_data" in dfp.columns:
            dfp = dfp.assign(_imp_dt=pd.to_datetime(dfp["Import_data"], errors="coerce", dayfirst=True))
            sort_cols.append("_imp_dt")
        if "_cd" in dfp.columns:
            sort_cols.append("_cd")
        if not sort_cols:
            return dfp.drop_duplicates(subset=[card_col], keep="last").reset_index(drop=True)
        out = (
            dfp.sort_values(sort_cols, kind="stable")
            .drop_duplicates(subset=[card_col], keep="last")
            .reset_index(drop=True)
        )
        if "_imp_dt" in out.columns:
            out = out.drop(columns=["_imp_dt"], errors="ignore")
        return out

    filtered_cumulative = _latest_snapshot(filtered_base.copy())

    filtered_period = filtered_base.copy()
    if creation_col and p_start is not None and p_end is not None:
        ts_start = pd.Timestamp(p_start)
        ts_end = pd.Timestamp(p_end) + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)
        filtered_period = filtered_period[
            filtered_period["_cd"].notna()
            & (filtered_period["_cd"] >= ts_start)
            & (filtered_period["_cd"] <= ts_end)
        ]
    filtered_period = _latest_snapshot(filtered_period)
    filtered_history = filtered_period.copy()
    filtered = filtered_cumulative

    if filtered.empty:
        _empty_reasons = []
        _full_n = int(len(work))
        _base_n = int(len(filtered_base))
        if _base_n == 0:
            if sel_obj != "Все":
                _empty_reasons.append(f"для объекта «{sel_obj}»")
            if sel_contr != "Все":
                _empty_reasons.append(f"для контрагента «{sel_contr}»")
            if sel_kind != "Все":
                _empty_reasons.append(f"для вида документа «{sel_kind}»")
        else:
            _date_str = (
                f"{p_start.strftime('%d.%m.%Y') if hasattr(p_start, 'strftime') else p_start}"
                f" — {p_end.strftime('%d.%m.%Y') if hasattr(p_end, 'strftime') else p_end}"
            ) if (p_start is not None and p_end is not None) else "выбранный диапазон"
            _empty_reasons.append(f"в периоде {_date_str}")
        _why = " и ".join(_empty_reasons) if _empty_reasons else "при выбранных фильтрах"
        _suggestion = (
            "Сбросьте лишние фильтры или расширьте период"
            if _base_n == 0 or pd.notna(dmin)
            else "Загрузите свежие файлы tessa_*.csv через папку web/"
        )
        st.warning(
            f"Нет документов {_why}. Всего в источнике: {_full_n} строк. {_suggestion}."
        )
        return

    stu = filtered["Статус"].astype(str)
    sl = stu.str.lower()

    def _has_status(s, *parts):
        sl_ = s.lower()
        return any(p.lower() in sl_ for p in parts)

    # ВАЖНО: переходные статусы («На согласовании», «На подписании», «У заказчика»)
    # не финальные «Подписано/Согласовано». Без явного исключения подстрока «согласован»
    # / «подписан» ловит и переходные статусы → метрика «Принято» становится завышенной,
    # а «На согласовании» — заниженной (расходится с оранжевым баром).
    is_on_agree = stu.str.strip().str.casefold().eq("на согласовании")
    is_on_sign = pd.Series(False, index=sl.index)
    is_rework = stu.str.strip().str.casefold().eq("на доработке")
    is_declined = stu.str.strip().str.casefold().eq("отказ")
    is_signed = stu.str.strip().str.casefold().eq("подписан")
    if "KrStateID" in filtered.columns:
        is_signed = is_signed | (pd.to_numeric(filtered["KrStateID"], errors="coerce").eq(8))
    is_signed = is_signed & (~is_on_agree)

    if "KrState" in filtered.columns:
        kb = filtered["KrState"].map(_krstate_bucket)
        # KPI по русским KrState из id.csv (без bucket KrState).

    overdue_mask = (~is_signed) & (~is_declined)
    cnt_c = int((overdue_mask & is_rework).sum())
    cnt_u = int((overdue_mask & is_on_agree).sum())
    total_overdue_two = cnt_c + cnt_u

    if card_col and card_col in filtered.columns:
        total_docs = filtered[card_col].nunique()
    else:
        total_docs = len(filtered)

    render_table_subheader(st, "Исполнительная документация накопительно")
    summary_cards = [
        {"title": "Всего документов", "value": int(total_docs), "subtitle": "Уникальные документы в текущей выборке"},
        {"title": "Отказы", "value": int(is_declined.sum()), "subtitle": "Документы со статусом отказа", "tone": "alert"},
        {"title": "На согласовании", "value": int(is_on_agree.sum()), "subtitle": "Документы у заказчика", "tone": "warn"},
        {"title": "Принято", "value": int(is_signed.sum()), "subtitle": "Только статус «Подписан»", "tone": "ok"},
        {"title": "У подрядчика", "value": int(is_rework.sum()), "subtitle": "Документы на доработке"},
        {"title": "Всего просрочек", "value": int(total_overdue_two), "subtitle": "Подрядчик + заказчик", "tone": "alert"},
    ]
    st.markdown(
        _exec_metric_cards_html(summary_cards),
        unsafe_allow_html=True,
    )

    oc1, oc2 = st.columns(2, gap="small")

    def _exec_ts_naive_norm(ts) -> pd.Timestamp:
        """Приводит значение к timezone-naive Timestamp (полночь), чтобы безопасно вычитать даты."""
        if ts is None or pd.isna(ts):
            return pd.NaT
        try:
            t = pd.Timestamp(ts)
        except Exception:
            return pd.NaT
        if getattr(t, "tzinfo", None) is not None:
            try:
                t = t.tz_convert("UTC").replace(tzinfo=None)
            except Exception:
                try:
                    t = pd.Timestamp(ts.to_pydatetime().replace(tzinfo=None))
                except Exception:
                    return pd.NaT
        try:
            return t.normalize()
        except Exception:
            return pd.NaT

    def _row_days_late_plan(r):
        if not plan_col:
            return np.nan
        pdt = _tessa_to_datetime(pd.Series([r.get(plan_col)])).iloc[0]
        if pd.isna(pdt):
            return np.nan
        pday = pdt.date() if hasattr(pdt, "date") else pdt
        eff_c = completed_eff_col if completed_eff_col in r.index else None
        if eff_c:
            fdt = _tessa_to_datetime(pd.Series([r.get(eff_c)])).iloc[0]
            if pd.notna(fdt):
                fday = fdt.date() if hasattr(fdt, "date") else fdt
                return max(0, (fday - pday).days)
        return max(0, (today - pday).days)

    def _row_contractor_late_days(r):
        ed = r.get("_dog_contract_end_dt")
        if pd.notna(ed):
            ed_ts = _exec_ts_naive_norm(ed)
            if pd.isna(ed_ts):
                pass
            else:
                rd = r.get("_dog_id_received_dt")
                if pd.notna(rd):
                    rd_ts = _exec_ts_naive_norm(rd)
                    if not pd.isna(rd_ts):
                        return float(max(0, (rd_ts - ed_ts).days))
                today_n = _exec_ts_naive_norm(pd.Timestamp.combine(today, datetime.min.time()))
                if not pd.isna(today_n):
                    return float(max(0, (today_n - ed_ts).days))
        base = _row_days_late_plan(r)
        return float(base) if pd.notna(base) else np.nan

    with oc1:
        st.subheader("Просрочка подрядчика (сдача ИД)")
        st.metric("Документов на доработке у подрядчика", cnt_c)
        sub_c = filtered.loc[overdue_mask & is_rework].copy()
        if plan_col and not sub_c.empty:
            sub_c["_late_days"] = sub_c.apply(_row_contractor_late_days, axis=1)
            b1 = int(((sub_c["_late_days"] >= 0) & (sub_c["_late_days"] <= 7)).sum())
            b2 = int(((sub_c["_late_days"] > 7) & (sub_c["_late_days"] <= 30)).sum())
