    with tab_detail:
        st.subheader("Детальный отчёт по сдаче и согласованию ИД")
        disp = filtered.loc[~is_signed].copy()
        rows_out = []
        for _, row in disp.iterrows():
            st_l = str(row.get("Статус", ""))
            st_low = st_l.lower()
