def _sync_multiselect_session_state(
    key: str,
    options: list,
    *,
    all_by_default: bool = True,
) -> None:
    """Сбросить устаревшие значения multiselect после смены списка options."""
    if not options:
        if key in st.session_state:
            st.session_state[key] = []
        return
    opt_set = set(options)
    if key not in st.session_state:
        st.session_state[key] = list(options) if all_by_default else []
        return
    prev = st.session_state.get(key)
    if not isinstance(prev, list):
        st.session_state[key] = list(options) if all_by_default else []
        return
    clean = [v for v in prev if v in opt_set]
    st.session_state[key] = clean if clean else (list(options) if all_by_default else [])


def _sync_selectbox_session_state(
    key: str,
    options: list,
    *,
    fallback: str = "Все",
) -> None:
    """Сбросить устаревшее значение selectbox, если его нет в options."""
    if not options:
        return
    opt_set = set(options)
    fb = fallback if fallback in opt_set else options[0]
    if key not in st.session_state or st.session_state[key] not in opt_set:
        st.session_state[key] = fb


def _pd_msp_immediate_parent_names(
    df: pd.DataFrame, level_col: str, name_col: str
) -> pd.Series:
    """Имя ближайшего родителя по иерархии MSP (порядок строк как в выгрузке)."""
    lv = outline_level_numeric(df[level_col])
    nm = df[name_col].map(lambda x: "" if pd.isna(x) else str(x))
    stack = []
    out = []
    for i in range(len(df)):
        raw_l = lv.iloc[i]
        n = nm.iloc[i] or ""
        if pd.isna(raw_l):
            out.append("")
            continue
        l = float(raw_l)
        while stack and stack[-1][0] >= l:
            stack.pop()
        par = stack[-1][1] if stack else ""
        out.append(par)
        stack.append((l, n))
    return pd.Series(out, index=df.index)


def _pd_msp_hierarchy_cols(df: pd.DataFrame) -> tuple[
    Optional[str], Optional[str], Optional[str], Optional[str], Optional[str]
]:
    """Иерархия MSP: level structure (outline), level (Уровень), task name, block."""
    if df is None or getattr(df, "empty", True):
        return None, None, None, None, None
    ensure_msp_hierarchy_columns(df)
    if "block" not in df.columns:
        for c in df.columns:
            if str(c).strip().casefold() in ("блок", "block"):
                df["block"] = df[c]
                break
    hier_col = "level structure" if "level structure" in df.columns else None
    outline_col = hier_col
    level_col = "level" if "level" in df.columns else None
    name_col = "task name" if "task name" in df.columns else None
    block_col = "block" if "block" in df.columns else None
    return hier_col, outline_col, level_col, name_col, block_col


def _pd_dedupe_msp_tasks_latest(df: pd.DataFrame) -> pd.DataFrame:
    """Оставляет последний снимок MSP по каждой задаче (проект + id) для отчёта ПД."""
    if df is None or getattr(df, "empty", True):
        return df
    out = df.copy()
    if "snapshot_date" not in out.columns:
        out["snapshot_date"] = pd.NaT
    if "__source_file" in out.columns:
        try:
            from web_loader import _parse_snapshot_date
        except Exception:
            _parse_snapshot_date = None  # type: ignore
        if _parse_snapshot_date is not None:
            def _snap_from_src(src) -> pd.Timestamp:
                s = str(src or "")
                m = re.search(r"(\d{2}-\d{2}-\d{4})", s)
                if not m:
                    return pd.NaT
                d = _parse_snapshot_date(m.group(1))
                return pd.Timestamp(d) if d is not None else pd.NaT

            miss = out["snapshot_date"].isna()
            if miss.any():
                out.loc[miss, "snapshot_date"] = out.loc[miss, "__source_file"].map(_snap_from_src)
    out["snapshot_date"] = pd.to_datetime(out["snapshot_date"], errors="coerce")
    pc = "project name" if "project name" in out.columns else None
    id_col = next(
        (c for c in ("unique id", "task id seq", "Ид") if c in out.columns),
        None,
    )
    if not pc or not id_col:
        return out
    ok = out[id_col].notna() & (out[id_col].astype(str).str.strip().ne(""))
    if not ok.any():
        return out
    part_ok = (
        out.loc[ok]
        .sort_values("snapshot_date", ascending=True, kind="mergesort")
        .drop_duplicates(subset=[pc, id_col], keep="last")
    )
    part_miss = out.loc[~ok]
    return pd.concat([part_miss, part_ok]).sort_index().reset_index(drop=True)


def _pd_table_row_mask(df: pd.DataFrame, metrics_mask: pd.Series, dynamics_mask: pd.Series) -> pd.Series:
    """Строки для таблицы ПД: metrics/dynamics (ур.5 + этап ПД + шифр) → fallback шифр."""
    m_met = metrics_mask.fillna(False)
    if m_met.any():
        return m_met
    bcol = _pd_msp_find_baseline_finish_col(df)
    finish = df[bcol] if bcol and bcol in df.columns else pd.Series(pd.NaT, index=df.index)
    chart_mask, _ = _pd_dynamics_chart_row_mask(metrics_mask, dynamics_mask, finish)
    m = chart_mask.fillna(False)
    if m.any():
        return m
    _, cipher_ok = _pd_cipher_filled_mask(df)
    return cipher_ok.fillna(False)


def _pd_msp_ancestor_under_pd_stage(
    df: pd.DataFrame,
    level_col: str,
    name_col: str,
    block_col: Optional[str] = None,
) -> pd.Series:
    """Предок в ветке «Проектная документация» (по стеку) или block=ПД."""
    lv = outline_level_numeric(df[level_col])
    nm = df[name_col].map(lambda x: "" if pd.isna(x) else str(x))
    blk_series = (
        df[block_col].astype(str).str.strip().str.casefold()
        if block_col and block_col in df.columns
        else pd.Series("", index=df.index)
    )
    stack: list[tuple[float, str]] = []
    out: list[bool] = []
    for i in range(len(df)):
        raw_l = lv.iloc[i]
        n = nm.iloc[i] or ""
        if pd.isna(raw_l):
            out.append(False)
            continue
        l = float(raw_l)
        while stack and stack[-1][0] >= l:
            stack.pop()
        ancestors = [s[1] for s in stack]
        is_pd = any(
            "проектная документация" in str(a).casefold()
            for a in ancestors
            if a
        )
        blk = blk_series.iloc[i]
        if blk in ("пд", "пд и рд"):
            is_pd = True
        out.append(is_pd)
        stack.append((l, n))
    return pd.Series(out, index=df.index)


def _pd_msp_parent_is_pd_stage(parent_name: str) -> bool:
    """Родитель ур.4 «Этап … Проектная документация» (без корректировок и смешанных этапов)."""
    s = str(parent_name or "").casefold()
    if "этап" not in s or "проектная документация" not in s:
        return False
    if "корректиров" in s:
        return False
    if "рабоч" in s:
        return False
    return True


def _pd_section_masks(df: pd.DataFrame) -> dict:
    """
    Маски ПД по ТЗ:
    - metrics / dynamics: задачи ур.5 под родителем ур.4 «Этап. Проектная
      документация» с непустым «Шифр ПД и РД» (общее число разделов ПД).
    """
    hier_col, outline_col, level_col, name_col, block_col = _pd_msp_hierarchy_cols(df)
    cipher_col, cipher_ok = _pd_cipher_filled_mask(df)
    empty = pd.Series(False, index=df.index)
    result: dict = {
        "metrics_mask": empty,
        "dynamics_mask": empty,
        "cipher_col": cipher_col,
        "hier_col": hier_col,
        "outline_col": outline_col,
        "level_col": level_col,
        "name_col": name_col,
        "block_col": block_col,
    }
    if (
        not hier_col
        or hier_col not in df.columns
        or not name_col
        or name_col not in df.columns
    ):
        return result
    ancestor_pd = _pd_msp_ancestor_under_pd_stage(
        df, hier_col, name_col, block_col=block_col
    )
    cipher_m = cipher_ok.fillna(False) if cipher_col else empty
    lv_num = (
        outline_level_numeric(df[level_col])
        if level_col and level_col in df.columns
        else pd.Series(np.nan, index=df.index)
    )
    # Стек по outline (level structure): родитель ур.4 «Этап. Проектная документация».
    parent_names = _pd_msp_immediate_parent_names(df, hier_col, name_col)
    parent_pd_stage = parent_names.map(_pd_msp_parent_is_pd_stage)
    # Уровень задачи: колонка «Уровень» (=5), иначе outline=5.
    lv_task = lv_num
    if outline_col and outline_col in df.columns:
        lv_struct = outline_level_numeric(df[outline_col])
        if not lv_task.notna().any():
            lv_task = lv_struct
        else:
            lv_task = lv_task.where(lv_task.notna(), lv_struct)
    tz_mask = lv_task.eq(5) & parent_pd_stage & cipher_m
    if not tz_mask.any():
        # Fallback: ур.5 в ветке ПД с шифром (если имя этапа в выгрузке отличается).
        tz_mask = lv_task.eq(5) & ancestor_pd & cipher_m
    if not tz_mask.any() and cipher_m.any():
        tz_mask = cipher_m
    result["metrics_mask"] = tz_mask
    result["dynamics_mask"] = tz_mask
    return result


def _pd_delay_row_mask(df: pd.DataFrame, masks: dict) -> pd.Series:
    """
    Просрочка ПД: ур.5 под «Этап. Проектная документация» + шифр ПД/РД
    (metrics/dynamics из ``_pd_section_masks``). Без Корректировки/Согласования.
    """
    empty = pd.Series(False, index=df.index)
    m_met = masks.get("metrics_mask", empty).fillna(False)
    dyn = masks.get("dynamics_mask", empty).fillna(False)
    base = m_met if m_met.any() else dyn
    if base.any():
        return base
    hier_col = masks.get("hier_col")
    name_col = masks.get("name_col")
    level_col = masks.get("level_col")
    if (
        not hier_col
        or hier_col not in df.columns
        or not name_col
        or name_col not in df.columns
        or not level_col
        or level_col not in df.columns
    ):
        return empty
    lv = outline_level_numeric(df[level_col])
    parent_names = _pd_msp_immediate_parent_names(df, hier_col, name_col)
    parent_pd_stage = parent_names.map(_pd_msp_parent_is_pd_stage).fillna(False)
    _, cipher_ok = _pd_cipher_filled_mask(df)
    return lv.eq(5) & parent_pd_stage & cipher_ok.fillna(False)


def _pd_delay_chart_source_mask(df: pd.DataFrame, masks: dict) -> pd.Series:
    """Задачи этапа «Проектная документация» с шифром (ур.≥5) — min/max дат на графике.

    Как и `_pd_delay_row_mask`, ограничиваем основным этапом (без Корректировки/
    Согласования/Экспертизы), чтобы диапазон дат совпадал с полосами по проекту.
    """
    empty = pd.Series(False, index=df.index)
    hier_col = masks.get("hier_col")
    name_col = masks.get("name_col")
    level_col = masks.get("level_col")
    block_col = masks.get("block_col")
    if not hier_col or hier_col not in df.columns or not name_col or name_col not in df.columns:
        return empty
    anc = _pd_msp_ancestor_under_pd_stage(
        df, hier_col, name_col, block_col=block_col
    ).fillna(False)
    _, cipher_ok = _pd_cipher_filled_mask(df)
    cipher_m = cipher_ok.fillna(False)
    if level_col and level_col in df.columns:
        lv = pd.to_numeric(df[level_col], errors="coerce")
        base = anc & cipher_m & lv.ge(5)
    else:
        base = anc & cipher_m
    parent_names = _pd_msp_immediate_parent_names(df, hier_col, name_col)
    parent_pd_stage = parent_names.map(_pd_msp_parent_is_pd_stage).fillna(False)
    scoped = base & parent_pd_stage
    if scoped.any():
        return scoped
    return base


def _pd_clamp_chart_dates(s: pd.Series, ts_report: pd.Timestamp) -> pd.Series:
    """Отсекаем мусорные даты MSP (напр. 01.01.2080) до расчёта сегментов Gantt.

    Значения вне диапазона [2000-01-01; дата отчёта + 10 лет] → NaT, иначе
    max() уводит конец красной полосы и ось X в далёкое будущее.
    """
    if s is None or len(s) == 0:
        return s
    ser = pd.to_datetime(s, errors="coerce")
    _ymin = pd.Timestamp("2000-01-01")
    _ymax = pd.Timestamp(ts_report).normalize() + pd.DateOffset(years=10)
    _bad = ser.notna() & ((ser < _ymin) | (ser > _ymax))
    if _bad.any():
        ser = ser.mask(_bad)
    return ser


def _pd_aggregate_delay_segments_for_indices(
    idx: pd.Index,
    *,
    bs_dt: pd.Series,
    ss_dt: pd.Series,
    bf_dt: pd.Series,
    sf_dt: pd.Series,
    af_dt: pd.Series,
    pct: pd.Series,
    ts_report: pd.Timestamp,
) -> dict | None:
    """Крайние сроки MSP по группе задач: min начало, max БП, max окончание."""
    if len(idx) == 0:
        return None
    bs = _pd_clamp_chart_dates(bs_dt.reindex(idx), ts_report)
    ss = _pd_clamp_chart_dates(ss_dt.reindex(idx), ts_report)
    bf = _pd_clamp_chart_dates(bf_dt.reindex(idx), ts_report)
    af = _pd_clamp_chart_dates(af_dt.reindex(idx), ts_report)
    sf = _pd_clamp_chart_dates(sf_dt.reindex(idx), ts_report)
    pc = pct.reindex(idx).fillna(0.0)
    starts: list[pd.Timestamp] = []
    for i in idx:
        s = bs.loc[i]
        if pd.isna(s):
            s = ss.loc[i]
        if pd.isna(s):
            s = bf.loc[i]
        if pd.notna(s):
            starts.append(pd.Timestamp(s).normalize())
    bf_valid = [
        pd.Timestamp(bf.loc[i]).normalize() for i in idx if pd.notna(bf.loc[i])
    ]
    sf_valid = [
        pd.Timestamp(sf.loc[i]).normalize() for i in idx if pd.notna(sf.loc[i])
    ]
    if not starts and not bf_valid and not sf_valid:
        return None
    start_n = (
        min(starts)
        if starts
        else (min(sf_valid) if sf_valid else (min(bf_valid) if bf_valid else pd.NaT))
    )
    if pd.isna(start_n):
        return None
    bf_n = max(bf_valid) if bf_valid else pd.NaT
    # ТЗ: на графике «Окончание» = текущий план (plan end / sf), как в детальной таблице.
    # Не подменяем фактом: иначе при 100% с пустым/ранним actual красный хвост пропадает.
    fin_all: list[pd.Timestamp] = []
    all_done = True
    any_row = False
    for i in idx:
        any_row = True
        pc_i = float(pc.loc[i]) if pd.notna(pc.loc[i]) else 0.0
        if pc_i < 99.99:
            all_done = False
        fin_i = sf.loc[i] if pd.notna(sf.loc[i]) else af.loc[i]
        if pd.notna(fin_i):
            fin_all.append(pd.Timestamp(fin_i).normalize())
    fin_n = max(fin_all) if fin_all else pd.NaT
    if pd.isna(bf_n) and pd.notna(fin_n):
        bf_n = fin_n
    if pd.isna(bf_n):
        return None
    done = bool(any_row and all_done and fin_all)
    seg = _pd_delay_chart_segments(
        start_n,
        bf_n,
        fin_n,
        done=done,
        ts_report=ts_report,
    )
    return seg


def _pd_segment_from_row_idx(
    idx,
    *,
    bs_dt: pd.Series,
    ss_dt: pd.Series,
    bf_dt: pd.Series,
    sf_dt: pd.Series,
    af_dt: pd.Series,
    pct: pd.Series,
    ts_report: pd.Timestamp,
) -> dict | None:
    """Одна строка MSP «Раздел …» — даты для графика по ТЗ (п.5–6)."""
    if idx not in bs_dt.index:
        return None

    def _clamp1(v):
        ts = pd.to_datetime(v, errors="coerce")
        if pd.isna(ts):
            return pd.NaT
        _ymin = pd.Timestamp("2000-01-01")
        _ymax = pd.Timestamp(ts_report).normalize() + pd.DateOffset(years=10)
        return pd.NaT if (ts < _ymin or ts > _ymax) else ts

    bs = _clamp1(bs_dt.loc[idx])
    ss = _clamp1(ss_dt.loc[idx]) if idx in ss_dt.index else pd.NaT
    bf = _clamp1(bf_dt.loc[idx])
    af = _clamp1(af_dt.loc[idx]) if idx in af_dt.index else pd.NaT
    sf = _clamp1(sf_dt.loc[idx]) if idx in sf_dt.index else pd.NaT
    pc = float(pct.loc[idx]) if idx in pct.index else 0.0
    start = bs if pd.notna(bs) else (ss if pd.notna(ss) else bf)
    if pd.isna(start) or pd.isna(bf):
        return None
    done = pc >= 99.99
    # ТЗ: «Окончание» = plan end (как колонка в таблице); факт — только запасной.
    fin = sf if pd.notna(sf) else af
    return _pd_delay_chart_segments(
        pd.Timestamp(start).normalize(),
        pd.Timestamp(bf).normalize(),
        fin,
        done=done and pd.notna(fin),
        ts_report=ts_report,
    )


def _pd_fmt_deviation_days(v) -> str:
    """Формат отклонения окончания ПД: +N / −N / 0 (опережение = плюс)."""
    num = pd.to_numeric(v, errors="coerce")
    if pd.isna(num):
        return ""
    n = int(round(float(num)))
    if n == 0:
        return "0"
    return f"{n:+d}"


def _pd_kpi_deviation_text_and_color(plan_v, fact_v) -> tuple[str, str]:
    """KPI «Отклонение на текущую дату»: факт − план; ≥0 зелёный, <0 красный."""
    p = int(round(float(pd.to_numeric(plan_v, errors="coerce") or 0)))
    f = int(round(float(pd.to_numeric(fact_v, errors="coerce") or 0)))
    d = f - p
    if d < 0:
        return f"{d:d}", "#ff5454"
    if d > 0:
        return f"{d:+d}", "#46d68a"
    return "0", "#46d68a"


def _render_pd_deviation_metric(label: str, plan_v, fact_v) -> None:
    """Метрика отклонения ПД: факт − план; ≥0 зелёный, <0 красный (−).

    Нативная st.metric (как у РД) — HTML-markdown раньше пропадал из‑за CSS колонок.
    """
    try:
        p = int(round(float(pd.to_numeric(plan_v, errors="coerce") or 0)))
        f = int(round(float(pd.to_numeric(fact_v, errors="coerce") or 0)))
        d = f - p
    except (TypeError, ValueError):
        d = 0
    disp = f"{d:d}" if d < 0 else (f"{d:+d}" if d > 0 else "0")
    tone = "neg" if d < 0 else "pos"
    with st.container(key=f"pd_dev_metric_{tone}"):
        st.metric(label, disp)


def _rd_kpi_plan_fact_deviation_today(
    *,
    today: date | None = None,
    msp_df: pd.DataFrame | None = None,
    csv_df: pd.DataFrame | None = None,
    plan_curve: float = 0.0,
    fact_curve: float = 0.0,
    rd_summ: dict | None = None,
) -> tuple[float, float, float]:
    """KPI «План/Факт/Отклонение на текущую дату»: план − факт (шт.)."""
    today = today or date.today()
    plan_to_date = 0.0
    fact_to_date = 0.0

    if msp_df is not None and not getattr(msp_df, "empty", True):
        if "_doc_plan_date" in msp_df.columns and "_rd_plan_inc" in msp_df.columns:
            pl_dt = pd.to_datetime(msp_df["_doc_plan_date"], errors="coerce")
            m_pl = pl_dt.notna() & (pl_dt.dt.date <= today)
            plan_to_date = float(
                pd.to_numeric(msp_df.loc[m_pl, "_rd_plan_inc"], errors="coerce")
                .fillna(0.0)
                .sum()
            )
        if "_doc_fact_date" in msp_df.columns:
            fc_dt = pd.to_datetime(msp_df["_doc_fact_date"], errors="coerce")
            m_fc = fc_dt.notna() & (fc_dt.dt.date <= today)
            if "in_production_numeric" in msp_df.columns:
                m_fc = m_fc & (
                    pd.to_numeric(msp_df["in_production_numeric"], errors="coerce").fillna(0.0)
                    > 0.0
                )
            fact_to_date = float(m_fc.sum())

    if csv_df is not None and not getattr(csv_df, "empty", True):
        if plan_to_date <= 0.0 and "_plan_dt" in csv_df.columns:
            pl_dt = pd.to_datetime(csv_df["_plan_dt"], errors="coerce")
            plan_to_date = float((pl_dt.notna() & (pl_dt.dt.date <= today)).sum())
        fc_col = (
            "_fact_dyn_dt"
            if "_fact_dyn_dt" in csv_df.columns
            else ("_fact_dt" if "_fact_dt" in csv_df.columns else None)
        )
        if fact_to_date <= 0.0 and fc_col:
            fc_dt = pd.to_datetime(csv_df[fc_col], errors="coerce")
            fact_to_date = float((fc_dt.notna() & (fc_dt.dt.date <= today)).sum())

    if plan_to_date <= 0.0 and plan_curve > 0.0:
        plan_to_date = float(plan_curve)
    if fact_to_date <= 0.0 and fact_curve > 0.0:
        fact_to_date = float(fact_curve)

    if rd_summ:
        if plan_to_date <= 0.0:
            plan_to_date = float(rd_summ.get("plan_to_date", 0) or 0)
        if fact_to_date <= 0.0:
            fact_to_date = float(rd_summ.get("fact_to_date", 0) or 0)

    return plan_to_date, fact_to_date, float(plan_to_date - fact_to_date)


def _render_rd_deviation_metric(label: str, deviation: float) -> None:
    """Метрика отклонения РД (план − факт).

    Нативная st.metric (выравнивание с соседними KPI). Цвет значения —
    через scoped-ключ контейнера: «+» (отставание) красный, «−» зелёный,
    «0» нейтральный. CSS: style.css + light_theme (выше общего stMetric).
    """
    try:
        d = int(round(float(deviation)))
    except (TypeError, ValueError):
        d = 0
    disp = f"{d:+d}" if d else "0"
    if d > 0:
        tone = "neg"
    elif d < 0:
        tone = "pos"
    else:
        tone = "zero"
    with st.container(key=f"rd_dev_metric_{tone}"):
        st.metric(label, disp)


def _pd_detail_table_labels(
    df: pd.DataFrame,
    *,
    task_col: Optional[str],
    cipher_col: Optional[str],
) -> tuple:
    """
    Подписи для детальной таблицы ПД:
    - наименование: полное имя задачи MSP (Раздел N «…»);
    - раздел: шифр ПД/РД или краткая метка «Раздел N», не этап/лот.
    """
    idx = df.index
    tn = (
        df[task_col].astype(str).str.strip().replace({"nan": "", "None": "", "<NA>": ""})
        if task_col and task_col in df.columns
        else pd.Series([""] * len(df), index=idx)
    )
    cipher = (
        df[cipher_col].astype(str).str.strip().replace({"nan": "", "None": "", "<NA>": ""})
        if cipher_col and cipher_col in df.columns
        else pd.Series([""] * len(df), index=idx)
    )
    razdel_from_task = tn.str.extract(
        r"(Раздел\s+[\d.]+(?:\.\d+)?)", flags=re.I, expand=False
    ).fillna("")
    razdel = cipher.where(cipher.ne(""), razdel_from_task)
    razdel = razdel.where(razdel.ne(""), razdel_from_task)
    stage_only = (
        razdel.str.casefold().str.contains("проектная документация", na=False)
        & ~razdel.str.contains("Раздел", case=False, na=False)
    )
    razdel = razdel.where(~stage_only, razdel_from_task)
    work_name = tn.where(tn.ne(""), "—")
    razdel = razdel.where(razdel.ne(""), "—")
    return work_name, razdel


def _doc_section_labels_series(
    df: pd.DataFrame,
    *,
    is_pd: bool,
    find_column_fn,
    section_col: Optional[str],
) -> Optional[pd.Series]:
    """Подпись раздела: «Шифр + Наименование» (напр. АС Стеновые…)."""
    if df is None or getattr(df, "empty", True):
        return None
    if is_pd:
        work = df
        cipher_col, cipher_ok = _pd_cipher_filled_mask(df)
        if not cipher_col or cipher_col not in df.columns:
            cipher_col = find_column_fn(
                df,
                [
                    "Шифр_ПД_и_РД",
                    "Шифр ПД и РД",
                    "Шифр ПД/РД",
                    "Шифр раздела",
                    "Шифр",
                    "abbreviation",
                    "DivisionCipher",
                    "Cipher",
                ],
            )
            cipher_ok = pd.Series(False, index=df.index)
        name_col_task = (
            "task name"
            if "task name" in df.columns
            else find_column_fn(df, ["Название задачи", "Задача", "Task Name", "Name"])
        )
        _pd_masks = _pd_section_masks(df)
        _dyn_m = _pd_masks["dynamics_mask"].fillna(False)
        if _dyn_m.any():
            work = df.loc[_dyn_m].copy()
        name_col = find_column_fn(
            work,
            [
                "Наименование раздела",
                "Наименование разделов работ",
                "Название раздела",
            ],
        )
        if not name_col or name_col not in work.columns:
            name_col = name_col_task if name_col_task and name_col_task in work.columns else section_col
    else:
        cipher_col = find_column_fn(
            df,
            [
                "Шифр",
                "Шифр полный",
                "Шифр раздела",
                "шифр раздела",
                "Шифр раздела РД",
                "Шифр РД",
                "Шифр ПД РД",
                "DivisionCipher",
                "Cipher",
            ],
        )
        name_col = find_column_fn(
            df,
            [
                "Наименование раздела",
                "наименование раздела",
                "Название раздела",
                "Наименование раздела РД",
            ],
        )
        if not name_col or name_col not in df.columns:
            name_col = section_col if section_col and section_col in df.columns else None
    _src = work if is_pd else df
    _has_cipher = bool(cipher_col and cipher_col in _src.columns)
    _name_src = name_col if name_col and name_col in _src.columns else None
    if not _has_cipher and not _name_src:
        return None
    ciph = pd.Series("", index=_src.index, dtype=object)
    nm = pd.Series("", index=_src.index, dtype=object)
    if _has_cipher:
        ciph = _src[cipher_col].fillna("").astype(str).str.strip()
        ciph = ciph.where(~ciph.str.lower().isin({"nan", "none", "-", "—"}), "")
    if _name_src:
        nm = _src[_name_src].fillna("").astype(str).str.strip()
        nm = nm.where(~nm.str.lower().isin({"nan", "none"}), "")
        if is_pd:
            nm = nm.str.replace(r"^\*\s*", "", regex=True)
            nm = nm.str.replace(r"^(?:Раздел|раздел)\s*", "", regex=True)
    lab = (
        (ciph.astype(str).str.strip() + " " + nm.astype(str).str.strip())
        .str.replace(r"\s+", " ", regex=True)
        .str.strip()
    )
    out = lab.mask(lab.eq(""), "(не указано)")
    if is_pd and not work.index.equals(df.index):
        full = pd.Series("(не указано)", index=df.index, dtype=object)
        full.loc[out.index] = out
        return full
    return out


def _rd_delay_section_label_series(
    df: pd.DataFrame,
    *,
    is_pd: bool,
    find_column_fn,
    section_col: Optional[str],
    task_col: Optional[str],
    msp_cipher_col: Optional[str],
    msp_name_col: Optional[str],
) -> pd.Series:
    """Единая подпись раздела для фильтра и графика просрочки."""
    if msp_cipher_col and msp_cipher_col in df.columns:
        _cip = df[msp_cipher_col].astype(str).str.strip()
        _cip = _cip.where(~_cip.str.lower().isin({"nan", "none", "<na>"}), other="")
        _nm_col = msp_name_col if msp_name_col and msp_name_col in df.columns else None
        if not _nm_col and section_col and section_col in df.columns:
            _nm_col = section_col
        elif not _nm_col and task_col and task_col in df.columns:
            _nm_col = task_col
        if _nm_col:
            _nm = df[_nm_col].astype(str).str.strip()
            _nm = _nm.where(~_nm.str.lower().isin({"nan", "none", "<na>"}), other="")
        else:
            _nm = pd.Series([""] * len(df), index=df.index)
        _combined = pd.Series([""] * len(df), index=df.index, dtype=object)
        _both = _cip.ne("") & _nm.ne("")
        _combined.loc[_both] = (_cip[_both].astype(str).str.strip() + " " + _nm[_both].astype(str).str.strip())
        _combined.loc[_cip.ne("") & ~_both] = _cip[_cip.ne("") & ~_both]
        _combined.loc[_nm.ne("") & ~_both] = _nm[_nm.ne("") & ~_both]
        _combined = _combined.astype(str).replace({"nan": "", "None": "", "<NA>": "", "NaT": ""}).str.strip()
        return _combined.mask(_combined.eq(""), "(не указано)")
    _ser = _doc_section_labels_series(
        df, is_pd=is_pd, find_column_fn=find_column_fn, section_col=section_col
    )
    if _ser is not None:
        return _ser
    if section_col and section_col in df.columns:
        return df[section_col].astype(str).str.strip().replace({"nan": "", "None": ""})
    if task_col and task_col in df.columns:
        return df[task_col].astype(str).str.strip()
    return pd.Series(["(не указано)"] * len(df), index=df.index)


def _rd_delay_overdue_row_count(series: pd.Series) -> int:
    return int((pd.to_numeric(series, errors="coerce").fillna(0.0) > 0).sum())


def _rd_delay_total_sections(series: pd.Series) -> float:
    total = float(pd.to_numeric(series, errors="coerce").fillna(0.0).sum())
    return max(total, float(len(series)))


def _rd_delay_overdue_group_agg_map() -> dict:
    return {
        "rd_deviation_numeric": "sum",
        "_rd_plan_n": "sum",
        "_rd_fact_n": "sum",
        "_base_dur": "max",
        "_cur_dur": "max",
        "_dev_dur": "max",
        "_overdue_cnt": ("rd_deviation_numeric", _rd_delay_overdue_row_count),
        "_total_cnt": ("_rd_plan_n", _rd_delay_total_sections),
        "_row_cnt": ("rd_deviation_numeric", "count"),
    }


def _rd_delay_apply_overdue_metric_chart(
    chart_data: pd.DataFrame,
    *,
    y_col: str,
    y_title: str,
    use_pct: bool,
    doc_code: str,
) -> None:
    """График просрочки РД: количество просроченных разделов или % от объёма по объекту."""
    if chart_data is None or chart_data.empty or y_col not in chart_data.columns:
        st.info("Нет данных для построения графика.")
        return
    work = chart_data.copy()
    if "_total_cnt" not in work.columns:
        work["_total_cnt"] = 0.0
    if "_overdue_cnt" not in work.columns:
        work["_overdue_cnt"] = 0
    if "_row_cnt" not in work.columns:
        work["_row_cnt"] = 1
    work["_total_cnt"] = pd.to_numeric(work["_total_cnt"], errors="coerce").fillna(0.0)
    work.loc[work["_total_cnt"] <= 0, "_total_cnt"] = pd.to_numeric(
        work.loc[work["_total_cnt"] <= 0, "_row_cnt"], errors="coerce"
    ).fillna(1.0)
    work["_overdue_cnt"] = pd.to_numeric(work["_overdue_cnt"], errors="coerce").fillna(0).astype(int)
    work["_overdue_pct"] = np.where(
        work["_total_cnt"] > 0,
        work["_overdue_cnt"] / work["_total_cnt"] * 100.0,
        0.0,
    )
    val_col = "_overdue_pct" if use_pct else "_overdue_cnt"
    x_title = (
        "% просроченных разделов от объёма"
        if use_pct
        else "Количество просроченных разделов"
    )
    work = work.sort_values(val_col, ascending=False)
    text_values: list[str] = []
    for _, row in work.iterrows():
        ovd = int(row["_overdue_cnt"])
        tot = int(round(float(row["_total_cnt"])))
        pct = float(row["_overdue_pct"])
        if use_pct:
            text_values.append(
                f"{pct:.0f}% ({ovd} из {tot})" if tot > 0 else f"{pct:.0f}%"
            )
        else:
            text_values.append(
                f"{ovd} из {tot} ({pct:.0f}%)" if tot > 0 else str(ovd)
            )
    work["_severity"] = pd.to_numeric(work[val_col], errors="coerce").fillna(0.0).clip(lower=0.0)
    severity_max = max(float(work["_severity"].max()), 1.0)
    _dev_vals = work["_severity"]
    _tick_labels = [
        (f"🔴 {lbl}" if float(d) > 0 else f"🟢 {lbl}")
        for lbl, d in zip(work[y_col].astype(str).tolist(), _dev_vals.tolist())
    ]
    fig = px.bar(
        work,
        x=val_col,
        y=y_col,
        orientation="h",
        title=None,
        labels={y_col: y_title, val_col: x_title},
        text=text_values,
        color="_severity",
        color_continuous_scale=[(0.0, "#27AE60"), (0.5, "#F1C40F"), (1.0, "#C0392B")],
        range_color=(0.0, severity_max if not use_pct else max(severity_max, 100.0)),
    )
    fig.update_traces(
        textposition="outside",
        textangle=0,
        textfont=dict(size=12, color="white"),
        marker=dict(line=dict(width=1, color="white")),
        showlegend=False,
    )
    category_list = work[y_col].tolist()
    _x_range = [0, 100] if use_pct else None
    fig.update_layout(
        xaxis_title=x_title,
        yaxis_title=y_title,
        height=max(480, len(work) * 44),
        showlegend=False,
        coloraxis_showscale=False,
        xaxis=dict(range=_x_range, ticksuffix="%" if use_pct else None)
        if _x_range
        else {},
        yaxis=dict(
            tickangle=0,
            categoryorder="array",
            categoryarray=list(reversed(category_list)),
            tickmode="array",
            tickvals=category_list,
            ticktext=list(reversed(_tick_labels)),
        ),
        bargap=0.12,
    )
    fig = _apply_bar_uniformtext(fig)
    fig = apply_chart_background(fig)
    render_chart(fig, caption_below=report_chart_caption_body(f"Просрочка выдачи {doc_code}"))


def _rd_delay_synthetic_deviation_days(
    df: pd.DataFrame,
    *,
    plan_end_col: Optional[str],
    base_end_col: Optional[str],
    actual_finish_col: Optional[str] = None,
) -> pd.Series:
    """Просрочка в днях: max(0, окончание − базовое окончание)."""
    idx = df.index
    be = (
        pd.to_datetime(df[base_end_col], errors="coerce", dayfirst=True, format="mixed")
        if base_end_col and base_end_col in df.columns
        else pd.Series(pd.NaT, index=idx)
    )
    pe = (
        pd.to_datetime(df[plan_end_col], errors="coerce", dayfirst=True, format="mixed")
        if plan_end_col and plan_end_col in df.columns
        else pd.Series(pd.NaT, index=idx)
    )
    af = (
        pd.to_datetime(df[actual_finish_col], errors="coerce", dayfirst=True, format="mixed")
        if actual_finish_col and actual_finish_col in df.columns
        else pd.Series(pd.NaT, index=idx)
    )
    ref = af.where(af.notna(), pe)
    dev = (ref.dt.normalize() - be.dt.normalize()).dt.days
    return pd.to_numeric(dev, errors="coerce").fillna(0.0).clip(lower=0.0)


def _rd_delay_duration_figure(
    rows: pd.DataFrame,
    *,
    y_col: str,
    dev_col: str,
    caption: str,
) -> "go.Figure":
    """Горизонтальные наложенные полосы: база (зел.), длительность (оранж.), отклонение (красн.)."""
    import plotly.graph_objects as go

    work = rows.copy()
    # П.8: сортировка от большей просрочки к меньшей (наибольшая — сверху).
    work = work.sort_values(dev_col, ascending=False)
    y_labels = work[y_col].astype(str).tolist()
    dev_vals = pd.to_numeric(work[dev_col], errors="coerce").fillna(0.0)

    # П.8: длинные названия задач переносим на несколько строк (узкая колонка подписей),
    # чтобы бары занимали больше места; текст выравниваем по левому краю без обрезания.
    def _wrap_label(text: str, width: int = 26) -> str:
        words = str(text).split()
        if not words:
            return str(text)
        lines: list[str] = []
        cur = ""
        for w in words:
            if not cur:
                cur = w
            elif len(cur) + 1 + len(w) <= width:
                cur = f"{cur} {w}"
            else:
                lines.append(cur)
                cur = w
        if cur:
            lines.append(cur)
        return "<br>".join(lines)

    ticktext = [
        (f"🔴 {_wrap_label(lbl)}" if float(d) > 0 else f"🟢 {_wrap_label(lbl)}")
        for lbl, d in zip(y_labels, dev_vals.tolist())
    ]
    base_d = pd.to_numeric(work.get("_base_dur", 0), errors="coerce").fillna(0.0).clip(lower=0.0)
    cur_d = pd.to_numeric(work.get("_cur_dur", 0), errors="coerce").fillna(0.0).clip(lower=0.0)
    dev_d = pd.to_numeric(work.get("_dev_dur", 0), errors="coerce").fillna(0.0).clip(lower=0.0)

    fig = go.Figure()
    fig.add_trace(
        go.Bar(
            name="Базовая длительность",
            orientation="h",
            y=y_labels,
            x=base_d,
            marker=dict(color="#27AE60"),
            hovertemplate="%{y}<br>База: %{x:.0f} дн.<extra></extra>",
        )
    )
    fig.add_trace(
        go.Bar(
            name="Длительность",
            orientation="h",
            y=y_labels,
            x=cur_d,
            marker=dict(color="#F39C12"),
            opacity=0.92,
            hovertemplate="%{y}<br>Длительность: %{x:.0f} дн.<extra></extra>",
        )
    )
    fig.add_trace(
        go.Bar(
            name="Отклонение длительности",
            orientation="h",
            y=y_labels,
            x=dev_d,
            base=base_d,
            marker=dict(color="#C0392B"),
            hovertemplate="%{y}<br>Отклонение: %{x:.0f} дн.<extra></extra>",
        )
    )
    x_max = float(max(base_d.max() if len(base_d) else 0, cur_d.max() if len(cur_d) else 0, 1.0))
    fig.update_layout(
        barmode="overlay",
        xaxis_title="Длительность / отклонение, дн.",
        yaxis_title="",
        # П.8: высота строки ≥ переноса названий (2–3 строки), иначе тики наезжают.
        height=_pd_delay_chart_height_for_labels(
            max(1, len(y_labels)), ticktext, min_px=480, layout_pad=56
        ),
        showlegend=True,
        legend=standard_chart_legend(),
        margin=dict(l=12, r=48, t=56, b=48),
        bargap=0.18,
    )
    fig.update_yaxes(
        categoryorder="array",
        categoryarray=list(reversed(y_labels)),
        tickmode="array",
        tickvals=y_labels,
        ticktext=ticktext,
        # П.8: подписи в области графика, выравнивание по левому краю, без обрезания.
        ticklabelposition="inside",
        tickfont=dict(size=11),
        automargin=True,
    )
    fig.update_xaxes(range=[0, x_max * 1.12])
    _ax_clr = _fin_chart_axis_color()
    fig.update_xaxes(
        tickfont=dict(color=_ax_clr, size=11),
        title_font=dict(color=_ax_clr),
    )
    fig.update_yaxes(
        tickfont=dict(color=_ax_clr, size=11),
        title_font=dict(color=_ax_clr),
    )
    fig = _apply_bar_uniformtext(fig)
    fig = apply_chart_background(fig)
    return fig


def _pd_chart_date_label(v) -> str:
    ts = pd.to_datetime(v, errors="coerce")
    if pd.isna(ts):
        return ""
    try:
        return pd.Timestamp(ts).strftime("%d.%m.%Y")
    except Exception:
        return ""


def _pd_delay_chart_segments(
    start_n: pd.Timestamp,
    bf_n: pd.Timestamp,
    fin_n: pd.Timestamp | None,
    *,
    done: bool,
    ts_report: pd.Timestamp,
) -> dict:
    """Сегменты графика ПД/РД по ТЗ:
      • жёлтый — start → Базовое окончание (подпись справа — БО);
      • зелёный — только при 100% и Окончание ≤ БО (подпись — Окончание);
      • красный — от БО до Окончания, если Окончание > БО (в т.ч. без 100%).
    Без 100% и без Окончания позже БО — только жёлтый.
    """
    start_n = pd.Timestamp(start_n).normalize()
    bf_n = pd.Timestamp(bf_n).normalize()
    fin_ts = (
        pd.Timestamp(fin_n).normalize()
        if fin_n is not None and pd.notna(fin_n)
        else pd.NaT
    )
    base_dur = max(int((bf_n - start_n).days), 0)
    bf_lbl = _pd_chart_date_label(bf_n)
    af_lbl = _pd_chart_date_label(fin_ts) if pd.notna(fin_ts) else ""
    fact_dur = 0.0
    delay_dur = 0
    delay_end = pd.NaT
    lbl_red = ""
    lbl_green = ""
    fin_for_green = pd.NaT
    if pd.notna(fin_ts) and fin_ts > bf_n:
        # Жёлтый до БО + красный до Окончания (и при 100%, и без).
        delay_dur = int((fin_ts - bf_n).days)
        delay_end = fin_ts
        lbl_red = af_lbl
    elif done and pd.notna(fin_ts) and fin_ts <= bf_n:
        # 100% вовремя/раньше — зелёный до Окончания, без красного.
        fact_dur = float(max(int((fin_ts - start_n).days), 0))
        fin_for_green = fin_ts
        gap_small = abs(int((bf_n - fin_ts).days)) <= 5
        lbl_green = "" if gap_small or fact_dur <= 0 else af_lbl
    return {
        "_start_dt": start_n,
        "_bf_dt": bf_n,
        "_fin_dt": fin_for_green,
        "_delay_end_dt": delay_end,
        "_base_dur": float(base_dur),
        "_fact_dur": float(fact_dur),
        "_delay_dur": float(delay_dur),
        "_lbl_yellow": bf_lbl,
        "_lbl_green": lbl_green,
        "_lbl_red": lbl_red,
    }


def _pd_msp_subtree_indices(
    df: pd.DataFrame,
    row_idx,
    *,
    hier_col: str,
) -> pd.Index:
    """Индексы поддерева MSP: строка + все нижестоящие до следующего узла того же уровня."""
    if row_idx not in df.index or hier_col not in df.columns:
        return pd.Index([row_idx])
    lv = outline_level_numeric(df[hier_col])
    row_lv = lv.loc[row_idx]
    if pd.isna(row_lv):
        return pd.Index([row_idx])
    pos = df.index.get_loc(row_idx)
    out: list = [row_idx]
    for j in range(pos + 1, len(df)):
        i = df.index[j]
        if lv.loc[i] <= row_lv:
            break
        out.append(i)
    return pd.Index(out)


def _pd_build_delay_section_rows(
    filtered_df: pd.DataFrame,
    *,
    y_col: str,
    source_df: pd.DataFrame,
    project_col: Optional[str],
    cipher_col: Optional[str],
    hier_col: Optional[str],
    bs_dt: pd.Series,
    ss_dt: pd.Series,
    bf_dt: pd.Series,
    sf_dt: pd.Series,
    af_dt: pd.Series,
    pct: pd.Series,
    report_date: date,
) -> pd.DataFrame:
    """Строки «По разделу»: каждая задача «Раздел N» из MSP (ТЗ п.5–6)."""
    ts_report = pd.Timestamp(report_date).normalize()
    rows: list[dict] = []
    seen_y: set[str] = set()
    for idx, row in filtered_df.iterrows():
        y_lbl = str(row.get(y_col, "") or "").strip() or "—"
        if y_lbl in seen_y:
            continue
        seen_y.add(y_lbl)
        seg = _pd_segment_from_row_idx(
            idx,
            bs_dt=bs_dt,
            ss_dt=ss_dt,
            bf_dt=bf_dt,
            sf_dt=sf_dt,
            af_dt=af_dt,
            pct=pct,
            ts_report=ts_report,
        )
        if seg:
            rows.append({y_col: y_lbl, **seg})
    return pd.DataFrame(rows)


def _pd_build_delay_project_rows(
    source_df: pd.DataFrame,
    *,
    project_col: str,
    display_projects: pd.Series,
    bs_dt: pd.Series,
    ss_dt: pd.Series,
    bf_dt: pd.Series,
    sf_dt: pd.Series,
    af_dt: pd.Series,
    pct: pd.Series,
    report_date: date,
) -> pd.DataFrame:
    """Строки для графика «По проекту»: min/max по всем задачам ПД проекта в MSP."""
    if project_col not in source_df.columns:
        return pd.DataFrame()
    ts_report = pd.Timestamp(report_date).normalize()
    rows: list[dict] = []
    for proj in display_projects.drop_duplicates():
        proj_lbl = str(proj or "").strip() or "—"
        idx = source_df.index[source_df[project_col] == proj]
        seg = _pd_aggregate_delay_segments_for_indices(
            idx,
            bs_dt=bs_dt,
            ss_dt=ss_dt,
            bf_dt=bf_dt,
            sf_dt=sf_dt,
            af_dt=af_dt,
            pct=pct,
            ts_report=ts_report,
        )
        if seg:
            rows.append({project_col: proj_lbl, **seg})
    return pd.DataFrame(rows)


def _pd_delay_label_annotation(
    seg_start: float,
    seg_width: float,
    text: str,
    *,
    inside_color: str,
    outside_color: str = "#E8E8E8",
    min_inside: float = 26.0,
    anchor_end: bool = True,
) -> dict | None:
    text = str(text or "").strip()
    if not text or float(seg_width) <= 0:
        return None
    w = float(seg_width)
    s = float(seg_start)
    if w >= min_inside:
        if anchor_end:
            return {
                "x": s + w * 0.96,
                "text": text,
                "xanchor": "right",
                "font": {"size": 10, "color": inside_color},
            }
        return {
            "x": s + w * 0.5,
            "text": text,
            "xanchor": "center",
            "font": {"size": 10, "color": inside_color},
        }
    return {
        "x": s + w + max(2.0, w * 0.04),
        "text": text,
        "xanchor": "left",
        "font": {"size": 9, "color": outside_color},
    }


def _pd_delay_date_annotation(
    x_end,
    x_start,
    text: str,
    *,
    inside_color: str,
    outside_color: str = "#E8E8E8",
    min_days: int = 18,
    anchor_end: bool = True,
) -> dict | None:
    text = str(text or "").strip()
    if not text:
        return None
    end = pd.Timestamp(pd.to_datetime(x_end, errors="coerce")).normalize()
    start = pd.Timestamp(pd.to_datetime(x_start, errors="coerce")).normalize()
    if pd.isna(end):
        return None
    if anchor_end:
        _days = int((end - start).days) if pd.notna(start) else 0
        _color = inside_color if _days >= min_days else outside_color
        return {
            "x": end.to_pydatetime(),
            "text": text,
            "xanchor": "left",
            "xshift": 8,
            "font": {"size": 10, "color": _color},
        }
    if pd.isna(start):
        return None
    days = int((end - start).days)
    if days <= 0:
        return None
    x_plot = (start + pd.Timedelta(days=days / 2)).to_pydatetime()
    return {
        "x": x_plot,
        "text": text,
        "xanchor": "center",
        "font": {"size": 10, "color": inside_color},
    }


_PD_DELAY_CHART_ROW_PX = 62
_PD_DELAY_CHART_VISIBLE_ROWS = 28
_PD_DELAY_CHART_KEY_SECTION = "pd_delay_section_chart"
_PD_DELAY_CHART_KEY_PROJECT = "pd_delay_project_chart"


def _pd_delay_chart_height_for_labels(
    n_rows: int,
    ticktexts: list[str] | None = None,
    *,
    task_font: int = 11,
    min_px: int = 280,
    layout_pad: int = 120,
) -> int:
    """Высота bar/gantt «по разделу»: полоса категории ≥ высоты <br>-подписи Y."""
    n = max(1, int(n_rows))
    max_lines = 1
    for t in ticktexts or []:
        max_lines = max(max_lines, str(t).count("<br>") + 1)
    lh = float(max(15.0, float(task_font) * 1.42))
    row_px = int(max(_PD_DELAY_CHART_ROW_PX, int(max_lines * lh + 30.0)))
    return int(max(min_px, n * row_px + layout_pad))


def _pd_build_project_indicator_chart_data(
    source_df: pd.DataFrame,
    *,
    project_col: Optional[str],
    masks: dict,
    report_date: date,
    bf_dt: pd.Series,
    pct_series: pd.Series,
) -> pd.DataFrame:
    """Сводка план/факт по проектам для индикаторов."""
    if (
        source_df is None
        or source_df.empty
        or not project_col
        or project_col not in source_df.columns
    ):
        return pd.DataFrame()
    delay_m = _pd_delay_row_mask(source_df, masks).reindex(
        source_df.index, fill_value=False
    )
    work = source_df.loc[delay_m.fillna(False)].copy()
    if work.empty:
        return pd.DataFrame()
    ts = pd.Timestamp(report_date).normalize()
    plan_fin = _pd_delay_plan_finish_dt_series(work).reindex(work.index)
    bs = pd.Series(pd.NaT, index=work.index)
    if "base start" in work.columns:
        bs = pd.to_datetime(work["base start"], errors="coerce", dayfirst=True, format="mixed")
    if "plan start" in work.columns:
        ps = pd.to_datetime(work["plan start"], errors="coerce", dayfirst=True, format="mixed")
        bs = bs.where(bs.notna(), ps)
    pc = pct_series.reindex(work.index).fillna(0.0)
    af = (
        pd.to_datetime(work["_fact_end_dt"], errors="coerce", dayfirst=True, format="mixed")
        if "_fact_end_dt" in work.columns
        else pd.Series(pd.NaT, index=work.index)
    )
    work["_pd_row_plan"] = _pd_delay_plan_due_row_mask(plan_fin, bs, ts).astype(int)
    work["_pd_row_fact"] = (
        (pc >= 99.99) | (af.notna() & (af.dt.normalize() <= ts))
    ).astype(int)
    return (
        work.groupby(project_col, as_index=False)
        .agg(
            _pd_plan_cnt=("_pd_row_plan", "sum"),
            _pd_fact_cnt=("_pd_row_fact", "sum"),
        )
        .rename(columns={project_col: "Проект"})
    )


def _pd_delay_indicator_color(val: float, dev_max: float) -> str:
    if dev_max <= 0 or val <= 0:
        try:
            from dashboards.light_theme import is_light_preview_active

            if is_light_preview_active():
                return "#15803d"
        except Exception:
            pass
        return "#1E8449"
    r = min(max(val / dev_max, 0.0), 1.0)
    if r < 0.5:
        t = r / 0.5
        r1, g1, b1 = 0x27, 0xAE, 0x60
        r2, g2, b2 = 0xF1, 0xC4, 0x0F
    else:
        t = (r - 0.5) / 0.5
        r1, g1, b1 = 0xF1, 0xC4, 0x0F
        r2, g2, b2 = 0xC0, 0x39, 0x2B
    rr = int(r1 + (r2 - r1) * t)
    gg = int(g1 + (g2 - g1) * t)
    bb = int(b1 + (b2 - b1) * t)
    return f"#{rr:02X}{gg:02X}{bb:02X}"


def _pd_delay_project_indicator_card_html(
    proj: str, ovd_i: int, *, bg: str, unit: str = "док."
) -> str:
    """Карточка проекта: цвет по уровню просрочки + «Просрочка: N …»."""
    _proj = html_module.escape(str(proj))
    _label = (
        "Без просрочки"
        if int(ovd_i) <= 0
        else f"Просрочка: {int(ovd_i)} {unit}"
    )
    _border = ""
    try:
        from dashboards.light_theme import is_light_preview_active

        if is_light_preview_active():
            _border = "border:1px solid rgba(15,23,42,0.08);"
    except Exception:
        pass
    return (
        f"<div style='background:{bg};color:white;padding:10px 14px;border-radius:8px;"
        f"margin-bottom:8px;min-height:68px;box-sizing:border-box;{_border}'>"
        f"<div style='font-size:13px;opacity:0.9;'>{_proj}</div>"
        f"<div style='font-size:18px;font-weight:600;'>{_label}</div>"
        f"</div>"
    )


def _render_pd_delay_project_indicators(
    chart_data: pd.DataFrame,
    y_col: str,
    doc_code: str,
    *,
    plan_col: str = "_pd_plan_cnt",
    fact_col: str = "_pd_fact_cnt",
) -> None:
    """Карточки просрочки по проектам: зелёный → жёлтый → красный по величине."""
    if chart_data is None or chart_data.empty or y_col not in chart_data.columns:
        return
    st.markdown(f"**Индикаторы просрочки {doc_code} по проектам**")
    rows: list[dict] = []
    for _, row in chart_data.iterrows():
        plan_i = int(row.get(plan_col, 0) or 0)
        fact_i = int(row.get(fact_col, 0) or 0)
        if "_pd_overdue_cnt" in chart_data.columns:
            ovd_i = int(row.get("_pd_overdue_cnt", 0) or 0)
        elif "_pd_dev_cnt" in chart_data.columns:
            ovd_i = int(row.get("_pd_dev_cnt", 0) or 0)
        else:
            ovd_i = max(0, plan_i - fact_i)
        rows.append({"Проект": str(row[y_col]), "ovd": ovd_i})
    ind_df = (
        pd.DataFrame(rows)
        .sort_values("ovd", ascending=False)
        .reset_index(drop=True)
    )
    _dev_max = float(ind_df["ovd"].max()) if not ind_df.empty else 0.0
    n = len(ind_df)
    _cols_n = min(4, max(1, n))
    cols_row = st.columns(_cols_n, gap="small")
    for i, (_, row) in enumerate(ind_df.iterrows()):
        ovd_i = int(row["ovd"])
        bg = _pd_delay_indicator_color(float(ovd_i), _dev_max)
        with cols_row[i % _cols_n]:
            st.markdown(
                _pd_delay_project_indicator_card_html(
                    str(row["Проект"]),
                    ovd_i,
                    bg=bg,
                ),
                unsafe_allow_html=True,
            )


def _pd_delay_chart_compact_css(key: str, height: int) -> str:
    """Фиксированная высота блока Plotly — без «раздувания» после загрузки iframe."""
    h = max(280, int(height))
    _chart_shell = ""
    try:
        from dashboards.light_theme import is_light_preview_active

        if is_light_preview_active():
            _chart_shell = (
                f"div[class*=\"st-key-{key}\"] [data-testid=\"stPlotlyChart\"]{{"
                f"background:#ffffff!important;border:1px solid #cbd5e1!important;"
                f"border-radius:8px!important;}}"
            )
    except Exception:
        pass
    return (
        f"<style>"
        f"div[class*=\"st-key-{key}\"] [data-testid=\"stPlotlyChart\"]{{"
        f"min-height:{h}px!important;height:{h}px!important;max-height:{h}px!important;"
        f"overflow-y:hidden!important;overflow-x:auto!important;"
        f"}}"
        f"div[class*=\"st-key-{key}\"] [data-testid=\"stPlotlyChart\"] iframe{{"
        f"min-height:{h}px!important;height:{h}px!important;max-height:{h}px!important;"
        f"display:block!important;"
        f"}}"
        f"{_chart_shell}"
        f"</style>"
    )


def _render_pd_delay_duration_chart(
    fig, caption_below: str, *, chart_key: str | None = None
) -> None:
    try:
        _h = int(fig.layout.height)
    except Exception:
        _h = 280
    _key = str(chart_key or _PD_DELAY_CHART_KEY_SECTION)
    # Много строк «по разделу»: полный fig + внутренний скролл — иначе Streamlit
    # сжимает сотни категорий во вьюпорт и <br>-названия наезжают друг на друга.
    _viewport = min(
        _h, max(520, _PD_DELAY_CHART_VISIBLE_ROWS * _PD_DELAY_CHART_ROW_PX)
    )
    if _h > _viewport:
        render_chart(
            fig,
            key=_key,
            height=_h,
            max_height=None,
            scroll_viewport_height=_viewport,
            caption_below=caption_below,
            skip_clamp_zoom=True,
            compact=False,
        )
        return
    st.markdown(
        _pd_delay_chart_compact_css(_key, _h),
        unsafe_allow_html=True,
    )
    render_chart(
        fig,
        key=_key,
        height=_h,
        max_height=None,
        caption_below=caption_below,
        skip_clamp_zoom=True,
        compact=True,
    )


def _pd_delay_section_duration_figure(
    rows: pd.DataFrame,
    *,
    y_col: str,
    yellow_name: str = "Базовый план",
    green_name: str = "Окончание",
    yellow_hover: str = "Базовое окончание",
    green_hover: str = "Окончание",
    show_forecast: bool = True,
    delay_label_as_days: bool = False,
) -> "go.Figure":
    """ПД/РД: жёлтый max БП, зелёное max окончание, красная просрочка; ось X — даты.

    Plotly Bar на date-axis: ``base`` = дата начала, ``x`` = длительность в ms.
    Абсолютная дата в ``x`` даёт числовую ось / уезд в ~2080.
    """
    import plotly.graph_objects as go

    _MS_DAY = 86400000.0
    _cols = [
        y_col,
        "_start_dt",
        "_bf_dt",
        "_fin_dt",
        "_delay_end_dt",
        "_delay_dur",
        "_lbl_yellow",
        "_lbl_green",
        "_lbl_red",
    ]
    work = rows.copy()
    if work.empty:
        work = pd.DataFrame(columns=_cols)
    work = work.sort_values("_delay_dur", ascending=False)
    y_labels = work[y_col].astype(str).tolist()
    starts = pd.to_datetime(work["_start_dt"], errors="coerce")
    bf_ends = pd.to_datetime(work["_bf_dt"], errors="coerce")
    fin_ends = pd.to_datetime(work["_fin_dt"], errors="coerce")
    delay_ends = pd.to_datetime(work["_delay_end_dt"], errors="coerce")
    delay_d = pd.to_numeric(work["_delay_dur"], errors="coerce").fillna(0.0)

    def _wrap_label(text: str, width: int = 24) -> str:
        words = str(text).split()
        if not words:
            return str(text)
        lines: list[str] = []
        cur = ""
        for w in words:
            if not cur:
                cur = w
            elif len(cur) + 1 + len(w) <= width:
                cur = f"{cur} {w}"
            else:
                lines.append(cur)
                cur = w
        if cur:
            lines.append(cur)
        return "<br>".join(lines)

    ticktext = [_wrap_label(lbl) for lbl in y_labels]

    def _as_ts(v):
        ts = pd.to_datetime(v, errors="coerce")
        if pd.isna(ts):
            return pd.NaT
        return pd.Timestamp(ts).normalize()

    def _bar_len_ms(start, end) -> float | None:
        s = _as_ts(start)
        e = _as_ts(end)
        if pd.isna(s) or pd.isna(e) or e < s:
            return None
        ms = float((e - s) / pd.Timedelta(milliseconds=1))
        return ms if ms > 0 else _MS_DAY

    def _base_dt(v):
        ts = _as_ts(v)
        return None if pd.isna(ts) else ts.to_pydatetime()

    fig = go.Figure()
    yellow_y: list[str] = []
    yellow_len: list[float] = []
    yellow_base: list = []
    yellow_cd: list[str] = []
    for y_lbl, st, bf_e in zip(y_labels, starts.tolist(), bf_ends.tolist()):
        ln = _bar_len_ms(st, bf_e)
        b = _base_dt(st)
        if ln is None or b is None:
            continue
        yellow_y.append(y_lbl)
        yellow_len.append(ln)
        yellow_base.append(b)
        yellow_cd.append(_pd_chart_date_label(bf_e))
    if yellow_y:
        fig.add_trace(
            go.Bar(
                name=yellow_name,
                orientation="h",
                y=yellow_y,
                x=yellow_len,
                base=yellow_base,
                marker=dict(color="#F1C40F"),
                customdata=yellow_cd,
                hovertemplate="%{y}<br>"
                + yellow_hover
                + ": %{customdata}<extra></extra>",
            )
        )
    green_y: list[str] = []
    green_len: list[float] = []
    green_base: list = []
    green_cd: list[str] = []
    green_ends: list = []
    if show_forecast:
        for y_lbl, st, fin_e in zip(y_labels, starts.tolist(), fin_ends.tolist()):
            ln = _bar_len_ms(st, fin_e)
            b = _base_dt(st)
            if ln is None or b is None:
                continue
            green_y.append(y_lbl)
            green_len.append(ln)
            green_base.append(b)
            green_cd.append(_pd_chart_date_label(fin_e))
            green_ends.append(_base_dt(fin_e))
    if green_y:
        fig.add_trace(
            go.Bar(
                name=green_name,
                orientation="h",
                y=green_y,
                x=green_len,
                base=green_base,
                marker=dict(color="#27AE60"),
                customdata=green_cd,
                hovertemplate="%{y}<br>"
                + green_hover
                + ": %{customdata}<extra></extra>",
            )
        )
    red_y: list[str] = []
    red_len: list[float] = []
    red_base: list = []
    red_cd: list[str] = []
    red_ends: list = []
    if show_forecast:
        for y_lbl, bf_e, d_e, d_days in zip(
            y_labels, bf_ends.tolist(), delay_ends.tolist(), delay_d.tolist()
        ):
            if float(d_days) <= 0:
                continue
            ln = _bar_len_ms(bf_e, d_e)
            b = _base_dt(bf_e)
            if ln is None or b is None:
                continue
            red_y.append(y_lbl)
            red_len.append(ln)
            red_base.append(b)
            red_cd.append(_pd_chart_date_label(d_e))
            red_ends.append(_base_dt(d_e))
    if red_y:
        fig.add_trace(
            go.Bar(
                name="Просрочка",
                orientation="h",
                y=red_y,
                x=red_len,
                base=red_base,
                marker=dict(color="#C0392B"),
                customdata=red_cd,
                hovertemplate="%{y}<br>Просрочка до %{customdata}<extra></extra>",
            )
        )
    for y_lbl, st, bf_e, fin_e, d_e, d_days, ly, lg, lr in zip(
        y_labels,
        starts.tolist(),
        bf_ends.tolist(),
        fin_ends.tolist(),
        delay_ends.tolist(),
        delay_d.tolist(),
        work["_lbl_yellow"].fillna("").astype(str).tolist(),
        work["_lbl_green"].fillna("").astype(str).tolist(),
        work["_lbl_red"].fillna("").astype(str).tolist(),
    ):
        _ann_kw = dict(y=y_lbl, showarrow=False, yanchor="middle")
        bf_n = _as_ts(bf_e)
        fin_n = _as_ts(fin_e)
        _has_red = show_forecast and float(d_days) > 0 and pd.notna(d_e)
        # Базовое окончание — всегда у конца жёлтой полосы. Без красного сегмента —
        # справа от полосы; при красном — у стыка жёлтого/красного (ТЗ: «справа от
        # конца жёлтого — Базовое окончание, справа от конца красного — Окончание»).
        # RD-08: без просрочки у конца полосы — «в срок» вместо даты по договору.
        _no_red_lbl = "в срок" if delay_label_as_days else ly
        if str(_no_red_lbl).strip() and pd.notna(bf_n) and not _has_red and (
            pd.isna(fin_n) or fin_n <= bf_n
        ):
            _y_ann = _pd_delay_date_annotation(
                bf_e,
                st,
                _no_red_lbl,
                inside_color="#1a1a1a",
                outside_color="#1a1a1a",
                anchor_end=True,
            )
            if _y_ann:
                fig.add_annotation(**_ann_kw, **_y_ann)
        elif str(ly).strip() and pd.notna(bf_n) and _has_red:
            fig.add_annotation(
                **_ann_kw,
                x=bf_n.to_pydatetime(),
                text=str(ly).strip(),
                xanchor="right",
                xshift=-6,
                font={"size": 10, "color": "#1a1a1a"},
            )
        if (
            show_forecast
            and pd.notna(fin_e)
            and str(lg).strip()
            and not _has_red
            and not delay_label_as_days
        ):
            _g_ann = _pd_delay_date_annotation(
                fin_e,
                st,
                lg,
                inside_color="#1a1a1a",
                outside_color="#1a1a1a",
                anchor_end=True,
            )
            if _g_ann:
                fig.add_annotation(**_ann_kw, **_g_ann)
        if _has_red and pd.notna(d_e):
            if delay_label_as_days:
                # RD-03: на вкладке просрочки подпись красного сегмента — число
                # дней просрочки (целое, выравнивание вправо), а не дата.
                _r_lbl = f"{int(round(float(d_days)))} дн."
            else:
                _r_lbl = str(lr).strip().split("/")[-1].strip() or str(lr).strip()
                if "/" in str(lr):
                    _r_lbl = _rd_format_chart_date_cell(lr) or _r_lbl
            _r_ann = _pd_delay_date_annotation(
                d_e,
                bf_e,
                _r_lbl,
                inside_color="#1a1a1a",
                outside_color="#1a1a1a",
                anchor_end=True,
            )
            if _r_ann:
                fig.add_annotation(**_ann_kw, **_r_ann)
    _n_rows = max(1, len(y_labels))
    _chart_h = _pd_delay_chart_height_for_labels(_n_rows, ticktext)
    fig.update_layout(
        barmode="overlay",
        xaxis_title="Период",
        yaxis_title="",
        height=_chart_h,
        showlegend=True,
        legend=standard_chart_legend(),
        margin=dict(l=16, r=140, t=56, b=48),
        bargap=0.44,
    )
    fig.update_traces(selector=dict(type="bar"), width=0.48)
    fig.update_yaxes(
        categoryorder="array",
        categoryarray=list(reversed(y_labels)),
        tickmode="array",
        tickvals=y_labels,
        ticktext=ticktext,
        ticklabelposition="outside",
        tickfont=dict(size=11),
        automargin=True,
    )
    _x_pts = []
    for st, bf_e, fin_e, d_e in zip(
        starts.tolist(), bf_ends.tolist(), fin_ends.tolist(), delay_ends.tolist()
    ):
        for v in (st, bf_e, fin_e, d_e):
            ts = _as_ts(v)
            if pd.notna(ts):
                _x_pts.append(ts.to_pydatetime())
    if _x_pts:
        d0 = min(_x_pts)
        d1 = max(_x_pts)
        pad = max((d1 - d0).days * 0.08, 6)
        fig.update_xaxes(
            type="date",
            tickformat="%d.%m.%Y",
            automargin=True,
            range=[
                d0 - pd.Timedelta(days=pad),
                d1 + pd.Timedelta(days=pad),
            ],
        )
    else:
        fig.update_xaxes(type="date", tickformat="%d.%m.%Y", automargin=True)
    fig = apply_chart_background(fig)
    _ax_clr = _fin_chart_axis_color()
    fig.update_xaxes(
        tickfont=dict(color=_ax_clr, size=11),
        title_font=dict(color=_ax_clr),
        type="date",
        tickformat="%d.%m.%Y",
    )
    fig.update_yaxes(
        tickfont=dict(color=_ax_clr, size=11),
        title_font=dict(color=_ax_clr),
    )
    return fig

def _pd_delay_plan_fact_figure(
    rows: pd.DataFrame,
    *,
    y_col: str,
    plan_col: str = "_pd_plan_cnt",
    fact_col: str = "_pd_fact_cnt",
    overdue_col: str = "_pd_dev_cnt",
) -> "go.Figure":
    """По проекту: жёлтый план, зелёный факт вовремя, красная просрочка (Finish > БО)."""
    import plotly.graph_objects as go

    work = rows.copy()
    if overdue_col not in work.columns:
        work[overdue_col] = (
            pd.to_numeric(work.get(plan_col, 0), errors="coerce").fillna(0)
            - pd.to_numeric(work.get(fact_col, 0), errors="coerce").fillna(0)
        ).clip(lower=0)
    work = work.sort_values(overdue_col, ascending=False)
    y_labels = work[y_col].astype(str).tolist()
    plan_v = pd.to_numeric(work[plan_col], errors="coerce").fillna(0.0)
    fact_v = pd.to_numeric(work[fact_col], errors="coerce").fillna(0.0)
    overdue_v = pd.to_numeric(work[overdue_col], errors="coerce").fillna(0.0).clip(
        lower=0.0
    )
    # Не допускаем зелёный+красный > плана из‑за двойного счёта.
    _stack = fact_v + overdue_v
    _over = _stack > plan_v + 1e-9
    if bool(_over.any()):
        fact_v = fact_v.where(~_over, (plan_v - overdue_v).clip(lower=0.0))

    def _wrap_label(text: str, width: int = 26) -> str:
        words = str(text).split()
        if not words:
            return str(text)
        lines: list[str] = []
        cur = ""
        for w in words:
            if not cur:
                cur = w
            elif len(cur) + 1 + len(w) <= width:
                cur = f"{cur} {w}"
            else:
                lines.append(cur)
                cur = w
        if cur:
            lines.append(cur)
        return "<br>".join(lines)

    ticktext = [_wrap_label(lbl) for lbl in y_labels]
    x_max = float(
        max(
            plan_v.max() if len(plan_v) else 0,
            (fact_v + overdue_v).max() if len(fact_v) else 0,
            1.0,
        )
    )

    fig = go.Figure()
    # Жёлтый план — полная ширина; зелёный факт полупрозрачный поверх, чтобы жёлтый был виден.
    fig.add_trace(
        go.Bar(
            name="План (разделы ПД на дату отчёта)",
            orientation="h",
            y=y_labels,
            x=plan_v,
            marker=dict(color="#F1C40F", line=dict(color="#D4AC0D", width=1)),
            text=[f"{int(v)}" if float(v) > 0 else "" for v in plan_v],
            textposition="outside",
            insidetextanchor="middle",
            textfont=dict(color="#F1C40F", size=11),
            cliponaxis=False,
            hovertemplate="%{y}<br>План: %{x:.0f} док.<extra></extra>",
        )
    )
    fig.add_trace(
        go.Bar(
            name="Факт вовремя (100%)",
            orientation="h",
            y=y_labels,
            x=fact_v,
            marker=dict(color="#27AE60"),
            opacity=0.72,
            textposition="none",
            texttemplate=" ",
            cliponaxis=False,
            hovertemplate="%{y}<br>Факт вовремя: %{x:.0f} док.<extra></extra>",
        )
    )
    red_base = fact_v.tolist()
    fig.add_trace(
        go.Bar(
            name="Просрочка (окончание > базовое)",
            orientation="h",
            y=y_labels,
            x=overdue_v,
            base=red_base,
            marker=dict(color="#C0392B"),
            textposition="none",
            texttemplate=" ",
            cliponaxis=False,
            hovertemplate="%{y}<br>Просрочка: %{x:.0f} док.<extra></extra>",
        )
    )
    for y_lbl, fv, ov in zip(y_labels, fact_v.tolist(), overdue_v.tolist()):
        _ann_kw = dict(
            y=y_lbl,
            showarrow=False,
            yanchor="middle",
            xref="x",
            yref="y",
            textangle=0,
        )
        fv_f = float(fv)
        ov_f = float(ov)
        if fv_f > 0:
            fig.add_annotation(
                **_ann_kw,
                x=fv_f / 2.0,
                text=f"{int(round(fv_f))}",
                font=dict(color="#FFFFFF", size=12),
                xanchor="center",
            )
        if ov_f > 0:
            fig.add_annotation(
                **_ann_kw,
                x=fv_f + ov_f / 2.0,
                text=f"{int(round(ov_f))}",
                font=dict(color="#FFFFFF", size=12),
                xanchor="center",
            )
    _n_pf = max(1, len(y_labels))
    _leg_pf = _line_chart_legend_below(n_items=3, long_labels=True)
    fig.update_layout(
        barmode="overlay",
        xaxis_title="Количество разделов ПД, док.",
        yaxis_title="",
        height=_pd_delay_chart_height_for_labels(_n_pf, ticktext),
        showlegend=True,
        legend=_leg_pf,
        margin=dict(l=12, r=48, t=56, b=160),
        bargap=0.34,
    )
    fig.update_traces(selector=dict(type="bar"), width=0.48)
    fig.update_yaxes(
        categoryorder="array",
        categoryarray=list(reversed(y_labels)),
        tickmode="array",
        tickvals=y_labels,
        ticktext=ticktext,
        ticklabelposition="outside",
        tickfont=dict(size=11),
        automargin=True,
    )
    fig.update_xaxes(range=[0, x_max * 1.12], automargin=True)
    fig = apply_chart_background(fig)
    _ax_clr = _fin_chart_axis_color()
    _leg_pf = _line_chart_legend_below(n_items=3, long_labels=True)
    _leg_pf["font"] = dict(size=12, color=_fin_chart_legend_text_color())
    fig.update_layout(
        legend=_leg_pf,
        showlegend=True,
        margin=dict(l=12, r=48, t=56, b=170),
    )
    fig.update_xaxes(
        tickfont=dict(color=_ax_clr, size=11),
        title_font=dict(color=_ax_clr),
    )
    fig.update_yaxes(
        tickfont=dict(color=_ax_clr, size=11),
        title_font=dict(color=_ax_clr),
    )
    return fig


def _pd_msp_find_baseline_finish_col(df: pd.DataFrame):
    # Канонические выгрузки MSP: «Базовое окончание» → `base end` (см. web_loader remap).
    for cand in ("base end", "baseline finish"):
        if cand in df.columns:
            return cand
    for c in df.columns:
        cl = str(c).strip().lower()
        if ("baseline" in cl or "базов" in cl) and ("finish" in cl or "оконч" in cl):
            return c
        if cl.startswith("base") and ("end" in cl or "finish" in cl):
            return c
    return None


def _pd_msp_find_baseline_start_col(df: pd.DataFrame):
    for cand in ("base start", "baseline start"):
        if cand in df.columns:
            return cand
    for c in df.columns:
        cl = str(c).strip().lower()
        if ("baseline" in cl or "базов" in cl) and ("start" in cl or "начал" in cl):
            return c
        if cl.startswith("base") and ("start" in cl or "begin" in cl):
            return c
    return None


def _pd_msp_find_schedule_start_col(df: pd.DataFrame):
    for cand in ("plan start", "start"):
        if cand in df.columns:
            return cand
    for c in df.columns:
        cs = str(c).strip()
        cl = cs.lower()
        if "базов" in cl or "baseline" in cl or cl.startswith("base"):
            continue
        if cl in ("start", "начало", "plan start") or (
            cl.endswith("начало") and "план" not in cl and "факт" not in cl
        ):
            return c
    return None


def _pd_mask_with_finish(
    df: pd.DataFrame,
    row_mask: pd.Series,
    finish_col: Optional[str],
) -> pd.Series:
    """Строки маски с валидной датой окончания (для накопительного графика ПД)."""
    m = row_mask.fillna(False)
    if finish_col and finish_col in df.columns:
        fe = pd.to_datetime(df[finish_col], errors="coerce", dayfirst=True, format="mixed")
        m = m & fe.notna()
    return m


def _pd_mask_with_start_finish(
    df: pd.DataFrame,
    row_mask: pd.Series,
    start_col: Optional[str],
    finish_col: Optional[str],
) -> pd.Series:
    """Строки маски с валидной парой дат начала и окончания."""
    m = row_mask.fillna(False)
    if start_col and start_col in df.columns:
        ss = pd.to_datetime(df[start_col], errors="coerce", dayfirst=True, format="mixed")
        m = m & ss.notna()
    if finish_col and finish_col in df.columns:
        fe = pd.to_datetime(df[finish_col], errors="coerce", dayfirst=True, format="mixed")
        m = m & fe.notna()
    return m


from dashboards.gdrs_theme import GDRS_THEME_DARK

_PD_PLAN_LINE_COLOR = GDRS_THEME_DARK.line_plan
_PD_FCST_LINE_COLOR = GDRS_THEME_DARK.line_fact


def _pd_necessary_productivity(
    deviation_to_date: float,
    baseline_finish: pd.Series,
    report_date: date,
    period_multiplier: float,
    *,
    schedule_finish: pd.Series | None = None,
) -> Optional[float]:
    """
    |отклонение| / (дней до срока) × множитель (×1 / ×7 / ×30).
    Срок: max БО (baseline); если уже прошёл — max Finish/прогноз; если и он
    в прошлом — один период гранулярности (как у РД: бэклог закрыть за период).
    Отклонение 0 → 0.0 (план выполнен). Нет ни одной валидной даты → None.
    """
    if not abs(float(deviation_to_date or 0)):
        return 0.0
    rem_days: int | None = None
    bf = pd.to_datetime(baseline_finish, errors="coerce", dayfirst=True, format="mixed").dropna()
    if not bf.empty:
        last_bf = bf.max()
        if pd.notna(last_bf):
            rem_days = (last_bf.date() - report_date).days
    if (rem_days is None or rem_days <= 0) and schedule_finish is not None:
        sf = pd.to_datetime(
            schedule_finish, errors="coerce", dayfirst=True, format="mixed"
        ).dropna()
        if not sf.empty:
            last_sf = sf.max()
            if pd.notna(last_sf):
                rem_days = (last_sf.date() - report_date).days
    if rem_days is None:
        # Нет дат вовсе — всё равно показать бэклог за один период гранулярности.
        rem_days = max(int(period_multiplier) or 1, 1)
    elif rem_days <= 0:
        # Срок плана/прогноза уже прошёл, бэклог ещё есть — считать за 1 период.
        rem_days = max(int(period_multiplier) or 1, 1)
    return (abs(float(deviation_to_date)) / float(rem_days)) * float(period_multiplier)


def _pd_baseline_finish_series(
    df: pd.DataFrame,
    baseline_col: Optional[str],
) -> pd.Series:
    """Даты базового окончания (БП); plan end / Finish не подставляются."""
    if baseline_col and baseline_col in df.columns:
        return pd.to_datetime(
            df[baseline_col], errors="coerce", dayfirst=True, format="mixed"
        )
    return pd.Series(pd.NaT, index=df.index)


def _pd_delay_plan_finish_dt_series(
    df: pd.DataFrame,
    row_mask: Optional[pd.Series] = None,
    *,
    baseline_col: Optional[str] = None,
    schedule_col: Optional[str] = None,
) -> pd.Series:
    """Срок сдачи раздела ПД для графика просрочки: БП → текущий план / plan end."""
    m = (
        row_mask.fillna(False)
        if row_mask is not None
        else pd.Series(True, index=df.index)
    )
    b_base = baseline_col or _pd_msp_find_baseline_finish_col(df)
    s_ref = schedule_col or _pd_msp_find_schedule_finish_col(df)
    if not s_ref and "plan end" in df.columns:
        s_ref = "plan end"
    pick = _pd_pick_finish_col(df, m, baseline_col=b_base, schedule_col=s_ref)
    out = _pd_baseline_finish_series(df, b_base)
    if pick and pick in df.columns:
        pick_dt = pd.to_datetime(
            df[pick], errors="coerce", dayfirst=True, format="mixed"
        )
        out = out.where(out.notna(), pick_dt)
    if "plan end" in df.columns:
        pe = pd.to_datetime(
            df["plan end"], errors="coerce", dayfirst=True, format="mixed"
        )
        out = out.where(out.notna(), pe)
    return out


def _pd_delay_plan_due_row_mask(
    plan_finish: pd.Series,
    plan_start: pd.Series,
    ts: pd.Timestamp,
) -> pd.Series:
    """Раздел в плане на дату отчёта: срок сдачи наступил или работы уже начаты."""
    ts_n = pd.Timestamp(ts).normalize()
    pf = pd.to_datetime(plan_finish, errors="coerce", dayfirst=True, format="mixed")
    ps = pd.to_datetime(plan_start, errors="coerce", dayfirst=True, format="mixed")
    due_finish = pf.notna() & (pf.dt.normalize() <= ts_n)
    due_start = (
        ps.notna()
        & (ps.dt.normalize() <= ts_n)
        & (~due_finish)
        & (pf.isna() | (pf.dt.normalize() > ts_n))
    )
    return (due_finish | due_start).fillna(False)


def _pd_msp_find_schedule_finish_col(df: pd.DataFrame):
    # «Окончание» (текущий график) → `plan end` / `Окончание`. НЕ базовое окончание.
    for cand in ("plan end", "finish"):
        if cand in df.columns:
            return cand
    candidates = []
    for c in df.columns:
        cs = str(c).strip()
        cl = cs.lower()
        if "базов" in cl or "baseline" in cl or cl.startswith("base"):
            continue
        if cl in ("finish", "окончание", "plan end") or (
            cl.endswith("окончание") and "план" not in cl and "факт" not in cl
        ):
            candidates.append((len(cs), c))
    if candidates:
        return min(candidates, key=lambda x: x[0])[1]
    return None


def _pd_msp_pct_complete_col(df: pd.DataFrame):
    # «% завершения» → `pct complete` в каноническом MSP.
    if "pct complete" in df.columns:
        return "pct complete"
    for c in df.columns:
        cl = str(c).strip().lower()
        if "%" in cl and ("заверш" in cl or "complete" in cl):
            return c
        if "процент" in cl and "заверш" in cl:
            return c
        if "pct" in cl and "complete" in cl:
            return c
    return None


def _pd_msp_actual_finish_col(df: pd.DataFrame):
    for c in df.columns:
        cl = str(c).strip().lower()
        if ("actual" in cl or "фактичес" in cl or cl.startswith("факт")) and (
            "finish" in cl or "оконч" in cl
        ):
            return c
    if "actual finish" in df.columns:
        return "actual finish"
    # ВАЖНО: не использовать `base end` как «фактическое окончание» — это БАЗОВОЕ
    # окончание. Иначе синтетическая просрочка = base_end − base_end = 0 (индикаторы
    # «без просрочки», Сводка = 0). Нет факта окончания → отклонение = Окончание − Базовое.
    return None


def _pd_cumsum_by_date(dates, row_mask):
    dt = pd.to_datetime(dates, errors="coerce", dayfirst=True, format="mixed")
    m = row_mask.fillna(False) & dt.notna()
    if not m.any():
        return pd.DataFrame(columns=["Дата", "Количество"])
    s = dt.loc[m].dt.normalize()
    daily = s.groupby(s).size().reset_index(name="cnt")
    daily.columns = ["Дата", "cnt"]
    daily = daily.sort_values("Дата")
    daily["Количество"] = daily["cnt"].cumsum()
    return daily[["Дата", "Количество"]]


def _pd_cipher_filled_mask(df: pd.DataFrame) -> tuple[Optional[str], pd.Series]:
    """Задачи ПД по ТЗ: признак — непустой «шифр ПД РД» (разные подписи колонки в выгрузках).

    После ``web_loader._MSP_COLUMN_REMAP`` исходный «Шифр_ПД_и_РД» → canonical ``abbreviation``.
    """
    cipher_col = _dev_tasks_find_column(
        df,
        [
            "abbreviation",
            "Шифр_ПД_и_РД",
            "Шифр ПД и РД",
            "шифр пд и рд",
            "Шифр ПД РД",
            "шифр ПД РД",
            "Шифр ПД/РД",
            "шифр ПД/РД",
            "ШифрПДРД",
            "Cipher PD RD",
            "Шифр",
            "Cipher",
            "DivisionCipher",
        ],
    )
    if not cipher_col or cipher_col not in df.columns:
        return cipher_col, pd.Series(False, index=df.index)
    cs = df[cipher_col].astype(str).str.strip()
    ok = cs.ne("") & ~cs.str.lower().isin(("nan", "none", "-", "—", "null"))
    return cipher_col, ok


def _pd_cumsum_by_granularity(dates, row_mask, gran_key: str):
    """Накопительное число задач по выбранной гранулярности (день / неделя / месяц)."""
    dt = pd.to_datetime(dates, errors="coerce", dayfirst=True, format="mixed")
    m = row_mask.fillna(False) & dt.notna()
    if not m.any():
        return pd.DataFrame(columns=["Дата", "Количество"])
    s = dt.loc[m].dt.normalize()
    if gran_key == "week":
        bucket = s - pd.to_timedelta(s.dt.dayofweek, unit="D")
    elif gran_key == "month":
        bucket = s - pd.to_timedelta(s.dt.day - 1, unit="D")
    else:
        bucket = s
    daily = bucket.groupby(bucket).size().reset_index(name="cnt")
    daily.columns = ["Дата", "cnt"]
    daily = daily.sort_values("Дата")
    daily["Количество"] = daily["cnt"].cumsum()
    return daily[["Дата", "Количество"]]


def _pd_pick_finish_col(
    df: pd.DataFrame,
    row_mask: pd.Series,
    *,
    baseline_col: Optional[str],
    schedule_col: Optional[str],
) -> Optional[str]:
    """Колонка даты окончания с наибольшим числом валидных дат на строках маски."""
    m = row_mask.fillna(False)
    best_col: Optional[str] = None
    best_n = -1
    for cand in (baseline_col, schedule_col):
        if not cand or cand not in df.columns:
            continue
        dt = pd.to_datetime(df[cand], errors="coerce", dayfirst=True, format="mixed")
        n = int((m & dt.notna()).sum()) if m.any() else int(dt.notna().sum())
        if n > best_n:
            best_n = n
            best_col = cand
    return best_col


def _pd_dynamics_line_tasks_mask(df: pd.DataFrame, masks: dict) -> pd.Series:
    """
    Задачи для линий «План»/«Прогноз»/«Факт» и KPI «План по проекту (БП)».

    ТЗ: ур.5 под «Этап. Проектная документация» (ур.4) + непустой «Шифр ПД и РД»
    — та же маска, что metrics/dynamics в ``_pd_section_masks``.
    """
    empty = pd.Series(False, index=df.index)
    metrics = masks.get("metrics_mask", empty).fillna(False)
    if metrics.any():
        return metrics
    dyn = masks.get("dynamics_mask", empty).fillna(False)
    if dyn.any():
        return dyn
    # Fallback: ур.5 в ветке «Проектная документация» с шифром.
    level_col = masks.get("level_col")
    name_col = masks.get("name_col")
    hier_col = masks.get("hier_col")
    block_col = masks.get("block_col")
    if (
        level_col and level_col in df.columns
        and name_col and name_col in df.columns
        and hier_col and hier_col in df.columns
    ):
        lv_num = outline_level_numeric(df[level_col])
        parent_names = _pd_msp_immediate_parent_names(df, hier_col, name_col)
        parent_pd_stage = parent_names.map(_pd_msp_parent_is_pd_stage)
        _cipher_col, _cipher_ok = _pd_cipher_filled_mask(df)
        _cipher_ok = (
            _cipher_ok.fillna(False) if _cipher_col else pd.Series(False, index=df.index)
        )
        fb = lv_num.eq(5) & parent_pd_stage & _cipher_ok
        if fb.any():
            return fb
        ancestor_pd = _pd_msp_ancestor_under_pd_stage(
            df, hier_col, name_col, block_col=block_col
        )
        fb = lv_num.eq(5) & ancestor_pd & _cipher_ok
        if fb.any():
            return fb
    return empty


def _pd_dynamics_chart_row_mask(
    metrics_mask: pd.Series,
    dynamics_mask: pd.Series,
    finish_dates,
) -> tuple:
    """Маска строк для накопительного графика ПД (fallback на metrics при пустой dynamics)."""
    m_met = metrics_mask.fillna(False)
    m_dyn = dynamics_mask.fillna(False)
    dt = pd.to_datetime(finish_dates, errors="coerce", dayfirst=True, format="mixed")

    def _dated_count(mask: pd.Series) -> int:
        return int((mask & dt.notna()).sum())

    if _dated_count(m_dyn) > 0:
        return m_dyn, False
    if _dated_count(m_met) > 0:
        return m_met, True
    return (m_dyn if m_dyn.any() else m_met), not bool(m_dyn.any())


def _pd_axis_date_tick_label_ru(ts: Any) -> str:
    """Подпись даты на оси графика ПД: «2 мар. 2025» (рус.)."""
    t = pd.Timestamp(ts)
    if pd.isna(t):
        return ""
    mn = RUSSIAN_MONTHS.get(int(t.month), "")
    short = ((mn[:3] + ".").lower()) if mn else ""
    return f"{int(t.day)} {short} {int(t.year)}"


def _rd_dynamics_chart_month_ticks_ru(dates) -> tuple[list, list]:
    """Подписи оси X для динамики РД/ПД: «Май 2025» (рус.).

    Тик ставится внутри видимого диапазона дат (не на 1-е число месяца вне данных),
    иначе подписи месяцев пропадают с оси.
    """
    all_dates = pd.to_datetime(dates, errors="coerce").dropna()
    if all_dates.empty:
        return [], []
    d_min = pd.Timestamp(all_dates.min()).normalize()
    d_max = pd.Timestamp(all_dates.max()).normalize()
    periods = pd.period_range(d_min.to_period("M"), d_max.to_period("M"), freq="M")
    tickvals: list = []
    ticktext: list = []
    for p in periods:
        month_start = pd.Timestamp(p.to_timestamp()).normalize()
        month_end = pd.Timestamp(p.to_timestamp(how="end")).normalize()
        # Середина пересечения месяца с фактическим диапазоном данных.
        lo = max(month_start, d_min)
        hi = min(month_end, d_max)
        if lo > hi:
            continue
        tickvals.append(lo + (hi - lo) / 2)
        ticktext.append(format_period_ru(p))
    if len(tickvals) > 18:
        step = max(1, (len(tickvals) + 11) // 12)
        tickvals = tickvals[::step]
        ticktext = ticktext[::step]
    return tickvals, ticktext


def _line_chart_legend_below(*, n_items: int = 2, long_labels: bool = True) -> dict:
    """Горизонтальная легенда под графиком без наложения длинных подписей."""
    entry_w = 260 if long_labels else 140
    # Длинные подписи: по одной «ячейке» шире + больший gap между пунктами.
    return standard_chart_legend(
        title_text="",
        orientation="h",
        yanchor="top",
        y=-0.36,
        xanchor="center",
        x=0.5,
        tracegroupgap=48,
        itemsizing="constant",
        itemwidth=48,
        entrywidthmode="pixels",
        entrywidth=entry_w,
        font=dict(size=13),
        valign="middle",
    )


def _line_chart_legend_above(*, n_items: int = 2, long_labels: bool = True) -> dict:
    """Легенда над графиком — не пересекается с осью «Период» и тиками месяцев."""
    entry_w = 260 if long_labels else 140
    return standard_chart_legend(
        title_text="",
        orientation="h",
        yanchor="bottom",
        y=1.12,
        xanchor="left",
        x=0.0,
        tracegroupgap=48,
        itemsizing="constant",
        itemwidth=48,
        entrywidthmode="pixels",
        entrywidth=entry_w,
        font=dict(size=13),
        valign="middle",
    )


def _apply_rd_dynamics_line_chart_theme(
    fig,
    *,
    plan_color: str = "#2E86AB",
    fact_color: str = "#F39C12",
) -> None:
    _ax = _fin_chart_axis_color()
    _ymax = 0.0
    for _tr in fig.data or []:
        _ys = getattr(_tr, "y", None)
        if _ys is None:
            continue
        try:
            for _v in _ys:
                if _v is not None and pd.notna(_v):
                    _ymax = max(_ymax, float(_v))
        except (TypeError, ValueError):
            pass
    _y_top = (_ymax * 1.14) if _ymax > 0 else None
    _yaxis_kw: dict = dict(
        tickfont=dict(size=10, color=_ax),
        title_font=dict(color=_ax),
        rangemode="tozero",
        automargin=True,
    )
    if _y_top is not None:
        _yaxis_kw["range"] = [0, _y_top]
    _m = fig.layout.margin
    _mt = int(getattr(_m, "t", None) or 40)
    fig.update_layout(
        xaxis=dict(
            tickfont=dict(size=10, color=_ax),
            title_font=dict(color=_ax),
        ),
        yaxis=_yaxis_kw,
        margin=dict(t=max(_mt, 64)),
    )
    for _tr in fig.data or []:
        _tn = str(getattr(_tr, "name", "") or "")
        if "План" in _tn:
            _tr.textfont = dict(color=plan_color, size=20)
        elif "Факт" in _tn:
            _tr.textfont = dict(color=fact_color, size=20)
        try:
            _tr.cliponaxis = False
        except Exception:
            pass


# ==================== DASHBOARD 8.7: Documentation ====================
def dashboard_documentation(
    df,
    page_title: str = "Рабочая/Проектная документация",
    *,
    embed_delay_at_end: bool = True,
):

    _doc_fk = (
        "rd_work_"
        if page_title == "Рабочая документация"
        else ("pd_doc_" if page_title == "Проектная документация" else "doc_")
    )
    is_pd = page_title == "Проектная документация"

    if df is None or not hasattr(df, "columns") or df.empty:
        if is_pd:
            if _rd_plan_fallback_view(page_title=page_title, doc_code="ПД", source_key="pd_plan_data"):
                return
        else:
            if _rd_plan_fallback_view(page_title=page_title, doc_code="РД", source_key="rd_plan_data"):
                return
        st.warning(
            f"Для отчёта «{page_title}» загрузите файл с данными проекта (CSV/Excel с колонками по задачам и "
            + ("ПД / MS Project." if is_pd else "РД.")
        )
        return

    # Find column names (they might have different formats)
    # Try to find columns by partial name matching
    def find_column(data, possible_names):
        """Find column by possible names"""
        for col in data.columns:
            # Normalize column name: remove newlines, extra spaces, normalize case
            col_normalized = str(col).replace("\n", " ").replace("\r", " ").strip()
            col_lower = col_normalized.lower()

            for name in possible_names:
                name_lower = name.lower().strip()
                # Exact match (case insensitive)
                if name_lower == col_lower:
                    return col
                # Substring match
                if name_lower in col_lower or col_lower in name_lower:
                    return col
                # Check if all key words from name are in column
                name_words = [w for w in name_lower.split() if len(w) > 2]
                if name_words and all(word in col_lower for word in name_words):
                    return col

        # Special handling for RD count column with key words
        if any(
            "разделов" in n.lower() and "рд" in n.lower() and "договор" in n.lower()
            for n in possible_names
        ):
            for col in data.columns:
                col_lower = str(col).lower().replace("\n", " ").replace("\r", " ")
                key_words = ["разделов", "рд", "договор", "количество"]
                if all(word in col_lower for word in key_words if len(word) > 3):
                    return col

        return None

    # Find required columns (sample_project_data_fixed.csv: «РД по Договору», нет «Количество разделов РД по Договору»)
    rd_count_col = find_column(
        df,
        [
            "Количество разделов РД по Договору",
            "Количество разделов РД",
            "РД по Договору",
            "разделов РД",
            "Количетсов разделов РД по Договору",  # Handle typo
            "Количество разделов РД по договору",
        ],
    )

    on_approval_col = find_column(df, ["На согласовании", "согласовании"])
    in_production_col = find_column(
        df,
        [
            "Выдано в производство работ",
            "Разработано",
            "В работе",
            "производство работ",
            "в производство",
        ],
    )
    plan_start_col = (
        "plan start"
        if "plan start" in df.columns
        else find_column(df, ["Старт План", "План Старт"])
    )
    plan_end_col = (
        "plan end"
        if "plan end" in df.columns
        else find_column(df, ["Конец План", "План Конец"])
    )
    base_start_col = (
        "base start"
        if "base start" in df.columns
        else find_column(df, ["Старт Факт", "Факт Старт"])
    )
    base_end_col = (
        "base end"
        if "base end" in df.columns
        else find_column(df, ["Конец Факт", "Факт Конец"])
    )

    # Для РД — колонки выгрузки; для ПД достаточно задач MS Project.
    # «На согласовании» не блокирует отчёт: в многих MSP-выгрузках колонки нет —
    # иначе включается только fallback по CSV без графика «Динамика выдачи РД».
    missing_cols = []
    if not is_pd:
        if not rd_count_col:
            missing_cols.append("Количество разделов РД по Договору")
        if not in_production_col and not _rd_has_tessa_production_dates():
            missing_cols.append("Выдано в производство работ")

    if missing_cols:
        _src_key = "pd_plan_data" if is_pd else "rd_plan_data"
        _doc = "ПД" if is_pd else "РД"
        if _rd_plan_fallback_view(page_title=page_title, doc_code=_doc, source_key=_src_key):
            return
        st.warning(f"⚠️ Отсутствуют необходимые колонки: {', '.join(missing_cols)}")
        st.info("Пожалуйста, убедитесь, что файл содержит все необходимые колонки.")
        return

    section_col = (
        "section" if "section" in df.columns else find_column(df, ["Раздел", "section"])
    )
    contractor_col = find_column(
        df,
        ["Передано подрядчику", "Выдана подрядчику", "подрядчику", "TransferToCustomer"],
    )
    rework_col = find_column(df, ["На доработке", "доработке"])
    period_source_col = (
        plan_end_col if plan_end_col and plan_end_col in df.columns else plan_start_col
    )

    def _to_numeric_series(series):
        return pd.to_numeric(
            series.astype(str)
            .str.replace(" ", "", regex=False)
            .str.replace(",", ".", regex=False),
            errors="coerce",
        ).fillna(0.0)

    def _to_datetime_series(series):
        return pd.to_datetime(series.astype(str), errors="coerce", dayfirst=True, format="mixed")

    # Find project column for filtering
    project_col = (
        "project name"
        if "project name" in df.columns
        else find_column(df, ["Проект", "project"])
    )
    _pd_proj_opts_src = df
    if is_pd:
        try:
            _pd_snap_all = st.session_state.get("project_data_all_snapshots")
        except Exception:
            _pd_snap_all = None
        if _pd_snap_all is not None and not getattr(_pd_snap_all, "empty", True):
            _pd_proj_opts_src = _pd_snap_all.copy()
            df = _pd_snap_all.copy()
    if project_col and project_col in _pd_proj_opts_src.columns:
        _pd_proj_opts_src = _project_column_apply_canonical(_pd_proj_opts_src, project_col)
    if project_col and project_col in df.columns:
        df = _project_column_apply_canonical(df, project_col)
    if not is_pd:
        _cipher_enrich_doc = find_column(
            df,
            [
                "abbreviation",
                "Шифр_ПД_и_РД",
                "Шифр ПД и РД",
                "Шифр ПД/РД",
                "Шифр раздела",
                "Шифр",
                "DivisionCipher",
            ],
        )
        if project_col and _cipher_enrich_doc and _cipher_enrich_doc in df.columns:
            try:
                df = _augment_df_with_tessa_rd(df, project_col, _cipher_enrich_doc)
            except Exception:
                pass

    # Подпись раздела для фильтра: «Шифр + Наименование» (ПД и РД).
    rd_section_labels_series: Optional[pd.Series] = _doc_section_labels_series(
        df, is_pd=is_pd, find_column_fn=find_column, section_col=section_col
    )

    rd_metric_mode = "Количество разделов"
    show_forecast_date_col = True

    # Add filters (развёрнуты по умолчанию — как на экранах «как было»).
    # panel_key _v2 — сброс старого session_state свёрнутого expander.
    with filters_panel(
        st,
        panel_key=f"{_doc_fk}filters_v2",
        reset_keys=[_doc_fk],
        expanded=True,
    ):
        filter_col1, filter_col2, filter_col3 = st.columns(3, gap="small")
        # Filter by project (несколько проектов; пусто = все)
        # R23-06 (стр.17): в ПД по умолчанию выбраны все проекты («Все» вместо «Select all»).
        selected_projects_doc: list[str] = []
        if project_col and project_col in _pd_proj_opts_src.columns:
            with filter_col1:
                _proj_opts = _unique_project_labels_for_select(_pd_proj_opts_src[project_col])
                selected_projects_doc, _ = project_filter_multiselect(st, _proj_opts,
                    key=f"{_doc_fk}project_filter_ms",
                )
        selected_date_start = None
        selected_date_end = None
        selected_sections_doc: list[str] = []
        def _period_filter_widgets_pd() -> None:
            _month_labels = _msp_snapshot_month_labels(df, descending=True)
            if _month_labels:
                _pd_period_key = f"{_doc_fk}period_month"
                _deviations_migrate_period_month_multiselect_state(
                    st, _pd_period_key, _month_labels
                )
                st.multiselect(
                    "Период",
                    options=_month_labels,
                    key=_pd_period_key,
                    placeholder="Все месяцы",
                    help=(
                        "Месяцы выгрузки MSP на FTP (от текущего к более ранним). "
                        "Пустой выбор — последний снимок по каждому проекту."
                    ),
                )
                return
            _period_filter_widgets()
        def _period_filter_widgets() -> None:
            nonlocal selected_date_start, selected_date_end
            if not period_source_col or period_source_col not in df.columns:
                suppress_caption(
                    "Колонка плановой даты для периода не найдена (plan end / plan start)."
                )
                return
            df_dates = _to_datetime_series(df[period_source_col])
            valid_dates = df_dates[df_dates.notna()]
            if valid_dates.empty:
                suppress_caption("Нет валидных дат для фильтра периода.")
                return
            min_date = valid_dates.min().date()
            max_date = valid_dates.max().date()
            selected_period_mode = st.selectbox(
                "Период",
                ["Весь период (за всё время)", "Выбор диапазона дат"],
                index=0,
                key=f"{_doc_fk}period_mode",
            )
            if selected_period_mode == "Выбор диапазона дат":
                selected_period = st.date_input(
                    LABEL_PERIOD,
                    value=(min_date, max_date),
                    min_value=min_date,
                    max_value=max_date,
                    key=f"{_doc_fk}date_range",
                    format="DD.MM.YYYY",
                    label_visibility="collapsed",
                )
                if isinstance(selected_period, tuple) and len(selected_period) == 2:
                    selected_date_start, selected_date_end = selected_period
                else:
                    selected_date_start = selected_period
                    selected_date_end = selected_period
            else:
                suppress_caption(f"Весь период: {min_date:%d.%m.%Y} - {max_date:%d.%m.%Y}")
        def _section_filter_widgets_pd() -> None:
            nonlocal selected_sections_doc
            if rd_section_labels_series is not None:
                section_options = sorted(
                    {
                        str(v).strip()
                        for v in rd_section_labels_series.tolist()
                        if str(v).strip()
                        and str(v).strip().lower() not in ("nan", "none", "(не указано)")
                    },
                    key=lambda x: x.casefold(),
                )
                if not section_options:
                    _cc, _ok = _pd_cipher_filled_mask(df)
                    if _cc and _cc in df.columns:
                        section_options = sorted(
                            {
                                str(v).strip()
                                for v in df.loc[_ok.fillna(False), _cc].tolist()
                                if str(v).strip()
                            },
                            key=lambda x: x.casefold(),
                        )
                _sec_ms_key = f"{_doc_fk}section_filter_ms"
                _sync_multiselect_session_state(
                    _sec_ms_key, section_options, all_by_default=False
                )
                selected_sections_doc = st.multiselect(
                    "Вид раздела",
                    options=section_options,
                    key=_sec_ms_key,
                    placeholder="Все разделы",
                    help="Шифр раздела и наименование через пробел.",
                )
            elif section_col and section_col in df.columns:
                section_options = sorted(
                    {
                        str(v).strip()
                        for v in df[section_col].dropna().tolist()
                        if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
                    },
                    key=lambda x: x.casefold(),
                )
                _sec_ms_key = f"{_doc_fk}section_filter_ms"
                _sync_multiselect_session_state(
                    _sec_ms_key, section_options, all_by_default=False
                )
                selected_sections_doc = st.multiselect(
                    "Вид раздела",
                    options=section_options,
                    key=_sec_ms_key,
                    placeholder="Все разделы",
                )
            else:
                suppress_caption("Колонка раздела ПД не найдена.")
        def _section_filter_widgets_rd() -> None:
            nonlocal selected_sections_doc
            if rd_section_labels_series is not None:
                section_options = sorted(
                    {
                        str(v).strip()
                        for v in rd_section_labels_series.tolist()
                        if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
                    },
                    key=lambda x: x.casefold(),
                )
                _sec_ms_key = f"{_doc_fk}section_filter_ms"
                _sync_multiselect_session_state(
                    _sec_ms_key, section_options, all_by_default=False
                )
                selected_sections_doc = st.multiselect(
                    "Раздел",
                    options=section_options,
                    key=_sec_ms_key,
                    placeholder="Все разделы",
                    help="Подпись: шифр раздела и наименование через пробел.",
                )
            elif section_col and section_col in df.columns:
                section_options = sorted(
                    {
                        str(v).strip()
                        for v in df[section_col].dropna().tolist()
                        if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
                    },
                    key=lambda x: x.casefold(),
                )
                _sec_ms_key = f"{_doc_fk}section_filter_ms"
                _sync_multiselect_session_state(
                    _sec_ms_key, section_options, all_by_default=False
                )
                selected_sections_doc = st.multiselect(
                    "Раздел",
                    options=section_options,
                    key=_sec_ms_key,
                    placeholder="Все разделы",
                )
            else:
                suppress_caption(
                    "Колонки раздела РД не найдены (шифр/наименование или колонка «Раздел»)."
                )
        # РД: проект | раздел (шифр + наименование) | период. ПД: без изменений — проект | период | раздел.
        if not is_pd:
            with filter_col2:
                _section_filter_widgets_rd()
            with filter_col3:
                _period_filter_widgets()
        else:
            with filter_col2:
                _period_filter_widgets_pd()
            with filter_col3:
                _section_filter_widgets_pd()
        # Filter by RD status — отдельной строкой, чтобы не ломать сетку selectbox’ов
        selected_statuses: list[str] = []
        rd_status_options: list[str] = []
        if on_approval_col and on_approval_col in df.columns:
            rd_status_options.append("На согласовании")
        if (
            ("_tessa_production_dt" in df.columns and df["_tessa_production_dt"].notna().any())
            or (in_production_col and in_production_col in df.columns)
            or _rd_has_tessa_production_dates()
        ):
            rd_status_options.append("Выдано в производство работ")
        if contractor_col and contractor_col in df.columns:
            rd_status_options.append(
                "Передано подрядчику"
                if page_title == "Рабочая документация"
                else "Выдана подрядчику"
            )
        if rework_col and rework_col in df.columns:
            rd_status_options.append("На доработке")
        if not is_pd:
            rd_status_options.append(_RD_TESSA_STATUS_NOT_ISSUED)
        # R23-06 (стр.17): статус «Просрочено подрядчиком» — и для РД, и для ПД.
        if "Просрочено подрядчиком" not in rd_status_options:
            rd_status_options.append("Просрочено подрядчиком")
        _status_label = "Статус"
        if rd_status_options:
            selected_statuses = st.pills(
                _status_label,
                rd_status_options,
                selection_mode="multi",
                default=rd_status_options,
                key=f"{_doc_fk}status_filter",
            )
            if selected_statuses is None:
                selected_statuses = []
        else:
            suppress_caption("Нет колонок статусов РД/ПД для фильтра.")
        if not is_pd:
            rd_metric_mode = st.radio(
                "Единица отображения",
                ["Количество разделов", "% от общего объёма"],
                horizontal=True,
                key=f"{_doc_fk}rd_metric_mode",
            )
            show_forecast_date_col = st.checkbox(
                "Показать прогнозную дату выдачи разделов",
                value=True,
                key=f"{_doc_fk}show_forecast_date",
            )

    # Apply filters to data
    filtered_df = df.copy()
    pd_report_date = date.today()
    if is_pd:
        if selected_date_end:
            pd_report_date = selected_date_end
        elif selected_date_start:
            pd_report_date = selected_date_start
        if "snapshot_date" in filtered_df.columns:
            filtered_df = _deviations_apply_snapshot_month_filter(
                filtered_df,
                session_key=f"{_doc_fk}period_month",
                dynamics=False,
            )
            filtered_df = _pd_dedupe_msp_tasks_latest(filtered_df)

    # Apply project filter
    # R23-06 (стр.17): если выбраны все опции — фильтр не сужает выборку (эквивалент «Все»).
    # Это корректно обрабатывает default=all и избавляет ПД-задачи MSP (где section_col
    # часто пуст) от ложного выпадения из выборки при default=all по разделам.
    if (
        selected_projects_doc
        and project_col
        and project_col in filtered_df.columns
    ):
        filtered_df = _filter_df_by_project_labels(
            filtered_df, selected_projects_doc, col=project_col
        )

    if selected_sections_doc:
        _sset = {str(x).strip() for x in selected_sections_doc if str(x).strip()}
        if rd_section_labels_series is not None:
            _lbl = rd_section_labels_series.reindex(filtered_df.index)
            try:
                _all_rd_labels = {
                    str(v).strip()
                    for v in rd_section_labels_series.tolist()
                    if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
                }
            except Exception:
                _all_rd_labels = set()
            if _sset and _sset != _all_rd_labels:
                filtered_df = filtered_df[_lbl.isin(_sset)]
        elif (not is_pd) and section_col and section_col in filtered_df.columns:
            try:
                _all_sec_opts = {
                    str(v).strip()
                    for v in df[section_col].dropna().tolist()
                    if str(v).strip() and str(v).strip().lower() not in ("nan", "none")
                }
            except Exception:
                _all_sec_opts = set()
            if _sset and _sset != _all_sec_opts:
                filtered_df = filtered_df[
                    filtered_df[section_col].astype(str).str.strip().isin(_sset)
                ]

    # Apply date filter (РД и ПД без snapshot_date — срез по plan end / plan start)
    if (
        not (is_pd and "snapshot_date" in df.columns)
        and selected_date_start
        and selected_date_end
        and period_source_col
        and period_source_col in df.columns
    ):
        filtered_df[period_source_col + "_parsed"] = _to_datetime_series(
            filtered_df[period_source_col]
        )
        date_mask = (
            filtered_df[period_source_col + "_parsed"].notna()
            & (filtered_df[period_source_col + "_parsed"].dt.date >= selected_date_start)
            & (filtered_df[period_source_col + "_parsed"].dt.date <= selected_date_end)
        )
        filtered_df = filtered_df[date_mask].copy()

    # Apply status filter: только если выбрано не «все метки» и не пусто (пусто = все)
    if selected_statuses and set(selected_statuses) != set(rd_status_options):
        status_mask = pd.Series([False] * len(filtered_df), index=filtered_df.index)

        if (
            "На согласовании" in selected_statuses
            and on_approval_col
            and on_approval_col in filtered_df.columns
        ):
            on_approval_series = (
                filtered_df[on_approval_col]
                .astype(str)
                .str.replace(",", ".", regex=False)
            )
            on_approval_numeric = pd.to_numeric(
                on_approval_series, errors="coerce"
            ).fillna(0)
            status_mask = status_mask | (on_approval_numeric > 0)

        if "Выдано в производство работ" in selected_statuses:
            status_mask = status_mask | _rd_in_production_mask(
                filtered_df, in_production_col
            )

        if (
            (
                "Выдана подрядчику" in selected_statuses
                or "Передано подрядчику" in selected_statuses
            )
            and contractor_col
            and contractor_col in filtered_df.columns
        ):
            contractor_series = (
                filtered_df[contractor_col]
                .astype(str)
                .str.replace(",", ".", regex=False)
            )
            contractor_numeric = pd.to_numeric(
                contractor_series, errors="coerce"
            ).fillna(0)
            status_mask = status_mask | (contractor_numeric > 0)

        if (
            "На доработке" in selected_statuses
            and rework_col
            and rework_col in filtered_df.columns
        ):
            rework_series = (
                filtered_df[rework_col].astype(str).str.replace(",", ".", regex=False)
            )
            rework_numeric = pd.to_numeric(rework_series, errors="coerce").fillna(0)
            status_mask = status_mask | (rework_numeric > 0)

        if "Просрочено подрядчиком" in selected_statuses:
            today_d = pd_report_date if is_pd else date.today()
            pe = pd.Series(pd.NaT, index=filtered_df.index)
            if plan_end_col and plan_end_col in filtered_df.columns:
                pe = pd.to_datetime(
                    filtered_df[plan_end_col].astype(str),
                    errors="coerce",
                    dayfirst=True,
                    format="mixed",
                )
            fe = pd.Series(pd.NaT, index=filtered_df.index)
            if base_end_col and base_end_col in filtered_df.columns:
                fe = pd.to_datetime(
                    filtered_df[base_end_col].astype(str),
                    errors="coerce",
                    dayfirst=True,
                    format="mixed",
                )
            issued = pd.Series(False, index=filtered_df.index)
            if contractor_col and contractor_col in filtered_df.columns:
                issued = (
                    pd.to_numeric(
                        filtered_df[contractor_col]
                        .astype(str)
                        .str.replace(",", ".", regex=False),
                        errors="coerce",
                    ).fillna(0)
                    > 0
                )
            done_on_time = fe.notna() & pe.notna() & (fe.dt.normalize() <= pe.dt.normalize())
            overdue_plan = pe.notna() & (pe.dt.date < today_d)
            oc_mask = issued & overdue_plan & (~done_on_time)
            status_mask = status_mask | oc_mask
            if is_pd:
                _pct_oc = _pd_msp_pct_complete_col(filtered_df)
                _pc_oc = (
                    pd.to_numeric(filtered_df[_pct_oc], errors="coerce").fillna(0.0)
                    if _pct_oc and _pct_oc in filtered_df.columns
                    else pd.Series(0.0, index=filtered_df.index)
                )
                _pe_oc = (
                    pd.to_datetime(
                        filtered_df[plan_end_col], errors="coerce", dayfirst=True, format="mixed"
                    )
                    if plan_end_col and plan_end_col in filtered_df.columns
                    else pd.Series(pd.NaT, index=filtered_df.index)
                )
                _be_oc = (
                    pd.to_datetime(
                        filtered_df[base_end_col], errors="coerce", dayfirst=True, format="mixed"
                    )
                    if base_end_col and base_end_col in filtered_df.columns
                    else pd.Series(pd.NaT, index=filtered_df.index)
                )
                _fin_oc = _pe_oc.where(_pe_oc.notna(), _be_oc)
                _pd_oc = _fin_oc.notna() & (_fin_oc.dt.date < today_d) & (_pc_oc < 99.99)
                status_mask = status_mask | _pd_oc

        if not is_pd and (
            "Не выдан" in selected_statuses
            or _RD_TESSA_STATUS_NOT_ISSUED in selected_statuses
        ):
            _nv_mask = ~_rd_in_production_mask(filtered_df, in_production_col)
            if on_approval_col and on_approval_col in filtered_df.columns:
                _oa = pd.to_numeric(
                    filtered_df[on_approval_col].astype(str).str.replace(",", ".", regex=False),
                    errors="coerce",
                ).fillna(0)
                _nv_mask &= _oa <= 0
            if contractor_col and contractor_col in filtered_df.columns:
                _ct = pd.to_numeric(
                    filtered_df[contractor_col].astype(str).str.replace(",", ".", regex=False),
                    errors="coerce",
                ).fillna(0)
                _nv_mask &= _ct <= 0
            if rework_col and rework_col in filtered_df.columns:
                _rw = pd.to_numeric(
                    filtered_df[rework_col].astype(str).str.replace(",", ".", regex=False),
                    errors="coerce",
                ).fillna(0)
                _nv_mask &= _rw <= 0
            if "_tessa_card_count" in filtered_df.columns:
                _nv_mask &= pd.to_numeric(filtered_df["_tessa_card_count"], errors="coerce").fillna(
                    0
                ) <= 0
            elif "_tessa_production_dt" in filtered_df.columns:
                _nv_mask &= filtered_df["_tessa_production_dt"].isna()
            status_mask = status_mask | _nv_mask.fillna(False)

        filtered_df = filtered_df[status_mask].copy()

    if (
        is_pd
        and rd_status_options
        and selected_statuses
        and set(selected_statuses) != set(rd_status_options)
    ):
        suppress_caption(
            "Фильтр по статусу ПД сужает строки по колонкам выдачи/подрядчика и просрочки. "
            "Если выбраны не все статусы (например только «Просрочено подрядчиком»), KPI и диаграммы по задачам MSP "
            "(ур. 5, шифр ПД РД, родитель «Проектная документация») могут быть пустыми — включите все статусы в фильтре."
        )

    if project_col and project_col in filtered_df.columns:
        filtered_df = _project_column_apply_canonical(filtered_df, project_col)

    if filtered_df.empty:
        st.info("Нет данных для выбранных фильтров.")
        return

    # Use filtered_df for all subsequent operations
    df = filtered_df

    if is_pd:
        ensure_date_columns(df)
        ensure_msp_hierarchy_columns(df)

    if not is_pd:
        # Prepare data for pie chart "Исполнение РД"
        # R23-07 (стр.20): категории круговой — Принято / На рассм. / Возвр. /
        # Не принято / Не выдано. «Принято/На рассм./Возвр./Не принято»
        # берутся из TESSA (KrState карточек `tessa_*_rd.csv`), если данные
        # загружены; иначе — fallback на MSP-агрегаты (Выдано→Принято,
        # На согласовании→На рассм., На доработке→Возвр., Не принято=0).
        try:
            total_sections = (
                float(_to_numeric_series(df[rd_count_col]).sum())
                if rd_count_col and rd_count_col in df.columns
                else 0.0
            )
            issued_sum = float(_rd_in_production_mask(df, in_production_col).sum())
            on_ap_sum = (
                float(_to_numeric_series(df[on_approval_col]).sum())
                if on_approval_col and on_approval_col in df.columns
                else 0.0
            )
            rework_sum = (
                float(_to_numeric_series(df[rework_col]).sum())
                if rework_col and rework_col in df.columns
                else 0.0
            )

            # Исполнение РД: Status из tessa_*_rd.csv; 100% = other_*_rd.csv;
            # «Не выдано» = план − три активных статуса.
            _stage_counts = _count_rd_pie_tz(selected_projects_doc or None)
            _stage_has_any = any(v > 0 for v in _stage_counts.values())

            if _stage_has_any:
                _active_sum = float(sum(_stage_counts.values()))
                if _active_sum > total_sections > 0:
                    _sc = total_sections / _active_sum
                    _stage_counts = {
                        k: int(round(v * _sc)) for k, v in _stage_counts.items()
                    }
                    _active_sum = float(sum(_stage_counts.values()))
                not_issued_sum = max(total_sections - _active_sum, 0.0)
                st.subheader("Исполнение РД")
                suppress_caption(
                    "Исполнение РД: статусы из tessa_*_rd.csv (поле Status) — "
                    "«Выдано в производство работ», «На рассмотрении у ГИП», "
                    "«Возвращено на доработку»; «Не выдано» = разделы "
                    "other_*_rd.csv минус эти три категории."
                )
                pie_data = {
                    _RD_TESSA_STATUS_PRODUCTION: int(
                        _stage_counts.get(_RD_TESSA_STATUS_PRODUCTION, 0)
                    ),
                    _RD_TESSA_STATUS_REVIEW: int(
                        _stage_counts.get(_RD_TESSA_STATUS_REVIEW, 0)
                    ),
                    _RD_TESSA_STATUS_REWORK: int(
                        _stage_counts.get(_RD_TESSA_STATUS_REWORK, 0)
                    ),
                    _RD_TESSA_STATUS_NOT_ISSUED: int(round(max(not_issued_sum, 0.0))),
                }
                pie_data = {k: v for k, v in pie_data.items() if v > 0}
                _pie_color_map = {
                    _RD_TESSA_STATUS_PRODUCTION: "#27AE60",
                    _RD_TESSA_STATUS_REVIEW: "#F1C40F",
                    _RD_TESSA_STATUS_REWORK: "#C0392B",
                    _RD_TESSA_STATUS_NOT_ISSUED: "#F5A9C0",
                }
                _build_pie = bool(pie_data)
            else:
                _tessa_counts = _count_tessa_rd_krstates(selected_projects_doc or None)
                _tessa_has_any = any(v > 0 for v in _tessa_counts.values())
                _used_tessa_source = False
                transferred_sum = 0.0
                if _tessa_has_any:
                    accepted_sum = float(_tessa_counts.get("Принято", 0))
                    review_sum = float(_tessa_counts.get("На рассм.", 0))
                    return_sum = float(_tessa_counts.get("Возвр.", 0))
                    not_accepted_cat_sum = float(_tessa_counts.get("Не принято", 0))
                    transferred_sum = float(_tessa_counts.get("Передано подрядчику", 0))
                    _used_tessa_source = True
                else:
                    accepted_sum = issued_sum
                    review_sum = on_ap_sum
                    return_sum = rework_sum
                    not_accepted_cat_sum = 0.0
                    if contractor_col and contractor_col in df.columns:
                        transferred_sum = float(_to_numeric_series(df[contractor_col]).sum())

                _active_sum = (
                    accepted_sum
                    + review_sum
                    + return_sum
                    + not_accepted_cat_sum
                    + transferred_sum
                )
                not_issued_sum = max(total_sections - _active_sum, 0.0)
                _build_pie = total_sections > 0 or _active_sum > 0 or not_issued_sum > 0
                if _build_pie:
                    st.subheader("Исполнение РД")
                    if _used_tessa_source:
                        suppress_caption(
                            "Статусы Принято/На рассм./Возвр./Не принято — из карточек "
                            "TESSA (KrState)."
                        )
                pie_data = {
                    "Принято": int(round(max(accepted_sum, 0.0))),
                    "На рассм.": int(round(max(review_sum, 0.0))),
                    "Возвр.": int(round(max(return_sum, 0.0))),
                    "Не принято": int(round(max(not_accepted_cat_sum, 0.0))),
                    "Передано подрядчику": int(round(max(transferred_sum, 0.0))),
                    "Не выдано": int(round(max(not_issued_sum, 0.0))),
                }
                pie_data = {k: v for k, v in pie_data.items() if v > 0}
                _pie_color_map = {
                    "Принято": "#27AE60",
                    "На рассм.": "#F1C40F",
                    "Возвр.": "#E67E22",
                    "Не принято": "#C0392B",
                    "Передано подрядчику": "#8E44AD",
                    "Не выдано": "#7F8C8D",
                }
                _build_pie = _build_pie and bool(pie_data)

            # RD-10: круговая «Исполнение РД» отражает тот же выбранный статус,
            # что и детальная таблица (единый классификатор _rd_status_filter_*).
            if (
                selected_statuses
                and rd_status_options
                and set(selected_statuses) != set(rd_status_options)
                and pie_data
            ):
                _pie_allow = _rd_status_filter_expand(selected_statuses)
                pie_data = {
                    k: v
                    for k, v in pie_data.items()
                    if _rd_status_label_matches_filter(k, _pie_allow)
                }
                _build_pie = _build_pie and bool(pie_data)

            if _build_pie:
                if True:
                    _nk = len(pie_data)
                    fig_pie = px.pie(
                        values=list(pie_data.values()),
                        names=list(pie_data.keys()),
                        color=list(pie_data.keys()),
                        title=None,
                        color_discrete_map=_pie_color_map,
                    )
                    fig_pie = apply_standard_pie_layout(
                        fig_pie,
                        height=500,
                        pct_fontsize=17 if _nk <= 5 else 15,
                        text_show_value_and_percent=True,
                    )
                    fig_pie.update_traces(
                        hovertemplate="<b>%{label}</b><br>Значение: %{value}<br>Доля: %{percent}<br><extra></extra>",
                    )
                    fig_pie = apply_chart_background(fig_pie)
                    render_chart(fig_pie, caption_below=report_chart_caption_body("Исполнение РД"))
                else:
                    st.info("Нет данных для построения графика 'Исполнение РД'.")
            else:
                st.info("Нет данных для построения графика 'Исполнение РД'.")
        except Exception as e:
            st.error(f"Ошибка при построении графика 'Исполнение РД': {str(e)}")


    else:
        try:
            # R23-06 (стр.18): для поиска родителя берём колонку глубины дерева
            # («Уровень_структуры» → level structure), для проверки outline-уровня «5»
            # (ТЗ п.1: «задачи уровня 5») — колонку outline («Уровень» → level).
            hier_col = (
                "level structure"
                if "level structure" in df.columns
                else ("level" if "level" in df.columns else None)
            )
            outline_col = (
                "level"
                if "level" in df.columns
                else ("level structure" if "level structure" in df.columns else None)
            )
            name_col = (
                "task name"
                if "task name" in df.columns
                else find_column(df, ["Название задачи", "Задача", "Task Name", "Имя задачи"])
            )
            _can_pd_pie = True
            if (
                not hier_col
                or not outline_col
                or not name_col
                or hier_col not in df.columns
                or outline_col not in df.columns
                or name_col not in df.columns
            ):
                _pm_pie = _pd_section_masks(df)
                _, _ok_pie = _pd_cipher_filled_mask(df)
                if not _pm_pie["metrics_mask"].any() and not _ok_pie.fillna(False).any():
                    st.warning("Для ПД нужны колонки уровня иерархии MSP и наименование задачи.")
                    _can_pd_pie = False
            if _can_pd_pie:
                _pd_masks_pie = _pd_section_masks(df)
                cipher_col_pie = _pd_masks_pie["cipher_col"]
                cipher_ok = _pd_cipher_filled_mask(df)[1]
                if not cipher_col_pie or cipher_col_pie not in df.columns:
                    suppress_caption(
                        "Колонка «шифр ПД РД» не найдена — диаграмма исполнения ПД по ТЗ недоступна."
                    )
                pct_col = _pd_msp_pct_complete_col(df)
                if pct_col and pct_col in df.columns:
                    pc = pd.to_numeric(df[pct_col], errors='coerce').fillna(0.0)
                else:
                    pc = pd.Series(0.0, index=df.index)
                m = _pd_masks_pie["metrics_mask"].fillna(False)
                done_v = int((m & (pc >= 99.99)).sum())
                prog_v = int((m & (pc > 0) & (pc < 99.99)).sum())
                wait_v = int((m & (pc <= 0)).sum())
                if done_v + prog_v + wait_v > 0:
                    st.subheader("Исполнение ПД")
                    pie_data = {
                        "Завершено (100%)": int(done_v),
                        "В работе": int(prog_v),
                        "Не начато": int(wait_v),
                    }
                    pie_data = {k: v for k, v in pie_data.items() if v > 0}
                    if pie_data:
                        _nk = len(pie_data)
                        _pie_color_map = {
                            "Завершено (100%)": "#2E86AB",
                            "В работе": "#F39C12",
                            "Не начато": "#E74C3C",
                        }
                        _pie_names = list(pie_data.keys())
                        _pie_vals = list(pie_data.values())
                        _pie_h = 560
                        _leg_col, _chart_col = st.columns([0.26, 0.74], gap="large")
                        _pd_pie_leg_clr = _fin_chart_label_color()
                        with _leg_col:
                            _leg_items = "".join(
                                f"<div style='display:flex;align-items:center;gap:14px;"
                                f"margin:22px 0;padding:4px 0;line-height:1.5;'>"
                                f"<span style='color:{_pie_color_map.get(lbl, '#2E86AB')};"
                                f"font-size:18px;line-height:1.5;flex-shrink:0;'>■</span>"
                                f"<span style='color:{_pd_pie_leg_clr};font-size:14px;"
                                f"line-height:1.5;white-space:normal;'>{lbl}</span></div>"
                                for lbl in _pie_names
                            )
                            st.markdown(
                                f"<div style='min-height:{_pie_h}px;display:flex;flex-direction:column;"
                                f"justify-content:center;gap:18px;padding:12px 8px 12px 4px;'>"
                                f"{_leg_items}</div>",
                                unsafe_allow_html=True,
                            )
                        with _chart_col:
                            _pie_colors = [
                                _pie_color_map.get(lbl, "#2E86AB") for lbl in _pie_names
                            ]
                            fig_pie = px.pie(
                                values=_pie_vals,
                                names=_pie_names,
                                title=None,
                                color_discrete_sequence=_pie_colors,
                            )
                            fig_pie.update_traces(
                                showlegend=False,
                                textinfo="percent",
                                texttemplate="%{percent:.0%}",
                                textposition="inside",
                                insidetextorientation="horizontal",
                                textfont=dict(
                                    size=40 if _nk <= 2 else 32,
                                    color="#ffffff",
                                    family="Inter, system-ui, Arial, sans-serif",
                                ),
                                marker=dict(colors=_pie_colors, line=dict(width=0)),
                                domain=dict(x=[0.02, 0.98], y=[0.02, 0.98]),
                                hovertemplate=(
                                    "<b>%{label}</b><br>Значение: %{value}<br>Доля: %{percent}<br><extra></extra>"
                                ),
                            )
                            fig_pie = apply_chart_background(fig_pie)
                            fig_pie.update_layout(
                                height=_pie_h,
                                width=_pie_h,
                                showlegend=False,
                                margin=dict(l=0, r=0, t=0, b=0),
                            )
                            _pc_l, _pc_c, _pc_r = st.columns([0.08, 0.84, 0.08], gap="small")
                            with _pc_c:
                                render_chart(
                                    fig_pie,
                                    caption_below=report_chart_caption_body("Исполнение ПД"),
                                    omit_default_width=True,
                                )
                else:
                    st.info(
                        "Нет задач ПД для диаграммы (ур.5, заполнен «шифр ПД РД», родитель «Проектная документация»)."
                    )
        except Exception as e:
            st.error(f"Ошибка при построении графика 'Исполнение ПД': {str(e)}")

    _rd_msp_prod_fb: Optional[dict[str, Any]] = None
    _rd_prod_shown = False

    if not is_pd:
        # Prepare data for "Динамика выдачи РД"
        # X-axis: "Старт План" (plan start date)
        # Plan (Y-axis): "РД по Договору" (grouped by "Старт План")
        # Fact (Y-axis): "Выдано в производство работ" (grouped by "Старт План")
        try:
            # Find column for plan data: "РД по Договору"
            rd_plan_col = find_column(
                df, ["РД по Договору", "РД по договору", "рд по договору", "РД по Договору"]
            )

            plan_date_col = (
                plan_end_col if plan_end_col and plan_end_col in df.columns else plan_start_col
            )
            fact_date_col = (
                "actual finish"
                if "actual finish" in df.columns
                else find_column(
                    df,
                    [
                        "actual finish",
                        "фактическое окончание",
                        "окончание факт",
                        "факт окончание",
                    ],
                )
            )
            if not fact_date_col or fact_date_col not in df.columns:
                fact_date_col = base_end_col

            # Подсказка пользователю: график строится из отчётного файла по
            # РД (CSV/XLSX), а не из MSP-графика или TESSA. Нужны колонки:
            # «РД по Договору» (план, шт.), «Выдано в производство работ»
            # (факт, шт.), «plan end»/«Конец План» (дата плана),
            # «actual finish»/«Конец Факт» (дата факта). Если одна из колонок
            # отсутствует — подгрузите отчётный XLS/CSV по РД, и график
            # построится без правок кода.
            _rd_dyn_hint = (
                "Подсказка: график «Динамика выдачи РД» строится из отчётного "
                "файла по РД (CSV/XLSX) с колонками «РД по Договору», "
                "«Выдано в производство работ», «plan end»/«Конец План», "
                "«actual finish»/«Конец Факт». Подгрузите его — график "
                "оживёт без правок кода."
            )
            if not plan_date_col or plan_date_col not in df.columns:
                st.warning(
                    "Для построения графика 'Динамика выдачи РД' необходима колонка плановой даты (plan end / plan start)."
                )
                st.info(_rd_dyn_hint)
                return

            if not rd_plan_col or rd_plan_col not in df.columns:
                st.warning(
                    "Для построения графика 'Динамика выдачи РД' необходима колонка 'РД по Договору'."
                )
                st.info(_rd_dyn_hint)
                return

            _has_prod_source = (
                ("_tessa_production_dt" in df.columns and df["_tessa_production_dt"].notna().any())
                or (in_production_col and in_production_col in df.columns)
                or _rd_has_tessa_production_dates()
            )
            if not _has_prod_source:
                st.warning(
                    "Для построения графика 'Динамика выдачи РД' необходима колонка "
                    "'Выдано в производство работ' или данные tessa_*-task.csv (ГИП/Подписан)."
                )
                st.info(_rd_dyn_hint)
                return

            max_plan_end_date = None
            max_fact_end_date = None

            df["rd_plan_numeric"] = _to_numeric_series(df[rd_plan_col])

            # Если «РД по Договору» везде ноль, а есть отдельная колонка «количество разделов РД» с данными — план берём из неё (ТЗ: план не нулевой без причины)
            rd_sections_for_plan_fallback = find_column(
                df,
                [
                    "Количество разделов РД по Договору",
                    "Количество разделов РД",
                    "разделов РД по договору",
                    "Количетсов разделов РД по Договору",
                ],
            )
            if (
                rd_sections_for_plan_fallback
                and rd_sections_for_plan_fallback in df.columns
                and rd_sections_for_plan_fallback != rd_plan_col
            ):
                if float(df["rd_plan_numeric"].sum()) == 0.0:
                    cnt_num = _to_numeric_series(df[rd_sections_for_plan_fallback])
                    if float(cnt_num.sum()) > 0.0:
                        df["rd_plan_numeric"] = cnt_num

            df["_rd_plan_inc"] = _rd_dynamics_plan_increment_series(
                df, "rd_plan_numeric", plan_date_col
            )

            _prod_mask = _rd_in_production_mask(df, in_production_col)
            df["in_production_numeric"] = np.where(
                _prod_mask,
                df["_rd_plan_inc"].where(df["_rd_plan_inc"] > 0, 1.0),
                0.0,
            )
            df["_doc_plan_date"] = _to_datetime_series(df[plan_date_col])
            df["_doc_fact_date"] = _rd_production_fact_date_series(
                df, in_production_col, fact_date_col
            )
            if df["_doc_plan_date"].notna().any():
                max_plan_end_date = df["_doc_plan_date"].max().date()
            if isinstance(df["_doc_fact_date"], pd.Series) and df["_doc_fact_date"].notna().any():
                max_fact_end_date = df["_doc_fact_date"].max().date()

            # Prepare data
            dynamics_data = []
            _csv_secs_dyn = _rd_plan_csv_sections_df(selected_projects_doc or None)

            # Plan data. Для РД план — по other_*_rd.csv (колонка «Дата выдачи
            # разделов по Договору»): это источник правды, покрывает весь плановый
            # период (даты уходят в будущее) и совпадает с KPI «План на текущую
            # дату». Детальная таблица df даёт неполный период (обрывается раньше),
            # поэтому CSV в приоритете. Для ПД — прежняя логика (MSP-прирост).
            _use_csv_plan = (
                page_title == "Рабочая документация"
                and not _csv_secs_dyn.empty
                and "_plan_dt" in _csv_secs_dyn.columns
                and _csv_secs_dyn["_plan_dt"].notna().any()
            )
            if _use_csv_plan:
                _cp = _csv_secs_dyn[_csv_secs_dyn["_plan_dt"].notna()].copy()
                plan_grouped = (
                    _cp.groupby(_cp["_plan_dt"].dt.normalize())
                    .size()
                    .reset_index(name="Количество")
                )
                plan_grouped.columns = ["Дата", "Количество"]
                plan_grouped["Тип"] = "План"
                dynamics_data.append(plan_grouped)
            elif (
                "_rd_plan_inc" in df.columns
                and "_doc_plan_date" in df.columns
                and df["_doc_plan_date"].notna().any()
            ):
                plan_mask = df["_doc_plan_date"].notna()
                if plan_mask.any():
                    plan_grouped = (
                        df[plan_mask]
                        .groupby(df[plan_mask]["_doc_plan_date"].dt.normalize())
                        .agg({"_rd_plan_inc": "sum"})
                        .reset_index()
                    )
                    plan_grouped.columns = ["Дата", "Количество"]
                    plan_grouped["Тип"] = "План"
                    plan_grouped["Количество"] = plan_grouped["Количество"].fillna(0)
                    dynamics_data.append(plan_grouped)
            elif not _csv_secs_dyn.empty:
                _cp = _csv_secs_dyn[_csv_secs_dyn["_plan_dt"].notna()].copy()
                if not _cp.empty:
                    plan_grouped = (
                        _cp.groupby(_cp["_plan_dt"].dt.normalize())
                        .size()
                        .reset_index(name="Количество")
                    )
                    plan_grouped.columns = ["Дата", "Количество"]
                    plan_grouped["Тип"] = "План"
                    dynamics_data.append(plan_grouped)
            else:
                plan_mask = df["_doc_plan_date"].notna()
                if plan_mask.any():
                    plan_grouped = (
                        df[plan_mask]
                        .groupby(df[plan_mask]["_doc_plan_date"].dt.normalize())
                        .agg({"_rd_plan_inc": "sum"})
                        .reset_index()
                    )
                    plan_grouped.columns = ["Дата", "Количество"]
                    plan_grouped["Тип"] = "План"
                    plan_grouped["Количество"] = plan_grouped["Количество"].fillna(0)
                    dynamics_data.append(plan_grouped)

            # Fact data: количество выданных разделов (шт.) по дате факта
            fact_mask = df["_doc_fact_date"].notna() & (df["in_production_numeric"] > 0)
            if fact_mask.any():
                fact_grouped = (
                    df[fact_mask]
                    .groupby(df[fact_mask]["_doc_fact_date"].dt.normalize())
                    .size()
                    .reset_index(name="Количество")
                )
                fact_grouped.columns = ["Дата", "Количество"]
                fact_grouped["Тип"] = "Факт"
                fact_grouped = fact_grouped[fact_grouped["Количество"] > 0]
                if not fact_grouped.empty:
                    dynamics_data.append(fact_grouped)

            if dynamics_data:
                st.subheader("Динамика выдачи РД")
                dynamics_df = pd.concat(dynamics_data, ignore_index=True)
                all_dates = pd.to_datetime(dynamics_df["Дата"], errors="coerce").dropna()
                if not all_dates.empty:
                    start_anchor = (all_dates.min() - pd.Timedelta(days=1)).normalize()
                    zero_rows = pd.DataFrame(
                        {
                            "Дата": [start_anchor, start_anchor],
                            "Количество": [0.0, 0.0],
                            "Тип": ["План", "Факт"],
                        }
                    )
                    dynamics_df = pd.concat([zero_rows, dynamics_df], ignore_index=True)
                dynamics_df = dynamics_df.sort_values(["Тип", "Дата"])

                dynamics_df["Накопительное_значение"] = 0.0
                for typ in dynamics_df["Тип"].unique():
                    mask = dynamics_df["Тип"] == typ
                    dynamics_df.loc[mask, "Накопительное_значение"] = dynamics_df.loc[
                        mask, "Количество"
                    ].cumsum()

                # Используем накопительные значения для графика
                dynamics_df["Количество"] = dynamics_df["Накопительное_значение"]

                # Показатели: план по проекту, план/факт/отклонение на текущую дату, прогноз производительности
                plan_df = dynamics_df[dynamics_df["Тип"] == "План"].sort_values("Дата")
                fact_df = dynamics_df[dynamics_df["Тип"] == "Факт"].sort_values("Дата")
                today = date.today()

                plan_total_msp = (
                    float(len(_csv_secs_dyn))
                    if not _csv_secs_dyn.empty
                    else float(df["_rd_plan_inc"].sum())
                    if "_rd_plan_inc" in df.columns
                    else 0.0
                )
                if plan_total_msp <= 0.0 and not plan_df.empty:
                    plan_total_msp = float(plan_df["Количество"].max())
                plan_to_date_msp = 0.0
                if not plan_df.empty:
                    dt_plan_msp = pd.to_datetime(plan_df["Дата"])
                    past_plan_msp = plan_df[dt_plan_msp.dt.date <= today]
                    plan_to_date_msp = (
                        float(past_plan_msp["Количество"].iloc[-1])
                        if not past_plan_msp.empty
                        else 0.0
                    )
                fact_to_date_msp = 0.0
                if not fact_df.empty:
                    dt_fact_msp = pd.to_datetime(fact_df["Дата"])
                    past_fact_msp = fact_df[dt_fact_msp.dt.date <= today]
                    fact_to_date_msp = (
                        float(past_fact_msp["Количество"].iloc[-1])
                        if not past_fact_msp.empty
                        else 0.0
                    )

                _rd_summ = None
                try:
                    _rd_summ = _compute_rd_exec_summary_from_csv_tessa(selected_projects_doc)
                except Exception as _e_rd_kpi:
                    suppress_caption(
                        "Сводные KPI (CSV/Tessa): ошибка расчёта — показаны только данные MSP. "
                        + str(_e_rd_kpi)[:220]
                    )

                if _rd_summ:
                    plan_total = float(_rd_summ["plan_total"])
                    _mpp = _rd_summ.get("max_plan_date")
                    _mff = _rd_summ.get("max_fact_date")
                    if _mpp is not None:
                        max_plan_end_date = _mpp
                    if _mff is not None:
                        max_fact_end_date = _mff
                else:
                    plan_total = plan_total_msp

                plan_to_date, fact_to_date, deviation_to_date = _rd_kpi_plan_fact_deviation_today(
                    today=today,
                    msp_df=df,
                    csv_df=_csv_secs_dyn if not _csv_secs_dyn.empty else None,
                    plan_curve=plan_to_date_msp,
                    fact_curve=fact_to_date_msp,
                    rd_summ=_rd_summ,
                )

                # RD-02: «Факт на текущую дату» для РД — «Выдано в производство
                # работ» + «На рассмотрении у ГИП» из tessa_*_rd.csv (как в pie
                # «Исполнение РД»), а НЕ количество строк MSP с датой факта —
                # иначе KPI завышается (428 вместо 374) и расходится с pie.
                # Тот же override уже есть в fallback-ветке (_render_rd_working_doc_...),
                # но основной путь dashboard_documentation его не применял.
                if page_title == "Рабочая документация":
                    try:
                        _tz_fact_kpi = _count_rd_pie_tz(selected_projects_doc or None)
                        _fd_tessa = float(
                            int(_tz_fact_kpi.get(_RD_TESSA_STATUS_PRODUCTION, 0))
                            + int(_tz_fact_kpi.get(_RD_TESSA_STATUS_REVIEW, 0))
                        )
                    except Exception:
                        _fd_tessa = 0.0
                    if _fd_tessa > 0:
                        fact_to_date = _fd_tessa
                        deviation_to_date = float(plan_to_date - fact_to_date)

                first_plan_date = plan_df["Дата"].min() if not plan_df.empty else None
                last_plan_date = plan_df["Дата"].max() if not plan_df.empty else None
                if first_plan_date is not None:
                    first_d = pd.to_datetime(first_plan_date).date()
                else:
                    first_d = today
                if last_plan_date is not None:
                    last_d = pd.to_datetime(last_plan_date).date()
                else:
                    last_d = today
                weeks_elapsed = max((today - first_d).days / 7.0, 1.0 / 7.0)
                current_productivity = fact_to_date / weeks_elapsed if weeks_elapsed > 0 else 0.0
                remaining_days = (last_d - today).days
                remaining_weeks = max(remaining_days / 7.0, 0.0)
                remaining_to_plan = max(plan_total - fact_to_date, 0.0)
                required_productivity = (remaining_to_plan / remaining_weeks) if remaining_weeks > 0 else float("inf")

                _rd_kpi_box = st.container(key="rd_exec_summary_kpi")
                with _rd_kpi_box:
                    c1, c2, c3, c4 = st.columns(4, gap="small")
                    with c1:
                        st.metric("План по проекту", _fmt_rd_whole_metric(plan_total))
                    with c2:
                        st.metric("План на текущую дату", _fmt_rd_whole_metric(plan_to_date))
                    with c3:
                        st.metric("Факт на текущую дату", _fmt_rd_whole_metric(fact_to_date))
                    with c4:
                        _render_rd_deviation_metric(
                            "Отклонение на текущую дату",
                            deviation_to_date,
                        )

                    _rd_msp_prod_fb = {
                        "plan_to_date": plan_to_date,
                        "fact_to_date": fact_to_date,
                        "deviation_to_date": deviation_to_date,
                        "fact_to_date_msp": fact_to_date_msp,
                        "max_plan_end_date": max_plan_end_date,
                        "max_fact_end_date": max_fact_end_date,
                        "last_plan_date": last_d if last_plan_date is not None else None,
                    }

                    if page_title == "Рабочая документация":
                        _render_rd_weekly_productivity_kpis(
                            selected_projects_doc or None,
                            msp_fallback=_rd_msp_prod_fb,
                        )
                        _rd_prod_shown = True

                if page_title != "Рабочая документация":
                    suppress_caption("Прогноз производительности (РД в неделю)")
                    p1, p2 = st.columns(2, gap="small")
                    with p1:
                        st.metric(
                            "Текущая производительность в неделю",
                            f"{round(current_productivity):,.0f}".replace(",", " "),
                        )
                    with p2:
                        if remaining_weeks <= 0:
                            st.metric(
                                "Необходимая для выполнения плана",
                                "—",
                            )
                        elif required_productivity == float("inf"):
                            st.metric(
                                "Необходимая для выполнения плана",
                                "—",
                            )
                        else:
                            st.metric(
                                "Необходимая для выполнения плана",
                                f"{round(required_productivity):,.0f}".replace(",", " "),
                            )

                # ТЗ: синяя кривая «План» должна доходить до общего плана
                # (other_*_rd.csv = «План по проекту»). Разделы без плановой даты
                # не попадают в накопительную кривую, поэтому её максимум меньше
                # общего плана (например, 536 при плане 587). Добавляем остаток к
                # последней плановой точке, чтобы кривая заканчивалась на «Всего
                # по плану».
                try:
                    if plan_total and float(plan_total) > 0:
                        _pm = dynamics_df["Тип"] == "План"
                        if _pm.any():
                            _cur_max = float(dynamics_df.loc[_pm, "Количество"].max())
                            if _cur_max + 0.5 < float(plan_total):
                                _pidx = pd.to_datetime(
                                    dynamics_df.loc[_pm, "Дата"], errors="coerce"
                                ).idxmax()
                                dynamics_df.loc[_pidx, "Количество"] = float(plan_total)
                                plan_df = dynamics_df[dynamics_df["Тип"] == "План"]
                except Exception:
                    pass

                pl_sorted = plan_df.sort_values("Дата")
                fc_sorted = fact_df.sort_values("Дата")

                def _rd_last_cum_on_or_before(sdf: pd.DataFrame, dt) -> float:
                    if sdf is None or getattr(sdf, "empty", True):
                        return 0.0
                    d = pd.to_datetime(dt, errors="coerce", dayfirst=True, format="mixed")
                    if pd.isna(d):
                        return 0.0
                    try:
                        if getattr(d, "tzinfo", None) is not None:
                            d = pd.Timestamp(d).tz_convert(None)
                    except Exception:
                        pass
                    sub_dates = pd.to_datetime(
                        sdf["Дата"], errors="coerce", dayfirst=True, format="mixed"
                    )
                    try:
                        if is_datetime64tz_dtype(sub_dates.dtype):
                            sub_dates = sub_dates.dt.tz_convert(None)
                    except Exception:
                        pass
                    sub = sdf[sub_dates <= d]
                    if sub.empty:
                        return 0.0
                    return float(sub["Количество"].iloc[-1])

                def _rd_line_point_text(row) -> str:
                    v = float(row["Количество"]) if pd.notna(row.get("Количество")) else 0.0
                    if abs(v) < 0.5:
                        return ""
                    t = str(row.get("Тип", ""))
                    d = row["Дата"]
                    dts = pd.to_datetime(d, errors="coerce")
                    den = float(plan_total) if plan_total and plan_total > 0 else 0.0
                    pct = (v / den * 100.0) if den > 0 else 0.0
                    if t == "План":
                        return f"{v:.0f} ({pct:.0f}%)" if den > 0 else f"{v:.0f}"
                    p_at = _rd_last_cum_on_or_before(pl_sorted, dts)
                    f_at = _rd_last_cum_on_or_before(fc_sorted, dts)
                    ovd = max(0.0, p_at - f_at)
                    if den > 0:
                        return f"{v:.0f} ({pct:.0f}%)<br>пр. {int(round(ovd))}"
                    return f"{v:.0f}<br>пр. {int(round(ovd))}"

                dynamics_df["Текст"] = dynamics_df.apply(_rd_line_point_text, axis=1)

                # §4.4: план — синий, факт — оранжевый; нулевой старт (якорь) + rangemode tozero.
                _rd_fact_color = "#F39C12"
                fig_dynamics = px.line(
                    dynamics_df,
                    x="Дата",
                    y="Количество",
                    color="Тип",
                    title=None,
                    markers=True,
                    labels={"Количество": "Количество", "Дата": "Дата"},
                    text="Текст",
                    color_discrete_map={"План": "#2E86AB", "Факт": _rd_fact_color},
                )

                _rd_tickvals, _rd_ticktext = _rd_dynamics_chart_month_ticks_ru(dynamics_df["Дата"])
                fig_dynamics.update_layout(
                    xaxis_title="Дата (Старт План)",
                    yaxis_title="Количество",
                    hovermode="x unified",
                    height=550,
                    xaxis=dict(
                        tickmode="array",
                        tickvals=_rd_tickvals,
                        ticktext=_rd_ticktext,
                        tickangle=-45,
                        tickfont=dict(size=10),
                    ),
                    yaxis=dict(rangemode="tozero"),
                    legend=standard_chart_legend(),
                )
                # Update legend labels to be more descriptive
                fig_dynamics.for_each_trace(
                    lambda t: t.update(
                        name=(
                            "План (РД по Договору)"
                            if str(t.name) == "План"
                            else (
                                "Факт (Выдано в производство работ)"
                                if str(t.name) == "Факт"
                                else t.name
                            )
                        )
                    )
                )
                # Add text labels and format - ensure text is always visible
                fig_dynamics.update_traces(
                    line=dict(width=2),
                    marker=dict(size=6),
                    mode="lines+markers+text",
                    textposition="top center",
                    textfont=dict(size=20, color="white"),
                )
                _apply_rd_dynamics_line_chart_theme(fig_dynamics)
                fig_dynamics = apply_chart_background(fig_dynamics)
                render_chart(fig_dynamics, caption_below=report_chart_caption_body("Динамика выдачи РД"))
            else:
                st.warning("Нет данных для построения графика 'Динамика выдачи РД'.")
                st.info(_rd_dyn_hint)
        except Exception as e:
            st.error(f"Ошибка при построении графика 'Динамика выдачи РД': {str(e)}")

        if page_title == "Рабочая документация" and not _rd_prod_shown:
            try:
                _render_rd_weekly_productivity_kpis(
                    selected_projects_doc or None,
                    msp_fallback=_rd_msp_prod_fb,
                )
            except Exception as _e_rd_prod:
                suppress_caption(
                    f"Производительность разделов в неделю: {_e_rd_prod}"
                )

    else:
        try:
            # См. комментарий выше: hier — для стека родителей, outline — для «уровень 5».
            hier_col = (
                "level structure"
                if "level structure" in df.columns
                else ("level" if "level" in df.columns else None)
            )
            outline_col = (
                "level"
                if "level" in df.columns
                else ("level structure" if "level structure" in df.columns else None)
            )
            name_col = (
                "task name"
                if "task name" in df.columns
                else find_column(df, ["Название задачи", "Задача", "Task Name", "Имя задачи"])
            )
            if (
                not hier_col
                or not outline_col
                or not name_col
                or hier_col not in df.columns
                or outline_col not in df.columns
                or name_col not in df.columns
            ):
                _pd_masks_probe = _pd_section_masks(df)
                _cipher_probe, _cipher_ok_probe = _pd_cipher_filled_mask(df)
                if not _pd_masks_probe["metrics_mask"].any() and not _cipher_ok_probe.fillna(False).any():
                    st.warning("Для графика ПД нужны колонки уровня и наименования задач MSP.")
                elif not hier_col or hier_col not in df.columns:
                    suppress_caption(
                        "Иерархия MSP без «Уровень_структуры» — таблица и график строятся по строкам с шифром ПД/РД."
                    )
            if True:
                _pd_masks_dyn = _pd_section_masks(df)
                pd_metrics_mask = _pd_masks_dyn["metrics_mask"].fillna(False)
                pd_section_mask = _pd_masks_dyn["dynamics_mask"].fillna(False)
                cipher_col = _pd_masks_dyn["cipher_col"]
                cipher_ok = (
                    _pd_cipher_filled_mask(df)[1]
                    if cipher_col
                    else pd.Series(False, index=df.index)
                )
                if not cipher_col or cipher_col not in df.columns:
                    suppress_caption(
                        "Колонка «шифр ПД РД» не найдена — сводные показатели ПД по ТЗ (по шифру раздела) недоступны."
                    )
                b_fin_col = _pd_msp_find_baseline_finish_col(df)
                if b_fin_col is None and plan_end_col and plan_end_col in df.columns:
                    b_fin_col = plan_end_col
                    suppress_caption(
                        "Колонка Baseline Finish не найдена — для плана используется plan end (приближённо)."
                    )
                s_fin_col = _pd_msp_find_schedule_finish_col(df)
                if s_fin_col is None and plan_end_col and plan_end_col in df.columns:
                    s_fin_col = plan_end_col
                b_start_col = _pd_msp_find_baseline_start_col(df)
                s_start_col = _pd_msp_find_schedule_start_col(df)
                if s_start_col is None and plan_start_col and plan_start_col in df.columns:
                    s_start_col = plan_start_col
                _plan_end_ref = (
                    plan_end_col if plan_end_col and plan_end_col in df.columns else None
                )
                m_dyn_pre = pd_section_mask.fillna(False)
                _b_base_raw = _pd_msp_find_baseline_finish_col(df)
                b_fin_col = (
                    _pd_pick_finish_col(
                        df,
                        m_dyn_pre,
                        baseline_col=b_fin_col,
                        schedule_col=_plan_end_ref,
                    )
                    or b_fin_col
                )
                s_fin_col = (
                    _pd_pick_finish_col(
                        df,
                        m_dyn_pre,
                        baseline_col=s_fin_col,
                        schedule_col=_plan_end_ref,
                    )
                    or s_fin_col
                )
                if (
                    b_fin_col
                    and _b_base_raw
                    and b_fin_col != _b_base_raw
                ):
                    suppress_caption(
                        "Колонка «Базовое окончание» без дат по разделам ПД — "
                        "для графика и KPI используется plan end."
                    )
                pct_col = _pd_msp_pct_complete_col(df)
                if pct_col and pct_col in df.columns:
                    pc = pd.to_numeric(df[pct_col], errors='coerce').fillna(0.0)
                else:
                    pc = pd.Series(0.0, index=df.index)
                act_fn = _pd_msp_actual_finish_col(df)
                bf = pd.to_datetime(df[b_fin_col], errors='coerce', dayfirst=True, format='mixed') if b_fin_col else pd.NaT
                sf = pd.to_datetime(df[s_fin_col], errors='coerce', dayfirst=True, format='mixed') if s_fin_col else pd.NaT
                bs = (
                    pd.to_datetime(df[b_start_col], errors="coerce", dayfirst=True, format="mixed")
                    if b_start_col and b_start_col in df.columns
                    else pd.Series(pd.NaT, index=df.index)
                )
                ss = (
                    pd.to_datetime(df[s_start_col], errors="coerce", dayfirst=True, format="mixed")
                    if s_start_col and s_start_col in df.columns
                    else pd.Series(pd.NaT, index=df.index)
                )
                af = (
                    pd.to_datetime(df[act_fn], errors='coerce', dayfirst=True, format='mixed')
                    if act_fn and act_fn in df.columns
                    else pd.Series(pd.NaT, index=df.index)
                )
                if b_fin_col is None or b_fin_col not in df.columns:
                    st.warning("Нет даты базового окончания (Baseline Finish / plan end) для графика ПД.")
                elif s_fin_col is None or s_fin_col not in df.columns:
                    st.warning("Нет даты окончания по текущему графику (Finish / plan end) для прогноза ПД.")
                else:
                    granularity_label = st.selectbox(
                        "Гранулярность расчётов",
                        ["За день", "За неделю", "За месяц"],
                        index=1,
                        key=_doc_fk + "pd_granularity",
                    )
                    _gran_cfg = {
                        "За день": ("day", 1, 1),
                        "За неделю": ("week", 7, 7),
                        "За месяц": ("month", 30, 30),
                    }
                    gran_key, mult_nec, win_days = _gran_cfg[granularity_label]

                    pd_chart_mask = _pd_dynamics_line_tasks_mask(df, _pd_masks_dyn)
                    if not pd_chart_mask.any():
                        pd_chart_mask = _pd_table_row_mask(
                            df, pd_metrics_mask, pd_section_mask
                        ).fillna(False)
                    # b_fin_col/s_fin_col уже выбраны через _pd_pick_finish_col (plan end,
                    # если base end пуст на разделах ПД — напр. Есипово V).
                    _chart_b_fin_col = (
                        _pd_pick_finish_col(
                            df,
                            pd_chart_mask,
                            baseline_col=b_fin_col or _b_base_raw,
                            schedule_col=_plan_end_ref,
                        )
                        or b_fin_col
                        or _b_base_raw
                        or _pd_msp_find_baseline_finish_col(df)
                    )
                    _chart_b_start_col = _pd_msp_find_baseline_start_col(df)
                    _chart_s_fin_col = (
                        _pd_pick_finish_col(
                            df,
                            pd_chart_mask,
                            baseline_col=s_fin_col,
                            schedule_col=_plan_end_ref,
                        )
                        or s_fin_col
                        or _pd_msp_find_schedule_finish_col(df)
                    )
                    _chart_s_start_col = _pd_msp_find_schedule_start_col(df)
                    plan_line_mask = _pd_mask_with_start_finish(
                        df, pd_chart_mask, _chart_b_start_col, _chart_b_fin_col
                    )
                    fcst_line_mask = _pd_mask_with_start_finish(
                        df, pd_chart_mask, _chart_s_start_col, _chart_s_fin_col
                    )
                    if not plan_line_mask.any():
                        plan_line_mask = _pd_mask_with_finish(
                            df, pd_chart_mask, _chart_b_fin_col
                        )
                    if not fcst_line_mask.any():
                        fcst_line_mask = _pd_mask_with_finish(
                            df, pd_chart_mask, _chart_s_fin_col
                        )

                    _chart_bf = (
                        pd.to_datetime(
                            df[_chart_b_fin_col], errors="coerce", dayfirst=True, format="mixed"
                        )
                        if _chart_b_fin_col and _chart_b_fin_col in df.columns
                        else pd.Series(pd.NaT, index=df.index)
                    )
                    _chart_bf_bp = _pd_baseline_finish_series(df, _b_base_raw)
                    if _chart_b_fin_col and _chart_b_fin_col in df.columns:
                        _pick_bp = pd.to_datetime(
                            df[_chart_b_fin_col],
                            errors="coerce",
                            dayfirst=True,
                            format="mixed",
                        )
                        _chart_bf_bp = _chart_bf_bp.where(_chart_bf_bp.notna(), _pick_bp)
                    _chart_sf = (
                        pd.to_datetime(
                            df[_chart_s_fin_col], errors="coerce", dayfirst=True, format="mixed"
                        )
                        if _chart_s_fin_col and _chart_s_fin_col in df.columns
                        else pd.Series(pd.NaT, index=df.index)
                    )

                    _plan_dates_chart = _chart_bf_bp.where(_chart_bf_bp.notna(), _chart_bf)
                    today = pd_report_date if is_pd else date.today()
                    ts_today = pd.Timestamp(today)
                    # Общее число разделов ПД — ур.5 под этапом + шифр (без требования даты).
                    m_sec = pd_chart_mask.fillna(False)
                    m_kpi = plan_line_mask.fillna(False)
                    m_kpi_bp = m_kpi & _plan_dates_chart.notna()
                    plan_total = float(m_sec.sum()) if m_sec.any() else float(m_kpi_bp.sum())
                    plan_to_date = int(
                        (
                            m_kpi_bp
                            & (_plan_dates_chart.dt.normalize() <= ts_today)
                        ).sum()
                    )
                    done_sec = m_sec & (
                        (pc >= 99.99)
                        | (af.notna() & (af.dt.normalize() <= ts_today))
                    )
                    # Факт на дату: среди разделов ТЗ; кривые — по строкам с датами.
                    fact_to_date = int(done_sec.sum())
                    deviation_to_date = float(fact_to_date - plan_to_date)
                    done_sec_dated = m_kpi_bp & (
                        (pc >= 99.99)
                        | (af.notna() & (af.dt.normalize() <= ts_today))
                    )

                    plan_curve = _pd_cumsum_by_granularity(
                        _plan_dates_chart, m_kpi_bp, gran_key
                    )
                    plan_curve["Тип"] = "План по проекту (БП)"
                    fcst_curve = _pd_cumsum_by_granularity(
                        _chart_sf, fcst_line_mask, gran_key
                    )
                    fcst_curve["Тип"] = "Прогноз по проекту"
                    # Факт: те же разделы, что в KPI «Факт на текущую дату» (не путать с прогнозом).
                    _fact_dates = af.copy()
                    _fact_proxy = done_sec_dated & _fact_dates.isna()
                    if _fact_proxy.any():
                        _fact_dates = _fact_dates.where(~_fact_proxy, _chart_sf)
                    fact_curve = _pd_cumsum_by_granularity(
                        _fact_dates, done_sec_dated & _fact_dates.notna(), gran_key
                    )
                    fact_curve["Тип"] = "Факт"
                    curves = [plan_curve, fcst_curve, fact_curve]
                    dynamics_df = pd.concat(
                        [c for c in curves if c is not None and not c.empty],
                        ignore_index=True,
                    )
                    all_dates = pd.to_datetime(dynamics_df["Дата"], errors="coerce").dropna()
                    if not all_dates.empty:
                        start_anchor = (all_dates.min() - pd.Timedelta(days=1)).normalize()
                        zplan = pd.DataFrame(
                            {
                                "Дата": [start_anchor],
                                "Количество": [0.0],
                                "Тип": ["План по проекту (БП)"],
                            }
                        )
                        zfcst = pd.DataFrame(
                            {
                                "Дата": [start_anchor],
                                "Количество": [0.0],
                                "Тип": ["Прогноз по проекту"],
                            }
                        )
                        zfact = pd.DataFrame(
                            {
                                "Дата": [start_anchor],
                                "Количество": [0.0],
                                "Тип": ["Факт"],
                            }
                        )
                        dynamics_df = pd.concat(
                            [zplan, zfcst, zfact, dynamics_df], ignore_index=True
                        )
                    dynamics_df = dynamics_df.sort_values(["Тип", "Дата"])
                    c1, c2, c3, c4 = st.columns(4, gap="small")
                    with c1:
                        st.metric("План по проекту (БП)", f"{plan_total:,.0f}".replace(",", " "))
                    with c2:
                        st.metric("План на текущую дату (БП)", f"{plan_to_date:,.0f}".replace(",", " "))
                    with c3:
                        st.metric("Факт на текущую дату", f"{fact_to_date:,.0f}".replace(",", " "))
                    with c4:
                        _render_pd_deviation_metric(
                            "Отклонение на текущую дату",
                            plan_to_date,
                            fact_to_date,
                        )
                    # П.7: |отклонение| / (дней до срока) × ×1/×7/×30;
                    # срок — max БО, иначе max Finish, иначе один период гранулярности.
                    nec = _pd_necessary_productivity(
                        float(plan_to_date - fact_to_date),
                        _plan_dates_chart.loc[m_kpi_bp],
                        today,
                        mult_nec,
                        schedule_finish=_chart_sf.loc[fcst_line_mask.fillna(False)],
                    )
                    period_start = today - timedelta(days=int(win_days) - 1)
                    ts_ps = pd.Timestamp(period_start)
                    prod_n = int(
                        (
                            done_sec
                            & af.notna()
                            & (af.dt.normalize() >= ts_ps)
                            & (af.dt.normalize() <= ts_today)
                        ).sum()
                    )
                    suppress_caption(
                        "Гранулярность: шаг накопления на графике, окно текущей производительности "
                        "и множитель ×1 / ×7 / ×30 к необходимой производительности (к отклонению за календарный день)."
                    )
                    _prod_title = {
                        "За день": "Текущая производительность за день",
                        "За неделю": "Текущая производительность за неделю",
                        "За месяц": "Текущая производительность за месяц",
                    }[granularity_label]
                    _nec_title = {
                        "За день": "Необходимая производительность (за день)",
                        "За неделю": "Необходимая производительность (за неделю)",
                        "За месяц": "Необходимая производительность (за месяц)",
                    }[granularity_label]
                    pw1, pw2 = st.columns(2, gap="small")
                    with pw1:
                        st.metric(_prod_title, f"{prod_n:,.0f}".replace(",", " "))
                    with pw2:
                        # П.7: при большом остатке дней значение бывает <1 — не округляем
                        # до 0 (иначе реальный бэклог скрывается), показываем с десятыми.
                        if nec is None:
                            _nec_disp = "—"
                        elif abs(float(nec)) < 1e-9:
                            _nec_disp = "0"
                        elif abs(nec) < 10:
                            _nec_disp = f"{nec:.1f}".replace(".", ",")
                        else:
                            _nec_disp = f"{round(nec):,.0f}".replace(",", " ")
                        st.metric(_nec_title, _nec_disp)
                    dynamics_df["Текст"] = dynamics_df["Количество"].apply(
                        lambda x: f"{x:.0f}" if pd.notna(x) and float(x) != 0.0 else ""
                    )
                    if plan_curve.empty and fcst_curve.empty and fact_curve.empty:
                        st.warning(
                            "Нет данных с датами для графика «Динамика выдачи ПД» "
                            "(проверьте базовое/плановое окончание в MSP)."
                        )
                    else:
                        _PD_FACT_LINE_COLOR = "#27AE60"
                        fig_dynamics = px.line(
                            dynamics_df,
                            x="Дата",
                            y="Количество",
                            color="Тип",
                            title=None,
                            markers=True,
                            labels={"Количество": "Количество разделов ПД", "Дата": "Дата"},
                            text="Текст",
                            color_discrete_map={
                                "План по проекту (БП)": _PD_PLAN_LINE_COLOR,
                                "Прогноз по проекту": _PD_FCST_LINE_COLOR,
                                "Факт": _PD_FACT_LINE_COLOR,
                            },
                            category_orders={
                                "Тип": [
                                    "План по проекту (БП)",
                                    "Прогноз по проекту",
                                    "Факт",
                                ]
                            },
                        )
                        # Подписи оси X — месяцы (как у РД), иначе тики «день» пропадали
                        # после apply_chart_background / сжатия легенды.
                        _pd_tickvals, _pd_ticktext = _rd_dynamics_chart_month_ticks_ru(
                            dynamics_df["Дата"]
                        )
                        _pd_y = pd.to_numeric(dynamics_df["Количество"], errors="coerce").dropna()
                        _pd_y_max = float(_pd_y.max()) if not _pd_y.empty else 1.0
                        _pd_y_min = float(_pd_y.min()) if not _pd_y.empty else 0.0
                        _pd_span = max(_pd_y_max - _pd_y_min, 1.0)
                        _pd_foot = max(_pd_span * 0.12, _pd_y_max * 0.08, 4.0)
                        _pd_head = max(_pd_span * 0.12, _pd_y_max * 0.08, 2.0)
                        _pd_y_lo = (
                            _pd_y_min - _pd_foot
                            if _pd_y_min >= 0
                            else _pd_y_min - max(_pd_foot, abs(_pd_y_min) * 0.15)
                        )
                        _pd_ax = _fin_chart_axis_color()
                        _pd_leg = _line_chart_legend_above(n_items=3, long_labels=True)
                        fig_dynamics.update_layout(
                            margin=dict(l=56, r=36, t=88, b=120),
                            yaxis_title="Количество разделов ПД",
                            hovermode="x unified",
                            height=600,
                            showlegend=True,
                            xaxis=dict(
                                title=dict(
                                    text="Период",
                                    standoff=22,
                                    font=dict(color=_pd_ax),
                                ),
                                tickmode="array",
                                tickvals=_pd_tickvals,
                                ticktext=_pd_ticktext,
                                tickangle=-35,
                                tickfont=dict(size=12, color=_pd_ax),
                                automargin=True,
                            ),
                            yaxis=dict(
                                range=[_pd_y_lo, _pd_y_max + _pd_head],
                                autorange=False,
                                tickfont=dict(size=10, color=_pd_ax),
                                title_font=dict(color=_pd_ax),
                            ),
                            legend=_pd_leg,
                        )
                        fig_dynamics.update_traces(
                            mode="lines+markers+text",
                            textposition="top center",
                        )
                        for _tr in fig_dynamics.data:
                            _tn = str(_tr.name or "")
                            if "План" in _tn:
                                _tr.line.color = _PD_PLAN_LINE_COLOR
                                _tr.line.width = 2.5
                                _tr.marker.color = _PD_PLAN_LINE_COLOR
                                _tr.marker.size = 8
                                _tr.textfont = dict(color=_PD_PLAN_LINE_COLOR, size=10)
                            elif "Прогноз" in _tn:
                                _tr.line.color = _PD_FCST_LINE_COLOR
                                _tr.line.width = 3
                                _tr.line.dash = "solid"
                                _tr.marker.color = _PD_FCST_LINE_COLOR
                                _tr.marker.size = 9
                                _tr.textfont = dict(color=_PD_FCST_LINE_COLOR, size=10)
                            elif "Факт" in _tn:
                                _tr.line.color = _PD_FACT_LINE_COLOR
                                _tr.line.width = 2.5
                                _tr.marker.color = _PD_FACT_LINE_COLOR
                                _tr.marker.size = 8
                                _tr.textfont = dict(color=_PD_FACT_LINE_COLOR, size=10)
                        fig_dynamics = apply_chart_background(fig_dynamics)
                        # apply_chart_background сбрасывает tickmode/легенду — возвращаем.
                        _pd_ax = _fin_chart_axis_color()
                        _pd_leg = _line_chart_legend_above(n_items=3, long_labels=True)
                        _pd_leg["font"] = dict(
                            size=13, color=_fin_chart_legend_text_color()
                        )
                        fig_dynamics.update_layout(
                            margin=dict(l=56, r=36, t=92, b=130),
                            xaxis=dict(
                                title=dict(
                                    text="Период",
                                    standoff=22,
                                    font=dict(color=_pd_ax),
                                ),
                                tickmode="array",
                                tickvals=_pd_tickvals,
                                ticktext=_pd_ticktext,
                                tickangle=-35,
                                tickfont=dict(size=12, color=_pd_ax),
                                automargin=True,
                            ),
                            yaxis=dict(
                                range=[_pd_y_lo, _pd_y_max + _pd_head],
                                autorange=False,
                                tickfont=dict(size=10, color=_pd_ax),
                                title_font=dict(color=_pd_ax),
                            ),
                            legend=_pd_leg,
                            showlegend=True,
                            hovermode="x unified",
                        )
                        render_chart(fig_dynamics, caption_below=report_chart_caption_body("Динамика выдачи ПД"))

                    render_table_subheader(st, "Выдача проектной документации по проектам")
                    _tbl_mask = (plan_line_mask | fcst_line_mask).fillna(False)
                    idx_sec = df.index[_tbl_mask]
                    if len(idx_sec) == 0:
                        st.info(
                            "Нет строк для таблицы (те же задачи, что на графике «Динамика выдачи ПД»)."
                        )
                    else:
                        _tn_tbl = df[name_col].astype(str) if name_col in df.columns else pd.Series("", index=df.index)
                        # Ярлык «Раздел» = шифр. Строки без шифра (процессные задачи
                        # «Согласование…», «Экспертиза…», «Разрешение…», «Корректировка
                        # АГО» и т.п.) — не разделы ПД: убираем, иначе они дают пустой
                        # «Раздел» и схлопываются дедупом (Проект, Раздел) в одну
                        # пустую строку на проект. Arrow-NA str не ловится .isin —
                        # поэтому определяем пустоту через .isna() + строковый набор.
                        _blank_lbl = {"", "nan", "none", "<na>", "nat", "null", "-", "—"}
                        if cipher_col and cipher_col in df.columns:
                            _raw_cipher = df.loc[idx_sec, cipher_col]
                            sec_disp = _raw_cipher.astype(str).str.strip()
                            _sec_blank = (
                                _raw_cipher.isna().to_numpy()
                                | sec_disp.str.strip().str.lower().isin(_blank_lbl).to_numpy()
                            )
                        else:
                            sec_disp = _tn_tbl.loc[idx_sec].astype(str).str.strip()
                            _sec_blank = (
                                sec_disp.str.strip().str.lower().isin(_blank_lbl).to_numpy()
                            )
                        _sec_keep = ~_sec_blank
                        idx_sec = idx_sec[_sec_keep]
                        sec_disp = sec_disp[_sec_keep]
                        tbl_raw = pd.DataFrame({"Раздел": sec_disp.values}, index=idx_sec)
                        _proj_src = (
                            project_col
                            if project_col and project_col in df.columns
                            else (
                                "project name"
                                if "project name" in df.columns
                                else find_column(df, ["Проект", "project"])
                            )
                        )
                        if _proj_src and _proj_src in df.columns:
                            tbl_raw["Проект"] = (
                                df.loc[idx_sec, _proj_src].astype(str).str.strip().values
                            )
                        else:
                            tbl_raw["Проект"] = ""
                        tbl_raw["_bf"] = _chart_bf_bp.reindex(idx_sec).dt.normalize()
                        tbl_raw["_sf"] = _chart_sf.reindex(idx_sec).dt.normalize()
                        tbl_raw["_dev"] = (tbl_raw["_bf"] - tbl_raw["_sf"]).dt.days
                        if "snapshot_date" in df.columns:
                            tbl_raw["_snap"] = pd.to_datetime(
                                df.loc[idx_sec, "snapshot_date"], errors="coerce"
                            ).values
                        else:
                            tbl_raw["_snap"] = pd.NaT
                        _tbl_keys = [c for c in ("Проект", "Раздел") if c in tbl_raw.columns]
                        if _tbl_keys:
                            tbl_raw["_ord_snap"] = pd.to_datetime(
                                tbl_raw["_snap"], errors="coerce"
                            ).fillna(pd.Timestamp(0))
                            tbl_raw["_ord_dt"] = tbl_raw[["_bf", "_sf"]].max(axis=1)
                            tbl_raw = (
                                tbl_raw.sort_values(
                                    ["_ord_snap", "_ord_dt"] + _tbl_keys,
                                    ascending=True,
                                    kind="mergesort",
                                )
                                .drop_duplicates(subset=_tbl_keys, keep="last")
                                .drop(columns=["_snap", "_ord_snap", "_ord_dt"], errors="ignore")
                            )
                        _sort_cols = ["Проект", "_dev", "Раздел"]
                        tbl_f = tbl_raw.sort_values(
                            _sort_cols,
                            ascending=[True, False, True],
                            kind="mergesort",
                        )
                        _dev_round = pd.to_numeric(tbl_f["_dev"], errors="coerce").round()
                        tbl_show = pd.DataFrame(
                            {
                                "№": range(1, len(tbl_f) + 1),
                                "Проект": tbl_f["Проект"].map(sanitize_display_label),
                                "Раздел": tbl_f["Раздел"].map(sanitize_display_label),
                                "Базовое окончание": tbl_f["_bf"].dt.strftime("%d.%m.%Y"),
                                "Окончание": tbl_f["_sf"].dt.strftime("%d.%m.%Y"),
                                "Отклонение окончания": _dev_round.map(_pd_fmt_deviation_days),
                            }
                        )
                        tbl_numeric = tbl_show.copy()
                        tbl_numeric["Базовое окончание"] = tbl_f["_bf"].values
                        tbl_numeric["Окончание"] = tbl_f["_sf"].values
                        tbl_numeric["Отклонение окончания"] = _dev_round.values
                        st.markdown(
                            _pd_dynamics_table_shell_css_for_theme(n_rows=len(tbl_show)),
                            unsafe_allow_html=True,
                        )
                        _export_tbl = tbl_show.copy()
                        _render_plan_fact_dates_main_table(
                            tbl_show,
                            tbl_numeric,
                            wrap_class="pd-dynamics-scroll-wrap pd-dynamics-table-wrap",
                            file_stem="pd_dynamics_table",
                            key_prefix="pd_dyn_tbl",
                            export_df=_export_tbl,
                        )
                        suppress_caption(
                            "Строки совпадают с задачами графика «Динамика выдачи ПД»; "
                            "сортировка по клику на заголовок; отклонение окончания (дни) — "
                            "красный при просрочке, зелёный при опережении."
                        )
        except Exception as e:
            st.error(f"Ошибка при построении графика 'Динамика ПД': {str(e)}")

    if not is_pd:
        try:
            _render_rd_working_doc_monthly_and_detail(
                work_df=df,
                selected_projects=selected_projects_doc or None,
                selected_sections=selected_sections_doc or None,
                selected_statuses=selected_statuses or None,
                status_options=rd_status_options or None,
                metric_mode=rd_metric_mode,
                show_forecast_date=show_forecast_date_col,
                doc_fk=_doc_fk,
                plan_end_col=plan_end_col,
                rd_count_col=rd_count_col,
                in_production_col=in_production_col,
            )
        except Exception as _e_rd_tbl:
            suppress_caption(f"Детальная таблица РД: {_e_rd_tbl}")

    if embed_delay_at_end:
        st.divider()
        if page_title == "Проектная документация":
            dashboard_pd_delay(df)
        else:
            dashboard_rd_delay(df)


def dashboard_working_documentation(df):
    """Рабочая документация: основной экран + вкладка «Просрочка выдачи РД» (без отдельного пункта меню)."""
    tab_main, tab_delay = st.tabs(
        ["Рабочая документация", "Просрочка выдачи РД"],
        key="rd_work_doc_page_tabs",
        on_change="rerun",
    )
    with tab_main:
        if tab_main.open:
            dashboard_documentation(
                df, page_title="Рабочая документация", embed_delay_at_end=False
            )
    with tab_delay:
        if tab_delay.open:
            dashboard_rd_delay(df)


def dashboard_project_documentation(df):
    """Проектная документация: основной экран + вкладка «Просрочка выдачи ПД»."""
    tab_main, tab_delay = st.tabs(
        ["Проектная документация", "Просрочка выдачи ПД"],
        key="pd_doc_page_tabs",
        on_change="rerun",
    )
    with tab_main:
        if tab_main.open:
            dashboard_documentation(
                df, page_title="Проектная документация", embed_delay_at_end=False
            )
    with tab_delay:
        if tab_delay.open:
            dashboard_pd_delay(df)


# ==================== DASHBOARD 8/9: «Утверждённый бюджет план/факт» (ТЗ заказчика 2026-05-07) ====================
# Старая логика (gauge «Исполнение бюджета», KPI-метрики и большая гистограмма с типами «План/Факт/Корректировка/Отклонение»)
# исключена — заказчик прямо указал «такой визуал нас не устраивает и не был ранее в правках».
# Источник данных приоритетно — `try_approved_budget_from_1c_dannye` (БДДС/ПЛАН без «(БДР)» vs БДДС/ФАКТ).
# Если 1С-выгрузки нет — fallback на MSP-колонки `budget plan / budget fact`.
def _find_contract_column_for_budget(d: pd.DataFrame):
    """Колонка контрактации / покрытия контрактами в данных бюджета."""
    for cand in (
        "Контрактация",
        "контрактация",
        "Контракт",
        "contract",
        "Contract",
        "Покрытие контрактами",
    ):
        if cand in d.columns:
            return cand
    for col in d.columns:
        c = str(col).lower().strip()
        if "контрактация" in c:
            return col
        if "контракт" in c and "план" not in c:
            return col
        if "покрытие" in c and "контракт" in c:
            return col
    return None


def _plan_fact_pct_label(numerator: float, denominator: float) -> str:
    """% = 100 × числитель / знаменатель (план > 0)."""
    if denominator and float(denominator) > 0:
        return f"{100.0 * float(numerator) / float(denominator):.1f}%"
    return "—"


def _plan_fact_contract_pct_label(
    contract_rub: float, plan_rub: float, *, has_contract_source: bool
) -> str:
    """% покрытия контрактами = 100 × контрактация / план; без колонки — «—», не 0%."""
    if not has_contract_source:
        return "—"
    return _plan_fact_pct_label(contract_rub, plan_rub)


def _contract_rub_by_project(msp_df: pd.DataFrame | None) -> pd.Series | None:
    if msp_df is None or msp_df.empty or "project name" not in msp_df.columns:
        return None
    col = _find_contract_column_for_budget(msp_df)
    if not col:
        return None
    tmp = msp_df.copy()
    tmp["_c"] = pd.to_numeric(tmp[col], errors="coerce").fillna(0.0)
    return tmp.groupby("project name", dropna=False)["_c"].sum()


def _render_plan_fact_detail_table(
    st,
    filtered_df: pd.DataFrame,
    *,
    msp_df: pd.DataFrame | None = None,
    key_suffix: str = "",
) -> None:
    """Таблица по проектам: план, факт, остаток, отклонение, % выполнения, % покрытия контрактами."""
    src = filtered_df.copy()
    if src.empty:
        st.info("Нет данных для таблицы.")
        return
    src["budget plan"] = pd.to_numeric(src["budget plan"], errors="coerce").fillna(0.0)
    src["budget fact"] = pd.to_numeric(src["budget fact"], errors="coerce").fillna(0.0)
    contract_col = _find_contract_column_for_budget(src)
    _has_contract_src = contract_col is not None
    if contract_col:
        src["_contract_rub"] = pd.to_numeric(src[contract_col], errors="coerce").fillna(0.0)
    else:
        src["_contract_rub"] = 0.0
    _msp_contract_by_proj = _contract_rub_by_project(msp_df)
    if _msp_contract_by_proj is not None:
        _has_contract_src = True

    if "project name" in src.columns:
        table_agg = (
            src.groupby("project name", dropna=False)
            .agg(
                plan=("budget plan", "sum"),
                fact=("budget fact", "sum"),
                contract=("_contract_rub", "sum"),
            )
            .reset_index()
        )
    else:
        table_agg = pd.DataFrame(
            [
                {
                    "project name": "Итого",
                    "plan": float(src["budget plan"].sum()),
                    "fact": float(src["budget fact"].sum()),
                    "contract": float(src["_contract_rub"].sum()),
                }
            ]
        )

    rows = []
    for _, r in table_agg.iterrows():
        plan = float(r["plan"])
        fact = float(r["fact"])
        contract = float(r["contract"])
        rows.append(
            {
                "Проект": str(r["project name"]),
                "План, млн руб.": f"{plan / 1e6:.2f}",
                "Факт, млн руб.": f"{fact / 1e6:.2f}",
                "Остаток, млн руб.": f"{(plan - fact) / 1e6:.2f}",
                "Отклонение, млн руб.": _finance_fmt_signed_million_deviation(fact - plan),
                "% выполнения": _plan_fact_pct_label(fact, plan),
                "% покрытия контрактами": _plan_fact_contract_pct_label(
                    contract if _msp_contract_by_proj is None else float(
                        _msp_contract_by_proj.get(r["project name"], contract)
                    ),
                    plan,
                    has_contract_source=_has_contract_src,
                ),
            }
        )
    display = pd.DataFrame(rows)
    if "project name" in src.columns and len(table_agg) > 1:
        plan_total = float(table_agg["plan"].sum())
        fact_total = float(table_agg["fact"].sum())
        contract_total = float(table_agg["contract"].sum())
        display = pd.concat(
            [
                display,
                pd.DataFrame(
                    [
                        {
                            "Проект": "ИТОГО",
                            "План, млн руб.": f"{plan_total / 1e6:.2f}",
                            "Факт, млн руб.": f"{fact_total / 1e6:.2f}",
                            "Остаток, млн руб.": f"{(plan_total - fact_total) / 1e6:.2f}",
                            "Отклонение, млн руб.": _finance_fmt_signed_million_deviation(
                                fact_total - plan_total
                            ),
                            "% выполнения": _plan_fact_pct_label(fact_total, plan_total),
                            "% покрытия контрактами": _plan_fact_pct_label(
                                contract_total, plan_total
                            ),
                        }
                    ]
                ),
            ],
            ignore_index=True,
        )

    render_table_subheader(
        st,
        "утверждённого бюджет план/факт по проектам",
    )
    _render_budget_table_html(
        display,
        finance_deviation_column="Отклонение, млн руб.",
        deviation_color_fact_vs_plan=True,
        expense_overrun_style=False,
        file_stem="approved_budget_plan_fact_detail",
        key_prefix=f"appr_budget_detail_{key_suffix}",
        **_appr_budget_table_html_kwargs(),
    )


def _plan_fact_summary_gauge_color(plan_rub: float, fact_rub: float) -> str:
    """Цвет дуги gauge: зелёный — запас до плана, оранжевый — в пределах 20% до плана, красный — перерасход."""
    if plan_rub <= 0:
        return "#8892a0"
    if fact_rub > plan_rub:
        return "#e74c3c"
    if fact_rub >= 0.8 * plan_rub:
        return "#e67e22"
    return "#27ae60"


