def _render_appr_pf_gauge_chart(fig: go.Figure, *, height: int, chart_key: str) -> None:
    h = max(200, int(height))
    cfg = dict(_PLOTLY_CONFIG)
    cfg["displayModeBar"] = False
    cfg["scrollZoom"] = False
    _apply_finance_light_preview_chart_colors(fig)
    try:
        plot_div = fig.to_html(
            full_html=False,
            include_plotlyjs="cdn",
            config=cfg,
            default_width="100%",
            default_height=f"{h}px",
        )
        _gauge_light_css = _fin_appr_gauge_iframe_light_css()
        shell = (
            "<!DOCTYPE html><html lang='ru'><head><meta charset='utf-8'>"
            "<style>"
            "html,body{margin:0;padding:0;overflow:hidden!important;background:transparent;}"
            f".appr-pf-gauge-wrap{{width:100%;height:{h}px;max-height:{h}px;overflow:hidden!important;}}"
            f"{_gauge_light_css}"
            "</style></head><body>"
            f'<div class="appr-pf-gauge-wrap">{plot_div}</div>'
            "</body></html>"
        )
        components.html(shell, height=h + 2, scrolling=False)
    except Exception:
        render_chart(
            fig,
            height=h,
            key=chart_key,
            skip_clamp_zoom=True,
            omit_default_width=True,
            max_height=h + 8,
        )


def _render_appr_pf_summary_kpi(
    *,
    plan_v: float,
    fact_v: float,
    plan_mln: float,
    fact_mln: float,
    pct_of_plan: float,
    plan_rub: float,
    fact_rub: float,
    vf: str,
    unit: str,
    height: int,
    plan_red: str,
    fact_green: str,
    value_color: str,
    muted_color: str,
) -> None:
    """KPI план/факт в iframe — Streamlit перебивает font-size в st.markdown."""
    from html import escape as html_esc

    h = max(200, int(height))
    pct_html = ""
    if plan_rub > 0 and np.isfinite(pct_of_plan):
        pct_color = fact_green if fact_rub >= plan_rub else plan_red
        pct_html = (
            f'<p class="appr-pf-kpi-pct" style="color:{html_esc(pct_color)};">'
            f"{pct_of_plan:.1f}% от плана</p>"
        )
    dev_rub = float(fact_rub or 0.0) - float(plan_rub or 0.0)
    dev_v = dev_rub / (1e9 if unit == "млрд" else 1e6)
    dev_mln = dev_rub / 1e6
    dev_pct = (100.0 * dev_rub / plan_rub) if plan_rub > 0 else float("nan")
    dev_color = fact_green if dev_rub >= 0 else plan_red
    _dev_sign = "−" if dev_v < 0 else "+"
    dev_val = html_esc(f"{_dev_sign}{abs(dev_v):{vf}} {unit}")
    if dev_mln < 0:
        dev_mln_html = html_esc(f"−{abs(dev_mln):.1f} млн рублей")
    else:
        dev_mln_html = html_esc(f"{dev_mln:.1f} млн рублей")
    dev_pct_html = ""
    if plan_rub > 0 and np.isfinite(dev_pct):
        _dp_sign = "−" if dev_pct < 0 else "+"
        dev_pct_html = (
            f'<p class="appr-pf-kpi-pct" style="color:{html_esc(dev_color)};">'
            f"{_dp_sign}{abs(dev_pct):.1f}% от плана</p>"
        )
    plan_val = html_esc(f"{plan_v:{vf}} {unit}")
    fact_val = html_esc(f"{fact_v:{vf}} {unit}")
    shell = (
        "<!DOCTYPE html><html lang='ru'><head><meta charset='utf-8'>"
        "<style>"
        "html,body{margin:0;padding:0;background:transparent!important;"
        "font-family:Inter,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;}"
        ".appr-pf-summary-kpi{display:flex;gap:1rem;flex-wrap:wrap;align-items:flex-start;"
        "padding:8px 4px;box-sizing:border-box;}"
        ".appr-pf-summary-kpi-col{flex:1 1 150px;min-width:140px;}"
        ".appr-pf-kpi-label{font-size:2.3rem!important;font-weight:800!important;"
        "margin:0 0 0.45rem 0!important;letter-spacing:0.02em!important;line-height:1.1!important;}"
        ".appr-pf-kpi-value{font-size:3.3rem!important;font-weight:700!important;"
        "margin:0 0 0.25rem 0!important;line-height:1.1!important;}"
        ".appr-pf-kpi-muted{font-size:2.1rem!important;font-weight:600!important;"
        "margin:0!important;line-height:1.1!important;}"
        ".appr-pf-kpi-pct{font-size:2.4rem!important;font-weight:700!important;"
        "margin:0.75rem 0 0!important;line-height:1.1!important;}"
        "</style></head><body>"
        '<div class="appr-pf-summary-kpi">'
        '<div class="appr-pf-summary-kpi-col">'
        f'<p class="appr-pf-kpi-label" style="color:{html_esc(plan_red)};">План</p>'
        f'<p class="appr-pf-kpi-value" style="color:{html_esc(value_color)};">{plan_val}</p>'
        f'<p class="appr-pf-kpi-muted" style="color:{html_esc(muted_color)};">'
        f"{plan_mln:.1f} млн рублей</p>"
        f'<p class="appr-pf-kpi-pct" style="color:{html_esc(value_color)};">100%</p>'
        "</div>"
        '<div class="appr-pf-summary-kpi-col">'
        f'<p class="appr-pf-kpi-label" style="color:{html_esc(fact_green)};">Факт</p>'
        f'<p class="appr-pf-kpi-value" style="color:{html_esc(value_color)};">{fact_val}</p>'
        f'<p class="appr-pf-kpi-muted" style="color:{html_esc(muted_color)};">'
        f"{fact_mln:.1f} млн рублей</p>"
        f"{pct_html}"
        "</div>"
        '<div class="appr-pf-summary-kpi-col">'
        f'<p class="appr-pf-kpi-label" style="color:{html_esc(dev_color)};">Отклонение</p>'
        f'<p class="appr-pf-kpi-value" style="color:{html_esc(dev_color)};">{dev_val}</p>'
        f'<p class="appr-pf-kpi-muted" style="color:{html_esc(muted_color)};">{dev_mln_html}</p>'
        f"{dev_pct_html}"
        "</div></div>"
        "</body></html>"
    )
    components.html(shell, height=h, scrolling=False)


