def _plan_fact_gauge_axis_ticks(
    hi: float,
    plan_v: float,
    fact_v: float,
    *,
    value_format: str,
    unit: str,
) -> tuple[list[float], list[str]]:
    """Деления шкалы: 0, план (фиолетовая линия), факт (если отличается)."""
    hi = float(hi or 0.0)
    if hi <= 0:
        return [0.0], ["0"]
    plan_v = float(plan_v or 0.0)
    fact_v = float(fact_v or 0.0)
    raw = [0.0]
    if plan_v > 0:
        raw.append(plan_v)
    if fact_v > 0 and abs(fact_v - plan_v) > 1e-6 and fact_v <= hi + 1e-9:
        raw.append(fact_v)
    ticks = sorted({round(v, 4) for v in raw if 0.0 <= v <= hi + 1e-9})
    if not ticks or ticks[0] != 0.0:
        ticks.insert(0, 0.0)
    texts = [f"{v:{value_format}} {unit}".strip() for v in ticks]
    return ticks, texts


def _render_plan_fact_summary_dashboard(
    st,
    *,
    plan_rub: float,
    fact_rub: float,
    key_suffix: str = "",
    reporting_label: str = "",
) -> None:
    """Сводка план/факт: gauge (накопительный БДДС) — план красный, факт зелёный."""
    plan_rub = float(plan_rub or 0.0)
    fact_rub = float(fact_rub or 0.0)
    use_bln = max(plan_rub, fact_rub, 1.0) >= 1e9
    scale = 1e9 if use_bln else 1e6
    unit = "млрд" if use_bln else "млн"
    vf = ".2f" if use_bln else ".1f"
    plan_v = plan_rub / scale
    fact_v = fact_rub / scale
    plan_mln = plan_rub / 1e6
    fact_mln = fact_rub / 1e6
    if fact_v >= plan_v:
        hi = max(fact_v, 1e-9) * 1.01
    else:
        hi = max(plan_v, fact_v, 1e-9) * 1.05
    pct_of_plan = (100.0 * fact_rub / plan_rub) if plan_rub > 0 else float("nan")
    _gauge_plan_red = "#e74c3c"
    _gauge_fact_green = "#27ae60"

    tickvals, ticktext = _plan_fact_gauge_axis_ticks(
        hi, plan_v, fact_v, value_format=vf, unit=unit
    )
    _light_gauge = False
    try:
        from dashboards.light_theme import is_light_preview_active

        _light_gauge = is_light_preview_active()
    except Exception:
        _light_gauge = False
    _gauge_value_color = _fin_chart_label_color(dark="#f8fbff", light="#111827")
    _gauge_tick_color = _fin_chart_neutral_color()
    _gauge_track = "rgba(15, 23, 42, 0.08)" if _light_gauge else "rgba(255,255,255,0.08)"
    _gauge_bar_thickness = 0.72
    gauge_steps: list[dict] = []
    if plan_v > 0:
        gauge_steps.append(
            {
                "range": [0.0, float(plan_v)],
                "color": _gauge_plan_red,
                "thickness": 1,
            }
        )
        if plan_v < hi - 1e-9:
            gauge_steps.append(
                {
                    "range": [float(plan_v), float(hi)],
                    "color": _gauge_track,
                    "thickness": 1,
                }
            )
    gauge_kw: dict = {
        "shape": "angular",
        "axis": {
            "range": [0.0, float(hi)],
            "tickmode": "array",
            "tickvals": tickvals,
            "ticktext": ticktext,
            "tickwidth": 2,
            "ticklen": 12,
            "tickcolor": "#64748b" if _light_gauge else "#c8d4e3",
            "tickfont": {"size": 15, "color": _gauge_tick_color},
            "showticklabels": True,
        },
        "bar": {"color": _gauge_fact_green, "thickness": _gauge_bar_thickness},
        "bgcolor": _gauge_track,
        "borderwidth": 0,
    }
    if gauge_steps:
        gauge_kw["steps"] = gauge_steps
    if plan_v > 0:
        gauge_kw["threshold"] = {
            "line": {"color": _gauge_plan_red, "width": 3},
            "thickness": 0.82,
            "value": float(plan_v),
        }

    fig = go.Figure(
        go.Indicator(
            mode="gauge+number",
            value=float(fact_v),
            number={
                "suffix": f" {unit}",
                "valueformat": vf,
                "font": {"size": 56, "color": _gauge_value_color},
            },
            gauge=gauge_kw,
        )
    )
    _gauge_h = _APPR_PF_GAUGE_HEIGHT_PX
    fig.update_layout(
        height=_gauge_h,
        margin=dict(l=96, r=96, t=56, b=44),
        autosize=False,
    )
    fig = apply_chart_background(fig)

    st.subheader("Сводный БДДС по проектам")
    st.markdown(_APPR_PF_SUMMARY_GAUGE_CSS, unsafe_allow_html=True)
    st.markdown('<div class="appr-pf-summary-anchor"></div>', unsafe_allow_html=True)
    g_col, val_col = st.columns([1.15, 1.35], gap="medium", vertical_alignment="center")
    with g_col:
        _render_appr_pf_gauge_chart(
            fig,
            height=_gauge_h,
            chart_key=f"appr_budget_summary_gauge_{key_suffix}",
        )
    _kpi_value_color = _gauge_value_color
    _kpi_muted_color = _gauge_tick_color
    with val_col:
        _render_appr_pf_summary_kpi(
            plan_v=plan_v,
            fact_v=fact_v,
            plan_mln=plan_mln,
            fact_mln=fact_mln,
            pct_of_plan=pct_of_plan,
            plan_rub=plan_rub,
            fact_rub=fact_rub,
            vf=vf,
            unit=unit,
            height=_gauge_h,
            plan_red=_gauge_plan_red,
            fact_green=_gauge_fact_green,
            value_color=_kpi_value_color,
            muted_color=_kpi_muted_color,
        )




def _render_budget_histogram_plan_fact_by_projects(filtered_df: pd.DataFrame) -> None:
    """Сводная гистограмма БДДС по проектам."""
    render_table_subheader(st, "Сводная гистограмма БДДС по проектам")

    adjusted_budget_col = None
    if "budget adjusted" in filtered_df.columns:
        adjusted_budget_col = "budget adjusted"
    elif "adjusted budget" in filtered_df.columns:
        adjusted_budget_col = "adjusted budget"

    show_reserve = st.checkbox(
        "Показать отклонение", value=True, key="budget_show_reserve"
    )

    hist_df = filtered_df.copy()
    if hist_df.empty:
        st.info("Нет данных для отображения гистограммы с выбранными фильтрами.")
        return

    hist_df["budget plan"] = pd.to_numeric(hist_df["budget plan"], errors="coerce").fillna(0)
    hist_df["budget fact"] = pd.to_numeric(hist_df["budget fact"], errors="coerce").fillna(0)
    hist_df["reserve budget"] = hist_df["budget fact"] - hist_df["budget plan"]

    if "project name" not in hist_df.columns:
        st.warning("Колонка project name не найдена в данных для построения гистограммы.")
        return

    budget_by_project = (
        hist_df.groupby("project name")
        .agg({"budget plan": "sum", "budget fact": "sum", "reserve budget": "sum"})
        .reset_index()
    )
    if adjusted_budget_col and adjusted_budget_col in hist_df.columns:
        hist_df[adjusted_budget_col] = pd.to_numeric(hist_df[adjusted_budget_col], errors="coerce").fillna(0)
        budget_by_project["budget adjusted"] = (
            hist_df.groupby("project name")[adjusted_budget_col].sum().values
        )
    else:
        budget_by_project["budget adjusted"] = 0.0

    _projects = budget_by_project["project name"].astype(str).tolist()
    _tlbl = 0.005
    _bar_label_color = _fin_chart_label_color()
    fig_hist = go.Figure()
    fig_hist.add_trace(
        go.Bar(
            x=_projects,
            y=budget_by_project["budget plan"].div(1e6),
            name="Бюджет План",
            marker_color="#2E86AB",
            text=_finance_bar_text_mln_rub(
                budget_by_project["budget plan"],
                min_abs_mln=_tlbl,
                unit_suffix=" млн.руб",
            ),
            textposition="outside",
            textfont=dict(size=12, color=_bar_label_color),
        )
    )
    fig_hist.add_trace(
        go.Bar(
            x=_projects,
            y=budget_by_project["budget fact"].div(1e6),
            name="Бюджет Факт",
            marker_color="#A23B72",
            text=_finance_bar_text_mln_rub(
                budget_by_project["budget fact"],
                min_abs_mln=_tlbl,
                unit_suffix=" млн.руб",
            ),
            textposition="outside",
            textfont=dict(size=12, color=_bar_label_color),
        )
    )
    if adjusted_budget_col and float(budget_by_project["budget adjusted"].abs().sum()) > 0:
        fig_hist.add_trace(
            go.Bar(
                x=_projects,
                y=budget_by_project["budget adjusted"].div(1e6),
                name="Бюджет Корректировка",
                marker_color="#F18F01",
                text=_finance_bar_text_mln_rub(
                    budget_by_project["budget adjusted"],
                    min_abs_mln=_tlbl,
                    unit_suffix=" млн.руб",
                ),
                textposition="outside",
                textfont=dict(size=12, color=_bar_label_color),
            )
        )
    if show_reserve:
        _dev_mln = budget_by_project["reserve budget"].div(1e6)
        _dev_thr_mln = 0.01
        _y_fact_lt_plan = _dev_mln.where(_dev_mln < -_dev_thr_mln)
        _y_fact_gt_plan = _dev_mln.where(_dev_mln > _dev_thr_mln)
        _dev_txt_lt = _finance_deviation_bar_text_signed_mln(
            _y_fact_lt_plan,
            min_abs_mln=_tlbl,
            decimals=1,
            unit_suffix=" млн.руб",
        )
        _dev_txt_gt = _finance_deviation_bar_text_signed_mln(
            _y_fact_gt_plan,
            min_abs_mln=_tlbl,
            decimals=1,
            unit_suffix=" млн.руб",
        )
        if _y_fact_lt_plan.notna().any():
            fig_hist.add_trace(
                go.Bar(
                    x=_projects,
                    y=_y_fact_lt_plan,
                    name="Отклонение (факт < план)",
                    marker_color=_FINANCE_DEV_BAR_RED,
                    text=_dev_txt_lt,
                    textposition="outside",
                    textfont=dict(size=12, color=_FINANCE_DEV_LABEL_RED),
                    cliponaxis=False,
                )
            )
        if _y_fact_gt_plan.notna().any():
            fig_hist.add_trace(
                go.Bar(
                    x=_projects,
                    y=_y_fact_gt_plan,
                    name="Отклонение (факт > план)",
                    marker_color=_FINANCE_DEV_BAR_GREEN,
                    text=_dev_txt_gt,
                    textposition="outside",
                    textfont=dict(size=12, color=_FINANCE_DEV_LABEL_GREEN),
                    cliponaxis=False,
                )
            )

    fig_hist.update_layout(
        xaxis_title="Проект",
        yaxis_title="млн.руб.",
        height=600,
        barmode="group",
        xaxis=dict(tickangle=-45, tickfont=dict(size=12)),
        legend=standard_chart_legend(title=dict(text="Тип бюджета")),
        margin=dict(l=56, r=220, t=72, b=120),
    )
    _ymax = float(
        np.nanmax(
            np.concatenate(
                [
                    budget_by_project["budget plan"].div(1e6).to_numpy(),
                    budget_by_project["budget fact"].div(1e6).to_numpy(),
                    *(
                        [budget_by_project["reserve budget"].div(1e6).to_numpy()]
                        if show_reserve
                        else []
                    ),
                ]
            )
        )
    )
    _ymin = 0.0
    if show_reserve:
        _ymin_dev = float(np.nanmin(budget_by_project["reserve budget"].div(1e6).to_numpy()))
        if np.isfinite(_ymin_dev) and _ymin_dev < 0:
            _ymin = _ymin_dev * 1.15
    if np.isfinite(_ymax):
        if _ymax > 0 or _ymin < 0:
            fig_hist.update_layout(yaxis=dict(range=[_ymin, max(_ymax * 1.22, 0.01)], tickformat=".1f"))
        else:
            fig_hist.update_layout(yaxis=dict(tickformat=".1f"))
    else:
        fig_hist.update_layout(yaxis=dict(tickformat=".1f"))
    fig_hist = _apply_finance_bar_label_layout(fig_hist)
    fig_hist = apply_chart_background(fig_hist)
    render_chart(
        fig_hist,
        caption_below=report_chart_caption_body(
            "Сводная гистограмма БДДС", granularity="по проектам"
        ),
    )

    render_table_subheader(st, "Сводная таблица БДДС по проектам")
    _sum_rows: list[dict] = []
    for _, row in budget_by_project.iterrows():
        plan = float(row["budget plan"])
        fact = float(row["budget fact"])
        _sum_rows.append(
            {
                "Проект": str(row["project name"]),
                "Бюджет План, млн руб.": f"{plan / 1e6:.2f}",
                "Бюджет Факт, млн руб.": f"{fact / 1e6:.2f}",
                "Отклонение, млн руб.": _finance_fmt_signed_million_deviation(fact - plan),
            }
        )
    if len(budget_by_project) > 1:
        plan_total = float(budget_by_project["budget plan"].sum())
        fact_total = float(budget_by_project["budget fact"].sum())
        _sum_rows.append(
            {
                "Проект": "ИТОГО",
                "Бюджет План, млн руб.": f"{plan_total / 1e6:.2f}",
                "Бюджет Факт, млн руб.": f"{fact_total / 1e6:.2f}",
                "Отклонение, млн руб.": _finance_fmt_signed_million_deviation(
                    fact_total - plan_total
                ),
            }
        )
    _render_budget_table_html(
        pd.DataFrame(_sum_rows),
        finance_deviation_column="Отклонение, млн руб.",
        deviation_color_fact_vs_plan=True,
        expense_overrun_style=False,
        file_stem="budget_summary",
        key_prefix="budget_summary",
        **_appr_budget_table_html_kwargs(),
    )

def _approved_budget_get_monthly_slice(
    filtered_df: pd.DataFrame,
    selected_project: str,
) -> tuple[pd.DataFrame | None, str]:
    """Помесячные строки БДДС до отчётной даты (budget_period_to или последний месяц)."""
    from dashboards.finance_from_1c import try_synthetic_budget_from_1c_dannye

    ref = st.session_state.get("reference_1c_dannye")
    syn = try_synthetic_budget_from_1c_dannye(reference_1c_dannye=ref)
    sub: pd.DataFrame | None = None
    if syn is not None and not syn.empty:
        sub = syn.copy()
    elif filtered_df is not None and not filtered_df.empty:
        sub = filtered_df.copy()
        ensure_date_columns(sub)
        if "plan end" in sub.columns:
            _pe = pd.to_datetime(sub["plan end"], errors="coerce")
            _mask = _pe.notna()
            if _mask.any() and "plan_month" not in sub.columns:
                sub.loc[_mask, "plan_month"] = _pe.loc[_mask].dt.to_period("M")

    if sub is None or sub.empty:
        return None, ""

    # Синтетический БДДС хранит «сырые» имена проектов (напр. «Дмитровский-1»),
    # тогда как approved-budget уже канонизирован («Дмитровский»). Приводим срез к
    # каноническим подписям, чтобы группировка и фильтр по одному проекту совпадали
    # с таблицей «Все проекты» (иначе фильтр по «Дмитровский» не находил «Дмитровский-1»
    # и падал в другой источник данных с иными суммами).
    if "project name" in sub.columns:
        sub = _project_column_apply_canonical(sub, "project name")

    if selected_project and selected_project != "Все" and "project name" in sub.columns:
        sub = sub[
            sub["project name"].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ].copy()
    if sub.empty:
        return None, ""

    if "plan_month" not in sub.columns and "plan end" in sub.columns:
        _pe2 = pd.to_datetime(sub["plan end"], errors="coerce")
        sub = sub.assign(plan_month=_pe2.dt.to_period("M"))
    if "plan_month" not in sub.columns:
        return None, ""

    sub["budget plan"] = pd.to_numeric(sub.get("budget plan", 0), errors="coerce").fillna(0.0)
    sub["budget fact"] = pd.to_numeric(sub.get("budget fact", 0), errors="coerce").fillna(0.0)
    sub = sub[sub["plan_month"].notna()].copy()
    if sub.empty:
        return None, ""

    reporting_label = ""
    pt = st.session_state.get("budget_period_to")
    if pt is not None:
        te = pd.to_datetime(pt, errors="coerce")
        if pd.notna(te):
            report_period = te.to_period("M")
            sub = sub[sub["plan_month"] <= report_period].copy()
            reporting_label = format_period_ru(report_period)
    if sub.empty:
        return None, reporting_label

    if not reporting_label:
        reporting_label = format_period_ru(sub["plan_month"].max())

    return sub, str(reporting_label)


def _approved_budget_cumulative_by_project(
    monthly_slice: pd.DataFrame,
) -> pd.DataFrame:
    """Накопительный план/факт по каждому проекту на конец среза monthly_slice."""
    if monthly_slice is None or monthly_slice.empty:
        return pd.DataFrame(columns=["project name", "budget plan", "budget fact"])

    rows: list[dict] = []
    if "project name" in monthly_slice.columns:
        for proj, grp in monthly_slice.groupby("project name", dropna=False):
            g = (
                grp.groupby("plan_month", dropna=False)[["budget plan", "budget fact"]]
                .sum()
                .reset_index()
                .sort_values("plan_month")
            )
            if g.empty:
                continue
            g = g.copy()
            g["plan_cum"] = g["budget plan"].cumsum()
            g["fact_cum"] = g["budget fact"].cumsum()
            last = g.iloc[-1]
            rows.append(
                {
                    "project name": str(proj),
                    "budget plan": float(last["plan_cum"]),
                    "budget fact": float(last["fact_cum"]),
                }
            )
    else:
        g = (
            monthly_slice.groupby("plan_month", dropna=False)[["budget plan", "budget fact"]]
            .sum()
            .reset_index()
            .sort_values("plan_month")
        )
        if not g.empty:
            g = g.copy()
            g["plan_cum"] = g["budget plan"].cumsum()
            g["fact_cum"] = g["budget fact"].cumsum()
            last = g.iloc[-1]
            rows.append(
                {
                    "project name": "Итого",
                    "budget plan": float(last["plan_cum"]),
                    "budget fact": float(last["fact_cum"]),
                }
            )
    return pd.DataFrame(rows)


def _approved_budget_cumulative_totals(
    filtered_df: pd.DataFrame,
    selected_project: str,
    *,
    fallback_plan: float,
    fallback_fact: float,
) -> tuple[float, float, str, bool]:
    """Накопительный БДДС план/факт до отчётной даты (budget_period_to или последний месяц)."""
    monthly_slice, reporting_label = _approved_budget_get_monthly_slice(
        filtered_df, selected_project
    )
    if monthly_slice is None or monthly_slice.empty:
        return float(fallback_plan), float(fallback_fact), reporting_label, False

    cum_proj = _approved_budget_cumulative_by_project(monthly_slice)
    if cum_proj.empty:
        return float(fallback_plan), float(fallback_fact), reporting_label, False

    plan_total = float(cum_proj["budget plan"].sum())
    fact_total = float(cum_proj["budget fact"].sum())
    return plan_total, fact_total, reporting_label, True


def _render_approved_budget_plan_fact(df: pd.DataFrame) -> None:
    """Утверждённый бюджет план/факт (ТЗ «ФИНАНСЫ» от 2026-05-07).

    - Чарт: группированные столбцы по проектам (План=фиолетовый, Факт=малиновый), как на рис. 4 ТЗ.
    - Раскрывающаяся таблица: Проект | Утверждённый бюджет | Фактические расходы | Отклонение.
    - Цвет «Отклонение»: <0 — красный, >0 — зелёный (через `budget_table_to_html(deviation_red_if_negative=True)`).
    - Фильтр Проект (по умолчанию «Все»).
    """
    df = df.copy()
    from dashboards.finance_from_1c import (
        ensure_budget_frame_with_fallback,
        try_approved_budget_from_1c_dannye,
    )

    ref = st.session_state.get("reference_1c_dannye")
    syn = try_approved_budget_from_1c_dannye(reference_1c_dannye=ref)
    used_1c_approved = bool(syn is not None and not syn.empty)

    if used_1c_approved:
        budget_df = syn.copy()
    else:
        ensure_budget_columns(df)
        df, _ = ensure_budget_frame_with_fallback(df, show_caption=False)
        ensure_budget_columns(df)
        budget_df = df

    if "project name" in budget_df.columns:
        budget_df = _project_column_apply_canonical(budget_df, "project name")

    with filters_panel(
        st,
        reset_keys=["approved_budget_project"],
        reset_defaults={"approved_budget_project": "Все"},
    ):
        with filters_selectors(st):
            if "project name" in budget_df.columns:
                projects = ["Все"] + _unique_project_labels_for_select(budget_df["project name"])
                selected_project = st.selectbox(
                    "Проект", projects, key="approved_budget_project"
                )
            else:
                selected_project = "Все"
                st.info("Колонка 'project name' не найдена.")

    filtered_df = budget_df.copy()
    if selected_project != "Все" and "project name" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["project name"].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ]

    if (
        "budget plan" not in filtered_df.columns
        or "budget fact" not in filtered_df.columns
    ):
        st.warning(
            "Столбцы бюджета (`budget plan` / `budget fact`) не найдены в MSP и не собраны из 1С. "
            "Добавьте в web/ JSON оборотов (массив записей): предпочтительно `*_dannye.json` или файл с колонками "
            "ТипСтатьи / Сценарий / СтатьяОборотов / Сумма — тогда загрузчик подхватит его даже при «нестандартном» имени; "
            "либо выгрузку MSP с колонками budget plan и budget fact."
        )
        return

    filtered_df["budget plan"] = pd.to_numeric(filtered_df["budget plan"], errors="coerce").fillna(0.0)
    filtered_df["budget fact"] = pd.to_numeric(filtered_df["budget fact"], errors="coerce").fillna(0.0)

    if "project name" in filtered_df.columns:
        agg = (
            filtered_df.groupby("project name", dropna=False)
            .agg(plan=("budget plan", "sum"), fact=("budget fact", "sum"))
            .reset_index()
        )
    else:
        agg = pd.DataFrame(
            [
                {
                    "project name": "Итого",
                    "plan": float(filtered_df["budget plan"].sum()),
                    "fact": float(filtered_df["budget fact"].sum()),
                }
            ]
        )
    if agg.empty:
        st.info("Нет данных для отображения по выбранному фильтру.")
        return

    plan_total = float(agg["plan"].sum())
    fact_total = float(agg["fact"].sum())

    monthly_slice, reporting_label = _approved_budget_get_monthly_slice(
        budget_df, selected_project
    )
    used_cumulative = monthly_slice is not None and not monthly_slice.empty
    if used_cumulative:
        display_df = _approved_budget_cumulative_by_project(monthly_slice)
        cum_plan = float(display_df["budget plan"].sum())
        cum_fact = float(display_df["budget fact"].sum())
    else:
        display_df = filtered_df
        cum_plan, cum_fact = plan_total, fact_total
        st.caption(
            "Накопительный БДДС недоступен (нет помесячных данных) — показаны полные суммы."
        )

    _render_plan_fact_summary_dashboard(
        st,
        plan_rub=cum_plan,
        fact_rub=cum_fact,
        reporting_label=reporting_label,
        key_suffix=_project_filter_norm_key(str(selected_project)),
    )

    _all_projects = str(selected_project or "Все").strip() == "Все"
    if _all_projects and used_cumulative:
        _render_approved_budget_monthly_block(
            monthly_slice,
            selected_project,
            reporting_label=reporting_label,
            skip_msp_fallback=True,
            primary_histogram=True,
        )
    else:
        _render_budget_histogram_plan_fact_by_projects(display_df)
        _render_approved_budget_monthly_block(
            monthly_slice if used_cumulative else filtered_df,
            selected_project,
            reporting_label=reporting_label if used_cumulative else "",
            skip_msp_fallback=used_cumulative,
        )

    _render_plan_fact_detail_table(
        st,
        display_df,
        msp_df=df if used_1c_approved else None,
        key_suffix=_project_filter_norm_key(str(selected_project)),
    )


def _render_approved_budget_monthly_block(
    df: pd.DataFrame,
    selected_project: str,
    *,
    reporting_label: str = "",
    skip_msp_fallback: bool = False,
    primary_histogram: bool = False,
) -> None:
    """График «Утверждённый бюджет (план/факт) по месяцам» + сводная таблица по месяцам.

    Источник — MSP-фрейм (`budget plan` / `budget fact` + `plan end` или `plan_month`).
    Округления — до десятых (1 знак), как в новом ТЗ от 08.05.2026.
    Без gauge/KPI — заказчик прямо требовал убрать.
    """
    from dashboards.finance_from_1c import ensure_budget_frame_with_fallback

    if df is None or df.empty:
        return
    src = df.copy()
    if skip_msp_fallback:
        ensure_budget_columns(src)
        ensure_date_columns(src)
    else:
        ensure_budget_columns(src)
        src, _ = ensure_budget_frame_with_fallback(src, show_caption=False)
        ensure_budget_columns(src)
        ensure_date_columns(src)

    if "budget plan" not in src.columns or "budget fact" not in src.columns:
        return

    project_col = (
        "project name" if "project name" in src.columns
        else ("Проект" if "Проект" in src.columns else None)
    )
    if not skip_msp_fallback and selected_project and selected_project != "Все" and project_col:
        src = src[
            src[project_col].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ]
    if src.empty:
        return

    if "plan_month" not in src.columns and "plan end" in src.columns:
        plan_end = pd.to_datetime(src["plan end"], errors="coerce")
        mask = plan_end.notna()
        if mask.any():
            src.loc[mask, "plan_month"] = plan_end.loc[mask].dt.to_period("M")
    if "plan_month" not in src.columns:
        return

    if primary_histogram:
        render_table_subheader(st, "Гистограмма: Бюджет план/факт/отклонение по месяцам")
    else:
        render_table_subheader(
            st,
            report_title_name("утверждённого бюджета план/факт", "по месяцам"),
        )
    if reporting_label:
        st.caption(f"Помесячные обороты до {reporting_label} (тот же срез, что спидометр).")
    _hide_zero_key = (
        "approved_budget_primary_hide_zero_months"
        if primary_histogram
        else "approved_budget_planfact_hide_zero_months"
    )
    _appr_hide_zero = st.checkbox(
        "Скрывать месяцы, где план и факт равны 0",
        value=True,
        key=_hide_zero_key,
    )
    _show_reserve = False
    if primary_histogram:
        _show_reserve = st.checkbox(
            "Показать отклонение",
            value=True,
            key="approved_budget_primary_show_reserve",
        )
    monthly_rows = (
        src.groupby("plan_month")
        .agg({"budget plan": "sum", "budget fact": "sum"})
        .reset_index()
        .sort_values("plan_month")
    )
    if monthly_rows.empty:
        st.info("Нет строк с периодом для построения графика.")
        return

    monthly_rows["Месяц"] = monthly_rows["plan_month"].apply(format_period_ru)
    monthly_rows["reserve budget"] = monthly_rows["budget fact"] - monthly_rows["budget plan"]

    if _appr_hide_zero:
        _pl0 = monthly_rows["budget plan"].fillna(0.0)
        _fc0 = monthly_rows["budget fact"].fillna(0.0)
        monthly_rows = monthly_rows.loc[_pl0.abs() + _fc0.abs() > 0.5].copy()
    if monthly_rows.empty:
        st.info("Нет месяцев с данными для графика.")
        return

    fig = go.Figure()
    _n_m = len(monthly_rows)
    _text_min_mln = 0.005
    _tf_size = 8 if _n_m > 32 else 9 if _n_m > 20 else 10 if _n_m > 12 else 11
    if _n_m > 32:
        _bg, _bgg = 0.04, 0.01
    elif _n_m > 18:
        _bg, _bgg = 0.06, 0.02
    else:
        _bg, _bgg = 0.1, 0.04

    _bar_label_color = _fin_chart_label_color()
    fig.add_trace(
        go.Bar(
            x=monthly_rows["Месяц"],
            y=monthly_rows["budget plan"].div(1e6),
            name="БДДС план",
            marker_color="#2E86AB",
            text=_finance_bar_text_mln_rub(
                monthly_rows["budget plan"],
                min_abs_mln=_text_min_mln,
                unit_suffix=" млн.руб",
            ),
            textposition="outside",
            textfont=dict(size=_tf_size, color=_bar_label_color),
            cliponaxis=False,
            hovertemplate="<b>%{x}</b><br>БДДС план: %{customdata}<extra></extra>",
            customdata=monthly_rows["budget plan"].apply(format_million_rub),
        )
    )
    fig.add_trace(
        go.Bar(
            x=monthly_rows["Месяц"],
            y=monthly_rows["budget fact"].div(1e6),
            name="БДДС факт",
            marker_color="#A23B72",
            text=_finance_bar_text_mln_rub(
                monthly_rows["budget fact"],
                min_abs_mln=_text_min_mln,
                unit_suffix=" млн.руб",
            ),
            textposition="outside",
            textfont=dict(size=_tf_size, color=_bar_label_color),
            cliponaxis=False,
            hovertemplate="<b>%{x}</b><br>БДДС факт: %{customdata}<extra></extra>",
            customdata=monthly_rows["budget fact"].apply(format_million_rub),
        )
    )
    if _show_reserve:
        _dev_mln = monthly_rows["reserve budget"].div(1e6)
        _dev_thr_mln = 0.01
        _y_fact_lt_plan = _dev_mln.where(_dev_mln < -_dev_thr_mln)
        _y_fact_gt_plan = _dev_mln.where(_dev_mln > _dev_thr_mln)
        _dev_txt_lt = _finance_deviation_bar_text_signed_mln(
            _y_fact_lt_plan,
            min_abs_mln=_text_min_mln,
            decimals=1,
            unit_suffix=" млн.руб",
        )
        _dev_txt_gt = _finance_deviation_bar_text_signed_mln(
            _y_fact_gt_plan,
            min_abs_mln=_text_min_mln,
            decimals=1,
            unit_suffix=" млн.руб",
        )
        _months_x = monthly_rows["Месяц"].astype(str).tolist()
        if _y_fact_lt_plan.notna().any():
            fig.add_trace(
                go.Bar(
                    x=_months_x,
                    y=_y_fact_lt_plan,
                    name="Отклонение (факт < план)",
                    marker_color=_FINANCE_DEV_BAR_RED,
                    text=_dev_txt_lt,
                    textposition="outside",
                    textfont=dict(size=_tf_size, color=_FINANCE_DEV_LABEL_RED),
                    cliponaxis=False,
                )
            )
        if _y_fact_gt_plan.notna().any():
            fig.add_trace(
                go.Bar(
                    x=_months_x,
                    y=_y_fact_gt_plan,
                    name="Отклонение (факт > план)",
                    marker_color=_FINANCE_DEV_BAR_GREEN,
                    text=_dev_txt_gt,
                    textposition="outside",
                    textfont=dict(size=_tf_size, color=_FINANCE_DEV_LABEL_GREEN),
                    cliponaxis=False,
                )
            )
    _leg_b_pre = max(300, min(460, 280 + int(_n_m * 3.5)))
    _top_px_pre = 140
    _min_plot_core_px = 400
    _ch_base = 600 if _n_m <= 20 else int(min(1100, 520 + int(_n_m * 1.4)))
    _chart_h = max(_ch_base, _top_px_pre + _leg_b_pre + _min_plot_core_px)
    _chart_h = int(min(1400, _chart_h))
    fig.update_layout(
        title_text="",
        yaxis_title="млн рублей",
        barmode="group",
        bargap=_bg,
        bargroupgap=_bgg,
        hovermode="x unified",
        height=_chart_h,
        xaxis=dict(title=dict(text="Месяц", standoff=30)),
    )
    fig = _apply_finance_bar_label_layout(fig)
    try:
        fig.update_layout(uniformtext=dict(minsize=1, mode="show"))
    except Exception:
        pass
    if not monthly_rows.empty:
        _ymax_parts = [
            monthly_rows["budget plan"].div(1e6).to_numpy(),
            monthly_rows["budget fact"].div(1e6).to_numpy(),
        ]
        if _show_reserve:
            _ymax_parts.append(monthly_rows["reserve budget"].div(1e6).to_numpy())
        _ymax = float(np.nanmax(np.concatenate(_ymax_parts)))
        _ymin = 0.0
        if _show_reserve:
            _ymin_dev = float(np.nanmin(monthly_rows["reserve budget"].div(1e6).to_numpy()))
            if np.isfinite(_ymin_dev) and _ymin_dev < 0:
                _ymin = _ymin_dev * 1.15
        if np.isfinite(_ymax) and (_ymax > 0 or _ymin < 0):
            fig.update_layout(yaxis=dict(range=[_ymin, max(_ymax * 1.28, 0.01)], tickformat=".1f"))
        else:
            fig.update_layout(yaxis=dict(tickformat=".1f"))
    fig = apply_chart_background(fig)
    _render_finance_bar_chart(
        fig,
        n_periods=_n_m,
        height=_chart_h,
        caption_below=report_chart_caption_body(
            "утверждённого бюджета план/факт", "Месяц"
        ),
        categories=monthly_rows["Месяц"].astype(str).tolist(),
        px_per_month=400,
        force_hscroll=True,
        n_bar_slots=3 if _show_reserve else 2,
    )

    if not primary_histogram:
        render_table_subheader(
            st,
            report_title_name("утверждённого бюджета", "по месяцам"),
        )
    elif primary_histogram:
        render_table_subheader(st, "Сводная таблица БДДС по месяцам")
    summary_table = monthly_rows[
        ["Месяц", "budget plan", "budget fact", "reserve budget"]
    ].copy()
    summary_table["БДДС план, млн руб."] = summary_table["budget plan"].apply(
        lambda x: f"{float(x) / 1e6:.1f}" if pd.notna(x) else ""
    )
    summary_table["БДДС факт, млн руб."] = summary_table["budget fact"].apply(
        lambda x: f"{float(x) / 1e6:.1f}" if pd.notna(x) else ""
    )
    summary_table["Отклонение, млн руб."] = summary_table["reserve budget"].apply(
        _finance_fmt_signed_million_deviation
    )
    summary_table = summary_table[
        ["Месяц", "БДДС план, млн руб.", "БДДС факт, млн руб.", "Отклонение, млн руб."]
    ]
    _render_budget_table_html(
        summary_table,
        finance_deviation_column="Отклонение, млн руб.",
        deviation_color_fact_vs_plan=True,
        file_stem="approved_budget_by_month",
        key_prefix="appr_budget_planfact_summary",
        **_appr_budget_table_html_kwargs(),
    )


# ==================== DASHBOARD 8: Budget by Type (Plan/Fact/Reserve) ====================
def dashboard_budget_by_type(df):
    """Точка входа отчёта «Бюджет план/факт» / «Утверждённый бюджет план/факт».

    Делегирует на `_render_approved_budget_plan_fact` (новая логика по ТЗ заказчика 2026-05-07).
    Прежняя реализация (gauge «Исполнение бюджета» + KPI-метрики + group-bar c типами
    «План/Факт/Корректировка/Перерасход/Экономия») удалена по явному требованию заказчика.
    """
    _render_approved_budget_plan_fact(df)
    return
    df = df.copy()
    from dashboards.finance_from_1c import ensure_budget_frame_with_fallback

    ensure_budget_columns(df)
    df, _budget_type_used_1c = ensure_budget_frame_with_fallback(df, show_caption=True)
    ensure_budget_columns(df)
    ensure_date_columns(df)
    if "project name" in df.columns:
        df = _project_column_apply_canonical(df, "project name")
    col1, col2, col3 = st.columns(3, gap="small")

    with col1:
        if "project name" in df.columns:
            projects = ["Все"] + _unique_project_labels_for_select(df["project name"])
            selected_project = st.selectbox(
                "Проект", projects, key="budget_type_project"
            )
        else:
            selected_project = "Все"
            st.info("Колонка 'project name' не найдена")

    with col2:
        if "section" in df.columns:
            sections = ["Все"] + sorted(df["section"].dropna().unique().tolist())
            selected_section = st.selectbox(
                "Этап", sections, key="budget_type_section"
            )
        else:
            selected_section = "Все"

    # Apply filters
    filtered_df = df.copy()
    if selected_project != "Все" and "project name" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["project name"].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ]
    if selected_section != "Все" and "section" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["section"].astype(str).str.strip()
            == str(selected_section).strip()
        ]
    # Check for budget columns (нормализуем русские названия)
    ensure_budget_columns(filtered_df)
    from dashboards.data_quality_hints import collect_budget_1c_hints, render_quality_hints

    _budget_type_q_hints = collect_budget_1c_hints(
        dict(getattr(filtered_df, "attrs", {}) or {}),
        used_fallback_1c=bool(_budget_type_used_1c),
    )
    has_budget = (
        "budget plan" in filtered_df.columns and "budget fact" in filtered_df.columns
    )

    if not has_budget:
        st.warning("Столбцы бюджета (budget plan, budget fact) не найдены в данных.")
        return

    # Остаток = План - Факт; Отклонение = Факт - План (>=0 красный, <0 зелёный)
    filtered_df["budget plan"] = pd.to_numeric(
        filtered_df["budget plan"], errors="coerce"
    )
    filtered_df["budget fact"] = pd.to_numeric(
        filtered_df["budget fact"], errors="coerce"
    )
    filtered_df["Остаток"] = (
        filtered_df["budget plan"] - filtered_df["budget fact"]
    )
    filtered_df["reserve budget"] = (
        filtered_df["budget fact"] - filtered_df["budget plan"]
    )

    # Колонка контрактации для % покрытия контрактами = контрактация / план * 100
    def _find_contract_column(d):
        for cand in ("Контрактация", "контрактация", "Контракт", "contract", "Contract", "Покрытие контрактами"):
            if cand in d.columns:
                return cand
        for col in d.columns:
            c = str(col).lower().strip()
            if "контрактация" in c or "контракт" in c and "план" not in c or "покрытие" in c and "контракт" in c:
                return col
        return None
    contract_col = _find_contract_column(filtered_df)
    if contract_col:
        filtered_df["_contract_numeric"] = pd.to_numeric(
            filtered_df[contract_col], errors="coerce"
        ).fillna(0)
    else:
        filtered_df["_contract_numeric"] = 0

    plan_total_abs = float(filtered_df["budget plan"].fillna(0).sum())
    fact_total_abs = float(filtered_df["budget fact"].fillna(0).sum())
    plan_total_mld = plan_total_abs / 1e9
    fact_total_mld = fact_total_abs / 1e9
    plan_total_mln = plan_total_abs / 1e6
    fact_total_mln = fact_total_abs / 1e6
    fact_share_pct = (fact_total_abs / plan_total_abs * 100.0) if plan_total_abs > 0 else 0.0
    overrun_pct = ((fact_total_abs - plan_total_abs) / plan_total_abs * 100.0) if plan_total_abs > 0 else 0.0
    if overrun_pct > 0:
        fact_tone = "#e74c3c"
    elif overrun_pct >= -20:
        fact_tone = "#f39c12"
    else:
        fact_tone = "#27ae60"

    gauge_max_mld = max(plan_total_mld, fact_total_mld, 0.01)
    gauge_number_format = ".3f" if gauge_max_mld < 0.1 else ".2f"
    metric_unit = "млн" if gauge_max_mld < 0.1 else "млрд"
    plan_metric_value = plan_total_mln if metric_unit == "млн" else plan_total_mld
    fact_metric_value = fact_total_mln if metric_unit == "млн" else fact_total_mld
    metric_decimals = 2 if metric_unit == "млн" else 2

    render_table_subheader(st, "Бюджет план/факт")
    kpi_gauge_col, kpi_plan_col, kpi_fact_col = st.columns([1.3, 1, 1], gap="small")
    with kpi_gauge_col:
        fig_kpi = go.Figure(
            go.Indicator(
                mode="gauge+number",
                value=fact_total_mld,
                number={
                    "suffix": " млрд",
                    "valueformat": gauge_number_format,
                    "font": {"size": 26, "color": "#f8fbff"},
                },
                gauge={
                    "axis": {"range": [0, gauge_max_mld]},
                    "bar": {"color": fact_tone},
                    "bgcolor": "#d8dde6",
                    "steps": [
                        {
                            "range": [0, gauge_max_mld],
                            "color": "rgba(255,255,255,0.08)",
                        }
                    ],
                },
                title={"text": "Исполнение бюджета"},
            )
        )
        fig_kpi.update_layout(height=220, margin=dict(l=16, r=16, t=48, b=16))
        fig_kpi = apply_chart_background(fig_kpi)
        render_chart(fig_kpi, caption_below=report_chart_caption_body("Бюджет план/факт"))
        render_quality_hints(_budget_type_q_hints)
    with kpi_plan_col:
        st.metric(
            "Расходы план",
            f"{plan_metric_value:,.{metric_decimals}f} {metric_unit}".replace(",", " "),
        )
    with kpi_fact_col:
        st.metric(
            "Расходы факт",
            f"{fact_metric_value:,.{metric_decimals}f} {metric_unit}".replace(",", " "),
            delta=f"{overrun_pct:+.1f}%"
        )

    # R23-13.3/4: в таблице оставлены «План / Факт / Отклонение»
    # (столбцы «Остаток», «% выполнения», «% покрытия контрактами» убраны по ТЗ).
    render_table_subheader(st, "Бюджет план/факт по проектам")
    if "project name" in filtered_df.columns:
        agg_dict = {
            "budget plan": "sum",
            "budget fact": "sum",
            "Остаток": "sum",
            "reserve budget": "sum",
            "_contract_numeric": "sum",
        }
        table_agg = filtered_df.groupby("project name").agg(agg_dict).reset_index()
    else:
        table_agg = pd.DataFrame(
            [{
                "project name": "Итого",
                "budget plan": filtered_df["budget plan"].sum(),
                "budget fact": filtered_df["budget fact"].sum(),
                "Остаток": filtered_df["Остаток"].sum(),
                "reserve budget": filtered_df["reserve budget"].sum(),
                "_contract_numeric": filtered_df["_contract_numeric"].sum(),
            }]
        )
    table_agg["План, млн руб."] = (
        (table_agg["budget plan"] / 1e6).round(2).apply(
            lambda x: f"{float(x):.2f}" if pd.notna(x) else ""
        )
    )
    table_agg["Факт, млн руб."] = (
        (table_agg["budget fact"] / 1e6).round(2).apply(
            lambda x: f"{float(x):.2f}" if pd.notna(x) else ""
        )
    )
    table_agg["Отклонение, млн руб."] = (
        (table_agg["reserve budget"] / 1e6).round(2).apply(
            lambda x: f"{float(x):.2f}" if pd.notna(x) else ""
        )
    )
    display_cols = [
        "project name",
        "План, млн руб.",
        "Факт, млн руб.",
        "Отклонение, млн руб.",
    ]
    budget_table_display = table_agg[display_cols].copy()
    budget_table_display = budget_table_display.rename(columns={"project name": "Проект"})
    # Строка «Итого» при группировке по проектам
    if "project name" in table_agg.columns and len(table_agg) > 1:
        plan_total = float(table_agg["budget plan"].sum())
        fact_total = float(table_agg["budget fact"].sum())
        total_row = {
            "Проект": "Итого",
            "План, млн руб.": f"{plan_total / 1e6:.2f}",
            "Факт, млн руб.": f"{fact_total / 1e6:.2f}",
            "Отклонение, млн руб.": f"{(fact_total - plan_total) / 1e6:.2f}",
        }
        budget_table_display = pd.concat([
            budget_table_display,
            pd.DataFrame([total_row]),
        ], ignore_index=True)
    # R23-13.3: окраска отклонения (<0 — зелёный, >0 — красный) через budget_table_to_html.
    _render_budget_table_html(
            budget_table_display,
            finance_deviation_column="Отклонение, млн руб.",
        )
    render_quality_hints(_budget_type_q_hints)

    # ========== Histogram: Budget by Project and Type ==========
    render_table_subheader(st, "Гистограмма: Бюджет план/факт/отклонение по проектам")

    adjusted_budget_col = None
    if "budget adjusted" in df.columns:
        adjusted_budget_col = "budget adjusted"
    elif "adjusted budget" in df.columns:
        adjusted_budget_col = "adjusted budget"

    show_reserve = st.checkbox(
        "Показать отклонение", value=False, key="budget_show_reserve"
    )
    selected_budget_types = ["Бюджет План", "Бюджет Факт"]
    if adjusted_budget_col:
        selected_budget_types.append("Бюджет Корректировка")
    if show_reserve:
        selected_budget_types.append("Отклонение (перерасход)")
        selected_budget_types.append("Отклонение (экономия)")

    # Apply filters for histogram - use filtered_df to respect project filter
    hist_df = filtered_df.copy()

    if selected_section != "Все" and "section" in hist_df.columns:
        hist_df = hist_df[
            hist_df["section"].astype(str).str.strip() == str(selected_section).strip()
        ]

    if hist_df.empty:
        st.info("Нет данных для отображения гистограммы с выбранными фильтрами.")
    else:
        # Convert budget columns to numeric
        hist_df["budget plan"] = pd.to_numeric(
            hist_df["budget plan"], errors="coerce"
        ).fillna(0)
        hist_df["budget fact"] = pd.to_numeric(
            hist_df["budget fact"], errors="coerce"
        ).fillna(0)
        hist_df["reserve budget"] = hist_df["budget plan"] - hist_df["budget fact"]

        # Group by project and aggregate
        if "project name" in hist_df.columns:
            budget_by_project = (
                hist_df.groupby("project name")
                .agg(
                    {
                        "budget plan": "sum",
                        "budget fact": "sum",
                        "reserve budget": "sum",
                    }
                )
                .reset_index()
            )

            # Add adjusted budget if available
            if adjusted_budget_col and adjusted_budget_col in hist_df.columns:
                # Convert to numeric first
                hist_df[adjusted_budget_col] = pd.to_numeric(
                    hist_df[adjusted_budget_col], errors="coerce"
                ).fillna(0)
                budget_by_project["budget adjusted"] = (
                    hist_df.groupby("project name")[adjusted_budget_col].sum().values
                )
            else:
                budget_by_project["budget adjusted"] = 0

            # Transform to long format
            hist_melted = []
            for idx, row in budget_by_project.iterrows():
                project = row["project name"]

                if "Бюджет План" in selected_budget_types:
                    hist_melted.append(
                        {
                            "project name": project,
                            "Тип бюджета": "Бюджет План",
                            "Сумма": row["budget plan"],
                        }
                    )

                if "Бюджет Факт" in selected_budget_types:
                    hist_melted.append(
                        {
                            "project name": project,
                            "Тип бюджета": "Бюджет Факт",
                            "Сумма": row["budget fact"],
                        }
                    )

                if (
                    "Бюджет Корректировка" in selected_budget_types
                    and adjusted_budget_col
                ):
                    hist_melted.append(
                        {
                            "project name": project,
                            "Тип бюджета": "Бюджет Корректировка",
                            "Сумма": row["budget adjusted"],
                        }
                    )

                if "Отклонение (перерасход)" in selected_budget_types and row["reserve budget"] >= 0:
                    hist_melted.append(
                        {
                            "project name": project,
                            "Тип бюджета": "Отклонение (перерасход)",
                            "Сумма": row["reserve budget"],
                        }
                    )
                if "Отклонение (экономия)" in selected_budget_types and row["reserve budget"] < 0:
                    hist_melted.append(
                        {
                            "project name": project,
                            "Тип бюджета": "Отклонение (экономия)",
                            "Сумма": row["reserve budget"],
                        }
                    )

            hist_by_type_df = pd.DataFrame(hist_melted)

            if hist_by_type_df.empty:
                st.info("Нет данных для отображения с выбранными типами бюджета.")
            else:
                # Преобразуем значения в миллионы рублей для отображения на столбцах
                hist_by_type_df["Сумма_млн"] = hist_by_type_df["Сумма"] / 1e6
                hist_by_type_df["bar_text"] = _finance_bar_text_mln_rub(
                    hist_by_type_df["Сумма"],
                    unit_suffix=" млн рублей",
                )

                fig_hist = px.bar(
                    hist_by_type_df,
                    x="project name",
                    y="Сумма_млн",
                    color="Тип бюджета",
                    title=None,
                    labels={"project name": "Проект", "Сумма_млн": "млн рублей"},
                    barmode="group",
                    text="bar_text",
                    color_discrete_map={
                        "Бюджет План": "#2E86AB",
                        "Бюджет Факт": "#A23B72",
                        "Бюджет Корректировка": "#F18F01",
                        "Отклонение (перерасход)": "#e74c3c",
                        "Отклонение (экономия)": "#27ae60",
                    },
                )

                fig_hist.update_layout(
                    xaxis_title="Проект",
                    yaxis_title="млн рублей",
                    height=600,
                    xaxis=dict(tickangle=-45, tickfont=dict(size=12)),
                )

                fig_hist.update_traces(
                    textposition="outside",
                    texttemplate="%{text}",
                    textfont=dict(size=12, color="white"),
                )
                try:
                    fig_hist.update_layout(yaxis=dict(tickformat=".1f"))
                except Exception:
                    pass

                fig_hist = _apply_finance_bar_label_layout(fig_hist)
                fig_hist.update_layout(
                    legend=standard_chart_legend(),
                    margin=dict(l=56, r=220, t=72, b=120),
                )
                fig_hist = apply_chart_background(fig_hist)
                render_chart(
                    fig_hist,
                    caption_below=report_chart_caption_body(
                        "Бюджет план/факт/отклонение", granularity="по проектам"
                    ),
                )
                render_quality_hints(_budget_type_q_hints)

                # Summary table (суммы в млн руб., два знака, подпись в названии колонки)
                render_table_subheader(st, "Бюджет план/факт по проектам")
                summary_hist = hist_by_type_df.pivot_table(
                    index="project name",
                    columns="Тип бюджета",
                    values="Сумма",
                    aggfunc="sum",
                    fill_value=0,
                ).reset_index()

                # Переводим в млн руб., два знака после запятой; подпись "млн руб." в названии колонки
                for col in summary_hist.columns:
                    if col != "project name":
                        summary_hist[col] = (
                            (summary_hist[col].astype(float) / 1e6)
                            .round(2)
                            .apply(lambda x: f"{float(x):.2f}" if pd.notna(x) else "0.00")
                        )
                summary_hist = summary_hist.rename(
                    columns={
                        c: f"{c}, млн руб."
                        for c in summary_hist.columns
                        if c != "project name"
                    }
                )

                # st.table(style_dataframe_for_dark_theme(summary_hist))
                _render_format_dataframe_html(
                    summary_hist,
                    file_stem="budget_summary",
                    key_prefix="budget_summary",
                )
        else:
            st.warning(
                "Колонка 'project name' не найдена в данных для построения гистограммы."
            )


# ==================== DASHBOARD 8.1: Budget Old Charts ====================
def dashboard_budget_old_charts(df):

    with filters_panel(st, reset_keys=["budget_old_period", "budget_old_project", "budget_old_section"]):
        col1, col2, col3 = st.columns(3, gap="small")

        with col1:
            period_type = st.selectbox(
                "Группировать по", ["Месяц", "Квартал", "Год"], key="budget_old_period"
            )
            period_map = {"Месяц": "Month", "Квартал": "Quarter", "Год": "Year"}
            period_type_en = period_map.get(period_type, "Month")

        with col2:
            if "project name" in df.columns:
                projects = ["Все"] + _project_name_select_options(df["project name"])
                selected_project = st.selectbox(
                    "Проект", projects, key="budget_old_project"
                )
            else:
                selected_project = "Все"

        with col3:
            if "section" in df.columns:
                sections = ["Все"] + sorted(df["section"].dropna().unique().tolist())
                selected_section = st.selectbox(
                    "Этап", sections, key="budget_old_section"
                )
            else:
                selected_section = "Все"

    # Apply filters
    filtered_df = df.copy()
    if selected_project != "Все" and "project name" in filtered_df.columns:
        filtered_df = _deviations_filter_df_by_project_name(filtered_df, selected_project)
    if selected_section != "Все" and "section" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["section"].astype(str).str.strip()
            == str(selected_section).strip()
        ]
    # Check for budget columns (нормализуем русские названия)
    ensure_budget_columns(filtered_df)
    has_budget = (
        "budget plan" in filtered_df.columns and "budget fact" in filtered_df.columns
    )

    if not has_budget:
        st.warning("Столбцы бюджета (budget plan, budget fact) не найдены в данных.")
        return

    # Determine period column
    if period_type_en == "Month":
        period_col = "plan_month"
        period_label = "Месяц"
    elif period_type_en == "Quarter":
        period_col = "plan_quarter"
        period_label = "Квартал"
    else:
        period_col = "plan_year"
        period_label = "Год"

    if period_col not in filtered_df.columns:
        st.warning(f"Столбец периода '{period_col}' не найден.")
        return

    # Отклонение = план − факт; отрицательное — красный, положительное — зелёный.
    filtered_df["budget plan"] = pd.to_numeric(
        filtered_df["budget plan"], errors="coerce"
    )
    filtered_df["budget fact"] = pd.to_numeric(
        filtered_df["budget fact"], errors="coerce"
    )
    filtered_df["reserve budget"] = (
        filtered_df["budget plan"] - filtered_df["budget fact"]
    )

    # Group by period first to get totals
    budget_by_period = (
        filtered_df.groupby(period_col)
        .agg({"budget plan": "sum", "budget fact": "sum", "reserve budget": "sum"})
        .reset_index()
    )

    budget_by_period[period_col] = budget_by_period[period_col].apply(
        format_period_ru
    )

    # Checkbox to hide/show deviation (default: hidden)
    hide_reserve = st.checkbox(
        "Скрыть отклонение", value=True, key="budget_old_hide_reserve"
    )

    # Transform data to long format - group by budget type
    budget_melted = []
    for idx, row in budget_by_period.iterrows():
        period = row[period_col]
        budget_melted.append(
            {
                period_col: period,
                "Тип бюджета": "Бюджет План",
                "Сумма": row["budget plan"],
            }
        )
        budget_melted.append(
            {
                period_col: period,
                "Тип бюджета": "Бюджет Факт",
                "Сумма": row["budget fact"],
            }
        )
        # Add deviation only if not hidden (split by sign for red/green)
        if not hide_reserve:
            if row["reserve budget"] >= 0:
                budget_melted.append(
                    {
                        period_col: period,
                        "Тип бюджета": "Отклонение (перерасход)",
                        "Сумма": row["reserve budget"],
                    }
                )
            else:
                budget_melted.append(
                    {
                        period_col: period,
                        "Тип бюджета": "Отклонение (экономия)",
                        "Сумма": row["reserve budget"],
                    }
                )

    budget_by_type_df = pd.DataFrame(budget_melted)
    # Суммы в млн руб. (исходные в рублях)
    budget_by_type_df["Сумма"] = (budget_by_type_df["Сумма"] / 1e6).round(2)

    # Visualizations
    col1, col2 = st.columns(2, gap="small")

    with col1:
        # Stacked area chart showing all budget types
        fig = px.area(
            budget_by_type_df,
            x=period_col,
            y="Сумма",
            color="Тип бюджета",
            title=None,
            labels={period_col: period_label, "Сумма": "Сумма, млн руб."},
            text="Сумма",
            color_discrete_map={
                "Бюджет План": "#2E86AB",
                "Бюджет Факт": "#A23B72",
                "Отклонение (перерасход)": "#e74c3c",
                "Отклонение (экономия)": "#27ae60",
            },
        )
        fig.update_xaxes(tickangle=-45)
        fig.update_traces(textposition="top center")
        fig = apply_chart_background(fig)
        render_chart(fig, caption_below=report_chart_caption_body("Бюджет по типам", cumulative=True))

    with col2:
        # Grouped bar chart
        fig = px.bar(
            budget_by_type_df,
            x=period_col,
            y="Сумма",
            color="Тип бюджета",
            title=None,
            labels={period_col: period_label, "Сумма": "Сумма, млн руб."},
            barmode="group",
            text="Сумма",
            color_discrete_map={
                "Бюджет План": "#2E86AB",
                "Бюджет Факт": "#A23B72",
                "Отклонение (перерасход)": "#e74c3c",
                "Отклонение (экономия)": "#27ae60",
            },
        )
        fig.update_xaxes(tickangle=-45)
        fig.update_traces(textposition="outside", textfont=dict(size=14, color="white"))
        fig = _apply_finance_bar_label_layout(fig)
        fig = apply_chart_background(fig)
        render_chart(fig, caption_below=report_chart_caption_body("Бюджет по типам", "Месяц"))

    # Line chart comparing all types
    fig = px.line(
        budget_by_type_df,
        x=period_col,
        y="Сумма",
        color="Тип бюджета",
        title=None,
        labels={period_col: period_label, "Сумма": "Сумма, млн руб."},
        markers=True,
        text="Сумма",
        color_discrete_map={
            "Бюджет План": "#2E86AB",
            "Бюджет Факт": "#A23B72",
            "Отклонение (перерасход)": "#e74c3c",
            "Отклонение (экономия)": "#27ae60",
        },
    )
    fig.update_xaxes(tickangle=-45)
    fig.update_traces(textposition="top center")
    fig = apply_chart_background(fig)
    render_chart(fig, caption_below=report_chart_caption_body("Сравнение типов бюджета", "Месяц"))

    # Summary metrics (суммы уже в млн руб.)
    col1, col2, col3, col4 = st.columns(4, gap="small")
    with col1:
        total_plan = budget_by_type_df[
            budget_by_type_df["Тип бюджета"] == "Бюджет План"
        ]["Сумма"].sum()
        st.metric("Всего План", f"{total_plan:.2f} млн руб." if pd.notna(total_plan) else "Н/Д")
    with col2:
        total_fact = budget_by_type_df[
            budget_by_type_df["Тип бюджета"] == "Бюджет Факт"
        ]["Сумма"].sum()
        st.metric("Всего Факт", f"{total_fact:.2f} млн руб." if pd.notna(total_fact) else "Н/Д")
    with col3:
        total_dev = (
            budget_by_type_df[
                budget_by_type_df["Тип бюджета"].isin(
                    ["Отклонение (перерасход)", "Отклонение (экономия)"]
                )
            ]["Сумма"].sum()
            if budget_by_type_df["Тип бюджета"].isin(
                ["Отклонение (перерасход)", "Отклонение (экономия)"]
            ).any()
            else 0
        )
        st.metric(
            "Всего Отклонение",
            f"{total_dev:.2f} млн руб." if pd.notna(total_dev) else "Н/Д",
        )
    with col4:
        variance = (
            total_plan - total_fact
            if pd.notna(total_plan) and pd.notna(total_fact)
            else None
        )
        st.metric(
            "Отклонение",
            (
                f"{variance:.2f} млн руб."
                if variance is not None and pd.notna(variance)
                else "Н/Д"
            ),
        )

    # Pivot table for better readability (Сумма уже в млн — budget_by_type_df["Сумма"] = /1e6)
    pivot_table = budget_by_type_df.pivot(
        index=period_col, columns="Тип бюджета", values="Сумма"
    ).fillna(0)

    # Detailed table — суммы в млн руб., два знака, подпись "млн руб." в названии колонки
    render_table_subheader(st, "Детальная таблица прогнозного бюджета")
    detailed_table = pivot_table.copy()

    # Названия колонок с подписью "млн руб."
    detailed_table = detailed_table.rename(
        columns={c: f"{c}, млн руб." for c in detailed_table.columns}
    )
    # Формат: два знака после запятой
    for col in detailed_table.columns:
        detailed_table[col] = detailed_table[col].apply(
            lambda x: f"{float(x):.2f}" if pd.notna(x) else "0.00"
        )

    st.table(style_dataframe_for_dark_theme(detailed_table))


# ── БДДС прогноз: распределение по месяцам (ТЗ PDF: равномерно или % A/B/C) ──


def _bdds_month_periods_inclusive(start, end):
    """Календарные месяцы от месяца даты «Начало» до месяца «Окончание» включительно."""
    ts = _forecast_parse_editor_date(start)
    te = _forecast_parse_editor_date(end)
    if pd.isna(ts) or pd.isna(te) or ts > te:
        return []
    cur = pd.Timestamp(ts.year, ts.month, 1)
    end_m = pd.Timestamp(te.year, te.month, 1)
    out = []
    while cur <= end_m:
        out.append(cur.to_period("M"))
        if cur.month == 12:
            cur = pd.Timestamp(cur.year + 1, 1, 1)
        else:
            cur = pd.Timestamp(cur.year, cur.month + 1, 1)
    return out


def _bdds_abc_sum(a, b, c) -> float:
    try:
        return float(a) + float(b) + float(c)
    except (TypeError, ValueError):
        return float("nan")


def _bdds_abc_is_valid(a, b, c, *, tol: float = 0.01) -> bool:
    """A+B+C должна быть ровно 100% (допуск tol — только погрешность ввода)."""
    s = _bdds_abc_sum(a, b, c)
    return bool(np.isfinite(s)) and abs(s - 100.0) <= float(tol)


def _bdds_parse_abc(a, b, c, *, tol: float = 0.01):
    """Возвращает (a, b, c) только если сумма = 100%; иначе None."""
    if not _bdds_abc_is_valid(a, b, c, tol=tol):
        return None
    try:
        return float(a), float(b), float(c)
    except (TypeError, ValueError):
        return None


def _bdds_distribute_row_uniform(total: float, start, end) -> dict:
    """Равномерно по всем месяцам периода [Начало; Окончание]."""
    months = _bdds_month_periods_inclusive(start, end)
    if not months or total is None or (isinstance(total, float) and pd.isna(total)):
        return {}
    t = float(total)
    if t == 0:
        return {m: 0.0 for m in months}
    per = t / len(months)
    return {m: per for m in months}


def _bdds_build_monthly_summary_from_msp(
    work_df: pd.DataFrame,
    *,
    period_col: str = "plan_month",
) -> pd.DataFrame:
    """
    Сводка БДДС по месяцам из MSP: plan/fact каждой строки равномерно
    по месяцам между plan start и plan end (как прогнозный БДДС).
    """
    if work_df is None or work_df.empty or "project name" not in work_df.columns:
        return pd.DataFrame()
    if "plan start" not in work_df.columns or "plan end" not in work_df.columns:
        return pd.DataFrame()
    ws = work_df.copy()
    ensure_budget_columns(ws)
    ws["plan start"] = ws["plan start"].map(_forecast_parse_editor_date)
    ws["plan end"] = ws["plan end"].map(_forecast_parse_editor_date)
    ws["budget plan"] = pd.to_numeric(ws["budget plan"], errors="coerce").fillna(0.0)
    ws["budget fact"] = pd.to_numeric(ws.get("budget fact", 0), errors="coerce").fillna(0.0)
    buckets: dict[tuple[str, pd.Period], dict[str, float]] = {}
    for _, row in ws.iterrows():
        proj = str(row.get("project name", "") or "")
        if not proj:
            continue
        ps, pe = row["plan start"], row["plan end"]
        if pd.isna(ps) or pd.isna(pe):
            continue
        plan_amt = float(row["budget plan"])
        fact_amt = float(row["budget fact"])
        if abs(plan_amt) < 1e-9 and abs(fact_amt) < 1e-9:
            continue
        for m, v in _bdds_distribute_row_uniform(plan_amt, ps, pe).items():
            key = (proj, m)
            buckets.setdefault(key, {"budget plan": 0.0, "budget fact": 0.0})
            buckets[key]["budget plan"] += float(v)
        for m, v in _bdds_distribute_row_uniform(fact_amt, ps, pe).items():
            key = (proj, m)
            buckets.setdefault(key, {"budget plan": 0.0, "budget fact": 0.0})
            buckets[key]["budget fact"] += float(v)
    if not buckets:
        return pd.DataFrame()
    out_rows: list[dict] = []
    for (proj, month), vals in buckets.items():
        plan_v = float(vals["budget plan"])
        fact_v = float(vals["budget fact"])
        try:
            pe_ts = month.to_timestamp(how="end")
        except Exception:
            continue
        out_rows.append(
            {
                "project name": proj,
                period_col: month,
                "plan end": pe_ts,
                "budget plan": plan_v,
                "budget fact": fact_v,
                "reserve budget": fact_v - plan_v,
            }
        )
    return pd.DataFrame(out_rows)


def _bdds_distribute_row_abc(total: float, start, end, a, b, c) -> dict:
    """
    % A — в месяце даты «Начало»; % C — в месяце «Окончание»;
    % B — равномерно по месяцам строго между ними; если таких нет — B делится пополам между первым и последним.
    """
    months = _bdds_month_periods_inclusive(start, end)
    if not months or total is None or (isinstance(total, float) and pd.isna(total)):
        return {}
    t = float(total)
    if t == 0:
        return {m: 0.0 for m in months}
    parsed = _bdds_parse_abc(a, b, c)
    if parsed is None:
        return {}
    ap, bp, cp = parsed
    ms, me = months[0], months[-1]
    out = {m: 0.0 for m in months}
    out[ms] += t * (ap / 100.0)
    out[me] += t * (cp / 100.0)
    mid_total = t * (bp / 100.0)
    interior = [m for m in months if m > ms and m < me]
    if interior:
        share = mid_total / len(interior)
        for m in interior:
            out[m] += share
    else:
        if len(months) == 1:
            out[ms] += mid_total
        else:
            out[ms] += mid_total / 2.0
            out[me] += mid_total / 2.0
    return out


def _bdds_distribute_row_abc_components(total: float, start, end, a, b, c):
    """
    Те же правила, что и _bdds_distribute_row_abc, но три словаря: доли A, B и C по месяцам (руб.).
    """
    months = _bdds_month_periods_inclusive(start, end)
    if not months or total is None or (isinstance(total, float) and pd.isna(total)):
        return {}, {}, {}
    t = float(total)
    if t == 0:
        z = {m: 0.0 for m in months}
        return z.copy(), z.copy(), z.copy()
    parsed = _bdds_parse_abc(a, b, c)
    if parsed is None:
        return {}, {}, {}
    ap, bp, cp = parsed
    ms, me = months[0], months[-1]
    da = {m: 0.0 for m in months}
    db = {m: 0.0 for m in months}
    dc = {m: 0.0 for m in months}
    da[ms] += t * (ap / 100.0)
    dc[me] += t * (cp / 100.0)
    mid_total = t * (bp / 100.0)
    interior = [m for m in months if m > ms and m < me]
    if interior:
        share = mid_total / len(interior)
        for m in interior:
            db[m] += share
    else:
        if len(months) == 1:
            db[ms] += mid_total
        else:
            db[ms] += mid_total / 2.0
            db[me] += mid_total / 2.0
    return da, db, dc


def _bdds_msp_monthly_plan_activity(work_df: pd.DataFrame) -> dict:
    """
    По каждому месяцу — сумма «БДДС план» по строкам, активным в этом месяце (как сводка MSP по пересечению).
    """
    if work_df is None or work_df.empty:
        return {}
    ws = work_df.copy()
    if "plan start" not in ws.columns or "plan end" not in ws.columns or "budget plan" not in ws.columns:
        return {}
    ws["plan start"] = ws["plan start"].map(_forecast_parse_editor_date)
    ws["plan end"] = ws["plan end"].map(_forecast_parse_editor_date)
    ws["budget plan"] = pd.to_numeric(ws["budget plan"], errors="coerce").fillna(0.0)
    all_months = set()
    for _, r in ws.iterrows():
        for m in _bdds_month_periods_inclusive(r["plan start"], r["plan end"]):
            all_months.add(m)
    monthly = {m: 0.0 for m in sorted(all_months)}
    for m in monthly:
        m_start = m.start_time
        m_end = m.end_time
        active = ws[(ws["plan start"] <= m_end) & (ws["plan end"] >= m_start)]
        monthly[m] = float(active["budget plan"].sum())
    return monthly


def compute_bddcs_forecast_monthly(
    work_df: pd.DataFrame,
    distribution_mode: str = "uniform",
    abc_source=None,
    row_modes: Optional[pd.Series] = None,
):
    """
    Возвращает DataFrame: month, bdds_plan_msp, bdds_forecast, bdds_fact;
    БДДС план/факт по месяцам — равномерно по периоду MSP; прогноз — по условию строки (равномерно или % A/B/C).
    abc_source: DataFrame с колонками A %, B %, C % (или A_, B_, C_) той же длины, что work_df; иначе 34/33/33.
    row_modes: опционально — для каждой строки «Равномерно» или «% …» (если задано, перекрывает distribution_mode).
    """
    if work_df is None or work_df.empty:
        return pd.DataFrame(), "Нет данных для расчёта прогноза БДДС"
    df = work_df.copy().reset_index(drop=True)
    if abc_source is not None:
        abc_source = abc_source.reset_index(drop=True)
    if row_modes is not None:
        row_modes = row_modes.reset_index(drop=True)
    ensure_budget_columns(df)
    req = ["budget plan", "plan start", "plan end"]
    miss = [c for c in req if c not in df.columns]
    if miss:
        return pd.DataFrame(), f"Отсутствуют колонки: {', '.join(miss)}"
    df["plan start"] = df["plan start"].map(_forecast_parse_editor_date)
    df["plan end"] = df["plan end"].map(_forecast_parse_editor_date)
    df["budget plan"] = pd.to_numeric(df["budget plan"], errors="coerce").fillna(0.0)
    if "budget fact" in df.columns:
        df["budget fact"] = pd.to_numeric(df["budget fact"], errors="coerce").fillna(0.0)
    else:
        df["budget fact"] = 0.0

    mode = (distribution_mode or "uniform").strip().lower()
    use_abc_default = mode in ("abc", "%", "процент", "a/b/c", "a b c")

    def _row_use_abc(pos: int) -> bool:
        if row_modes is None or len(row_modes) <= pos:
            return use_abc_default
        rm = str(row_modes.iloc[pos]).strip()
        sl = rm.casefold()
        if not rm:
            return use_abc_default
        if sl.startswith("%") or "a/b/c" in sl or "распредел" in sl:
            return True
        if "равном" in sl:
            return False
        return use_abc_default

    fc_totals: dict = {}
    plan_totals: dict = {}
    fact_totals: dict = {}
    abc_errors: list[str] = []

    for pos in range(len(df)):
        r = df.iloc[pos]
        plan_amt = float(r["budget plan"])
        fact_amt = float(r["budget fact"])
        use_abc_row = _row_use_abc(pos)
        a, b, c = 34.0, 33.0, 33.0
        if use_abc_row and abc_source is not None and len(abc_source) > 0:
            row_abc = abc_source.iloc[min(pos, len(abc_source) - 1)]
            for ca, cb, cc in (
                ("A %", "B %", "C %"),
                ("A, %", "B, %", "C, %"),
                ("A_", "B_", "C_"),
            ):
                if ca in row_abc.index and cb in row_abc.index and cc in row_abc.index:
                    a = row_abc[ca]
                    b = row_abc[cb]
                    c = row_abc[cc]
                    break

        ps, pe = r["plan start"], r["plan end"]
        for m, v in _bdds_distribute_row_uniform(plan_amt, ps, pe).items():
            plan_totals[m] = plan_totals.get(m, 0.0) + float(v)
        for m, v in _bdds_distribute_row_uniform(fact_amt, ps, pe).items():
            fact_totals[m] = fact_totals.get(m, 0.0) + float(v)

        if use_abc_row:
            if not _bdds_abc_is_valid(a, b, c):
                lot = str(r.get("section", r.get("task name", "")) or "").strip() or f"строка {pos + 1}"
                abc_errors.append(f"{lot}: A+B+C={_bdds_abc_sum(a, b, c):.2f}% (нужно 100%)")
                # Не теряем прогноз: пока доли невалидны — считаем равномерно.
                dp = _bdds_distribute_row_uniform(plan_amt, ps, pe)
            else:
                dp = _bdds_distribute_row_abc(plan_amt, ps, pe, a, b, c)
        else:
            dp = _bdds_distribute_row_uniform(plan_amt, ps, pe)
        for m, v in dp.items():
            fc_totals[m] = fc_totals.get(m, 0.0) + float(v)

    _abc_warn = None
    if abc_errors:
        _abc_warn = "Исправьте доли A/B/C (сумма ровно 100%): " + "; ".join(abc_errors[:8])

    all_m = sorted(set(plan_totals.keys()) | set(fc_totals.keys()) | set(fact_totals.keys()))
    if not all_m:
        return pd.DataFrame(), "Нет валидных периодов для распределения БДДС"

    rows = []
    for m in all_m:
        row_out = {
            "month": m,
            "bdds_plan_msp": float(plan_totals.get(m, 0.0)),
            "bdds_forecast": float(fc_totals.get(m, 0.0)),
            "bdds_fact": float(fact_totals.get(m, 0.0)),
        }
        rows.append(row_out)
    out = pd.DataFrame(rows).sort_values("month").reset_index(drop=True)
    if out.empty and _abc_warn:
        return out, _abc_warn
    return out, _abc_warn


def _forecast_per_lot_distribution_totals(
    work_df: pd.DataFrame,
    *,
    abc_source=None,
    row_modes: Optional[pd.Series] = None,
    distribution_mode: str = "uniform",
    only_month=None,
) -> pd.DataFrame:
    """По каждой строке лота: суммы план/факт и распределённый БДДС прогноз (руб. → млн в таблице).

    only_month=None — прогноз за весь срок лота (итог). Если передан период (pd.Period месяца
    или значение, приводимое к нему), в колонку прогноза попадает только доля этого месяца —
    тогда видно, как условие распределения (равномерно / % A/B/C) меняет прогноз в этом месяце.
    """
    if work_df is None or getattr(work_df, "empty", True):
        return pd.DataFrame()
    df = work_df.copy().reset_index(drop=True)
    abc_src = abc_source.reset_index(drop=True) if abc_source is not None else None
    rm = row_modes.reset_index(drop=True) if row_modes is not None else None
    _only_mp = _forecast_norm_month_period(only_month) if only_month is not None else None
    if isinstance(_only_mp, float) and pd.isna(_only_mp):
        _only_mp = None

    mode = (distribution_mode or "uniform").strip().lower()
    use_abc_default = mode in ("abc", "%", "процент", "a/b/c", "a b c")

    def _row_use_abc(pos: int) -> bool:
        if rm is None or len(rm) <= pos:
            return use_abc_default
        row_m = str(rm.iloc[pos]).strip()
        sl = row_m.casefold()
        if not row_m:
            return use_abc_default
        if sl.startswith("%") or "a/b/c" in sl or "распредел" in sl:
            return True
        if "равном" in sl:
            return False
        return use_abc_default

    def _fmt_d(ts) -> str:
        if ts is None or (isinstance(ts, float) and pd.isna(ts)):
            return ""
        try:
            tt = pd.Timestamp(ts)
            return "" if pd.isna(tt) else tt.strftime("%d.%m.%Y")
        except Exception:
            return ""

    rows_out: List[dict] = []
    for pos in range(len(df)):
        r = df.iloc[pos]
        ps = _forecast_parse_editor_date(r.get("plan start"))
        pe = _forecast_parse_editor_date(r.get("plan end"))
        plan_amt = float(pd.to_numeric(r.get("budget plan"), errors="coerce") or 0.0)
        fact_amt = float(pd.to_numeric(r.get("budget fact"), errors="coerce") or 0.0)
        lot = _forecast_row_lot_label(r)

        use_abc_row = _row_use_abc(pos)
        a, b, c = 34.0, 33.0, 33.0
        if use_abc_row and abc_src is not None and len(abc_src) > 0:
            row_abc = abc_src.iloc[min(pos, len(abc_src) - 1)]
            for ca, cb, cc in (
                ("A %", "B %", "C %"),
                ("A, %", "B, %", "C, %"),
                ("A_", "B_", "C_"),
            ):
                if ca in row_abc.index and cb in row_abc.index and cc in row_abc.index:
                    a = row_abc[ca]
                    b = row_abc[cb]
                    c = row_abc[cc]
                    break

        if use_abc_row:
            dp = _bdds_distribute_row_abc(plan_amt, ps, pe, a, b, c)
        else:
            dp = _bdds_distribute_row_uniform(plan_amt, ps, pe)

        if not dp:
            fc_sum = 0.0
        elif _only_mp is not None:
            fc_sum = float(
                sum(v for m, v in dp.items() if _forecast_norm_month_period(m) == _only_mp)
            )
        else:
            fc_sum = float(sum(dp.values()))

        rows_out.append(
            {
                "Лот": lot,
                "План. начало": _fmt_d(ps),
                "План. окончание": _fmt_d(pe),
                "БДДС план (утверждённый), млн руб.": round(plan_amt / 1e6, 4),
                "БДДС факт, млн руб.": round(fact_amt / 1e6, 4),
                "БДДС прогноз (итого), млн руб.": round(fc_sum / 1e6, 4),
                "Отклонение (план − прогноз), млн руб.": round((plan_amt - fc_sum) / 1e6, 4),
            }
        )

    return pd.DataFrame(rows_out)


def _forecast_lot_oldnew_month_options(
    work_df: pd.DataFrame,
    *,
    abc_source=None,
    row_modes: Optional[pd.Series] = None,
) -> list:
    """Месяцы (pd.Period, freq=M) с ненулевым прогнозом — для выбора периода в таблице «было → стало»."""
    mdf, _err = compute_bddcs_forecast_monthly(
        work_df,
        distribution_mode="uniform",
        abc_source=abc_source,
        row_modes=row_modes,
    )
    if mdf is None or getattr(mdf, "empty", True):
        return []
    out: set = set()
    for _, r in mdf.iterrows():
        try:
            if float(r.get("bdds_forecast", 0.0) or 0.0) <= 0.0:
                continue
        except (TypeError, ValueError):
            continue
        mp = _forecast_norm_month_period(r["month"])
        if mp is None or (isinstance(mp, float) and pd.isna(mp)):
            continue
        out.add(mp)
    return sorted(out, key=lambda x: str(x))


# ==================== DASHBOARD: Approved Budget ====================
def calculate_approved_budget(df, rule_name="default"):
    """
    Рассчитывает утвержденный бюджет на основе правил распределения.

    Логика расчета:
    1. Группируем задачи по проекту/разделу/задаче
    2. Для каждой группы находим все месяцы этапа (от минимальной даты начала до максимальной даты окончания)
    3. Для каждого месяца находим все задачи, активные в этом месяце
    4. Суммируем плановый бюджет активных задач - это 100% для месяца
    5. Распределяем эту сумму по правилу между месяцами этапа

    Правила распределения:
    - default: 50% - первый месяц, 45% - равномерно по промежуточным месяцам, 5% - последний месяц

    Args:
        df: DataFrame с данными проектов
        rule_name: название правила из справочника

    Returns:
        DataFrame с распределением утвержденного бюджета по месяцам
    """
    # Справочник правил распределения бюджета
    budget_rules = {
        "default": {
            "first_month_percent": 0.50,  # 50% на первый месяц
            "middle_months_percent": 0.45,  # 45% на промежуточные месяцы
            "last_month_percent": 0.05,  # 5% на последний месяц
            "description": "50% - первый месяц, 45% - равномерно по промежуточным месяцам, 5% - последний месяц",
        }
    }

    # Получаем правило
    if rule_name not in budget_rules:
        rule_name = "default"
    rule = budget_rules[rule_name]

    # Проверяем наличие необходимых колонок
    required_cols = ["budget plan", "plan start", "plan end"]
    missing_cols = [col for col in required_cols if col not in df.columns]
    if missing_cols:
        return (
            pd.DataFrame(),
            f"Отсутствуют необходимые колонки: {', '.join(missing_cols)}",
        )

    # Копируем данные для работы
    work_df = df.copy()

    # Конвертируем даты
    work_df["plan start"] = pd.to_datetime(
        work_df["plan start"], errors="coerce", dayfirst=True
    )
    work_df["plan end"] = pd.to_datetime(
        work_df["plan end"], errors="coerce", dayfirst=True
    )
    work_df["budget plan"] = pd.to_numeric(work_df["budget plan"], errors="coerce")

    # Фильтруем строки с валидными данными
    valid_mask = (
        work_df["plan start"].notna()
        & work_df["plan end"].notna()
        & work_df["budget plan"].notna()
        & (work_df["budget plan"] > 0)
        & (work_df["plan start"] <= work_df["plan end"])
    )
    work_df = work_df[valid_mask].copy()

    if work_df.empty:
        return pd.DataFrame(), "Нет данных с валидными датами и бюджетом"

    # Определяем группировку: группируем по комбинации project + section + task
    # Это позволяет правильно обрабатывать случаи, когда выбраны разные уровни фильтрации
    grouping_cols = []
    if "project name" in work_df.columns:
        grouping_cols.append("project name")
    if "section" in work_df.columns:
        grouping_cols.append("section")
    if "task name" in work_df.columns:
        grouping_cols.append("task name")

    # Если нет колонок для группировки, обрабатываем все задачи вместе
    if not grouping_cols:
        # Создаем фиктивную группу для всех задач
        work_df["_group"] = "all"
        grouping_cols = ["_group"]

    # Список для хранения результатов
    approved_budget_rows = []

    # Группируем задачи
    if grouping_cols:
        grouped = work_df.groupby(grouping_cols)
    else:
        # Если нет колонок для группировки, создаем одну группу
        grouped = [("all", work_df)]

    for group_key, group_df in grouped:
        # Находим минимальную дату начала и максимальную дату окончания для группы
        min_start = group_df["plan start"].min()
        max_end = group_df["plan end"].max()

        if pd.isna(min_start) or pd.isna(max_end):
            continue

        # Генерируем все месяцы этапа
        current_date = min_start.replace(day=1)
        end_month = max_end.replace(day=1)

        months = []
        while current_date <= end_month:
            months.append(current_date.to_period("M"))
            # Переходим к следующему месяцу
            if current_date.month == 12:
                current_date = current_date.replace(year=current_date.year + 1, month=1)
            else:
                current_date = current_date.replace(month=current_date.month + 1)

        if len(months) == 0:
            continue

        # Для каждого месяца находим активные задачи и суммируем их плановый бюджет
        monthly_budgets = {}
        for month in months:
            month_start = month.start_time
            month_end = month.end_time

            # Находим задачи, активные в этом месяце
            active_tasks = group_df[
                (group_df["plan start"] <= month_end)
                & (group_df["plan end"] >= month_start)
            ]

            # Суммируем плановый бюджет активных задач - это 100% для месяца
            total_budget = active_tasks["budget plan"].sum()
            monthly_budgets[month] = total_budget

        # Рассчитываем распределение бюджета по правилу
        num_months = len(months)

        if num_months == 1:
            # Если только один месяц, весь бюджет идет туда
            first_month_percent = 1.0
            middle_months_percent = 0.0
            last_month_percent = 0.0
        elif num_months == 2:
            # Если два месяца: 50% на первый, 50% на последний
            first_month_percent = rule["first_month_percent"]
            middle_months_percent = 0.0
            last_month_percent = (
                rule["middle_months_percent"] + rule["last_month_percent"]
            )
        else:
            # Если больше двух месяцев: 50% на первый, 45% равномерно на промежуточные, 5% на последний
            first_month_percent = rule["first_month_percent"]
            last_month_percent = rule["last_month_percent"]
            middle_months_percent = rule["middle_months_percent"] / (num_months - 2)

        # Распределяем бюджет по месяцам
        for i, month in enumerate(months):
            # Берем бюджет для этого месяца (100%)
            month_total_budget = monthly_budgets.get(month, 0)

            if month_total_budget == 0:
                continue

            # Определяем процент для этого месяца
            if i == 0:
                # Первый месяц
                month_percent = first_month_percent
            elif i == len(months) - 1:
                # Последний месяц
                month_percent = last_month_percent
            else:
                # Промежуточные месяцы
                month_percent = middle_months_percent

            # Рассчитываем утвержденный бюджет для месяца
            approved_budget = month_total_budget * month_percent

            # Получаем значения группировки
            group_dict = {}
            if grouping_cols:
                if isinstance(group_key, tuple):
                    group_dict = dict(zip(grouping_cols, group_key))
                elif len(grouping_cols) == 1:
                    group_dict = {grouping_cols[0]: group_key}
                else:
                    # Если group_key не кортеж и колонок несколько, возможно это одна группа
                    for col in grouping_cols:
                        if col in group_df.columns:
                            # Берем первое значение из группы
                            group_dict[col] = (
                                group_df[col].iloc[0] if len(group_df) > 0 else ""
                            )

            # Создаем строку с данными
            approved_row = {
                "month": month,
                "approved budget": approved_budget,
                "budget plan": month_total_budget,  # Плановый бюджет для месяца (100%)
                "rule_name": rule_name,
            }

            # Добавляем значения группировки (исключаем фиктивную колонку _group)
            for col in grouping_cols:
                if col != "_group":
                    approved_row[col] = group_dict.get(col, "")

            approved_budget_rows.append(approved_row)

    # Создаем DataFrame из результатов
    if not approved_budget_rows:
        return pd.DataFrame(), "Нет данных для расчета утвержденного бюджета"

    approved_budget_df = pd.DataFrame(approved_budget_rows)

    return approved_budget_df, None


def dashboard_approved_budget(df):
    """Панель для отображения утвержденного бюджета"""
    from dashboards.finance_from_1c import ensure_budget_frame_with_fallback

    df = df.copy()
    ensure_budget_columns(df)
    df, _approved_budget_used_1c = ensure_budget_frame_with_fallback(df, show_caption=True)
    ensure_budget_columns(df)
    ensure_date_columns(df)

    with filters_panel(st, reset_keys=["approved_budget_project", "approved_budget_section"]):
        col1, col2 = st.columns(2, gap="small")

        with col1:
            project_col = None
            if "project name" in df.columns:
                project_col = "project name"
            elif "Проект" in df.columns:
                project_col = "Проект"

            if project_col:
                projects = ["Все"] + _unique_project_labels_for_select(df[project_col])
                selected_project = st.selectbox(
                    "Проект", projects, key="approved_budget_project"
                )
            else:
                st.warning("Колонка 'project name' не найдена.")
                selected_project = "Все"

        with col2:
            if "section" in df.columns:
                sections = ["Все"] + sorted(df["section"].dropna().unique().tolist())
                selected_section = st.selectbox(
                    "Этап", sections, key="approved_budget_section"
                )
            else:
                selected_section = "Все"

    # Применяем фильтры
    filtered_df = df.copy()
    if selected_project != "Все" and project_col and project_col in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df[project_col].map(_project_filter_norm_key)
            == _project_filter_norm_key(selected_project)
        ]
    if selected_section != "Все" and "section" in filtered_df.columns:
        filtered_df = filtered_df[
            filtered_df["section"].astype(str).str.strip()
            == str(selected_section).strip()
        ]

    if project_col and project_col in filtered_df.columns:
        filtered_df = _project_column_apply_canonical(filtered_df, project_col)

    ensure_budget_columns(filtered_df)
    from dashboards.data_quality_hints import collect_budget_1c_hints, render_quality_hints

    _approved_q_hints = collect_budget_1c_hints(
        dict(getattr(filtered_df, "attrs", {}) or {}),
        used_fallback_1c=bool(_approved_budget_used_1c),
    )
    _proj_key = project_col if project_col and project_col in filtered_df.columns else None
    if (
        _proj_key
        and "budget plan" in filtered_df.columns
        and "budget fact" in filtered_df.columns
    ):
        render_table_subheader(st, "Детальные данные утверждённого бюджета")
        suppress_caption(
            "По ТЗ: утверждённый бюджет и факт из оборотов; отклонение = план − факт "
            "(красный шрифт при отклонении < 0, зелёный при ≥ 0)."
        )
        _tz = (
            filtered_df.groupby(_proj_key)
            .agg({"budget plan": "sum", "budget fact": "sum"})
            .reset_index()
        )
        _tz["_dev"] = _tz["budget plan"] - _tz["budget fact"]
        _tz_out = pd.DataFrame(
            {
                "Проект": _tz[_proj_key].astype(str),
                "Утверждённый бюджет (план), млн руб.": (_tz["budget plan"] / 1e6).round(2).apply(
                    lambda x: f"{float(x):.2f}" if pd.notna(x) else ""
                ),
                "Фактические расходы, млн руб.": (_tz["budget fact"] / 1e6).round(2).apply(
                    lambda x: f"{float(x):.2f}" if pd.notna(x) else ""
                ),
                "Отклонение, млн руб.": (_tz["_dev"] / 1e6).round(2).apply(
                    lambda x: f"{float(x):.2f}" if pd.notna(x) else ""
                ),
            }
        )
        _render_budget_table_html(
                _tz_out,
                finance_deviation_column="Отклонение, млн руб.",
                deviation_red_if_negative=True,
            )
        render_quality_hints(_approved_q_hints)

    if "budget plan" in filtered_df.columns and "budget fact" in filtered_df.columns:
        _plan_tot = float(pd.to_numeric(filtered_df["budget plan"], errors="coerce").fillna(0.0).sum())
        _fact_tot = float(pd.to_numeric(filtered_df["budget fact"], errors="coerce").fillna(0.0).sum())
        render_table_subheader(st, "Сводка утверждённого бюджета план/факт")
        _pb = _plan_tot / 1e9
        _fb = _fact_tot / 1e9
        _hi = max(_pb, _fb, 1e-9) * 1.08
        if _plan_tot > 0:
            if _fact_tot > _plan_tot:
                _gauge_bar = "#e74c3c"
            elif _fact_tot >= 0.8 * _plan_tot:
                _gauge_bar = "#e67e22"
            else:
                _gauge_bar = "#27ae60"
        else:
            _gauge_bar = "#8892a0"
        _pct_of_plan = (100.0 * _fact_tot / _plan_tot) if _plan_tot > 0 else float("nan")
        _gauge_kw = {
            "axis": {"range": [0.0, float(_hi)]},
            "bar": {"color": _gauge_bar},
            "bgcolor": "rgba(26,28,35,0.85)",
            "borderwidth": 0,
        }
        if _pb > 0:
            _gauge_kw["threshold"] = {
                "line": {"color": "#2E86AB", "width": 3},
                "thickness": 0.82,
                "value": float(_pb),
            }
        _g = go.Figure(
            go.Indicator(
                mode="gauge+number",
                value=float(_fb),
                number={"suffix": " млрд", "valueformat": ".2f"},
                title={"text": "Расходы факт (к цели плана)"},
                gauge=_gauge_kw,
            )
        )
        _g = apply_chart_background(_g)
        _gc1, _gc2 = st.columns([1, 1], gap="medium")
        with _gc1:
            render_chart(
                _g,
                height=340,
                caption_below="",
                key=f"approved_budget_gauge_{_project_filter_norm_key(str(selected_project))}",
            )
        with _gc2:
            # R23-13.5: без серых пояснительных подписей под gauge — оставляем
            # только ключевые значения (план / факт в млн и млрд руб.).
            st.markdown("**Расходы план**")
            st.markdown(f"{_pb:.2f} млрд руб. ({_plan_tot/1e6:.2f} млн руб.)")
            st.markdown("**Расходы факт**")
            if _plan_tot > 0 and np.isfinite(_pct_of_plan):
                st.markdown(
                    f"{_fb:.2f} млрд руб. ({_fact_tot/1e6:.2f} млн руб.) — **{_pct_of_plan:.1f}%** от плана"
                )
            else:
                st.markdown(f"{_fb:.2f} млрд руб. ({_fact_tot/1e6:.2f} млн руб.)")
        render_quality_hints(_approved_q_hints)

    ensure_date_columns(filtered_df)
    if "plan end" in filtered_df.columns:
        plan_end = pd.to_datetime(filtered_df["plan end"], errors="coerce")
        mask = plan_end.notna()
        if mask.any() and "plan_month" not in filtered_df.columns:
            filtered_df.loc[mask, "plan_month"] = plan_end.loc[mask].dt.to_period("M")

    if "budget plan" not in filtered_df.columns or "budget fact" not in filtered_df.columns:
        st.warning("Нет колонок плана/факта бюджета для графика.")
        return

    if "plan_month" not in filtered_df.columns:
        st.info(
            "Для графика «план/факт по месяцам» нужна дата периода (например «Конец план» / plan end) в данных."
        )
        return

    render_table_subheader(
        st,
        report_title_name("утверждённого бюджета план/факт", "по месяцам"),
    )
    _appr_hide_zero = st.checkbox(
        "Скрывать месяцы, где план и факт равны 0",
        value=True,
        key="approved_budget_hide_zero_months",
    )
    monthly_rows = (
        filtered_df.groupby("plan_month")
        .agg({"budget plan": "sum", "budget fact": "sum"})
        .reset_index()
        .sort_values("plan_month")
    )
    if monthly_rows.empty:
        st.info("Нет строк с периодом для построения графика.")
        return

    monthly_rows["Месяц"] = monthly_rows["plan_month"].apply(format_period_ru)
    monthly_rows["reserve budget"] = monthly_rows["budget plan"] - monthly_rows["budget fact"]

    if _appr_hide_zero:
        _pl0 = monthly_rows["budget plan"].fillna(0.0)
        _fc0 = monthly_rows["budget fact"].fillna(0.0)
        monthly_rows = monthly_rows.loc[_pl0.abs() + _fc0.abs() > 0.5].copy()
    if monthly_rows.empty:
        st.info(
            "Нет месяцев с данными для графика. Снимите «Скрывать месяцы, где план и факт равны 0»."
        )
        return

    # Как на БДДС: план/факт — фиксированные цвета, без «светофора» (читаемость + единый стиль).
    fig = go.Figure()
    _n_m = len(monthly_rows)
    # Не дублировать «0.00 млн»; подписи — как в БДДС (min_abs_mln).
    _text_min_mln = 0.005
    _tf_size = 8 if _n_m > 32 else 9 if _n_m > 20 else 10 if _n_m > 12 else 11
    if _n_m > 32:
        _bg, _bgg = 0.04, 0.01
    elif _n_m > 18:
        _bg, _bgg = 0.06, 0.02
    else:
        _bg, _bgg = 0.1, 0.04

    _bar_label_color = _fin_chart_label_color()
    fig.add_trace(
        go.Bar(
            x=monthly_rows["Месяц"],
            y=monthly_rows["budget plan"].div(1e6),
            name="БДДС план",
            marker_color="#2E86AB",
            text=_finance_bar_text_mln_rub(
                monthly_rows["budget plan"], min_abs_mln=_text_min_mln
            ),
            textposition="outside",
            textfont=dict(size=_tf_size, color=_bar_label_color),
            cliponaxis=False,
            hovertemplate="<b>%{x}</b><br>БДДС план: %{customdata}<extra></extra>",
            customdata=monthly_rows["budget plan"].apply(format_million_rub),
        )
    )
    fig.add_trace(
        go.Bar(
            x=monthly_rows["Месяц"],
            y=monthly_rows["budget fact"].div(1e6),
            name="БДДС факт",
            marker_color="#A23B72",
            text=_finance_bar_text_mln_rub(
                monthly_rows["budget fact"], min_abs_mln=_text_min_mln
            ),
            textposition="outside",
            textfont=dict(size=_tf_size, color=_bar_label_color),
            cliponaxis=False,
            hovertemplate="<b>%{x}</b><br>БДДС факт: %{customdata}<extra></extra>",
            customdata=monthly_rows["budget fact"].apply(format_million_rub),
        )
    )
    _leg_b_pre = max(300, min(460, 280 + int(_n_m * 3.5)))
    _top_px_pre = 140
    _min_plot_core_px = 400
    _ch_base = 600 if _n_m <= 20 else int(min(1100, 520 + int(_n_m * 1.4)))
    _chart_h = max(_ch_base, _top_px_pre + _leg_b_pre + _min_plot_core_px)
    _chart_h = int(min(1400, _chart_h))
    fig.update_layout(
        title_text="",
        yaxis_title="млн. руб.",
        barmode="group",
        bargap=_bg,
        bargroupgap=_bgg,
        hovermode="x unified",
        height=_chart_h,
        xaxis=dict(title=dict(text="Месяц", standoff=30)),
    )
    fig = _apply_finance_bar_label_layout(fig)
    try:
        fig.update_layout(uniformtext=dict(minsize=1, mode="show"))
    except Exception:
        pass
    if not monthly_rows.empty:
        _ymax = float(
            np.nanmax(
                np.concatenate(
                    [
                        monthly_rows["budget plan"].div(1e6).to_numpy(),
                        monthly_rows["budget fact"].div(1e6).to_numpy(),
                    ]
                )
            )
        )
        if np.isfinite(_ymax) and _ymax > 0:
            fig.update_layout(yaxis=dict(range=[0, _ymax * 1.28]))
    fig = apply_chart_background(fig)
    _render_finance_bar_chart(
        fig,
        n_periods=_n_m,
        height=_chart_h,
        caption_below=(
            "Как в отчёте БДДС: план/факт по месяцам; нулевые/мелкие суммы — в подсказке. "
            "Скрытие пустых месяцев — как в БДДС, чтобы не сжимать столбцы."
        ),
        categories=monthly_rows["Месяц"].astype(str).tolist(),
        px_per_month=400,
        force_hscroll=True,
        n_bar_slots=2,
    )

    render_table_subheader(
        st,
        report_title_name("утверждённого бюджета", "по месяцам"),
    )
    summary_table = monthly_rows[
        ["Месяц", "budget plan", "budget fact", "reserve budget"]
    ].copy()
    for c in ("budget plan", "budget fact", "reserve budget"):
        summary_table[c] = (summary_table[c] / 1e6).round(2).apply(
            lambda x: f"{float(x):.2f}" if pd.notna(x) else ""
        )
    summary_table = summary_table.rename(
        columns={
            "budget plan": "БДДС план, млн руб.",
            "budget fact": "БДДС факт, млн руб.",
            "reserve budget": "Отклонение, млн руб.",
        }
    )
    _render_budget_table_html(
            summary_table,
            finance_deviation_column="Отклонение, млн руб.",
        )
    render_quality_hints(_approved_q_hints)


# ==================== DASHBOARD: Forecast Budget ====================
def calculate_forecast_budget(
    df,
    edited_data=None,
    distribution_mode="uniform",
    abc_source=None,
    row_modes: Optional[pd.Series] = None,
):
    """
    Прогноз БДДС по месяцам:
    - «БДДС план» / «БДДС факт» — всегда равномерно по месяцам срока лота;
    - «БДДС прогноз» — равномерно или % A/B/C (по условию строки / row_modes).
    """
    work_df = edited_data.copy() if edited_data is not None else df.copy()
    return compute_bddcs_forecast_monthly(
        work_df,
        distribution_mode=distribution_mode,
        abc_source=abc_source,
        row_modes=row_modes,
    )


def _forecast_find_turnover_dataframe():
    """Ищет в session_state DataFrame оборотов 1С (БДДС) по типичным ключам/колонкам."""
    try:
        d0 = st.session_state.get("reference_1c_dannye")
        if isinstance(d0, pd.DataFrame) and not getattr(d0, "empty", True):
            return d0
    except Exception:
        pass
    try:
        keys = list(st.session_state.keys())
    except Exception:
        keys = []
    preferred = (
        "budget_1c_data",
        "bddcs_1c",
        "bddcs_turnover",
        "project_budget_1c",
        "dannye_bddcs",
        "turnover_1c",
    )
    for k in preferred:
        if k in keys:
            d = st.session_state.get(k)
            if isinstance(d, pd.DataFrame) and not getattr(d, "empty", True):
                return d
    for k in keys:
        d = st.session_state.get(k)
        if not isinstance(d, pd.DataFrame) or getattr(d, "empty", True):
            continue
        joined = " ".join(str(c).casefold() for c in d.columns)
        if "сценар" in joined and ("сумм" in joined or "amount" in joined):
            if "стать" in joined or "article" in joined or "оборот" in joined:
                return d
    return None


def _forecast_is_lot_value(s) -> bool:
    """Признак «лота»: текст содержит «ЛОТ» либо начинается с числового обозначения (17.1, 01, 98 и т.п.)."""
    txt = _clean_display_str(s)
    if not txt:
        return False
    if "лот" in txt.casefold():
        return True
    return bool(re.match(r"^\s*\d", txt))


def _forecast_norm_lot_id(v) -> str:
    """Нормализация ID лота для сопоставления 1С ↔ MSP (регистр, хвост .0)."""
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return ""
    s = str(v).strip()
    if not s or s.casefold() in ("nan", "none", "<na>"):
        return ""
    if re.fullmatch(r"\d+\.0+", s):
        s = s.split(".", 1)[0]
    return s.casefold()


def _forecast_merge_bddcs_from_1c(project_df: pd.DataFrame, project_name: str) -> pd.DataFrame:
    """
    Подставляет суммы из оборотов 1С (БДДС):

    - **БДДС план**: сценарий «Бюджет»/«План», статья оборотов без «(БДР)».
    - **БДДС факт**: сценарий «Факт», те же ограничения по статье.
    - Учитываем только **лотовые статьи** оборотов (статья содержит «ЛОТ» или начинается с
      числового обозначения) и разносим суммы **по лоту** через ключ `ID_Лота` ↔ `ЛОТ_ID`.
      Сумма лота делится поровну между строками MSP этого лота (чтобы при агрегации по лоту
      получить исходный итог, а на уровне задач — корректные доли).
    - Фолбэк (нет лотовых сопоставлений): прежнее пропорциональное распределение по проекту.
    """
    bdf = _forecast_find_turnover_dataframe()
    if bdf is None or bdf.empty or project_df is None or project_df.empty:
        return project_df
    out = project_df.copy()

    def _col(df, needles):
        cols = {str(c).strip().casefold(): c for c in df.columns}
        for n in needles:
            k = str(n).strip().casefold()
            if k in cols:
                return cols[k]
        for c in df.columns:
            cl = str(c).casefold()
            for n in needles:
                if str(n).casefold() in cl:
                    return c
        return None

    scen = _col(bdf, ("Сценарий", "scenario"))
    art = _col(bdf, ("СтатьяОборотов", "Статья оборотов", "article"))
    amt = _col(bdf, ("Сумма", "amount"))
    proj = _col(bdf, ("Проект", "project"))
    typ = _col(bdf, ("ТипСтатьи", "article_type", "Тип статьи"))
    if not scen or not amt:
        return out

    t = bdf.copy()
    if proj:
        pn = _project_filter_norm_key(project_name)
        t["_pk"] = t[proj].map(_project_filter_norm_key)
        t = t[t["_pk"] == pn]
    if t.empty:
        return out

    def _no_bdr(row) -> bool:
        a = str(row.get(art, "") if art else "").casefold()
        if "(бдр)" in a or a.strip() == "бдр":
            return False
        if typ and typ in row.index:
            tl = str(row.get(typ, "")).casefold()
            if "бдр" in tl and "бддс" not in tl:
                return False
        return True

    t_base = t[t.apply(_no_bdr, axis=1)]
    if t_base.empty:
        return out

    t_bd = t_base
    if typ:
        _tls = t_base[typ].astype(str).str.casefold()
        _bdds_rows = _tls.str.contains("бддс", na=False)
        if bool(_bdds_rows.any()):
            t_bd = t_base.loc[_bdds_rows]
    if t_bd.empty:
        t_bd = t_base

    try:
        from dashboards.finance_from_1c import _amount_series_to_rubles
        amt_num = _amount_series_to_rubles(t_bd, amt)
    except Exception:
        amt_num = pd.to_numeric(t_bd[amt], errors="coerce").fillna(0.0)
    sser = t_bd[scen].astype(str)

    _norm_scen = sser.str.strip().str.casefold()
    budget_mask = sser.str.contains("бюджет", case=False, na=False) | sser.str.contains(
        "budget", case=False, na=False
    )
    plan_mask = budget_mask
    fact_mask = sser.str.contains("факт", case=False, na=False) | sser.str.contains(
        "fact", case=False, na=False
    ) | _norm_scen.eq("факт")

    if plan_mask.sum() == 0:
        legacy_plan_mask = (
            sser.str.contains("план", case=False, na=False)
            & ~sser.str.contains("факт", case=False, na=False)
        ) | _norm_scen.eq("план")
        if legacy_plan_mask.any():
            plan_mask = legacy_plan_mask

    plan_sum = float(amt_num.loc[plan_mask].sum())
    fact_sum = float(amt_num.loc[fact_mask].sum())

    # ── Разнос по лоту: только лотовые статьи, ключ ID_Лота ↔ ЛОТ_ID ──
    lotid_col = _col(t_bd, ("ID_Лота", "ID Лота", "ID_лота", "lot id", "id_lot"))
    art_ser = t_bd[art].astype(str) if art and art in t_bd.columns else pd.Series("", index=t_bd.index)
    is_lot_art = art_ser.map(_forecast_is_lot_value)
    _mps_lotid_col = "ЛОТ_ID" if "ЛОТ_ID" in out.columns else None
    _per_lot_done = False
    if lotid_col is not None and _mps_lotid_col is not None:
        lotid_ser = t_bd[lotid_col].map(_forecast_norm_lot_id)
        _plan_sel = plan_mask & is_lot_art
        _fact_sel = fact_mask & is_lot_art
        plan_map = (
            amt_num.loc[_plan_sel].groupby(lotid_ser.loc[_plan_sel]).sum().to_dict()
            if bool(_plan_sel.any()) else {}
        )
        fact_map = (
            amt_num.loc[_fact_sel].groupby(lotid_ser.loc[_fact_sel]).sum().to_dict()
            if bool(_fact_sel.any()) else {}
        )
        plan_map.pop("", None)
        fact_map.pop("", None)
        if plan_map or fact_map:
            ids = out[_mps_lotid_col].map(_forecast_norm_lot_id)
            counts = ids.value_counts()

            def _per_lot(idv, m):
                v = m.get(idv)
                if v is None or not idv:
                    return 0.0
                c = int(counts.get(idv, 1)) or 1
                return float(v) / c

            _bp_new = pd.Series([float(_per_lot(i, plan_map)) for i in ids], index=out.index)
            _bf_new = pd.Series([float(_per_lot(i, fact_map)) for i in ids], index=out.index)
            # Если ID не сопоставились — не затираем нулями, уходим в пропорциональный фолбэк.
            if float(_bp_new.sum()) > 0.0 or float(_bf_new.sum()) > 0.0:
                out["budget plan"] = _bp_new
                out["budget fact"] = _bf_new
                try:
                    out.attrs["forecast_bddcs_injected_from_1c"] = True
                    out.attrs["forecast_bddcs_per_lot"] = True
                except Exception:
                    pass
                _per_lot_done = True
    if _per_lot_done:
        return out

    if "budget plan" in out.columns:
        w = pd.to_numeric(out["budget plan"], errors="coerce").fillna(0.0)
    else:
        w = pd.Series(0.0, index=out.index)
    # Фолбэк: разносим только по строкам-лотам (иначе агрегация по лоту отбрасывает сумму).
    _lot_text_col = "ЛОТ" if "ЛОТ" in out.columns else ("lot" if "lot" in out.columns else None)
    _lot_row_mask = pd.Series(False, index=out.index)
    if _lot_text_col is not None:
        _lot_row_mask = out[_lot_text_col].map(_forecast_is_lot_value)
    if bool(_lot_row_mask.any()):
        w = w.where(_lot_row_mask, 0.0)
    wsum = float(w.sum())
    _fc_uniform_lot_weights = False
    if wsum <= 0 and (plan_sum > 0 or fact_sum > 0):
        _fc_uniform_lot_weights = True
        if bool(_lot_row_mask.any()):
            w = _lot_row_mask.astype(float)
            wsum = float(w.sum())
        else:
            w = pd.Series(1.0, index=out.index)
            wsum = float(len(out))
    if wsum > 0 and (plan_sum > 0 or fact_sum > 0):
        out["budget plan"] = w / wsum * float(plan_sum)
        out["budget fact"] = w / wsum * float(fact_sum)
        try:
            out.attrs["forecast_bddcs_injected_from_1c"] = True
            if _fc_uniform_lot_weights:
                out.attrs["forecast_bddcs_uniform_lot_weights"] = True
        except Exception:
            pass
    return out


def _forecast_filter_rows_by_plan_end_range(
    work: pd.DataFrame, *, date_from, date_to
) -> pd.DataFrame:
    """Оставляем лоты, АКТИВНЫЕ в периоде «С»–«По» (пересечение срока лота с диапазоном).

    Раньше фильтр отбирал только строки, у которых plan end попадает в диапазон, —
    из-за этого многомесячные лоты, идущие сквозь выбранный месяц, но заканчивающиеся
    позже, выпадали (например, лот с началом в июне и окончанием в ноябре пропадал при
    сужении до июня). Теперь строка остаётся, если её срок [plan start; plan end]
    пересекает [date_from; date_to]: plan end ≥ date_from И plan start ≤ date_to.
    """
    if work is None or getattr(work, "empty", True) or date_from is None or date_to is None:
        return work
    if "plan end" not in work.columns:
        return work
    # Не dayfirst: YYYY-MM-DD иначе ломается (2026-06-01 → январь).
    pe = work["plan end"].map(_forecast_parse_editor_date)
    if not pe.notna().any():
        return work
    # Начало лота: plan start, если есть; иначе — plan end (одномоментный лот).
    if "plan start" in work.columns:
        ps = work["plan start"].map(_forecast_parse_editor_date)
        ps = ps.fillna(pe)
    else:
        ps = pe
    d0 = pd.Timestamp(date_from)
    d1 = pd.Timestamp(date_to)
    if d0 > d1:
        d0, d1 = d1, d0
    d1_end = d1 + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)
    return work[(pe >= d0) & (ps <= d1_end)].copy()


def _forecast_month_calendar_intersects(
    m_per: pd.Period, *, date_from, date_to
) -> bool:
    """Период (месяц/квартал/год) пересекает календарь «С»–«По»."""
    if date_from is None or date_to is None:
        return True
    try:
        p = m_per if isinstance(m_per, pd.Period) else pd.Period(str(m_per), freq="M")
        d0 = pd.Timestamp(date_from)
        d1 = pd.Timestamp(date_to)
        if d0 > d1:
            d0, d1 = d1, d0
        ms = pd.Timestamp(p.start_time)
        me = pd.Timestamp(p.end_time)
        return not (me < d0 or ms > d1)
    except Exception:
        return True


def _forecast_resample_monthly_dataframe(mf: pd.DataFrame, period_type_en: str) -> pd.DataFrame:
    """Месячный mf → месяц / квартал / год (суммы в рублях)."""
    if mf is None or getattr(mf, "empty", True):
        return mf
    if period_type_en == "Month":
        return mf.copy()
    work = mf.copy().reset_index(drop=True)

    def _m_to_ts(x):
        try:
            if isinstance(x, pd.Period):
                return x.to_timestamp(how="start")
            ts = pd.to_datetime(x, errors="coerce", dayfirst=True)
            return pd.NaT if pd.isna(ts) else ts
        except Exception:
            return pd.NaT

    ts = work["month"].map(_m_to_ts)
    try:
        if period_type_en == "Quarter":
            work["_grp"] = ts.dt.to_period("Q")
        else:
            work["_grp"] = ts.dt.to_period("Y")
    except Exception:
        work["_grp"] = ts.apply(
            lambda t: pd.NaT if pd.isna(t) else pd.Period(t, freq=("Q-DEC" if period_type_en == "Quarter" else "Y-DEC"))
        )

    grp = (
        work.dropna(subset=["_grp"])
        .groupby("_grp", sort=True)
        .agg({"bdds_plan_msp": "sum", "bdds_forecast": "sum", "bdds_fact": "sum"})
        .reset_index()
        .rename(columns={"_grp": "month"})
    )
    grp["_dev"] = grp["bdds_plan_msp"] - grp["bdds_forecast"]
    return grp


def _forecast_apply_view_cumulative(mf: pd.DataFrame) -> pd.DataFrame:
    if mf is None or getattr(mf, "empty", True):
        return mf
    out = mf.sort_values("month").copy()
    for c in ("bdds_plan_msp", "bdds_forecast", "bdds_fact"):
        out[c] = pd.to_numeric(out[c], errors="coerce").fillna(0.0).cumsum()
    out["_dev"] = out["bdds_plan_msp"] - out["bdds_forecast"]
    return out



def _forecast_row_lot_label(r: pd.Series) -> str:
    """Подпись лота в таблице: section → lot → block → название задачи."""
    for col in ("section", "lot"):
        if col in r.index:
            s = _clean_display_str(r.get(col))
            if s:
                return s
    for col in ("BLOCK", "block"):
        if col in r.index:
            s = _clean_display_str(r.get(col))
            if s:
                return s
    if "task name" in r.index:
        s = _clean_display_str(r.get("task name"))
        if s:
            return s
    return "—"


def _forecast_lot_label_series(cur: pd.DataFrame) -> pd.Series:
    if cur is None or getattr(cur, "empty", True):
        return pd.Series(dtype=str)
    return cur.apply(_forecast_row_lot_label, axis=1)



def _forecast_editor_visible_mask(pdf: pd.DataFrame) -> pd.Series:
    """Какие строки показывать в UI редактора (расчёт — по всем строкам project_df).

    После агрегации по лоту уровней MSP нет — по умолчанию только строки с БДДС ≠ 0,
    иначе в редакторе десятки пустых WBS-узлов («55.8…») и кажется, что сумм нет.
    """
    if pdf is None or getattr(pdf, "empty", True):
        return pd.Series(dtype=bool)
    bp = (
        pd.to_numeric(pdf["budget plan"], errors="coerce").fillna(0.0)
        if "budget plan" in pdf.columns
        else pd.Series(0.0, index=pdf.index)
    )
    bf = (
        pd.to_numeric(pdf["budget fact"], errors="coerce").fillna(0.0)
        if "budget fact" in pdf.columns
        else pd.Series(0.0, index=pdf.index)
    )
    has_sum = (bp > 0.0) | (bf > 0.0)
    ls = None
    if "level structure" in pdf.columns:
        ls = pd.to_numeric(pdf["level structure"], errors="coerce")
    elif "level" in pdf.columns:
        ls = pd.to_numeric(pdf["level"], errors="coerce")
    if ls is not None:
        structural = ls.fillna(99) <= 2
        return has_sum | (~structural)
    # Нет иерархии (уже сгруппировано по лоту) — скрываем нулевые строки.
    return has_sum


def _forecast_deduplicate_msp_rows(pdf: pd.DataFrame) -> pd.DataFrame:
    """Один лот (метка + plan start/end) — одна строка; при дублях оставляем с большей суммой."""
    if pdf is None or getattr(pdf, "empty", True):
        return pdf
    work = pdf.copy().reset_index(drop=True)
    if "plan start" not in work.columns or "plan end" not in work.columns:
        return work
    work["_fc_lot_key"] = _forecast_lot_label_series(work).astype(str).str.strip().str.casefold()
    work["_fc_ps"] = work["plan start"].map(_forecast_parse_editor_date).dt.normalize()
    work["_fc_pe"] = work["plan end"].map(_forecast_parse_editor_date).dt.normalize()
    work["_fc_score"] = (
        pd.to_numeric(work.get("budget plan"), errors="coerce").fillna(0.0)
        + pd.to_numeric(work.get("budget fact"), errors="coerce").fillna(0.0)
    )
    work = work.sort_values("_fc_score", ascending=False)
    work = work.drop_duplicates(subset=["_fc_lot_key", "_fc_ps", "_fc_pe"], keep="first")
    return work.drop(columns=["_fc_lot_key", "_fc_ps", "_fc_pe", "_fc_score"], errors="ignore").reset_index(drop=True)


def _forecast_aggregate_by_lot(pdf: pd.DataFrame) -> pd.DataFrame:
    """Один лот = одна строка: группируем по реальному лоту (колонка «ЛОТ»/«lot»),
    суммируем отдельно БДДС план и БДДС факт; даты — мин. «Планируемое начало» и
    макс. «Планируемое окончание» среди строк лота. В редактор попадают только строки-лоты
    (у которых заполнен лот); это убирает дубли строк и БДДС по нелотовым задачам.
    Фолбэк (нет колонки лота / нет лотовых строк) — группировка по прежней метке (section)."""
    if pdf is None or getattr(pdf, "empty", True):
        return pdf
    work = pdf.copy().reset_index(drop=True)
    ensure_budget_columns(work)
    if "budget plan" not in work.columns:
        work["budget plan"] = 0.0
    if "budget fact" not in work.columns:
        work["budget fact"] = 0.0
    if "plan start" not in work.columns:
        work["plan start"] = pd.NaT
    if "plan end" not in work.columns:
        work["plan end"] = pd.NaT
    work["plan start"] = work["plan start"].map(_forecast_parse_editor_date)
    work["plan end"] = work["plan end"].map(_forecast_parse_editor_date)
    work["budget plan"] = pd.to_numeric(work["budget plan"], errors="coerce").fillna(0.0)
    work["budget fact"] = pd.to_numeric(work["budget fact"], errors="coerce").fillna(0.0)
    _proj = (
        work["project name"].iloc[0]
        if "project name" in work.columns and len(work)
        else ""
    )

    _lot_text_col = "ЛОТ" if "ЛОТ" in work.columns else ("lot" if "lot" in work.columns else None)
    _grouped_by_lot = False
    if _lot_text_col is not None:
        _lot_lbl = work[_lot_text_col].map(_clean_display_str)
        _is_lot = _lot_lbl.map(_forecast_is_lot_value)
        if bool(_is_lot.any()):
            work = work.loc[_is_lot].copy()
            work["_fc_lot"] = _lot_lbl.loc[_is_lot].astype(str).str.strip()
            _grouped_by_lot = True
    if not _grouped_by_lot:
        work["_fc_lot"] = _forecast_lot_label_series(work).astype(str).str.strip()

    rows_out: List[dict] = []
    for _lot, g in work.groupby("_fc_lot", sort=False):
        rows_out.append(
            {
                "project name": (
                    g["project name"].iloc[0] if "project name" in g.columns else _proj
                ),
                "section": _lot,
                "task name": _lot,
                "plan start": g["plan start"].min(),
                "plan end": g["plan end"].max(),
                "budget plan": float(g["budget plan"].sum()),
                "budget fact": float(g["budget fact"].sum()),
            }
        )
    return pd.DataFrame(rows_out)


def _forecast_prepare_msp_slice(pdf_raw: pd.DataFrame, project_display_name: str) -> tuple[Optional[pd.DataFrame], Optional[str]]:
    pdf = pdf_raw.copy()
    ensure_budget_columns(pdf)
    ensure_date_columns(pdf)
    ensure_msp_hierarchy_columns(pdf)
    try:
        from web_loader import _fill_section_from_task_tree

        pdf = _fill_section_from_task_tree(pdf)
    except Exception:
        pass
    if "plan start" not in pdf.columns:
        for _rus in ("Начало", "План начало", "План Начало"):
            if _rus in pdf.columns:
                pdf["plan start"] = pdf[_rus]
                break
    if "plan end" not in pdf.columns:
        for _rus in ("Окончание", "План окончание", "План Окончание"):
            if _rus in pdf.columns:
                pdf["plan end"] = pdf[_rus]
                break
    pdf = _forecast_merge_bddcs_from_1c(pdf, project_display_name)
    if "budget plan" not in pdf.columns:
        pdf["budget plan"] = 0.0
    pdf["budget plan"] = pd.to_numeric(pdf["budget plan"], errors="coerce").fillna(0.0)
    if "budget fact" not in pdf.columns:
        pdf["budget fact"] = 0.0
    pdf["budget fact"] = pd.to_numeric(pdf["budget fact"], errors="coerce").fillna(0.0)

    missing_dates = [c for c in ("plan start", "plan end") if c not in pdf.columns]
    if missing_dates:
        return None, f"Нужны колонки дат: {', '.join(missing_dates)}."

    if "section" not in pdf.columns:
        pdf["section"] = ""
    if "Название" in pdf.columns and "task name" not in pdf.columns:
        pdf["task name"] = pdf["Название"]
    if "lot" in pdf.columns:
        _sec_s = pdf["section"].astype(str).str.strip()
        _lot_s = pdf["lot"].astype(str).str.strip()
        pdf["section"] = _sec_s.mask(_sec_s.eq("") | _sec_s.str.lower().isin(("nan", "none", "")), _lot_s)
    pdf["section"] = pdf["section"].apply(_clean_display_str)
    if "task name" not in pdf.columns:
        pdf["task name"] = ""
    pdf = _forecast_deduplicate_msp_rows(pdf)
    # ISO-даты YYYY-MM-DD нельзя парсить через dayfirst (ломает 2024-06-01 → 2024-01-06).
    if "plan start" in pdf.columns:
        pdf["plan start"] = pdf["plan start"].map(_forecast_parse_editor_date)
    if "plan end" in pdf.columns:
        pdf["plan end"] = pdf["plan end"].map(_forecast_parse_editor_date)
    return pdf, None


def _forecast_combine_monthly_all_projects(scope_df: pd.DataFrame, project_col: str) -> tuple[pd.DataFrame, float, Optional[str]]:
    """Сводка по всем проектам: суммирование месячных рядов; approved total в млн."""
    labs = sorted(
        {_clean_display_str(x) for x in scope_df[project_col].dropna().unique() if str(x).strip()},
        key=lambda s: str(s).casefold(),
    )
    pieces: List[pd.DataFrame] = []
    approved_mln = 0.0
    errs: List[str] = []
    for lab in labs:
        sub = scope_df[
            scope_df[project_col].map(_project_filter_norm_key) == _project_filter_norm_key(str(lab))
        ].copy()
        if sub.empty:
            continue
        prep, prep_err = _forecast_prepare_msp_slice(sub, str(lab))
        if prep is None or prep_err:
            if prep_err:
                errs.append(f"{lab}: {prep_err}")
            continue
        approved_mln += float(pd.to_numeric(prep["budget plan"], errors="coerce").fillna(0.0).sum()) / 1e6
        mdf, merr = calculate_forecast_budget(
            sub,
            edited_data=prep,
            distribution_mode="uniform",
            abc_source=None,
            row_modes=None,
        )
        if merr:
            errs.append(f"{lab}: {merr}")
            continue
        if mdf is None or mdf.empty:
            continue
        pieces.append(mdf)

    if not pieces:
        return pd.DataFrame(), float(approved_mln), "; ".join(errs) if errs else "Нет расчётных строк по проектам."

    acc = pd.concat(pieces, ignore_index=True)
    summed = (
        acc.groupby("month", sort=False)
        .agg({"bdds_plan_msp": "sum", "bdds_forecast": "sum", "bdds_fact": "sum"})
        .reset_index()
    )
    summed["_dev"] = summed["bdds_plan_msp"] - summed["bdds_forecast"]
    summed = summed.sort_values("month").reset_index(drop=True)
    note = "; ".join(errs) if errs else None
    return summed, float(approved_mln), note




def _forecast_norm_month_period(m):
    try:
        if isinstance(m, pd.Period):
            return m.asfreq("M")
        if pd.isna(m):
            return pd.NaT
        ts = pd.Timestamp(m)
        if pd.notna(ts):
            return ts.to_period("M")
    except Exception:
        pass
    try:
        return pd.Period(str(m), freq="M")
    except Exception:
        return m


def _forecast_turnover_monthly_plan_fact(
    project_name: str,
    *,
    date_from=None,
    date_to=None,
) -> dict:
    """Помесячные план/факт из оборотов 1С (отчёт БДДС), руб."""
    try:
        from dashboards.finance_from_1c import (
            _bdds_turnover_g_for_project,
            resolve_budget_turnover_dannye,
        )
    except Exception:
        return {}
    try:
        from dashboards.finance_from_1c import resolve_reference_1c_dannye
        ref_boot = resolve_reference_1c_dannye(_forecast_find_turnover_dataframe())
    except Exception:
        ref_boot = _forecast_find_turnover_dataframe()
    ref = resolve_budget_turnover_dannye(ref_boot)
    prep = _bdds_turnover_g_for_project(
        project_name=str(project_name or ""),
        period_start=date_from,
        period_end=date_to,
        reference_1c_dannye=ref,
        prefer_budget_scenario=True,
    )
    if prep is None:
        return {}
    g, _months, _art, _canon = prep
    out: dict = {}
    for m in sorted(g["_m"].dropna().unique(), key=lambda x: str(x)):
        mk = _forecast_norm_month_period(m)
        if mk is pd.NaT or (isinstance(mk, float) and pd.isna(mk)):
            continue
        if date_from is not None and date_to is not None:
            if not _forecast_month_calendar_intersects(mk, date_from=date_from, date_to=date_to):
                continue
        chunk = g.loc[g["_m"] == m]
        if chunk.empty:
            continue
        plan_v = float(chunk["_plan"].sum())
        fact_v = float(chunk["_fact"].sum())
        if plan_v + fact_v <= 50_000.0:
            continue
        out[mk] = (plan_v, fact_v)
    return out


def _forecast_turnover_monthly_plan_fact_scope(
    project_labels: list,
    *,
    date_from=None,
    date_to=None,
) -> dict:
    """Сумма план/факт по месяцам для списка проектов (руб.)."""
    agg: dict = {}
    for lab in project_labels:
        for m, (pl, fc) in _forecast_turnover_monthly_plan_fact(
            str(lab), date_from=date_from, date_to=date_to
        ).items():
            if m not in agg:
                agg[m] = [0.0, 0.0]
            agg[m][0] += float(pl)
            agg[m][1] += float(fc)
    return {m: (v[0], v[1]) for m, v in agg.items()}


def _forecast_overlay_turnover_on_monthly(
    mf: pd.DataFrame,
    turnover: dict,
) -> pd.DataFrame:
    """Дополняет помесячный ряд месяцами из оборотов 1С, не подменяя план/факт MSP.

    План/факт/прогноз на этом экране считаются из таблицы лотов (равномерно или % A/B/C).
    Раньше обороты 1С затирали MSP-план/факт → после смены условия лота «прогноз»
    визуально «не пересчитывался» относительно чужих цифр 1С, а ожидаемые доли A%
    (напр. 34% от суммы лотов с началом в месяце) не сходились с таблицей.
    1С здесь только добавляет месяцы, которых нет в MSP-ряде (план/факт/прогноз = 0).
    """
    if mf is None or getattr(mf, "empty", True):
        return mf
    out = mf.copy()
    if not turnover:
        return out
    existing = {
        _forecast_norm_month_period(m)
        for m in out["month"].tolist()
    }
    extra_rows: list[dict] = []
    for m, (_pl, _fc) in turnover.items():
        mk = _forecast_norm_month_period(m)
        if mk is pd.NaT or (isinstance(mk, float) and pd.isna(mk)):
            continue
        if mk in existing:
            continue
        # Месяц есть только в оборотах — оставляем нули, чтобы не смешивать источники.
        extra_rows.append(
            {
                "month": mk,
                "bdds_plan_msp": 0.0,
                "bdds_fact": 0.0,
                "bdds_forecast": 0.0,
            }
        )
    if not extra_rows:
        return out
    return (
        pd.concat([out, pd.DataFrame(extra_rows)], ignore_index=True)
        .sort_values("month")
        .reset_index(drop=True)
    )






def _forecast_filter_chart_months(
    df: pd.DataFrame,
    *,
    hide_zero_months: bool,
    min_rub: float = None,
) -> pd.DataFrame:
    """Фильтр месяцев для графика: нули и «пыль» слева (0.2 млн при пике 300)."""
    if df is None or getattr(df, "empty", True):
        return df
    thr = float(_FINANCE_CHART_MIN_MONTH_RUB if min_rub is None else min_rub)
    out = df.sort_values("month").copy()
    pl = pd.to_numeric(out["bdds_plan_msp"], errors="coerce").fillna(0.0)
    fc = pd.to_numeric(out["bdds_fact"], errors="coerce").fillna(0.0)
    fr = pd.to_numeric(out["bdds_forecast"], errors="coerce").fillna(0.0)
    tot = pl.abs() + fc.abs() + fr.abs()
    active = tot >= thr
    if hide_zero_months:
        kept = out.loc[active]
        if kept.empty:
            return kept.reset_index(drop=True)
        peak = float(
            np.nanmax(
                np.concatenate(
                    [
                        pl.loc[kept.index].abs().to_numpy(),
                        fc.loc[kept.index].abs().to_numpy(),
                        fr.loc[kept.index].abs().to_numpy(),
                    ]
                )
            )
            or 0.0
        )
        # Иначе слева волоски без подписей, а шкала уезжает вверх по поздним месяцам.
        rel_thr = max(thr, peak * 0.015)
        return out.loc[tot >= rel_thr].reset_index(drop=True)
    if not bool(active.any()):
        return out
    idx = np.flatnonzero(active.to_numpy())
    return out.iloc[int(idx[0]) : int(idx[-1]) + 1].reset_index(drop=True)


def _finance_force_grouped_bar_annotations(
    fig: go.Figure,
    *,
    min_abs: float = 0.05,
    unit_suffix: str = " млн. руб.",
) -> go.Figure:
    """Подписи над grouped bar через annotations — не зависят от bar.text/sanitize."""
    if fig is None:
        return fig
    try:
        bars = [
            tr
            for tr in (fig.data or [])
            if getattr(tr, "type", None) == "bar" or type(tr).__name__ == "Bar"
        ]
    except Exception:
        return fig
    if not bars:
        return fig
    n_ser = len(bars)
    lbl_color = _fin_chart_label_color()
    suf = str(unit_suffix or "")
    anns: list[dict] = []
    # Пиксельный сдвиг внутри группы (при ~880px на категорию и 3–4 серии).
    slot_px = 52.0
    for s_idx, tr in enumerate(bars):
        xs = list(getattr(tr, "x", None) or [])
        ys = list(getattr(tr, "y", None) or [])
        raw_txt = getattr(tr, "text", None)
        try:
            texts = list(raw_txt) if raw_txt is not None else []
        except Exception:
            texts = []
        # Цвет подписи: outsidetextfont / textfont / дефолт; per-point — по индексу.
        tf = getattr(tr, "outsidetextfont", None) or getattr(tr, "textfont", None)
        base_color = lbl_color
        per_colors = None
        try:
            if tf is not None and getattr(tf, "color", None) is not None:
                c = tf.color
                if isinstance(c, (list, tuple)):
                    per_colors = list(c)
                else:
                    base_color = c
        except Exception:
            pass
        xshift = (s_idx - (n_ser - 1) / 2.0) * slot_px
        for i, (x, y) in enumerate(zip(xs, ys)):
            try:
                yf = float(y)
            except (TypeError, ValueError):
                continue
            if not np.isfinite(yf):
                continue
            t = ""
            if i < len(texts) and texts[i] is not None and str(texts[i]).strip():
                t = str(texts[i]).strip()
            # Явная подпись (в т.ч. «0.0») важнее порога min_abs — иначе пропадает откл.≈0.
            if not t and abs(yf) < float(min_abs):
                continue
            if not t:
                t = f"{yf:.1f}"
            if not t:
                continue
            if suf and "млн" not in t.casefold():
                t = f"{t}{suf}"
            col = base_color
            if per_colors is not None and i < len(per_colors):
                col = per_colors[i]
            anns.append(
                dict(
                    x=x,
                    y=yf,
                    text=t,
                    showarrow=False,
                    xref="x",
                    yref="y",
                    xanchor="center",
                    yanchor="bottom" if yf >= 0 else "top",
                    yshift=6 if yf >= 0 else -6,
                    xshift=float(xshift),
                    font=dict(size=11, color=col, family="Arial, Helvetica, sans-serif"),
                    bgcolor="rgba(255,255,255,0.65)",
                    borderpad=1,
                )
            )
    if not anns:
        return fig
    try:
        prev = list(fig.layout.annotations or [])
    except Exception:
        prev = []
    keep: list = []
    for a in prev:
        try:
            ys = a.get("yshift") if isinstance(a, dict) else getattr(a, "yshift", None)
            sa = a.get("showarrow") if isinstance(a, dict) else getattr(a, "showarrow", True)
            meta = a.get("meta") if isinstance(a, dict) else getattr(a, "meta", None)
            if meta == "bi-bar-label" or (ys == 6 and sa is False):
                continue
        except Exception:
            pass
        keep.append(a)
    for a in anns:
        a["meta"] = "bi-bar-label"
    fig.update_layout(annotations=list(keep) + anns)
    return fig


def _forecast_financier_status_dataset(
    *,
    filtered_scope: pd.DataFrame,
    project_col: str,
    all_projects: bool,
    selected_project_label: Optional[str],
    period_type_en: str,
    date_from,
    date_to,
    single_updated_data: Optional[pd.DataFrame],
    abc_source,
    row_modes,
    monthly_snapshot: Optional[pd.DataFrame] = None,
    dev_base: str = "БДДС план",
) -> pd.DataFrame:
    """Строки для таблицы «Статус»: план/факт/прогноз из распределения по лотам (MSP).

    Обороты 1С — только запасной источник, если в помесячном MSP-ряде нет месяца.
    """
    rows: List[dict] = []

    def _append_from_mf(mf: pd.DataFrame, lab: str, turnover: dict) -> None:
        fc_by_m: dict = {}
        plan_by_m: dict = {}
        fact_by_m: dict = {}
        if mf is not None and not getattr(mf, "empty", True):
            for _, rr in mf.iterrows():
                mk = _forecast_norm_month_period(rr["month"])
                fc_by_m[mk] = float(rr.get("bdds_forecast", 0.0) or 0.0)
                plan_by_m[mk] = float(rr.get("bdds_plan_msp", 0.0) or 0.0)
                fact_by_m[mk] = float(rr.get("bdds_fact", 0.0) or 0.0)
        turn_norm = {_forecast_norm_month_period(k): v for k, v in turnover.items()}
        months_all = sorted(
            set(fc_by_m.keys()) | set(plan_by_m.keys()) | set(turn_norm.keys()),
            key=lambda x: str(x),
        )
        if not months_all and mf is not None and not getattr(mf, "empty", True):
            months_all = list(mf["month"])
        for m in months_all:
            plan_rub = float(plan_by_m.get(m, 0.0) or 0.0)
            fact_rub = float(fact_by_m.get(m, 0.0) or 0.0)
            # 1С — только если MSP не дал сумм по месяцу (нет лотов в сроке).
            if abs(plan_rub) + abs(fact_rub) <= 1e-6 and m in turn_norm:
                plan_rub, fact_rub = turn_norm[m]
            rows.append(
                {
                    "_period": m,
                    "Проект": str(lab),
                    "plan_rub": plan_rub,
                    "fact_rub": fact_rub,
                    "forecast_rub": float(fc_by_m.get(m, 0.0)),
                }
            )

    if (
        not all_projects
        and monthly_snapshot is not None
        and not getattr(monthly_snapshot, "empty", True)
    ):
        lab = str(selected_project_label or "").strip()
        if lab:
            turnover = _forecast_turnover_monthly_plan_fact(
                lab, date_from=date_from, date_to=date_to
            )
            mf = monthly_snapshot.sort_values("month").copy()
            if date_from is not None and date_to is not None:
                _keep_m = mf["month"].map(
                    lambda m: _forecast_month_calendar_intersects(
                        m, date_from=date_from, date_to=date_to
                    )
                )
                mf = mf.loc[_keep_m].reset_index(drop=True)
            mf = _forecast_resample_monthly_dataframe(mf, period_type_en)
            _append_from_mf(mf, lab, turnover)
    elif all_projects:
        labs = sorted(
            {_clean_display_str(x) for x in filtered_scope[project_col].dropna().unique() if str(x).strip()},
            key=lambda s: str(s).casefold(),
        )
        for lab in labs:
            sub = filtered_scope[
                filtered_scope[project_col].map(_project_filter_norm_key)
                == _project_filter_norm_key(str(lab))
            ].copy()
            if sub.empty:
                continue
            prep, prep_err = _forecast_prepare_msp_slice(sub, str(lab))
            if prep is None or prep_err:
                continue
            mdf, merr = calculate_forecast_budget(
                sub,
                edited_data=prep,
                distribution_mode="uniform",
                abc_source=None,
                row_modes=None,
            )
            if merr or mdf is None or getattr(mdf, "empty", True):
                continue
            mf = mdf.sort_values("month").copy()
            if date_from is not None and date_to is not None:
                _keep_m = mf["month"].map(
                    lambda m: _forecast_month_calendar_intersects(
                        m, date_from=date_from, date_to=date_to
                    )
                )
                mf = mf.loc[_keep_m].reset_index(drop=True)
            mf = _forecast_resample_monthly_dataframe(mf, period_type_en)
            turnover = _forecast_turnover_monthly_plan_fact(
                str(lab), date_from=date_from, date_to=date_to
            )
            _append_from_mf(mf, str(lab), turnover)
    else:
        lab = str(selected_project_label or "").strip()
        if not lab:
            return pd.DataFrame()
        sub = filtered_scope.copy()
        prep, prep_err = _forecast_prepare_msp_slice(sub, lab)
        if prep is None or prep_err:
            return pd.DataFrame()
        ed = single_updated_data if single_updated_data is not None else prep
        mdf, merr = calculate_forecast_budget(
            sub,
            edited_data=ed,
            distribution_mode="uniform",
            abc_source=abc_source,
            row_modes=row_modes,
        )
        if merr or mdf is None or getattr(mdf, "empty", True):
            return pd.DataFrame()
        mf = mdf.sort_values("month").copy()
        if date_from is not None and date_to is not None:
            _keep_m = mf["month"].map(
                lambda m: _forecast_month_calendar_intersects(
                    m, date_from=date_from, date_to=date_to
                )
            )
            mf = mf.loc[_keep_m].reset_index(drop=True)
        mf = _forecast_resample_monthly_dataframe(mf, period_type_en)
        turnover = _forecast_turnover_monthly_plan_fact(
            lab, date_from=date_from, date_to=date_to
        )
        _append_from_mf(mf, lab, turnover)

    out = pd.DataFrame(rows)
    if out.empty:
        return out

    _from_fact = str(dev_base).strip() == "БДДС факт"

    def _stat_txt(v: float) -> str:
        try:
            x = float(v)
        except (TypeError, ValueError):
            return ""
        if abs(x) < 1e-9:
            return "Без отклонения"
        # dv > 0: прогноз выше базы → перерасход (зелёный); dv < 0 → отставание (красный)
        if x > 0:
            return "Фактический перерасход" if _from_fact else "Прогнозируется перерасход"
        return "Фактическое отставание" if _from_fact else "Прогнозируется отставание"

    out["Месяц"] = out["_period"].apply(format_period_ru)
    out["БДДС (план), млн"] = out["plan_rub"] / 1e6
    out["БДДС (факт), млн"] = out["fact_rub"] / 1e6
    out["БДДС (прогноз), млн"] = out["forecast_rub"] / 1e6
    _base_mln = (
        out["БДДС (факт), млн"]
        if _from_fact
        else out["БДДС (план), млн"]
    )
    out["Отклонение по сумме, млн"] = out["БДДС (прогноз), млн"] - _base_mln
    out["Статус"] = out["Отклонение по сумме, млн"].map(_stat_txt)
    # Сортировка хронологическая по периоду (а не по строке «Месяц»).
    out["_period_sort"] = out["_period"].map(_forecast_norm_month_period)
    disp = (
        out.sort_values(["Проект", "_period_sort"])[
            [
                "Месяц",
                "Проект",
                "БДДС (план), млн",
                "БДДС (факт), млн",
                "БДДС (прогноз), млн",
                "Отклонение по сумме, млн",
                "Статус",
            ]
        ].reset_index(drop=True)
    )
    return disp.round(2)




def _forecast_financier_status_table_html(df: pd.DataFrame) -> str:
    """«Статус»: ● зелёный при перерасходе (прогноз > база), красный при отставании."""
    if df is None or getattr(df, "empty", True):
        return "<p>Нет данных для статуса.</p>"
    import utils as u
    from dashboards.light_theme import finance_dev_negative_color

    _col_dev = "Отклонение по сумме, млн"
    _col_stat = "Статус" if "Статус" in df.columns else "Статус для финансиста"
    green = finance_dev_negative_color()
    red = "hsl(348,100%,63%)"
    neutral_bullet = "#94a3b8"
    _th_border = u.FINANCE_TABLE_CELL_BORDER
    _td_border = u.TABLE_CELL_BORDER
    _hdr_bg = u.TABLE_HEADER_BG_COLOR
    _txt = u.TABLE_TEXT_COLOR
    _bg = u.TABLE_BG_COLOR
    _hdr_css = u.TABLE_HEADER_FONT_CSS
    _wrap_id = "fcst_" + str(abs(id(df)))
    _st_vh = 52.0
    _st_box_h = int(min(640, max(280, _st_vh * 10 + 56)))
    parts = [
        "<style>"
        ".fc-st-cell-red, .fc-st-cell-red * { color: hsl(348,100%,63%) !important; }"
        ".fc-st-cell-green, .fc-st-cell-green * { color: " + green + " !important; }"
        f"#{_wrap_id} .budget-table-scroll {{ height: {_st_box_h}px !important; max-height: {_st_box_h}px !important; min-height: 0; "
        f"overflow: auto; -webkit-overflow-scrolling: touch; scrollbar-gutter: stable; "
        f"box-sizing: border-box; }}"
        f"#{_wrap_id}.budget-deviation-table-wrap {{ display: block; overflow: hidden; width: 100%; }}"
        f"#{_wrap_id} thead th {{ position: sticky; top: 0; z-index: 5; "
        f"background-color: {_hdr_bg} !important; color: {_txt}; {_hdr_css} }}"
        f"#{_wrap_id} .budget-table-scroll table {{ width: max-content; min-width: 100%; }}"
        "</style>",
        f'<div id="{_wrap_id}" class="budget-deviation-table-wrap bi-styled-table-wrap" data-bi-rows="{len(df)}">',
        f'<div class="budget-table-scroll" data-scroll-vh="{_st_vh:.1f}" data-scroll-box-h="{_st_box_h}">',
        f'<table class="rendered-table bi-sortable-table bi-sort-click-only" style="width:max-content;min-width:100%;border-collapse:collapse;background-color:{_bg};color:{_txt};font-size:14px;">',
        "<thead><tr>",
    ]
    for c in df.columns:
        _cn = str(c).strip()
        parts.append(
            f'<th style="border:{_th_border};padding:8px 6px;text-align:center;vertical-align:middle;'
            f'background-color:{_hdr_bg};color:{_txt};{_hdr_css};" '
            f'data-sort-label="{html_module.escape(_cn, quote=True)}">{html_module.escape(_cn)}</th>'
        )
    parts.append("</tr></thead><tbody>")
    for _, row in df.iterrows():
        parts.append("<tr>")
        for col in df.columns:
            raw = row[col]
            val_esc = html_module.escape("" if pd.isna(raw) else str(raw))
            if col == _col_dev:
                try:
                    num = float(raw)
                except (TypeError, ValueError):
                    num = None
                if num is None or pd.isna(num):
                    parts.append(
                        f'<td style="border:{_td_border}; padding:5px 8px;">{val_esc}</td>'
                    )
                elif abs(float(num)) < 1e-9:
                    parts.append(
                        f'<td style="border:{_td_border}; padding:5px 8px;">'
                        f'<span style="font-weight:700">{html_module.escape(f"{float(num):.2f}")}</span></td>'
                    )
                else:
                    txt = f"{float(num):+.2f}"
                    txt_esc = html_module.escape(txt)
                    # + перерасход (зелёный), − отставание (красный)
                    _cls = "fc-st-cell-green" if float(num) > 0 else "fc-st-cell-red"
                    parts.append(
                        f'<td class="{_cls}" style="border:{_td_border}; padding:5px 8px; '
                        f'font-weight:700;"><span>{txt_esc}</span></td>'
                    )
            elif col == _col_stat:
                try:
                    dv = float(row.get(_col_dev, float("nan")))
                except (TypeError, ValueError):
                    dv = float("nan")
                if pd.isna(dv) or abs(float(dv)) < 1e-9:
                    bullet = neutral_bullet
                elif dv > 0:
                    bullet = green
                else:
                    bullet = red
                parts.append(
                    f'<td style="border:{_td_border}; padding:5px 8px;">'
                    f'<span style="color:{bullet};font-weight:700;font-size:1.12em;margin-right:6px">●</span>'
                    f'<span style="color:{_txt};font-weight:600">{val_esc}</span>'
                    "</td>"
                )
            else:
                parts.append(
                    f'<td style="border:{_td_border}; padding:5px 8px;">{val_esc}</td>'
                )
        parts.append("</tr>")
    parts.append("</tbody></table></div></div>")
    return "".join(parts)




def _forecast_row_modes_use_abc(mode_val) -> bool:
    sl = str(mode_val or "").strip().casefold()
    if not sl:
        return False
    if "равном" in sl:
        return False
    if sl.startswith("%") or "a/b/c" in sl or "распредел" in sl:
        return True
    return False


def _forecast_edit_disabled_mask(edit_df: pd.DataFrame) -> pd.DataFrame:
    dis = pd.DataFrame(False, index=edit_df.index, columns=edit_df.columns)
    if "Условие распределения" not in edit_df.columns:
        return dis
    for i in range(len(edit_df)):
        if not _forecast_row_modes_use_abc(edit_df.iloc[i]["Условие распределения"]):
            for c in ("A, %", "B, %", "C, %"):
                if c in dis.columns:
                    dis.at[edit_df.index[i], c] = True
    if "Лот" in dis.columns:
        dis["Лот"] = True
    return dis




