# Горизонтальный bar-chart «Предписания по подрядчикам»: эталонная высота строки
# (при фильтре по подрядчику — yaxis domain, чтобы бар не растягивался).
_PRED_CHART_ROW_H = 64
_PRED_CHART_LAYOUT_PAD = 200
_PRED_CHART_MIN_HEIGHT = 280


def _pred_chart_group_row_count(
    df: pd.DataFrame, group_col: str | None, *, hide_resolved: bool
) -> int:
    if df is None or getattr(df, "empty", True) or not group_col or group_col not in df.columns:
        return 1
    work = df
    if hide_resolved and "_resolved" in work.columns:
        work = work.loc[~work["_resolved"].astype(bool)]
    if work.empty:
        return 1
    names = work[group_col].astype(str).str.strip()
    names = names[names.ne("") & ~names.str.casefold().isin({"nan", "none"})]
    return max(1, int(names.nunique()))


def _pred_chart_layout_height(n_ref_rows: int) -> int:
    n = max(1, int(n_ref_rows))
    return max(_PRED_CHART_MIN_HEIGHT, n * _PRED_CHART_ROW_H + _PRED_CHART_LAYOUT_PAD)


def _pred_chart_yaxis_domain(n_visible: int, n_ref: int) -> tuple[float, float]:
    n_v = max(1, int(n_visible))
    n_r = max(1, int(n_ref))
    if n_v >= n_r:
        return (0.0, 1.0)
    span = min(1.0, n_v / n_r)
    return (1.0 - span, 1.0)


_PRED_COLOR_STOP_WORK = "#722F37"
_PRED_COLOR_CRITICAL = "#e74c3c"
_PRED_COLOR_UNRESOLVED = "#e67e22"
_PRED_COLOR_ON_TIME = "#2ecc71"
_PRED_COLOR_OVERDUE_RESOLVED = "#f1c40f"
_PRED_PIE_STATUS_ORDER = (
    "Остановка работ",
    "Критические",
    "Не устранено",
    "Сдано в срок",
    "Устранено с просрочкой",
)


def _pred_tessa_tag_series(df: pd.DataFrame, tag_col: str | None) -> pd.Series:
    if df is None or getattr(df, "empty", True) or not tag_col or tag_col not in df.columns:
        return pd.Series("", index=df.index if df is not None else None)
    return (
        df[tag_col]
        .astype(str)
        .str.replace("\ufeff", "", regex=False)
        .str.replace("\xa0", " ", regex=False)
        .str.strip()
        .str.casefold()
    )


def _pred_tag_contains_any(tags: pd.Series, needles: tuple[str, ...]) -> pd.Series:
    out = pd.Series(False, index=tags.index)
    for needle in needles:
        n = str(needle or "").strip().casefold()
        if n:
            out = out | tags.str.contains(n, regex=False, na=False)
    return out


def _pred_pct_round(n: int, total: int) -> float:
    if total <= 0:
        return 0.0
    return round(100.0 * int(n) / int(total), 1)


def _pred_pct_ends_half(p: float) -> bool:
    tenths = int(round(float(p) * 10))
    return abs(float(p) * 10 - tenths) < 1e-9 and tenths % 10 == 5


def _pred_build_status_pie_df(df: pd.DataFrame) -> pd.DataFrame:
    """Круговая диаграмма: взаимоисключающие доли + правила округления % (ТЗ п.7)."""
    if df is None or getattr(df, "empty", True):
        return pd.DataFrame(columns=["Статус", "Количество", "Доля"])
    unres = ~df["_resolved"].astype(bool)
    stop = unres & df.get("_stop_work", False).astype(bool)
    crit_only = unres & df.get("_critical", False).astype(bool) & ~df.get("_stop_work", False).astype(bool)
    unres_other = unres & ~stop & ~crit_only
    od = pd.to_numeric(df.get("_overdue_days", 0), errors="coerce").fillna(0)
    on_time = df["_resolved"].astype(bool) & (od <= 0)
    overdue_res = df["_resolved"].astype(bool) & (od > 0)
    counts = {
        "Остановка работ": int(stop.sum()),
        "Критические": int(crit_only.sum()),
        "Не устранено": int(unres_other.sum()),
        "Сдано в срок": int(on_time.sum()),
        "Устранено с просрочкой": int(overdue_res.sum()),
    }
    total = sum(counts.values())
    if total <= 0:
        return pd.DataFrame(columns=["Статус", "Количество", "Доля"])

    nu = counts["Остановка работ"] + counts["Критические"] + counts["Не устранено"]
    pct_u = _pred_pct_round(nu, total)
    pct_r = round(100.0 - pct_u, 1)

    p_stop = _pred_pct_round(counts["Остановка работ"], total)
    p_crit = _pred_pct_round(counts["Критические"], total)
    p_other_u = _pred_pct_round(counts["Не устранено"], total)
    if _pred_pct_ends_half(p_stop) and _pred_pct_ends_half(p_crit):
        p_crit = round(pct_u - p_stop - p_other_u, 1)
    else:
        p_other_u = round(pct_u - p_stop - p_crit, 1)

    p_on_time = _pred_pct_round(counts["Сдано в срок"], total)
    p_od = _pred_pct_round(counts["Устранено с просрочкой"], total)
    if _pred_pct_ends_half(p_on_time) and _pred_pct_ends_half(p_od):
        p_od = round(pct_r - p_on_time, 1)
    else:
        p_od = round(pct_r - p_on_time, 1)

    pct_map = {
        "Остановка работ": p_stop,
        "Критические": p_crit,
        "Не устранено": p_other_u,
        "Сдано в срок": p_on_time,
        "Устранено с просрочкой": p_od,
    }
    rows = [
        {"Статус": label, "Количество": counts[label], "Доля": pct_map[label]}
        for label in _PRED_PIE_STATUS_ORDER
        if counts.get(label, 0) > 0
    ]
    return pd.DataFrame(rows)


_PRED_UNRESOLVED_STATUS_BUCKETS = ("Остановка работ", "Критические", "Не устранено")


def _pred_status_bucket_series(df: pd.DataFrame) -> pd.Series:
    """Взаимоисключающая категория строки (как в круговой диаграмме по статусам)."""
    if df is None or getattr(df, "empty", True):
        return pd.Series(dtype=object)
    unres = ~df["_resolved"].astype(bool)
    stop = unres & df.get("_stop_work", False).astype(bool)
    crit_only = (
        unres
        & df.get("_critical", False).astype(bool)
        & ~df.get("_stop_work", False).astype(bool)
    )
    unres_other = unres & ~stop & ~crit_only
    od = pd.to_numeric(df.get("_overdue_days", 0), errors="coerce").fillna(0)
    on_time = df["_resolved"].astype(bool) & (od <= 0)
    overdue_res = df["_resolved"].astype(bool) & (od > 0)
    out = pd.Series("Не устранено", index=df.index, dtype=object)
    out.loc[stop] = "Остановка работ"
    out.loc[crit_only] = "Критические"
    out.loc[unres_other] = "Не устранено"
    out.loc[on_time] = "Сдано в срок"
    out.loc[overdue_res] = "Устранено с просрочкой"
    return out


def _pred_objects_chart_status_order(*, hide_resolved: bool) -> tuple[str, ...]:
    if hide_resolved:
        return _PRED_UNRESOLVED_STATUS_BUCKETS
    return _PRED_PIE_STATUS_ORDER


def _pred_build_by_object_status_df(
    df: pd.DataFrame, obj_col: str, *, hide_resolved: bool
) -> pd.DataFrame:
    if df is None or df.empty or not obj_col or obj_col not in df.columns:
        return pd.DataFrame()
    work = df.copy()
    work["_status_bucket"] = _pred_status_bucket_series(work)
    if hide_resolved:
        work = work[~work["_resolved"].astype(bool)]
    if work.empty:
        return pd.DataFrame()
    piv = (
        work.groupby([obj_col, "_status_bucket"], observed=False)
        .size()
        .unstack(fill_value=0)
    )
    status_order = _pred_objects_chart_status_order(hide_resolved=hide_resolved)
    for col in status_order:
        if col not in piv.columns:
            piv[col] = 0
    piv = piv[[c for c in status_order if c in piv.columns]]
    piv["_total"] = piv.sum(axis=1).astype(int)
    piv["_sort_name"] = piv.index.astype(str).str.casefold()
    piv = piv.sort_values(["_total", "_sort_name"], ascending=[False, True], kind="mergesort")
    piv = piv.drop(columns=["_sort_name"])
    return piv.reset_index()


def _pred_axis_upper_bound(xmax: float) -> float:
    try:
        val = float(xmax)
    except (TypeError, ValueError):
        return 5.0
    if not np.isfinite(val) or val <= 0:
        return 5.0
    if val <= 5:
        return 5.0
    if val <= 10:
        return 10.0
    if val <= 25:
        return float(int(np.ceil(val / 5.0)) * 5)
    if val <= 100:
        return float(int(np.ceil(val / 10.0)) * 10)
    return float(int(np.ceil(val / 25.0)) * 25)


def _pred_objects_by_status_figure(
    piv: pd.DataFrame,
    obj_col: str,
    *,
    hide_resolved: bool,
) -> go.Figure:
    if piv is None or piv.empty or not obj_col or obj_col not in piv.columns:
        return go.Figure()
    obj_labels = piv[obj_col].astype(str).tolist()
    status_order = _pred_objects_chart_status_order(hide_resolved=hide_resolved)
    fig = go.Figure()
    for status in status_order:
        if status not in piv.columns:
            continue
        vals = pd.to_numeric(piv[status], errors="coerce").fillna(0).astype(int).tolist()
        texts = [str(v) if v > 0 else "" for v in vals]
        fig.add_trace(
            go.Bar(
                x=obj_labels,
                y=vals,
                name=status,
                marker=dict(color=_pred_status_chart_color(status)),
                text=texts,
                texttemplate="%{text}",
                textposition="inside",
                insidetextanchor="middle",
                textangle=0,
                textfont=dict(color="#ffffff", size=13, family="Inter, Arial, sans-serif"),
                hovertemplate=f"<b>%{{x}}</b><br>{status}: %{{y}}<extra></extra>",
            )
        )
    for _, row in piv.iterrows():
        total = int(row.get("_total", 0) or 0)
        if total <= 0:
            continue
        fig.add_annotation(
            x=str(row[obj_col]),
            y=float(total),
            text=f"<b>{total}</b>",
            showarrow=False,
            xref="x",
            yref="y",
            xanchor="center",
            yanchor="bottom",
            yshift=14,
            font=dict(color=_fin_chart_label_color(), size=16, family="Inter, Arial, sans-serif"),
        )
    _n_obj = len(piv.index)
    _obj_gaps = _plotly_bargaps_sparse_x_like_gdrs(_n_obj)
    ymax = float(pd.to_numeric(piv["_total"], errors="coerce").fillna(0).max() or 0)
    axis_upper = _pred_axis_upper_bound(ymax) if ymax > 0 else 5.0
    fig.update_layout(
        barmode="stack",
        height=470,
        xaxis_title="",
        yaxis_title="Количество",
        showlegend=True,
        legend=dict(
            orientation="h",
            yanchor="top",
            y=-0.18,
            xanchor="center",
            x=0.5,
            font=dict(size=12, color=_fin_chart_label_color()),
        ),
        uirevision=f"pred_by_obj_v3_{int(hide_resolved)}",
        xaxis=dict(
            fixedrange=False,
            categoryorder="array",
            categoryarray=obj_labels,
            tickangle=0,
            tickfont=dict(size=16, color=_fin_chart_label_color()),
        ),
        yaxis=dict(fixedrange=False, range=[0, axis_upper * 1.12]),
        margin=dict(l=56, r=36, t=64, b=110),
        **_obj_gaps,
    )
    fig.update_traces(
        width=max(0.08, 0.46 / 5),
        selector=dict(type="bar"),
        textangle=0,
    )
    fig.update_layout(uniformtext=dict(minsize=9, mode="show"))
    fig = _apply_finance_bar_label_layout(fig)
    return fig


def _pred_fmt_days_display(val) -> str:
    """Дни просрочки = устранение − срок: просрочка > 0 (красный, сверху); досрочно < 0 (зелёный, ниже нуля)."""
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return ""
    try:
        v = int(round(float(val)))
    except (TypeError, ValueError):
        return str(val).strip()
    return str(v)


def _pred_fmt_due(val) -> str:
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return ""
    dt = pd.to_datetime(val, errors="coerce", dayfirst=True)
    if pd.isna(dt):
        return _clean_display_str(val)
    return dt.strftime("%d.%m.%Y")


def _pred_fmt_num(val) -> str:
    if val is None or (isinstance(val, float) and pd.isna(val)) or str(val).strip() == "":
        return "Без номера"
    formatted = _pred_fmt_doc_full(val)
    if formatted == "—":
        return "Без номера"
    return formatted


def _pred_fmt_doc_full(val) -> str:
    """ID/номер документа из TESSA — целое без плавающей точки (73.0 → «73»)."""
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return "—"
    # numpy/pandas целые и float-целые
    try:
        if isinstance(val, (int, np.integer)) and not isinstance(val, bool):
            return str(int(val))
        if isinstance(val, (float, np.floating)) and float(val) == int(val):
            return str(int(val))
    except (TypeError, ValueError, OverflowError):
        pass
    s = str(val).strip()
    if not s or s.lower() in ("nan", "none", "nat", "<na>"):
        return "—"
    # «318.0» / «318,0» из CSV/Excel
    if re.fullmatch(r"-?\d+[.,]0+", s.replace(" ", "").replace("\xa0", "")):
        try:
            return str(int(float(s.replace(" ", "").replace("\xa0", "").replace(",", "."))))
        except (TypeError, ValueError):
            pass
    try:
        nf = float(s.replace(" ", "").replace("\xa0", "").replace(",", "."))
        if nf == int(nf) and abs(nf) < 1e15:
            return str(int(nf))
    except (TypeError, ValueError):
        pass
    return s


@st.cache_data(show_spinner=False, ttl=600)
def _load_dogovor_lookup() -> dict[str, dict]:
    """Q15/Q30: lookup ID_Договора из dogovor_json в активной версии БД."""
    try:
        from web_db_read import load_dogovor_lookup_from_db

        return load_dogovor_lookup_from_db()
    except Exception:
        return {}

_CONTRACT_NO_HOMO_MAP = {

        "\u0430": "a",
        "\u0441": "c",
        "\u0435": "e",
        "\u043d": "h",
        "\u043a": "k",
        "\u043c": "m",
        "\u043e": "o",
        "\u0440": "p",
        "\u0442": "t",
        "\u0445": "x",
        "\u0443": "y",
        "\u0432": "v",
    }
_CONTRACT_NO_HOMOGLYPHS = str.maketrans(_CONTRACT_NO_HOMO_MAP)


def _contract_no_search_key(val: object) -> str:
    """Нормализация № договора для поиска (casefold + латиница/кириллица)."""
    t = str(val or "").strip().casefold().replace("\xa0", " ")
    return t.translate(_CONTRACT_NO_HOMOGLYPHS)


def _contract_no_latin_alias(val: object) -> str:
    """Латинский alias для подсказок при неверной раскладке."""
    out: list[str] = []
    for ch in str(val or ""):
        rep = _CONTRACT_NO_HOMO_MAP.get(ch.casefold())
        if rep is None:
            out.append(ch)
        elif ch.isupper():
            out.append(rep.upper())
        else:
            out.append(rep)
    return "".join(out)


def _contract_no_filter_matches(
    query: str, contracts: list[str], *, limit: int = 30
) -> list[str]:
    q = _contract_no_search_key(query)
    if not q:
        return []
    out: list[str] = []
    for c in contracts:
        if q in _contract_no_search_key(c):
            out.append(c)
            if len(out) >= limit:
                break
    return out


def _contract_no_select_options(contracts: list[str]) -> list[str]:
    """Опции selectbox: реальные № + латинские alias для homoglyphs."""
    out: list[str] = []
    seen: set[str] = set()
    for c in contracts:
        cs = str(c).strip()
        if not cs:
            continue
        ck = cs.casefold()
        if ck not in seen:
            out.append(cs)
            seen.add(ck)
        alias = _contract_no_latin_alias(cs)
        ak = alias.casefold()
        if ak and ak not in seen:
            out.append(alias)
            seen.add(ak)
    return sorted(out, key=lambda x: x.casefold())





def _collect_contract_filter_options(
    pred: pd.DataFrame,
    contract_col: str | None,
) -> list[str]:
    """All contract numbers: pred + 1c Dogovor + DK."""
    nums: set[str] = set()
    _uuid_re = re.compile(
        r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
        re.I,
    )

    def _add(val: object) -> None:
        s = str(val or "").strip()
        if not s or s.lower() in ("nan", "none", "nat") or _uuid_re.match(s):
            return
        nums.add(s)

    if contract_col and contract_col in pred.columns:
        for x in pred[contract_col].dropna().tolist():
            _add(x)
    try:
        for rec in (_load_dogovor_lookup() or {}).values():
            if isinstance(rec, dict):
                _add(rec.get("Номер_Договора") or rec.get("Номер_Договор"))
    except Exception:
        pass
    try:
        dk_df = st.session_state.get("debit_credit_data")
        if dk_df is not None and not getattr(dk_df, "empty", True):
            num_col = _tessa_find_column(
                dk_df,
                ["Номер договора", "НомерДоговора", "ContractNumber"],
            )
            if num_col and num_col in dk_df.columns:
                for x in dk_df[num_col].dropna().tolist():
                    _add(x)
    except Exception:
        pass
    return sorted(nums, key=lambda x: x.casefold())


def _inject_contract_no_datalist(
    options: list[str], *, list_id: str = "bi-pred-contract-ac"
) -> None:
    """Подсказки № договора: фильтрация по мере ввода (клиентский autocomplete)."""
    if not options:
        return
    opts_json = json.dumps(options, ensure_ascii=False)
    box_id = json.dumps(list_id + "-box")
    lid_json = json.dumps(list_id)
    label_json = json.dumps("№ договора (частичный поиск)")
    components.html(
        f"""
        <script>
        (function() {{
          const OPTIONS = {opts_json};
          const BOX_ID = {box_id};
          const LIST_ID = {lid_json};
          const LABEL_TEXT = {label_json};
          const HOMO = {{"\u0430":"a","\u0441":"c","\u0435":"e","\u043d":"h","\u043a":"k","\u043c":"m","\u043e":"o","\u0440":"p","\u0442":"t","\u0445":"x","\u0443":"y","\u0432":"v"}};
          const MAX = 25;
          function normKey(s) {{
            return String(s || "")
              .toLowerCase()
              .replace(/\\u00a0/g, " ")
              .split("")
              .map(function(ch) {{ return HOMO[ch] || ch; }})
              .join("");
          }}
          function resolveDoc() {{
            try {{
              if (window.parent && window.parent.document && window.parent.document.body)
                return window.parent.document;
            }} catch (e0) {{}}
            return document.body ? document : null;
          }}
          function setInputValue(input, val) {{
            try {{
              const desc = Object.getOwnPropertyDescriptor(
                window.HTMLInputElement.prototype, "value"
              );
              if (desc && desc.set) desc.set.call(input, val);
              else input.value = val;
            }} catch (e1) {{
              input.value = val;
            }}
            input.dispatchEvent(new Event("input", {{ bubbles: true }}));
            input.dispatchEvent(new Event("change", {{ bubbles: true }}));
          }}
          function ensureBox(doc, _anchor) {{
            let box = doc.getElementById(BOX_ID);
            if (box) return box;
            box = doc.createElement("div");
            box.id = BOX_ID;
            box.style.cssText =
              "display:none;position:fixed;z-index:100000;max-height:240px;overflow:auto;" +
              "background:#1e293b;border:1px solid #475569;border-radius:6px;" +
              "box-shadow:0 8px 24px rgba(0,0,0,.45);min-width:200px;";
            doc.body.appendChild(box);
            return box;
          }}
          function hideBox(doc) {{
            const box = doc.getElementById(BOX_ID);
            if (box) box.style.display = "none";
          }}
          function renderBox(doc, input, q) {{
            const nq = normKey(q);
            if (!nq) {{ hideBox(doc); return; }}
            const hits = [];
            for (let i = 0; i < OPTIONS.length; i++) {{
              const v = OPTIONS[i];
              if (normKey(v).indexOf(nq) >= 0) {{
                hits.push(v);
                if (hits.length >= MAX) break;
              }}
            }}
            if (!hits.length) {{ hideBox(doc); return; }}
            const box = ensureBox(doc, null);
            box.innerHTML = "";
            const rect = input.getBoundingClientRect();
            box.style.left = rect.left + "px";
            box.style.top = (rect.bottom + 2) + "px";
            box.style.width = Math.max(rect.width, 220) + "px";
            box.style.display = "block";
            hits.forEach(function(v) {{
              const row = doc.createElement("div");
              row.textContent = v;
              row.style.cssText =
                "padding:6px 10px;cursor:pointer;color:#e2e8f0;font-size:14px;line-height:1.3;";
              row.onmouseenter = function() {{ row.style.background = "#334155"; }};
              row.onmouseleave = function() {{ row.style.background = "transparent"; }};
              row.onmousedown = function(ev) {{
                ev.preventDefault();
                setInputValue(input, v);
                hideBox(doc);
              }};
              box.appendChild(row);
            }});
          }}
          function wireInput(doc, input) {{
            if (input.dataset.biContractAc === "1") return;
            input.dataset.biContractAc = "1";
            input.setAttribute("autocomplete", "off");
            input.removeAttribute("list");
            input.addEventListener("input", function() {{
              renderBox(doc, input, input.value || "");
            }});
            input.addEventListener("focus", function() {{
              if ((input.value || "").trim()) renderBox(doc, input, input.value || "");
            }});
            input.addEventListener("blur", function() {{
              setTimeout(function() {{ hideBox(doc); }}, 150);
            }});
          }}
          function findInput(doc) {{
            const inputs = doc.querySelectorAll('[data-testid="stTextInput"] input[type="text"]');
            for (let i = 0; i < inputs.length; i++) {{
              const aria = (inputs[i].getAttribute("aria-label") || "").toLowerCase();
              if (aria.indexOf("\u0434\u043e\u0433\u043e\u0432\u043e\u0440") >= 0) return inputs[i];
            }}
            for (let j = 0; j < inputs.length; j++) {{
              const inp = inputs[j];
              const block = inp.closest('[data-testid="stTextInput"]');
              if (!block) continue;
              const labelEl = block.querySelector("label");
              const labelTxt = labelEl ? (labelEl.textContent || "") : "";
              if (labelTxt.indexOf("\u0434\u043e\u0433\u043e\u0432\u043e\u0440") >= 0) return inp;
            }}
            return null;
          }}
          function attach() {{
            const doc = resolveDoc();
            if (!doc || !doc.body) return;
            const input = findInput(doc);
            if (input) wireInput(doc, input);
          }}
          attach();
          try {{
            const doc = resolveDoc();
            if (doc && doc.body) {{
              const obs = new MutationObserver(function() {{ attach(); }});
              obs.observe(doc.body, {{ childList: true, subtree: true }});
            }}
          }} catch (e2) {{}}
        }})();
        </script>
        """,
        height=0,
        width=0,
    )


def _pred_guess_contract_column(df, exclude=None):
    """Если явного столбца договора нет — ищем по подстроке в имени колонки."""
    if df is None or not hasattr(df, "columns"):
        return None
    ex = {str(c).strip().lower() for c in (exclude or []) if c is not None}
    for col in df.columns:
        k = str(col).strip().lower()
        if k in ex:
            continue
        if k in ("contr", "con"):
            continue
        if "подрядчик" in k and "договор" not in k:
            continue
        if "договор" in k or "contract" in k:
            return col
    return None


def _pred_guess_due_column(df, exclude=None):
    """Колонка срока устранения: по подстроке, без дат создания/загрузки; приоритет — «устран», DueDate, deadline."""
    if df is None or not hasattr(df, "columns"):
        return None
    ex = {str(c).strip().lower() for c in (exclude or []) if c is not None}
    scored = []
    for col in df.columns:
        k = str(col).strip().lower()
        if k in ex:
            continue
        if "создан" in k or "creation" in k or "загруз" in k:
            continue
        score = 0
        if "устран" in k:
            score += 6
        kn = k.replace(" ", "")
        if "duedate" in kn or "due_date" in k:
            score += 5
        if "deadline" in k:
            score += 4
        if "контрольный" in k and "срок" in k:
            score += 4
        if "planend" in kn or "plan_end" in k:
            score += 3
        if k == "срок" or (k.startswith("срок ") and "создан" not in k):
            score += 1
        if score > 0:
            scored.append((score, col))
    if not scored:
        return None
    scored.sort(key=lambda x: (-x[0], str(x[1]).lower()))
    return scored[0][1]


def _pred_build_seven_column_df(
    show: pd.DataFrame,
    contr_col,
    obj_col,
    contract_col,
    doc_num_col,
    due_col,
) -> pd.DataFrame:
    """Детальная таблица строго из 7 колонок (как макет), порядок фиксирован; пустые ячейки — «—» или пусто."""
    cols = list(_PRED_MOCK_TABLE_COLUMNS)
    if show is None or show.empty:
        return pd.DataFrame(columns=cols)
    rows = []
    for _, row in show.iterrows():
        def _cell(col):
            if not col or col not in show.columns:
                return None
            return row[col]

        sub = _clean_display_str(_cell(contr_col), empty="") if contr_col and contr_col in show.columns else ""
        pod = _clean_display_str(_cell(obj_col), empty="") if obj_col and obj_col in show.columns else ""
        contr_s = sub if sub else "—"
        proj_s = pod if pod else "—"
        dog = _pred_fmt_num(_cell(contract_col)) if contract_col and contract_col in show.columns else "—"
        num = _pred_fmt_doc_full(_cell(doc_num_col)) if doc_num_col and doc_num_col in show.columns else "—"
        due_s = _pred_fmt_due(_cell(due_col)) if due_col and due_col in show.columns else ""
        days = _pred_fmt_days_display(_cell("_overdue_days"))
        cv = _cell("_critical")
        crit = "Критическое" if cv is True else ("—" if cv is False else "")
        rows.append({
            "Подрядчик": contr_s,
            "Проект": proj_s,
            "№ договора": dog,
            "№ предписания": num,
            "Срок устранения предписания": due_s,
            "Дней просрочки": days,
            "Критические предписания": crit,
        })
    return pd.DataFrame(rows, columns=cols)



def _pred_projekts_1c_lookup() -> tuple[dict[str, str], frozenset[str], frozenset[str]]:
    """ID_Проекта → имя; множества id и имён (casefold) из web/1с_*_Projekts.json."""
    raw = _load_project_id_to_name_lookup() or {}
    ids = frozenset(str(k).strip().lower() for k in raw if str(k).strip())
    names = frozenset(str(v).strip().casefold() for v in raw.values() if str(v).strip())
    return raw, ids, names


def _pred_project_state_mask(df: pd.DataFrame) -> pd.Series:
    """KrStateID=0, KrState/Статус «Проект» (в т.ч. Draft в KrState при любом KrStateID)."""
    if df is None or getattr(df, "empty", True):
        return pd.Series(dtype=bool)
    mask = pd.Series(False, index=df.index)
    if "KrStateID" in df.columns:
        mask = mask | pd.to_numeric(df["KrStateID"], errors="coerce").eq(0)
    kr_col = _tessa_find_column(df, ["KrState", "krstate"])
    if kr_col and kr_col in df.columns:
        try:
            from tessa_status_utils import krstate_raw_to_label

            kr_lbl = df[kr_col].map(lambda x: krstate_raw_to_label(x))
        except Exception:
            kr_lbl = df[kr_col].astype(str).str.strip()
        mask = mask | kr_lbl.astype(str).str.strip().str.casefold().eq("проект")
    if "Статус" in df.columns:
        mask = mask | df["Статус"].astype(str).str.strip().str.casefold().eq("проект")
    return mask.fillna(False)


def _tessa_drop_project_state_rows(df: pd.DataFrame) -> pd.DataFrame:
    """Исключить документы TESSA в статусе «Проект» (KrStateID=0 / текст / Draft)."""
    if df is None or getattr(df, "empty", True):
        return df
    return df[~_pred_project_state_mask(df)].copy().reset_index(drop=True)


def _pred_filter_by_selected_projects(
    df: pd.DataFrame,
    selected: list[str],
    obj_col: str | None,
    proj_id_col: str | None,
    lookup: dict[str, str],
) -> pd.DataFrame:
    """Фильтр проектов: 1C_ID_OBJECT (если есть), иначе нормализованное имя объекта."""
    if not selected or df is None or getattr(df, "empty", True):
        return df
    pk_set = {
        _project_filter_norm_key(x)
        for x in selected
        if str(x).strip() and _project_filter_norm_key(x)
    }
    if not pk_set:
        return df.iloc[0:0].copy()

    by_id = pd.Series(False, index=df.index)
    if proj_id_col and proj_id_col in df.columns and lookup:
        selected_ids: set[str] = set()
        for proj_id, name in lookup.items():
            nk = _project_filter_norm_key(name)
            if nk in pk_set or _project_norm_key_matches_msp_keys(nk, pk_set):
                selected_ids.add(str(proj_id).strip().lower())
        if selected_ids:
            sid = df[proj_id_col].astype(str).str.strip().str.lower()
            sid = sid.replace({"": pd.NA, "nan": pd.NA, "none": pd.NA})
            by_id = sid.isin(selected_ids).fillna(False)

    by_name = pd.Series(False, index=df.index)
    if obj_col and obj_col in df.columns:
        by_name = (
            df[obj_col]
            .map(_project_filter_norm_key)
            .map(lambda rk: _project_norm_key_matches_msp_keys(rk, pk_set))
            .fillna(False)
        )

    mask = by_id | by_name
    if not mask.any():
        return df.iloc[0:0].copy()
    return df[mask].copy()


def _pred_filter_by_projekts_registry(df: pd.DataFrame, obj_col: str | None) -> pd.DataFrame:
    """Только проекты с ID в 1с_*_Projekts.json (остальные отбрасываем)."""
    if df is None or getattr(df, "empty", True):
        return df
    _raw, valid_ids, valid_names = _pred_projekts_1c_lookup()
    if not valid_ids:
        return df
    proj_id_col = _tessa_find_column(
        df,
        ["1C_ID_OBJECT", "1C_ID_PROJ", "ID_Проекта", "ProjectID", "1c_id_object"],
    )
    if proj_id_col and proj_id_col in df.columns:
        sid = df[proj_id_col].astype(str).str.strip().str.lower()
        sid = sid.replace({"": pd.NA, "nan": pd.NA, "none": pd.NA})
        mask = sid.isin(valid_ids)
        return df[mask.fillna(False)].copy()
    if obj_col and obj_col in df.columns:
        if _raw:
            resolved = _resolve_project_display_labels(df[obj_col], _raw)
            names = resolved.astype(str).str.strip().str.casefold()
        else:
            names = df[obj_col].astype(str).str.strip().str.casefold()
        return df[names.isin(valid_names)].copy()
    return df.iloc[0:0].copy()


def _pred_status_display_label(
    status: Any, *, resolved: bool = False, overdue_days: int | float | None = None
) -> str:
    """«На ознакомлении» → «Не устранено»; устранённые в срок → «Сдано в срок»."""
    try:
        od = int(round(float(overdue_days))) if overdue_days is not None and not pd.isna(overdue_days) else 0
    except (TypeError, ValueError):
        od = 0
    if resolved:
        return "Сдано в срок" if od <= 0 else "Устранено с просрочкой"
    s = _clean_display_str(status, empty="Неизвестно")
    if str(s).strip().casefold() == "на ознакомлении":
        return "Не устранено"
    return s


def _pred_status_pie_color(status_label: str) -> str:
    sl = str(status_label).strip().casefold()
    if "остановка" in sl:
        return _PRED_COLOR_STOP_WORK
    if sl == "критические" or sl.startswith("критич"):
        return _PRED_COLOR_CRITICAL
    if "не устранено" in sl:
        return _PRED_COLOR_UNRESOLVED
    if "сдано в срок" in sl or "снято" in sl:
        return _PRED_COLOR_ON_TIME
    if "устранено с просрочкой" in sl:
        return _PRED_COLOR_OVERDUE_RESOLVED
    if "просрочк" in sl:
        return _PRED_COLOR_OVERDUE_RESOLVED
    return "#94a3b8"


# Палитра сегментов графика «Предписания по объектам» — строго по макету
# KPI-кружков (см. `.pred-kpi-circle.*`): бордовый/красный/оранжевый/зелёный + янтарь.
_PRED_STATUS_CHART_COLOR = {
    "Остановка работ": "#922b3e",
    "Критические": "#e74c3c",
    "Не устранено": "#e67e22",
    "Сдано в срок": "#2ecc71",
    "Устранено с просрочкой": "#f1c40f",
}


def _pred_status_chart_color(status_label: str) -> str:
    return _PRED_STATUS_CHART_COLOR.get(str(status_label).strip(), _pred_status_pie_color(status_label))


def _pred_crit_overdue_unresolved_mask(df: pd.DataFrame) -> pd.Series:
    """Критические + просроченные + неустранённые (для сортировки таблицы и графика)."""
    if df is None or getattr(df, "empty", True):
        return pd.Series(dtype=bool)
    idx = df.index
    critical = (
        df["_critical"].astype(bool)
        if "_critical" in df.columns
        else pd.Series(False, index=idx)
    )
    if "_overdue_open" in df.columns:
        overdue_open = df["_overdue_open"].astype(bool)
    else:
        resolved = (
            df["_resolved"].astype(bool)
            if "_resolved" in df.columns
            else pd.Series(False, index=idx)
        )
        overdue_days = pd.to_numeric(
            df.get("_overdue_days", 0), errors="coerce"
        ).fillna(0)
        overdue_open = (~resolved) & (overdue_days > 0)
    return critical & overdue_open


def _pred_build_detail_table_df(
    show: pd.DataFrame,
    contr_col,
    obj_col,
    contract_col,
    doc_num_col,
    full_doc_col,
    issue_date_col,
    block_col,
    due_col,
    completion_col,
    name_col=None,
) -> pd.DataFrame:
    if show is None or show.empty:
        return pd.DataFrame(columns=_PRED_DETAIL_TABLE_COLUMNS)
    rows = []
    for _, row in show.iterrows():
        due_raw = row.get(due_col) if due_col and due_col in show.columns else None
        comp_raw = row.get(completion_col) if completion_col and completion_col in show.columns else None
        issue_raw = row.get(issue_date_col) if issue_date_col and issue_date_col in show.columns else None
        block_raw = row.get(block_col) if block_col and block_col in show.columns else None
        critical_raw = row.get("_critical")
        overdue_raw = row.get("_overdue_days")
        resolved_raw = bool(row.get("_resolved", False))
        if isinstance(critical_raw, (bool, np.bool_)):
            is_crit = bool(critical_raw)
        else:
            try:
                if critical_raw is None or pd.isna(critical_raw):
                    is_crit = False
                else:
                    is_crit = bool(critical_raw)
            except Exception:
                is_crit = False
        critical_text = "Да" if is_crit else "—"
        stop_raw = row.get("_stop_work")
        is_stop = bool(stop_raw) if isinstance(stop_raw, (bool, np.bool_)) else False
        stop_text = "Да" if is_stop else "—"
        try:
            overdue_num = int(round(float(overdue_raw)))
        except (TypeError, ValueError):
            overdue_num = 0
        crit_overdue_unresolved = is_crit and (not resolved_raw) and overdue_num > 0
        overdue_display = _pred_fmt_days_display(overdue_raw)
        name_raw = row.get(name_col) if name_col and name_col in show.columns else None
        name_s = _clean_display_str(name_raw, empty="—") if name_raw is not None else "—"
        if not name_s:
            name_s = "—"
        if full_doc_col and full_doc_col in show.columns:
            doc_full_s = _pred_fmt_doc_full(row.get(full_doc_col))
        else:
            doc_full_s = "—"
        pred_num_raw = row.get(doc_num_col) if doc_num_col and doc_num_col in show.columns else None
        rows.append(
            {
                "Статус предписания": _pred_status_display_label(
                    row.get("Статус"), resolved=resolved_raw, overdue_days=overdue_num
                ),
                "Подрядчик": _clean_display_str(row.get(contr_col), empty="—") if contr_col and contr_col in show.columns else "—",
                "Проект": _clean_display_str(row.get(obj_col), empty="—") if obj_col and obj_col in show.columns else "—",
                "№ договора": _pred_fmt_num(row.get(contract_col)) if contract_col and contract_col in show.columns else "Без номера",
                "№ документа": doc_full_s,
                "№ предписания": _pred_fmt_doc_full(pred_num_raw) if pred_num_raw is not None and not (isinstance(pred_num_raw, float) and pd.isna(pred_num_raw)) and str(pred_num_raw).strip() not in ("", "nan", "None") else "Без номера",
                "Наименование": name_s,
                "Дата выдачи предписания": _pred_fmt_due(issue_raw),
                "Блок выдачи предписания": _clean_display_str(block_raw, empty="—"),
                "Срок устранения": _pred_fmt_due(due_raw),
                "Фактическая дата устранения предписания": _pred_fmt_due(comp_raw),
                "Дней просрочки": overdue_display,
                "Критические предписания": critical_text,
                "Остановка работ": stop_text,
                "_crit_overdue_flag": 1 if crit_overdue_unresolved else 0,
                "_resolved_flag": "1" if resolved_raw else "",
                "_overdue_num": overdue_num,
            }
        )
    df_out = pd.DataFrame(rows)
    ordered = list(_PRED_DETAIL_TABLE_COLUMNS) + [
        "_crit_overdue_flag",
        "_resolved_flag",
        "_overdue_num",
    ]
    for c in ordered:
        if c not in df_out.columns:
            df_out[c] = ""
    return df_out[ordered]


def _pred_overdue_mock_table_html(rows: list, overdue_total: int) -> str:
    """Таблица просроченных как в макете: rowspan по подрядчику, бейджи «Критическое», дни со знаком −."""
    esc = html_module.escape
    head = (
        '<div class="pred-mock-head"><div>'
        f'<div class="pred-mock-title">{esc("Неустраненные предписания")}</div>'
        f'<div class="pred-mock-sort">{esc("Сортировка: по подрядчикам ↑, по просрочке ↓, критические вверху")}</div>'
        "</div>"
        f'<span class="pred-mock-badge">{esc(str(overdue_total))} просроченных</span></div>'
    )
    if not rows:
        return _pred_dash_mock_css_for_theme() + head + f'<p style="color:{_pred_muted_text_color()};padding:16px;">{esc("Нет просроченных предписаний")}</p>'

    thead = (
        "<thead><tr>"
        + "".join(f"<th>{esc(h)}</th>" for h in _PRED_MOCK_TABLE_COLUMNS)
        + "</tr></thead>"
    )
    parts = [_pred_dash_mock_css_for_theme(), head, '<div class="pred-mock-table-wrap"><table>', thead, "<tbody>"]
    for block in rows:
        contr = esc(str(block["contractor"]))
        rowspan = int(block["rowspan"])
        sub = esc(block["subline"])
        for i, r in enumerate(block["lines"]):
            cr = "pred-crit" if r.get("critical") else ""
            parts.append(f'<tr class="{cr}">')
            if i == 0:
                parts.append(
                    f'<td class="pred-td-contr" rowspan="{rowspan}">{contr}'
                    f'<div class="pred-td-sub">{sub}</div></td>'
                )
            parts.append(f'<td><span class="pred-tag">{esc(r["project"])}</span></td>')
            parts.append(f'<td><span class="pred-tag">{esc(r["contract"])}</span></td>')
            parts.append(f"<td>{esc(r['number'])}</td>")
            parts.append(f"<td>{esc(r['due'])}</td>")
            days = int(r["days"]) if pd.notna(r.get("days")) else 0
            parts.append(f'<td><span class="pred-days-neg">-{esc(str(days))}</span></td>')
            if r.get("critical"):
                parts.append(f'<td><span class="pred-crit-yes">{esc("Критическое")}</span></td>')
            else:
                parts.append('<td><span class="pred-crit-dash">—</span></td>')
            parts.append("</tr>")
    parts.append("</tbody></table></div>")
    return "".join(parts)


